(window.GIM_TP=window.GIM_TP||{})["Nedarim.0"]={"from":0,"a":[[["מתני׳ \u0001כל\u0002 כינויי נדרים כנדרים","וחרמים כחרמים ושבועות כשבועות ונזירות כנזירות","האומר לחברו מודרני ממך מופרשני ממך מרוחקני ממך שאני אוכל לך שאני טועם לך אסור","מנודה אני לך ר''ע היה חוכך בזה להחמיר"],[[0,"מתני' כל כנויי נדרים כנדרים","דעיקר נדר דכתיב בתורה (במדבר ל׳:ג׳) איש כי ידור נדר דאמר קרבן שאני אוכל לך או קרבן שאני נהנה לך ואם אמר בלשון אחר בכינוי נדר כדקתני לקמן קונם שאני נהנה לך או קונם שאיני נהנה לך דאם כינה לקרבן בהני לשונות נמי מיתסר בהו בנדרים כמו שאסור גבי קרבן וכן כנויי חרמים כחרמים וכן כנויי שבועות כו' מפרש לקמן:"],[2,"מודר אני ממך","כלומר הרי עלי כנדר מה שאני נהנה ממך או א\"ל מופרשני ממך בהאי לשון או אמר מרוחק אני ממך דמשמע דמיתסר נפשיה ולא מיתהני מיניה וכל הני כיון דלא מפרש ממש לנדר דלא מידכר ביה שום לשון קרבן הויין ידות:"],[3,"מנודה אני לך","כמו שאם היה בנידוי דאסור ליה לישא וליתן בהדיה כך אסר נפשיה עליה:"],[3,"ר\"ע היה חוכך בזה להחמיר","הוה מחכך להחמיר דאסור נמי דענין נדר הוא ולא בריר ליה:"]],[[0,"מתני' כל כנויי נדרים כנדרים וחרמים כחרמים","כינוי זהו שם שפל (נ\"א טפל) כדאמרי' המכנה שם לחברו ה\"נ כנויי נדרים דעיקר הנדר הוא כשמתפיס החפץ בדבר הנדור כמו דאמר הרי עלי ככר זה כהקדש ועל ככר אחר אומר יהא כזה זהו נדר כדאמר פרק ג' דשבועות (ד' כ) עד שידור בדבר הנדור והני לישני כעין נדר הן ולקמן בשילהי פירקין קאמר ר\"ל לשון שבדו חכמי' ולהכי תקינו כנויי דלא לימא קרבן לה' דזימנין דאמר לה' ולא אמר לקרבן ומפיק שם שמים לבטלה ור' יוחנן אמר לשון נכרים דבלשונם כשנודרין נדר אומרים הכי וקשה למ\"ד לשון נכרים אמאי נקט הני לישני לימא בכל הלשונות שהם נודרים בלשונם יהא נדר ואומר ר\"י ודאי אם יהא כלשונם יהא נדר אחרי שהם מבינים והני דמתני' אפי' לא יבינו האי לשון הרי הוא נדר ולמ\"ד לשון שבדו חכמים קשה דה\"נ כנויי דנזיר בדו חכמים והיכי יביא קרבן על לשון חכמים ובנדרים לא קשה אי עבר בבל תאחר על לשון חכמים וי\"ל דהא דאמר ל' בדו לא קאמר אלא גבי נדרים אבל לא גבי נזיר וכן מוכח בגמרא דפריך הניחא למ\"ד לשון נכרים אלא למ\"ד לשון שבדו חכמים מאי איכא למימר ובמס' נזיר דקאמר כל כנויי נזירות כנזירות לא פריך כה\"ג בגמ' ואור\"י דאין זו ראיה דרגילות הוא להאריך במקום אחד ולקצר במקום אחר ועל לשון שבדו חכמים נמי הוי נזיר דכיון דתקינו חכמים שנודרין בהני לישני הוי כעיקר נזירות ויש - כח בידיהם לעשות תקנתן כעיקר נזירות ועוד י\"ל כיון שתיקנו חכמים הני לישני כוונת הנודר לנדר גמור וגמר בלבו לעשותו כעיקר הלשון:"],[0,"כל כנויי נדרים כנדרים וחרמים כחרמים","כינוי זהו שם שפל (נ\"א טפל) כדאמרי' המכנה שם לחברו ה\"נ כנויי נדרים דעיקר הנדר הוא כשמתפיס החפץ בדבר הנדור כמו דאמר הרי עלי ככר זה כהקדש ועל ככר אחר אומר יהא כזה זהו נדר כדאמר פרק ג' דשבועות (ד' כ) עד שידור בדבר הנדור והני לישני כעין נדר הן ולקמן בשילהי פירקין קאמר ר\"ל לשון שבדו חכמי' ולהכי תקינו כנויי דלא לימא קרבן לה' דזימנין דאמר לה' ולא אמר לקרבן ומפיק שם שמים לבטלה ור' יוחנן אמר לשון נכרים דבלשונם כשנודרין נדר אומרים הכי וקשה למ\"ד לשון נכרים אמאי נקט הני לישני לימא בכל הלשונות שהם נודרים בלשונם יהא נדר ואומר ר\"י ודאי אם יהא כלשונם יהא נדר אחרי שהם מבינים והני דמתני' אפי' לא יבינו האי לשון הרי הוא נדר ולמ\"ד לשון שבדו חכמים קשה דה\"נ כנויי דנזיר בדו חכמים והיכי יביא קרבן על לשון חכמים ובנדרים לא קשה אי עבר בבל תאחר על לשון חכמים וי\"ל דהא דאמר ל' בדו לא קאמר אלא גבי נדרים אבל לא גבי נזיר וכן מוכח בגמרא דפריך הניחא למ\"ד לשון נכרים אלא למ\"ד לשון שבדו חכמים מאי איכא למימר ובמס' נזיר דקאמר כל כנויי נזירות כנזירות לא פריך כה\"ג בגמ' ואור\"י דאין זו ראיה דרגילות הוא להאריך במקום אחד ולקצר במקום אחר ועל לשון שבדו חכמים נמי הוי נזיר דכיון דתקינו חכמים שנודרין בהני לישני הוי כעיקר נזירות ויש כח בידיהם לעשות תקנתן כעיקר נזירות ועוד י\"ל כיון שתיקנו חכמים הני לישני כוונת הנודר לנדר גמור וגמר בלבו לעשותו כעיקר הלשון:"],[1,"וחרמים כחרמים","תימה למ\"ד סתם חרמים לכהנים אם ירצה להחרים לבדק הבית יצטרך לומר חרם לה' וא\"כ מה הועילו חכמים בתקנתם והא כל הכנויים אינם אלא משום שלא יזכיר שם שמים לבטלה שאחרי הכנויים אלו אינו רהוט לומר לה' כמו אם יאמר קרבן דאז הוא רהוט לומר לה' וי\"ל שאם ירצה להחרים לבדק הבית יאמר חרם לבדק הבית:"],[1,"ושבועות כשבועות","שבותה שבוקה מפרש לקמן וקשה דשילהי פ' שבועת העדות (שבועות דף לה) קאמר יתן ה' אותך לאלה ולשבועה נאמר כאן אלה ונאמר להלן אלה מה להלן בשם אף כאן בשם וכן ריש פ' שבועת הדיינין (שבועות דף לח) קאמר כמאן כר' חנינא דאמר בעינן שם אפי' תימא רבנן דאמרי בכינויין אבל (לא) בלא כינוי דשם לא מחייב וכן קשה התם דאמרי' במס' שבועות (דף יט) שבועה שלא אוכל שבועה שאוכל לך אסור ואור״ת הא דבעינן שם או כינוי במושבע מפי אחרים אבל מושבע מפי עצמו מצי אסר נפשיה בלא שום כינוי:"],[1,"ונזירות כנזירות","תימה אמאי לא תנא איסורי כאיסורי והקדשות כהקדשות וכו' וי\"ל דלמ\"ד לשון נכרים לא נמצא להם לשון נכרים אלא בהני דתנא ולמ\"ד לשון שבדו חכמים צ\"ל דלהכי לא תנא דלא כתב ערך לה' איסור לה' הקדש לה' כמו דכתיב חרם לה' וקרבן לה':"],[2,"האומר לחבירו מודר אני ממך","הני ידות מיקרו שאינו גומר דבריו אלא מתחיל והוי ידות כמו יד לכלי ומפרש בגמ' אמאי שבק בכינויין דמיירי בהון ומפרש ידות דלא איירי בהון:"],[2,"שאני אוכל לך","יש דגורסין ביו\"ד שאיני אוכל לך וקשה דהא אין נדרים חלין אלא על דבר שיש בו ממש ושמא מיירי דמסרבין בו לאכול ואומר שאיני והוי כמו קונם שאני אין אור\"י דבגמ' משמע דבמידי דמאכל אף שאיני ביו\"ד לא קרי בזה דבר שאין בו ממש ולא דמי לשאיני ישן דאמר לקמן (נדרים דף יד) [דהוי] דבר שאין בו ממש דהתם אין בו ממש לא בדבור ולא בשינה אבל הכא מ\"מ במאכל שהוא מזכיר יש בו ממש והוא קונם המאכל עצמו ענין זה שאני אוכל וא\"ת מהו עיקר הנדר בשלמא חרמים הוא עיקר מן החרם ושבועות מן השבועה וי\"ל שנדר עצמו הוא עיקר דאמר ככר זה עלי נדר וכן משמע מתני' כינוי נדרים כנדרים וקרא נמי מוכח כי ידור נדר ולא נראה דא\"כ מאי קאמר התם מודר אני ממך אדרבה הוא עיקר הנדר ועוד קשה דקאמר קונם קונח קונס הרי זה כינוי לקרבן הוה ליה למימר לנדרים לכך נראה לפרש דעיקר הנדר כשהוא אומר ככר זה עלי קרבן וכי ידור נדר אתי למימר דבעינן שידור בדבר הנדור:"]]],[["\u0001גמ׳\u0002 כל כינויי נדרים כנדרים מאי שנא גבי נזיר דלא קתני להו לכולהו ומאי שנא גבי נדרים דקתני לכולהו","משום דנדר ושבועה כתיבי גבי הדדי תני תרתין וכיון דתני תרתין תני לכולהו","וליתני כינוי שבועות בתר נדרים איידי דתנא נדרים דמיתסר חפצא עליה תנא נמי חרמים דמיתסר חפצא עליה לאפוקי שבועה דקאסר נפשיה מן חפצא","פתח בכינויין כל כנויי נדרים ומפרש ידות האומר לחבירו מודר אני ממך ותו ידות אינשי","איירי בהון וחסורי מיחסרא והכי קתני כל כינויי נדרים כנדרים וידות נדרים כנדרים","וליפרוש כינויין ברישא","ההוא דסליק מיניה ההוא מפרש ברישא כדתנן במה מדליקין ובמה אין מדליקין אין מדליקין כו'","במה טומנין ובמה אין טומנין אין טומנין כו' במה אשה יוצאה ובמה אינה יוצאה לא תצא אשה","וכל היכא דפתח לא מפרש ברישא והתנן יש נוחלין ומנחילין נוחלין ולא מנחילין ואלו נוחלין ומנחילין","יש מותרות לבעליהן ואסורות ליבמיהן מותרות ליבמיהן ואסורות לבעליהן ואלו מותרות לבעליהן ואסורות ליבמיהן","יש טעונות שמן ולבונה שמן ולא לבונה ואלו טעונות שמן ולבונה יש טעונות הגשה ואין טעונות תנופה תנופה ולא הגשה ואלו טעונות הגשה","יש בכור לנחלה ואין בכור לכהן בכור לכהן ואין בכור לנחלה ואיזהו בכור לנחלה ואין בכור לכהן","הלין משום דאוושו ליה מפרש ההוא דפתח ברישא","והא במה בהמה יוצאה ובמה אינה יוצאה דלא אוושא וקתני יוצא גמל"],[[0,"גמ' מ\"ש גבי גזיר דלא קתני לכולהו","דהתם קתני כל כינויי נזירות ותו לא מידי ולא קתני לכל הני דנדרים ושבועות:"],[1,"כתיבין בהדי הדדי","כל נדר ובל שבועת איסר וכיון דאגב דקתני שבועות קתני לכולהו:"],[2,"וליתני שבועות בתר נדרים","כדכתיבי והדר ליתני לכולהו:"],[2,"דמיתסר חפצא","דכי אמר דבר זה עלי בקרבן או בחרם אסר ליה לחפץ עליו ומשום הכי תני להו בהדי הדדי אבל כי אמר שבועה שלא אוכל דבר זה או שאיני נהנה מדבר זה איהו לא אסר לחפצא עליה אלא נפשיה אסר מההוא חפצא:"],[3,"פתח בכינוי ומפרש ידות","לאלתר מודר אני ממך וכו' דהיינו ידות ולכתחילה ה\"ל למתני' לפרש כינויין כגון קונם והדר ליתני ידות:"],[3,"ותו","אכתי איכא למיפרך ידות אינשי היכי שכחם התנא דלא קתני וידות נדרים כנדרים:"],[4,"איירי בהו","דודאי לא שכח להו לידות וחסורי מיחסרא וכו':"],[5,"וליפרוש","אכתי אי בכינויים איירי ברישא ליפרוש נמי ברישא קודם דפריש ידות:"],[6,"ההוא דסליק מיניה","כגון ידות דסליק מינייהו ומפרש להו לאלתר ברישא כדתנן במה מדליקין ונקיט במה אין מדליקין דסליק מיניה וכן כל הני:"],[8,"","וכל היכא דפתח ביה לא מפרש ברישא והתנן יש נוחלין כו' ומפרש ברישא אלו נוחלין ומנחילין:"],[12,"הלין","פתח ברישא משום דאוושו ליה קתני דיש נוחלין ומנחילין נפישין מהני דלא מנחילין וכן כל הני משום הכי מפרש להו לאלתר אע\"ג דפתח בהו ברישא אבל הכא גבי נדרים וכן במה מדליקין דלא נפישי ההוא דסליק מיניה פתח ברישא ל\"א אוושו דקתני ארבעה דברי' כגון יש נוחלין ומנחילין נוחלין ולא מנחילין מנחילין ולא נוחלין לא נוחלין ולא מנחילין וכן בכולהו יש מותרות לבעליהן ואסורות ליבמיהן כו' הואיל ותני כל הני מתחיל בההוא דפתח ברישא ומפרש יתיה דאם היה מפרש בההוא דסליק מיניה ברישא שמא ישכח את הראשונות אלא פתח בראשון ומפרש להו כסדרן אבל היכא דלא אוושו כגון הני במה מדליקין וכו' ליכא למיחש להו ובמתניתין נמי ליכא למיחש דלא מפרש אלא כינויי וידות והני חרמים ושבועות ונזיר בהני ליכא למימר דאוושן דהא לא צריך להו למיתני אלא אגב גררא נסיב להו ומשום הכי לא שכח לקמייתא דלא צריך הכא כל כך דלא הויא עיקר אלא כינוי וידות בלבד וכמאן דלא תני להו לאחריני דמי:"]],[[0,"ומ\"ש גבי נזיר דלא תני כולהו","פי' חרמים ושבועות ונדרים ומשני משום דנדר ושבועות גבי הדדי כתיבי דכתי' איש כי ידור נדר או השבע שבועה אע\"ג דגבי נזיר כתיב כי יפליא לנדור נדר נזיר להזיר מ\"מ עיקר פרשת נדרים לאו התם כתיב אבל עיקר פ' שבועות ונדר כתיבן גבי הדדי תימה גבי שבועות ליפרוך כי האי ולימא כינוי שבועות כשבועות כי האי דגבי נזיר דמהדר ונקט כל כינוי נזירות כנזירות וי\"ל דכיון דלית ביה ידות לא חשו להזכירם:"],[2,"נדרים דמתסר חפצא עילויה","דאמר ככר זה קונם עלי שעושה הככר עליו הקדש גבי חרמים נמי אסר חפצא על נפשיה דגלי קרא אשר יחרים [איש לה'] מכל אשר לו (ויקרא כז) משמע דהחפץ יהיה חרם גבי נדרי' אע\"ג דכתיב כי ידור דמשמע לה דר\"ל אגברא מ\"מ כתיב כי ידור נדר דר\"ל דמתפי' בנדור וזהו החפץ ואע\"ג דגבי שבועה כתיב או השבע שבועה מ\"מ גלי קרא לא תשבעו דמזהר אגברא וא\"ת ומנ\"מ אי אסר חפצא עילויה או איהו אחפצא י\"ל דלענין זה שאם היה אומר קונם שלא אוכל ככר זה לא אמר כלום וכן אמר גבי שבועה להפך:"],[3,"ותו ידות אנשי","פי' ברישא ליתני ידות נדרים כנדרים ומשני לא אנשי איירי בהון וחסורי מחסרא:"],[5,"וליפרוש כינויין ברישא","דהא קאמרת דתני ידות בתר כינויין ולא משמע ליה להגיה המשנה ולומר תני רישא ידות קודם כינויין דלא רצה לשבש המסכתא:"],[6,"ההוא דסליק מיניה פתח ברישא","ואם תאמר תקשי ליה מתניתין גופיה דקתני (דף י) כנוי נדרים קודם הוי ליה למתני כנוי [נזירות] קודם דסליק מיניה וי\"ל דסליק מקרבן דקתני נדר בנזיר וכו':"],[9,"יש מותרות לבעליהן","הך בבא ביבמות מפרש לה ומשני הני משום דאוושן מפרש ההוא דכתיב ברישא ודאג פן יטעה בהן לכך מפרש ההוא דכתיב ברישא ובנזיר נמי איכא כי האי סוגיא ומשני בבמה בהמה באידך ענין בהמה באיסורא איירי מפרש היתר ברישא:"]]],[["אלא לאו דווקא זימנין מפרש ההוא דפתח ברישא זימנין ההוא דסליק מפרש ברישא ואיבעית אימא ידות איידי דאתיין מדרשא מפרש להון ברישא","וליפתח הדין ברישא מיפתח פתח בכינויין דאורייתא ברישא והדר מפרש ידות דאתיין ליה מדרשא","הניחא למאן דאמר כינויין לשון נכרים הן אלא למ''ד לשון שבדו להן חכמים להיות נודר בו מאי איכא למימר","מי קתני ידות ולאו חסורי קא מחסרת לה אקדים נמי ותני ידות כל ידות נדרים כנדרים וכל כינויי נדרים כנדרים ואלו הן ידות האומר לחבירו ואלו הן כינויין קונם קונח קונס","וידות היכא כתיב (במדבר ו ב) איש כי יפליא לנדור נדר נזיר להזיר לה' ותניא נזיר להזיר לעשות כינויי נזירות כנזירות וידות נזירות כנזירות","אין לי אלא בנזירות בנדרים מנין ת''ל איש כי יפליא לנדור נדר נזיר להזיר לה' מקיש נזירות לנדרים ונדרים לנזירות מה נזירות עשה בו ידות נזירות כנזירות אף נדרים עשה בהם ידות נדרים כנדרים","ומה נדרים עובר בבל יחל ובבל תאחר אף נזירות עובר בבל יחל ובבל תאחר ומה נדרים האב מיפר נדרי בתו ובעל מיפר נדרי אשתו אף נזירות האב מיפר נזירות בתו ובעל מיפר נזירות אשתו","מ''ש גבי נזירות דכתיב נזיר להזיר נדרים נמי הא כתיב לנדור נדר והיקישא למה לי","אי כתב נדר לנדור כדכתב נזיר להזיר כדקאמרת לא צריך היקישא השתא דכתיב לנדור נדר דברה תורה כלשון בני אדם","הניחא למאן דאית ליה דברה תורה כלשון בני אדם אלא למאן דלית ליה דברה תורה כלשון בני אדם האי לנדור נדר מאי עביד ליה דריש ליה לעשות ידות נדרים כנדרים ומקיש נזירות לנדרים נזיר להזיר דריש ליה מלמד"],[[0,"אלא לאו דוקא","הא דאמרת דתנא לא דייק להי מפרש ברישא דזימנין מפרש וכו':"],[1,"וליפתח","בגווייהו וליתני ברישא כל ידות נדרים הואיל דחביבי ליה:"],[2,"כינויין לשון נכרים","דבהני לשונות נדרי נכרים כקונם קונח קונס שיש לשון שקורין לקרבן קונם ויש לשון שקורין לקרבן קונח וכן השאר [ומש\"ה] קא חשיב להו וה\"ה לכל לשון הנודר אדם מיחייב והא דקא מנו חכמים הני לשונות משום דבהני לשונות בקיאין וכיון דאיכא נכרים דנדרי התורה אסרה בכל לשון דקאמר דהא הוי נדר:"],[2,"אלא לריש לקיש דקאמר לשון שבדו להם חכמים","דחכמים תקינו הני לשונות להיות נודר בו:"],[2,"מאי איכא למימר","היכי מצי אמרת ידות איידי דאתיין מדרשא הא תרוייהו בין ידות בין כינויין מדרשא אתיין דמדרבנן נינהו:"],[3,"מי קתני ידות","הא לא קתני במתני' וידות נדרים כנדרים אלא חסורי מיחסרת לה דאמרת לעיל חסורי מיחסרא וכו' וכיון דאמרת הכי תני נמי ברישא כל ידות נדרים כנדרים וכיון דפתח להו ברישא להכי מפרש נמי להו ברישא:"],[4,"וידות היכן כתיבן","היכא כתב להו קרא דדריש להו מיניה דאמר (רישא) מדרשא אתיא ולא כתיבי ממש דא\"כ הוו להו מדאוריי':"],[4,"נזיר להזיר","דמצי למיכתב כי יפליא לנדור נדר נזיר אלא מלהזיר דרשינן לעשות כל כינויי נזירות [כנזירות] דבכל כינויי לשון דמזיר הוי נזיר. והתם במסכת נזיר מפרש ידות נזירות וכינויי נזירות:"],[6,"מה נדרים עובר בבל יחל","דכתיב לא יחל דברו (במדבר ל׳:ג׳):"],[6,"ובבל תאחר","דכתיב כי תדור נדר לה' אלהיך לא תאחר (דברים כ״ג:כ״ב):"],[7,"הא כתיב לנדור נדר","ונידרוש נמי מלנדור לעשות כינויי נדרים כנדרים:"],[7,"והיקישא למה לי","דאמרת מקיש נדרים לנזירות הא מצינן למידרש מקרא גופיה:"],[8,"לנדור נדר","הכי משתעו בני אדם ודברה תורה כלשון בני אדם וליכא למידרש מינה כלום:"],[9,"לא דברה תורה כלשון בני אדם","דכל היכא דכתב ייתור לשון כהאי גוונא לדרשא קא אתי ולא משום דמשתעי בלשון בני אדם:"]],[[2,"אלא למאן דאמר לשון שבדו חכמים","למא' דפרשינן במתני' דתקינו חכמים שהלשון יהיה מועיל וחל עליה מן התורה י\"ל מ\"מ אין דינם פשוט יותר מידות ובדין היה להקדימן אמאי לא אקדמינהו: \u0003עוד\u0004 אומר ר\"י בשם רבי יחיאל דבירושלמי איתא בהדיא למאן דאמר לשון שבדו חכמים דאינו מביא קרבן על כינוי נזירות וכינוי נזירות אינו כנזיר אלא לענין מלקות: הכי נמי אקדים ותני ידות ברישא. וצ\"ע כי מתחילה היה קשה להגיה ברישא ועתה מגיה:"],[3,"הכי נמי אקדים ותני ידות ברישא","וצ\"ע כי מתחילה היה קשה להגיה ברישא ועתה מגיה: (לעיל):"],[4,"וידות","דאמר לעיל דאתיא מדרשא מהיכא נפקא:"],[4,"לעשות כינוי נזירות כנזירות","לא מיבעיא קרא יתירא דודאי הם מן התורה ולא איצטריך היתר רק לידות (ולא) [דהא] מגופיה דקרא שמעינן הכינויים וכבר הזכירה דבהיקש דסיפא לא מזכיר כינויין כן פירש ה\"ר אליעזר דיתור דאיצטריך למדרש ידות נזירות כנזירות:"],[6,"אף נזירות עובר בבל תאחר","ולקמן קאמר בל תאחר דנזירות היכי משכחת לה:"],[8,"אי כתב נדר לנדור כדכתב נזיר להזיר כדקאמרת","שכך דרך המקראות לכתוב שם דבר כמו עשה יעשה אמר אמרתי ומדשני דכתב נזיר להזיר לדרוש השתא דכתיב לנדור נדר אורחיה דקרא הוא וליכא יתורא ודברה תורה כלשון בני אדם:"],[9,"הניחא למאן דאמר נזירות חל על נזירות","פלוגתא היא בפרק שני דמכילתין (דף יז) ואומר ר\"י דלקמן מוכח דהיכא דאמר הריני נזיר היום הריני נזיר למחר דכולי עלמא לא פליגי דחייב שתי נזירות מיגו דחיילא על יום אחד חיילא על כולו וכי פליגי באומר הריני נזיר היום הריני נזיר היום ובזה יש לפרש האי פלוגתא:"]]],[["שהנזירות חל על הנזירות","ולמ''ד דברה תורה כלשון בני אדם ונזיר להזיר דריש לעשות ידות נזירות כנזירות שהנזירות חל על הנזירות מנא ליה הניחא אי ס''ל כמ''ד אין נזירות חל על נזירות אלא אי ס''ל כמ''ד נזירות חל על נזירות מנא ליה","נימא קרא ליזור מאי להזיר שמעת מינה תרתי","במערבא אמרי אית תנא דמפיק ליה לידות מן לנדור נדר ואית תנא דמפיק ליה מן (במדבר ל ג) כל היוצא מפיו יעשה","אמר מר ומה נדרים עובר (במדבר ל ג) בבל יחל ובל תאחר בשלמא בל יחל דנדרים משכחת לה כגון דאמר ככר זו אוכל ולא אכלה עובר משום בל יחל דברו","אלא בל יחל דנזירות היכי משכחת לה כיון דאמר הריני נזיר הוה ליה נזיר אכל קם ליה בבל יאכל שתה קם ליה בבל ישתה אמר רבא לעבור עליו בשנים","בל תאחר דנזירות היכי משכחת לה כיון דאמר הריני נזיר הוה ליה נזיר אכל קם ליה בבל יאכל באומר לכשארצה אהא נזיר ואי אמר כשארצה ליכא בל תאחר","אמר רבא כגון דאמר לא איפטר מן העולם עד שאהא נזיר דמן ההיא שעתא הוה ליה נזיר מידי דהוה האומר לאשתו הרי זו גיטיך שעה אחת קודם מיתתי אסורה לאכול בתרומה מיד אלמא אמרינן כל שעתא ושעתא דילמא מיית הכא נמי לאלתר הוי נזיר דאמרינן דילמא השתא מיית"],[[0,"שהנזירות חל על הנזירות","שאם היה נזיר ואמר הריני נזיר חל עליה נזירות (במס' נזיר בפ' מי שאמר הריני נזיר (דף טז:) מחלוקת ר' יוחנן וריש לקיש) וכשישלמו אותן ימי נזירות צריך להיות נזיר עוד פעם אחרת:"],[2,"שמעת מינה תרתי","לעשות ידות נזירות כנזירות ונזירות חל על הנזירות:"],[3,"אית תנא דמפיק לידות מלנדור נדר","דלא ס\"ל דברה תורה כלשון בני אדם:"],[3,"מן ככל היוצא מפיו יעשה","דמשמע בכל ענין דנדר:"],[5,"קם ליה בבל יאכל","כדכתיב מחרצנים ועד זג לא יאכל (במדבר ו׳:ד׳):"],[5,"קם ליה בבל ישתה","כל משרת ענבים לא ישתה וליכא לא יחל דברו:"],[5,"אמר רבא","לעולם אית ביה כמי לא יחל לעבור עליו בשני לאוין לא יאכל ולא יחל:"],[6,"קם ליה בלא יאכל","לא מאחר לנזריה בכך דאיהו הוי נזיר אלא דקם ליה בלא יאכל:"],[6,"באומר לכשארצה אהא נזיר","דאי משהי ליה קם ליה בבל תאחר:"],[6,"אכתי מאי בל תאחר איכא","כל אימת דבעי למיהוי מצי למיהוי ולית ביה משום בל תאחר:"],[7,"הכא נמי לאלתר הוי נזיר","דאי משהי ליה קים ליה בבל תאחר דאמרינן דילמא השתא מאית דאיהו אמר דלא ליפטר מן העולם עד דהוי נזיר מן אלתר באותה שעה כל אלתר דגרסינן היינו על אתר באותו מקום וכן מפרש בידות:"]],[[5,"אלא בל יחל דנזיר היכי משכחת לה","דעובר בבל יחל גרידא ומשני לעבור עליו בשתים:"],[6,"בל תאחר בנזירו' היכי משכחת לה","בשלמא גבי נדרים משכחת לה אי אמר הרי עלי עולה ושהה ולא הקריבה עד אחר שלש רגלים אלא בנזירות היכי משכחת לה דאי אמר הריני נזיר מהשתא חל עליה נזירות ומשני - כגון דאמר לא אפטר מן העולם עד שאהיה נזיר דמההיא שעתא הוי נזיר כלומר דמיד יש לו להתחיל נזירותו ואם לא התחיל עובר בבל תאחר מידי דהוה לאומר לאשתו הרי זה גיטך וכל זה מן התירוץ ור\"ת מפרש לה בתמיה מהאי שעתא הוה ליה נזיר ומאי בל תאחר איכא מידי דהוה לאומר לאשתו הרי זה גיטך דהוה גט מיד ה\"נ הוה חל עליו הנזירות מיד וכל זה מן הקושיא ולפירוש זה צריך לגרוס אמר רב אחא בר יעקב דשינויא היא דשני ליה ולפירוש אחר רב אחא בר יעקב אמר:"],[7,"מידי דהוה לאומר לאשתו","נהי דלא דמי דהתם אסורה לאכול בתרומה מיד והכא לא חל נזירות מיד לדוגמא בעלמא מדמינן דחיישינן שמא ימות מיד ה\"נ ליחוש שמא ימות מיד וקא עבר אם לא יתחיל מיד הקשה הר\"ר יוסף שהלך בארץ הצבי אמאי לא משכחת בל תאחר בנזירות דאמר הרי עלי לקבל נזירות אחר שלשים יום ואי מאחר עובר בבל תאחר ושמא היינו כשינויא דשנינן לא אפטר מן העולם עד שאהיה נזיר כלומר עד שאקבל נזירות עוי\"ל דאי מאחר לשלם נדרו א\"כ לאו היינו בל תאחר דנזיר כ\"א בל תאחר דנדר שמאחר לנדור נדרו:"]]],[["רב אחא בר יעקב אמר כגון דנדר והוא בבית הקברות","הניחא למ''ד לא חיילא עליה נזירות מאלתר אלא למ''ד מאלתר חיילא עליה מי איכא בל תאחר ועוד האמר מר בר רב אשי חיילא נזירות עליה מאלתר וכי פליגי לענין מלקות פליגי","אפ''ה קם ליה בבל תאחר משום דקא מאחר נזירות דטהרה א''ר אשי הואיל וכן נזיר שטימא עצמו במזיד עובר משום בל תאחר דנזירות טהרה","רב אחא בריה דרב איקא אמר עובר בבל תאחר תגלחתו","ולא מיבעיא למ''ד תגלחת מעכבת אלא אפי' למ''ד תגלחת אינה מעכבת מצות גילוח מיהא לא מיקיים","מר זוטרא בריה דרב מרי אמר עובר בבל תאחר קרבנותיו","ומן הכא נפקא ליה מהתם נפקא ליה (דברים כג:כב) כי דרוש ידרשנו אלו חטאות ואשמות","מהו דתימא חידוש הוא שחידשה תורה בנזיר","מאי חידוש אילימא דלא מתפיס ליה לחטאת נזיר בנדר הרי חטאת חלב שאין מתפיסה בנדר ועובר בבל תאחר","אלא מאי חידושיה סד''א הואיל ואם אמר הריני נזיר אפילו מן חרצן הוי נזיר לכל אימא לא ליעבור עליה משום בל תאחר קמ''ל","הניחא למ''ד כי נזיר מן חרצן הוי נזיר לכל אלא לר''ש דאמר אין נזיר עד שיזיר מכולן מאי איכא למימר ועוד האי חידוש לחומרא הוא","אלא מאי חידושיה דסד''א הואיל"],[[1,"לענין מלקות פליגי","למאן דאמר חיילא עליה נזירות מלקינן ליה דמטמא עצמו בבית הקברות ולמ\"ד לא חיילא עליה נזירות דלא מלקינן ליה הואיל ובבית הקברות נדר אבל לכולי עלמא לאלתר הוי נזיר וליכא בל תאחר דאמרינן נמי אי אכל קם ליה בבל תאכל:"],[2,"דקא מאחר לנזירות דטהרה","דלאלתר מבעי ליה למיפק חוץ מבית הקברות ולמינזר נזירותיה בטהרה:"],[2,"וכן נזיר","בעלמא שטימא עצמו במזיד אע\"ג דמחלל לנזירות קם ליה בבל תאחר דנזירות דטהרה:"],[3,"רב אחא אמר","מאי בל תאחר איכא בנזיר איכא בל תאחר דתגלחת דכי נפקי ימי נזירותיה בעי לגלח עצמו ולאיתויי קרבן ואי מאחר לתגלחת קאי בבל תאחר:"],[4,"ואפי' למ\"ד תגלחת אינה מעכבת","בקרבן אפ\"ה מצוה לגלח וקאי בבל תאחר באותה מצוה:"],[5,"בבל תאחר קרבנותיו","דאי משהי ליה לקרבן עובר בבל תאחר:"],[6,"כי דרוש ידרשנו אלו חטאות ואשמו'","דמיחייב אדם קאי עלייהו בבל תאחר ולא ילפינן מהא הקישא דנדרים:"],[7,"מהו דתימא חידוש הוא","מעשה דנזיר אהכי מקילי ביה דלא קאי בבל תאחר דלא נפקי קרבנותיו מהאי קרא דחטאות ואשמות:"],[8,"דלא מתפיס ליה לחטאת נזיר","דאם אמר הרי עלי חטאת נזיר לא אמר כלום ולא מיחייב ולא מידי משא\"כ בשאר קרבנות דכל קרבן שאמר אדם הרי עלי (חטאות) כך וכך מתפיס ומיחייב לאיתויי וכיון דחידוש הוא אימא לא קאי עליה בבל תאחר. דבשאר קרבנות להכי איצטריך למיכתב הכא לאקושי לנדרים דקאי נמי בבל תאחר:"],[8,"והא חטאת חלב דאינה מתפיסה בנדר","דאי אמר הרי עלי חטאת לא אמר כלום ואפ\"ה כי אכל חלב דמיחייב להביא חטאת קאי בבל תאחר:"],[9,"הואיל ואם אמר הריני נזיר אפי' מחרצן","כלומר דאפילו בחרצן בלבד הזיר עצמו הוי נזיר נמי לכל דהיינו חידוש דאיהו לא נדר אלא בחרצן בלבד (ומיתסר) ואפילו הכי מיתסר בכל מידי דמשכר והואיל וחידוש הוא לא ליקום עליה בבל תאחר כבשאר קרבנות קמשמע לן הקישא דקאי בבל תאחר:"],[10,"עד שיזיר מכולן","דאי [אמר הריני] נזיר מחרצן לא הוי כלום עד שיזיר בכל אכתי מאי חידושא איכא:"],[10,"ועוד האי חידושא","דקאמר לחומרא הוא והיינו חומרא דאיהו לא נזר אלא בדבר אחד והוי נזיר בכולן:"]],[[0,"כגון שנדר והוא בבית הקברות","דבעודו עומד לשם נזירות לא חל עליה עד דנפיק משם - וידכי ויקבל ויחול לנזירות עליה הילכך קאי בבל תאחר שמוטל עליו לצאת וליטהר ולהתחיל נזירות:"],[1,"הניחא למ\"ד לא חיילא עליה נזירות בעודו בבית הקברות","פלוגתא היא בפרק ג' דנזיר (דף טז): ועוד האמר מר בר רב אשי במיחל כ\"ע לא פליגי דחיילא אם שותה ביין או מגלח לוקה בעודו נמי בבית הקברות חל נזירות עליו כי פליגי למילקי על הטומאה אם התרו בו בעודו לשם צא משם כי נזיר אתה רבי יוחנן סבר כיון דחיילא לענין שאר דינין לקי ור\"ש בן לקיש סבר לא לקי משום טומאה דאכתי לא חל עליו נזירות טהרה אבל ודאי חל הנזירות לענין שאר דינין לשתות יין ולגלח וא\"כ מאי בל תאחר איכא:"],[1,"וכי פליגי לענין מלקות","לאו דוקא אלא כלומר לענין מלקות דטומאה אבל מודה דמלקות איכא אי שותה יין או מגלח ומשני אפ\"ה קאי בבל תאחר לנזירות דטהרה חל עליו שיש לו לעשות נזירות דטהרה:"],[3,"משום בל תאחר דתגלחת","לעולם מיירי דשילם נזירות בטהרה מכל מקום מצוה לגלח שערו ולתתו תחת הדוד ומשהה התגלחת עובר בבל תאחר משמע קצת לאחר שלשים יום לא גילח יגלח מדקאמר דאיכא עליה משום בל תאחר:"],[5,"בל תאחר קרבנותיו","אם השלים ימי נזירותו ולא הביא איכא בל תאחר:"],[6,"דרוש ידרשנו אלו חטאות ואשמות","דפשטיה דקרא כי תדור נדר לא תאחר לשלמו אבל בחובה לא אשמעינן ונפקא מינה מידרשנו ומשמע ליה חטאת נזיר בכלל שאר חטאות:"],[8,"דלא מתפיס ליה לחטאת נזיר בנדר","שאם אומר הרי עלי חטאת נזיר לא אמר כלום דחטאת נזיר אינו בא בנדר ובנדבה ולהכי פריך מחטאת חלב דכמו כן אם לא אכל חלב ואמר הרי עלי חטאת חלב לא אמר כלום וכן כל חטאת והא דנקט חלב זהו רגילות דנקט חטאת חלב מכל שאר חטאות אבל י\"מ דלא מתפיס פירוש דא\"צ לומר הרי זה חטאתי ול\"נ דא\"כ מאי פריך מחטאת חלב האמר בהדיא בחולין דאם לא אמר הרי זו לחטאתי דאינו קרב:"],[10,"חידוש לחומרא הוא","ואע\"ג דבדוכתא אחריתא אמר חידוש אע\"פ שהוא לחומרא כגון גבי עד זומם מיהו הכי פריך אדרבה כל שכן שיש לנו לומר שהוא בבל תאחר מ\"ש משאר חטאות:"]]],[["ואם גילח על אחת משלשתן יצא לא ליעבור עליה בבל תאחר קמ''ל","ואיבעית אימא מאי חדושיה משום דלא מתפיסו בנדר והא דקא קשיא לך חטאת חלב חטאת חלב קאתיא לכפרה חטאת נזיר למאי אתיא","והרי חטאת יולדת דלא אתיא לכפרה ועבר עלה משום בל תאחר ההיא קא שריא לה למיכל בקדשי'","אמר מר ומה נדרים האב מיפר נדרי בתו ובעל מיפר נדרי אשתו אף נזירות האב מיפר נזירות בתו ובעל מיפר נזירות אשתו למה לי היקשא תיתי במה מצינו מנדרים","דילמא גבי נדרים הוא דמיפר משום דלא אית ליה קיצותא אבל גבי נזירות דאית ליה קיצותא דסתם נזירות ל' יום אימא לא קמ''ל","האומר לחבירו מודר אני וכו' אמר שמואל בכולן עד שיאמר שאני אוכל לך שאני טועם לך","מיתיבי מודר אני ממך מופרשני ממך מרוחקני ממך ה''ז אסור שאני אוכל לך שאני טועם לך ה''ז אסור הכי קתני בד''א באומר שאני אוכל לך שאני טועם לך","והתניא איפכא שאני אוכל לך שאני טועם לך אסור מודרני ממך ומופרשני ממך מרוחקני ממך ה''ז אסור תני הכי וכבר אמר מודרני","אי הכי היינו רישא ועוד אסור אסור ל''ל למתני","אלא אמר שמואל טעמא דאמר שאני אוכל לך שאני טועם לך הוא דאסור וחבירו מותר"],[[0,"שאם גילח על אחת משלשתן","דנזיר חייב שלש קרבנות עולה חטאת ושלמים כדכתיב והקריב את קרבנו לה' כבש בן שנתו תמים וגו' (במדבר ו׳:י״ד) ואם לא הביא אלא חטאת מגלח עליו והיינו חידוש משא\"כ בשאר קרבנות ולהכי אימא אינו עובר בבל תאחר קמ\"ל:"],[1,"ואב\"א מאי חידושיה דאין מתפיסו בנדר","כדאמרינן לעיל דאי אמר הרי עלי חטאת נזיר לא מתפיס ליה:"],[1,"אתיא לכפרה","דהאי צריך כפרה משום חלב שאכל וכיון דלכפרה קא אתי קאי בבל תאחר אבל נזיר לא עביד שום חטא דליבעי כפרה:"],[3,"תיתי במה מצינו","בנדרים אב מיפר:"],[4,"אבל גבי נזירות דאית ליה קיצותא","דכיון דלא מיתסר אלא עד אותו זמן ימתין עד לזמן ולא ליעבור ליה קא משמע לן היקישא דא היקישא ליכא למיפרך כמו במה מצינו:"],[5,"אמר שמואל בכולן","בכל הני דקתני במתני' מודר אני ממך מופרשני ממך וכו' לא הוי נדר ועד שיאמר שאני אוכל לך לא מיתסר באותו דבר:"],[6,"הכי קתני","כלומר חסורי מיחסרא:"],[6,"במה דברים אמורים","דאסור כי אמר מודר אני באומר נמי שאני אוכל לך:"],[7,"והתניא איפכא","דלא מצית אמרת בד\"א:"],[7,"תני הכי","דהכי קתני שאני אוכל לך ושאני טועם וכבר אמר מעיקרא מודרני ממך אסור אבל אמר שאני אוכל לך בלבד או מודרני ממך אינו אסור אא\"כ אמר לתרוייהו דהיינו נדר גמור:"],[8,"אי הכי היינו נמי רישא","דקתני מודרני ממך בברייתא קמא:"],[8,"ועוד","אי הכי הוא כדתרצת תרי זימני אסור למה לי למיתני:"],[9,"אלא","הכי אמר שמואל טעמא דאמר נמי שאני אוכל לך הוא דאיהו אסור בלבד דמתני' בנודר בלבד קאמר דאסור דקתני אסור:"]],[[0,"וכי גילח על אחת משלשתן יצא","כי נזיר היה לענין שמביא ג' קרבנות חטאת ועולה ושלמים ויצא לענין שיהא מותר ביין ולא לעבור משום בל תאחר קמ\"ל:"],[1,"מאי חידושו דאין מתפיסו בנדר","דמכי הוי נזיר ממילא חייב להביא קרבן:"],[1,"חטאת חלב לכפרה קאתי","ושייך בל תאחר אבל נזיר לא לכפרה קאתי ולכך ליכא בל תאחר:"],[2,"והרי חטאת יולדת","דמשמע ליה דאיתא בכלל שאר חטאות תימה תיקשי ליה אמאי איצטריך היקשא לקרבן יחיד דליתיה בכלל שאר חטאות:"],[2,"ההיא קא שריא ליה למיכל בקדשים","אע\"ג דנזיר נמי שרי ליה (נמי) לשתות ביין אין זה מצוה אבל לאכול בקדשים מצוה היא דכתיב ואכלו אותם אשר כופר בהם הלכך שייך ביה:"],[3,"למה לי היקשא","אבל לעיל גבי בל תאחר לא פריך דאין עונשין מן הדין אבל לא מצי למימר גבי בל יחל דאתי במה מצינו דלא שייך נמי הכא דטעמא דמפר נדר משום עינוי נפש גם בנזירות נמי יש עינוי נפש:"],[4,"נדרים לית ליה קיצותא","ובנדרים כי נדר סתם לעולם הוא אבל נזירות אימא לא דסתם נזירות שלשים יום קמ\"ל דהך עינוי נפש ומיפר:"],[5,"אמר שמואל בכולן עד שיאמר כו'","פירוש דמודרני ממך לאו כלום לחודיה אבל שאני אוכל לחודיה ודאי אסור ומתני' פירושי קמפרש לה מודרני ממך באומר שאני אוכל לך:"],[6,"מיתיבי מודרני ממך אסור","מדקאמר אסור אכל חד משמע דבלא שאני אוכל קאמר ומשני בד״א קתני דסיפא מפרש לרישא שאין אסור אא״כ אמר שאני אוכל לך והא קתני סיפא שאני אוכל לך והכא ליכא למימר בד״א דהא שאני אוכל לחודיה אמר דדוקא לעיל דקתני ברישא מודרני ממך שייך למימר בד״א אע״ג דבריי' אחריתי היא קרי ליה סיפא וכן איתא בפרק גט פשוט (בבא בתרא דף קסה) דקאמר זהב בדינרים ופריך אי הכי היינו רישא אע״ג דהיינו ברייתא אחריתי ומשני וכבר אמר מודרני ממך תימה שהרי שאני אוכל לך לחודיה אמר וצ״ל דה״פ וכבר אמר כלומר אפילו אומר מודרני ממך דסד״א הואיל ומודרני ממך לחודיה לא אסר אפי' אמר אחריו שאני אוכל לך לא אסר וכבר אמר אפי' כבר אמר:"],[8,"אי הכי היינו רישא","כלומר אם בא התנא לאשמועינן דכ\"ע עד שיאמר שאני טועם לך א\"כ אמאי לא אמר כי האי לישנא של אידך ברייתא ולא להקדים שאני אוכל לך דאז ניחא למימר בד\"א שמפרש דאי אמר שאני אוכל לך לחודיה דאינו אסור וכן משמע דקמשני גבי וכבר אמר מודרני ממך וכן משמע דמתחילה הוה פריך ורוצה להוכיח דשאני אוכל לחודיה מהני:"],[8,"אי הכי היינו רישא","תימה מאי אי אמרת בשלמא איכא הכא וי\"ל דהכי פרושא אי אמרת בשלמא דכל חד וחד מהני לחודיה לא קשיא מידי דליכא למיפרך היינו רישא דה\"א דתנא סיפא לגלויי רישא דאי לא תנא סיפא הייתי מפרש דרישא ר\"ל כגון שאמר שאני אוכל לך עם מודרני ממך קמ\"ל סיפא דכל חד וחד לחודיה מהני:"],[8,"ועוד אסור אסור למה לי","אברייתא קאמר ליה הכי:"],[9,"אלא הכי קאמר טעמא [דאמר] בהדיא מודרני ממך שאני טועם לך הוא דאסור וחבירו מותר","דהכי משמע אסור מדלא קתני שניהם אסורים אבל מודרני ממך לחודיה שניהם אסורין דמודרני ממך משמע ממוני וממונך עלי וברייתא דקתני מודרני ממך אסור שניהם אסורים קאמר והא דלא תני שניהם אסורים משום דתנא ברישא שאני טועם לך דאז אינו אסור אלא מודר:"]]],[["אבל אמר מודרני הימך לחודיה שניהן אסורין כי הא דאמר ר' יוסי בר' חנינא מודרני הימך שניהן אסורין","תנן הריני עליך חרם המודר אסור אבל מדיר לא כגון דפריש ואת עלי לא","את עלי חרם הנודר אסור אבל מודר לא כגון דפריש ואנא עלך לא","אבל סתמא מאי שניהן אסורים הא מדקתני סיפא הריני עליך ואת עלי שניהן אסורין הדין הוא דשניהם אסורין הא סתמא הוא אסור וחברו מותר","אלא הכי אתמר דר' יוסי בר' חנינא מודר אני לך שניהם אסורין מודרני הימך הוא אסור וחברו מותר","והא מתניתין דקתני הימך ואוקימנא למתניתין לשמואל בכולן עד שיאמר שאני טועם לך ושאני אוכל לך הוא דאסור וחברו מותר אבל במודרני הימך שניהם אסורין","אלא מעיקרא דשמואל הכי איתמר טעמא דאמר שאני אוכל לך ושאני טועם לך הוא דאין הוא אסור אלא באכילה הא מודרני ממך אסור אפילו בהנאה","אי הכי לימא שמואל הכי ואם לא אמר אלא שאני אוכל לך ושאני טועם לך אין אסור אלא באכילה","אלא הכי איתמר טעמא דאמר שאני אוכל לך ושאני טועם לך הוא דאסור אבל אמר מודרני הימך לא משמע דאמר אסור מאי טעמא מודר אני ממך לא משתעינא בהדך משמע מופרשני ממך דלא עבידנא עמך משא ומתן משמע מרוחקני ממך דלא קאימנא בד' אמות דילך משמע"],[[0,"אבל אמר מודרני הימך לחוד","דלא אמר שאני אוכל לך:"],[0,"שניהן אסורין","דכיון דאמר שאני אוכל לך משמע דאסר נפשיה בלבד שאינו אוכל מחבירו אבל כי אמר מודרני הימך סתם משמע דמדיר נמי חבריה מיניה מכל וכל:"],[1,"תנן","בפ' השותפין (לקמן מז:):"],[1,"הריני עליך חרם המודר אסור","והא הכא דלא אמר שאני אוכל לך חרם ולא הוי אסור אלא המודר ולא שניהן:"],[1,"כגון דמפריש","בהדיא אבל את עלי לא:"],[3,"אבל סתמא","דלא פריש ואת עלי לא מאי שניהן אסורין:"],[3,"הדין הוא דשניהן אסורין","דאמר בפירוש הריני עליך ואת עלי אבל סתמא דאמר הריני עליך ולא אמר ואת עלי לא הוו שניהן אסורין אלא חד בלבד:"],[4,"אלא הכי איתמר אמר ר' יוסי בר' חנינא מודרני ממך הוא אסור וכו'","דהיינו כמתניתין הריני עליך חרם וכו':"],[5,"והא מתני' מודרני הימך","קתני ואוקמא שמואל דאמר בכולן עם כל אחד ואחד שאני אוכל דאהכי איהו אסור וחבירו מותר אבל אמר מודרני הימך בלבד ולא אמר שאני אוכל שניהן אסורין והיינו דלא כרבי יוסי בר' חנינא:"],[6,"אלא מעיקרא דשמואל הכי איתמר","הכי מתרץ לה למתניתין ולא כדאוקימנא דתיקשי לר' יוסי:"],[6,"הא אמר מודרני הימך","דלא מפרש כלום ודאי מכולה מילתא מדיר ואסור אפי' בהנאה:"],[7,"א\"ה לימא שמואל הכי","למה ליה אפושי למימריה כולי האי לימא הכי אמר שמואל ואם לא אמר שאני אוכל לך דלא אמר אלא מודרני הימך אסור אפילו בהנאה:"],[8,"אלא הכי אתמר","אמר שמואל טעמא דאמר שאני אוכל לך דכיון דאמר בפירוש אכילה אסור אבל לא אמר בפירוש אכילה לא אסור למיכל מדידיה דדילמא הא דאמר מודר אני ממך אדיבוריה קאמר דלא מישתעי בהדיה אבל לא למיכל מיניה וכן כי אמר מופרשני ממך דלא אמר שאני אוכל דדילמא ממשא ומתן קא פריש מיניה מרוחקני ממך נמי דלא ליקרב בארבע אמות דיליה משמע ולא דמדיר מאכילתו:"]],[[1,"תנן הריני עליך חרם המודר אסור אבל לא המדיר","ולשמואל דאמר מודרני ממך משמע תרוייהו הכי נמי נימא הריני עליך חרם משמע הריני על ממונך חרם וגם מדיר נמי ליתסר ומשני דפריש ואת עלי לא ועתה פריך הרי את עלי חרם אסור ומודר מותר ואמאי נימא דה\"ק הרי את עלי וממוני חרם ואסור גם מודר:"],[4,"אלא אי איתמר דרבי יוסי בר חנינא הכי אתמר מודר אני ממך הוא אסור וחבירו מותר","תימה מאי אתא לאשמעי' הא תנא בברייתא הכי וי\"ל דאשמעי' דמודרני ממך לא משמע מודר ממונו אע\"ג דהריני חרם ר\"ל מודר ממונו זה לא אמר הכי:"],[5,"והא מתני' דממך תנן","כלומר אכתי [קשה] דשמואל קאמר דאמר דמודרני ממך דשניהם אסורים:"],[6,"","אלא שמואל הכי אתמר טעמא דאמר שאני אוכל הוא דאין אסור אלא באכילה. דלישנא דאסור במתני' משמע ליה אסור באכילה ולא בהנאה אבל מודרני ממך אסור בהנאה ומודרני דקתני בברייתא אסור בהנאה וה\"ק שמואל וכולן אסור בהנאה עד שיאמר שאני טועם לך:"],[7,"אי הכי לימא שמואל הכי אם לא אמר שאני טועם לך אסור [אפי'] בהנאה","דלישנא עד שיאמר שאני טועם לך משמע כשאני טועם אסר עצמו טפי ממודרני והא ליתא דאדרבה מודרני חמור טפי ויש ספרים דגרסי לימא שמואל ואם לא אמר אלא שאני אוכל לך אינו אסור אלא באכילה וקשה ליישבו. וה\"ה דלעיל דשמואל קאמר אבל מודרני שניהם אסורים מצי למפרך לימא שמואל אם לא אמר שאני אוכל לך שניהם אסורים:"],[8,"אלא הכי איתמר","לעולם כדאמר מעיקרא דלשמואל מודרני לחודיה לא אסר כלל דלמא לא משתעי בהדך קאמר וקשה מברייתא דלעיל דמודרני אסור בלא שאני טועם לך וי\"ל דהאי אסור ר\"ל דלא מישתעי בהדיה א\"נ מעתה נחית לומר תנאי היא דברייתא דלעיל ס\"ל כרבנן דידים שאינם מוכיחות הויין ידים ושמואל סבר דמתני' כרבי יהודה דאמר לא הויין ידים:"]]],[["לימא קסבר שמואל ידים שאין מוכיחות לא הוויין ידים אין שמואל מוקים לה למתני' כר' יהודה דאמר ידים שאין מוכיחות לא הוויין ידים","דתנן גופו של גט הרי את מותרת לכל אדם רבי יהודה אומר ודין דיהוי ליכי מינאי ספר תירוכין ואיגרת שבוקין","אמאי דחיק שמואל לאוקומה למתני' כרבי יהודה לוקמה כרבנן אע''ג דאין ידים מוכיחות","אמר רבא מתני' קשיתיה אמאי תאני שאני אוכל לך שאני טועם לך ליתני שאני אוכל שאני טועם ש''מ בעינן ידים מוכיחות","איתמר ידים שאין מוכיחות אביי אמר הוויין ידים ורבא אמר לא הוויין ידים אמר רבא רבי אידי אסברה לי אמר קרא (במדבר ו ב) נזיר להזיר לי''י מקיש ידות נזירות לנזירות מה נזירות בהפלאה אף ידות נזירות בהפלאה","לימא בפלוגתא דר' יהודה ורבנן קמיפלגי דתנן גופו של גט הרי את מותרת לכל אדם ר' יהודה אומר ודין דיהוי ליכי מינאי ספר תירוכין וגט פטורין ואיגרת שבוקין אביי דאמר כרבנן ורבא דאמר כרבי יהודה","אמר לך אביי אנא דאמרי אפי' לר' יהודה עד כאן לא קאמר רבי יהודה בעינן ידים מוכיחות אלא גבי גט דבעינן כריתות וליכא אבל בעלמא מי שמעת ליה","ורבא אמר אנא דאמרי אפי' לרבנן ע''כ לא קאמרי רבנן דלא בעינן ידים מוכיחות אלא גבי גט"],[[0,"לימא סבר שמואל ידים שאין מוכיחות כו'","דהכא הואיל ולא אמר ממש שאני אוכל לך אמרינן לא מוכחא מילתא דבאכילה קאמר ולא מיתסר באכילה:"],[1,"רבי יהודה אומר ודין די יהוי ליכי וכו'","דקסבר אי לא כתב ביה ממש ודין לאו מוכחא מילתא דבהאי גיטא מגרש לה דידים שאין מוכיחות לא הויין ידים:"],[2,"לוקמה למתני' כרבנן","לימא אע\"ג דקאמר מודר אני ממך או מרוחק אני ממך לחודיה אסור באכילה ואע\"ג דלא אמר שאני אוכל לך דידים שאין מוכיחות הויין ידים כרבנן דאמרי לא צריך למיכתב בגט אלא הרי את מותרת לכל אדם:"],[3,"מתני' קשיתיה","דלא מצי לאוקמה כרבנן:"],[3,"ליתני שאני אוכל או שאני טועם","למה לי למימר לך אלא להכי קתני לך דקסבר ידים שאין מוכיחות לא הויין ידים ואי קתני שאני אוכל בלבד ולא קאמר לך לא הוה משמע דמודר מחבירו דבעינן ידים מוכיחות וכי אמר נמי מודרני ולא אמר שאני אוכל לך לא משמע דבאכילה קאמר אלא דלא מישתעינא בהדך:"],[4,"מקיש ידות נזירות","כדאמרינן לעיל דמלהזיר נפקא ידות נזירות:"],[4,"מה נזירות בהפלאה","דבעינן שיפרש לנזירות דכתיב כי יפליא (במדבר ו) אף ידות נמי בעינן שיפרש לדיבורו דאי לא מפרש לא הוי כלום דידים שאין מוכיחות לא הויין ידים:"],[6,"דבעינן כריתות","שכורת בינו לבינה דבעינן שיפסיק לדיבורו:"]],[[0,"לימא קסבר שמואל ידים שאין מוכיחות לא הויין ידים מדקאמר מודרני ממך שרי","ומשני אין כלומר ודאי סבר דלא הויין ידים ומוקי לה למתניתין כרבי יהודה דתנן גופו של גט הרי את מותרת לכל אדם רבי יהודה אומר ודין דיהוי ליכי מינאי אגרת וכו' במאי קמיפלגי רבנן סברי ידים שאין מוכיחות הויין ידים ולא בעי ודין וכו' ורבי יהודה סבר לא הויין ידים מדקבעי לומר ודין דאי לא כתב ודין בגט הוי כמגרש בדבורא בעלמא ושטר ראיה בעלמא הוא וכן משמע פ' המגרש דקאמר דקריא למוכיחו' מודין ולקמן בשמעתין משמע דהמוכיח הוי מלישנא דמנאי מדקאמ' עד כאן לא קאמר התם לא בעי' ידים מוכיחות אלא גבי גט דאין אדם מגרש אשת חבירו אלמא דמלישנא דמנאי קדייק:"],[2,"ואמאי דחיק שמואל לאוקמא מתני' כרבי יהודה לוקמא כרבנן","תימה הלא יש לו לאוקמה כר' יהודה משום דס״ל כוותיה ויש מתרצים דמוטב לאוקמא כרבנן ואע״ג דהוא לא ס״ל ועתה להך לישנא משמע דשמואל סבר דידים שאין מוכיחות לא הויין ידים והכי מוכח סוגיא דקידושין (דף ה:) גבי הרי את מאורסת דקאמר לימא קסבר שמואל ידים שאין מוכיחות הויין ידים לא דאמר הרי את מאורסת לי אבל אי לא אמר לי לא והיינו כסוגיא דהכא מיהו תימה גדול מאי פריך מאי דוחקיה לאוקמה מתני' כר' יהודה דשינויא דשנינן שנויא דחיקא הוא מוטב לאוקמה כרבנן והוא לא ס״ל ועוד הקשה הר״ר יוסף מהאי דפרק כל הגט (גיטין דף כו.) דקאמר הכותב טופסי גיטין צריך שיניח מקום האיש ומקום האשה ומקום הזמן וקאמר שמואל עלה דההיא אף מקום הרי את מותרת לכל אדם פי' משום דהוא עיקר של גט ואי סבירא ליה כר' יהודה א״כ צריך שיניח מקום ודין שהרי ודין הוי עיקר לר' יהודה להכי ל״ג (אין) כ״א ושמואל מוקי לה למתני' כר' יהודה והוא סבר לה כרבנן ואז ניחא דפריך שפיר לוקמא כרבנן כיון דגם הוא סבר כרבנן מיהו קשה מההיא דקידושין דמשמע שמואל אית ליה דלא הויין ידים ור״י מחלק בידים שאין מוכיחות גרועות כי ההיא דקידושין דאם לא אמר לי הויין גרועות טפי מדאי (דאדם עשוי לקדש אשה לחבירו) וכן ההיא דנזיר דפריך עלה דאמר האומר אהא ה״ז נזיר ופריך ודילמא אהא בתענית קאמר ומוקי שמואל שהיה נזיר עובר לפניו ולהכי צ״ל הכא לימא קסבר שמואל ידים שאין מוכיחות לא הויין ידים ומשני לא שמואל מוקי לה למתני' כר' יהודה פירוש לעולם קסבר הויין ידים חשובות כי הכא מודרני ממך ומוקי לה למתני' כר' יהודה והוא לא סבירא ליה ובהא ניחא ההיא דריש פ״א דנזיר משום דאהא הוי ידים גרועות משמע כוליה גופיה וזהו תענית דנזיר לא הוי כוליה גופיה ולהכי צריך לאוקומה בנזיר עובר לפניו וכן ההיא דקידושין כדפי' התם ור״ת גרס אין השתא יש ליישבו ודייק אין ידים גרועות כי התם לא הויין ידים אבל ידים חשובות ס״ל דהויין ידים:"],[3,"מתני' קשיתיה","מאי איריא התם שאני אוכל לך בלא לך נמי אלא ש\"מ דלא הויין ידים וקשה מברייתא דלעיל דאמר שאני אוכל לך משמע כמו כן דאי לא אמר לך לא מועיל וי\"ל דכיון דגלי דמודרני ממך מועיל משמע ממילא לך לאו דווקא ובלא לך נמי מהני:"],[3,"ליתני שאני אוכל (לך) שאני טועם","פי' בלא לך וא\"ת א\"כ לא הוה ידעינן למאן קאמר וי\"ל דמיירי במסרבין בו לאכול והוא ממאן וא\"כ לאותו שמפציר בו לאכול קאמר שאני טועם שאני אוכל משלך ואפי' בלא לך שמעינן הכי וא\"ת אכתי מאי תירץ דהנך ברייתא דלעיל דקתני אסור תרי זמני דמשמע דמודרני לחוד אסור ולא שאני אוכל לך וי\"ל כיון דאוקמא טעמא דשמואל משום דידים שאין מוכיחות דפליגי תנאי בעלמא בגיטין א\"כ נתרץ דהנך ברייתא דלעיל כרבנן דרבי יהודה דסברי דידים שאין מוכיחות הויין ידים ושמואל סבר כר' יהודה דמעיקרא שלא היה מעמיד טעמא דשמואל משום שאין מוכיחות וא\"כ הוי טעמא דשמואל משום דלא חשוב יד מודרני בלא שאני אוכל להכי הוה קשיא ליה לשמואל מהנך ברייתא דלא מוכיחות פלוגתא דתנאי בהכי אבל השתא דטעמא דשמואל משום שאין מוכיחות ניחא כדפרי' צ\"ע לשמואל כשאני אוכל בלא מודרני אם מועיל אם לאו ופר\"י כר' יהודה דמתני' שאומר שאני אוכל לך משמע דשאני אוכל לך מועיל בלא מודרני אפי' לשמואל וכ\"נ דודאי מודרני בלא שאני אוכל לך הוי ידים שאין מוכיחות כדמפרש טעמא דילמא דלא משתעינא בהדך קאמר אבל כשאני אוכל לך או איני טועם לך הוו ידים מוכיחות והקשה ריצב\"א א\"כ לא מצינו ידים ורגלים דא\"כ כל מה שידבר אדם עם חבירו יהא נדר שאם אמר אני אוכל או אוכל לך הוי נדר לגי' דשאני אוכל וי\"ל דלא קשה מידי דווקא כשאני אוכל או בשאיני בשי\"ן הוי יד לפי [שחטף] וחסר [ומנע] לשונו שמדלג קונם שהיה לו לומר או בתחילה או בסוף אבל אני אוכל לך או איני אוכל לך בלא שי\"ן לא הוי יד כלל וא\"ת כיון דשאני אוכל לך מועיל בלא מודרני אבל מודרני אינו מועיל בלא שאני אוכל לך מנלן דשאני אוכל הוי יד לנדר דילמא הוי יד לשבועה שמדלג שבועה לכתחילה וי\"ל דבשבועה רגילות לומר שבועה שאוכל או שלא אוכל אבל שאני או שאיני שייך לנדרים וא\"ת למאי דפרישית דשאני אוכל הוי יד בלא מודרני גם לשמואל והא לעיל בתחילת סוגיא כדפריך ליה מהנך ברייתא משני שמואל דברייתא שניה וכבר אמר מודרני ממך משמע בהדיא דשאני אוכל לא מהני בלא מודרני ויש לדחות שלא בא אלא להשמיענו דמודרני אינו מועיל בלא שאני אוכל לך ועי\"ל דודאי מעיקרא שהיה סובר טעמא דשמואל דלא הוי מודרני יד כלל בלא שאני אוכל לך אז ודאי צריך לומר דה\"ה שאני אוכל לך לא הוי יד ואינו מועיל בלא מודרני אבל למסקנא דאסיקנא דטעמא דשמואל משום יד נאמר ודאי דשאני אוכל הוי מוכיח שפיר בלא מודרני כדפרישית א\"כ גם לשמואל מועיל שאני אוכל בלא מודרני כ\"נ למהר\"ף נ\"ע מיהו ר\"י פירש דשאני אוכל אינו מוכיח בלא מודרני:"],[4,"אמר קרא נזיר להזיר","לרבות ידות נזירות כנזירות מה נזירות בהפלאה אף ידות נזירות בהפלאה:"],[7,"ע\"כ לא קאמרי רבנן דלא בעינן ידים מוכיחות אלא גבי גט משום דמוכח דמיניה הוא דאין אדם מגרש אשת חבירו אבל בעלמא מי שמעת להו","תימה לר\"י תיקשי ליה ברייתא דלעיל מודרני ממך אסור אלמא דהויין ידים וקשה לאביי מתני' דאמר שאני אוכל לך אבל בלא לך מותר וי\"ל דלא ס\"ל לאביי כשמואל אבל י\"ל דלך לאו דוקא או שמא למסקנא ניחא דאביי כרבנן ורבא כרבי יהודה אבל קשה דבפ\"ב דנזיר (דף סב.) קאמר איפכא דאביי אית ליה הויין ידים וי\"ל דהני שיטות הפוכות שבתלמוד וההיא דהתם כאיכא דאמרי אבל גירסא דהכא כר' יהודה כדמוכח התם [עיין תוס' נזיר שם ד\"ה איש]:"]]],[["דאין אדם מגרש את אשת חבירו אבל בעלמא מי שמעת להו","מיתיבי הרי הוא עלי הרי זה [עלי] אסור מפני שהוא יד לקרבן טעמא דאמר עלי הוא דאסור אבל לא אמר עלי לא תיובתא דאביי","אמר לך אביי טעמא דאמר עלי הוא דאסור אבל אמר הרי הוא ולא אמר עלי הרי הוא דהפקר הרי הוא דצדקה קאמר והא מפני שהוא יד לקרבן קתני","אלא אימא טעמא דאמר עלי הוא אסור וחבירו מותר אבל אמר הרי הוא שניהן אסורין דדלמא הרי הוא הקדש קאמר","מיתיבי הרי זו חטאת הרי זו אשם אע''פ שהוא חייב חטאת ואשם לא אמר כלום הרי זו חטאתי הרי זו אשמי אם היה מחויב דבריו קיימין תיובתא דאביי","אמר לך אביי הא מני ר' יהודה היא והא אביי הוא דאמר אנא דאמרי אפילו לרבי יהודה הדר ביה","אלא לימא רבא דאמר כרבי יהודה","אמר לך רבא אנא דאמרי אפילו לרבנן עד כאן לא קאמרי רבנן דלא בעינן ידים מוכיחות אלא גבי גט דאין אדם מגרש את אשת חבירו אבל בעלמא בעינן ידים מוכיחות"],[[0,"דאין אדם מגרש את אשת חבירו","דאי כתב הרי את מותרת לכל אדם משמע דלאשתו קאמר דאשת איניש דעלמא אינו מגרש ומוכחא מילתא ושפיר מגרש:"],[0,"אבל בעלמא","דאי אפשר למימר הכי בעינן ידים מוכיחות:"],[1,"אבל לא קאמר עלי לא","דהרי הוא לא משמע כלום דבעינן ידים מוכיחות:"],[2,"אמר לך אביי","לעולם לא בעינן ידים מוכיחות והכא היינו טעמא דאי לא אמר בלשון קרבן לא מיתסר דדלמא הרי הוא הפקר קאמר דמוכיחות הוא להפקר או לצדקה:"],[2,"והא מפני שהוא יד לקרבן קאמר","דאסור כקרבן ולא מצית אמרת לצדקה או להפקר הוה משמע:"],[3,"אבל אמר הרי הוא","ולא אמר עלי שניהם אסורין דכיון דלא אמר עלי אלא הוא משמע דחבירו נמי אסור דה\"ק הרי הוא כהקדש מה הקדש אסור אף אותו דבר נמי אסור:"],[4,"אע\"ג דהוא מחויב חטאת ואשם לאו כלום הוא","דלא אמר עלי אלמא בעינן ידים מוכיחות:"],[4,"אם הוא מחויב","חטאת או אשם:"],[4,"דבריו קיימין","הוא דאמר חטאתי אבל לא היה מחויב חטאת אינו כלום הואיל ולא אמר עלי שאם אמר הרי זו עלי חטאת אע\"ג דלא היה מחויב הואיל ואמר עלי דבריו קיימין:"],[5,"הא מני","הא ברייתא דאמרה לא אמר ולא כלום:"],[5,"רבי יהודה היא","דאמר בעינן ידים מוכיחות ואנא דאמרי כרבנן דאמרי לא בעינן ידים מוכיחות:"],[5,"והא אמר אביי אנא דאמרי אפי' לר' יהודה","דלא בעי ידים מוכיחות אלא גבי גט אבל בעלמא לא והיכי קאמר הכא ר' יהודה היא:"],[6,"אלא [לימא] רבא דאמר כר' יהודה","דכיון דאביי לא מתרץ טעמא אליבא דר' יהודה לימא נמי דרבא לא מתרץ טעמא אליבא דרבנן כדמתרץ לעיל וכר\"י קאמר דיחידאה היא:"],[7,"לא לעולם רבא אפילו לרבנן","כדקאמרינן ע\"כ לא קאמרי רבנן כו' דודאי רבנן סבירא להו בעלמא דידים שאין מוכיחות לא הוויין ידים כרבא:"]],[[1,"הרי הוא עלי הרי זה עלי אסור","פי' ככר מונח לפניו אמר הרי עלי אסור מפני שהוא יד לקרבן ואסר עליו הככר כקרבן שכך מתנדב אדם ואומר הרי עלי טעמא דאמר הרי עלי אסור אבל לא אמר עלי לא וקשה לאביי:"],[2,"אמר לך","כלומר לכך אי לא אמר עלי לא הוי בכלל דהרי הוא הפקר קאמר:"],[2,"והא מפני שהוא יד לקרבן קתני","דמשמע דעלי הוי יד מעליא אסור אבל אי לא אמר עלי יד מיהא הוי וקשה לאביי דאמר כו':"],[2,"והא מפני שהוא יד לקרבן","כלומר אינו אלא יד בעלמא ואינו עיקר הקדש ואינו אסור אלא לזה ולא לכ\"ע:"],[3,"אלא אימא טעמא דאמר עלי הוא דאסור וחבירו מותר","דאי אמר הרי הוא אסור לכ\"ע ולאו דווקא שניהם אסורין כל אחד לדידיה לחודיה דהרי הוא עיקר הקדש קאמר:"],[4,"הרי זו חטאת הרי זו אשם","בהמת חולין עוברת לפניו אמר הרי זו חטאת לא אמר כלום משום דאין חטאת באה נדבה ולכך כי אמר חטאת ולא אמר חטאתי לא אמר ולא כלום דמשמע שמתנדב חטאת הלכך חולין הוי ואף על גב דאמרינן לקמן ככר לפניו ואמר הרי זה קרבן אסור יש לומר דהתם משום דיודע דאי אפשר לככר היותו קרבן ונתכוין לומר כקרבן אבל הכא הוא סבור שיכול להתפיס חטאת בנדבה ולא נתכוין לאסור בהמה כחטאת אלא נדבה הלכך לא אמר כלום:"],[4,"הרי זו חטאתי","אם מחויב חטאת דבריו קיימין ופריך מרישא דקאמר לא אמר כלום דידים שאין מוכיחות לא הויין ידים דאי הויין ידים כי אמר ה\"ז לחטאת היה לנו לאסור כאילו אמר חטאתי:"],[5,"הא מני ר' יהודה היא","דאמר לא הויין ידים:"],[6,"לימא רבא דאמר כרבי יהודה","כי היכי דאביי כרבנן ה\"נ רבא כרבי יהודה ולא כרבנן:"],[6,"לימא רבא דאמר כר' יהודה","דס\"ד דכי היכי דהדר ביה אביי ה\"נ הדר ביה רבא:"],[7,"אמר לך רבא ה\"נ אנא דאמרי אפי' לרבנן","כדאמר לעיל ופליגי רבא ואביי אליבא דרבנן:"],[7,"עד כאן לא קאמרי רבנן התם אלא משום דאין אדם מגרש אשת חבירו","כאן משמע דמוכיחות הוי ממינאי ובגיטין משמע דהוה להוכיח שמגרשה בלא גט ותרוייהו תננהי וצ\"ע בתוס' ממילתיה דידים שאין מוכיחות:"]]],[["בעי רב פפא יש יד לקידושין או לא היכי דמי אילימא דאמר לה לאשה הרי את מקודשת לי ואמר לחבירתה ואת נמי פשיטא היינו קידושין עצמן אלא כגון דאמר לה לאשה הרי את מקודשת לי ואמר לה לחבירתה ואת מי אמרינן ואת נמי אמר לה לחבירתה ותפסי בה קידושין לחבירתה או דלמא ואת חזאי אמר לה לחבירתה ולא תפסי בה קידושין בחבירתה","ומי מיבעי ליה לרב פפא והא מדאמר ליה רב פפא לאביי מי סבר שמואל ידים שאין מוכיחות הויין ידים מכלל דסבירא ליה לרב פפא דיש יד לקידושין חדא מגו מאי דסבירא ליה לשמואל אמר ליה לאביי","בעי רב פפא יש יד לפאה או אין יד לפאה היכי דמי אילימא דאמר הדין אוגיא ליהוי פאה והדין נמי ההיא פיאה מעלייתא היא כי קא מיבעיא ליה כגון דאמר והדין ולא אמר נמי מאי","מכלל דכי אמר שדה כולה תיהוי פאה הויא פאה","אין והתניא מנין שאם רוצה לעשות כל שדהו פאה עושה ת''ל (ויקרא יט ט) פאת שדך","מי אמרינן כיון דאיתקש לקרבנות מה קרבנות יש להם יד אף פאה יש לה יד או דלמא כי איתקש לבל תאחר הוא דאיתקש והיכא איתקש דתניא"],[[0,"יש יד לקידושין","היכא דלא מפרש ממש מקודשת לי אלא ביד דקידושין קא מקדש לה כדקא מפרש מי הוי יד לקידושין ומקודשת או אין יד לקידושין ואינה מקודשת:"],[0,"פשיטא","כיון דאמר ואת נמי קידושין עצמן נינהו דבאותן קידושין דקידש לחברתה מקדש לה נמי וכה\"ג לא הוי יד אלא קידושין גמורים נינהו:"],[0,"או דלמא","הא דאמר ואת לאו משום דתהוי מקודשת קאמר לה אלא הכי קאמר לה ואת חזאי כלומר ואת פלניתא חזית דקדישנא לה:"],[1,"והא אמר ליה רב פפא לאביי וכו'","בפ\"ק דקידושין (דף ה:) בהלכה קמייתא אמר שמואל נתן לה כסף או שוה כסף ואמר לה הרי את מקודשת הרי את מאורסת וכו' ואמר ליה רב פפא לאביי למימרא דסבר שמואל ידים שאין מוכיחות הויין ידים מדאמר ליה רב פפא הכי אליבא דשמואל דידים שאין מוכיחות כו':"],[1,"מכלל דס\"ל דיש יד לקידושין","היכא דמוכיחות:"],[1,"חדא מגו מאי דס\"ל לשמואל קאמר ליה לאביי","דהכי קאמר מי סבירא ליה לשמואל דיש יד לקידושין ואם תמצא לומר דיש להן יד מי בעינן ידים מוכיחות או לא:"],[2,"אוגיא","שדה כדאמרינן במס' [ברכות] (דף ו.) וקיימי עלן כי כסלא לאוגיא כלומר כתלמים לבקעה:"],[2,"פאה מעלייתא היא","האי שדה אחר דאמר והא נמי:"],[4,"תלמוד לומר פאת שדך","כלומר כולה שדך:"],[5,"כיון דאיתקש לקרבנות מה קרבנות יש להן יד","כדאמרינן במתני':"],[5,"או דלמא האי דאיתקש לבל תאחר","דקאי עליה נמי בבל תאחר כקרבן אבל בכה\"ג דאית ליה יד לא איתקש:"]],[[0,"יש יד לקידושין","תימה מהיכא תיתי יד לקידושין והלא בנדרים לא ידעינן יד אלא מדאתקוש נדרים לנזירות כדאמרי' לעיל וא\"כ אמרינן היכא דגלי גלי היכא דלא גלי לא גלי ועוד תדע דהא בסמוך בענין דפאה וצדקה לא מספקא ליה אלא משום דאיתקש לקרבנות וי\"ל דקידושין נמי כיון דאסר לה אכ\"ע כהקדש לכך מספקא לן דשמא יש יד לקידושין כמו הקדש מיהו אכתי קשה דלעיל אשכחן דפליגי ר' יהוד' ורבנן בידים שאין מוכיחות בגיטין משמע לכ\"ע יש יד לגיטין והשתא מהיכא תיתי דיש יד לגיטין ואפילו אם ת\"ל דגיטין וקידושין משום ויצאה והיתה דאיתקש יציאה להוייה גם בקדושין איבעיא לן ולא איפשוט ויש לומר דודאי בגיטין לא פליגי ביד דהא לשונות גמורים כתובים בתוך הגט וגם מגרש בלשון גירושין גמורין ומה שהזכיר לעיל ידים לאו דוקא אלא כלומר פליגי ר' יהודה ורבנן אי בעינן דיבור מוכיח או לא וא\"ת והא מדמה לעיל פלוגתא דר' יהוד' ורבנן בגיטין לפלוגתא דאביי ורבא דפליגי בנדרים בידים שאין מוכיחות בידים ממש וי\"ל דמ\"מ מדמה שפיר כי היכי דפליגי ר' יהודה ורבנן בגיטין אי בעי שיהא מוכיח מתוך הגט שמגרש הוא הלכך בנדרים דגלי קרא בהו ידות הוו פליגי ר' יהודה ורבנן בידים שאין מוכיחות אי מהני אי לא:"],[0,"או דלמא ואת חזאי קאמר לה","פי' דשמא אין יד ולכך תלינן לומר ואת חזאי קאמר תימה למה האריך כל כך הו\"ל לומר או דלמא לא וי\"ל דאי לאו משום דאית ליה למיתלי במילתא אחריתי ואת חזאי קאמר הוה פשיטא ליה דיש יד לקידושין ול\"נ דהא גבי ידות דנדרים אע\"ג דליכא למיתלי במידי אחרינא אפ\"ה ה\"א דאין יד אי לאו דגלי קרא וע\"כ האומר ככר זה עלי דהוי יד להקדש כדאמר לעיל ליכא למיתלי במידי אחרינא [דאי] איכא למיתלי במידי אחרינא א\"כ לא הוה מהני למ\"ד ידים שאין מוכיחות לא הויין ידים וגם מודרני ממך שאני אוכל לך כשאמר שניהם לשמואל [דאי] תרוייהו אמר ודאי ליכא למיתלי במידי אחרינא ואפ\"ה לא הוה מועיל אי לאו דגלי קרא ידות וא\"כ הוה ליה למימר או דלמא אין יד ולכן לא מהני אף כי ליכא למיתלי במידי אחרינא לכ\"נ לומר דשמא הכא כיון שאמר בפירוש לשון קדושין גמורין לאחת מן הנשים שאמר לה הרי את מקודשת לי הלכך כי אמר לחברתה בתר הכי ואת אי לא דאיכא למיתלי במידי אחרינא לומר דשמא הכי כיון שאמר ואת חזאי הוי משתמע לשון קידושין גמורין ולא יד לקידושין ולא דמי לידות דנדרים דמיירי שלא הוזכרה קודם לכן כלל [ובזה] ניחא קושיא אחריתי שיש להקשות דמשמע הך בעיא דאי יש יד לקידושין מהני אע\"ג דאיכא למיתלי באת חזאי ואמאי והלא סוף סוף ידים שאין מוכיחות הויין ולמ\"ד לא הויין [ידים] אינו מועיל אלא ודאי כדפרישית דכיון שהזכיר קודם לכן לשון קדושין גמורין שפיר הוי יד מוכיח ומיירי שאחת נעשית שליח לחברתה ונתן לה שתי פרוטות דאיכא שיעור קידושין לשתיהן ובשלא היה מדבר עם השניה כלל בעסקי קידושין דאם היה מדבר על עסקי קידושין א\"כ היתה מקודשת אפי' בלא אמר ואת. בתוס' פי' דמיירי שנתן לכל אחת פרוטה והקשה אמאי לא קאמר או דלמא שקולי לשם מתנה קאמר כדקאמר בתר הכי כה\"ג גבי צדקה [ותי'] דמשמע ליה ואת דקאמר קאי אדיבור הרי את מקודשת לי שאמר מיד וצ\"ע:"],[1,"חדא מגו מאי דס\"ל לשמואל א\"ל לאביי","כלומר לדבריו של שמואל דמשמע דפשיטא ליה דיש יד לקידושין ויש ספרים דגרסי חדא מאי דס\"ל ליה לשמואל קאמר ליה לאביי כלומר לאחד מן הדברים שיש להסתפק בדברי שמואל הזכיר לו רב פפא לאביי שאמר לו לימא קסבר שמואל ידים שאין מוכיחות הוויין ידים ה\"ה שהיה לו לומר לימא קסבר שמואל דיש יד לקידושין והלא בעיא היא ולא איפשיטא אלא עדיפא למנקט אותה סברא דידים שאין מוכיחות משום דמירמא משמואל לשמואל:"],[2,"בעי רב פפא יש יד [לפאה]","פי' את\"ל אין יד [לקידושין] דלמא שאני פאה דאיתקש לקרבנות משום שהפסיק בקושיא ומי בעיא ליה לרב פפא וכו' לכך חוזר ומפרש בעיא דרב פפא בתחילת הבעיא כמו באינך בעיות דבסמוך שלא הזכיר רב פפא:"],[2,"הדין אוגיא ליהוי פאה","אוגיא ערוגה ועל שם החריץ שסביב הערוגה קורין ליה אוגיא:"],[2,"כי קמיבעיא ליה כגון דאמר והדין ולא אמר נמי מאי","אור\"י דמספקא ליה [אי] והדין נמי קאמר או דלמא והדין לעצמו קאמר דומיא דבעיא דצדקה דמספקא ליה והדין לנפקותא בעלמא הוא ואע\"ג דלא מפרש ליה תלמודא הכי מ\"מ כך רגילות התלמוד שמקצר במקום אחד ומאריך במקום אחר א\"נ משום הכא לא פירש משום שהקשה ליה מיד מכלל דכי אמר כולו שדה:"],[3,"מכלל דכי אמר כולה שדה ליהוי פאה","תימה מהיכא דייק ליה ופירש דדייק ליה מדקאמר תלמודא אי דאמר והדין נמי ההיא פאה מעלייתא ומשמע דאפי' כל השדה הויא פאה מדעביד שתי הערוגות פאה ול\"נ חדא דמי לא עסקינן בשדה גדולה דגם כי עבד שתי ערוגות פאה אכתי יש שאר לעצמו ועוד דא\"כ הוה קאי מכלל אסוגיא דתלמודא שאומר אי דאמר והדין כו' ולא אמילתיה דרב פפא ומכלל משמע דקאי אעיקר מילתיה דרב פפא לכ\"נ לומר דהכי נמי קאי אבעיא דרב פפא שהוא מסופק או דלמא והדין לעצמו שמשייר הערוגה השניה לעצמו ואם היה שם שאר הרבה מלבד זה א\"כ לא שייך לומר והדין לעצמו כיון שמלבד זה יש הרבה לעצמו לו אלא ש\"מ שאותן שתי הערוגות הן שוין כל השדה ואפ\"ה אמר דאי והדין קאמר תרווייהו הוויין פאה אלמא כי אמר תיהוי כל השדה פאה הוי פאה ולהכי פריך מכלל וכו' ומשני אין והתניא מנין שאם רצה לעשות כל השדה פאה עושה וכו' וא\"ת והלא בירושל' (פ\"ג דפאה) גבי קרקע כל שהוא חייבת בפאה אי עד שלא קצר אין כאן חיוב אי שקצר אין כאן פאה דבעינן שיתחיל לקצור ואפי' כשהתחיל קודם שיתחייב בפאה י\"ל דה\"נ קאמר הכא כל שדהו פאה אחר שיתחיל מעט ואפי' כשהתחיל לקצור שבולת לבד שרי בכך ולעיל נמי דבעי מיירי שהתחיל לקצור מעט ומ\"מ שפיר קאמר והדין לעצמו כדפרישית לפי דבאותה קציר אין בו שוה פרוטה הלכך לא חשיב שיור לעצמו אותו קציר ראשון:"],[4,"ת\"ל פאת שדך","ולא כתיב פאת משדך ש\"מ אפי' כל השדה קאמר וכגון שהתחיל לקצור מעט כדפרישית והא דתנא נמי פאה אין לה שיעור מיירי נמי כשהתחיל לקצור כדפרישית וא\"ת א\"כ אמאי לא תנן נמי תרומה בהדי דברים שאין להם שיעור דתרומה יכול אדם לעשות כל גורנו תרומה רק שישאר מעט משום ראשית דמשמע ששיריה ניכרים דהא פאה נמי בעינן שישאר מעט לעצמו תחלה כדפרישית ואפ\"ה חשיב ליה בהדי דברים שאין להם שיעור וי\"ל דמ\"מ לא דמי דגבי פאה קודם שהתחיל לקצור אין שום חיוב עליו דכי תקצור אמר רחמנא והדר לא תכלה פאת שדך ומכיון שמתחיל לקצור החיוב מיד אין לו שיעור אבל בתרומה מכיון שנתמרח בכרי חל עליה חיוב תרומה ואפ\"ה אין יכול לעשות כל גורנו תרומה דבעינן שיריה ניכרים הילכך בתרומה לא מתני ליה אין לו שיעור וה\"נ מתרץ ליה בירושלמי דפאה:"]]],[["(דברים כג כב) מעמך זה לקט שכחה ופאה","יש יד לצדקה או אין יד לצדקה היכי דמי אילימא דאמר הדין זוזא לצדקה והדין נמי ההוא צדקה עצמה היא אלא כגון דאמר הדין ולא אמר נמי מאי הדין נמי צדקה קאמר או דלמא [מאי] והדין (נמי) לנפקותא בעלמא קאמר ודבורא הוא דלא אסקיה","מי אמרינן כיון דאיתקש לקרבנות דכתיב (דברים כג כד) בפיך זו צדקה מה קרבנות יש להן יד אף צדקה יש לה יד או דלמא לבל תאחר הוא דאיתקש","יש יד להפקר או דלמא אין יד להפקר היינו צדקה","אם תמצא לומר קאמר אם תמצא לומר יש יד לצדקה דאין היקש למחצה הפקר מי אמרינן היינו צדקה או דלמא שאני צדקה דצדקה לא חזיא אלא לעניים אבל הפקר בין לעניים בין לעשירים","בעי רבינא יש יד לבית הכסא או לא היכי דמי אילימא דאמר הדין ביתא ליהוי בית הכסא והדין נמי ההוא בית הכסא נמי הוה אלא כגון דאמר והדין ולא אמר נמי מאי הדין דאמר והדין נמי בית הכסא או דלמא מאי והדין לתשמישא בעלמא קאמר","מכלל דפשיטא ליה לרבינא דיש זימון לבית הכסא והא מיבעיא ליה לרבינא הזמינו לבית הכסא מהו הזמינו לבית המרחץ מהו זימון מועיל או אין זימון מועיל","רבינא חדא מגו חדא קמיבעיא ליה זימון מועיל או אין זימון מועיל את''ל יש זימון יש יד או אין יד תיבעי ליה:","מנודה אני לך וכו': אמר אביי מודה ר''ע לענין מלקות שאינו לוקה דאם כן ניתני ר' עקיבא מחמיר","אמר רב פפא בנדינא מינך דכולי עלמא לא פליגי דאסור משמתנא מינך לכולי עלמא שרי במאי פליגי"],[[0,"מעמך","כי דרוש ידרשנו ה' אלהיך מעמך:"],[1,"לנפקותא בעלמא","כלומר והדין זוז אחר ליהוי לי להוצאה ודבורא הוא דלא אסקיה דלא גמר דיבורו דאמר עלי לנפקותא:"],[2,"דכתיב בפיך","כאשר דברת בפיך יצא מפי צדקה (ישעיהו מ״ה:כ״ג):"],[4,"או דלמא שאני צדקה","להכי אית לה יד דלא חזיא אלא לעניים אבל הפקר דהא נמי אפי' לעשירים חזי מי אמרת דיש להן יד:"],[5,"יש יד לבית הכסא","היכא דלא אמר בפירוש דלהוי בית הכסא מי הוי הזמנה ואסור להתפלל בו:"],[7,"חדא מגו חדא קא מיבעיא ליה","מגו דקא מיבעיא ליה אי זימון מועיל בעי נמי אי אית ליה יד או לא:"],[8,"מנודה אני לך","כלומר כמנודה שאסור לההנותו כך אהא אסור ליהנות ממך:"],[8,"ר׳ עקיבא היה חוכך בזה להחמיר","כאדם שמתחכך אילך ואילך כך איהו לא בריר ליה שיהא ודאי אסור:"],[8,"לענין מלקות","שאם עבר אינו לוקה כל כך ודאי לא היה מחמיר:"],[9,"בנדינא ממך","דמשמע בפירוש אהא מנודה לך דהיינו ודאי לכולי עלמא אסור: שמתא אינו כל כך כנידוי:"]],[[4,"הפקר היינו צדקה","דסתם מפקיר בשביל שיזכו בה עניים ומסיק מ\"מ הפקר הוי לעניים ולעשירים:"],[4,"ואם תמצא לומר דאין היקש למחצה","וא\"ת שפיר קאמר דאין היקש למחצה ומאי מיבעיא ליה גבי צדקה י\"ל דשאני הכא דסברא הוא שלא לעשות ההיקש אלא לענין בל תאחר הכתוב שם שהרי כמה דברים הכתובים באותו פסוק שחלוקים זה מזה בכמה ענינים ולא נכתב שם אלא לענין בל תאחר:"],[4,"הפקר היינו צדקה","דסתם מפקיר בשביל שיזכו בה עניים ומסיק מ\"מ הפקר הוי לעניים ולעשירים:"],[5,"יש יד לבית הכסא","ה\"נ לא מספקא ליה דאורייתא אלא חומרא בעלמא מדרבנן מספקא ליה אם החמירו לענין לאסור כך לדבר ק\"ש כיון דביה\"כ [שאמרו] שאין בו צואה (אי נמי) כיון דיש זימון כדמסיק אם כן תאסור ע\"י דבור בעלמא כמו אינך הפקר וצדקה דמ\"מ מדרבנן מיבעי ליה דהא לא איתקש:"],[6,"מכלל דיש זימון","כאן משמע דאפי בדיבור בעלמא בעיא ליה דשמא יש זימון ובשבח מוכח דגם בעשיה מבעיא [דשמא] אין זימון ומוקי התם בחדתי שבנאו לכך וכן האמת והבעיא הויא בין בדבור בין במעשה:"],[6,"הזמינו לבית הכסא הזמינו לבית המרחץ מהו","בשבת (פ\"א דף י) פ\"ה ול\"ג למרחץ דקמייתי התם בעיא דרבינא הזמינו לבית הכסא וקאמר התם מאי לאו ה\"ה למרחץ מיהו יש לישבו דגריס ליה הכא אע\"ג דרבינא לא הזכיר בבעיא רק בית הכסא כדמוכח בשבת מ\"מ התלמוד הזכיר כאן המרחץ לפי מה דס\"ד התם ה\"ה למרחץ:"],[7,"חדא מגו חדא קא מיבעיא ליה","מגו דקא מיבעיא ליה אי זימון מועיל בעי נמי אי אית ליה יד או לא:"],[7,"תיבעי לך","פי' כמו תיקו ולשון נדרים משונה:"],[8,"מנודה אני לך","פי' ריצב\"א דלשמואל דאמר גבי מודרני מופרשני דבעי שיאמר עמו שאני אוכל ה\"ה הכא גבי מנודה אני לך דבעי שיאמר עמו שאיני אוכל לך דאל\"כ אמרי' דלמא דלא קיימא בד' אמות דילך קאמר ליה כמו כי מרוחקני ממך דטפי משנינן לישנא דמנודה מלישנא דמרוחקני ול\"נ דא\"כ שמואל היה לו להמתין לומר דבריו עד כאן והוה קאי אכולה מילתא דמתני' לכ\"נ לר\"י דהכא ודאי מודה שמואל דלא בעינן שאני אוכל לך דאין לספקו בהרחקת ד\"א דאמר ליה בלשון נידוי לפי שאין אדם רגיל להזכיר לשון נידוי על עצמו כשא\"ל לחבירו לא אעמוד בד\"א שלך לפי שגנאי הוא לו להזכיר לשון נידוי לעצמו אלא אומר בפירוש להרחיק ד\"א ממנו והלכך כיון דאין לספק מנודה אני לך בהרחקת ד\"א א\"כ ודאי לשון נדר הוא ר\"ל לשון נע ונד ומרוחק מהנאתו כדמסיק בגמרא שאינו לוקה:"],[8,"מודה ר\"ע וכו'","דא\"כ ליתני ר\"ע מחמיר תימא תלמודא דדייק מאריכות הלשון דמילתיה דר\"ע דקתני חוכך בזה להחמיר וע\"ז הוא אומר שהיה די לומר ר\"ע מחמיר ולישתוק מחוכך והיא גופה אין להקשות אמאי אין התלמוד מדקדק משינוי הל' לאסור להחמיר איכא למימר אין זה דיוק משינוי ל' כמו מאריכות הל':"],[9,"נדינא מנך כ\"ע ל\"פ דאסור","פי' משום דל' נע ונד הוא א\"כ מועיל שפיר בלא שאני אוכל לך ושפיר הוי ידים מוכיחות טפי ממודרני ממך דאין לספקו בהרחקת ד\"א משום דלשון נדינא לא משמע כלל ל' הרחקה אלא משמע שאני נע ונד מליהנות ממך:"],[9,"משמתנא כ\"ע לא פליגי דשרי","דלשון קללה הוא כמו מקוללני ממך ואפילו את\"ל שמנדה עצמו מלעמוד בד' אמותיו מכ\"מ איסור הנאה לא משמע:"]]],[["במנודה אני לך דרבי עקיבא סבר לישנא דנידויא הוא ורבנן סברי לישנא דמשמתנא הוא","ופליגא דרב חסדא דההוא גברא דאמר משמתנא בנכסיה דבריה דרב ירמיה בר אבא אתא לקמיה דרב חסדא א''ל לית דחש לה להא דרבי עקיבא קסבר במשמתנא פליגי","אמר רבי אילא אמר רב נדהו בפניו אין מתירין לו אלא בפניו נדהו שלא בפניו מתירין לו בין בפניו בין שלא בפניו","אמר רב חנין אמר רב השומע הזכרת השם מפי חבירו צריך לנדותו ואם לא נידהו הוא עצמו יהא בנידוי שכל מקום שהזכרת השם מצויה שם עניות מצויה","ועניות כמיתה שנאמר (שמות ד יט) כי מתו כל האנשים ותניא כל מקום שנתנו חכמים עיניהם או מיתה או עוני","אמר רבי אבא הוה קאימנא קמיה דרב הונא שמעה להך איתתא דאפקה הזכרת השם לבטלה שמתה ושרא לה לאלתר באפה ש''מ תלת ש''מ השומע הזכרת השם מפי חבירו צריך לנדותו וש''מ נידהו בפניו אין מתירין לו אלא בפניו וש''מ אין בין נידוי להפרה ולא כלום","א''ר גידל אמר רב תלמיד חכם מנדה לעצמו ומיפר לעצמו פשיטא מהו דתימא אין חבוש מתיר עצמו מבית האסורין קמ''ל","היכי דמי כי הא דמר זוטרא חסידא כי מחייב בר בי רב שמתא משמית נפשיה ברישא והדר משמת בר בי רב וכי עייל לביתיה שרי לנפשיה והדר שרי ליה","ואמר רב גידל א''ר"],[[1,"קסבר במשמתנא פליגי","דהכא משמתנא קאמר וקאמר ליה רב חסדא לית דחש לה להא דר\"ע דהוה אוסר במנודה אני לך דהיינו משמתנא:"],[2,"נידהו בפניו","חכם שנידה את האדם בפניו אין יכול להתיר לו אלא בפניו:"],[3,"הזכרת השם","שמוציא שם שמים לבטלה:"],[4,"שנאמר כי מתו כל האנשים","ואמרינן היינו דתן ואבירם שנפלו בעניות:"],[4,"כל מקום שנתנו חכמים עיניהם","לאדם שנידו או מת או נופל בעניות ואהכי צריך לנדותו כדי שיפול בעניות דהיינו כמיתה:"],[5,"אין בין נידוי להפרה ולא כלום","דלא צריך להיות יום או יומים בנידוי דהא לאלתר שרא לה:"],[7,"היכי דימי","דמנדה לעצמו:"],[7,"ועייל לביתיה ושרי ליה","שלא נידהו בפניו:"]],[[0,"במאי פליגי במנודה אני לך דר\"ע סבר לישנא דנדינא הוא","שיהא נע ונד ומרוחק מהנאתו דאין לספקו בלשון נידוי ולענין הרחקת ד' אמות אף על גב דלשון המשנה קורא מנודה שנדוהו כדאמרי' מ\"ק (דף טו:) מנודה לא שונה ולא שונין לו מכל מקום כשאדם רוצה להרחיק עצמו ד' אמות אינו רגיל להזכיר נידוי על עצמו בשביל כך הלכך על כרחך לישנא דנדינא הוא כדפי' ושפיר הוי ידים מוכיחות בלא שאני אוכל לך:"],[2,"נדהו בפניו אין מתירין לו אלא בפניו","יש לפרש דשפיר מועיל גם שלא בפניו אלא לכבודו של מנודה דכמו שביישו לפניו כך יש לפייסו לפניו אע\"פ שנדהו בדין אי נמי בעי למימר דכיון שנדוהו בפניו אלים הנידוי כל כך שלא יועיל ההיתר אלא בפניו כעין שנדהו ודכוותה אמרינן בגיטין (דף לג:) כל מילתא דמתאמרא בפני י' צריכא בי י' [למשלפא]:"],[3,"אם לא נדהו הוא בעצמו יהא בנידוי","כלומר חכמי הדור חייבין לנדותו:"],[3,"שכ\"מ שהזכרת השם מצויה עניות מצויה","פי' הרב אלעזר דנפקא לן מדכתיב (שמות כ׳:כ״א) בכל מקום אשר אזכיר את שמי אבא אליך וברכתיך מדהזכרת שם דמצוה גורם ברכה דהיינו עושר א\"כ הזכרת שם דלבטלה גורם עניות ור\"י פי' דנפקא לן מדכתיב גבי שבועת שקר (זכריה ה׳:ד׳) ובא אל בית הגנב וכלתו ואת עציו ואבניו והזכרת השם לבטלה דומה קצת לשבועת שקר:"],[4,"עניות כמיתה דכתיב כי מתו כל האנשים המבקשים את נפשך","גבי דתן ואבירם דע\"כ לא מתו אז במצרים שהרי היו במדבר וליכא למימר שהיו סומין ומצורעים החשובים כמתים סומין ליכא למימר דכתיב (במדבר ט״ז:י״ד) העיני האנשים ההם תנקר ומצורעים נמי לא שהרי היו בקרב ישראל וליכא למימר שנתרפאו במתן תורה שהרי חזרו למומן במעשה העגל וליכא למימר שלא היו להם בנים דהא כתיב (שם) (הם) ונשיהם ובניהם וטפם ועוד דמשום שלא היו להם בנים לא נמנעו מלהיות קרובים למלכות כבתחילה אבל בשביל עניות ודאי נמנעו מלהיות קרובים למלכות:"],[5,"אין בין נידוי להפרה ולא כלום","תימה דאמרי' במ\"ק (דף טז.) טוט אסר וטוט שרי פי' לאלתר ה\"מ לענין מנודה אבל לענין אפקירותא עד דחייל עליה שמתא תלתין יומין וי\"ל ה\"נ כיון שנידוי זה אינו אלא לכפרה בעלמא וחיישי' עליו שלא ירגיל עוד להזכיר שם שמים לבטלה אין זה נידוי חשוב כאפקירותא לשאר עבירות לחול עליו נידוי שעה אחת:"],[7,"משמת נפשיה והדר משמת בר בי רב","פר\"ת שזה היה עושה כדי שלא ישכח להתיר הנידוי של בר בי רב אבל עכשיו שמשמת נפשיה מתוך כך שהיה זכור להתיר שלו זכור יהיה נמי להתיר של בר בי רב ור\"י פירש דלכפרה היה עושה כך שלא יענש במה שמנדה צורבא מדרבנן כי בקושי יש לנדותו כדאמרינן (בפסחים נב.) ממנו אנגידא ולא ממנו אשמתא ואע\"פ שזה היה מתחייב שמתא מן הדין אעפ\"כ היה ירא מן העונש לכך היה משמת נפשיה לכפרה:"],[7,"משמת נפשיה","היה מרחיק עצמו ד\"א מחביריו:"],[7,"כי עייל לביתיה שרי לנפשיה","משום בני ביתיה והדר שרי לבר בי רב כדי שיבא זכאי ויכפר על החייב לכך היה מתיר לעצמו קודם:"]]],[["מנין שנשבעין לקיים את המצוה שנאמר (תהילים קיט קו) נשבעתי ואקיימה לשמור משפטי צדקך","והלא מושבע ועומד מהר סיני הוא אלא הא קמ''ל דשרי ליה לאיניש לזרוזי נפשיה","ואמר רב גידל אמר רב האומר אשכים ואשנה פרק זה אשנה מסכתא זו נדר גדול נדר לאלהי ישראל והלא מושבע ועומד הוא ואין שבועה חלה על שבועה מאי קמ''ל דאפי' זרוזי בעלמא היינו דרב גידל קמייתא","הא קמ''ל כיון דאי בעי פטר נפשיה בקרית שמע שחרית וערבית משום הכי חייל שבועה עליה","א''ר גידל א''ר האומר לחבירו נשכים ונשנה פרק זה עליו להשכים שנאמר (יחזקאל ג כב-כג) ויאמר אלי (בן אדם) קום צא אל הבקעה ושם אדבר אותך ואצא אל הבקעה והנה שם כבוד ה' עומד","אמר רב יוסף נידוהו בחלום צריך י' בני אדם להתיר לו והוא דתנו הלכתא אבל מתנו ולא תנו לא ואי ליכא דתנו הלכתא אפילו מתנו ולא תנו","ואי ליכא ליזיל וליתב אפרשת דרכים ויהיב שלמא לבי י' עד דמקלעי ליה עשרה דגמרי הלכתא","א''ל רבינא לרב אשי ידע מאן שמתיה מהו דלישרי ליה אמר ליה לשמותיה שויוה שליח למישרי ליה לא שויוה שליח","אמר ליה רב אחא לרב אשי שמתיה ושרו ליה בחלמיה מאי א''ל כשם שאי אפשר לבר בלא תבן"],[[1,"קא משמע לן דשרי ליה לאינש","לישבע כדי לזרז עצמו לקיים את המצוה:"],[2,"והלא מושבע ועומד מהר סיני","דכתיב ושננתם (דברים ו) דצריך אדם לשנות בתורה לישנא אחרינא והלא מושבע ועומד מהר סיני דכתיב (יהושע א׳:ח׳) לא ימוש ספר התורה הזה וגו':"],[3,"כיון דאי בעי פטר נפשיה בקרית שמע שחרית וערבית","דכיון דקרא ק\"ש קיים לא ימוש דא\"ר שמעון בן יוחי במסכת מנחות (דף צט:) כל הקורא קרית שמע שחרית וערבית הרי זה קיים מצות לא ימוש וכיון דאי בעי פטר נפשיה מושננתם בקרית שמע דיוצא בה ידי חובתו מאותה שבוע' דהר סיני משום הכי כי אמר אשנה פרק זה (אע\"ג) דלא הוי מושבע בהכי דכבר פטר נפשיה ואהכי חל עליה שבועה:"],[4,"והנה שם כבוד","אלהי ישראל עומד:"],[5,"תנו","גמרא:"],[5,"מתנו","משנה:"],[6,"יהיב שלמא לבי עשרה","וכד מתיבין ליה הוו מתירין ליה נדויו:"]],[[0,"","ה על ידו:"],[1,"מושבע ועומד מהר סיני הוא","קא ס\"ד נשבעין לקיים מצוה דקאמר היינו לחייב משום שבועת ביטוי אם לא [יקיים] ותימה אדפריך לרב גידל תקשי ליה קרא דנשבעתי ואקיימה ופי' בתוס' דאה\"נ וי\"ל דקרא איכא לקיומי במצוה דאפשר ליפטר ממנה כמו באשנה פרק זה אבל לרב גידל ע\"כ מיירי במצות שמחויב לעשות דאל\"כ מאי קמ\"ל וגם היינו דרב גידל בתרייתא לכך פריך אדרב גידל ומשני קמ\"ל דשרי לזרוזי נפשי' פירוש ולא מיתסר משום דמוציא שם שמים לבטלה אבל לא מיירי לענין שבועת ביטוי כך פי' בתוס' ובפי' הר\"ר אליעזר פי' הא דפריך מושבע ועומד מהר סיני הוא היינו כלומר אם בא להשמיענו שמותר לישבע לקיים מצוה ולא חיישינן שמא יעבור על שבועתו ולא יקיים אי נמי לא מקיים לא עבר על שבועתו דמושבע - ועומד מהר סיני ואין שבועה חלה על שבועה ומשני הא קמ\"ל דשרי לזרוזי נפשיה ולא מיתסר משום הוצאת ש\"ש לבטלה כדפרי' מיהא מה דפי' מושבע ועומד מהר סיני וכו' [משמע] דאכללא דגופא דמילתא פריך הלא מושבע ועומד וכו' כפי' לפירוש ראשון משום דס\"ד לענין שבועת ביטוי פריך:"],[2,"האומר אשנה פרק זה וכו' נדר גדול נדר לאלהי ישראל","לכאורה משמע שאמר לשון זה ולא הזכיר שבועה וקמ\"ל דיש יד לשבועה אי נמי כדפירש הר\"ר אליעזר דהוי נדר כמו נדר דצדקה וקשה דא\"כ מאי פריך לקמן מאי קמ\"ל לזרוזי נפשיה היינו דרב גידל קמייתא מה ענין זה לרב גידל קמייתא כיון שלא הזכיר שבועה ועוד דטובא קמ\"ל דהכא הוי יד לשבועה לכ\"נ לפרש דאיירי שהזכיר שבועה מפיו שאמר שבועה שאשנה פרק זה ופריך מעיקרא והלא מושבע ועומד וכו' וא\"כ ליכא לחיוביה משום שבועת ביטוי דכי היכי דאין שבועה חלה על שבועה ה\"נ אין נדר חל על נדר ואי קמ\"ל דשרי לזרוזי אנפשיה לקיים המצוה היינו דרב גידל קמייתא ומשני הא קמ\"ל כיון דאי בעי פטר נפשיה וכו' כלומר לעולם לענין לחייבו משום שבועת ביטוי אם יעבור וכי תימא מושבע וכו' דאי בעי פטר נפשיה וכו' וא\"כ אפשר ליפטר ממצוה זו חיילא עליה שבועה לחייבו משום ביטוי אם יעבור כמו בשבועה דדבר הרשות והא דתנן בשבועות נשבע לקיים המצוה ולא קיים פטור דוקא במצוה שאי אפשר ליפטר ממנה כמו להניח תפילין ליטול לולב אבל האי דאי בעי פטר נפשיה חייל שבועה עילויה וה\"ה דאם נשבע שלא לשנות פרק זה [דאין] חייב משום שבועת ביטוי ושייך התרה ולא חשיב נשבע לבטל המצוה וא\"ת א\"כ הא דתנן בשבועות (דף כה.) נשבע שבועה שלא אתן שחייב משום שבועת ביטוי ופריך בגמרא אילימא שלא אתן לעני מושבע ועומד וכו' וכי מושבע לתת לכל עני ועני מתנה ומאי דוחקיה לשנויי התם בעשיר ויש לומר דמשמע ליה שלא אתן כלל מדלא פירש והא ודאי מזה מושבע וכו' ליתן לעני הצריך לפרנס והוה מצי לשנויי שלא אתן לעני מנה אבל תירוץ פשוט לקח לו דמיתוקמא ביה שלא אתן כלל כדמשמע המשנה:"],[4,"עליו להשכים","פירוש על האומר לחבירו להשכים כמו שמצינו ביחזקאל שאמרה לו שכינה והקדים שכינה על ידו:"],[5,"צריך עשרה ב\"א להתירו לו","לפי שחלום הוי כעין נבואה יש לו לדאוג מן הפורענות לכן צריך להתירו בעשרה ואז הוא מותר באותו ב\"ד שנידוהו דאכל בי עשרה שכינה שריא (עיין לשון הרא\"ש):"],[5,"והוא דמתנו","לאחרים הלכתא הלכה למשה מסיני אותן ראוין לשרות שכינה ביניהם ואי ליכא דמתנו אפי' תנו לעצמן ולא לאחרים:"],[6,"ואי לא אזיל לפרשת דרכים ויהיב שלמא לבי עשרה","כי היכי דליהדרי ליה שלמא ומועיל לו לתלות לו להגין לו מן היסורין. עד דמיקלעי עשרה דגמירי הלכתא ויתירו לו הנידוי אבל ליכא לפרש עד דמיקלעי עשרה דמתנו הלכתא ויהיב להו שלמא א\"כ למה חזר והזכיר עשרה גבי עד דמיקלעי היה לו לומר דמקלעי דמתנו ואנן ידעינן דאאותן כבר דיהיב שלמא קאי אלא ש\"מ כדפרישית והא דנקט פרשת דרכים יש לפרש ששם רגילות למצוא עשרה ב\"א יחד יותר מבעיר מיהו יש לפרש דאפי' בזה אחר זה מועיל ומ\"מ נקט פרשת דרכים לפי ששם רגילות ליתן שלום לבני אדם:"],[8,"כשם שלא אפשר לבר בלא תבן וכו'","וכן פ' דריש ליה מהאי קרא האיש אשר אתו חלום יספר חלום ואשר אתו דברי אמת יאמר דברי אמת כי מה לתבן את הבר וגו':"]]],[["כך אי אפשר לחלום בלא דברים בטלים","רבינא הוה לה נדרא לדביתהו אתא לקמיה דרב אשי אמר ליה בעל מהו שייעשה שליח לחרטת אשתו אמר ליה אי מכנפין אין אי לא לא","שמע מינה תלת שמע מינה בעל נעשה שליח לחרטת אשתו ושמע מינה לא שרי למישרי נדרא באתרא דרביה ושמע מינה כי מכנפין שפיר דמי","ושמתא אפילו באתרא דרביה ויחיד מומחה שרי שמתא","אמר רבי שמעון בר זביד אמר רב יצחק בר טבלא אמר רבי חייא אריכא דבי רבי אחא אמר רבי זירא אמר רבי אלעזר אמר רבי חנינא אמר רבי מיאשה משמיה דרבי יהודה בר אילעאי מאי דכתיב וזרחה לכם יראי שמי (שמש צדקה וגו') אלו בני אדם שהן יראין להוציא שם שמים לבטלה שמש צדקה ומרפא אמר אביי שמע מינה חירגא דיומא מסי","ופליגא דרבי שמעון בן לקיש דאמר אין גיהנם לעולם הבא לא הקדוש ברוך הוא מוציא חמה מנרתיקה צדיקים מתרפאין בה ורשעים נידונין בה שנאמר וזרחה לכם יראי שמי שמש וגו' ולא עוד אלא שמתעדנין בה שנאמר ויצאתם ופשתם כעגלי מרבק","והרשעים נידונין בה שנאמר הנה יום בא בוער כתנור וגו':"],[[0,"כך אי אפשר לחלום בלא דברים בטלים","ושמא הא דשרו ליה דברים בטלים הוו:"],[1,"הוה ליה נדרא לדביתהו","ואיהו לא הפיר לה בו ביום ששמע:"],[1,"אי מיכנפין","תלתא מומחין דשרו ליה שפיר דמי:"],[2,"לא שרי למישרי נידרא באתרא דרביה","משום הכי לא בעי רבינא למישרא לה מקמיה רביה:"],[3,"ויחיד מומחה שרי שמתא","דלא בעי עשרה כמו לנידוי:"],[4,"יראי שמי","למי שיראין להוציא שם שמים:"],[4,"חירגא","זיהרא דשימשא והיינו לא (יומא ב:) דכתיב וכל דארי ארעא כלא חשיבין:"],[4,"מסי","מרפא כדכתיב שמש צדקה ומרפא:"],[5,"צדיקי' מתרפאין בה","באותו השמש דלע\"ל אבל בהאי שמש לית ביה רפואה:"],[6,"ולהט אותם היום הבא","שמש של אותו יום:"]],[[1,"רבינא ה\"ל נדרא לדביתהו אתא לקמיה דרב אשי","שיתיר לה נדרה ומיירי בנדרי' שאין בהן עינוי נפש לכך לא היה יכול להפר אי נמי כשקיים לה הנדר מיהו למ\"ד (לקמן נדרים דף סט.) [אין] נשאלין על ההיקם צריך לומר כפירוש ראשון ועתה אשתו אמרה ליפתח בחרטה לנדרה כדי שיאמרו לרב אשי:"],[1,"מהו שיעשה שליח לחרטת אשתו","להביא חרטת אשתו לפני חכם כדי להתיר לה נדרה:"],[1,"אמר ליה אי מיכנפי אין ואי לא לא","כלומר שאינו מוצא ג' מזומנים ומכנפי אלא צריך לחזור אחריהם לא וצ\"ע טעמא מאי ופר\"י דחיישינן שמא מתוך שהוא טרוד לטרוח לחזר אחריהם לכנופייהו שמא ישכח מדברי הפתח והחרטה שאמרה לו אשתו וישנה דבורה ויוסיף עליה כדי ליישב החרטה יפה יפה:"],[2,"ש\"מ לא שרי נדרא באתרא דרביה","מדלא הוה רבינא שרי לאשתו נדרה ובהתרת חכם וא\"ת דלמא דהיינו משום דס\"ל לרבינא כרבי יהודה דאמר במס' נגעים (פ\"ב) כל הנדרים אדם מתיר חוץ מנדרי אשתו שבינה לבין אחרים וי\"ל דמ\"מ היה מוצא שפיר ג' שהיו מתירין לה בביתו ויהיה שרי למשרי אלא הוה באתריה דרביה:"],[2,"וש\"מ כי מכנפין שפיר דמי","פי' לעשות שליח לחרטת אשתו וש\"מ לכנופי לא וש\"מ שמתא אפי' באתרא דרביה שפיר דמי להתיר השמתא דפעמים שלא יהא הרב מזומן או לא יהיה פנוי ואין לדחות היתר השמתא דודאי גבי נדר אין חשש כל כך אם יבא לדחות ההיתר ויהיה נדרו עליו עד שיהיה הרב מזומן להתיר אבל שמתא אין להשהות על האדם:"],[3,"ויחיד מומחה שרי שמתא","אגב דאיירי בשמתא מסיק להא דיחיד מומחה שרי שמתא ולא בעי עשרה ולא למעוטי נדר דבנדר נמי מועיל יחיד מומחה להתיר והקשה רשב״ם דמאי קאמר אי מכנפי אין דמשום דצריך ג' להתיר הנדר והלא רב אשי לבדו יכול להתירה שהרי רב אשי היה מומחה כדמוכח פרק כל פסולי המוקדשין (בכורות דף לו:) שהרי מתיר הבכור לבדו ואמר לשם על ג' מתירין הנדר במקום שאין מומחה וי״ל דרבינא שאל לו סתמא מהו שיעשה שליח לחרטת אשתו ולא פירש אם להתיר ביחיד מומחה או בשלשה הדיוטות על כן השיב לו רב אשי דלענין ג' אי מיכנפי כו' אי נמי שמא י״ל אע״ג דרב אשי היה מתיר הבכור לבדו היינו משום דמומחה דבעינן גבי בכור היינו גמיר אפי' בלא סמיכה כמו שפירש בבכורות אבל במומחה דבעינן בהיתר נדרים היינו מומחה בסמיכה דומיא דראשי המטות כך נראה להרי״ף נ״ע מיהו קשה לרשב״ם דמה שייך ענין זה דנדרים כאן בפירקא דמיירי בשמתא אבל לא בנדרים לקמן בפרק ארבעה נדרים הוה ליה לאיתויי דהתם מיירי במילי דנדרים ועוד כיון שיכול החכם להתיר הנדר שלא בפני הנודר ע״י שליח כדקאמר הכא שהבעל נעשה שליח לחרטת אשתו א״כ מאי קאמר בפרק השולח (גיטין דף מו.) אין אדם רוצה שתתבזה אשתו בב״ד בנדר שצריך חקירת חכם פירוש שתתבזה במה שתלך לפני חכם להתיר והלא יכולה לעשות שליח בב״ד להתירה ומה בזיון יהא לה אם יתירו לה בב״ד ע״י שליח לב״ד לכן נראה לרשב״ם דגרס הכא רבינא הוה ליה נידוי לדביתהו פי' שנידוה בחלום והיתה בושה לבוא לב״ד לפני רב אשי להתיר לה וגרס מהו שיעשה שליח לאשתו להתיר לה נידוי מי מדמי לנידוהו בפניו דאין מתירין לו אלא בפניו דבפניה נידוה בחלום או דלמא כיון שלא נידוה אלא בחלום כשלא בפניו דמי ומתירין לו שלא בפניו והשיב לו רב אשי אי מכנפי העשרה מתירים לו ע״י שליח שלא בפניו דמסתייעא מילתא כיון שמצאן מזומנין ומכונפין ואי לאו שלא מצאן מזומנין ומכונפין וצריך לחזור אחריהם לא. פי' לא יתירו ע״י שליח אבל ודאי ע״י מנודה עצמו יועיל אפי' ע״י חיזור:"],[4,"אלו בני אדם שיראים להזכיר שם שמים לבטלה","שמש להם צדקה ומרפא בעוה\"ז קאמר מדמסיק עלה ש\"מ הדין חירגא דיומא מסי חירגא היינו עפרורית הבאה בזריחת השמש:"],[4,"חירגא דיומא מסי","תימה מאי רפואה יש בו ושמא מרפא כשמסתכלין בו קאמר אי נמי לחולה קאמר כדאמרינן בבבא בתרא (דף טז:) אידלי חמה אידלי קצירא:"],[5,"ופליגא דרשב\"ל","פירוש הא דאוקימנא קרא דמרפא בכנפיה בעוה\"ז פליג אדרשב\"ל ומוקי לה ברפואה בעוה\"ב ומיהו גם רשב\"ל מודי הא דאמרי אינשי אידלי חמה אידלי קצירא אך לא מן הפסוק:"]]],[["\u0001מתני׳\u0002 כנדרי רשעים נדר בנזיר ובקרבן ובשבועה. כנדרי כשרים לא אמר כלום כנדבותם נדר בנזיר ובקרבן","\u0001גמ׳\u0002 ודלמא הכי קאמר כנדרי רשעים לא נדרנא אמר שמואל באומר כנדרי רשעים הריני עלי והימנו הריני בנזירות עלי בקרבן הימנו בשבועה","הריני נזירות דלמא הריני בתענית קאמר אמר שמואל כשהיה נזיר עובר לפניו","(עלי בקרבן) הימנו בשבועה דלמא הימנו דאכילנא קאמר אמר רבא דאמר הימנו שלא אוכל","אי הכי מאי למימרא מהו דתימא הא לא מפיק שבועה מפומיה קא משמע לן הדין","כנדרי כשרים לא אמר כלום כנדבותם נדר וכו' מאן תנא דשאני ליה בין נדר לנדבה לימא לא רבי מאיר ולא רבי יהודה","דתניא טוב אשר לא תדור וגו' (קהלת ה) טוב מזה ומזה שאינו נודר כל עיקר דברי רבי מאיר רבי יהודה אומר טוב מזה ומזה נודר ומשלם","אפילו תימא רבי מאיר"],[[0,"מתני' כנדרי רשעים","כגון שהיה ככר מונח לפניו ואמר כנדרי רשעים משמע דאותו ככר יהא עליו כנדרי רשעים וכיון דאמר הכי נדר בנזיר ובקרבן ובשבועה ואם אכלו מחייב נזירות וקרבן ושבועה דחייב נמי קרבן שבועה דדרכן של רשעים הוא שנודרים בנזירות ובקרבן ונשבעין והאי כי אמר כנדרי רשעים הוי כמאן דאמר הריני נזיר אם אוכל הימנו והרי עלי כקרבן ושבועה שאיני אוכל:"],[0,"אבל אמר כנדרי כשרים לא אמר כלום","שאין דרכן של כשרים שנודרים כדמפרש וכל שכן דאין נשבעין ואהכי לא אמר כלום ולא מיתסר בהאי ככר:"],[0,"אבל אמר כנדבותם של כשרים","ואכלו חייב בנזיר ובקרבן אבל לא בשבועה דכשרים עבידי דמתנדבין בנזירות ובקרבן בדרך נדבה אבל בשבועה אין נשבעין כלל משום הכי אינו חייב משום שבועה:"],[1,"גמ' ודלמא הכי קאמר כנדרי רשעים לא נדרנא","כיון דאיהו לא מפרש מידי דלא אמר הרי הוא עלי כנדרי רשעים אלא בסתם קאמר דלמא ה\"ק כנדרי רשעים לא נדרנא ולא כלום הוא:"],[1,"אמר רבא באומר","כגון שהיה ככר לפניו ואמר כנדרי רשעים הריני עלי והימנו ומשתמע דה\"ק הריני בנזירות דמאן דנזר ה\"ק הריני נזיר והא דאמר עלי משמע דאמר הרי עלי קרבן והימנו משמע דאמר שבועה שלא אוכל הימנו דהואיל דאמר בתחלה כנדרי רשעים משתמע ודאי דהכי בעי למימר דדרכן של רשעים הוא דאגב ריתחייהו נודרין בנזיר ובקרבן ובשבועה:"],[2,"ודלמא","הא דאמר הריני בתענית משמע ולא בנזירות:"],[3,"ודלמא","הא דאמר הימנו לא משמע שלא אוכל הימנו אלא שבועה שאוכל ממנו וכי אכיל מיניה לא מחייב משום שבועה:"],[4,"אי הכי","כיון דאמר בפירוש שלא אוכל מאי למימרא ודאי לא מיבעיא למיתנא דחייב משום שבועה כי אכיל מיניה:"],[4,"הא לא מפיק שבועה","דלא אמר בפירוש שבועה שלא אוכל אפ\"ה אמרינן ודאי שבועה קאמר:"],[5,"דשני ליה בין נדר לנדבה","דקתני כנדרי כשרים לא אמר כלום וכי אמר כנדבתם. של כשרין הוי נדי. ומשמע דנדר אסור אבל נדבה מותרת:"],[6,"דתניא טוב אשר לא תדור טוב מזה ומזה","דהכי דריש ר' מאיר לקרא את אשר תדור שלם טוב אשר לא תדור משתדור ולא תשלם (טוב אשר לא תדור ומשתדור ולא תשלם) וטוב שאינו נודר כל עיקר מזה שנודר ואינו משלם ואפי' מזה שנודר ומשלם:"],[6,"ר' יהודה אומר טוב מזה ומזה נודר ומשלם","דמשמע ליה לר' יהודה דהאי טוב קאי אקרא דלקמיה הכי דריש ליה את אשר תדור שלם טוב אותו שנודר ומשלם טוב מאשר לא תדור ומשתדור ולא תשלם והיינו דלא כר' יהודה ודלא כר' מאיר דאמר טוב שאינו נודר כל עיקר דסבר בין בנדר בין בנדבה אסור ליה לאיניש למידר ואילו ר\"י דאמר שנודר ומשלם טוב לא מפליג בין נדר לנדבה דאפילו בנדר שפיר דמי.:"]],[[0,"כנדרי כשרים לא אמר כלום","פי' ה\"ר אליעזר שאפי' הזכיר קונם בהדיא עם כנדרי כשרים אפ\"ה לא אמר כלום כיון דכשרים לא נדרי וצריך עיון:"],[0,"כנדבתם נדר בנזיר ובקרבן","דכשרים מתנדבים שפיר בנזיר ובקרבן כדאמרינן בגמ' אבל שבועה לא משתבעי כשרים כלל משום מוציא ש\"ש לבטלה:"],[1,"כנדרי רשעים הריני עלי והימנו","א' מלשונות הללו אם כנדרי רשעים עלי בקרבן דעלי שייך גבי קרבן כדאמרינן לעיל הרי הוא עלי אסור מפני שהוא יד לקרבן והלכך כי אמר כנדרי רשעים עלי נדר בקרבן ופירש הר\"ר אליעזר דאסר עליו בקונם וקשה דמי ידעינן מה בא לאסור עליו ויש לומר דמיירי שהיה ככר לפניו ואמר כנדרי רשעים עלי א\"כ אההוא ככר שלפניו קאמר אי נמי מיירי במסרבין בו לאכול וקשה דמאי איריא משום כנדרי רשעים אפי' בעלי גרידא הוי יד לקרבן כדאמר לעיל ואי משום דלא פירש בככר זו וכן לא פירש חבירו השתא נמי לא מפרש אלא אמרי' דכיון דככר לפניו או מסרבין בו לאכול הוי יד כדמפרש והלכך בלא נדרי רשעים נמי וע\"ק מאי קאמר כנדבתם נדר בקרבן כיון שלענין קונם קאמר וכי דרך כשרים לאסור עצמם במותר להם לכך נראה לרשב\"ם דנדר בקרבן דקאמר היינו בקרבן ממש אם הביא קרבן כל דהו לזבוח והשתא ניחא דעלי גרידא לא מחייב להביא קרבן דהא דעלי יד לקרבן היינו דוקא לענין קונמות ונדבות ניחא כדקאמר הכא בסמוך וא\"ת דלמא עלי לצדקה לבדק הבית קאמר וי\"ל דא\"כ היה לו לפרש בהדיא ועוד מדקאמר כנדרי רשעים מסתמא אנדרי הפסוק לרשע וחוטא קאי דכתיב אשר לא תדור וקרא בקרבנות ממש איירי בתוספתא:"],[1,"הימנו שבועה","הכא ודאי מיירי בככר לפניו ואמר כנדרי רשעים הימנו דנדר בשבועה שלא יאכל הימנו:"],[1,"הריני בנזירות","כמו אמר מר ודלמא הריני בתענית קאמר ושפיר הוי כנדרי רשעים דכל היושב בתענית נקרא חוטא ומיהו קשה דהא אפ\"ה נקרא קדוש וי\"ל דהכא לשמואל קאמינא ובפ\"ק דתענית (דף יא.) סבר שמואל כמ\"ד נקרא חוטא ועוד תירץ הר\"ר אליעזר דאפי' למאן דאמר נקרא קדוש ה\"מ כשקובע זמנו דמפרש מחר או יום אחר אבל כיון שאומר הריני בתענית ואינו מפרש אימת וא\"כ אינו מקבל תענית רק שירצה לקבוע יום הוי כנדרי רשעים לכך נראה דשמא יאחר נדר יותר מדאי או שמא לא יעשנו כלל:"]]],[["כי קאמר רבי מאיר בנדר בנדבה לא קאמר והא קתני כנדבותם, נדר בנזיר ובקרבן תני נדב בנזיר ובקרבן","מאי שנא נודר דלא דלמא אתי בה לידי תקלה נדבה נמי לא דלמא אתי בה לידי תקלה","כהלל הזקן דתניא אמרו על הלל הזקן שלא מעל אדם בעולתו כל ימיו מביאה כשהיא חולין לעזרה ומקדישה, וסומך עליה ושוחטה","הניחא נדבה דקרבנות נדבה דנזירות מאי איכא למימר סבר לה כשמעון הצדיק","דתניא אמר (רבי) שמעון הצדיק מימי לא אכלתי אשם נזיר טמא אלא אחד פעם אחת בא אדם אחד נזיר מן הדרום וראיתיו שהוא יפה עינים וטוב רואי וקווצותיו סדורות לו תלתלים אמרתי לו בני מה ראית להשחית את שערך זה הנאה","אמר לי רועה הייתי לאבא בעירי הלכתי למלאות מים מן המעיין ונסתכלתי בבבואה שלי ופחז עלי יצרי ובקש לטורדני מן העולם אמרתי לו רשע למה אתה מתגאה בעולם שאינו שלך במי שהוא עתיד להיות רימה ותולעה העבודה שאגלחך לשמים","מיד עמדתי ונשקתיו על ראשו. אמרתי לו בני כמוך ירבו גוזרי נזירות בישראל עליך הכתוב אומר איש כי יפליא לנדור נדר נזיר להזיר לה'","מתקיף לה רבי מני מאי שנא אשם נזיר טמא דלא אכל דאתי על חטא כל אשמות נמי לא ליכול דעל חטא אתו","אמר ליה רבי יונה היינו טעמא כשהן תוהין נוזרין וכשהן מטמאין ורבין עליהן ימי נזירות מתחרטין בהן ונמצאו מביאין חולין לעזרה","אי הכי אפילו נזיר טהור נמי נזיר טהור לא דאמודי אמיד נפשיה דיכול לנדור","ואיבעית אימא"],[[0,"כי קאמר ר\"מ בנדר","אסור בלשון נדרים דוקא קאמר:"],[0,"אבל בנדבה לא אמר","והיינו מתני' דקתני כנדבתם דכשרין נדרי בלשון נדבה:"],[0,"והא קתני כנדבותם נדר כו'","דמשמע דבלשון נדר קאמר:"],[1,"דלמא אתי בה לידי תקלה","דכי אמר בל' נדר הרי עלי קרבן אתי בה לידי תקלה דעבר משום בל תאחר:"],[1,"נדבה נמי","כי אמר הרי זו קרבן אתי בהו לידי תקלה לידי גיזה ועבודה א] אבל בבל תאחר לא דכל היכא דאיתא בי גזא דרחמנא איתא:"],[2,"[כהלל]","מתני' דקתני נדבה מותר כגון דעביד כהלל דמקדישה בעזרה דחו לא אתי בה לידי מטילה:"],[3,"נדבה דנזירות מאי איכא למימר","היכי עביד דלא ליתי לידי תקלה דקתני נדב בנזיר דמותר דכשרים מתנדבים בנזירות:"],[3,"סבר לה כשמעון הצדיק","דמנזיר לשם שמים כאותו שבא לפני שמעון הצדיק:"],[4,"לא אכלתי אשם נזיר טמא","דנזיר שמיטמא מביא אשם ואח\"כ מונה ימי נזירות אחר ומאותו אשם לא אכל וטעמא מפרש לקמן:"],[4,"בא לפני אדם אחד","שבא להקריב קרבן נזירותו ולגלח שערו:"],[5,"ופחז יצרי עלי","מתוך שראיתי במים צורתי כל כך נאה נתגבר עלי יצרי ובקש להביאני לידי מעשים רעים לטורדני מן העולם:"],[6,"אמרתי לו","כך אמר בעצמו:"],[6,"עליך הכתוב אומר איש כי יפליא כו'","דהיינו לה' לשם שמים:"],[7,"דאתי על חטא","שטימא עצמו וכיון דאתי על חטא הוא א\"כ לא בעי למיכל שום קרבן חטאת אלא היינו טעמא דלא אכל אשם נזיר טמא:"],[8,"כשהן תוהין","מתפחדים כמו ופחדת לילה ויומם (דברים כ״ח:ס״ו) ומתרגמינן ותהית כשהן כועסין נודרין שאינן נודרים לשם שמים אלא לשם כעס מנזרין עצמי:"],[8,"וכשהן מטמאין","דאתא טומאה וסתרי להנהו יומי דנזירות ובעו למימני יומי נזירות אחר וריבה עליהן ימי טומאה דשמא מיטמא פעם אחרת ובעי למיסתר כל הני יומי דנזירות ומתחרטין בעצמן שנדרו וכיון דמתחרטין לא הוי נזירות לש\"ש ונמצאו מביאין חולין לעזרה ומשו\"ה לא אכל אלא מזה דודאי לש\"ש הוא דעבד:"],[9,"א\"ה אפי' נזיר טהור","דדלמא מתחרט על נזירותו ונמצא מביא חולין לעזרה:"],[9,"בנזיר טהור","ליכא למיחש דמתחרט דכיון דלא נטמא ולא רבו עליו ימי טומאה ודאי לא מתחרט ואי אמרת אפ\"ה הוא מתחרט דאינו יכול לעמוד בנזירותו להא ליכא למיחש דאי לאו דאמיד בנפשיה קודם שנדר דיכול לעמוד בו לא הוה נדר ולא מיתחרט כל היכא דלא נטמא:"]],[[0,"והא קתני כנדבתם","תימה מגופיה דמתני' תיקשי ליה דקתני כנדבתם והדר קתני נדר וי\"ל דאין ה\"נ ולשנויא ניחא הכל:"],[2,"כהלל הזקן שמביאין בעזרה","וא\"ת אכתי היכי קרי ליה נדבת כשרים הא ליכא שריותא כ\"א כהלל כשהבהמה בעזרה ומתני' משמע בכל ענין ועוד דהא תינח נדרי קרבן אבל נדרי דקונם כגון שאוסר ככר עליו התם לא שייך טעם זה ואומר הר\"ר אליעזר כיון דכשרים מתנדבים בשום צד בעזרה גם חוץ לעזרה נמי תפיס שפיר הנדבה בלשון זה ואף על גב דכשרים לא מתנדבים כה\"ג אבל נדרי כשרים לא הוו כלל בשום צד אף כשהיא בעזרה נמי איכא חששא שמא תמות ויהא חייב באחריות ואתי לידי תקלה דבל תאחר הלכך כנדרי כשרים לא אמר כלום:"],[3,"דנזירות מאי איכא למימר","והלא מיד שנדר קם ליה בבל יאכל ובבל ישתה ואיכא חששא לתקלה שמא יעבור ומשני כי ההיא דשמעון הצדיק דנדר נזירות לשם שמים מאהבה ולכך קרי ליה נדבה כדכתיב (שמות לה) כל נדיב לב וא\"ת והלא כל הכשרים שמתנדבים לשם שמים נודרין בלשון נדר [וא\"כ] כנדרי כשרים אמאי לא אמר כלום אף כי שמא זה אינו מתכוין לשם שמים תופס שפיר הלשון כיון שיש כשרים שנודרים נזירות לשם שמים מידי דהוה אנדבת כשרים דקרבן לפירוש הר\"ר אליעזר וכדפרישית לעיל וי\"ל דמ\"מ נדר כשר לא מיקרי כלל דנדר משמע מה שאדם נודר מדאגת יסורים מעונותיהם ולא מאהבת המקום אבל כשרים תופס שפיר דנדבה משמע מאהבה דכתיב (הושע יד) אהבם נדבה אלמא נדבה משמע מאהבה וכן בתוספ' קתני כנדבת רשעים לא אמר כלום לפי שאין הרשעים מתנדבין כלל ואע\"ג דכמה מתנדבים בלשון נדבה ואומרים הרי זו עולה מ\"מ לא מיקרי נדבה משום שאין עושין מנדבת לבם מאהבה רק מדאגת יסורים מעונותיהם כנדבת רשעים אינו קרויין נדבה לפי שאין עושין מאהבת המקום נדרי כשרים נמי אינו קרוי נדר כיון שאין עושין מדאגת יסורים אלא מאהבה (אלא) קרוי נדבה ולכך קרי נזירות כשרין נדבתם אע\"ג דבלשון נדר נמי דכל נזירות בלשון נדר הוא:"],[8,"כשהן תוהין נודרין","תוהין לשון ותוהא על הראשונות כלומר כשהן תוהין בעונותיהם ודואגין מן היסורין נודרין להגין מן היסורין וכשרבים עליהם ימי טומאה מתחרטין:"]]],[["אפילו תימא רבי יהודה כי אמר רבי יהודה בנדבה בנדר לא אמר","והקתני טוב מזה ומזה נודר ומקיים תני נודב ומקיים","מאי שנא נודר דלא דילמא אתי בה לידי תקלה נדבה נמי דילמא אתי לידי תקלה","רבי יהודה לטעמיה דאמר אדם מביא כבשתו לעזרה ומקדישה וסומך עליה ושוחטה","תינח נדבה דקרבנות נדבה דנזירות מאי איכא למימר","רבי יהודה לטעמיה דתניא רבי יהודה אומר חסידים הראשונים היו מתאווין להביא קרבן חטאת לפי שאין הקדוש ברוך הוא מביא תקלה על ידיהם מה היו עושין עומדין ומתנדבין נזירות למקום כדי שיתחייב קרבן חטאת למקום","רבי שמעון אומר לא נדרו בנזיר אלא הרוצה להביא עולה מתנדב ומביא שלמים מתנדב ומביא תודה וארבעה מיני לחמה מתנדב ומביא אבל בנזירות לא התנדבו כדי שלא יקראו חוטאין שנאמר וכפר עליו מאשר חטא על הנפש","אמר אביי שמעון הצדיק ורבי שמעון ורבי אלעזר הקפר כולן שיטה אחת הן דנזיר חוטא הוי שמעון הצדיק ורבי שמעון הא דאמרן","ורבי אלעזר הקפר ברבי דתניא רבי אלעזר הקפר ברבי אומר וכפר עליו מאשר חטא על הנפש וכי באיזו נפש חטא זה אלא שציער עצמו מן היין והלא דברים קל וחומר ומה זה שלא ציער עצמו אלא מן היין נקרא חוטא המצער עצמו מכל דבר, על אחת כמה וכמה מכאן כל היושב בתענית נקרא חוטא","והדין קרא בנזיר טמא כתיב משום דשנה בחטא הוא","\u0001מתני׳\u0002 האומר (לחבירו) קונם קונח קונס הרי אלו כינויין לקרבן חרק חרך חרף הרי אלו כינויין לחרם נזיק נזיח פזיח הרי אלו כינויין לנזירות שבותה שקוקה נודר במוהי הרי אלו כינויין לשבועה:","\u0001גמ׳\u0002 איתמר כינויין רבי יוחנן אמר לשון אומות הן רבי שמעון בן לקיש אמר לשון שבדו להם חכמים להיות נודר בו וכן הוא אומר בחדש אשר בדא מלבו","וטעמא מאי תקינו רבנן כינויין דלא לימא קרבן ולימא קרבן דילמא אמר קרבן לה' ולימא קרבן לה' דילמא אמר לה' ולא אמר קרבן וקא מפיק שם שמים לבטלה","ותניא רבי שמעון אומר"],[[0,"אפילו תימא רבי יהודה היא","מתני' דשני בין נדר לנדבה דלר' יהודה נמי שאני ליה וכי קאמר ר' יהודה טוב נודר ומשלם היינו דאמר בלשון נדבה אבל בנדר לא אמר:"],[2,"מ\"ש נדר דלא כו' דאתי בה לידי תקלה","כדלעיל:"],[5,"לפי שאין הקב\"ה מביא תקלה על ידייהן","(שאין באין) כלומר שהם מתייראים שלא יעשו שום חטא ורוצין להביא קרבן להתכפר עליהם לפי שאין הקב\"ה מביא תקלה על ידיהם מה היו עושין כדי שיתחייבו קרבן שאין מביאין קרבן חטאת אלא על חטא ממש ענין אחר לפי שאין הקב\"ה מביא תקלה על ידיהם שאין באין לידי שום תקלה ושום חטא שיתחייבו קרבן חטאת:"],[6,"אלא הרוצה להתנדב מתנדב ומביא שלמים וכו'","אבל חטאת לא אתי בנדבה ובנזירות נמי לא היו מתנדבין שלא יקראו חוטאים ומתני' דקתני נדר בנזיר דמשמע דכשרים נודרין בנזירות לאו ר' שמעון היא:"],[7,"כולן שיטה אחת","דבשיטה אחת משוו דעתייהו:"],[7,"דנזיר חוטא הוי","משום דנדר:"],[9,"והדין קרא בנזיר טמא כתיב","על שם שטימא את עצמו במת קאמר קרא אשר חטא על הנפש:"],[9,"משום דשנה בחטא הוא","דעל שם ששנה עצמו בחטא שנזר עצמו ועוד שטימא נזירותו להכי כתיב ביה אשר חטא על הנפש והוא הדין נמי לשאר נזירין דאיקרו חוטאים וגלי רחמנא בהאי והוא הדין לכולהו ואהכי גילה בהאי משום דזה שונה בחטא שני פעמים ותולין הקלקלה במקולקל:"],[10,"מתני' האומר קונם","שאמר קונם ככר זה עלי:"],[10,"חרק","האומר ככר זה עליך חרק או שאמר נזיק נזיח פזיח הריני נזיק אם אוכל ככר זה או שאמר נזיח הוי כאילו נדר בנזיר:"],[10,"שבותה","שלא אוכל ככר זה או שקוקה הרי אלו כינווים לשבועה והוי כאילו נשבע ממש:"],[10,"נדיר במוהי","כמו מומתא לשון שבועה:"],[11,"גמ' איתמר כינויין","דקתני במתני':"],[11,"רבי יוחנן אמר לשון אומות הן","דהכי משתבעי אומות וכי נדרי אז משתבעי משתעו בהני לשונות וישראל נמי כי אמר בהאי לישנא מיתסר דהתורה אמרה כי ידור בכל לשון דנדר:"],[11,"לשון שבדו להן חכמים","הני לשונות מצאו להם חכמים שיהו נודרין בהן:"],[12,"תקינו חכמים כינויין דלא לימא קרבן","בשם כדאמרינן בעלמא (עירובין ד' כא:) קודם שבא שלמה היתה תורה דומה לכפיפה שאין לה אזנים עד שבא שלמה ותיקן לה אזנים דכתיב איזן וחיקר תיקן משלים הרבה שגזר על השניות כי היכי דלא לפגעו באיסורא דאורייתא הכי נמי תקינו רבנן כינויין לנדרים דהנודר בהני כינויין כאילו נודר בקרבן עצמו וכן בכינוי דחרם וכגון נמי ושמרתם את משמרתי (ויקרא י״ח:ל׳) עשו משמרת למשמרתי כי היכי דלא ליתי למינדר בנדר דאורייתא דאתי למימר נמי קרבן לה' והיינו דתנן (אבות פ\"ג מי\"ג) נדרים סיג לפרישות שתיקנו אלו כינויין כדי להפריש האדם מן העבירה:"]],[[0,"","ואבע\"א כי קאמר ר' יהודה בנדר אבל בנדבה לא קאמר:"],[2,"נדבה נמי אתי לידי תקלה","ומשני ר\"י לטעמיה ה\"מ לשנויי כדלעיל אלא ניחא ליה לאתויי כרבי יהודה גופיה וכן בסמוך [גבי] נזירות מייתי מר' יהודה חסידים הראשונים וכו' מהאי טעמא אע\"ג דהוה מצי לשנויי כדלעיל:"],[3,"רבי יהודה אומר אדם מביא כבשתו בעזרה","ואם תאמר וללישנא קמא דאוקמינא פלוגתייהו בנדר ואפי' בנדר שרי ר' יהודה הא דקתני בהו אדם מביא כבשתו וכו' אלמא חייש רבי יהודה לתקלה ואפי' בנדבה לא שרי אלא בכה\"ג לכ\"ש בנדר דמיתסר וי\"ל דאיכא למימר עצה טובה קמ\"ל וא\"ת והא בתוספתא קתני ר' יהודה אמר טוב מזה ומזה ש\"מ דלענין איסורא קאמר וי\"ל דלעולם עצה טובה קמ\"ל הך ברייתא ולא משום איסורא קאמר ואיידי דאיירי ר\"מ טוב מזה ומזה דלענין איסור קאמר ר\"מ א\"ר יהודה נמי האי לישנא טוב מזה ומזה ולעולם לענין עצה טובה קמ\"ל ולא לענין איסור קא\"ל והשתא מסיק לישנא בתרא דנדרים אתי לכ\"ע אפי' לר' יהודה וכן ללישנא קמא אפי' לר\"מ בנדבה:"],[3,"אדם מביא כבשתו","מדנקט לשון נקיבה אלמא דבשלמים איירי ותימה דמאי תקלה שייך בשלמים והלא אין מעילה בשלמים וי\"ל דנהי דמעילה ליכא איסור דאורייתא מיהא איכא כדאמר בר\"ה (דף כח -) בשופר של שלמים לא יתקע ואם תקע לא יצא משום דאיסורא רכיב עליה:"],[7,"אמר אביי שמעון הצדיק כו'","תרוייהו אינם שוין ר\"ש איירי בנזיר טמא כדאמר לעיל ור' אליעזר הקפר איירי בטהור וי\"ל דאה\"נ ולהכי לא קאמר דבר אחד אלא שיטה א' דכולהו ס\"ל דנזיר חוטא טפי מרבנן דידהו וכה\"ג אמרי' בהמוכר את הספינה (דף עח:):"],[7,"כולן שיטה אחת הן","לאו דוקא שהרי שמעון הצדיק אין להוכיח דטעמא אינו אלא מפני שמתחרטין וכה״ג איכא בפרק רבן גמליאל (יבמות דף נא: ושם) כולהו סבירא להו מאמר קונה קנין גמור הר״ר יוסף זצ״ל כדפירש':"],[9,"דשנה בחטא","בצער של יין כי חוזר ומתחיל נזירות אי נמי שנה בחטא דיין ובטומאה:"],[10,"חרק חרך וכו'","אין לפרש משום דלשונות הללו נוטין קצת אחר לשון חרם אלא למאן דאמר לשון אומות נינהו דוקא [אבל] למ\"ד לשון שבדו חכמים [לא דא\"כ לתני נמי חרך חרט]:"],[11,"וכן הוא אומר בחדש אשר בדא מלבו","וכה\"ג לא אשכחן בעלמא:"],[12,"ה\"ג דלא לימא קרבן ולימא קרבן דלמא אמר קרבן לה' ונימא קרבן לה' דילמא אמר לה' ולא אמר קרבן","והאי טעמא שייך בכולהו [כמו] בנדרים כדאמר הש\"ס בנזיר דלא לימא לה' הריני נזיר כדכתיב נזיר להזיר לה' (במדבר ו׳:ב׳) וחרם דלא לימא לה' חרם דכתיב אשר יחרם איש לה' (ויקרא כ״ז:כ״ח) וכן שבועה דכתיב שבועת ה' תהיה וגו' (שמות כ״ב:י׳) ומשום דעיקר מכילתין בנדרים נקט לפרושי הכי בנדרים דוקא:"]]],[["מניין שלא יאמר אדם לה' עולה לה' מנחה לה' תודה לה' שלמים תלמוד לומר קרבן לה'","וקל וחומר ומה זה שלא נתכוון אלא להזכיר שם שמים על הקרבן אמרה תורה קרבן לה' לבטלה על אחת כמה וכמה","לימא כתנאי בית שמאי אומרים כינויי כינויין אסורין ובית הלל אומרים כינויי כינויין מותרין","מאי לאו מאן דאמר כינויי כינויין אסורין קסבר (כינויי) כינויין לשון אומות הן, ולמאן דאמר מותרים קסבר לשון שבדו להן חכמים","לא דכולי עלמא כינויין לשון אומות הן ובית שמאי סברי בהני נמי משתעי אומות ובית הלל סברי בהני לא משתעי אומות","ואיבעית אימא בית שמאי סברי גזרינן כינויי כינויין משום כינויין ובית הלל סברי לא גזרינן כינויי כינויין משום כינויין","היכי דמי כינויי כינויין דנדרים תני רב יוסף מקנמנא מקנחנא מקנסנא היכי דמי כינויי כינויין דחרם תני מפשאה חרקים חרכים חרפים כינויי כינויין דנזירות תני רב יוסף מחזקנא מנזחנא מפיחנא","איבעיא להו מיפחזנא מאי מיתחזנא מאי מיתעזנא מאי אמר ליה רבינא לרב אשי קינמא (קינמא) מאי קונם קאמר, או דילמא קינמן בשם קאמר","אמר ליה רב אחא בריה דרב חייא לרב אשי קינה מאי קינה של תרנגולין קאמר או דילמא לשון דקונם תיבעי","כינויי כינויין דשבועה היכי דמי שבואל שבותיאל שקוקאל שבואל שבואל בן גרשום משמע אלא שבובאל שבותיאל שקוקאל מהו אמר שמואל אמר אשיבתא לא אמר כלום אשקיקא לא אמר כלום קרינשא לא אמר כלום","נדר במוהי הרי אלו כינויין תניא רבן שמעון בן גמליאל אומר האומר במוהי לא אמר כלום במומתא דאמר מוהי הרי אלו כינויין לשבועה:","\u0001מתני׳\u0002 האומר לחולין שאוכל לך לא כשר ולא דכי טהור וטמא נותר ופיגול אסור","כאימרא כדירים כעצים כאשים כמזבח כהיכל כירושלים נדר באחד מכל משמשי המזבח אף על פי שלא הזכיר קרבן הרי זה נדר בקרבן רבי יהודה אומר האומר ירושלים לא אמר כלום"],[[0,"מנין שלא יאמר אדם לה' עולה וכו'","דילמא אמר לה' ולא גמר לדיבור זה דלא אמר קרבן וקא מפיק שם שמים לבטלה אלא לכתחילה בעי למימר עולה והדר לה':"],[2,"כינויי כינויין אסורין","שאם נדר בכינויי כינויין דקסבר כינויין דתנן במתניתין לשון אומות הם ומשום הכי אם כינה בלשון אחר מהני לשון אומות חשיב נמי נדר ואסור:"],[3,"ולמאן דאמר מותר קסבר לשון שבדו להם חכמים","ומשום הכי מותרים הני הוא דבדו להן חכמים אסורים אבל אם כינה בלשון אחר דלא בדו הן חכמים מותרין:"],[4,"בהני נמי משתעי אומות","והני נמי הוו ככינויין עצמן דמתניתין ואסירי:"],[4,"ובית הלל סברי לא משתעי אומות הכי","ולאו לשון אומות נינהו ומותרין:"],[5,"גזרינן כנויי כינויין","דאסירי אטו כינויין עצמן דמתני' דלשון אומות:"],[6,"מקנמנא מקנחנא מקנסנא","דקונם קונח קונס היינו כינויין עצמן אבל בהאי לשון מקנמנא מקנחנא מקנסנא היינו כינויי כינויין:"],[6,"תני מפשאה","שם חכם:"],[6,"תרקייא תרכייא","כמו חרק חרך:"],[7,"מיפחזנא מאי מיתחזנא מאי","דמתחלף במנזחנא מי הוי כנויי כינויין אליבא דמאן דאסר:"],[7,"או דילמא קינמן קאמר","ולאו כלום הוא:"],[9,"שבואל בן גרשום משמע","דכתיב שבואל בן גרשום נגיד על האוצרות (דה\"א לז) ולא משמע לשון שבועה:"],[10,"נדר במוהי","כמו מומתא:"],[11,"מתני' האומר","לחבירו לא חולין שאוכל לך ליהוי מה שאוכל לך אלא קרבן ליהוי אסור:"],[11,"","או שאמר לא כשר שאוכל לך לא טהור שאוכל לך או שאמר טמא שאוכל לך או נותר או פיגול בכל הני לשונות הוי נדר ואסור:"],[12,"כאימרא","שאמר הרי עלי כאימרא דמשמע כבש תמידין:"],[12,"כדירים","כדיר בהמות של קרבן ואית דאמרי כדיר העצים:"],[12,"כעצים","משמע כעצי המערכה:"],[12,"כאשים","כאשו של מזבח:"],[12,"או נדר באחד מכל משמשי מזבח","בכלי המזבח כמזרק או כמחתה אסור באותו חפץ שנדר בו:"]],[[3,"מ\"ד אסור קסבר לשון אומות הן","וה\"נ משתעי אומות מ\"ד מותר קסבר לשון שבדו חכמים (בנזיר) כינויי [כינויין] לא בדו:"],[7,"איבעיא להו מפזיחנא מאי אדסליק","מיניה קאי לכך נקט מפזיחנא קודם מפקיחנ' מאי מכדיקנא מאי וא\"ת אמאי לא מיבעיא כמו כן גבי קונם בהפוך האותיות מקימנא מאי וכו' וי\"ל כיון שיש מימי\"ן [נ\"א עייני\"ן] תכופין יחד אין זה נראה כינוי כלל אבל תימה דה\"ל למיבעיא מנקימנא מאי וכו' וי\"ל דהא פשיטא דלעולם אות ראשונה לא תזוז ממקומה:"],[10,"רשב\"ג אומר במוהי במומתא לא אמר כלום","פר\"י לפי שנראה שתי תיבות כמו תיבה בפני עצמה פר\"י דפליג אתנא קמא דמתניתין דקתני נדר במוהי ודוקא קאמר לשון זה במתני' שאמר במוהי בבי\"ת ואפ\"ה מהניא א\"כ פליג ארשב\"ג דהכא:"],[11,"לחולין שאוכל לך","ול\"ג לא חולין:"],[11,"לא כשר ולא דכי","ר\"ל בקרבן לא כשר ולא דכי דכשרות וטהרה לא שייך כ\"א בקרבנות שיש קפידה בטהרתם וכן גבי בשר קרבנות דוקא אמר פסול וכשר דגבי חולין שייך איסור והיתר:"],[11,"טמא","תימה למה לי טמא השתא לא דכי מהני לאסור טמא כ\"ש טמא בהדיא וי\"ל דסד\"א דדוקא לא דכי שהזכיר טהרה קצת שייך בקרבנות שצריכין לנהוג בטהרה אבל טמא בהדיא הוי אמינא אדרבא משתמע דבר שנוהגים בו טומאה דהיינו חולין קמ\"ל דבקרבן טומאה קאמר:"],[11,"נותר ופיגול","אע\"ג דהוי דבר האסור דמתפיס בעיקר קדושת הקרבן שנעשה נותר ופיגול:"],[12,"כאימרא","יש לפרש כאימרא תמידא אי נמי ולד חטאת אי נמי אילו של אברהם אבינו:"],[12,"כדירים","של קרבנות א\"נ כדיר של עצים ולפי ששני עניני דיר הן לכך נקט לשון רבים כדירים:"],[12,"כעצים","עצי מערכה:"],[12,"כאשים","הקרבן - עצמו קאמר אשה ריח ניחוח ובירושלמי מפרש כעצים שני גזירי עצים כאשים שלהביות של מזבח דאש של מזבח מועלין בו כדאיתא ביומא (דף מו:):"],[12,"משמשי מזבח","מפרש בירושלמי כגון מחתה:"]]],[["\u0001גמ׳\u0002 סברוה מאי לחולין לא לחולין ליהוי אלא קרבן","מני מתניתין אי רבי מאיר לית ליה מכלל לאו אתה שומע הן דתנן רבי מאיר אומר כל תנאי שאינו כתנאי בני גד ובני ראובן אינו תנאי","אלא רבי יהודה היא אימא סיפא רבי יהודה אומר האומר ירושלים לא אמר כלום מדסיפא רבי יהודה רישא לאו רבי יהודה היא","כולה רבי יהודה היא והכי קתני שרבי יהודה אומר האומר ירושלים לא אמר כלום","וכי אמר כירושלים לרבי יהודה מי מיתסר והתניא רבי יהודה אומר האומר כירושלים לא אמר כלום עד שידור בדבר הקרב בירושלים","כולה רבי יהודה היא ותרי תנאי אליבא דרבי יהודה"],[[1,"גמ' לית ליה מכלל לאו אתה שומע הן","כגון במתניתין דמכלל דאמר לא לחולין שמעי' מינה הא קרבן הוי ואהכי אסור ור' מאיר סבר דלא הוי אסור אא\"כ אמר בפירוש לא חולין ליהוי אלא קרבן דלא משמע ליה מכלל לא חולין אתה שומע קרבן:"],[1,"דתנן","במסכת קידושין בפרק האומר ר' מאיר אומר כל תנאי שאינו כתנאי בני גד ובני ראובן אינו תנאי דכתיב ויאמר אליהם משה אם יעברו בני גד ובני ראובן אתכם וגו' ואם לא יעברו וגו' לא נכתוב אם יעברו דלא צריך למיכתב אלא אם לא יעברו דמשמע אם לא יעברו ונאחזו בתוככם הא אם יעברו ונתתם להם וגו' אלא להכי איצטריך למיכתב לתרוייהו דלא אמרינן מכלל לאו אתה שומע הן ומתניתין קתני אסור דמכללא לא לחולין שמעינן קרבן:"],[2,"אלא","מתניתין רבי יהודה היא דאית ליה מכלל לאו אתה שומע הן דלית ליה תנאי כפול:"],[2,"אימא סיפא רבי יהודיה אומר אף האומר ירושלים לא אמר כלום","דפליג אתנא דלעיל מיניה דהיינו ר' מאיר דסתם משנה היא ומדסיפא ר' יהודה רישא לאו רבי יהודה דא\"כ הוי רישא וסיפא רבי יהודה ומציעתא רבי מאיר:"],[2,"שר' יהודה אומר האומר ירושלים כו'","דבעינן שיאמר כירושלים כלומר נזירים בירושלים:"],[2,"האומר כירושלים לא אמר כלום","דלא מיקדשא ירושלים:"],[4,"עד שידור בדבר הקרב בירושלים","כגון קרבנות ומנחות שקריבין לגבי מזבח:"],[5,"ותרי תנאי אליבא דרבי יהודה","דתנא דמתניתין סבר האומר ירושלים לא אמר כלום הא כירושלים אסור דירושלים מיקדשא ותנא דברייתא סבר האומר כירושלים לא אמר כלום דקסבר ר' יהודה לא נתקדשה ירושלים אא\"כ יאמר כדבר הקרב בירושלים:"]],[[0,"סברוה מאי לחולין כו'","האי סברוה דקאמר קיים במסקנא הוא דכוותיה אשכחנא בב\"ב (דף ב.) סברוה מאי מחיצה גודא:"],[1,"דאי ר״מ לית ליה מכלל לאו אתה שומע הן","תימה דאמרינן בשבועות פרק שבועת העדות (שבועות דף לו.) כי לית ליה לר״מ בממונא אבל באיסורא אית ליה [וי״ל] נדרים נמי חשיב ליה איסורא דאית ביה ממונא כיון שאוסר ממון של חבירו עליו:"],[3,"כולה רבי יהודה היא","וה\"ק שרבי יהודה אומר כל האומר ירושלים לא אמר כלום עד שיאמר בכ\"ף וא\"ת כיון דכולה ר' יהודה א\"כ לא כשר לא דכי וכו' טמא נותר פיגול נמי ליכא כ\"ף ואומר דחייל הנדר ואור\"י דעד כאן ר' יהודה לא קאמר דבעי כ\"ף אלא כשמתפיס בשם דבר כגון קרבן עולה ומנחה וכן כיוצא בהן שהם שם דבר אבל לשון פעולה מודה ר' יהודה דלא בעינן כ\"ף והוי לשון פעולה מיניה טהור ומטהר טמא ומטמא פיגול ונתפגל אע\"ג דקרבן נמי יש לפרש לשון מוקרב מ\"מ על כרחך שם דבר הוא דקרוי הכי:"],[4,"והתניא האומר כירושלים לא אמר כלום עד שידור בדבר הקרב בירושלים","וס\"ל דאף ירושלים מתרומת הלשכה דהוי דבר הנדור רק אין דעת הנודר לכך אלא דעתו להתפיס כמו שירושלים קדוש יותר מכל ארץ ישראל ולא דבר הנדור:"],[5,"תרי תנאי אליבא דר' יהודה","דאמר ירושלים בלא כ\"ף הא בכ\"ף מיתסר סבירא דדעת הנודר להתפיס בקדושת ירושלים שעשויה מתרומת הלשכות:"]]],[["תניא חולין החולין כחולין בין שאוכל לך ובין שלא אוכל לך מותר לחולין שאוכל לך אסור לחולין לא אוכל לך מותר","רישא מני רבי מאיר היא דלית ליה מכלל לאו אתה שומע הין","אימא סיפא לחולין לא אוכל לך מותר והתנן לקרבן לא אוכל לך רבי מאיר אוסר וקשיא לן הא לית ליה מכלל לאו אתה שומע הין","ואמר רבי אבא נעשה כאומר לקרבן יהא לפיכך לא אוכל לך הכא נמי הכי קאמר ליה לא חולין ליהוי לפיכך לא אוכל לך","האי תנא סבר לה כרבי מאיר בחדא ופליג עליה בחדא סבר לה כותיה בחדא דלית ליה מכלל לאו אתה שומע הין ופליג עליה בחדא בקרבן","רב אשי אמר הא דאמר לחולין והא דאמר לא חולין דמשמע לא ליהוי חולין אלא כקרבן:","טהור וטמא נותר ופיגול אסור: בעי רמי בר חמא הרי עלי כבשר זבחי שלמים לאחר זריקת דמים מהו","אי דקאמר בהדין לישנא בהיתרא קא מתפיס אלא כגון דמחית בשר זבחי שלמים ומחית דהיתרא גביה ואמר זה כזה מאי בעיקרו קא מתפיס או בהיתרא קא מתפיס","אמר רבא תא שמע נותר ופיגול"],[[0,"בין שאוכל לך בין שלא אוכל לך","בין שאמר חולין שאוכל לך או החולין שאוכל לך דהיינו ודאי מותר ובין שאמר חולין שלא אוכל לך או החולין שלא אוכל לך דמשמע חולין מה שלא אוכל לך אבל מה שאוכל לך לא הוי חולין אלא קרבן אפי' הכי מותר דלא אמרינן מכלל לאו אתה שומע הן דהא ברייתא ר\"מ היא דלית ליה מכלל לאו אתה שומע הן דכשאמר חולין שלא אוכל לך לא כפליה לתנאיה ולא אמר כלום אבל כי אמר לא חולין שאוכל לך אסור דהכא לא אמרינן מכלל לאו אתה שומע הן דאע\"ג דאמרינן לעיל לא חולין שאוכל לך ודייקינן לא חולין ליהוי אלא קרבן ודייקינן לרבי מאיר לית ליה מכלל לאו אתה שומע הן והכא נמי אי דאמר חולין דלא אוכל לך אילו דקדקנו האי חולין שלא אוכל לך הא שאוכל לך לא הוי חולין אלא קרבן הוה משמע מכלל לאו אתה שומע הן אבל האי לאו לא משמע מכלל לאו אתה שומע הן דהא בפירוש אמר האי תנא הכא דהאי [לא] הוי מכלל לאו אתה שומע הן ואיכא דאמרי חולין שלא אוכל לך האי חולין שלא אוכל לך אלא קרבן משמע דהאי תנא משמע ליה מכלל לאו אתה שומע הן אבל האי לא משמע ליה מכלל לאו אתה שומע הן דהא בפירוש אמר לא לחולין שאוכל לך שאינו רוצה ליהנות ממנו:"],[0,"לא לחולין לא אוכל מותר","מפרש לקמן:"],[2,"וקשיא האי קרבן לא אוכל לו אמאי אסור הא לית ליה מכלל לאו כו'","דהאי מכלל לאו אתה שומע הן כלומר לא קרבן הוא מה שלא אוכל לך אבל מה שאוכל לך הוי קרבן:"],[3,"ואמר ר' אבא נעשה כאומר כו'","דבפירוש מפרש שאינו רוצה ליהנות ממנו ולא מכלל לאו אתה שומע הן הוא:"],[3,"הכא נמי","גבי לא לחולין לא אוכל לך אמאי מותר ליתרציה נמי ר' אבא דה\"ק לא לחולין ליהוי לפיכך לא אוכל לך כלומר מה שאתה רוצה להאכילני משלך לא לחולין הוי אלא לקרבן לפיכך לא אוכל לך:"],[4,"האי תנא","דברייתא דאמר לחולין לא אוכל לך מותר:"],[4,"סבר לה כוותיה בחדא וכו' ופליג עליה בחדא","בקרבן וכי היכי דאמר לא לחולין לא אוכל לך מותר הכי נמי היכא דאמר לקרבן לא אוכל לך דלית ליה האי תירוצא דרבי אבא:"],[5,"הא דאמר לחולין","דאמר לחולין לא אוכל לך הוי מותר אע\"ג דמשמע מה שאוכל הוי קרבן דלית ליה מכלל לאו אתה שומע הן כדפרישית לעיל ולענין האי תירוצא דמתרצינן לעיל לא לחולין ליהוי וכו' הני מילי היכא דאמר לא לחולין אבל לחולין לא משמע לא לחולין:"],[6,"הרי עלי כבשר זבחי שלמים וכו'","אי דקאמר בהאי לישנא בהיתירא קא מתפיס. ופשיטא דמותר דשלמים לאחר זריקת דמים מותרין אפילו לבעלים:"],[7,"","כגון דמחית בשר חולין ובשר זבח שלמים לאחר זריקת דמים:"],[7,"מי אמרינן בעיקרו קאי מתפיס","בעיקר זבחי שלמים כמו שהיה לפני זריקת דמים שאסור:"],[7,"או","כדהשתא כמו שהיא עכשיו שהיא מותרת:"],[8,"תא שמע","דתנן נותר ופיגול ומשמע נמי כגון דמחית בשר דהיתירא ונותר ופיגול ואמר זה כזה:"]],[[0,"תניא חולין החולין כחולין בין שאוכל לך בין שלא אוכל לך מותר","וא\"ת שאוכל לך פשיטא וי\"ל דשלא אוכל איצטריך ליה אע\"ג דמשמע מה שלא אוכל יהא כחולין הא מה שאוכל לך יהא כקרבן אפ\"ה לא אמר כלום כדפרישי' דאתאן כרבי מאיר דלית ליה מכלל לאו כו' מיהו קשה מסיפא דקתני לא חולין שאוכל לך אסור לא לחולין לא אוכל לך מותר הא לא חולין שאוכל לך אסור אמאי אתיא לר\"מ אי משום דוקיא לא חולין ליהוי אלא קרבן מה שאוכל לך הא נמי חשיב מכלל לאו כו' כדאמרינן לעיל גבי לחולין במתני' מפרש לא לחולין ליהוי אלא לקרבן ומסיק עליה מני אי ר\"מ לית ליה מכלל לאו וכו' אלמא חשיב ליה מכלל לאו וכו' וי\"ל דלא דמי דלעיל מתני' לא אמר לא חולין אלא לחולין בפתח ואם אתה בא לאסור צריך אתה לפרש דיבורו לחולין כמו לא חולין וכיון דצריך לפרש כולי האי חשיב מכלל לאו וכו' ולית ליה לר\"מ מכלל לאו וכו' אבל הכא שאמר בפירוש לא חולין הוי כאילו פירש דבריו בהדיא לא חולין אלא קרבן והואיל ואין כאן חסרון פתרון מהני אפי' לר\"מ ולא חשיב מכלל לאו וכו':"],[2,"אימא סיפא לא חולין לא אוכל לך מותר והא תנן לקרבן מותר כו' ה\"נ ה\"ק ליה לא חולין ליהוי אלא קרבן לפיכך לא אוכל לך","וא\"ת והא מוכח לעיל דכיון דאמר לחולין בפתח חשיב מכלל לאו וכו' וי\"ל דס\"ד השתא דכיון דאמר לא חולין לא אוכל לך להוכיח סופו של איסור בא הילכך אפי' לר\"מ מיפשטא פשיטא ליה לחולין בפתח כמו לחולין דלא דמי לחולין דמתני' דהתם אומר לחולין אוכל לך וליכא הוכחה לאסור לא בתחילת דבריו ולא בסוף דבריו ומסיק רב אשי הא דאמר לחולין בפתח לא מהני לר\"מ אף כי בסוף דבריו אמר לא אוכל דלא חשיב הוכחה רק היכא דאמר לא חולין שמתחילת דבריו איכא הוכחה כדפ\"ל:"]]],[["הא נותר ופיגול לאחר זריקת דמים הוא","אמר ליה רב הונא בריה דרב נתן בנותר של עולה אמר ליה אם כן ליתני בבשר עולה","לא מיבעיא קאמר לא מיבעיא בשר עולה דאסור דהא בקרבן קא מתפיס נותר ופיגול דעולה איצטריכא","סלקא דעתך אמינא כאיסור נותר כאיסור פיגול והוה ליה כמתפיס בדבר האסור ולא מיתסר קא משמע לן","מיתיבי איזהו איסר האמור בתורה אמר הריני שלא אוכל בשר ושלא אשתה יין כיום שמת בו אביו כיום שמת בו רבו כיום שנהרג בו גדליה בן אחיקם כיום שראיתי ירושלים בחורבנה ואמר שמואל והוא שנדור באותו היום","היכי דמי לאו כגון דקאי בחד בשבא דמית ביה אבוה ואף על גב דאיכא טובא חד בשבא דהיתרא וקתני אסור שמע מינה בעיקר הוא מתפיס","דשמואל הכי איתמר אמר שמואל והוא שנדור ובא מאותו היום ואילך","אמר רבינא תא שמע כחלת אהרן וכתרומתו מותר הא כתרומת לחמי תודה אסור"],[[0,"והא נותר לאחר זריקת דמים הוא","דאיתסר דנותר הוי שניתותר חוץ לזמנו שלא נאכל ופיגול שיצא חוץ למחיצתו ואמר זה כזה וקאמר דהוי אסור והא נמי דלאחר זריקת דמים והוה ליה שעת הכושר קודם לכן וקתני דאסור אלמא בדהשתא קא מתפיס ואיכא דאמרי האי פיגול לאו דוקא הוא דלא הוי פיגול אלא היכא שנשחט על מנת לאוכלו חוץ לזמנו דלא הוה ליה שעת הכושר מעולם ולא קא פריך אלא מנותר דהוה ליה שעת הכושר ופיגול אגררא נסבה ולאו דוקא:"],[1,"אמר ליה רב הונא לרבא בנותר של עולה","מיירי דלא הוה ליה שעת הכושר מעולם דעולה כולה כליל היא אבל אי הוה ליה שעת הכושר אמרינן מעיקרא קא מתפיס:"],[1,"אם כן ניתני בבשר עולה","ממש דלית ליה שעת הכושר:"],[2,"דהא בקרבן קא מתפיס","והויא נדר גמור:"],[2,"אלא נותר ופיגול איצטריכא ליה","דאימא באיסור נותר כו' קמתפיס:"],[3,"ולא מיתסר","דלא הוי נדר כדבעינן למימר לקמן שיהא מתפיס בדבר הנדור ולא בדבר האסור:"],[3,"קמשמע לן","האי דקאמר נותר ופיגול לאו איסור נותר ופיגול קאמר איסור כמותו אלא בנותר ממש ופיגול ממש דהוי דבר הנדור:"],[4,"איזהו איסר האמור בתורה","דכתיב לכל שבועת אסר (במדבר ל׳:י״ד) דמשמע שיהא נודר בדבר שנאסר בכך:"],[4,"ואמר שמואל והוא שנדור ובא","במסכת שבועות:"],[4,"מאותו היום","כגון דבאותו יום שמת אביו קיבל עליו בנדר שלא יהא אוכל בשר וכגון דהוה אותו היום חד באייר דאיכא חד בשבת דהיתירא טובא בנתים ולסוף שנה באייר בחד בשבת נמי אמר הריני שלא אוכל בשר בחד בשבת כמו אותו חד דאשתקד שמת בו אביו ואמרי' דאסור דאע\"ג דאיכא חד בשבת דהיתירא בנתים דכל הני חד בשבת בנתים אכל ועכשיו כשאמר הריני שלא אוכל בשר בחד בשבת כמו אותו חד בשבת שמת בו אביו דלא אכל והרי איכא כמה בחד בשבת דאכל אפ\"ה אמרי' בעיקרו קא מתפיס באותו חד בשבת דלא אכל ואסור: ענין אחר כגון דנדר בחד בשבת דר\"ח אייר שמת בו אביו ולסוף שש שנים או חמש שנים קאי בחד בשבת דר\"ח אייר ואע\"ג דאיכא טובא ראשי חדשים דאייר בנתים דהיתירא וקתני דאסור:"],[6,"הכי איתמר דשמואל והוא שנדור ובא מאותו היום ואילך","דכל חד בשבת מאותו היום ואילך היה נדור שלא יאכל בשר ועכשיו אומר הריני כאותו היום שמת בו אביו אהכי אסור דלא הוי שום היתירא בנתים אח\"כ באותו יום וליכא למיחש דבהיתירא קא מתפיס:"],[7,"ת\"ש כחלת אהרן וכתרומתו","תרומה גדולה או תרומת מעשר דהיינו דבר האסור ומדקאמר כתרומתו מכלל דאיכא תרומה דאי מתפיס בה הוי אסור דהיינו תרומת לחמי תודה דדבר הנדור הוא תודה ולחמה:"]],[[0,"והא נותר ופגול לאחר זריקת דמים הוא","ר\"ת לא גרס פגול דהא זריקה לא מהני לפגול דלעולם הוה כקודם זריקה מיהו יש ליישבו אגב נותר נקט ליה הש\"ס והא קושיא מנותר דלאחר זריקת דמים ואפילו הכי מתסר אלמא במעיקרא מתפיס וא\"ת הא כיון דאמר בהדיא בנותר ונותר הוי לעולם לאחר זריקת דמים אם כן הוי כאילו אמר לאחר זריקת דמים דפשיטא לך לעיל דמותר א\"כ קשה דהא משמע דרבא בא ליפשוט הבעיא וי\"ל דלא דמיא דהתם מדהאריך בלשון לאחר זריקת דמים ודאי בעינן להתיר אבל גבי נותר לא האריך בלשונו יותר מאילו אמר זה כזה מה שייך למימר משום דמתפיס בנותר והשתא מיתסר דהא דבר האסור הוא אלא ע\"כ משום דמעיקרא מתפיס ומשני בנותר של עולה שיש בו מעילה לעולם אבל ליכא לפרושי דבנותר סתם תלינן ליה בעולה להחמיר א\"כ מאי פריך ליתני כבשר עולה הא רבותא טפי אתא לאשמועינן דבנותר סתם תלינא בנותר של עולה לכן נראה כדפרישית:"],[3,"אבל נותר ופגול באיסור נותר ופגול קמתפיס והוה ליה דבר האסור קמ\"ל","דבמעיקרא בקדושת הקרבן קמתפיס וא\"ת מ\"מ תיפשוט בעיא כי היכי דאמר הכא דאע\"ג דאיכא למיתלי בדבר האסור דהשתא (אפ\"ה) הוי תלינן ליה בדבר [האסור] דמעיקרא ה\"נ דאיכא למיתלי בהיתירא דהשתא תלינן לומר בעיקרא מתפיס וי\"ל דלא דמי הכא שסוף סוף מוכיח שלאיסור עצמו קמתכוין כי תלינן תלינן בדבר האסור אבל לעיל דאיכא למיתליה בהיתרא דהשתא ולא בא לאסור עצמו איכא למימר בהיתר קמתפיס א\"נ שאני הכא דדבר האסור דהשתא לא חייל כ\"א מכח קדושת דבר הנדור דמעיקרא ולפי תי' שני ניחא ההיא דשבועות פ\"ג:"],[5,"לאו כגון דקאי בחד בשבת דמית ביה אבוה","כלומר שמת אביו בחד בשבת ועכשיו הוא עומד ג' שנים או ד' אחר שמת אביו כאותו יום שמת אביו בא' בשבת ולאו דוקא נקט באחד בשבת דאין דבר תלוי כ\"א בכך וכך לחדש כמו שהיה יום שמת אביו אפי' לא יהיה אותו יום בחד בשבת וקס\"ד השתא שאינו נודר אלא אותו יום בלבד שמת אביו ולא אחרינא והיינו דקאמר אע\"ג דאיכא טובא חד בשבת דהיתירא כל סתם חד בשבת שאחרי מיתת אביו ואפ\"ה תלינן לומר דבעיקרא מתפיס ביום שמת אביו ממש ולא בימים של היתר שאח\"כ ומשני שנדר מאותו יום ואילך כל השנים שאחרי כן דהשתא ליכא היתירא וא\"ת אכתי איכא למיתלי בהיתרא בחד בשבת שקודם מיתת אביו וי\"ל דאם ביום שמת אביו אין לו משמעות כלל קודם לכך כ\"א אותו היום עצמו או ימים שמשם ואילך שהם כאותו יום:"],[7,"כחלת אהרן וכתרומתו מותר","משום דלא הוי דבר הנדור וא\"ת והלא קדושת התרומה חלה על ידי דיבור והפרשה וא\"כ הוי דבר הנדור וי\"ל מ\"מ אין האיסור שבתרומה בא ע\"י הפרשה שהרי קודם לכן נמי היה אסור משום טבל דהפרשת התרומה אינה כ\"א להתיר:"]]],[["והא תרומת לחמי תודה לאחר זריקת דמים היא","אימא כתרומת הלשכה אסור","אבל תרומת לחמי תודה מאי מותר ליתני לחמי תודה וכל שכן תרומתו הא קא משמע לן תרומת לחמי תודה תרומתו היא","ואי בעית אימא תרומת לחמי תודה נמי קודם זריקת דמים הוא כגון דאפרשינהו בלישה","וכי הא דאמר רב טובי בר קיסנא אמר שמואל לחמי תודה שאפאן בארבע חלות יצא והכתיב ארבעים למצווה","והא בעי למשקל תרומה וכי תימא דשקיל חדא ריפתא על כולה והתנן אחד מכל קרבן שלא יטול מקרבן על חבירו וכי תימא דשקיל פרוסה מכל חד וחד והתנן אחד שלא יטול פרוסה","אלא דאפרשינהו בלישה דשקיל חדא מחמץ וחדא מן חלות וחדא מן רקיקים וחדא מן רבוכה","לימא כתנאי הרי עלי כבכור רבי יעקב אוסר ורבי יהודה מתיר","היכי דמי אי נימא לפני זריקת דמים מאי טעמא דמאן דשרי ואי לאחר זריקת דמים מאי טעמא דמאן דאסר אלא לאו"],[[0,"והא תרומת לחמי תודה לאחר זריקת דמים הוא","ואליבא דר' אליעזר בר' שמעון נקיט ליה דאמר לא קדש הלחם עד שישחוט ויזרוק דמה לשמה ובתורת כהנים קאמר לה גבי לחמי תודה וקודם זריקה אי אכל מהני לחמי תודה לא עבד איסור גמור ואפי' הכי הוי אסור אלמא כדהשתא מיתפיס: לעולם אימא לך בתר מעיקרא אזלינן היכא דאיכא היתירא ואיסורא ולא תימא דאמרי' בתרומת לחמי תודה אלא אימא הא בתרומת הלשכה אסור דהיא אסורה בין מעיקרא בין בסוף והוי נמי דבר הנדור דכתיב אשר ידבנו לבו תקחו את תרומתי (שמות כ״ה:ב׳):"],[2,"אבל תרומת לחמי תודה מאי מותר","משום דלתרומת לחמי תודה הוי היתר קודם זריקת דם תודה ואזלינן בתר מעיקרא:"],[2,"","אי הכי ליתני כחלת אהרן או כתרומת לחמי תודה מותר ואע\"ג דהוי דבר הנדור ואנא ידענא דכ\"ש כתרומתו דמותר דהוי מתפיס בדבר האסור:"],[2,"","לעולם כתרומת לחמי תודה מותר והאי דקתני כתרומתו הא קמ\"ל דתרומת לחמי תודה תרומתו היא כתרומה חשובה דהויא נמי דבר האסור ואין אדם יכול להתפיס בה דבר בנדר אע\"ג דבאה על ידי נדר:"],[3,"ואיבעית אימא","כדקאמרת הא כתרומת לחמי תודה אסור ואפילו הכי אימא דדייקינן נמי מהכא דאזלינן בתר מעיקרא ואסורה התרומה קודם זריקה כגון דאפרשה בלישה וכי הא דאמר רב טובי בר קיסנא וכו':"],[3,"ואית דמפרשי והא תרומת לחמי תודה לאחר זריקת דם","היה כהן מפרישה והיתה מותרת לכהן וקודם זריקת דם היתה אסורה דמאחר שנתקדשו לחמי תודה בשחיטה נאסרו לכל העולם ונעשה טבל עד שהופרשה התרומה לאחר זריקה שהותרה לכהן אלמא אע\"ג דקודם זריקה היתה אסורה כבשר זבחי שלמים דאסור קודם זריקה ולאחר זריקה הותרה כבשר זבחי שלמים אסור בככר אלמא דאזלינן בתר מעיקרא שהיה אסור לכל העולם: לעולם מהא לא תיפשוט ואימא הא כתרומת הלשכה אסור דתרומת הלשכה לא היה לה היתר בין בתחילת הקדש בין בסוף הקדש:"],[3,"הא כתרומת לחמי תודה מאי מותר","משום דאמרינן בסוף מתפיס ומאחר דתרומת הכהן היא חשובה כתרומה בעלמא כדבר האסור ולא כדבר הנדור ולהכי מותר המתפיס אי הכי ליתני כתרומת לחמי תודה מותר כל שכן כתרומת אהרן דאנא ידענא דמותר דהיא לא באה ע\"י נדר כלל:"],[3,"[תרומתו היא]","להכי קתני כתרומתו במתניתין לאשמועינן דתרומת לחמי תודה לאחר זריקת דם שהיא מופרשת ויש עליה שם תרומת אהרן חשובה דהא מתפיס ככר בתרומת לחמי תודה לאחר זריקת דם שהוא דבר האסור ויש עליה שם תרומה כתרומת אהרן חשובה ולעולם האומר כתרומת לחמי תודה מותר:"],[3,"ואיבעית אימא","האומר כתרומת לחמי תודה אסור ולא תפשוט מהכא בשר זבחי שלמים אי בעיקר מתפיס או בסוף דאפשר דאיסור והיתר תרוייהו ליהוו קודם זריקת דם כגון דאפרשה בלישה והיתה תרומה מותרת לכהן קודם זריקה ולהכי איסור והיתר ביחד קודם הזריקה והיתר לאחר האיסור ותרוייהו קודם זריקה להכי אמרינן באיסור שהיתה קודם שהופרשה שהיתה קדושה בשחיטה קודם הפרשה אסורה לכל העולם הפריש זה את ככרו דמותר להפריש בלישה וכדרב טובי וכו':"],[4,"והא כתיב ארבעים","דארבעים חלות מיבעי ליה למיפי עשרה מכל מין:"],[4,"ומשני למצוה","דמצותו שיהו ארבעים אבל אי אפאן בארבע חלות גדולות מכל מין אחת יצא:"],[5,"והא בעי למישקל תרומה","מן חד וחד מכל מין אחד מעשרה:"],[5,"וכי תימא דשקיל חדא ריפתא אכולהו","דמהני ארבעה שקיל חדא לתרומה:"],[5,"והתנן אחד מכל קרבן","דמכל מין ומין בעי למישקל חדא חדא מחמץ חדא ומחלות חדא ומרקיקין חדא ומרבוכה חדא אבל לא שקיל מחד מין בלבד על תלתא:"],[6,"אלא דאפרשה בלישה","דמכל מין ומין הפריש קודם אפייה לתרומה ואח\"כ אפה לשירים דהשתא שקיל תרומה שלימה מכל קרבן דאופה חלה ממה שנוטל מכל מין ומין:"],[7,"הרי עלי כבכור","בכהן קא מיירי דאי בישראל לית ליה שום זכייה בגוויה ואסור ליה נמי באכילה שאמר הרי עלי בשר זה כבשר בכור:"],[8,"היכי דמי אילימא","דאמר הרי עלי בשר זה כבשר בכור לפני זריקת דמים:"],[8,"מאי טעמא דמאן דשרי","הא בכור לא לישתרי אלא בזריקת דמו:"]],[[0,"דהא תרומת לחמי תודה לאחר זריקה הוא","מ\"מ לא הוי כאומר כבשר שלמים לאחר זריקה כיון שלא האריך בלשונו כדפ\"ל גבי נותר:"],[1,"לימא כתנאי וכו'","אלא דמחית בשר זבחי שלמים גביה ואמר זה כזה - אגב ריהטא דבעיא מיירי בשלמים נקט נמי הכא שלמים אלא כלומר דמחית בשר בכור גביה לאחר זריקה ואמר זה כזה ויס\"ג בהדיא דמחית בשר בכור גביה:"],[2,"הא קא משמע לן דתרומת לחמי תודה תרומתו היא","כלומר כדפ\"ל תרומתו כלל היא:"],[6,"אלא דאפרשינהו בלישייהו","כלומר שהפריש בעודה עיסה ומן השאר עשה ד' חלות מד' מינין:"],[7,"לימא כתנאי וכו'","אלא דמחית בשר זבחי שלמים גביה ואמר זה כזה. אגב ריהטא דבעיא מיירי בשלמים נקט נמי הכא שלמים אלא כלומר דמחית בשר בכור גביה לאחר זריקה ואמר זה כזה ויס\"ג בהדיא דמחית בשר בכור גביה:"]]],[["דמחית בשר בכור קמיה ומחית בשר דהאיך גביה ואמר זה כזה ותנאי היא","לא דכולי עלמא לפני זריקת דמים ומאי טעמא דמאן דשרי אמר קרא כי ידור עד שידור בדבר הנדור לאפוקי בכור דדבר האסור הוא","ומאן דאסר אמר קרא לה' לרבות דבר האסור","ומאן שרי לה' מאי עביד ליה מיבעי ליה למתפיס בחטאת ואשם","ומה ראית לרבות חטאת ואשם ולהוציא את הבכור מרבה אני חטאת ואשם שהוא מתפיס בנדר ומוציא אני את הבכור שהוא קדוש ממעי אמו","ומאן דאסר בכור נמי מתפיסו בנדר הוא דתניא משום רבי אמרו מניין לנולד בכור בתוך ביתו שמצווה להקדישו שנאמר הזכר תקדיש","ומאן דשרי כי לא מקדיש ליה מי לא מיקדיש","כאימרא כדירים","תנא אימרא לאימרא כאימרא דירים לדירים כדירים עצים לעצים כעצים אישים לאישים כאישים מזבח למזבח כמזבח היכל להיכל כהיכל ירושלים לירושלים כירושלים כולן שאוכל לך אסור לא אוכל לך מותר","מאן שמעינן ליה דלא שני ליה אימרא לאימרא כאימרא רבי מאיר היא","אימא סיפא וכולן לא אוכל לך מותר והתנן לקרבן לא אוכל לך רבי מאיר אוסר ואמר רבי אבא נעשה כאומר לקרבן יהא לפיכך לא אוכל לך","לא קשיא הא דאמר לא אימרא הא דאמר לאימרא","\u0001מתני׳\u0002 האומר קרבן עולה מנחה חטאת תודה שלמים שאני אוכל לך אסור רבי יהודה מתיר הקרבן כקרבן קרבן שאוכל לך אסור לקרבן לא אוכל לך רבי מאיר אוסר","\u0001גמ׳\u0002 קתני קרבן הקרבן כקרבן שאוכל לך אסור סתמא תנא כרבי מאיר דלא שני ליה בין אימרא לאימרא","[אי רבי מאיר הא] דקתני הקרבן שאוכל לך אסור והתניא מודים חכמים לרבי יהודה באומר הא קרבן והא עולה והא מנחה והא חטאת שאוכל לך שמותר שלא נדר זה אלא בחיי קרבן"],[[0,"ואמר זה כזה","ובהא קא מיפלגי מר סבר בעיקרו מתפיס ומר סבר בהיתר קא מתפיס לאחר זריקת דמים:"],[1,"אמר קרא כי ידור נדר כי ידור בדבר הנדור","הוי נדר ואסור לאפוקי בכור דדבר האסור דממילא מיתסר:"],[2,"אמר קרא לה' לרבות דבר האסור","דכל דבר שהוא אסור ולגבוה הוא מתפיסו נמי בנדר אע\"פ שהוא אסור בלא נדר כגון בכור:"],[4,"מרבה אני חטאת ואשם","שהם מתפיסים מפני שהוא מתפיסן בנדר אע\"ג דעל חטא באין ולא משום נדר אפ\"ה איהו מתפיסו שאומר הרי זו לחטאתי ולאשמי אבל בכור אינו מתפיס כלל שממעי אמו קדש עצמו:"],[6,"כי לא מקדיש ליה","אם לא הקדישו מי לא מיקדיש בלאו הכי משום הכי לא חשיב כלל כי מתפיס ליה בנדר אבל חטאת ואשם לא מיקדשי לעולם אי לא מקדיש להו:"],[8,"כולן שאוכל לך אסור","דכי אמר כאימרא שאוכל לך דמי כמאן דאמר יאסר עלי מה שאוכל לך אבל אמר כאימרא לא אוכל לך מותר דמשמע אבל אם אוכל לך לא יהא כאימרא ומותר:"],[9,"מאן שמעינן ליה דלא שאני ליה בין אימרא לאימרא כאימרא","דכולן שאוכל לך אסור:"],[9,"ר\"מ היא","דפליג עליה דר\"י דאי ר\"י לית ליה אימרא דאמר האומר ירושלים לא אמר כלום:"],[10,"וכולן לא אוכל לך מותרין","אפילו אמר לאימרא לא אוכל לך:"],[10,"מאן שמעינן ליה דילא שאני ליה בין אימרא לאימרא כאימרא","דכולן שאוכל לך אסור:"],[10,"וכולן לא אוכל לך מותח","אפילו אמר לאימרא לא אוכל לך:"],[11,"לא קשיא הא דאמר לאימרא","מתני' דתנן לקמן וכו' דאמר לאימרא לא אוכל לך דהיינו לקרבן דמשמע לקרבן יהא לפיכך לא אוכל לך וברייתא דקתני מותר תריץ לה הכי דאמר לא לאימרא לא אוכל לך הא אם אוכל לך יהא כאימרא דהיינו מכלל לאו הן ולהכי מותר דלר\"מ לית ליה מכלל לאו [הן]:"],[12,"מתני' האומר עולה","יהא שאוכל לך או מנחה כו' אסור:"],[12,"רבי יהודה מתיר","דלא אמר כעולה כחטאת:"],[13,"גמ' סתמא תנא כרבי מאיר דלא שאני ליה בין אימרא לאימרא","דאסר היכא דאמר ירושלים כמאן דאמר כירושלים ולהכי אסור היכא דאמר קרבן כהיכא דאמר כקרבן:"],[14,"אי רבי מאיר היא","רישא דקתני הקרבן שאוכל לך אסור:"],[14,"והתניא מודים חכמים לרבי יהודה","דהיינו רבי מאיר דפליג עליה:"],[14,"שלא נדר זה אלא בחיי קרבן","דכי אמר הא קרבן שאוכל לך משמע כמאן דאמר חיי קרבן שאוכל לך ולא כלום קאמר:"]],[[2,"אמר קרא לה' לרבות דבר האסור","פי' דבר האסור כי האי דבכור לפי שנחשב קצת דבר הנדור כדמפרש ואזיל:"],[4,"מרבה אני חטאת ואשם שהוא מתפיס בנדר","אע\"ג שהוא חייב אותן בלא נדר מ\"מ אין קדושה חל עליהן ממילא:"],[8,"תנא אימרא לאימרא וכו' הא דאמר לאימרא","בפתח דלאימרא בפתח מפרשינן ליה לאימרא יהא לפיכך לא אוכל לך כמו לקרבן בפתח והא דתניא בהך ברייתא לאימרא לא אוכל לך מותר מיירי שאמר לא אימרא כפר\"ת וא\"ת אי לאימרא דהך ברייתא מיירי דאמר לא אימרא אם כן שאוכל לך אמאי משמע איסורא וי\"ל דודאי לאימרא דרישא (דלא) דאוכל לך מיירי בלאימרא בפתח ולאימרא דלא אוכל מיירי שאמר לא אימרא וא\"ת אם כן אדמפליג בלא אימרא בין אוכל ללא אוכל ליפלוג כולה בלא אוכל בין לאימרא בפתח ללא אימרא דהשתא נמי דמפליג בין אוכל ללא אוכל הוי לאימרא גבי אוכל בפתח וגבי לא אוכל לא אימרא וי\"ל דאה\"נ אלא כיון דאימרא כאימרא לא ליתני ליה לאיסורא רק באוכל לך תני נמי באוכל לך גבי לאימרא ואע\"ג דגבי לאימרא הוי מתסר נמי גם בלא אוכל לך כך צריך לדחוק לפר\"ת ור\"י גרס הא דאמר לאימרא בחטף התם מפרש ליה לאימרא יהא לפיכך לא אוכל לך דומיא דלקרבן לא אוכל לך דהתם נמי לקרבן בחטף הא ברייתא דלעיל דשרי מיירי בלאימרא בפתח בין ברישא גבי שאוכל בין גבי לא אוכל לך:"],[12,"האומר קרבן עולה ומנחה וכו'","אשמעי' אע\"ג דליכא כ\"ף:"],[12,"רבי יהודה מתיר","משום דלא אמר בכ\"ף וה\"ה בלשון קונם בלא כ\"ף דמותר טפי דלא עדיף מלשון קרבן עצמו וקונם בכל הש\"ס בלא כ\"ף דלא כרבי יהודה ור\"י פי' דאמר קונם יש לפרש לשון פעולה כמו מקונם ובלשון פעולה מודה רבי יהודה כקרבן הקרבן:"],[12,"הקרבן כקרבן קרבן אוכל לך אסור","תימה בשלמא הקרבן אשמעינן דלא הא קרבן קאמר כיון שאמר הקרבן תיבה אחת אבל אינך תרתי למה לי ואי משום קרבן בלא כ\"ף כבר אשמעינן (ונראה דא\"ל) דוקא שאוכל לך הוא דאסור אבל לא אוכל לך מותר דלא מפרש קרבן יהא לפיכך לא אוכל לך כך נראה למהר\"ף נ\"ע:"]]],[["לא קשיא הא דאמר הא קרבן והא דאמר הקרבן מאי טעמא חיי קרבן קאמר","קתני לקרבן לא אוכל לך רבי מאיר אוסר והא לית ליה לרבי מאיר מכלל לאו אתה שומע הן אמר רבי אבא נעשה כאומר לקרבן יהא לפיכך לא אוכל לך","\u0001מתני׳\u0002 האומר לחבירו קונם פי מדבר עמך ידי עושה עמך רגלי מהלכת עמך אסור","\u0001גמ׳\u0002 ורמינהו חומר בשבועות מבנדרים ובנדרים מבשבועות חומר בנדרים שהנדרים חלין על המצווה כברשות מה שאין כן בשבועות וחומר בשבועות שהשבועות חלות על דבר שיש בו ממש ושאין בו ממש מה שאין כן בנדרים","אמר רב יהודה באומר ייאסר פי לדיבורי ידיי למעשיהם רגליי להילוכן דייקא נמי דקתני פי מדבר עמך ולא קתני שאני מדבר עמך","\u0001הדרן עלך כל כנויי\u0002","מתני׳ \u0001ואלו\u0002 מותרין חולין שאוכל לך כבשר חזיר כעבודה זרה כעורות לבובין כנבילות וטריפות כשקצים ורמשים כחלת אהרן וכתרומתו מותר","האומר לאשתו הרי את עלי כאימא פותחין לו פתח ממקום אחר שלא יקל ראשו לכך","\u0001גמ׳\u0002 טעמא דאמר חולין שאוכל לך הא אמר לחולין שאוכל לך משמע לא לחולין ליהוי אלא קרבן","מני מתניתין אי רבי מאיר הא לית ליה מכלל"],[[0,"לא קשיא","מתניתין דאסר דאמר הקרבן דהיינו כקרבן שאוכל לך רבי מאיר היא דלא שאני ליה בין אמר הקרבן לכקרבן וברייתא דאמר הא קרבן דמשמע חיי:"],[1,"מתני' קונם פי מדבר עמך","מה שאני מדבר עמך אסור טלי כקרבן או שאמר קונם ידי עושה עמך או קונם רגלי מהלכת עמך אסור לדבר עמו ולהלך עמו ולעשות עמו מלאכה:"],[1,"לא קרבן לא אוכל לך","אבל שאוכל לך הוי קרבן להכי אוסר רבי מאיר ואית דאמרי הכי משמע לקרבן בשביל קרבן לא אוכל לך שאם אוכל לך יהא אסור עלי כקרבן:"],[1,"","ומקשינן והא לית ליה לרבי מאיר וכו':"],[2,"מתני' קונם פי מדבר עמך","מה שאני מדבר עמך אסור עלי כקרבן או שאמר קונם ידי עושה עמך או קונם רגלי מהלכת עמך אסור לדבר עמו ולהלך עמו ולעשות עמו מלאכה:"],[3,"גמ' חלין על המצוה כברשות","שאם אמר קונם שאני עושה סוכה או קונם שאני מניח תפילין חל עליו הנדר ואם עשה קם ליה בבל יחל:"],[3,"מה שאין כן בשבועה","שאין נשבעין לבטל את המצות דמושבע ועומד מהר סיני הוא לקיימן ולהכי לא חלה שבועה עליה דאין שבועה חלה על שבועה:"],[3,"מה שאין כן בנדרים","דאין חלין על דבר שאין בו ממש כגון דיבור שאין בו ממש ואמאי קתני אסור:"],[4,"באומר יאסר פי לדבורי","כלומ' פי יאסר לאותו דיבור שאני מדבר עמך והפה שנאסר יש בו ממש ודאי וידים למעשה ידיהם שאיני עושה עמך ורגלי להילוך שלא אהלך עמך:"],[4,"דיקא נמי","מתני' דאסר דפי קאמר דקתני קונם פי מדבר עמך ולא קתני שאני מדבר עמך שמע מינה דיאסר פי קאמר והיינו דבר שיש בו ממש:"],[5,"","הדרן עלך כל כנויי"],[6,"ואלו מותרין","דלא חשיבי נדר:"],[6,"","האומר חולין שאני אוכל לך או כבשר חזיר שאוכל לך או כעבודת כוכבים כו':"],[6,"כחלת אהרן וכתרומתו מותר","לאכול עמו דכל הני לאו דבר הנדור הן אלא דבר האסור דממילא מיתסרי בלא נדר ואין נודרים בדבר האסור:"],[9,"אי רבי מאיר והא לית ליה מכלל לאו אתה שומע הן","והיכא דאמר לחולין לא אמרינן דמשמע אלא לקרבן דהיינו הן מכלל לאו:"]],[[0,"הא דאמר הא קרבן","בשתי תיבות אז אמרינן בחיי קרבן קאמר והכי משמע הא הנה בקרבן אני נשבע הא דאמר הקרבן כלומר מתניתין דאסרה מיירי דאמר הקרבן בתיבה אחת לפיכך אסור דלא שייך לומר שהוא לשון שבועה כיון דאמר ליה בתיבה אחת ומתניתין נמי דייקינן דמיירי בתיבה אחת דומיא דקרבן אע\"ג דבהעבודה הזה הוי לשון שבועה אף כי בתיבה אחת שאני הכא כיון דבלשון נדר קא\"ל דקאמר הקרבן שאוכל לך הילכך אין לפרשו בלשון שבועה היכא דקא\"ל בתיבה אחת:"],[1,"קתני לקרבן לא אוכל לך רבי מאיר אוסר והא לית ליה לר\"מ מכלל וכו'","השתא דטעמא דאסור משום מכלל וכו' משמע לא קרבן מה שלא אוכל הא מה שאוכל לך יהא קרבן ומשני באמר לקרבן יהא לפיכך לא אוכל לך כלומר הכי מפרש ליה ופר\"ת דמיירי דאמר לקרבן בפתח בין לפי דברי המקשה בין לפי דברי המתרץ אלא שהמקשה היה סבור דפי' לקרבן בפתח כמו לא ודחי דמפרשי' ליה לקרבן יהא ור\"י מפרש דלפי שינויא מיירי דאמר לקרבן בחטף מיהו לפר\"ת ניחא טפי דע\"כ למאי דס\"ד מעיקרא הוי לקרבן בפתח מדהוה טעי המקשה לומר טעמא דאיסורא משום מכלל ומסתמא ה\"ה לדברי המתרץ א\"נ גם לפר\"י יש ליישב דבזה הם חלוקין המקשה והמתרץ דודאי המקשה היה סבור דגרס לקרבן בפתח לפיכך היה טועה לומר דטעמא משום מכלל לאו כו' ודחי דרבי מאיר מיירי דאמר לקרבן בחטף וא\"ת לפר\"ת דאמר לשינויא דאמר לקרבן בפתח לרבנן דלית להו האי סברא דלקרבן יהא לפיכך וכו' מ\"מ מיתסר מטעם מכלל לאו וכו' לרבנן דאית להו מכלל וכו' וא\"כ אמאי קתני רבי מאיר אוסר הא לרבנן נמי מיתסר בשלמא לפר\"י דגרס לקרבן בחטף וליכא למימר מכלל לאו וכו' לכך ליכא למיסר כ\"א מטעם לקרבן יהא לפיכך מותר לרבנן דלית להו סברא דלקרבן יהא אבל לפר\"ת קשה כדפרישית וי\"ל דאה\"נ דאסור גם לרבנן ולרבותא נקט ר\"מ אוסר דאע\"ג דרבי מאיר לית ליה מכלל וכו' מ\"מ אוסר מטעם דלקרבן יהא וכו':"],[4,"באומר יאסר פי לדיבורי","תימה אמאי לא משני לה דאף כי אין בו ממש ואין נדרים חלים מדאורייתא מ\"מ מיתסר מדרבנן כדמסיק רבינא לקמן פ\"ב ואיסור דמתניתין מדרבנן קאמר וי\"ל דמתרץ ליה האמת דמתניתין מוכחא דמיירי בהכי שאמר יאסר פי לדיבורי כדמסיק דיקא נמי דקתני כו':"],[4,"ידי לעושיהם","וא\"ת תיפוק ליה דמעשה ידים גופיה יש בו ממש כדמוכח בכתובות (דף נט.) דאם אמר קונם מעשה ידי דחייל לר\"מ דאמר אדם מקדיש דבר שלא בא לעולם וי\"ל דאה\"נ ואגב אינך נקט הך שינויא אכולהו ועוד דאיכא מעשה ידים שאין בהן ממש כגון שלא אתן לפני בקרו תבן:"],[5,"","הדרן עלך כל כנויי נדרים"],[6,"ואלו מותרין","הרי עלי:"],[8,"טעמא דאמר חולין שאוכל הא לחולין שאוכל לך וכו'","דס״ד לדיוקא איצטריך למידק מיניה לחולין כיון דלגופיה לא איצטריך:"]]],[["לאו אתה שומע הן ואלא רבי יהודה היינו רישא","איידי דקתני כבשר חזיר כעבודת כוכבים להכי קתני חולין","רבינא אמר הכי קתני אלו מותרין כחולין כבשר חזיר כעבודת כוכבים ואי לא תנא חולין הוה אמינא בעי שאלה","ומי איכא לאסוקי על דעתא הכי הא מדקתני סיפא האומר לאשתו הרי את עלי כאימא פותחין לו פתח ממקום אחר מכלל דרישא לא בעיא שאלה אלא מחוורתא חולין ממילא נסבה","מנא הני מילי אמר קרא איש כי ידור נדר לה' עד שידור בדבר הנדור","אי הכי אפילו בדבר האסור נמי דהא כתיב לאסור איסר על נפשו לאסור איסר מבעי ליה לכדתניא איזהו איסר האמור בתורה וכו':","האומר לאשתו הרי את עלי כאימא וכו': ורמינהו הרי את עלי כבשר אימא כבשר אחותי כערלה וככלאי הכרם לא אמר כלום","אמר אביי לא אמר כלום מדאורייתא וצריך שאלה מדרבנן רבא אמר הא בתלמידי חכמים הא בעם הארץ","והתניא הנודר בתורה לא אמר כלום ואמר רבי יוחנן וצריך שאלה לחכם ואמר רב נחמן ותלמיד חכם אינו צריך שאלה"],[[0,"אלא רבי יהודה היא","דאית ליה מכלל לאו הן:"],[0,"היינו רישא","כלומר כבר תנינא בפירקין דלעיל (נדרים דף י:) לחולין שאוכל לך לא כשר וכו' ומוקמינן לה כרבי יהודה ומאי קא משמע לן הכא אלא ודאי לא איצטריך הכא חולין אלא איידי דבעא למיתני כבשר חזיר כעבודת כוכבים תנא נמי חולין:"],[2,"רבינא אומר","הא דקתני חולין לאו דאמר חולין שאוכל אלא הכי קתני אלו מותרין כחולין האומר כבשר חזיר כעבודת כוכבים כו':"],[2,"ואי לא תנא חולין","דמשמע מותר כחולין הוא הוה אמינא בעי שאלה לחכם היכא דאמר כבשר חזיר או כעבודת כוכבים בעי למישאל אי הוה נדר אי לא ולהכי תנא חולין למימר דחולין גמורין נינהו דלא בעי שאלה:"],[3,"ומי איכא לאסוקי אדעתא","דבעי שאלה היכא דנדר כהאי גוונא אי לא תני נמי חולין:"],[3,"והא מדקתני סיפא האומר לאשתו הרי את אסורה כאימא","אע\"ג דנדר בדבר האסור דלא הוי נדר:"],[3,"פותחין לו פתח ממקום אחר","לנודר זה לחרטה שצריך לבא לפני חכם ואין פותחין לו לומר הואיל ונדרת בדבר האסור לא כלום נדרת אלא מפתח אחר מראין לו ההיתר כדי שלא יקל את ראשו לכך כלומר להכי מצרכינן ליה שאלה ופותחין לו פתח ממקום אחר כדי שלא יהא קל בעיניו לידור בכך להזכיר אמו לגנאי ומדקתני בהא סיפא דצריך שאלה מכלל דרישא דלא קתני לא צריך שאלה ואפילו אי לא אמר חולין לא מצרכינן ליה שאלה:"],[3,"אלא חולין ממילא נסבה","כדי נסבה:"],[5,"דהא כתב נמי לאסור איסר","ונימא נמי עד שידור בדבר האסור:"],[6,"לא אמר כלום","אלמא אפילו שאלה לא בעי:"],[7,"לא אמר כלום מדאורייתא","הואיל דנדר בדבר האסור ומ\"מ צריך שאלה כדי שלא יקל את ראשו בכך:"],[7,"תלמיד חכם","לא בעי שאלה דאקרי בעלמא היא דאירע לו ולא יקל את ראשו בכך ומתני' מיירי בעם הארץ דאי אמרת אפילו שאלה לא בעי יקל את ראשו להיות נודר כך:"]],[[0,"היינו רישא","פירוש מתני' דפ\"ק דתנא לחולין שאוכל לך לא כשר וכו' ואוקימנא כרבי יהודה:"],[1,"איידי דתנן כבשר חזיר","וכייל דברים הרבה שאין הנדר חל תנא נמי חולין בהדייהו דבעי ליישב לעולם מתני' לאוקמה דאיצטריך למידק הא לחולין וכר' יהודה ואע\"ג דתנינא חדא זימנא פ\"ק תנייה אגב גררא ול\"נ דלאו לדוקיא אתיא מתני' אלא לגופיה אע\"ג דלא הוי שום רבותא מ\"מ תנינא אגב גררא דאינך והשתא מתוקמא גם כר\"מ ולהכי לא הוי מצי למיתני קרבן שאוכל לך:"],[2,"ה\"א דבעי שאלה מדרבנן ומי מצי למימר הכי והא מדקתני סיפא","וא\"ת היכא ס\"ד דבעי שאלה מדרבנן והא קתני דמותרין וי\"ל דס\"ד דמותרין ר\"ל מדאורייתא וכה\"ג אמרינן לקמן ד' נדרים התירו חכמים ואפ\"ה קאמר בגמרא דבעי שאלה מדרבנן:"],[3,"ה\"א דבעי שאלה מדרבנן ומי מצי למימר הכי והא מדקתני סיפא","וא\"ת היכא ס\"ד דבעי שאלה מדרבנן והא קתני דמותרין וי\"ל דס\"ד דמותרין ר\"ל מדאורייתא וכה\"ג אמרינן לקמן ד' נדרים התירו חכמים ואפ\"ה קאמר בגמרא דבעי שאלה מדרבנן:"],[5,"אי הכי אפי' בדבר האסור נמי דהא כתיב לאסור איסר","וא\"ת א\"כ כי ידור נדר לדבר הנדור למה לי וי\"ל דלא תימא דדבר האסור חמיר (פי') [טפי] להתפיס בו מדבר הנדור:"],[5,"ההיא מיבעי' ליה לכדתניא איזהו איסר האמור בתורה וכו'","דמוקי לה בשבועות פ\"ג (דף כ.) למתפיס בנדר או למתפיס בשבועה שאומ' זה כזה ונפקא לן מכפילות הלשון דלאסור איסר וא\"ת התינח לאביי דמוקי ליה הכי פ\"ג דשבועות אלא לרבא דאמר התם מתפיס בשבועה ובנדר לא כלום הוא והך ברייתא מפרש לה ואיזה הוא איסר נדר האמור בתורה הרי שאמר הרי עלי שלא לאכול בשר וכו' דכיון שמזכיר בהדיא שלא לאכול הוי עיקר הנדר ומסברא נפקא ליה ולא משום פסוק א\"כ לדידיה כפילות דלאסור איסר למה לי ושמא יש לומר דלרבא אין להקשות מן הכפילות מלאסור איסר משום דרבא אמר התם דאיסר הוא לשון בפני עצמו [ואם] הוציאו בלשון נדר נדר כגון שאמר ככר זה עלי לאיסור ואם הוציאו בלשון שבועה שאמר איסור שלא יאכל (בדבר) [ככר] זה הוי כאילו אמר שבועה שלא אוכל ככר זה ודריש ליה התם משום דאיסר זה הטילו הכפילות בין נדר לשבועה וכיון דלשון הוא לעצמו ליכא למידרש מן הכפילות שיתפיס בדבר מידי דהוה אשבועה דכתיב או השבע שבועה כפילות ואפילו הכי לא דרשינן מן הכפילות שיתפיס בדבר האסור ע\"י שבועה בכפילות מנדר משום דגלי קרא בעלמא לא תשבעו בשמי לשקר דמשמע שהוא לשון לעצמו שאסר עצמו בלשון שבועה הילכך לרבא לא קשיא כלל מן הכפילות כדפרי' כך נראה למורי שי':"],[6,"ורמינהו הרי את עלי וכו'","יודע היה דמתניתין"],[6,"ורמינהו הרי את עלי וכו'","יודע היה דמתניתין דבעי התרת חכם אינו כ\"א מדרבנן דדבר הנדור בעי אלא ס\"ד דהך ברייתא דקתני לא אמר כלום אפי' מדרבנן לא בעי שאלה מדקתני לא אמר כלום וכן מוכח שינויא דאביי דקאמר לא אמר כלום מדאורייתא וצריך שאלה מדרבנן:"],[6,"","ה\"ג בהך ברייתא הרי את עלי כבשר אמי כבשר אחותי ואאחותו של הבעל קאי אבל ל\"ג כבשר אמה כבשר אחותה דמשמע דאמה ואחותה של אשתו קאי ול\"נ דא\"כ הוה ליה למימר כבשר אמך או כבשר אחותך דהא במדבר עם אשתו מיירי כדקאמר הרי את עלי אלא גר' כבשר אמי כבשר אחותי אך הסופרים טעו לכתוב אמה ואחותה:"],[7,"רבא אמר הא בתלמיד חכם הא בעם הארץ","ואביי מדלא משני הכי משמע לדידיה דאין חילוק בין תלמיד חכם לעם הארץ ואפי' בת\"ח בעי שאלה מדרבנן:"],[8,"והתניא הנודר בתורה וכו'","פירוש והתניא בניחותא שיש חילוק בין ת\"ח לעם הארץ:"]]],[["תניא הנודר בתורה לא אמר כלום במה שכתוב בה דבריו קיימין בה ובמה שכתוב בה דבריו קיימין","קתני במה שכתוב בה דבריו קיימין בה ובמה שכתוב בה צריך למימר","אמר רב נחמן לא קשיא הא דמחתא אורייתא אארעא הא דנקיט לה בידיה מחתא על ארעא דעתיה אגווילי נקט לה בידיה דעתיה על האזכרות שבה","ואיבעית אימא דמחתא על ארעא והא קא משמע לן דאף על גב דמחתא על ארעא כיוון דאמר במה שכתוב בה מהני וזו ואין צריך לומר זו קתני","ואי בעית אימא כולה מציעתא נמי דנקיט ליה בידיה והא קא משמע לן כיוון דנקיט ליה בידיה אף על גב דלא אמר אלא בה כמאן דאמר במה שכתוב בה דמי:","\u0001מתני׳\u0002 קונם שאני ישן שאני מדבר שאני מהלך האומר לאשה קונם שאני משמשך הרי זה בלא יחל דברו:","\u0001גמ׳\u0002 איתמר קונם עיני בשינה היום אם אישן למחר אמר רב יהודה אמר רב אל יישן היום שמא יישן למחר ורב נחמן אמר יישן היום ולא חיישינן שמא יישן למחר ומודה רב יהודה באומר קונם עיני בשינה למחר אם אישן היום שישן היום"],[[0,"הנודר בתורה","שאוכל לך לא אמר כלום:"],[2,"אי מחתא ספר תורה אארעא","ואמר במה שכתוב בה:"],[2,"דעתיה אגוילי","דכשנדר לא נדר אלא בגוילין שכתוב בהן התורה דכיון שהיה רואה אותה מונחת על הארץ סבר הואיל ומונחת על הארץ ודאי אין כתוב בה ולא נדר אלא בגוילין ולא אמר כלום אבל אי אמר בה ובמה שכתוב בתוכה אפילו אי מחתא אארעא מוכחא מילתא דודאי שבועה גמורה עשה ודבריו קיימין אע\"ג דמחתא אארעא דלהכי אמר בה ובמה שכתוב בה:"],[2,"","אבל אי מנקיט ליה בידיה אפילו אמר במה שכתוב בה דבריו קיימין ובהכי מיירי הא דקתני במה שכתוב בה דבריו קיימין דכיון דמנקיט ליה בידיה בכבוד ורואה ויודע מה שבתוכה כי אמר במה שכתוב בה דבריו קיימין דשבועה גמורה חשיבא וכ\"ש כי אמר בה ובמה שכתוב בה:"],[4,"","תרוייהו מיירי בדנקיט לה בידיה ואהכי תנא בה ובמה שכתוב בה דהא קמ\"ל דכיון דנקיט לה בידיה . דיודע שהיא כתובה אי אמר בה גרידא כמאן דאמר במה שכתוב בה דמי ודבריו קיימין:"],[5,"מתני' קונם שאני ישן שאני מהלך","האומר יאסר עלי כקרבן אם אני ישן או אני מהלך והכי גרסינן גבי נדר בל יחל וגבי שבועה אסור משום דהאי לא יחל דנדר מוקי לה בגמרא דמדרבנן הוא ודשבועה הוי איסור דאורייתא:"],[6,"גמ' קונם עיני בשינה היום אם אני אישן למחר","מה שאני ישן היום יהא עלי בקונם על מנת אם אישן למחר דאם ישן הוא למחר לוקה על מה שישן אתמול:"],[6,"אל ישן היום","דשמא יישן מיד למחר ולא מיקיים תנאיה ונמצא עובר בבל יחל על מה שישן אתמול:"],[6,"ורב נחמן אומר יישן היום ולא חיישי' שמא יישן למחר","דלמחר מיזהיר זהיר שלא יישן כדי שלא ילקה על מה שישן אתמול:"]],[[2,"הא דמחתא אארעא","והכי דייקינן סיפא דבעינן תרתי בה ובמה שכתוב בה אבל מה שכתוב בה לחוד אמרי' דעתיה אגוילין וה\"ק במה שכתוב בה דהיא הקלף אבל כשאמר בה ובמה שכתוב בה ע\"כ מדייתר לשונו שמע מינה דדעתיה אאזכרות שבה ורישא דנקיט ליה בידיה הילכך כשאמר במה שכתוב בה לחוד דעתיה אאזכרות אבל בה לחוד לעולם דעתו אגוילין אע\"ג דנקט ליה בידיה איבעית אימא רישא מחתא אארעא והא קמ\"ל דמחתא אארעא ואמר במה שכתוב בה לחודיה מהני וה\"ג סיפא דנקיט ליה בידיה והא [קמ\"ל] אע\"ג דלא אמר אלא בה כמ\"ד שכתוב בה דמי והא דקתני סיפא בה ובמה שכתוב בה ה\"ק סיפא זימנין דבה לחודה מהני כמה שכתוב בה והיינו היכא דנקיט ליה בידיה:"],[6,"איתמר קונם עיני בשינה היום","ושינה הוא שם דבר בלשון הש\"ס כמו שינה בלשון פסוק:"],[6,"רב נחמן אמר ישן ואין חוששין שמא ישן למחר","מפרש טעמיה בגיטין (ד' פד.) דאי בעי מבריז נפשיה בסילוא:"]]],[["כי לא מזדהיר בתנאה אבל באיסוריה מזדהר","תנן קונם שאני ישן שאני מהלך שאני מדבר וכו' היכי דמי אילימא כדקתני שאני ישן מי הוי נדרא והתנן חומר בשבועות שהשבועות חלות על דבר שיש בו ממש ועל דבר שאין בו ממש מה שאין כן בנדרים ושינה דבר שאין בו ממש הוא אלא דאמר קונם עיני בשינה","ואי דלא יהיב שיעורא מי שבקינן ליה עד דעבר איסור בל יחל והאמר רבי יוחנן שבועה שלא אישן שלשה ימים מלקין אותו וישן לאלתר","אלא דאמר קונם עיני בשינה למחר אם אישן היום הא אמרת כל באיסוריה מזדהר","אלא פשיטא דאמר קונם עיני בשינה היום אם אישן למחר ואי לא ניים היום כי ניים למחר מאי בל יחל דברו איכא אלא לאו בדניים אלמא איתיה דניים ותיובתא דרב יהודה","כי קתני דאי ניים","רבינא אמר לעולם כדקתני ומאי בל יחל מדרבנן","ומי איכא בל יחל מדרבנן אִין והתניא דברים המותרין ואחרים נהגו בהן איסור אי אתה רשאי להתירן בפניהם שנאמר לא יחל דברו","תנן שאת נהנית לי עד הפסח אם תלכי לבית אביך עד החג הלכה לפני הפסח אסורה בהנאתו עד הפסח","הלכה לפני הפסח אסורה לא הלכה לא","אמר רבי אבא הלכה לפני הפסח אסורה ולוקה לא הלכה אסורה בעלמא","אימא סיפא אחר הפסח בבל יחל דברו ואי דלא איתהני לפני הפסח מי איכא בל יחל אלא פשיטא דאיתהני אלמא מיתהני"],[[0,"כי לא מיזדהר בתנאיה","דכיון דיום של מחר הוי תנאיה ליום אתמול כגון דאמר קונם עיני בשינה היום אם אישן למחר הוי אותו היום דלמחר תנאי לאותו היום דאתמול דאם יישן למחר הוי לקי מאותו שינה דאתמול ואם לא יישן לא לקי משום הכי אמרינן דלא יישן היום דשמא כי אתי למחר לא מיזדהר בתנאי ונמצא עובר בבל יחל:"],[0,"אבל באיסורא","דאמר קונם עיני בשינה מחר אם אישן היום דאותו יום של מחר נטוי לאיסורא ודאי מיזהר זהיר ביה דאי לא מקיים תנאי שישן באותו היום ודאי כי אתי למחר לא הוי ישן דהא איתסר בנדר:"],[1,"אילימא כדקתני שאני ישן מי הוי נדר","הא שינה דבר שאין בו ממש הוא:"],[1,"אלא דקאמר קונם עיני בשינה","ועין שנדר בו יש בו ממש:"],[2,"ואי דלא יהיב שיעורא","עד כמה זמן אינו ישן:"],[2,"מי שבקינן ליה","הא עבר ודאי באיסור לא יחל דלא מצי למיקם בנפשיה דלא יישן:"],[2,"והאמר ר' יוחנן וכו'","לאלתר מלקין אותו שיישן הואיל דנדר בדבר שאין יכול לעמוד בו:"],[4,"ואי לא ניים היום כי ניים למחר מאי איסור בל יחל איכא","דקתני אסור והרי לא ישן אתמול כלום:"],[4,"אלא בדניים","אתמול דהכי מיירי מתניתין אם יישן היום ויישן למחר אסור:"],[4,"אלמא אית ליה דניים","אלמא דשבקינן ליה לישן היום ולא חיישינן שמא יישן למחר ותיובתא דרב יהודה:"],[5,"","אמר לך רב יהודה הכי קתני מתני' קונם שאני בשינה היום אם אישן למחר דאסור כי ניים למחר דאי ניים מאתמול דיעבד אבל לכתחילה אין מניחין אותו לישן היום דחיישינן שמא יישן למחר:"],[6,"לעולם כדקתני","שאיני ישן והאי דקאמר והא שינה דבר שאין בו ממש וליכא בל יחל ודאי מדאורייתא ליכא בל יחל ומאי בל יחל איכא דקתני מתניתין דאסור מדרבנן:"],[7,"ומי אכא בל יחל מדרבנן","דמלקין ליה מדרבנן:"],[7,"אי אתה רשאי לנהוג בהן היתר לפניהם","לבטל מנהגם דעובר משום בל יחל ומן התורה אינו בבל יחל אלא מדרבנן:"],[8,"קונם שאת נהנית לי עד הפסח אם תלכי לבית אביך מכאן עדי החג","בפ' הנודר מן הירק כגון דקאי באדר ואמר קונם תהא הנאתי עליך מאכל ומשקה עד הפסח אם תלכי לבית אביך מכאן עד החג עד סוכות:"],[9,"אם הלכה","לבית אביה קודם הפסח אסורה להנות ממנו קודם הפסח כמו שנדר:"],[9,"הא אם לא הלכה","לפני הפסח אינה אסורה עד הפסח ולא חיישינן שמא תלך לאחר הפסח ונמצאת למפרע נהנית באיסור וקשה לרב יהודה דאמר אל יישן היום שמא יישן למחר דאם איתא לדרב יהודה הוה אסר לה מתני' עד הפסח אפי' אם לא הלכה עד הפסח דחיישינן שמא תלך לאחר הפסח ונמצאת נהנית ממנו באיסורא:"],[10,"אמר ר' אבא","תריץ הכי למתניתין הלכה לפני הפסח אסורה בהנאתו ולוקה דעוברת על בל יחל ואם לא הלכה לפני הפסח ואפילו הכי אסורה בהנאתו עד הפסח איסורא בעלמא דחיישינן שמא תלך לאחר הפסח ונמצאת נהנית למפרע באיסורא:"],[10,"הלכה","חייבת מלקות דהא עברה: הכי מסקנא דמתני' הלכה לאחר הפסח עוברת משום בל יחל:"],[11,"","ומקשינן מינה ואי דלא איתהני לפני הפסח מי איכא בל יחל:"],[11,"אלא לאו פשיטא דאיתהני","לפני הפסח וסברה לא אלך אחר הפסח והלכה לאחר הפסח:"]],[[1,"אלא דאמר קונם עיני היום וכו' אלמא איתא דניים","והיא גופ' אשמעי' דאתיא לידי אסור בל יחל מתוך שמותר לישן היום וא\"ת ולוקמיה כגון דאמר קונם עיני בשינה למחר אם אישן - היום דבההיא מודה רב יהודה וי\"ל דהא נמי מילתא דפשיטא היא ולא איצטריך לאשמוע':"],[2,"ואי דלא יהיב שיעורא מי שבקיניה עד דעבר איסורא בל יחל והא א\"ר יוחנן שבועה שלא אישן שלשה ימים וכו'","מכאן פר\"י דנדר שאי אפשר לקיים אינו חל דהכא מדמי נדר שא\"א לקיימו לשבועת שוא וההוא דנדר מכל פרי דעלמא (דף עט:) לאו דוקא כל פרי דא\"כ לא הוה חייל כיון דאי אפשר לקיים:"],[4,"אלא דאמר קונם עיני היום וכו' אלמא איתא דניים","והיא גופ' אשמעי' דאתיא לידי אסור בל יחל מתוך שמותר לישן היום וא\"ת ולוקמיה כגון דאמר קונם עיני בשינה למחר אם אישן היום דבההיא מודה רב יהודה וי\"ל דהא נמי מילתא דפשיטא היא ולא איצטריך לאשמועי':"],[5,"כי קתני דאי ניים","וא\"ת פשיטא דאם ניים דהוה בבל יחל ויש לומר דההיא גופא אתא לאשמועינן דאסור לישן היום כדרב יהודה וה\"ק הרי זה בלא יחל דברו כלומר יש לו ליזהר שלא ישן שאם ישן יבא לידי בל יחל דברו דשמא ישן למחר דמתנאי לא מזדהר כדר' יהודה לכך אם ישן היום קרוב לודאי הוא שיבא לידי בל יחל דברו לפי שרגילות הוא שישן למחר כדפרישי' דבתנאי לא מזדהר וא\"ת ולוקמא כגון דיהיב שיעורא לשינתו ועכשיו לא קשיא ההיא דרבי יוחנן וי\"ל דהאי נמי פשיטא:"],[6,"רבינא אמר לעולם כדקתני","שאני ישן ואע\"ג דהוי דבר שאין בו ממש מ\"מ אסור מדרבנן ובל יחל דקתני אסמכתא בעלמא ומיהו גבי קונם שאני משמשך מודה רבינא דאיכא בל יחל מדאורייתא והוי מתני' לצדדין גבי שאני ישן הוי בל יחל מדרבנן וגבי קונם שאני משמשך הוי בל יחל מדאורייתא ונראה דהלכה כרבינא דאמר דאפילו דבר שאין בו ממש איכא בל יחל מדרבנן חדא דרבינא בתראה ועוד כ\"ע סבירא להו כרבינא והא דדחיק הש\"ס לשנויי דאי ניים ולא מתרץ כרבינא לא משום דלית ליה דרבינא אלא משום דמשמע ליה מתניתין דקתני בל יחל גבי שאני ישן דוקא קאמר מדאורייתא דומיא דגבי שאני משמשך דתני בהדייהו ורבינא לא חייש להכי הלכך הנודר שאני ישן שאני מדבר וכן כל דבר שאין בו ממש צריך התרת חכם:"],[7,"ואחרים נהגו בו איסור","תימה מה ענין זה לנהגו בו איסור וי\"ל דהאי נמי שנדר ונתכוון לאסור עצמו גם בדבר שאין בו ממש אין לך נהגו גדול מזה כ\"נ למשי\"ח:"],[8,"תנן שאת נהנית לי עד הפסח וכו'","תימה הא משעבד לה והיכי מצי מדיר לה וי\"ל באומר קונם תשמישך עלי ושאת נהנית לי לאו דוקא אי נמי שאני הכא כיון שתולה הנדר בדבר שיכולה לקיים שפיר חייל הנדר אף כי מדירה כשאמר קונם תשמישי עליך שהרי לא תלך לבית אביה ולא תיאסר: הלכה אין לא הלכה לא:"]]],[["ותיובתא דרב יהודה","כי קתני דאי איתהני הרי זה בבל יחל דברו","תנן שאת נהנית לי עד החג אם תלכי לבית אביך עד הפסח הלכה לפני הפסח אסורה בהנאתו עד החג ומותרת לילך אחר הפסח","הלכה אסורה לא הלכה לא","אמר רבא הוא הדין דאפילו לא הלכה אסורה הלכה אסורה ולוקה לא הלכה אסורה בעלמא","מיתיבי ככר זו עלי היום אם אלך למקום פלוני למחר אכל הרי זה בבל ילך","מי קתני אוכל אכל קתני דכי אכל הרי זה בבל ילך","הלך הרי זה בבל יחל דברו מהלך לא וקשיא לרב יהודה","אמר לך רב יהודה הוא הדין דליתני מהלך איידי דקתני רישא אכל דלא מיתני ליה אוכל תני סיפא הלך:","האומר לאשה קונם שאני משמשך הרי זה בבל יחל דברו: והא משתעבד לה מדאורייתא דכתיב שארה כסותה ועונתה לא יגרע","באומר הנאת תשמישך עלי והא לא קא ניחא ליה בתשמיש","דאמר רב כהנא תשמישי עליך כופין אותה ומשמשתו דשעבודי משעבדת ליה הנאת תשמישך עלי אסור שאין מאכילין לו לאדם דבר האסור לו:","\u0001מתני׳\u0002 שבועה שאיני ישן שאיני מדבר שאיני מהלך אסור קרבן לא אוכל לך הא קרבן שאוכל לך לא קרבן לא אוכל לך מותר:"],[[0,"ותיובתא דרב יהודה","דאמר אל יישן היום שמא יישן למחר דהא חזינן הכא דשבקינן לה ליהנות לפני הפסח דבתנאה נמי מזדהר:"],[1,"אמר לך רב יהודה לעולם אימא לך אל יישן היום שמא יישן למחר וכי קתני מתניתין הלכה אחר הפסח וכו' דאי איתהני","אם עברה ונהנית לפני הפסח ועברה והלכה לאחר הפסח עוברת משום בל יחל:"],[2,"קונם שאת נהנית לי עד החג אם תלכי לבית אביך מכאן עד הפסח הלכה וכו'","אבל אם לא הלכה לפני הפסח אינה אסורה ליהנות מאדר עד הפסח דלא חיישינן לשמא תלך עדיין לפני הפסח ותיובתא דרב יהודה דאמר אל יישן כו':"],[4,"","א\"ר אבא הכי קאמר הלכה וכו' לא הלכה איסורא בעלמא דחיישינן שמא תלך עדיין לפני הפסח:"],[5,"","ככר זה קונם עלי היום אם אלך למקום פלוני למחר אם אכלו היום והלך למחר עובר על אכילתו משום בל יחל קתני אכל היום ולא קתני לא יאכל היום אלמא דשבקינן ליה למיכל לאלתר ולא חיישינן שמא ילך למחר:"],[6,"מי קתני אוכל","לכתחילה ולא ילך למחר אכל קתני דיעבד אבל לכתחילה אסור לאכול ודאי היום דחיישינן שמא ילך למחר:"],[6,"והא קתני סיפא הלך הרי הוא בבל יחל אבל מהלך לא קתני","דמשמע דלא שבקינן ליה למיכל אתמול אלא קתני הלך דיעבד ש\"מ דאתמול שבקינן ליה למיכל ולהכי כיון דאכל אתמול אם הלך היום הרי הוא בבל יחל:"],[7,"ותיובתא דרב יהודיה","דאמר אל יישן כו':"],[8,"אמר לך רב יהודה הוא הדין דליתני מהלך","דמשמע דאינו אוכל ומהלך למחר דודאי לא שבקינן ליה למיכל אתמול אלא איידי דתנא רישא אכל דלא מצי למיתני אוכל לרב יהודה דלא מצי למיכל לכתחילה:"],[8,"תנא סיפא","נמי הלך:"],[9,"שאני משמשך הרי זה בבל יחל","אם משמש עמה:"],[9,"והיכי מצי למימר שאינו משמשה והא משתעבד לה","לתשמיש:"],[10,"באומר הנאת תשמישך עלי","כלומר הנאה דאתי לי מתשמישך קונם עלי:"],[10,"והא לא ניחא ליה בתשמישה","ויכול לאסור הנאתה עליו והוי נדר:"],[11,"דיאמר רב כהנא","אשה האומרת קונם הנאת תשמישי עליך כופה ומשמשתו דלאו כל כמינה לאסור נפשה עליו דהיא משועבדת לו להנאתו:"],[11,"אבל אמרה קונם הנאת תשמישך עלי","שאוסרת הנאה שיש לה מתשמישו על עצמה אסור לשמשה וצריך להפר לה:"],[11,"לפי שאין מאכילין לו לאדם דבר האסור לו","והנאת תשמישו אסורה עליה ה\"נ כי אמר הנאת תשמישך עלי ודאי הוי נדר ואסור לשמשה מפני שנהנה ממנה:"],[12,"מתני' שבועה שאיני ישן שאיני מדבר וכו'","דשבועה חלה על דבר שאין בו ממש:"],[12,"קרבן לא אוכל לך","דהיינו כמו אימרא לא אוכל לך דמותר:"],[12,"הא קרבן שאוכל לך","נמי מותר דלא נדר אלא בחיי קרבן:"],[12,"לא קרבן לא אוכל לך","משמע בשביל איסור לא אוכל לך שאם אוכל לך ליהוי אסור עלי כקרבן ומותר לטעמא דר\"מ דלית ליה מכלל לאו וכו' דאי רבי יהודה בין אמר קרבן שאוכל לך בין אמר הא קרבן שאוכל בתרוייהו מתיר רבי יהודה אפילו אמר קרבן שאוכל לך כדאמרינן בפירקין דלעיל קרבן הקרבן כקרבן שאוכל לך אסור מני רבי מאיר היא דלא שני ליה בין אימרא לכאימרא דלרבי יהודה קרבן שאוכל לך מותר:"]],[[1,"כי קתני דאי איתהני","וא\"ת פשיטא ויש לומר דהיא גופא אתא לאשמועינן שיש לו ליזהר שלא תהנה ממנו קודם הפסח שאם תהנה תבא לידי בל יחל מתוך שלא תזהר ותלך אחר הפסח דבתנאי לא מזדהרא:"],[2,"ומותרת לילך אחר הפסח","כלומר אם לא הלכה לפני הפסח מותרת לילך אחר הפסח וליכא למיחש למידי ואין זה חידוש אלא איידי דתנא אחר הפסח משום לא יחל דברו כדפרישית תנא נמי בהך סיפא דינא מותרת לילך אחר הפסח:"],[3,"הלכה אין לא הלכה לא","תיובתא דרב יהודה וא\"ת לפי דברי המקשן הוה דיוק דרישא וסיפא לאפוקי מדרב יהודה תרתי למה לי וכן קשה לפי שינויא דמוקי לה (אותה) כדרב יהודה כדפירשתי וי\"ל דמפרש לכולהו גווני:"],[5,"אכל הרי זו בבל ילך","אלמא איתא דאכל וקשה לרב יהודה [ומשני] מי קתני אוכל אכל קתני דמשמע דוקא דיעבד ואדרבה היא גופא אתא לאשמועי' דאסור לאכול לכתחילה דחיישינן שמא ילך כדרב יהודה:"],[7,"הלך הרי הוא בבל יחל הלך אין מהלך לא","וא\"ת אמאי אינו מדקדק דומיא דלעיל מדקתני הלך הרי הוא בבל יחל אלמא איתיה דאכיל ואע\"ג דמצי לשנויי כדלעיל כי קתני דאי אכיל הוה ליה לאקשויי ולתרץ כדלעיל וי\"ל דהכא פשיטא ליה שיש לו לתרץ דאי אכיל מדקתני ברישא אכל הרי הוא בבל ילך ועלה קאי סיפא הלך הרי הוא בבל יחל כלומר אם הלך אחר האכילה שהזכיר ברישא הרי הוא בבל יחל אבל בהנך דלעיל שלא הזכיר ההנאה שנהנה ברישא וקתני סיפא אחר הפסח בבל יחל להכי ס\"ד מדקתני סתמא לא אתא לאשמועינן דאי איתהני אלא שמותרת ליהנות דלא חיישינן שמא תלך ודחי מ\"מ כי קתני דאי איתהני כדפרישית ועתה נפרש ממה מדקדק הספר הלך אין לא הלך לא כלומר מדלא קתני מהלך דמשמע דלכתחלה ש\"מ דמותר לאכול הככר שאסר עליו ולהכי ניחא דלא קתני מהלך דמשמע לכתחלה דוודאי לא נתיר לילך אחר שאכל אי ס\"ד דאסור לאכול הככר שחכמים אסרו לו ואז ודאי לא יאכלנו א\"כ אפילו לכתחלה נתיר לו לילך כיון שלא אכל ואם כן ליתני מהלך למחר אלא ש\"מ דמותר לאכול לכתחלה והאי דקתני אכל דמשמע דיעבד לאו דוקא:"],[9,"אלא דאמר קונם עיני היום וכו' אלמא איתא דניים","והיא גופ' אשמעי' דאתיא לידי אסור בל יחל מתוך שמותר לישן היום וא\"ת ולוקמיה כגון דאמר קונם עיני בשינה למחר אם אישן היום דבההיא מודה רב יהודה וי\"ל דהא נמי מילתא דפשיטא היא ולא איצטריך לאשמועי':"],[12,"מתני' לא קרבן לא אוכל לך מותר","פי' וקמ\"ל דלא אמר מכלל לאו אתה שומע הן:"]]],[["\u0001גמ׳\u0002 מני מתניתין רבי מאיר היא דאי רבי יהודה לא שני ליה קרבן ולא שני ליה הקרבן","אימא סיפא לקרבן לא אוכל לך מותר והתנן לקרבן לא אוכל לך רבי מאיר אוסר ואמר רבי אבא נעשה כאומר לקרבן יהא לפיכך לא אוכל לך","לא קשיא הא דאמר לקרבן הא דאמר לא לקרבן דלא הוי קרבן קאמר:","\u0001מתני׳\u0002 שבועה לא אוכל לך הא שבועה שאוכל לך לא שבועה לא אוכל לך אסור:","\u0001גמ׳\u0002 מכלל דהא שבועה שאוכל לך דלא אכילנא משמע ורמינהו שבועות שתים שהן ארבע שאוכל ושלא אוכל שאכלתי ושלא אכלתי מדקאמר שלא אוכל שאכלתי ושלא אכלתי מכלל דשאוכל לך דאכילנא משמע","אמר אביי שאוכל שתי לשונות משמע היו מסרבין בו לאכול ואמר אכילנא אכילנא ותו שבועה שאוכל דאכילנא משמע אבל אמר לא אכילנא לא אכילנא ותו אמר שבועה שאוכל דלא אכילנא קאמר","רב אשי אמר שאוכל דשבועה שאי אוכל קאמר אם כן פשיטא מאי למימרא מהו דתימא מיקם לישנא היא דאיתקיל ליה קא משמע לן","אביי לא אמר טעם כרב אשי דלא קתני שאי אוכל","ורב אשי נאדי מן טעם דאביי קסבר שלא אוכל נמי משמע שתי לשונות היו מסרבין בו לאכול ואמר לא אכילנא לא אכילנא ואמר נמי שבועה בין שאוכל בין שלא אוכל הדין אכילנא משמע דאמר","ואיכא לתרוצה נמי לישנא שבועה שלא אוכל שבועה דלא אכילנא קאמר אלא תנא פסקה שאוכל דאכילנא משמע ושלא אוכל לא אוכל משמע:","\u0001מתני׳\u0002 זה חומר בשבועות מבנדרים וחומר בנדרים מבשבועות כיצד אמר קונם סוכה שאני עושה לולב שאני נוטל תפילין שאני מניח בנדרים אסור בשבועות מותר שאין נשבעין לעבור על המצות:"],[[0,"גמ' מתניתין","דהכא לא קתני דלהוי מותר אלא הקרבן שאוכל ולא קרבן שאוכל ואהכי רבי מאיר היא ולא רבי יהודה:"],[1,"אימא סיפא לקרבן לא אוכל לך מותר והא תנן","באידך פירקין לקרבן לא אוכל לך וכו':"],[2,"הא דאמר לקרבן","אסור ומתניתין דקתני מותר דאמר לא לקרבן דמשמע לא להוי קרבן מה שלא אוכל לך דאם אוכל ליהוי קרבן דהיינו מכלל לאו הן ולית ליה לרבי מאיר מכלל לאו הן:"],[3,"מתני' שבועה לא אוכל לך כו' הא שבועה שאוכל אסור","כדמפרש בגמרא דהאי שאוכל לא אוכל משמע כלומר שבועה תהא חלה עלי אם אוכל והאי שבועה ליכא למימר דחיי שבועה קאמר דשבועה לית בה ממש כמו בקרבן אלא שבועה ממש קאמר:"],[3,"לא שבועה לא אוכל לך אסור","אפי' לרבי מאיר דהכי גמרינן במסכת שבועות (דף לו.) דבשבועה אית ליה לר\"מ מכלל לאו אתה שומע הן:"],[5,"גמ' שאוכל שתי לשונות משמע היו מסרבין","מפצירים שיאכל ואמר אכילנא אכילנא ומתוך כך אמר שבועה שאוכל משמע דאכילנא קאמר:"],[5,"","(כשלא היו מסרבין בו אלא מעצמו אמר שבועה שאוכל):"],[6,"רב אשי אומר","הא דקתני הא שבועה שאוכל שאי אוכל קתני ולהכי אסור דלא אכילנא הוא:"],[6,"פשיטא","דודאי אי קאמר שאי אוכל ודאי לא אכילנא הוא ואסור:"],[6,"מהו דתימא","האי דקאמר שאי אוכל מיקם לישנא כלומר תקון הלשון הוא דבדעתו היה לומר שאוכל ונתקל ואמר שאי אוכל ונימא לעולם להוי כמאן דאמר שאוכל קא משמע לן דלא דודאי אסור:"],[7,"אביי לא אמר כטעמא דרב אשי דלא קתני","במתני' שאי אוכל:"],[8,"ורב אשי הוה נאדי","נדוד וסור מטעמיה דאביי דכי היו מסרבין בו לאכול ואמר לא אכילנא לא אכילנא ותו אמר שבועה בין אם אמר שבועה שאוכל בין אם אמר שבועה שלא אוכל משמע דקאמר אכילנא אם אמר שבועה שאוכל משמע קאמר אכילנא דהכי קאמר בתמיה לא אכילנא לא אכילנא שבועה שאוכל בודאי ואם אמר שבועה שלא אוכל הדין משמע נמי דאכילנא דמשמע לא אכילנא שבועה אי לא אכילנא והיינו חדא לישנא:"],[9,"והא איכא נמי לתרוצי","בניחותא דמשמע לישנא אחרינא והאי דאמר שבועה שלא אוכל דלא אכילנא משמע דהאי דאמר לא אכילנא בניחותא קאמר אם כן לא להוי אסור אי נמי כי אמר במתניתין שבועה לא אוכל אלא ודאי ליתא לטעמא דאביי אלא ודאי תנא במסכת שבועות דשאוכל דאכילנא משמע ולא ענין אחר ושלא אוכל משמע דלא אכילנא ולא דבר אחר הלכך מתרץ מתניתין שאי אוכל דכשאוכל ודאי לאו משמע אלא אי אמר דאכילנא:"],[10,"מתני' זה חומר בשבועות מבנדרים","הא דאמרן שבועה שלא אוכל כו' דבשבועות אסור ובנדרים מותר:"]],[[3,"לא שבועה לא אוכל לך אסור","מטעם מכלל לאו וכו' וא\"ת מאי שנא מקרבן ויש לומר דמשום דשבועה חמורה טפי מנדרים משו\"ה אזלינן לחומרא עוד יש לומר דטעמא דשבועה היינו משום דגזרינן שמא יאמר שבועה לא אוכל וידלג לא ובהא ודאי פשיטא אבל גבי נדר אפי' ידלג לא ויאמר קרבן לא אוכל ליכא איסור:"],[10,"זה חומר בשבועות מבנדרים","ומפרש לא קרבן לא אוכל לך וכו' פריך בגמרא דחומר מכלל דנדר הוא מדקאמר חומר בשבועו' מבנדרים משמע הכי דהחומרא דנדרים אינה שוה לשבועה אבל מ\"מ נדר קל הוי והא מותר קתני ומשני אסיפא דאידך קתני שבועה שאיני ישן דודאי בנדרים ליכא איסורא כ\"א מדרבנן כדאמר רבינא וגבי שבועה איכא איסורא דאורייתא וא\"ת לשנויא אחרינא דאוקימנא לעיל כגון דאמר קונם עיני בשינה היום וכו' דלשם ודאי איכא איסורא דאורייתא (וכי) היכא מיתרצנא לישנא דתני דחומר וכו' דליכא למימר דקאי אסיפא פי' כמו שמתרץ הספר דהתם איכא איסורא דאורייתא בנדרים כמו בשבועות כמו שפי' וי\"ל דקאי אדיוק' דמתני' ונדקדק הכי טעמא משום דאמר קונם עיני דהוי דבר שיש בו ממש אבל קונם שלא ישן ליכא איסורא דאורייתא כי אם מדרבנן כדפרשינן לעיל דכולהו אמוראי מודו דאיכא איסורא דרבנן ולא פליגי אלא בלישנא דבל יחל ועל זה אומר זה חומר בשבועות מבנדרים דבשבועות כה\"ג איכא איסורא דאורייתא:"]]],[["\u0001גמ׳\u0002 חומר מכלל דנדר הוא והא מותר קתני","אסיפא דאידך בבא קתני שבועה שאיני ישן שאיני מדבר שאיני מהלך אסור זה חומר בשבועות מבנדרים:","חומר בנדרים מבשבועות כיצד כו': רב כהנא מתני אמר רב גידל אמר רב ורב טביומי מתני אמר רב גידל אמר שמואל מניין שאין נשבעין לעבור על המצות תלמוד לומר לא יחל דברו דברו לא יחל אבל מיחל הוא לחפצי שמים","מאי שנא נדר דכתיב איש כי ידור נדר לה' לא יחל דברו שבועה נמי הא כתיב או השבע שבועה לה' לא יחל דברו","אמר אביי הא דאמר הנאת סוכה עלי הא דאמר שבועה שלא אהנה מן הסוכה","אמר רבא וכי מצות ליהנות ניתנו אלא אמר רבא הא דאמר ישיבת סוכה עלי והא דאמר שבועה שלא אשב בסוכה","ושאין נשבעין לעבור על המצות מהכא נפקא ליה מהתם נפקא ליה דתניא יכול נשבע לבטל את המצוה ולא ביטל יכול יהא חייב"],[[0,"גמ' מדקאמר חומר בשבועות מבנדרים","כלומר דזה חומר טפי בשבועות מחומרא דנדרים מכלל דנדר מיהא הוי כי אמר קרבן לא אוכל לך וכו' דאיסור נדר איכא מדרבנן אלא דלא לקי מדאורייתא ולא מיחייב קרבן שבועה כי היכי דמחייב בשבועות:"],[0,"והא מותר קתני","בנדרים דאפילו שום איסור ליכא:"],[1,"אסיפא","הא דקתני חומר בשבועות מבנדרים דמשמע דנדר חשיב לא קאי ארישא דקתני קרבן לא אוכל לך אלא אסיפא דאידך בבא (לעיל נדרים יד:) דקתני קונם שאיני ישן שאיני מדבר הרי זה בלא יחל דברו ואומר רבינא עלה לעיל (נדרים טו.) לעולם כדקתני שאני ישן ומאי בל יחל בל יחל דרבנן דהיינו איסור דרבנן אבל שבועה שאיני ישן שאיני מדבר מדאורייתא אסור וזה חומר בשבועות מבנדרים ששבועה חלה על דבר שאין בו ממש וחייב קרבן מה שאין כן בנדרים:"],[2,"אבל מיחל הוא לחפצי שמים","שאם נדר לעבור על אחת מן המצות אין שבועה חלה עליו ומיחל לאותה שבועה דמושבע ועומד הוא לקיימה ואין שבועה חלה עליו ויכול לחלל דברו:"],[3,"מאי שנא נדר","דאמר כי נדר על המצוה חל עליו הנדר וכי עבר ועשה המצוה קם ליה בלא יחל:"],[3,"דכתיב כי ידור נדר לה'","דאפילו בחפצי שמים דלה' לא יחל דברו:"],[3,"שבועה נמי","תחול עליה אם נשבע לעבור על המצוה:"],[3,"והכתיב נמי או השבע שבועה לה' לא יחל דברו","דלה' סמוך אאו השבע דמשמע נמי לה' השבע שבועה לא יחל דברו:"],[4,"אמר אביי הא דאמר הנאת סוכה עלי הא דאמר שבועה שלא אהנה מן הסוכה","כלומר הא דקתני מתניתין שנודרין על המצוה כגון דאמר הנאת סוכה עלי דהשתא קאסר חפצא עליה דהכי מצי למידר אפי' לכתחילה כדאמרינן לעיל אע\"ג דמשועבד לאשתו בתשמיש חל עליו הנדר כי אמר הנאת תשמישך עלי שאינו אוסר עצמו עליה אלא לדידה אוסר עליו וקסבר אביי דבכל לשון שבועה לא מצינו דתיחול עליה דאי אמר שבועה הנאת סוכה עלי דהנאתה אוסר עליו דהא ודאי לא הויא שבועה אלא נדר דכיון דקאמר עלי היינו נדר דכל היכא דקאמר עלי אמרינן היינו נדר וחייב באחריותו ונדר הוא כי אמר הכי אפילו לכתחלה מצי נדר וקאסר חפצא עליה אבל שבועה לא מצי לאוקמי אלא כגון דאמר שבועה שלא אהנה וכהאי גוונא לא חייל עליה דלא מצי למיסר נפשיה עליה דמצוה כי קאמר שלא אהנה דאוסר עצמו במצוה שהוא משועבד לו וכה\"ג מיירי חומר בנדרים מבשבועות דבנדרים אומר קונם הנאת סוכה עלי ובשבועה שלא אהנה:"],[5,"וכי מצות ליהנות ניתנו","דקאמר הנאת סוכה עלי הא לא ליהנות ניתנו ולא מצי למיסר נפשיה בהנאתה דהא לא חשיבה הנאה מצוה דלא ניתנו בשביל הנאה:"],[5,"אלא אמר רבא וכו' ישיבת סוכה עלי","כדאמרן דבישיבת סוכה עלי קאסר חפצא עליה:"],[5,"ובשבועה שלא אשב","קאסר נפשיה מן חפצא והא לא מצי למיעבד דמשועבד הוא למצוה ולהכי לא חיילא עליה שבועה:"],[6,"יכול יהא חייב","קרבן שבועה:"]],[[5,"הא דאמר ישיבת סוכה עלי והא דאמר שבועה שלא אשב בסוכה","פי' היכא דאמר ישיבת סוכה עלי קונם מיחל חייל משום דסוכה אינה משועבדת לו אבל היכא דאמר שבועה שלא אשב בסוכה וגופו משועבד לסוכה לא חיילא וא\"ת אדמפליג בנדרים לשבועות ליפלוג וליתני בשבועו' דבשבועות נמי זימנין דחיילי היכא דאמ' ישיבת סוכה עלי שבועה וי\"ל דאה\"נ אלא אורחא דמילתא קתני דסתם נדרים החפץ נאסר עליו וסתם שבועות קאסר נפשיה אחפצא וה\"ק זה חומר בנדרים מה ששייך בנדרים דהיינו דקאסר חפצא עליה ממה ששייך בשבועות והיינו דקאסר נפשיה אחפצא ועי\"ל ודאי בשבועות לא חייל בשום צד אפילו היכא דאמר ישיבת סוכה עלי שבועה וטעם גדול יש בדבר דבשבועות כיון דסתם שבועות קאסר נפשיה אחפצא ולא קאסר חפצא אנפשיה א\"כ אפילו כשאמר ישיבת סוכה עלי שבועה אפ\"ה מתרצינן שבועתיה וחזרה על נפשיה והוי כאילו אמר שבועה שלא אשב בסוכה והאי דאמר ישיבת סוכה עלי שבועה לא משום דקאסר חפצא עליה דבודאי בשבועות לא שייך בה אלא יד שבועה הוי ולעולם קאסר נפשיה מחפצא ובנדרים לאידך גיסא:"]]],[["תלמוד לומר להרע או להיטיב מה הטבה רשות אף הרעה רשות יצא נשבע לבטל את המצוה ולא ביטל שאין הרשות בידו","חד קרא למיפטריה מקרבן שבועה וחד למיפטריה מן לאו דשבועה:","\u0001מתני׳\u0002 יש נדר בתוך נדר ואין שבועה בתוך שבועה כיצד אמר הריני נזיר אם אוכל הריני נזיר אם אוכל ואכל חייב על כל אחת ואחת שבועה שלא אוכל שבועה שלא אוכל ואכל אינו חייב אלא אחת:","\u0001גמ׳\u0002 אמר רב הונא לא שנו אלא דאמר הריני נזיר היום הריני נזיר למחר דמיגו דקא מיתוסף יומא יתירא חיילא נזירות על נזירות אבל אמר הריני נזיר היום הריני נזיר היום אין חלה נזירות על נזירות ושמואל אמר אפילו אמר הריני נזיר היום הריני נזיר היום חלה נזירות עליה","ולרב הונא אדתנא אין שבועה בתוך שבועה ליתני יש נדר בתוך נדר ואין נדר בתוך נדר הריני נזיר היום הריני נזיר למחר יש נדר בתוך נדר הריני נזיר היום הריני נזיר היום"],[[0,"תלמוד לומר להרע או להיטיב מה הטבה רשות","דאי בעי אכיל ואי בעי לא אכיל חייב בקרבן על השבועה אף הרעה דמחייב עלה קרבן הרעה דרשות ולא נשבע לבטל את המצוה דהיא שבועה דהרעה לאו הרשות בידו:"],[1,"חד קרא","קא אתי למיפטריה מקרבן שבועה דהאי קרא דלהרע או להיטיב בקרבן מיירי ואידך לא יחל דברו דבלאו מיירי אתי למיפטריה מן לאו דשבועה:"],[2,"מתני' יש נדר בתוך נדר","דנדר חל אחר נדר:"],[2,"אין שבועה בתוך שבועה","ואם אמר שבועה שלא אוכל כו':"],[2,"כיצד אמר הריני נזיר אם אוכל","וחזר ואמר כו' חייב על כל פעם ופעם נזירות אחת:"],[2,"אינו חייב אלא על אכילה אחת","קרבן שבועה אחת:"],[3,"גמ' לא שנו","דיש נדר בתוך נדר:"],[3,"אלא דאמר כו'","דמיגו דאיתוסף יומא יתירא בנזירות ראשונה דכי אמר הריני נזיר היום קבל עליו נזירות שלשים וכי הדר ואמר הריני נזיר למחר משמע הריני נזיר שלשים יום ואחד ואין נזירות ליום אחד הלכך חל נזירות על נזירות והוי נזיר שלשים אחרים:"],[3,"אבל","אם אמר וכו':"],[4,"ולרב הונא","דקאמר דכי אמר הריני נזיר היום לא חיילי עליה שתי נזירות אם כן ליפלוג בדידה בנדרים וניתני נמי יש נדר בתוך נדר ואין נדר בתוך נדר כיצד הריני נזיר היום הריני נזיר למחר יש נדר בתוך נדר וכו':"]],[[1,"חד למפטריה מקרבן שבועה וחד למפטרי' מלאו דשבועה","מלא יחל כלומר אם מיחל דברו ומקיים המצוה אבל מ\"מ אינו פטור משבועה דנשבע לבטל המצוה אלא לוקה עליו משום שוא כדתנן פ\"ג דשבועות (דף כט.):"],[2,"יש נדר בתוך נדר","כדמפרש ואזיל בתר הכי דאמר הריני נזיר הריני נזיר וא\"ת פתח בנדר דמשמע קונם וסיים בנזירות וי\"ל דנזירות נמי איקרי נדר דכתיב (במדבר ו) לנדור נדר נזיר אבל מ\"מ אמאי שבק סתם נדר ופתח בזה וי\"ל משום דבנדרים לא משכחת נדר בתוך נדר דאי אמר ככר זה עלי קונם ככר זה עלי קונם לא חייל דאין איסור חל על האיסור ואף בנזירות דקאמר דנזירות חל על נזירות לאו לחיובי תרתי בחד ל' יום אלא לענין שיעשה שתי נזירות זו אחר זו דבשלמא התם בנזירות שייך למימר כשאמר ב\"פ הריני נזיר היום הריני נזיר היום שיכול להוסיף בדבור שני ל' יום משמע ל' יום חדשים כפעם ראשונה שאמר הריני נזיר היום שרוצה לומר ל' יום דהויא השתא כאילו [אמר] ל' יום ב' פעמים ואפילו את\"ל דאפילו אם אמר הריני נזיר ל' יום והדר אמר הריני נזיר אלו ל' יום דהוי לשמואל כמו כהיום היום מכ\"מ י\"ל דשאני נזירות הואיל ואית ליה קיצותא ל' יום יש לנו לומר שבא להוסיף שלשים יום חדשים ולכך שייך שפיר למימר דחייל נזירות על נזירות מעשה זו אחר זו כדפרישית אבל גבי נדר דקונם דלית ליה אלא לפי מה שמפרש האדם נמי אפי' כי אמר ככר זו עלי קונם היום אינו אסור אלא אותו היום וכי הדר אמר זימנא אחריתי קונם ככר זה היום אין לנו לתלות דאתא לאסור ולאוסופי למחר כיון דמהיום משמע הלכך לא שייך למימר נדר חל על נדר ולהוסיף נדר אחר כמו בנזירות כדפרישית ולאותו יום גופיה נמי אין לנו שיחול נדר על נדר ולחיובי תרתי קאמר דאין איסור חל על איסור ואפילו בנזירות אין איסור חל על איסור:"],[2,"הריני נזיר אם אוכל הריני נזיר","ה\"ה דהוי מצי למתני הריני נזיר בלא שום תנאי אלא אורחא דמילתא קאמר שכן דרך לומר מחמת שום דבר כיוצא בזה שמסרבין בו לאכול והוא אינו רוצה ונודר אם יאכל ועי\"ל דאגב דבעי לאדכורי אכילה גבי שבועה נקטי' נמי גבי נזירות וכן פר\"י: ולפלוג וליתני בדידה:"]]],[["אין נדר בתוך נדר קשיא","תנן יש נדר בתוך נדר ואין שבועה בתוך שבועה היכי דמי אילימא דאמר הריני נזיר היום הריני נזיר למחר דכוותה גבי שבועה שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל ענבים אמאי לא חלה שבועה על שבועה","אלא היכי דמי דלא חלה שבועה על שבועה כגון דאמר שבועה שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל תאנים דכוותה גבי נזירות היכי דמי דאמר הריני נזיר היום הריני נזיר היום וקתני יש נדר בתוך נדר קשיא לרב הונא","אמר לך רב הונא מתניתין דאמר הריני נזיר היום הריני נזיר למחר דכוותה גבי שבועה דאמר שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל תאנים וענבים דלא חיילא","והאמר רבה שבועה שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל תאנים וענבים ואכל תאנים והפריש קרבן וחזר ואכל ענבים הויא להו ענבים חצי שיעור ואין מביאים קרבן על חצי שיעור","אלמא היכא דאמר שבועה שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל תאנים וענבים מיגו דחל שבועה על ענבים חיילא נמי על תאנים רב הונא לא סבירא ליה כרבה","מיתיבי מי שנזר שתי נזירות מנה את הראשונה והפריש קרבן ונשאל עליה עלתה לו שניה בראשונה","היכי דמי אילימא דאמר הריני נזיר היום הריני נזיר למחר אמאי עלתה לו שניה בראשונה הא איכא יומא יתירא אלא פשיטא דאמר הריני נזיר היום הריני נזיר היום"],[[1,"דכוותה גבי שבועה","דאמר בדיבור שני מה שלא אמר בדבור ראשון מי איכא למ\"ד שלא תחול שבועה על שבועה כהאי גוונא אלא היכי דמי וכו':"],[2,"ומי לא חיילא שבועה על שבועה","בכה\"ג:"],[3,"אמר לך רב הונא מתני' כגון דאמר הריני נזיר היום הריני נזיר למחר","כדאמינא אנא והיינו יש נדר בתוך נדר ודכוותה איירי בשבועה כגון דאמר שבועה וכו' וקסבר רב הונא דכהאי גוונא לא חיילא שבועה על שבועה הא דאמר בשבועה שניה תאנים שמושבע מהן ומ\"מ דומיא דנדר הוא שהוסיף בשניה ענבים:"],[4,"והאמר רבה וכו'","ואכל תאנים והפריש קרבן על שבועה ראשונה שעבר ואכל תאנים:"],[4,"וחזר ואכל ענבים","ולא תאנים:"],[4,"הויא להו ענבים","שאכל חצי שיעור על שבועה שניה לפי שהוא נשבע בשבוע' שניה על תאנים וענבים ועכשיו שלא אכל אלא ענבים לא ביטל אלא חצי שיעור והיינו חצי שבועה ואין מביא קרבן על חצי שיעור:"],[5,"אלמא","טעמא משום דלא אכל אלא חצי שיעור משום הכי פטור מקרבן הא אי אכל תאנים וענבים דאכל כוליה שיעור דשבועה חייב קרבן דמיגו דחלה שבועה על ענבים דהוי חידוש שלא נשבע עליהן עדיין חיילא נמי אתאנים אע\"פ שכבר מושבע מהן וקשה לרב הונא:"],[5,"לא סבירא ליה","לרב הונא הא דרבה וליכא למירמא ליה מיניה:"],[6,"והפריש קרבן","וקודם שהפרישו נשאל על נזירות ראשונה שכבר נדר ואמרו ליה שבטעות נדר ושלא לצורך היה נדר אותם שלשים:"],[7,"עלתה לו","אותה נזירות שכבר נדר בשניה שעדיין חייב ומקריב הקרבן על נזירות השניה ביום שהשלים נזירות ראשונה:"],[7,"הא איכא יומא יתירא","דהריני נזיר למחר דקאמר אותו יום דנזירות שניה אינו חל אלא לאחר שלשים דהיינו לאחר נזירות ראשונה ואמאי עלתה לו שניה בראשונה ויהא נפטר מנזירות שניה קודם שיבא יום שלשים ואחד והא נדר להיות נזיר ביום שלשים וא' דהיינו למחר אלא כגון וכו':"]],[[1,"","אילימא [דאמר הריני נזיר היום] ולמחר דכוותה גבי שבועה דאמר שבועה שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל ענבים האי ודאי חיילא שבועה כיון שהזכיר ענבים לבדם אלא היכי דמי כגון דאמר שבועה שלא אוכל תאנים וכו':"],[3,"אמר לך רב הונא מתני' דאמר היום ולמחר דכוותה גבי שבועה שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל תאנים וענבים","והוי שפיר דכוותה סיפא דגרסי' כדפרישי' ול\"נ דהיכי קאמר מעיקרא אילימא דאמר היום דכוותה גבי שבועה דאמר תאנים וחזר ואמר ענבים האי לאו דכוותה הוא דגבי נזיר למחר שייך כהיום דהא לא מוסיף אלא איסור יתירה אבל ענבים לא שייכי כלל בתאנים שאמר תחלה לכ\"נ לר\"ת לעיל הכי גרסינן אילימא דקאמר היום דכוותה גבי שבועה דאמר שבועה שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל ענבים ותאנים אמאי לא חיילא פי' הא ודאי חיילא כמו שאמר רבה בסמוך דהשתא סבירא ליה כוותיה דרבה אלא דאמר תאנים וכו' כמו לאידך גירסא אמר לך רב הונא לעולם דאמר היום ומחר דכוותה גבי שבועות דלא חיילא כה\"ג כלומר כה\"ג דאמר כבר דהיינו כי אמר תאנים וענבים דכיון שהוא צריך לצירוף תאנים שכבר והשתא ניחא ולפי שהזכיר כבר למעלה לא הוצרך לחזור ולשנותו כאן:"],[4,"","והאמר רבה האומר שבועה שלא אוכל תאנים וחזר ואמר שבועה שלא אוכל תאנים וענבים ועבר ואכל תאנים והפריש קרבן וחזר ואכל ענבים הוו להו ענבים חצי שיעורא - אור\"י דמיירי שאמר שלא אוכל תאנים וענבים ביחד כזית מכל חד וחד והשתא שבועה שניה אינה מחייבת לו על כזית תאנים לבד ולא על כזית ענבים לבד אלא על כזית מכל חד וחד להכי קרי ענבים חצי שיעורא והא דקאמר בסמוך מכ\"מ חיילא וכו' ה\"פ אע\"פ שכבר מושבע הוא על תאנים בשבועה ראשונה מ\"מ חיילא שפיר שבועה שניה על תאנים לענין דמצטרפו בהדי ענבים לחייב משום שבועה שניה דשבועה שניה לא הויא כ\"א משתיהם יחד כדפירשתי ולא מיבעיא אם אכל תאנים וחזר ואכל תאנים וענבים דחייב משבועה שניה כדפירשתי אלא אפילו לא אכל כ\"א ענבים אחר תאנים שאכל בראשונה ולא אכל תאנים באכילה שניה אפ\"ה חייב שתים דמצטרפי הנך תאנים דאכל בראשונה עם אותם ענבים לחייב קרבן שני משום שבועה שניה אע\"ג דכבר מחויב הוא על אותם תאנים קרבן בפני עצמו אפי' הכי מצטרפי שפיר עם ענבים כיון דלא הפריש עליה קרבן ותדע דמדקאמר הפריש קרבן וכו' משמע הא לא הפריש קרבן מחויב קרבן שני אף על גב דלא חזר ואכל תאנים עם ענבים בשניה שכך משמע אבל השתא במפריש קרבן משמע דלא מחייב קרבן שני משום אכילה שניה משום דלא מצטרפין אכילה ראשונה תאנים עם ענבים דבשניה להתחייב שבועה שניה דתאנים וענבים ביחד כיון דהפריש קרבן בין שתי אכילות והפרשה מחלקת ומיהו קרבן חד מחייב אתאנים משום שבועה ראשונה אבל אין לפרש וחזר ואכל תאנים וענבים דאמר לא כזית תאנים לבד ולא כזית ענבים לבד והא דקאמר בסמוך דחיילא אענבים וכו' מטעם איסור כולל קאמר וכי ההיא דרבה בפרק שלישי דשבועות (דף כח:) אמר שבועה שלא אוכל תאנים וחזר [ואמר שבועה שלא אוכל תאנים וענבים] ואכל תאנים וענבים מגו דחיילא וכו' דמיירי נמי באיסור כולל כדפרישית מדמייתי לה גבי כולל דברים המותרים עם דברים האסורים אין לפרש כן דאם כן הוו להו ענבים שיעור שלם וחייב נמי על כזית ענבים לבד והיכי קרי ליה חצי שיעור ואין לפרש נמי דחזר ואכל תאנים וענבים אפילו כזית משניהם דהיינו חצי זית מכל אחד דאם כן לא היינו צריכין לטעמא דבסמוך מגו דחיילא אענבים וכו' דתיפוק ליה משום דגבי תאנים נמי מוסיף הוא בשבועה אחרונה דמשבועה ראשונה לא מחייב אתאנים כ\"א אכזית משום דסתם אכילה משמע כזית והשתא בשבועה שניה מחייב אפילו אחצי כזית דעם חצי זית ענבים לכן נראה דמיירי כדפירשתי ויש להקשות לעיל דקאמר היום ומחר דכוותיה הכא דאמר שבועה שלא אוכל תאנים וענבים מה מדמה זה לזה בשבועה דין הוא שלא יהא חייב על אחת דהא אפי' בשבועה שניה אינו חייב כי אם ע\"י צירוף דתאנים ומתאנים הוא כבר מושבע אבל בנזיר [אם אמר] היום ומחר אם יהיה שותה יין ביום ל' ואחד היה חייב וי\"ל נהי נמי דאם היה שותה חייב מ\"מ לענין חיילות אינו חל לבדו דנזירות אינו מיום אחד ואם כן הוא לצירוף האחרים דמהשלשים יום ראשונים כבר הוא מושבע ועומד:"],[6,"מיתיבי מי שנזר שתי נזירות","בבת אחת:"]]],[["ותיובתא דרב הונא","לא לעולם הריני נזיר היום הריני נזיר למחר ומאי עלתה לו לבר מההוא יומא יתירא אי נמי כגון שקיבל שתי נזירות בבת אחת","מתיב רב המנונא נזיר להזיר מכאן שהנזירות חל על הנזירות שיכול והלא דין הוא ומה שבועה חמורה אין שבועה חלה על שבועה נזירות קלה לא כל שכן תלמוד לומר נזיר להזיר מכאן שהנזירות חלה על הנזירות","היכי דמי אילימא דאמר הריני נזיר היום הריני נזיר למחר הא קרא בעיא אלא לאו דאמר הריני נזיר היום הריני נזיר היום וקתני נזירות חל על נזירות","לא הכא במאי עסקינן כגון שקיבל עליו שתי נזירות בבת אחת","ומאי חומרא דשבועה מנדר אילימא משום דחיילא אפילו על דבר שאין בו ממש נדר נמי חמור שכן חל על המצווה כרשות אלא משום דכתיב בה בשבועה לא ינקה","שבועה שלא אוכל שבועה שלא אוכל ואכל אינו חייב אלא אחת אמר רבא אם נשאל על הראשונה שניה חלה עליו ממאי מדלא קתני אינו אלא אחת וקתני אינו חייב אלא אחת רווחא הוא דלית לה כי מיתשיל על חבירתה חיילא","לישנא אחרינא חיובא הוא דליכא הא שבועה איכא למאי הלכתא לכדרבא דאמר רבא נשאל על הראשונה עלתה לו שניה תחתיה","לימא מסייע ליה מי שנדר שתי נזירות ומנה את הראשונה והפריש קרבן ונשאל עליה עלתה לו שניה בראשונה","כגון שקיבל עליו שתי נזירות בבת אחת"],[[0,"ותיובתא דרב הונא","דמדקתני עלתה לו שניה בראשונה מכלל דנזירות שניה נמי חיילא עליה:"],[1,"לא לעולם דאמר וכו' ומאי עלתה לו לבר מההוא יומא","למשלים אותו ושוב מקריב קרבנו ונמצא נזיר אותו יום שנדר עם ימי נזירות של שלשים יום:"],[1,"אי נמי","להכי חייב נזירות שניה כגון שקיבל עליו שתי נזירות בבת אחת דאמר הרי עלי שתי נזירות להכי חייב שתים אי לאו שנשאל אבל אי אמר הריני נזיר היום הריני נזיר היום אין נזירות חל על נזירות:"],[2,"והלא דין הוא","שלא תהא נזירות חל על נזירות ולא שאר נדרים נדר על נדר:"],[2,"ומה שבועה חמורה","מפרש לקמן אפ\"ה אין שבועה חלה על שבועה:"],[3,"הא קרא בעי","פשיטא ודאי דהא איכא חד יומא יתירא:"],[6,"אם נשאל על הראשונה","שבא לפני חכם ושאל על שבועה ראשונה והתיר:"],[6,"שניה חלה עליו","שאם עובר חייב משום שבועה שניה:"],[6,"מדלא קתני חייב אחת","דאילו קתני חייב אחת הוה משמע נמי שעל כולן חייב אחת וכן אי קתני אינה אלא אחת הוה משמע נמי שכולן שבועה אחת היא ואי בצרה לה אזיל ליה חיובא אלא מדקתני אינו חייב ש\"מ דחיובא חדא מיהא איתיה דאי נשאל על הראשונה שניה חלה עליו דהא דלא חיילא כי לא מיתשיל אראשונה משום דלית רווחא דראשונה עומדת דחייב עליה אבל כשנשאל על הראשונה חיילא השניה:"],[7,"לישנא אחרינא חיובא הוא דליכא","על השניה במקום הראשונה:"],[7,"הא שבועה איכא","כלומר שם שבועה עליה לכי מיתשיל אקמייתא:"],[7,"לכדרבא וכו'","(אבל) כשנשאל על הראשונה חיילא השניה:"]],[[5,"אלא משום דכתיב לא ינקה","כדאמרי' בשבועות (דף לט.) והתם איכא חומרות אחרות והכא נקט הפשוטות דכתיב בקרא דלא תשא ואע\"ג דלא ינקה בשבועת שקר כתיב ומתניתין מיירי בשבועת ביטוי מכל מקום חומרא חשיבותא שוה היא:"],[6,"מדלא קתני אינו אלא אחת","ואע\"ג דבכמה מקומות שונה אינו חייב אלא אחת אע\"ג דליכא אלא חד חיובא מ\"מ היכא דאיכא למיטעי לא הוה ליה למתני מתניתין בהאי לישנא:"],[8,"לימא מסייע ליה מי שנדר","והוי מצי לדחויי כשמואל דאמר דהוי נזיר בהריני נזיר היום הריני נזיר היום אלא רוצה שלא תהא הסיוע קיימת אפילו לרב הונא כיון דמצי לדחויי גם לרב הונא:"],[9,"שקבל עליו ב' נזירות בבת אחת","ק\"ק דהוה מצי לדחויי גם לרב הונא דאמר היום ומחר מאי עלתה לו לבר מההוא יומא אלא הפשוט נקט יותר דעלתה משמע לגמרי:"]]],[["\u0001מתני׳\u0002 סתם נדרים להחמיר ופירושם להקל כיצד אמר הרי עלי כבשר מליח כיין נסך אם בשל שלמים נדר אסור","אם בשל עבודה זרה נדר מותר ואם סתם אסור","הרי עלי כחרם אם כחרם של שמים אסור ואם כחרם של כהנים מותר ואם סתם אסור","הרי עלי כמעשר אם כמעשר בהמה נדר אסור ואם של גורן מותר ואם סתם אסור","הרי עלי כתרומה אם כתרומת הלשכה נדר אסור ואם של גורן מותר ואם סתם אסור דברי רבי מאיר","רבי יהודה אומר סתם תרומה ביהודה אסורה בגליל מותרת שאין אנשי גליל מכירין את תרומת הלשכה סתם חרמים ביהודה מותרין בגליל אסורין שאין אנשי גליל מכירין את חרמי הכהנים","\u0001גמ׳\u0002 והתנן ספק נזירות להקל","אמר רבי זירא לא קשיא הא רבי אליעזר הא רבנן דתניא המקדיש חייתו ובהמתו הקדיש את הכוי רבי אליעזר אומר לא הקדיש את הכוי","מאן דאמר ממונו מעייל לספיקא גופיה נמי מעייל ומאן דאמר ממונו לא מעייל לספיקא גופיה (נמי)"],[[0,"מתני' סתם נדרים","דאינו יודע באיזה ענין נדר:"],[0,"להחמיר","דאזלינן לחומרא ואמרינן על כל דבר הנדור נדר:"],[0,"ופירושן","אבל אי מפרש ואמר דבדבר איסור נדר:"],[0,"להקל","דהכי הוא כדקאמר:"],[0,"כיצד האומר ככר זו עלי בבשר מליח אם בשל שלמים נדר","כי שיילינן ליה אמר על של שלמים נדרתי על שם בשר שלמים שצריכין מלח דכתיב וכל קרבן מנחתך במלח תמלח (ויקרא ב׳:י״ג) ועל יין המתנסך על גבי המזבח לשמים:"],[0,"אסור","שהרי נדר בדבר הנדור, ואם על שם יין נסך של עבודת כוכבים וכבשר מליח דעבודת כוכבים מותר שהרי נדר בדבר האסור:"],[1,"ואם סתם","דאמר אין ידוע לי אם על שם שמים או על שם טומאה נדרתי:"],[1,"אסור","דאמרינן לא נתכוון זה אלא בדבר הנדור והיינו סתם להחמיר ופירושן להקל דאם פי' ואמר לשם עבודת כוכבים נדרנא מותר. ל\"א סתם נדרים דאמר ככר זו עלי כבשר מליח וכיין נסך דלא הזכיר לא לשם שמים ולא לשם עבודת כוכבים להחמיר ופירושן דאם מפרש בשעה שנדר ואמר כבשר מליח של שלמים משלמים ודאי קאמר שצריכות מלח יותר משאר קרבנות שהרי נאכלין לשני ימים ולילה אחת וכיין נסך שעל המזבח דהיינו בדבר הנדור ואם כיין נסך של עבודת כוכבים וכבשר מליח של עבודת כוכבים להקל:"],[2,"אם כחרם של שמים","נדר כגון שהתפיס במה שהקדיש לגבוה לקדשי בדק הבית הלכך אסור דלא ניתן לפדות כדכתיב (ויקרא כ״ז:כ״ח) כל חרם קדש קדשים הוא:"],[2,"כחרם של כהנים","שהתפיס כחרם של חרמי כהנים דכתיב כל חרם בישראל לך יהיה (במדבר י״ח:י״ד) דהאי הוי ממון כהנים והוי מותר כחולין לכל דבריהן לאחר שבא ליד כהן ודין חרמים מפרש במסכת תמורה (דף לב.):"],[2,"אם כחרם של כהנים","שמותר בהנאה לאחר שבא ליד כהנים:"],[3,"כמעשר בהמה","היינו דבר הנדור שאינו אסור עד שיקרא עליו שם מעשר:"],[3,"[ואם של גורן]","מעשר דגן דבר האסור שמעשר ותרומה בשבלין אסור:"],[4,"תרומת הלשכה","דהיינו דבר הנדור מעיקרא דמפריש להו לשקלים:"],[5,"שאין אנשי גליל מכירין בתרומת הלשבה","[לפי שהיו] רחוקים מירושלים:"],[5,"שאין אנשי גליל מכירין חרמי כהנים","שלא היו כהנים ביניהם וכשמחרימין אין מחרימין אלא לשמים:"],[6,"גמ' והתנן ספק נזירות להקל","דאמרינן במסכת נזיר (דף לב:) הריני נזיר אם זהו פלוני שבא נגדי נזיר והלך לו אותו שאין יודע אם נזיר אם לא אינו נזיר ונזירות היינו כנדרים והיכי קתני סתם נדרים להחמיר:"],[7,"המקדיש חייתו ובהמתו","שהקדיש כל חיות ובהמות שיש לו ואם היה לו כוי ביניהן הקדיש נמי דכוי בכלל חיה ובהמה:"],[7,"רבי אליעזר אומר לא הקדיש את הכוי","דלא מעייל איניש ממוניה לספיקא דכוי דספק הוא אי מין בהמה אי מין חיה מאותה ספיקא לא עייליה להקדיש בכלל חיה ובהמה וכי היכי דסבירא ליה דלא מעייל ממוניה לספיקא כל שכן דסבירא ליה דלא מעייל גופיה לספיקא דהיכא דנדר ויש בנזירות ספק לא הוי נזיר ולדידיה סבירא ליה דסתם נזירות להקל:"],[8,"רבי אליעזר אומר לא הקדיש את הכוי","דלא מעייל איניש ממוניה לספיקא. דכוי דספק הוא אי מין בהמה אי מין חיה מאותה ספיקא לא עייליה להקדיש בכלל חיה ובהמה וכי היכי דסבירא ליה דלא מעייל ממוניה לספיקא:"]],[[0,"סתם נדרים להחמיר ופירושן להקל","כדמפרש ואזיל אמר הרי עלי כבשר מליח אם של שלמים נדר אסור פי' שפירש בשעת נדרו הרי עלי כבשר מליח של גבוה שרגילות היה למלוח בשר גבוה כדכתיב על כל קרבנך תקריב מלח אסור ואם של עבודת כוכבים נדר שפי' בשעת נדרו הרי עלי כבשר מליח של עבודת כוכבים דגם לעבודת כוכבים רגילות הוא למלוח מותר דדבר האסור הוא מותר ולהכי לא קתני של חולין משום דאין רגילות לקרות בשר מליח אלא אלו דקתני של שמים ושל עבודת כוכבים ולא של חולין ואם סתם פי' שאמר כבשר מליח סתם ולא פי' שום דבר פי' שנתכוין למה שמשמע בשר מליח ואסור ול\"נ חדא דאם כן לא הוי ופירושן להקל שום חידוש ועוד דל' של שמים ושל עבוד' כוכבים לא משמע כדפירש' וה\"ל למימר אם אמר הרי עלי כבשר מליח של שמים אסור ואם אמר כבשר מליח של עבודת כוכבים מותר כיון דאשעת נדרו קאי לכ\"נ כפי' ר\"ת דאיירי לעולם שלא הוציא בשפתים כ\"א האי לישנא כבשר מליח ותו לא ואם של שמים כלומר שאילנא ליה אחרי כן אם אמר שנתכוין בלבו לומר בשר מליח של שמים אסור ואם אמר נתכוין של עבודת כוכבים מותר הוי פי' לשפתיו כמו דנתכוון בלבו לפת חיטין והוציא משפתיו פת סתם בשבועה ובין ת\"ח ובין ע\"ה מהימן כדאמר דנתכוון לשם עבודת כוכבים ולא בעי התרה כלל ולא דמי להא דאמר בסמוך נדר בקרבן ואמר לא נדרתי אלא בקרבנות מלכים וכן בחרם ואמר בחרמו של ים והאמרי' לכ\"ע מחמרינן עליה להצריכו לבקש לו פתח להתיר דהתם היינו טעמא משום שנראה כנודר נדר גמור ואח\"כ אמר שלא נתכוון אלא לדברי הבאי דלא שייכא כלל לנדר אבל בשר מליח דעבודת כוכבים וכל שכן הני דבתר הכי שייך קצת להתפיס בהם אלא מכל מקום אין הנדר חל דלא הוי נדר גמור ולהכי מהימן שפיר בלא כלום:"],[1,"ואם סתם אסור","פירוש שאמר שנתכוין סתם למה שהלשון משמע והשתא ניחא בכולה מתניתין משתמעי חידוש בין סתם להחמיר בין פירושן להקל:"],[2,"ואם של כהנים מותר","ואף על גב דכל זמן שהן בבית הבעלים הרי הן כהקדש לכל דבריהם מ\"מ דעתו להתרה ואפילו את\"ל דבעיקרא מתפיס דברו דתלה נדרו בשל כהנים שמא דעתו לאחר שהן באו לידי הגזבר שהן כחולין לכל דבריהם:"],[3,"ואם של מעשר סתמא נדר אסור","ואם תאמר והלא עשירי מאיליו הוי קדוש ואם כן לא הוי דבר הנדור וי״ל דבעי העברת מנין ואם היו עשרה ונטל אחד בלא מנין אינו קדוש כדאמר בפ' מעשר בהמה (בכורות דף נח:) מיקרי שפיר דבר הנדור:"],[5,"שאין אנשי גליל מכירין בתרומת הלשכה","לפי שהן רחוקין מירושלים וסתם תרומות דמקומן תרומת דגן:"],[5,"סתם חרמים וכו' שאין אנשי גליל מכירין חרמי כהנים","לפי שהכהנים היה עיקר דירתם ביהודה סמוך לירושלים ולא היו רגילין בחרמי כהנים בגליל כמו ביהודה ובגמרא פריך רישא לסיפא ומשני לה:"],[7,"והתנן ספק נזירות להקל וכו' רבי אליעזר אמר לא הקדיש הכוי","פירש הריב\"א דמיירי דמקדיש חייתו או בהמתו ובהא פליגי דת\"ק סבר מכל מקום קדיש מספק ולא ודאי ור' אליעזר סבר דאפי' ספיקא נמי לא קדיש אבל אם הקדיש שניהם אפילו רבי אליעזר מודה דקדוש ממה נפשך מיהו במס' ביכורים (פ\"ב מי\"א) תנן כיצד אינו שוה לא לחיה ולא לבהמה וכן הכותב חיתו ובהמתו לא כתב הכוי משמע דאפי' בכותב תרווייהו מיירי (והכא לא כ\"ש) לכן נראה לר\"י דפליגי בכל ענין בין הקדיש את שניהן בין לא הקדיש אלא אחד מהם דתנא קמא סבר דאם הקדיש אחד מהם קדוש מספק ואם הקדיש שניהם קדוש בודאי ורבי אליעזר סבר דאפילו אם הקדיש שניהן לא הקדיש דאין דעתו אלא לחיה ובהמה ודאי:"],[8,"למ\"ד ממונו עייל לספיקא גופיה נמי מעייל לספיקא","ולית ליה ההיא דספק נזירות להקל אלא סבירא ליה כרבי שמעון דבסמוך ומתני' דסתם נדרים להחמיר מיתוקמא כוותיה:"]]],[["כל שכן דלא מעייל לספיקא","אמר ליה אביי במאי אוקימתא לספק נזירות להקל כרבי אליעזר אימא סיפא ספק בכורות אחד בכורי אדם ואחד בכורי בהמה בין טמאה בין טהורה המוציא מחבירו עליו הראייה","ותני עלה ואסורים בגיזה ועבודה","אמר ליה אמאי קא מדמית קדושה הבאה מאליה לקדושה הבאה בידי אדם","אלא אי קשיא הא קשיא ספק משקין ליטמא טמא לטמא אחרים טהור דברי רבי מאיר וכן היה רבי אלעזר אומר כדבריו","ומי סבירא ליה לרבי אלעזר ליטמא טמא","והתניא רבי אלעזר אומר אין טומאה למשקין כל עיקר תדע שהרי העיד יוסי בן יועזר איש צרידה על איל קמצא דכן ועל משקין בית מטבחיא דכן","הניחא לשמואל דאמר דכן מלטמא אחרים אבל טומאת עצמן יש בהן שפיר","אלא לרב דאמר דכן ממש מאי איכא למימר","אלא הא רבי יהודה והא רבי שמעון","דתניא הריני נזיר אם יש בכרי הזה מאה כור והלך ומצאו שנגנב או שאבד רבי יהודה מתיר ורבי שמעון אוסר","ורמי דרבי יהודה אדרבי יהודה מי אמר רבי יהודה לא מעייל איניש נפשיה לספיקא ורמינהי רבי יהודה אומר סתם תרומה ביהודה אסורה ובגליל מותרת שאין אנשי הגליל מכירין את תרומת הלשכה טעמא דאין מכירין"],[[0,"","כל שכן דסבירא ליה דלא מעייל גופיה לספיקא דהיכא דנדר ויש בנזירות ספק לא הוי נזיר ולדידיה סבירא ליה דסתם נזירות להקל:"],[1,"אימא סיפא","דספק נזירות להקל:"],[1,"המוציא מחבירו","כהן דבעי לאפוקי מיניה עליו להביא ראיה שהן בכורות שלא הפילה נפל קודם לכן ואי תפס להו כהן על הבעלים להביא ראיה דלאו בכור הוא:"],[2,"ואסורים בגיזה ועבודה","אע\"פ דלא היה ודאי אלמא ספק קדשים לחומרא ואסורין בגיזה ועבודה והיכי מצינן לאוקמה כרבי אליעזר והאמר רבי אליעזר לא הקדיש את הכוי דספק קדשים לקולא:"],[3,"אמאי קא מדמית","קדושת בכור הבאה מאליה לקדושת כוי דע\"י אדם קדושת בכור באה מאליה להכי מחמיר בגיזה ועבודה קדושת כוי דעל ידי אדם לא הוי קדושה מספק:"],[4,"הא קשיא","דקתני סיפא דהא וספק נזירות להקל:"],[4,"ספק משקה","לכל טומאת משקין קרי ספק משום דלית להו עיקר מן התורה לפי שלא מצינו טומאה למשקין בפירוש מן התורה והאי דכתיב וכל משקה אשר ישתה בכל כלי יטמא (ויקרא י״א:ל״ד) ההוא הכשר הוא:"],[4,"ליטמא טמא","לקבל טומאה לעצמן ודאי טמאין:"],[4,"אבל לטמא אחרים טהורין","ואי ר\"א היא הא דאוקמא. לרישא דספק נזירות כרבי אליעזר ומי סבירא ליה דליטמא טמא והתניא רבי אליעזר אומר אין טומאה למשקין כל עיקר תדע כו':"],[7,"הניחא לשמואל","לא קשיא דרבי אליעזר אדר' אליעזר אלא ודאי לא מיתוקמא הך ברייתא דספק נזירות להקל כר\"א:"],[7,"","ע\"א אלא אי קשיא דרבי אלעזר הא קשיא ספק משקין ליטמא טומאת משקין עצמן כו':"],[7,"הא ניחא לשמואל אבל טומאת עצמן יש בהן","ניחא ליה נמי לרבי אלעזר דאמר כדבריו דר\"מ דספק משקין ליטמא טמא והכא בספק נזירות אמאי מיקל משום דקסבר לאו מצוה היא לקבל נזירות ואיש כי יפליא דיעבד קאמר הלכך אית ליה ספק נזירות להקל:"],[8,"אלא לרב דאמר דכן ממש","דאין טומאה למשקין כל עיקר אמאי קאמר רבי אלעזר הכא ספק משקין ליטמא טמא והכא סבירא ליה ספק נזירות להקל:"],[9,"אלא הא רבי יהודה","ברייתא דספק נזירות:"],[9,"והא רבי שמעון","מתניתין דקתני סתם נדרים להחמיר:"],[10,"ומצאו שנגנב או שאבד","ואין יודע אם היה שם מאה כור אי לא:"],[11,"אמר רבי יהודה לא מעייל איניש נפשיה לספיקא","כגון הכא דכשנדר לא על דעתא דהכי נדר שאם נגנב הכרי דהוי ספק אם היה שם מאה כור שיהא נזיר באותה ספיקא:"]],[[10,"ור\"ש אוסר","דמעייל נפשיה לספיק' וא\"ת היכי מייתי קרבנו והלא חולין בעזרה היא דשמא אין בכרי מאה כור ואין הנדר חל וי\"ל שנודר על תנאי אם יש בו מאה כור הריני נזיר ואם לאו הריני נזיר נדבה אלמא לר\"ש מעייל נפשיה לספיקא ומתניתין דסתם נדרים להחמיר מיתוקמא כר\"ש וא\"ת והלא לרבי שמעון לא הוי נזיר ודאי אלא הוי נזיר מספק וצריך להתנות (לרבנן) אם יש בו מאה כור אבל במתני' קתני אסור בודאי קאמר ג\"כ למלקות דומיא דקתני גבי של שמים נדר אסור דהתם אסור ודאי קאמר וי\"ל דבמתני' איכא נדר ודאי אלא שהוא נודר בלשון דמשמע איסור והיתר אבל הכא הנדר אינו נדר ודאי דשמא אין בכרי מאה כור [וא\"ת] א\"כ מה מדמה הא דרבי שמעון לנדר דמתני' דבמתניתין הנדר ודאי והכא הנדר ספק וי\"ל דה\"ק ורבי שמעון אוסר אלמא אפילו בנדר ספק מספק ניזיל לחומרא כ\"ש במתניתין שהנדר הוי ודאי נדר שתופסין חומר משמעות:"],[11,"טעמא דאין מכירין הא מכירין אסור","תימה [מרישא] דמילתא הוי מצי למיפרך דקתני בהדיא סתם תרומה ביהודה אסורה בלא שום דיוק וי\"ל דסתם תרומה ביהודה הוי כמו ודאי כיון שהם סמוכים כ\"כ לירושלים פשיטא דדעתו לאסור אבל בגליל אפילו במקום שהן מכירין מ\"מ רחוקים והוי כמו ספק ואפ\"ה אסורים:"]]],[["הא מכירין אסורין","אמר רבא גבי כרי קסבר כל שספיקו חמור מוודאי לא מעייל נפשיה לספיקא דאילו גבי נזיר ודאי מגלח ומביא קרבן ונאכל על ספיקו לא מצי מגלח","אמר ליה רב הונא בר יהודה לרבא אמר הריני נזיר עולם מאי","אמר ליה נזיר עולם נמי ספיקו חמור מודאי דאילו ודאי הכביד שערו מיקל בתער ומביא שלוש בהמות ואילו ספיקו לא","אמר הריני נזיר שמשון מאי","אמר ליה נזיר שמשון לא תניא אמר ליה והאמר רב אדא בר אהבה תניא נזיר שמשון אמר ליה אי תניא תניא","רב אשי אמר ההיא רבי יהודה משום רבי טרפון היא דתניא רבי יהודה משום רבי טרפון אומר אין אחד מהם נזיר לפי שלא ניתנה נזירות אלא להפלאה","אי הכי מאי איריא שנגנב או שאבד אלא להודיעך כוחו דרבי שמעון דאף על גב דנגנב או שאבד קסבר מעייל איניש נפשיה לספיקא","רבי יהודה אומר סתם תרומה ביהודה כו' הא מכירין אסורין אלמא ספיקא לחומרא","אימא סיפא סתם חרמים ביהודה מותרין ובגליל אסורין שאין אנשי הגליל מכירין את חרמי הכהנים הא מכירין מותרין אלמא ספיקא לקולא","אמר אביי סיפא רבי אלעזר ברבי צדוק היא דתניא רבי יהודה אומר סתם תרומה ביהודה אסורה רבי אלעזר ברבי צדוק אומר סתם חרמים בגליל אסורין"],[[0,"הא מכירין אסורין","ואע\"ג דבסתם נדר וספק אי בתרומת הלשכה אי בתרומת הגורן דמעייל איניש נפשיה לספיקא דאמרינן על דעת תרומת הלשכה נדר:"],[1,"גבי כרי","להכי מתיר ר' יהודה:"],[1,"קסבר לא מעייל איניש וכו'","וכיון דספיקו חמור מודאי ודאי לא מעייל נפשיה באותה ספיקא לחומרא אלא על דעת כן ודאי נדר שאם הכרי בעין דמשכח ליה אם יש שם מאה כור דליהוי נזיר כדיניה אבל לא משכח ליה בעין דליהוי נזיר מספיקא לחומרא לא דגבי נזיר מספיקא הוי חומרא יותר מודאי:"],[1,"[גבי] נזיר ודאי","איכא הא קולא דלסוף נזירותו מגלח ומביא קרבנו ונאכל ואילו ספק נזירות דנגנב הכרי לא מצי מגלח לפי שאינו מגלח אלא על קרבן והא לא מצי לאיתויי קרבן דדלמא לא נזיר הוא וקא מייתי חולין לעזרה הלכך לא מעייל נפשיה בהאי ספיקא אבל גבי תרומה אמרינן מעייל נפשיה לספיקא דאפי' אמרינן תרומת הלשכה מספיקא לא הוי טפי חמורה [ספק יותר] מודאי (יותר) אם אמר בפירוש הרי עלי כתרומת הלשכה:"],[2,"אמר האי הריני נזיר עולם","אם יש בכרי הזה ק' כור דהכא ליכא למימר ספיקו חמור מודאי דאפילו בודאי דמדד הכרי ויש בו ק' כור לא יתגלח לעולם מאי איכא למימר אמאי לא מעייל נפשיה לספיקא:"],[3,"[נזיר עולם נמי]","אפילו היכא דאמר הריני נזיר עולם הוי נמי ספיקו חמור מודאי דאילו נזיר עולם ודאי הכביד עליו שערו מיקל בתער ומביא ג' בהמות חטאת ועולה ושלמים כדין נזיר ואילו ספק נזיר עולם לא מצי לאיתויי קרבן דשמא לאו נזיר הוא:"],[4,"אמר הריני נזיר שמשון","דלא מגלח לעולם כלל מאי איכא למימר אמאי קאמר רבי יהודה מותר הא ליכא למימר דספיקו חמור מודאו:"],[5,"אמר ליה לא תניא","לא אשכחן שום ברייתא דקתני הריני נזיר שמשון דליתיה כלל וכי אמר הריני נזיר שמשון דליחול עליה נזירות כלל משום דשמשון לא יצא נזירות מפיו דהא היה מטמא למתים כי הוה קטיל להו הלכך לספיקא לא עייל נפשיה:"],[5,"והתניא נזיר שמשון","שאומר הריני נזיר שמשון הרי הוא נזיר שמשון ואינו מיקל בתער ומטמא למתים כשמשון:"],[5,"אי תניא תניא","אי משכחת ברייתא תניא דאיכא לתרוצי הכי משום הכי מתיר ר' יהודה דלא מעייל איניש נפשיה לספיקא וליכא למירמא דרבי יהודה:"],[6,"רב אשי אמר ההיא","ברייתא דכרי דמתיר רבי יהודה בספק נזירות ר' יהודה משום ר' טרפון היא:"],[6,"אין אחד מהם נזיר","שנים שהיו עומדים ואמר אחד הריני נזיר אם זה איש פלוני שבא כנגדנו ואידך אמר הריני נזיר אם אינו הוא:"],[6,"אין אחד מהם נזיר","הואיל ובשעת הנדר לא היה ברור לאחד מהן:"],[6,"שלא ניתנה נזירות אלא להפלאה","דבעינן בשעת שנדר שיהא יודע אי הוי נזיר:"],[7,"אי הכי","דמשום הכי מתיר דלא ניתנה אלא להפלאה:"],[7,"מאי איריא נגנב","אפילו איתיה בעיניה נמי כיון דבשעת הנדר לא הוה בריר ליה דלא הוה ידע אי היה ביה מאה כור אע\"ג דהוה אפשר למודדן:"],[7,"אלא להכי תניא נגנב או אבד להודיעך כחו דר' שמעון","דאמר אע\"ג דנגנב דלא אפשר למודדן קאמר ר' שמעון:"],[8,"הא מכירין אסורים","אע\"ג דמספקא לן אי מתרומת הלשכה קאמר אי מתרומת הגורן:"],[8,"אלמא ספיקא לחומרא","להכי פריך מסיפא [ואע\"ג] דמרישא [נמי] איכא למיפרך דקתני ר' יהודה אומר סתם תרומה ביהודה אסורה אלמא ספיקא לחומרא אלא קמ\"ל דבין רישא ובין סיפא קשיא לאידך רישא וסיפא להכי פריך דסיפא לסיפא:"],[10,"ר' אלעזר ברבי צדוק אומר סתם חרמים בגליל אסורים לפי שאין מכירין אלא חרמי שמים","הא אם היו מכירין חרמי כהנים נמי סתמן מותר דספיקא לקולא ורישא ר' יהודה וסיפא ר' אלעזר:"]],[[1,"על ספיקו לא מצי מגלח","וא\"ת אמאי לא מצי מגלח יביא עולות ושלמים ויתנם בנדבה ויגלח עליהם ואי משום חטאת דנזיר דליכא בנדבה מ\"מ מצי לגלח על העולה ועל השלמים בלא חטאת כדאמר בנזיר אם גילח באחד משלשתן יצא וי\"ל מ\"מ לא מצי מגלח כהלכתן על גבי ג' בהמות חטאת עולה שלמים דאין חטאת באה בנדבה והלכך אין יכול להביא על תנאי ור\"י פירש דלא מצי לגלח משום דעבד הקפה וכמאן דאמר דהקפת כל הראש שמה הקפה דמספק אינו יכול לדחות לאו דהקפה הלכך הוי ספיקו חמור מודאי הלכך לא מחית נפשיה בספיקא אבל במתניתין בנדרים אין ספיקו חמור מודאי:"],[5,"א\"ל לא תניא","בשום מקום שיתיר רבי יהודה בהריני נזיר שמשון אם יש בכרי מאה כור:"],[6,"רב אשי אמר ההיא","דספק נזירות דכרי דשרי ר' יהודה לאו טעמא משום דאין אדם מכניס עצמו לדבר שספיקו חמור מודאי אלא רבי יהודה משום רבי טרפון היא דבעי הפלאה וטעמא משום דמספיקא לא משתעבד נפשיה ול\"נ דהא בפרק בית שמאי דנזיר (דף לד.) מוכח בהדיא דרבי יהודה דכרי פליג אההיא דר' יהודה משום רבי טרפון לכ\"נ דה\"ק ההיא דנזיר שמשון דפליג רבי יהודה לאו רבי יהודה אליבא דנפשיה היא דודאי מודה רבי יהודה גבי נזיר שמשון כיון דאין ספיקו חמור מודאי אלא ר\"י משום רבי טרפון היא דבעי הפלאה ופריך מאי איריא נגנבו ואם תאמר התינח לפי' ראשון דקאי ההיא כרבי יהודה משום רבי טרפון לההיא דלעיל דסתם נזיר אלא לפירוש שני דהא דר' יהודה משום ר' טרפון לא קאי אלא אההיא דנזיר שמשון מאי פריך מאי אריא נגנב והא במלתא דנזיר שמשון לא קתני נגנב וי\"ל דס\"ל דברייתא במלתיה דשמשון קתני נגנב להודיעך כחו דר\"ש וכו' וא\"ת התינח לפי' קמא דרב אשי אברייתא דלעיל קאי דקתני בה נזיר סתם אבל לפירוש שני דרב אשי אברייתא דקתני נזיר שמשון קאי א\"כ היכי מיירי בה ר\"ש והא אמר ר\"ש פ\"ק דנזיר (דף ד.) האומר נזיר שמשון לא אמר כלום וי\"ל דברייתא דקתני והתניא נזיר שמשון לא קתני בה נזיר שמשון לבדו אלא שנה בה נזיר שמשון וסתם נזיר והשתא שונה בה נזיר סתם להודיעך כחו דרבי שמעון דמעייל בספיקא אע\"ג דספיקא חמור מודאי ותנא נמי נזיר שמשון להודיעך כחו דרבי יהודה דשרי אע\"ג דאין ספיקו חמור מודאי ומטעם הפלאה כר' טרפון כדקאמר רב אשי:"]]],[["\u0001מתני׳\u0002 נדר בחרם ואמר לא נדרתי אלא בחרמו של ים בקרבן ואמר לא נדרתי אלא בקרבנות של מלכים","הרי עצמי קרבן ואמר לא נדרתי אלא בעצם שהנחתי לי להיות נודר בו: קונם אשתי נהנית לי ואמר לא נדרתי אלא באשתי הראשונה שגירשתי","על כולן אין נשאלין להם ואם נשאלו עונשין אותן ומחמירין עליהן דברי רבי מאיר","וחכמים אומרים פותחין להן פתח ממקום אחר ומלמדין אותן כדי שלא ינהגו קלות ראש בנדרים:","\u0001גמ׳\u0002 הא גופא קשיא אמרת אין נשאלין להן והדר תני אם נשאלו עונשין אותן ומחמירין עליהן","אמר רב יהודה הכי קתני וכולן אין צריכין שאלה במה דברים אמורים בתלמיד חכם אבל בעם הארץ שבא לישאל עונשין אותו ומחמירין עליו","בשלמא מחמירין דלא פתחינן ליה בחרטה אלא עונשין היכי דמי","כדתניא מי שנזר ועבר על נזירותו אין נזקקין לו עד שינהוג בו איסור כימים שנהג בהן היתר דברי רבי יהודה אמר רבי יוסי במה דברים אמורים בנזירות מועטת אבל בנזירות מרובה דיו שלושים יום","אמר רב יוסף הואיל ואמרי רבנן אין נזקקים לו בי דינא דמזדקקי לא עביד שפיר רב אחא בר יעקב אומר משמתינן ליה:","וחכמים אומרים פותחין לו פתח כו': תנא לעולם אל תהי רגיל בנדרים שסופך למעול בשבועות ואל תהי רגיל אצל עם הארץ שסופך להאכילך טבלים אל תהי רגיל אצל כהן עם הארץ שסופך להאכילך תרומה ואל תרבה שיחה עם האשה שסופך לבוא לידי ניאוף","רבי אחא ברבי יאשיה אומר כל הצופה בנשים סופו בא לידי עבירה וכל המסתכל בעקבה של אשה הויין לו בנים שאינן מהוגנין אמר רב יוסף ובאשתו נדה אמר רבי שמעון בן לקיש עקבה דקתני במקום הטינופת שהוא מכוון כנגד העקב","תניא בעבור תהיה יראתו על פניכם זו בושה לבלתי תחטאו מלמד שהבושה מביאה לידי יראת חטא מיכן אמרו סימן יפה באדם שהוא ביישן אחרים אומרים כל אדם המתבייש לא במהרה הוא חוטא ומי שאין לו בושת פנים בידוע שלא עמדו אבותיו על הר סיני","אמר רבי יוחנן בן דהבאי ארבעה דברים סחו לי מלאכי השרת חיגרין מפני מה הויין מפני שהופכים את שולחנם אילמים מפני מה הויין מפני שמנשקים על אותו מקום חרשים מפני מה הויין מפני שמספרים בשעת תשמיש סומין מפני מה הויין מפני שמסתכלים באותו מקום","ורמינהו שאלו את אימא שלום מפני מה"],[[0,"מתני' נדר בחרם","דאמר חפץ זה חרם עלי ושוב אמר לא נדרתי אלא בחרמו של ים על שם הרשת שצדין בו את הדגים ולא בחרם ממש:"],[0,"אלא בקרבנות מלכים","דורונות שמקריבין לפני מלכים:"],[1,"וכן אם אמר הריני עצמי קרבן","דמשמע שהקדיש את עצמו ושוב אמר לא נדרתי אלא בעצם אחד שיש לי בתוך ביתי שהנחתיו להיות נודר בו ולא בעצמי ממש:"],[2,"על כל אלו אין נשאלין להן","דאין צריך שאלה דודאי מותר הואיל ואינהו אמרי דעל דעת כן אמרו:"],[2,"ואם נשאלו","אם באו לישאל:"],[3,"וחכמים אומרים פותחין להן פתח","בחרטה ומוכיחין אותן שלא ינהגו קלות ראש בנדרים:"],[4,"גמ' וכולן אין נשאלין","דאין פותחין להם פתח ואין מתירים להן דקנסינן להו משום דנדרא ממש משמע:"],[4,"והדר תני אם נשאלו","דמשמע דנשאלין:"],[5,"וכולן אין צריכין שאלה","דמותרין בלא שאלה:"],[5,"בד\"א בתלמידי חכם","דאקראי הוא דנדר כה\"ג ולא אתי למיסרך:"],[5,"אבל ע\"ה שבא לישאל עונשים אותו ומחמירים עליו","כדי שלא יהא רגיל לנדור בו:"],[7,"ועבר על נזירותו","דכסבור בטעות נדר ואחרי כן בא לישאל:"],[7,"אין נזקקין לו","לפתוח לו בחרטה:"],[7,"נזירות מועטת","שקבל עליו נזירות ל' יום אבל אם קיבל נזירות מרובה ועבר ושתה ק' יום אין אומרים ינהג איסור ק' יום שנהג היתר אלא לעונש ל' יום כסתם נזירות הכי נמי עונשין אותו שינהג איסור בנדרו וכימים שעכב כל נדרו דכשאמר לא נדרתי אלא בחרמו של ים ונהג היתר בנדר עד לאחר זמן שעלה בדעתו לישאל:"],[8,"בי דינא דמזדקקי ליה","קודם שינהוג איסור בעצמו לא עביד שפיר:"],[9,"שסופך למעול בנדרים","אם תרבה לנדור:"],[12,"שהופכין","פנים כנגד עורף שבאים על נשותיהן שלא כדרכן:"],[12,"שהופכים שולחנן","היא למעלה והוא למטה:"]],[[0,"ואמר לא נדרתי אלא בחרמו של ים","לשון מצודה לשון משטח חרמים תהיה בתוך הים (יחזקאל כ״ו:ה׳):"],[1,"לא נדרתי אלא בעצם","אחד של בהמה שהנחתי בתיבתי להיות נודר בו להטעות העולם להאמין דברי שיהו סבורים כי אני נודר נדר גמור:"],[2,"כולן אין נשאלין עליהם","ואין צריכין שאלה בת\"ח אבל ע\"ה שבא לישאל עונשין אותו כדקאמר בגמרא שאם נוהג היתר בנזירות על ידי טעמים הללו שהוא אמר עכשיו שלא היה חושבו נדר אע\"פ שאינו נדר ולבסוף בא לישאל עליו לפי שלבו טרפו שמא נדר גמור הוא עונשין אותו לנהוג איסור כימים שנהג בה היתר:"],[2,"ומחמירין עליו","מפרש בגמרא דלא פתחינן בחרטה לומר לבך עלך או כדו תהית אלא צריך לומר לו דאדעתא דהכי לא נדר דזהו חרטה גמורה כדפי' ר\"ת:"],[3,"וחכ\"א פותחין לו פתח ממקום אחר","פר\"ת פותחין לו פתח ממקום אחר כדאמרת כלומר זאת החומרא אני מודה לך דלא פתחינן ליה בחרטה אלא צריך לבקש לו פתח ממקום אחר דהיינו אדעתא דהכי לא נדר אבל מיענש לא מיענשי ליה וקשה אם כן אמאי שביק לישנא דמתני' דמחמירין עליו דאמר ת\"ק הואיל ולא פליגי עליה דמחמירין ונקט בלישנא אחרינא פותחין הוה ליה למימר מחמירין ועוד דבירושלמי משמע דפליגי רבנן עליה אף במחמירין עליו לכך נראה לר\"י דרבנן פליגי אף במחמירין עליו דפותחין ממקום אחר לאפוקי שלא יתירו לו [מגופו של] נדר כלל כיון שהיה בדעתו לקרבנות מלכים וכיוצא בהן אלא מבקשין לו ממקום אחר כמו בשאר נדרים או על ידי פתח דאדעתא דהכי לא נדרת [או] ע\"י חרטה [דכדו] וכן פי' התוס' לעיל גבי האומר הרי את עלי כבשר [אימא] פותחין לו פתח ממקום אחר וכן פר\"י כרבי יהודה:"],[4,"אמר מר אין נשאלין","לשון נדרים משונה הוא מדתניא אין נשאלין דמשמע דמקיל סתם אין צריכין שאלה והדר תני אם נשאלין אלמא משמע דבעי שאלה לא קשיא הא בת\"ח כדפי' המשנה:"],[5,"אבל בעם הארץ שבא לישאל","יש לספק דמשמע דוקא נקט בא לישאל אבל לא בא לישאל לא אמרינן ליה:"],[7,"מי שנזר ועבר על נזירותו","ששתה יין כדמוכח בירושלמי:"],[7,"אין נזקקין לו","להתיר עד שינהוג איסור כימים שנהג בהן היתר:"],[7,"א\"ר יוסי בד\"א בנזירות מועטת","דאינו כ\"א שלשים יום:"],[7,"אבל נזירות מרובה","כגון שנה או שנתים וכו' והשתא עונשין אותו היינו כי הכא לנהוג איסור כימים שנהג בהן היתר ורבנן פליגי במתניתין גבי קרבנות מלכים אבל בשאר נדרים גמורים אפילו רבנן מודו דעונשין אותו אם עבר על נזירותו ואין נזקקין לו עד שינהוג איסור כימים שנהג בהן היתר ואפשר דאף ר' יוסי דאמר בנזירות מרובה דיו שלשים יום היינו דוקא בנזירות דסתם נזירות שלשים יום אבל בנדרים דאין סתם נדר ל' יום אלא לעולם אפי' ר' יוסי מודה עד שינהוג איסור כימים שנהג בהן היתר אף בנדר מרובה ומיהו בתוספתא (ספ״א) קתני האי פלוגתא דר' יוסי ור' יהודה בלשון נדר ולא בלשון נזירות ואפ״ה א״ר יוסי בנדר מרובה שלשים יום ותימה מה ענין ל' יום לנדר ויש רוצים לדקדק מזה דסתם נדר ל' יום ול״נ דהא אמר בפרק קמא (דף ד:) נדר לית ליה קיצותא לכ״נ דאע״ג דסתם נדר לעולם מ״מ אין סברא להחמיר בנדר יותר מבנזירות שיש בה קרבן ולכך אמר ר' יוסי ל' יום כמו בנזירות ולכאורה היה נראה דהלכה כרבי יוסי דרבי יהודה ורבי יוסי הלכה כרבי יוסי ואם כן בנדר גמור נמי אם עבר על נדרו דיו שלשים יום כדמשמע בתוספתא דאף בנדר פליג רבי יוסי ומיהו הדעת נוטה דהלכה כר' יהודה דבפרק ב״ש (נזיר דף לד.) מייתי הש״ס להך ולא מדכרא התם רבי יהודה כלל אלא קתני סתם מילתיה ועוד [דקרו] התם בכולה סוגיא מילתא דרבי יהודה רבנן דקאמר מתני' לא רבי יוסי ולא רבנן משמע דהלכה כוותיה מדקרי ליה רבנן ולענין מתני' דחרם צ״ע דנימא הלכה כר״מ משום דהלכה כר״מ בגזירותיו (כתובות נז.) בחומרותיו ושמא לא חשבינן ליה הלכה כר״מ בגזירותיו אלא בקנסותיו:"],[9,"אל תהי רגיל בנדרים שסופך למעול בנדרים","ויש ספרים דגרסי שסופך למעול בשבועות פירוש אף בשבועות החמורות שכתוב בהם לא ינקה ויש ספרים דגרסינן בהדיא אף בשבועות והא דאמר נדרים סייג לפרישות מפרש ר\"ת כגון שנודר לקיים המצוה כמו אשנה פרק זה או אעשה מצוה זו:"],[10,"הויין ליה בנים שאינם מהוגנים","מדה כנגד מדה לפי שמסתכל בעקיבה של אשה שזהו ענין הערוה לכך הויין ליה בנים שאינן מהוגנים:"],[12,"חגרים מפני שהופכים שולחנם","פי' שמשמשים מטותם שלא כדרכם ולפי שמשנים תשמישן בדבר התלוי בירכים אף בניהם לוקים בירכים הר\"י:"],[12,"מפני שמנשקים באותו מקום","ולכך לוקים הוולדות בפיהם:"],[12,"מפני שמספרים בשעת תשמיש","שיש להם לשמש בהצנע והם משמיעים קולם לכך נעשים הולדות חרשים:"]]],[["בניך יפיפין ביותר אמרה להן אינו מספר עמי לא בתחלת הלילה ולא בסוף הלילה אלא בחצות הלילה וכשהוא מספר מגלה טפח ומכסה טפח ודומה עליו כמי שכפאו שד","ואמרתי לו מה טעם ואמר לי כדי שלא אתן את עיני באשה אחרת ונמצאו בניו באין לידי ממזרות","לא קשיא הא במילי דתשמיש הא במילי אחרנייתא","אמר רבי יוחנן זו דברי יוחנן בן דהבאי אבל אמרו חכמים אין הלכה כיוחנן בן דהבאי אלא כל מה שאדם רוצה לעשות באשתו עושה משל לבשר הבא מבית הטבח רצה לאוכלו במלח אוכלו צלי אוכלו מבושל אוכלו שלוק אוכלו וכן דג הבא מבית הצייד","אמר אמימר מאן מלאכי השרת רבנן דאי תימא מלאכי השרת ממש אמאי אמר רבי יוחנן אין הלכה כיוחנן בן דהבאי הא אינהו בקיאי בצורת הולד טפי ואמאי קרו להו מלאכי השרת דמצייני כמלאכי השרת","ההיא דאתאי לקמיה דרבי אמרה לו רבי ערכתי לו שולחן והפכו אמר לה בתי תורה התירתך ואני מה אעשה ליך ההיא דאתאי לקמיה דרב אמרה לו רבי ערכתי לו שולחן והפכו אמר מאי שנא מן ביניתא","ולא תתורו אחרי לבבכם מכאן אמר רבי אל ישתה אדם בכוס זה ויתן עיניו בכוס אחר אמר רבינא לא נצרכא אלא דאפילו שתי נשיו","וברותי מכם המורדים והפושעים בי אמר רבי לוי אלו בני תשע מדות בני אסנ\"ת משגע\"ח","בני אימה בני אנוסה בני שנואה בני נידוי בני תמורה בני מריבה בני שכרות בני גרושת הלב בני ערבוביא בני חצופה","איני והאמר רבי שמואל בר נחמני אמר רבי יונתן כל אדם שאשתו תובעתו הויין לו בנים שאפילו בדורו של משה רבינו לא היו כמותם שנאמר הבו לכם אנשים חכמים ונבונים וכתיב ואקח את ראשי שבטיכם ולא כתיב נבונים","וכתיב יששכר חמור גרם וכתיב מבני יששכר יודעי בינה לעתים","ההיא דמרציא ארצויי:","\u0001הדרן עלך ואלו מותרין\u0002","מתני׳ \u0001ארבעה\u0002 נדרים התירו חכמים נדרי זרוזין ונדרי הבאי ונדרי שגגות ונדרי אונסין נדרי זרוזין כיצד היה מוכר חפץ ואמר קונם שאיני פוחת לך מן הסלע והלה אומר קונם שאיני מוסיף לך על השקל"],[[0,"אינו מספר","אינו משמש:"],[0,"מגלה טפח","מבגדה:"],[0,"ומכסה","אותו טפח מבגד וכן עושה עד שיבא עליה:"],[0,"ודומה כמי שכפאו שד","שבא אליה בכח ודומה כמי ששד כפאו ואית דאמרי שמתכסה כולו כאדם שמפחד מן השד:"],[4,"דמצייני","שעטופים בציצית:"],[5,"ביניתא","דג שיכול לאכלו כמו שירצה:"],[7,"בני אסנ\"ת משגע\"ח","סימן הוא:"],[8,"שנואה","שלבו על אחרת בשעת תשמיש ואמרו כשבא עליה לאו ביאה גמורה היא הואיל וכל כך שונאה אלא כזנות בעלמא הוא:"],[8,"בני נידוי","שהבעל בנידוי ובא עליה ומתעברת הימנו:"],[8,"בגי תמורה","שיש לו ב' נשים וכסבור לבא על זו ובא על אחרת. ל\"א בני תמורה שהוא סבור לבא על אשה אחרת ונמצאת שהיא אשתי וקרובין לממזרות שהרי נתכוון לניאוף:"],[8,"בני מריבה","שמשמש במריבה:"],[8,"בני שכרות","שמשמש בשכרות דביאתו לאו ביאה גמורה אלא כביאת זנות היא שאין. מתכוון אלא לבעול בעלמא:"],[8,"בני ערבוביא","שבא על אשה אחת בין הנשים ואין ידוע על איזו מהן בא. ל\"א שבאו עליה אנשים הרבה ואין ידוע בן מי הוא ל\"א בני ערבוביא ספק בן תשעה לראשון או בן שבעה לאחרון:"],[10,"יששכר חמור גרם","חמור גרם ליששכר שנולד אותו חמור שהיה יעקב רוכב שפנה לאהל לאה:"],[11,"דמרציא ארצויי","אינה תובעת בפה אלא דמרציא קמיה מראה לו מתוך דבריה כגון לאה דמההיא נפקי בני מעליא:"],[12,"","הדרן עלך ואלו מותרין"],[13,"ארבעה נדרים התירו חכמי'","בלא שום שאלה:"],[13,"נדרי זירוזין כו' מן הסלע","שהוא ארבע דינרין:"],[13,"והלה","הקונה אומר שאינו מוסיף לו על שקל שהוא שני דינרין:"]],[[13,"מתני' ארבעה נדרים","עד השתא איירי בכינויי האסורין ובכינויי המותרים במתפיס בדבר הנדור ובמתפיס בדבר המותר והשתא מיירי בנדרים דאע\"ג דהוציאם מפיו בלשון שאר נדר אפילו הכי מותרין וטעמא הוי משום דבעינן פיו ולבו שוין ואנן סהדי דלא שוו פיו ולבו בהני ד' נדרים והיינו טעמא דלא פריך בגמרא והא דברים שבלב כדפריך לקמן אנדרי אונסין משום דבעינן פיו ולבו שוין ונדרי זירוזין שריין מהאי טעמא:"],[13,"נדרי הבאי","גוזמא והבאי לשון אחרים:"],[13,"מתני' ארבעה נדרים","עד השתא איירי בכינויי האסורין ובכינויי המותרים במתפיס בדבר הנדור ובמתפיס בדבר המותר והשתא מיירי בנדרים דאע\"ג דהוציאם מפיו בלשון שאר נדר אפילו הכי מותרין וטעמא הוי משום דבעינן פיו ולבו שוין ואנן סהדי דלא שוו פיו ולבו בהני ד' נדרים והיינו טעמא דלא פריך בגמרא והא דברים שבלב כדפריך לקמן אנדרי אונסין משום דבעינן פיו ולבו שוין ונדרי זירוזין שריין מהאי טעמא:"]]],[["שניהם רוצין בשלושה דינרין","\u0001גמ׳\u0002 ארבעה נדרים התירו חכמים כו' אמר ליה רבי אבא בר ממל לרבי אמי אמרת לן משמיה דרבי יהודה נשיאה מאן תנא ארבעה נדרים רבי יהודה היא דאמר משום רבי טרפון לעולם אין אחד מהן נזיר לפי שלא ניתנה נזירות אלא להפלאה","רבא אמר אפילו תימא רבנן מי קתני שניהן רצו שניהן רוצין קתני","אמר ליה רבינא לרב אשי אמר לו טפי מסלע והלה אמר בציר משקל נדרא הוי או זירוזין הוי","אמר ליה תנינא היה מסרב בחבירו שיאכל אצלו ואמר לו קונם ביתך שאני נכנס טיפת צונן שאני טועם מותר ליכנס לביתו ולשתות הימנו צונן שלא נתכוון זה אלא לשום אכילה ושתיה","ואמאי והא טיפת צונן קאמר אלא משתעי איניש הכי הכא נמי משתעי איניש הכי","אמר ליה"],[[0,"שניהם רוצין בשלשה דינרין","כלומר זה הנשבע שאינו פוחת לו מן הסלע לא היה פיו ולבו שוין לכך שלא יפחות לו מן הסלע כלום אלא להכי נדר כן לזרז את חבירו שיתן לו ג' דינרין הוא רוצה לבא וזה שנשבע שלא ליתן לו יותר משקל לא היה פיו ולבו שוין שלא היה בדעתו שלא יתן יותר אלא לכך נדר שיתן לו בג' דינרין ולפיכך מותרין:"],[1,"גמ' מאן תנא","התירו חכמים:"],[1,"ר' יהודה היא דאמר אין אחד מהן נזיר","דלא סמכא דעתייהו ממש לשם נזירות אלא תלו נזירותן בזה שבא כנגדן ולא היה פיו ולבו שוין להכי אין אחד מהם נזיר ה\"נ לא סמכא דעתייהו בשעת הנדר דכל חד וחד אדעתא דחבריה כדי לזרזו ולא הי' פיו ולבו שוים להכי דאי רבנן דפליגי עליה דר' יהודה דאמרי אע\"ג דלא סמכא דעתייהו להיות נודר ממש בנזיר דתלה נזירות באחר הוי נזיר אותו שנתקיימו דבריו ה\"נ אף על גב דלא סמכא דעתייהו אדבור פיהן שלא נתכוונו אלא לזרז אסורים דאמרינן כשנדרו ודאי סמכא דעתייהו דזה לא יפחות מסלע וזה לא יוסיף על שקל והרי פיהן ולבן שוים ואסור:"],[2,"רבא אמר אפי' תימא רבנן","דפליגי עליה דר' יהודה:"],[2,"מי קתני שניהן רצו","דאי קתני הכי הוה משמע שניהן רצו בתחלה בשלשה דינרין ואלא עכשיו בשעת הנדר אין רוצין אלא סמכא דעתייהו אדבור פיהן ופיהן ולבן שוים ונדר מעליא הוי:"],[2,"רוצין תנן","דמשמע מעיקרא היו רוצין בג' דינרין ואכתי שניהן נמי רוצין ולא היה פיהן ולבן שוין הלכך אפילו רבנן מודו דמותרין וכדי לזרז זה את זה נתכוונו שניהן:"],[3,"אמר לו טפי מסלע והלה אומר בציר משקל","היכא דאמר שאינו פוחת מסלע וזה אומר שאינו מוסיף על שקל כיון דדברי שניהם קרובין לשלשה דינרין אמרינן דנדרי זרוזין הוו אבל הכא כיון דאמר טפי מסלע דהיינו פרוטה והלה אומר קונם שאיני מוסיף לך על פרוטה פחות משקל דהשתא מרחקי מילתייהו משלשה דינרין כיון דדייקי הכי נדרא הוי ואסורים או לא דזירוזין הוה:"],[4,"היה מסרב","שהיה מפצירו לאכול אצלו מעט:"],[4,"קונם ביתך שאני נכנס","שנדר שלא יכנס לביתו:"],[4,"וטיפת צונן שאני טועם","שלא לאכול אצלו כלום:"],[4,"מותר ליכנס לביתו ולאכול קימעא ולשתות הימנו טיפת צונן","אבל לא אכילה מרובה:"],[4,"שלא נתכוון זה","המסרב אלא לשום אכילה מרובה שיסעוד אצלו הרבה ולשון טיפת צונן לא נתכוון זה שהיא שתיה מועטת:"],[5,"והא טיפת צונן קאמר","דמשמע שתיה מועטת ואכילה מועטת:"],[5,"אלא משתעי איניש הכי","דכי אמר (טיפת צונן) יאכל עמו ודאי לאכילה מתכוון וכי נדר זה שאינו טועם עמו טיפת צונן ודאי לאכילה מרובה נתכוון ולהכי מותר לשתות טיפת צונן:"],[5,"ה\"נ משתעי איניש הכי","דכי נתכוון ליתן שלשה דינרין אומר שאינו מוסיף על פרוטה פחות משקל ולעולם נדרי זירוזין הוו ואפילו דאמר טפי מסלע ובציר משקל:"]],[[1,"אלא להפלאה","וא\"ת והא גבי נדרים לא כתב יפליא וי\"ל דילפינן מהדדי משום דאתק' נדרים לנזירות:"],[1,"מספיקא לא משעבד נפשיה","וה\"נ במתניתין אע\"ג דבשעת הנדר לא היה דעת זה וזה בג' דינרין אלא הוה דעתיה להוריד כמה שיוכל לזה דלמא בשעת הנדר מספקא ליה אם חל נדר אם לאו דשמא יתן לו סלע או יתן לו בב' דינרין מספיקא לא משעבד נפשיה:"],[2,"רבא אמר","לא היו מסופקין אפי' תימא רבנן מי קתני שניהן רצו דהוה משמע רצו לבסוף ולא מתחלה רוצים קתני משמע דמתחלה כשנודרים היו רוצים בג' אלו שהיו ואנן סהדי דדעתן לכך הלכך לאו נדר הוא כלל דדוקא כשאמר המוכר לבסוף שכך היה דעתו מתחלה כדפרישית אבל אם אמר שדעתו למה שהיו אומרים מכוונת לבם לכך התם אין נדרי זירוזין דהוי נדר קיים ודלא כרבי יהודה משום רבי טרפון:"]]],[["מי דמי גבי צונן צדיקים אומרים מעט ועושין הרבה","הכא ספיקא הוא דלמא פחות מסלע ויותר על שקל קאמר וזירוזין הוי או דלמא דווקא קאמר ונידרא הוי תיבעי","אמר רב יהודה אמר רב אסי ארבעה נדרים הללו צריכין שאלה לחכם כי אמריתא קמיה דשמואל אמר תנא תני ארבעה נדרים התירו חכמים ואת אמרת צריכין שאלה לחכם","רב יוסף מתני לה להא שמעתא בהאי לישנא אמר רב יהודה אמר רב אסי אין חכם רשאי להתיר אלא כעין ארבעה נדרים הללו קסבר אין פותחין בחרטה","ההוא דאתא לקמיה דרב הונא אמר ליה ליבך עלך אמר ליה לא ושרייה","ההוא דאתא לקמיה דרבה בר רב הונא אמר ליה אילו היו עשרה בני אדם שיפייסוך באותה שעה מי נדרת אמר ליה לא והתירו","תניא רבי יהודה אומר אומרים לו לאדם לב זה עליך אם אמר לאו מתירין אותו רבי ישמעאל ברבי יוסי אומר משום אביו אומרים לו לאדם אילו היו עשרה בני אדם שיפייסוך באותה שעה מי נדרת אם אמר לאו מתירין אותו","(סימן אסי ואלעזר יוחנן וינאי)","ההוא דאתא לקמיה דרבי אסי אמר ליה כדו תהית אמר ליה לא ושרייה ההוא דאתא לקמיה דרבי אלעזר אמר ליה בעית נדור אמר ליה אילו לא מרגזין לי לא בעינן כלום אמר ליה תהא כבעית ההיא איתתא דאדרתה לברתה אתאי לקמיה דרבי יוחנן אמר לה אילו הוה ידעת דאמרן מגירתיך עלה דברתך"],[[0,"מי דמי גבי צונן צדיקים אומרים מעט ועושין הרבה","וזה שהיה מסרב בחבירו שיאכל אצלו קימעא וישתה טיפת צונן ודאי לאכילה ושתיה מרובה קאמר כי כן דרכן של צדיקים לומר מעט ולעשות הרבה וכי אמר ליה האי קונם טיפת צונן שאני טועם הכי נתכוון לומר אותה טיפה שאתה רוצה ליתן לי איני טועם דהיינו אכילה מרובה ולא נתכוון לטיפת צונן ממש הלכך . אסור באכילה ושתיה מרובה ומותר לשתות הימנו טיפת צונן אבל הכא דדילמא האי דאמר טפי מסלע דעתיה על פחות מסלע ליתן בשלשה דינרין והאי דאמר בציר דעתיה על יותר משקל ליתן ג' דינרין:"],[1,"וזירוזין הוי","ומותר:"],[1,"או דלמא דוקא קאמר ונדרא הוי","ואסור:"],[3,"אלא כעין ד' נדרים [הללו]","והני הוא דשרו משום דלית בהו ממש אבל שאר נדרים אין אדם רשאי להתיר עד שיתחרט הנודר מעצמו:"],[3,"קסבר אין פותחין בחרטה","שאין חכם רשאי לפתוח ולומד לו נדרת אדעתא דהכי כדאמרינן לקמן אלא הנודר הוא יתחרט תחלה ויפתח ויאמר לו לא לדעת כן נדרתי והוא פותח תחלה בחרטה:"],[4,"אמר ליה לבך עלך","כלומר עומד אתה על דעת הראשונה שרצונך עדיין באותו נדר:"],[4,"אמר ליה לא","כלומר מתחרט אכי אלמא קסבר פותחין בחרטה:"],[5,"אם היו י' בני אדם כו'","שאם פתחו לך בחרטה כשרצית לנדור כלום נדרת:"],[5,"אמר ליה לאו","קסבר אין פותחין בחרטה ולכך אמר ליה כה\"ג דכיון דאמר אילו היו י' בני אדם כו' דמיעקר עקר לנדריה ולא הוי נדר כלל ולכך פותח בחרטה הוא אבל בעלמא אין פותחין בחרטה:"],[6,"","קסבר רבי ישמעאל ברבי יוסי אין פותחין בחרטה:"],[8,"תהית","מצטער אתה:"],[8,"כדו תהית","מצטער אתה שנדרת דהיינו בחרטה:"],[8,"בעית נדור","קיבלת הנדר מרצונך:"],[8,"אי לא מרגזין לי","אלמלא שהכעיסוני לא הייתי נודר:"],[8,"דאמרן מגירתיך","שאומרות השכינות על בתך כמו ומגרת ביתה (שמות ג):"]],[[3,"ורב יוסף נמי מתני לקולא","אפילו לרב אסי כדאמר דהלכתא דד' נדרים אין צריכין שאלה דבשל סופרים הלך אחר המיקל וכן פסק הר\"ר אליעזר ממי\"ץ בשם רבי יעקב:"],[3,"אלא כעין ארבעה נדרים","שפותחין ואומרין (לאו) אדעתא דהכי מי נדרת והוא אומר לא נתכוון לנדור אלא כעין ד' נדרים שלא נתכוון בהם לאיסור:"],[3,"קסבר אין פותחין לנודר בחרטה","לומר לו מתחרט אתה שהיית רוצה שלא יהיה עליך נדר מתחלה דההוא פתח לא משוי ליה בהדיא נדר טעות אלא אומר לו אדעתא דהכי נדרת והוא אומר אילו ידעתי כן לא הייתי נודר דמשוי ליה נדר טעות מעיקרא:"],[4,"אמר ליה לבך עלך","פי' לבך שהיה עליך בשעת נדר יש בו עליך עדיין ואין אתה מתחרט מעיקרא אלא מכאן ולהבא:"],[4,"אמר ליה לא","אלא מתחרט אני על שנדרתי כל עיקר ודוקא כשמתחרט מעיקרא כדפרישית אבל אם אינו מתחרט מעיקרא אלא מכאן ולהבא לכ\"ע אין פותחין בחרטה זו:"],[4,"ושרייה","דקסבר פותחין בחרטה."]]],[["אילו לא חמאת בה אימה מילין דעזיבה בכדי לא אדרתה מי אדרתה אמרה ליה לא ושרייה","בר ברתיה דרבי ינאי סבא אתא לקמיה דרבי ינאי סבא אמר ליה אילו הוה ידעת דפתחין פינקסך וממשמשין בעובדך מי נדרת אמר ליה לא ושרייה","אמר רבי אבא מאי קראה ואחר נדרים לבקר ואף על גב דפתח רבי ינאי ליה אנן לא פתחינן ליה בהא","ולא פתחינן בהדא אחרנייתא דאמר רבה בר בר חנה אמר רבי יוחנן מאי פתח ליה רבן גמליאל לההוא סבא יש בוטה כמדקרות חרב ולשון חכמים מרפא כל הבוטה ראוי לדוקרו בחרב; אלא לשון חכמים מרפא.","ולא פתחינן בהדא אחרנייתא דתניא רבי נתן אומר הנודר כאילו בנה במה והמקיימו כאילו מקריב עליו קרבן ברישא פתחינן בסיפא אביי אמר פתחינן רבא אמר לא פתחינן","רב כהנא מתני לה להא שמעתא בהדין לישנא... רב טביומי מתני הכי בסיפא לא פתחינן ברישא אביי אמר פתחינן רבא אמר לא פתחינן והלכתא לא פתחינן לא ברישא ולא בסיפא","ולא פתחינן בהא נמי דשמואל דאמר שמואל אף על פי שמקיימו נקרא רשע אמר רבי אבהו מאי קרא וכי תחדל לנדור לא יהיה בך חטא ויליף חדלה חדלה כתיב הכא כי תחדל לנדור וכתיב התם שם רשעים חדלו רוגז","אמר רב יוסף אף אנן נמי תנינא כנדרי כשרים לא אמר כלום כנדרי רשעים נדר בנזיר ובקרבן ובשבועה","אמר רבי שמואל בר נחמני אמר רבי יונתן כל הכועס כל מיני גיהנם שולטין בו שנאמר והסר כעס מלבך והעבר רעה מבשרך ואין רעה אלא גיהנם שנאמר כל פעל ה' למענהו וגם רשע ליום רעה","ולא עוד אלא שהתחתוניות שולטות בו שנאמר ונתן ה' לך שם לב רגז וכליון עינים ודאבון נפש איזהו דבר שמכלה את העינים ומדאיב את הנפש הוי אומר אלו התחתוניות","עולא במיסקיה לארעא דישראל איתלוו ליה תרין בני חוזאי בהדיה קם חד שחטיה לחבריה אמר ליה לעולא יאות עבדי אמר ליה אין ופרע ליה בית השחיטה כי אתא לקמיה דרבי יוחנן אמר ליה דילמא חס ושלום אחזיקי ידי עוברי עבירה אמר ליה נפשך הצלת","קא תמה רבי יוחנן מכדי כתיב ונתן ה' לך שם לב רגז בבבל כתיב אמר ליה ההוא שעתא"],[[0,"אילו לא חמאת בה אימה","אילולי שראתה בה אימה:"],[0,"מילין דעזיבה","דברים שיפין להניחן כלומר דבר זימה:"],[0,"בכדי לא אדרת","בחנם לא היתה מדירתה ומלעיזין עליה מי היית מדירה הכא ליכא למשמע אי פותחין אי לא:"],[1,"שמבקרין מעשיך","בב\"ד של מעלה בשביל שנדרת:"],[2,"מאי קראה","שמפני נדרים חוקרין מעשיו של אדם:"],[2,"ואחר נדרים לבקר","שאם נודר מבקרין מעשיו:"],[3,"ולא פתחינן","לשום אדם בהאי אחר נדרים לבקר משום דהוי איום גדול שאפי' אין דעתו להפר יאמר עכשיו שרצונו להפר ולא בהני תרתי אחרנייתא נמי משום דהוי איום גדול ואומר שדעתו להפר ואינו כן:"],[3,"כל הבוטה","כל הנודר כמו מבטא שפתיה (במדבר ל):"],[3,"ולשון חכמים מרפא","שמתירין לו:"],[4,"כאילו בנה במה","לעבודת כוכבים:"],[4,"ברישא פתחינן","בתחילת דבריו של ר' נתן דאמר כאילו בנה במה פתחינן ליה דלא הוי עונשו יתירא כל אימת דלא עבד עלה קרבן וליכא איום כל כך אבל בסיפא כאילו מקטיר עליה מתחייב מיתה היינו איום יתירא:"],[5,"בסיפא","דברי הכל לא פתחינן:"],[6,"כי תחדל לנדור לא יהיה בך חטא","מכלל דאי נדר ועבד ליה איכא חטא:"],[7,"כנדרי רשעים","אע\"פ שנודרים ומקיימין איקרו רשעים:"],[9,"לב רגז","היינו כעס בשביל לב רגז יהיה כליון עינים:"],[10,"במיסקיה","כשעלה לא\"י:"],[10,"איתלוו","עשו לו לוייה:"],[10,"בני חוזאי","יהודים היו:"],[10,"א\"ל אין ופרע לו בית שחיטה","ונתיירא לומר לו שלא עשה יפה שמא יהרגנו:"],[10,"כי אתא","עולא לקמיה דרבי יוחנן:"],[10,"אמר דלמא אחזיקי ידי עוברי עבירה","שאמרתי לו זיל ופרע בית שחיטה:"],[10,"א\"ל יפה עשית","שכך אמרת לו שנפשך הצלת באותו דיבור:"],[11,"תמה ר' יוחנן","על דהוה ליה לההוא בר חוזאה כעס כל כך שהרג לחבירו הואיל דהוה בארץ ישראל:"]],[]],[["לא עברינן ירדנא","אמר רבה בר רב הונא כל הכועס אפילו שכינה אינה חשובה כנגדו שנאמר רשע כגובה אפו בל ידרוש אין אלהים כל מזמותיו רבי ירמיה מדיפתי אמר משכח תלמודו ומוסיף טיפשות שנאמר כי כעס בחיק כסילים ינוח וכתיב וכסיל יפרוש אולת רב נחמן בר יצחק אמר בידוע שעוונותיו מרובין מזכיותיו שנאמר ובעל חימה רב פשע","אמר רב אדא ברבי חנינא אלמלא (לא) חטאו ישראל לא ניתן להם אלא חמישה חומשי תורה וספר יהושע בלבד [מפני] שערכה של ארץ ישראל הוא מאי טעמא כי ברוב חכמה רב כעס","אמר רבי אסי אין נזקקין לאלהי ישראל חוץ מקונם אשתי נהנית לי שגנבה את כיסי ושהכתה את בני ונודע שלא גנבה ושלא הכתו","ההיא דאתאי לקמיה דרב אסי אמר לה במאי נדרת באלהי ישראל אמר לה אי נדרת במוהי שהיא כינוי בעלמא מזדקיקנא לך השתא דלא נדרת במוהי אלא באלהי ישראל לא מזדקיקנא לך","רב כהנא איקלע לבי רב יוסף אמר ליה לטעום מר מידי אמר ליה לא מרי כולא לא טעימנא ליה אמר ליה לא מרי כולא לא טעימת ליה הניחא לרב כהנא דאמר לא מרי כולא אלא לרב יוסף אמאי אמר לא מרי כולא הכי הוא דקאמר ליה לא מרי כולא הוא דקאמרת הלכך לא טעימת ליה","אמר רבא אמר רב נחמן הלכתא פותחין בחרטה ונזקקין לאלהי ישראל","משתבח ליה רבא לרב נחמן ברב סחורה דאדם גדול הוא אמר לו כשיבא לידך הביאהו לידי הוה ליה נדרא למישרא אתא לקמיה דרב נחמן","אמר ליה נדרת אדעתא דהכי אמר ליה אין אדעתא דהכי אין כמה זימנין איקפד רב נחמן אמר ליה זיל לקילעך","נפק רב סחורה ופתח פיתחא לנפשיה רבי אומר איזו היא דרך ישרה שיבור לו האדם כל שהיא תפארת לעושיה ותפארת לו מן האדם והשתא דאיקפד רב נחמן אדעתא דהכי לא נדרי ושרא לנפשיה","רבי שמעון ברבי הוה ליה נדרא למישרא אתא לקמייהו דרבנן אמרי ליה נדרת אדעתא דהכי אמר אין אדעתא דהכי אין כמה זימנין"],[[0,"לא עברינן ירדנא","עדיין לא עברנו את הירדן כשאירע אותו מעשה ולא הוינן בתחום א\"י:"],[1,"כגובה אפו","שיש לו חרון:"],[1,"אין אלהים כל מזמותיו","במחשבותיו אין שכינה חשובה כנגדו:"],[1,"יפרוש אולת","שמשתטה:"],[1,"רב פשע","שפשעיו מרובים:"],[2,"מפני שערכה של ארץ ישראל הוא","שכתוב בו ערך חלק של כל שבט ושבט ולא סגיא בלאו הכי ולפי שבעטו וחטאו נוסף להם רוב חכמה שאר הספרים להטריחן יותר:"],[3,"אין נזקקין","להתיר לו נדרו לפי שנדר חמור הוא:"],[3,"חוץ מקונם אשתי נהנית לי","שאפילו נדר באלהי ישראל שאין אשתי נהנית לי נזקקין להתיר לו לפי שאמרה תורה שמי שנכתב בקדושה ימחה על המים בידים לעשות שלום בין איש לאשתו לא כ\"ש האי נדר אי נדר באלהי ישראל שהוא לשון נדר:"],[5,"לא מרי כולא","שהוא נשבע באדון העולם לא אוכל א\"ל רב יוסף לא מרי כולא לא טעימת ליה הכי קאמר רב יוסף לא מרי כולא קאמרת בודאי לא טעימת ליה שאסור להתיר לך דהיינו כמי שנשבע באלהי ישראל:"],[5,"","[חסר הנה והעתקתיו מפירוש רבינו גרשום]"],[5,"הניחא לרב כהנא","לפי שהיה מסרב בו רב יוסף נדר הכי אלא רב יוסף אמאי קאמר נמי לא מרי כולא:"],[5,"[ה\"ק לא מרי כולא קאמרת]","בתמיה קא\"ל רב יוסף כדאמרן:"],[8,"איקפד רב נחמן","שלא היה יכול לומר לו דבר שהוא פתח לחרטה:"],[8,"אמר ליה זיל לקילעך","לביתך הואיל ואיני יודע לפתוח לך:"],[9,"כל שהיא תפארת לעושיה ותפארת לו מן האדם","שיהא דבר מקובל נמי בעיני הבריות הוי תפארת לעושיה והואיל דאיקפד רב נחמן שאין מתקבל עליו שנדרו חמור כ\"כ שאינו יכול למצוא לו פתח אדעתא דהכי והכי לא נדרי:"]],[[3,"אין נזקקין לאלהי ישראל","דכיון שנשבע בשם שמים אין נזקקים לו: חוץ מקונם אשתי נהנית לי שגנבה את כיסי ושהכתה את בני ונודע לו שלא הכת' - וריצב\"א ל\"ג ונודע לו שלא הכתה דאם כן אפי' התרה נמי לא בעי דאמר כשם שנדרי שגגות מותרות כך שבועות שגגות מותרות אלא הכי גרסינן חוץ מקונם אשתי נהנית לי ותו לא ומיירי שהוא אמת שגנבה כיסו ושהכתה את בנו דהשתא בעי התרת חכם וקאמר דאפי' נשבע באלהי ישראל נזקקין להתירו משום שלום בית:"],[9,"לעושיה","להקב\"ה ותפארת לו מן האדם שבני אדם מקלסים אותו:"],[9,"והשתא דאיקפד רב נחמן אדעתא דהכי וכו'","פי' משום דליכא תפארת מן האדם אבל תפארת לעושיה שמא הוה כגון שנדר לקיים דבר מצוה:"],[9,"ושריא לנפשיה","פי' שע\"י פתח זה נתחרט והפר לו נדרו וא\"ת אמאי לא התיר לו רב נחמן מעיקרא ע\"י חרטה דהא רב נחמן גופיה אמר לעיל הלכה פותחין בחרטה וי\"ל דהיינו דוקא כשמתחרט מן הנדר מעיקרא אבל כשאינו מתחרט אלא מכאן ולהבא לא ולכך לא רצה להתירו עד שאמר אדעתא דהכי נדרת:"]]],[["והוו מצטערי רבנן משימשא לטולא ומטולא לשימשא","(לישנא אחרינא אדעתא דהכי אין כמה זימנין והוו מצטערי רבנן משימשא לטולא ומטולא לשימשא)","אמר ליה בטנית בריה דאבא שאול בן בטנית מי נדרת אדעתא דמצערי רבנן מטולא לשימשא ומשימשא לטולא אמר לא ושריוה","רבי ישמעאל בר רבי יוסי הוה ליה נדרא למישרא אתא לקמייהו דרבנן אמרו ליה נדרת אדעתא דהכי אמר להו אין נדרתא אדעתא דהכי אמר להו אין כמה זימנין כיוון דחזא ההוא קצרא דמצטערי רבנן מחייה באוכלא דקצרי אמר אדעתא דמחי לי קצרא לא נדרי ושריה לנפשיה","אמר ליה רב אחא מדיפתי לרבינא האי נולד הוא דלא מסיק אדעתיה דמחי ליה קצרא ותנינא אין פותחין לו בנולד אמר ליה האי לאו נולד הוא דשכיחי אפיקורי דמצערי רבנן","דביתהו דאביי הוה לה ההיא ברתא הוא אמר לקריבאי היא אמרה לקריבה אמר לה תיתסרא הנאתי עלך אי עברת אדעתאי ומינסבת לה לקריבך אזלת ועברת על דעתיה ואינסבא לקריבה אתא לקמיה דרב יוסף אמר ליה אילו הוה ידעת דעברת על דעתך ומנסבא לה לקריבה מי אדרתה אמר לא ושרייה רב יוסף","ומי שרי כי האי גוונא אין והתניא מעשה באדם אחד שהדיר את אשתו מלעלות לרגל ועברה על דעתו ועלתה לרגל ובא לפני רבי יוסי אמר לו ואילו היית יודע שעוברת על דעתך ועולה לרגל כלום הידרתה אמר לו לא והתירו רבי יוסי","\u0001מתני׳\u0002 רבי אליעזר בן יעקב אומר אף הרוצה להדיר את חבירו שיאכל אצלו יאמר לו כל נדר שאני עתיד לידור הוא בטל ובלבד שיהא זכור בשעת הנדר","\u0001גמ׳\u0002 וכיוון דאמר כל נדר שאני עתיד לידור יהא בטל לא שמע ליה ולא אתי בהדיה"],[[0,"והוו מצטערי רבנן","והיו נוסעים משמש לצל ומצל לשמש מרוב תוגה שלא היו יודעין לומר דבר פתח לחרטתו:"],[3,"באוכלא דקצרי","כלי שמשימין בו הכובסין בגדיהן:"],[4,"אין פותחין בנולד","שאין ראוי ליארע כזה אבל הני דאמרן דמצטערי רבנן לאו מילתא דנולד הוא:"],[4,"אמר ליה האי נמי שכיחי אפיקורי דמצערי רבנן","כי האי ולא דמי לנולד:"],[7,"מתני' ר\"א בן יעקב אומר אף הרוצה להדיר את חבירו שיאכל","שאומר לו קונם שאין אתה נהנה לי אם לא תאכל עמי היינו נמי נדרי זרוזין שאינו מדירו אלא כדי לזרזו שיאכל עמו יאמר כל נדר שאני עתיד לידור יהא בטל:"],[8,"גמ' לא שמע ליה","האי מודר ולא אתי למיכל בהדיה הואיל והנדר בטל:"]],[]],[["חסורי מיחסרא והכי קתני הרוצה שיאכל אצלו חבירו ומסרב בו ומדירו נדרי זירוזין הוא והרוצה שלא יתקיימו נדריו כל השנה יעמוד בראש השנה ויאמר כל נדר שאני עתיד לידור יהא בטל ובלבד שיהא זכור בשעת הנדר","אי זכור עקריה לתנאיה וקיים ליה לנדריה אמר אביי תני ובלבד שלא יהא זכור בשעת הנדר","רבא אמר לעולם כדאמרינן מעיקרא הכא במאי עסקינן כגון שהתנה בראש השנה ולא ידע במה התנה והשתא קא נדר אי זכור בשעת הנדר ואמר על דעת הראשונה אני נודר נדריה לית ביה ממשא לא אמר על דעת הראשונה אני נודר עקריה לתנאיה וקיים לנדריה","רב הונא בר חיננא סבר למידרשיה בפירקא אמר ליה רבא תנא קא מסתים לה סתומי כדי שלא ינהגו קלות ראש בנדרים ואת דרשת ליה בפירקא","איבעיא להו פליגי רבנן עליה דרבי אליעזר בן יעקב או לא ואם תימצי לומר פליגי הלכתא כוותיה או לא תא שמע דתנן האומר לחבירו"],[[0,"(אלא) חסורי מחסרא","מתני' והכי קתני הרוצה שיאכל כו':"],[0,"ובלבד שיהא זכור בשעת הנדר","התנאי שהתנה בר\"ה:"],[1,"אי זכור","ואעפ\"כ נדר אם כן עקריה לתנאיה:"],[1,"אלא תני ובלבד שלא יהא זכור","התנאי:"],[2,"לעולם כדאמרינן מעיקרא","ובלבד שיהא זכור בשעת הנדר:"],[2,"והכא במאי עסקי' כגון שהתנה בראש השנה","כל נדר שאני עתיד לידור והיה יודע בשעת התנאי דברים שהוא רגיל לידור בהן ועל דעת כן התנה ושוב שכח ממה שהתנה:"],[2,"והשתא קא נדר אי זכור בשעת הנדר","[שהתנה אבל לא ידע] שבשביל אותו נדר נמי התנה ואמר על דעת הראשונה אני נודר שלא יהא מקוים כמו שהתניתי עליו נדריה לית ביה מששא:"],[2,"לא אמר","בשעת הנדר על דעת הראשונה אני נודר שלא יהא מקוים עקריה לתנאיה וקיים נדריה:"],[3,"סבר למדרשיה בפירקא","בדרשה הרוצה שלא יתקיימו נדריו:"],[3,"א\"ל רבא","סתמה תנא דמתניתין כדי שלא ילמדו ממנה שלא ינהגו קלות ראש בנדרים:"],[4,"פליגי רבנן עליה דרבי אליעזר בן יעקב","בהא דסברי דלא הוי נדרי זירוזין:"]],[[2,"רבא אמר כגון שהתנה ושכח ממה התנה","פי' דהתנה בשעת ביטולו שלא היה מבטל כל נדריו שידור בכל ענין אלא פירש אם אדור בענין זה או מדבר זה יהא בטל ולא מדבר אחר ובשעת הנדר שכח ממה התנה מאיזה דבר בטל והשתא אם אמר בשעת הנדר על דעת הראשונה אני נודר שאם היה התנאי מנדרים אלו שנדרתי רוצה אני שיהיה תנאי שלי קיים דנדריה לית ביה מששא אם נמצא שבטל אותו דבר שנדר שאינו הוא שיהא בטולו קיים לא אמר על דעת הראשונ' - אני עושה כיון שהוא זכור שעשה התנאי בראש השנה ולא חשש לו עתה לומר מספק על דעת הראשונה [אני עושה] א\"כ בטליה לתנאיה ומקיים לנדריה וה\"ה נמי דאם זכור לגמרי מביטולו שאם אמר על דעת הראשונה דנדריה לית ביה מששא דסברא הוא דכיון דעל דעת הראשונה דתנאי הוא עושה ביטולו קיים וא\"ת למה ליה לרבא לדחוק ולהעמידו שהתנה ולא ידע ממה התנה לימא כגון דידע שפיר ממה התנה ונזכר ואמר על דעת הראשונ' אני עושה וי\"ל דזה לא היה שום חידוש כיון שזכר יפה מביטול נדרים שעשה פשיטא דכי אמר על דעת הראשונה אני עושה דנדריה בטל ואם לאו הנדר קיים פי' ר\"י - ורבא פליג [על] אביי ואמר דוקא זכור בשעת הנדר מועיל כדקאמר רבא אם זכור בשעת הנדר משמע דוקא זכור אבל אם אין זכור כלל נדרו קיים דמסתמא דעתו לקיים נדרו כיון שאינו זכור בתנאי והלכתא כרבא דקי\"ל בכולי הש\"ס דאביי ורבא הלכה כרבא הלכך אם אינו זכור אינו מועיל ביטולו ול\"נ דמסתמא דהש\"ס משמע דדבר פשוט הוא דביטולא מועיל שפיר טפי כשאינו זכור מדפריך אדרבא כי זכור בשעת הנדר עקריה וכו' משמע דוקא זכור אבל שכח לא ואין סברא לומר דרבא פליג אסתמא דהש\"ס ועוד דאם אינו מועיל כי אם בששכח מקצת תנאי כדפרישית במתני' נמי מיירי בכה\"ג בששכח ממה שהתנה ויחזור ויתלה בדעת הראשונה איכפל תנא דמתניתין לאורויי בדבר שאינו רגיל כששכח מקצת התנאי דאין רגילות שיבטל בעצמו זה ועוד דבסמוך קאמר תנא סתמא מסתם לה שלא ינהגו קלות ראש בנדרים ובהכי ליכא קלות ראש בששכח מקצת לכ\"נ כפר\"ת דרבא לא פליג אאביי דודאי הכי הלכתא דכשאינו זכור מועיל שפיר ביטול נדרים אלא לישנא דמתני' בעי רבא לאוקומי מדקתני ובלבד שיהא זכור בשעת הנדר וא\"ת א\"כ קשה אי זכור בשעת הנדר דמשמע דוקא אבל שכחתי לא וי\"ל דאשכח מקצת תנאי קאי ולכך קאמר שצריך שיהא זכור לתלות בשעה ראשונה ומתניתין נמי הכי קאמר דרוצה שלא יתקיימו נדריו יאמר כל נדר דבעי (כי) כשאין זכור ופעמים דבעי שיהא זכור לומר על דעת הראשונה היינו שהתנה ולא ידע וכו':"],[3,"סבר למידרשיה בפירקא","להך משנה דהרוצה שלא יתקיימו נדריו:"],[3,"תנא סתומי מסתמא ליה","שמתכוין קצת התנא שלא ינהגו קלות ראש בנדרים והוציאו להגיה חסורי מיחסרא וא\"ת לפי מה דפרישית לעיל דכל נדרי דביטול נדרים הוא היאך אמרינן בבהכ\"נ בכנופיא בפני כל והאמר הכא דלא דרשינן בפירקא וי\"ל דהכא היינו דוקא משום עמי הארץ דאתו לפרקא ועוד כשהיו דורשין ללועזות בלעז ואתי לזלזולי בנדרים ולכך קאמר דלא דרשינן ליה בפירקא בפירוש אבל כל נדרי שהוא כתרגומו אין כל העם מבינים וגם אין לומר להם מותרין אתם:"],[3,"ואת דרשת ליה בפירקא","מכאן משמע דרבא מודה בשכח מעיקרא דאי לא אמר אלא דוקא שכח במקצת מאי קאמר שלא ינהוג קלות ראש בנדרים והא אין רגילות שיהא זכור במקצת ושכוח במקצת. מתוך שמעתין מוחק ר\"ת מה שכתוב במחזורים בכל נדרי מיום הכפורים שעבר עד יום הכפורים הבא עלינו לטובה וסבורים הם שמתירין נדרים משנה שעברה וטועין חדא בכל התרת נדרים בעי חרטה מעיקרא לכל הפחות והרי אין אנו פותחין בשום חרטה ועוד דבעי יחיד מומחה או ג' הדיוטות וליכא ועוד שהלכה כרב פפא דהוא בתראה דאמר פרק השולח (גיטין דף לה:) צריך לפרט הנדר ואנן לא עבדינן הכי ועוד דנודר עצמו אי אפשר לו להתיר לכך נראה לו להגיה מיוה\"כ זה עד יוה\"כ הבא עלינו לטובה ונדרים של שנה הבאה הוא דשרינן וסמך לדבר דתנן הרוצה שלא יתקיימו נדריו כו' ובלבד שלא יהא זכור בשעת הנדר ואפילו רבא נמי מודה בזה ואע\"ג דעומד אדם בר\"ה תנן ואנן ביוה\"כ עבדינן אשכחן יוה\"כ דאקרי ר\"ה כדכתיב ביחזקאל בר\"ה בעשור לחדש ואמרו דזהו יוה\"כ דיובל ועוד שהוא סמוך לר\"ה ולכך תקנוהו ביוה\"כ לומר טפי משום דיוה\"כ בטל מכל מלאכות ואיכא כנופיא טובא ואע\"ג דשרינן בכל נדרי אף חרמים ושבועות ואנן נדרים תנן לאו דוקא נדרים ה\"ה חרמים ושבועות ומשום דבנדרים קיימינן קתני נדרים ומטעם שהראשונים טועים וסבורים שמתירין הנדרים שעברו היו אומרים חוץ מתקנות קהלות ושבועות ב\"ד אבל השתא דאנן אין מתירין אלא נדרים מכאן ולהבא אין לנו לפרש חוץ מתקנות קהלות דאנן אין מתירין אלא מה שאדם נודר בינו לבין עצמו אבל דבר שבין אדם לחבירו אין אנו יכולין להתיר והא דאומרים בכל נדרי דנדרנא דמשמע לשעבר אלמא דמשמע דאנו מתירין שעברו י\"ל דנדרנא משמע שתי לשונות כמו אמרי פי משמע כדאמרי משמע לשעבר ומשמע דאמינא דהיינו להבא ה\"נ דנדרנא משמע להבא ולשעבר ודאחרטנא דאומרים בכל נדרי פירושו הוי כשנתחרט דאין מועיל ביטול בר\"ה אלא כשנתחרט עליו לאחר מכאן שנדר ומה שנהגו לומר אחר כל נדרי וכו' ונסלח לכל עדת זהו לפרש כשידור אדם לאחר מכאן ולא יזכור לתנאי של ביטול דכל נדרי ויעבור על נדרו הרי זה צריך כפרה וסליחה אע\"ג שאותו מבטל כאן שלא ידע כשעבר כדאמרינן (נזיר דף כג.) גבי אשה הרי שנדרה והפר לה בעלה והיא לא ידעה שהפר לה בעלה והיתה שותה יין הרי היא צריכה כפרה וסליחה וא\"ת והאמר בכל נדרי ושבועתנא לא שבועות ואמאי והאמר יש תנאי בנדרים ואין תנאי בשבועות משמע דאין תנאי ביטול מועיל בשבועות והיאך אנו מתירין נמי לומר ושבועתנא לא שבועות וי\"ל דהא דאמר תנאי בנדרים ואין תנאי בשבועות לאו לענין ביטול ר\"ה מיירי אלא היינו כשמחשב בלבו שהוא נודר על דבר שמותר כגון הנודר בחרמא ואמר לא נדרתי אלא בחרמו של ים והא מילתא ליתא בשבועות אבל גבי ביטול ר\"ה שוין הן:"],[4,"אי תבעי להו","כמו איבעיא להו פליגי רבנן עליה דרבי אליעזר בן יעקב ואת\"ל פליגי הלכה כמותו ואע\"ג דמשנת ר\"א ב\"י קב ונקי זימנין דפסקינן דלא כוותיה ולכך מיבעיא ליה אי פסקי' בהך קולא כוותיה או לא אי נמי משום דלא דמי נדרי זירוזין דהכא לנדרי זירוזין דארבעה נדרים דלעיל לכך לא איבעיא מקמייתא דהרוצה להדיר חבירו זירוזין והוי מיבעיא ליה אההוא דהרוצה שלא יתקיימו וכו' דפשיטא ליה דאפילו פליגי רבנן עליה מכל מקום הלכה כמותו דרב הונא סבר לעיל למדרשיה בפירקא ואף רבא לא איקפיד אלא דלא למדרשיה בפירקא:"]]],[["קונם שאיני נהנה לך אם אי אתה נוטל לבנך כור של חיטין ושתי חביות של יין הרי זה יכול להתיר את נדרו שלא על פי חכם שיכול לומר לו כלום אמרת אלא בשביל כבודי זה הוא כבודי","טעמא דאמר זה הוא כבודי הא לאו הכי נדר הוא מני אי רבי אליעזר בן יעקב נדרי זירוזין הוי אלא שמע מינה פליגי רבנן עליה","לעולם רבי אליעזר בן יעקב היא ומודה רבי אליעזר בן יעקב בהאי דנדרא הוי דאמר ליה לא כלבא אנא דמיתהנינא מינך ולא מיתהנית מינאי","תא שמע האומר לחבירו קונם שאתה נהנית לי אם אי אתה נותן לבני כור של חיטין ושתי חביות של יין רבי מאיר אומר עד שיתן וחכמים אומרים אף זה יכול להתיר את נדרו שלא על פי חכם שיכול לומר הריני כאילו התקבלתי","טעמא דאמר הריני כאילו התקבלתי הא לאו הכי נדר הוא מני אי רבי אליעזר בן יעקב נדרי זירוזין הוי אלא לאו רבנן ופליגי","לא לעולם רבי אליעזר בן יעקב ומודה רבי אליעזר בהאי דנדרא הוי משום דאמר ליה לאו מלכא אנא דמהנינא לך ואת לא מהנית לי","אמר ליה מר קשישא בריה דרב חסדא לרב אשי תא שמע נדרי אונסין הדירו חבירו שיאכל אצלו וחלה הוא או חלה בנו או שעכבו נהר הא לאו הכי נדר הוא מני אי רבי אליעזר בן יעקב זירוזין הוי אלא לאו רבנן ופליגי","לעולם רבי אליעזר בן יעקב ומי סברת דאדריה מזמנא לזמינא לא דזמינא אדריה למזמנא דאמר ליה מזמנת לי לסעודתיך אמר ליה אין נדר זה עליך ונדר וחלה הוא או שחלה בנו או שעכבו נהר הרי אלו נדרי אונסין","תא שמע יתר על כן אמר רבי אליעזר בן יעקב האומר לחבירו קונם שאני נהנה לך אם אי אתה מתארח אצלי ותאכל עמי פת חמה ותשתה עמי כוס חמין והלה הקפיד כנגדו אף אלו נדרי זירוזין ולא הודו לו חכמים מאי לא הודו לו חכמים לאו"],[[0,"הרי זה יכול","המודר להתיר נדרו בעצמו שלא ע\"פ חכם שיכול לומר לו המודר כלום אמרת ליתן לבני כך וכך אלא בשביל כבודי:"],[0,"זהו כבודי","יותר שלא אקבל שאיני צריך וכבר הותר הנדר:"],[1,"מני אי רבי אליעזר בן יעקב","אע\"ג דלא אמר זהו כבודי יותר בטל דנדרי זירוזין הוא:"],[1,"אלא לאו רבנן היא","דסברי דלא הוי נדרי זירוזין וש\"מ פליגי:"],[2,"לעולם רבי אליעזר בן יעקב היא","הא מתני':"],[2,"ומודה ר' אליעזר בן יעקב בהאי דנדר הוי","ולא זירוזין דודאי משום נדר ממש קא\"ל דאמר ליה לאו כלבא אנא כו':"],[3,"וחכ\"א אף זה","נודר יכול להתיר שיכול לומר לו הריני מחזיק לך טובה כאילו התקבלתי ממך לפיכך אינו נדר:"],[4,"אי ר\"א בן יעקב נדרי זירוזין הוו","שמזרזו ומדירו כדי שיתן לו כך וכך אע\"ג דלא אמר התקבלתי הוי בטל דנדרי זירוזין הוו:"],[4,"אלא לאו רבנן היא","דסברי דלא הוו נדרי זירוזין אלמא פליגי:"],[5,"לעולם ר\"א בן יעקב היא","הא מתני':"],[5,"ומודה","דהאי לא הוה נדרי זירוזין אלא נדר ממש ולהכי אי אמר התקבלתי לא הוי נדר:"],[5,"","משום דאמר ליה לאו מלכא כו':"],[6,"מני אי ר\"א בן יעקב נדרי זירוזין הוו","המדיר חברו שיאכל עמו ואפי' לא חלה מותר:"],[6,"אלא לאו רבנן היא","ופליגי דלא הוו נדרי זירוזין:"],[7,"לעולם ר\"א בן יעקב היא","ומודה דלאו נדרי זירוזין הוו:"],[7,"מי סברת דאדריה מזמנא","דהיינו נדרי זירוזין:"],[7,"לא זמינא הוא דאדריה למזמנא דאמר ליה מזמנת לי בהדך אמר ליה אין נדר זה קבל עליך ונדר וחלה הוא","המזומן הא לא חלה הוי נדר גמור:"],[8,"יתר על כן","על אותו שאמר במשנה אמר ר\"א בן יעקב האומר לחבירו קונם שאיני נהנה לך כו':"],[8,"והלה הקפיד כנגדו","אף על גב שפירש לו הכל ואע\"פ שהקפיד כנגדו אף אלו נדרי זירוזין ומותר:"],[8,"ולא הודו לו חכמים","שיהא נדרי זירוזין:"]],[[7,"מי סברת דאדריה מזמנא לזמינא לא זמינא אדריה למזמנא אמר ליה מזמנת לי אמר ליה אין","פירוש כן אני רוצה לזמן אותך וא\"ל זמינא למזמנא דור עליך שאתה מזמן לי ונדר פירוש נדר מזמנא ואמר קונם פירות עלי אם אין אני מזמן אותך ולא הוו נדרי זירוזין משום דדוקא היכא שהמזומן מסרב ומזמן מפציר בו ומזרזו לאכול משלו התם שייך נדרי זרוזין אבל כאן אין צריך לזרז המזומן לאכול שהרי אדרבה המזומן מבקש מן המזמן שידור על כך שיזמנהו:"],[8,"יתר על כן אמר ר' אליעזר ב\"י ואוכל עמו פת חמה","וא\"ת מאי יתר על כן י\"ל דהכי קאמר אע\"ג דשייך לומר לאו כלבא אנא וא\"ת והאמר לעיל דלא הוי זירוזין היכא דשייך לומר לאו כלבא אנא לכן נראה דאמר ליה קונם שאי אתה נהנה ממני לעולם אם אי אתה אוכל היום פת חמה והשתא לא שייך טעמא דלאו כלבא אנא ואשמעינן דאע\"ג דפי' לו פת חמה וכוס של חמין דמקפיד הוא טפי וסד\"א דמתכוין לנדר אפ\"ה שרי:"]]],[["דאפילו בקמייתא ושמע מינה פליגי רבנן עליה שמע מינה","מאי הוי עלה תא שמע דאמר רב הונא הלכה כרבי אליעזר בן יעקב וכן אמר רב אדא בר אהבה הלכה כרבי אליעזר בן יעקב","\u0001מתני׳\u0002 נדרי הבאי אמר קונם אם לא ראיתי בדרך הזה כעולי מצרים אם לא ראיתי נחש כקורת בית הבד","\u0001גמ׳\u0002 תנא נדרי הבאי מותרין שבועות הבאי אסורין","היכי דמי שבועות הבאי אילימא דאמר שבועה אם לא ראיתי בדרך הזה מידעם קאמר","אמר אביי דאמר שבועה שראיתי אמר ליה רבא אם כן למה לי למימר ועוד דומיא דנדר קתני אלא אמר רבא באומר ייאסרו פירות העולם עלי בשבועה אם לא ראיתי בדרך הזה כעולי מצרים","אמר ליה רבינא לרב אשי ודילמא האי גברא קינא דשומשמני חזא ואסיק להון שמא עולי מצרים ושפיר משתבע"],[[0,"אפי' בקמייתא","הנך דלעיל ש\"מ:"],[1,"מאי הוי עלה","אי הוי הלכתא כוותיה דר' אליעזר דהוי נדרי זרוזין ומותר:"],[5,"אמר ליה רבא","א\"כ מתניתא דאמר שבועה שראיתי בדרך הזה:"],[5,"למה לי למימר","דאסור דהיינו שבועה גמורה ודאי כאילו אמר שבועה שאכלתי:"],[5,"ועודי דומיא דנדר קתני","שבועות (נדרי) הבאי אסורין דמשמע דקאמר בלשון נדר ושבועה:"],[5,"אלא אמר רבא","קאמר הכי יאסרו כל פירות העולם עלי בשבועה:"],[5,"אם לא ראיתי","ולא קאמר שראיתי:"],[6,"אמר ליה רבינא","אמאי אסורות ודלמא שפיר אישתבע לדעתיה דידיה:"],[6,"דלמא קינא דשומשמני","נמלות מקובצות הרבה ראה ביחד כעולי מצרים דאפשר:"]],[[1,"מאי הויא עלה","וא\"ת והא פשיטנא כבר דפליגי רבנן עליה לכן נראה לפרש הלכה כרבי אליעזר ב\"י או לא:"],[2,"נדרי הבאי אם לא ראיתי","פירוש שאמר קונם פירות העולם עלי אם לא ראיתי וכו' מותרין מטעם דעבידי אינשי דמשתעי הכי כדי לאמת ולצדק את דבריהן כשרואין מעשה אחד יותר ממה שרגיל להיות ואין בלבו לאסור ואנן סהדי כדפרישית לעיל:"],[2,"כעולי מצרים","לפי שראה עם רב יותר ממה שרגיל:"],[2,"נחש טרוף","לפי שראוהו טרוף - יותר משאר נחשים ודווקא כשראה כדפרישית אבל אם לא ראה שום אדם ולא שום נחש ודאי לא הוי נדר הבאי ואסור משום דעבידי אינשי דמישתעו הכי כיון שלא ראה כלל:"],[5,"","אלא אמר רבא דאמר יאסרו כל פירות שבעולם וכו'. [בשבועות פירשו התוספות באורך]:"]]],[["אמר ליה כי משתבע אדעתא דידן משתבע ואנן לא מסקינן נפשין אשומשמני","ועל דעתא דנפשיה לא עביד איניש דמשתבע והתניא כשהן משביעין אותו אומרים לו הוי יודע שלא על תנאי שבלבך אנו משביעין אותך אלא על דעתינו ועל דעת בית דין לאפוקי מאי לאו לאפוקי דאסיק להו לאיסקונדרי ואסיק להון שמא זוזי","ומדקאמר על דעתינו מכלל דעביד אינש דמשתבע אדעתא דנפשיה","לא לאפוקי מקניא דרבא דההוא גברא דהוה מסיק בחבריה זוזי אתא לקמיה דרבא אמר ליה ללווה זיל פרע לי אמר ליה פרעתיך אמר ליה רבא אם כן זיל אישתבע ליה דפרעתיה","אזל ואייתי קניא ויהיב זוזי בגויה והוה מסתמיך ואזיל ואתי עליה לבי דינא אמר ליה למלוה נקוט האי קניא בידך נסב ספר תורה ואישתבע דפרעיה כל מה דהוה ליה בידיה","ההוא מלוה רגז ותברה לההוא קניא ואישתפך הנהו זוזי לארעא ואישתכח דקושטא אישתבע","ואכתי לא עביד דמישתבע אדעתא דנפשיה והתניא וכן מצינו במשה רבינו כשהשביע את ישראל בערבות מואב אמר להם הוו יודעים שלא על דעתכם אני משביע אתכם אלא על דעתי ועל דעת המקום שנאמר ולא אתכם לבדכם וגו' (דברים כט יג)","מאי אמר להו משה לישראל לאו הכי קאמר להו דלמא עבידתון מילי ואמריתון על דעתינו משום הכי אמר להו על דעתי לאפוקי מאי לאו לאפוקי דאסיקו שמא לעבודת כוכבים אלוה מכלל דעביד איניש דמשתבע אדעתא דנפשיה","לא עבודת כוכבים איקרי אלוה דכתיב ובכל אלהי מצרים וגו'","ולשבע יתהון דמקיימיתון מצוות משמע מצוַת המלך","ולשבע יתהון דמקיימיתון כל מצוות משמע מצוַת ציצית דאמר מר שקולה מצוַת ציצית כנגד כל מצוות שבתורה","ולשבע יתהון דמקיימיתון תורה משמע תורה אחת ולשבע יתהון דמקיימיתון תורות משמע תורת מנחה תורת חטאת תורת אשם ולשבע יתהון דמקיימיתון [תורות] ומצוות [תורות] משמע תורת המנחה מצוות משמע מצות המלך","ולשבע יתהון דמקיימיתון תורה כולה תורה כולה משמע עבודת כוכבים דתניא חמורה עבודת כוכבים שכל הכופר בה כאילו מודה בתורה כולה","ולשבע יתהון דמקיימיתון עבודת כוכבים ותורה כולה אי נמי שש מאות ושלוש עשרה מצוות אלא משה רבינו מילתא דלא טריחא נקט:","אם לא ראיתי נחש כקורת בית הבד: ולא והא ההוא חויא דהוה בשני שבור מלכא רמו ליה תליסר אורוותא דתיבנא ובלע יתהון אמר שמואל בטרוף כולהו נחשי מיטרף טרפי אגבו טרוף קאמרינן","ולתני טרוף מילתא אגב אורחיה קא משמע לן דקורת בית הבד גבו טרוף למאי נפקא מינה למקח וממכר לומר לך המוכר קורת בית הבד לחבירו אי גבו טרוף אין ואי לא לא:"],[[0,"אדעתא דידן אישתבע","כדרך שבני אדם נשבעין ואין דרך בני אדם לקרוא לנמלים עולי מצרים:"],[1,"לאפוקי מאי","אמרי ליה הכי דשלא על דעתך אנו משביעין אותך:"],[1,"לאו לאפוקי","דיהיב ליה לבעל חובו אסקונדרי פיספסים שמשחקים בהן וקרא אותן זוזי ובכך רוצה לפטור עצמו מן השבועה מכלל דעביד איניש דנשבע לדעתא דנפשיה הכא נמי נימא הכי גבי שומשמני:"],[3,"לא","שומשמני ואיסקונדרי לאו מילתא היא ובהכי לא מיפטר איניש נפשיה ומשום האי טעמא לא היו אומרים לו הוי יודע כו':"],[3,"אלא לאפוקי מקניא דרבא","דזוזי ממש יהב ובעי למיפטר בהכי ובשאר מילי לא עביד איניש דנשבע אדעתא דנפשיה:"],[6,"והא תניא וכן מצינו כו' שנאמר ולא אתכם לבדכם","הכי פירושו איני משביע אתכם על דעתכם לבדכם:"],[7,"לאפוקי מאי","קאמר להו הכי לאו לאפוקי דאי אסיקו לה שמא לעבודת כוכבים אלוה ופלחו לה ובעו למיפטר נפשייהו דאמרי דפלחי לאלוה:"],[7,"לא","לאו לאפוקי משום האי קאמר הכי דאינהו לא מצו לאסוקי לעבודת כוכבים שמא אלוה ולמפטר נפשייהו דהא עבודת כוכבים איקרי אלוה מעצמה:"],[11,"","אם כן אמאי משבע יתהון הכי על דעת המקום ועל דעתי לישבע יתהון דמקיימיתו תורה:"],[11,"הוה משמע תורה אחת","שבכתב בלבד:"],[11,"משמע מצות המלך","שבפרשה שום תשים עליך מלך (דברים י״ז:ט״ו) שיש שם מצות:"],[13,"ולישבע להו הכי דמקיימיתו עבודת כובבים ותורה כולה אי נמי דמקיימיתו תרי\"ג מצות","ולא מצי למיטעי מידי:"],[13,"אלא משה רבינו מילתא דלאו טירחא נקט","כשאמר על דעת המקום ועל דעתי ששם נכלל הכל:"],[14,"אורוותא","איצטבלאות מלאות תבן:"],[14,"ובלע יתהון","אלמא דהוה גדול מקורת בית הבד:"],[14,"בטרוף קאמר","נחש מנומר לא משתכח כקורת בית הבד:"],[14,"והא כולהו מיטרף טריפי","הוו מנומרין:"],[14,"בגבו טרוף קאמרינן","ולא הוי גדול כי האי גוונא:"],[15,"וליתני","אם לא ראיתי נחש גבו טרוף כקורת בית הבד:"],[15,"מילתא אגב אורחא קמ\"ל","דכי אמר בית הבד אגבו טרוף קאמר דומיא דקורת בית הבד דהוי טרוף חדקים חדקים:"],[15,"נפקא מינה","למוכר קורת בית הבד לחבירו:"],[15,"אי גבה טרוף אין","ודאי הוי קורת בית הבד:"]],[[14,"בטרוף","פי' שהוא מנומר שהיו כמו קורות בית הבד ול\"נ דמה ענין מנומר לקורות בית הבד לכ\"נ לפרש בטרוף פלט\"ר בלע\"ז ופריך כולהו נמי טרופין פירוש בבטן ולכך ניחא גבי קורות בית הבד:"]]],[["\u0001מתני׳\u0002 נדרי שגגות אם אכלתי ואם שתיתי ונזכר שאכל ושתה שאני אוכל ושאני שותה ושכח ואכל ושתה אמר קונם אשתי נהנית לי שגנבה את כיסי ושהכתה את בני ונודע שלא הכתו ונודע שלא גנבה","ראה אותן אוכלין תאנים ואמר הרי עליכם קרבן ונמצאו אביו ואחיו והיו עמהן אחרים בית שמאי אומרים הן מותרים ומה שעמהם אסורים ובית הלל אומרים אלו ואלו מותרין:","\u0001גמ׳\u0002 תנא כשם שנדרי שגגות מותרין כך שבועות שגגות מותרות היכי דמי שבועות שגגות כגון רב כהנא ורב אסי הדין אמר שבועתא דהכי אמר רב והדין אמר שבועתא דהכי אמר רב דכל חד וחד אדעתא דנפשיה שפיר קמישתבע:","ראה אותן אוכלין: תנן התם פותחין בשבתות ובימים טובים בראשונה היו אומרים אותן הימים מותרים ושאר כל הימים אסורים עד שבא רבי עקיבא ולימד נדר שהותר מקצתו הותר כולו","אמר רבה דכולי עלמא כל היכא דאמר אילו הייתי יודע שאבא ביניכם הייתי אומר כולכם אסורין חוץ מאבא דכולהון אסורין ואביו מותר לא נחלקו אלא באומר אילו הייתי יודע שאבא ביניכם הייתי אומר פלוני ופלוני אסורין ואבא מותר"],[[0,"מתני' נדרי שגגות","אמר קונם כו':"],[0,"ונזכר שאכל ושתה","פטור דלבו אונסו דסבר שבאמת נשבע:"],[1,"וכן ראה אותם אוכלים תאנים ואמר הרי הן עליכם קרבן ונמצאו","אותן האוכלים שהיה אביו או אחיו היינו נמי נדרי שגגות שאילו היה יודע שהיה אביו או אחיו לא היה מדירן:"],[1,"או שהיה אוכל עמהן","עם אביו ועם אחיו אחרים:"],[1,"בש\"א הן מותרין","אביו ואחיו בלבד ומה שעמהם אסורים דקסברי נדר שהותר מקצתו לא הותר כולו וב\"ה סברי נדר שהותר מקצתו הותר כולו. ע\"כ מפי' רבינו גרשום זצ\"ל:"],[3,"גמ' תנן התם","בפרק ר\"א אומר כו':"],[3,"פותחין בשבתות וימים טובים","שאם נדר שלא יאכל כל ימות השנה פותחין לו חרטה כך כלום נדרת על דעת להתענות בשבתות וימים טובים אם יאמר לאו:"],[3,"בראשונה","היו ב\"ד של ראשונים אומרים אותן הימים שבתות וי\"ט מותרין וכו':"],[3,"הותר כולו","וכולן מותרין:"],[4,"אמר רבה הכל מודים כו'","אמתני' קאי כלומר שאם ראה אותם אוכלים תאנים וענבים ואמר הרי הן עליכם קרבן (כמו שאמר עליהם על כולכם אסורין) ושוב אמר אילו הייתי יודע שאבא ביניכם הייתי אומר כולכם אסורים חוץ מאבא הואיל ומעיקרא כללן דאמר כולכם כולן אסורים ואביו ואמו מותרין דלא הוי נדר שהותר מקצתו הותר כולו הואיל ואכתי בדיבורו קמא קאי דאמר כולכם:"],[4,"לא נחלקו אלא באומר","תחלה בכלל הרי הם עליכם קרבן ושוב אמר אילו הייתי יודע שאבא ביניכם הייתי אומר פלוני ופלוני אסורין ואבא מותר הואיל ולבסוף פרטן פלוני ופלוני קסברי ב\"ה דהו\"ל נדר שהותר מקצתו הותר כולו וב\"ש סברי כל עיקר לא אמר הותר מקצתו הותר כולו (הואיל ואכתי אדיבורו קמא קאי דאמר כולכם):"]],[[0,"נדרי שגגות","קונם כל הפירות שבעולם אם אכלתי ושתיתי היום ונזכר שאכל ושתה פטור שאלמלי היה יודע שאכל לא היה נודר ובעי' פיו ולבו שוין וא\"ת לעיל (נדרים יד:) דקאמר קונם [עיני] בשינה היום אם אישן למחר אל יישן היום שמא יישן למחר ה\"ד אי שכח וישן למחר נדרי שגגות מותרין ובמזיד ליכא למיחש עד שיעבור במזיד על נדרו וי\"ל מתוך כן דאמרינן בתנאיה לאו מזדהר איכא למיחש שמא יישן למחר במזיד:"],[0,"קונם אשתי נהנית לי","פר\"י מיירי דלא משועבד לה:"],[0,"שגנבה כיסי ושהכתה בני","אין לפרש שפירש אם גנבה את כיסו וכן אם הכתה את בנו דא\"כ פשיטא דלא חל הנדר:"],[3,"פותחין לאדם בכבוד שבתות וי\"ט","כגון שנדר שלא לאכול ושלא לשתות יין שנה אחת ולא נזכר על שבתות וי\"ט להוציאם מן הכלל כשבא לישאל על נדרו פותחין לו בכבוד שבתות וי\"ט דאמרינן אילו ידעת והיית זכור בשעת הנדר על שבתות וי\"ט כלום נדרת עליהם והוא אמר לאו מתירין אותו אף לימי החול כדמסיק במשנה דנדר שהותר מקצתו הותר כולו והותר מקצתו הותר כולו דקאמר בלא התרת חכם אלא הותר מחמת נדר טעות קאמר ול\"נ דהלשון משמע שצריך התרת חכם מדקאמר פותחים אלמא משמע דצריך התרת חכם לכ\"נ דודאי צריך התרת חכם ולא דמי למתני' דנמצאו אביו או אחיו דלא צריך שאלה דהתם הנדר בטעות ושגגה גמורה דאנן סהדי שסבור בלבו ששם אינם קרובים דהא אפשר שפיר בלא אחיו הלכך הרי הוא כאילו אמר בפירוש הרי עליכם פלוני ופלוני אבל הכא שנדר שנה אחת תמימה הכל יודעין שאי אפשר לשנה אחת בלא שבתות ואם כן כשנדר שנה אחת ודאי היה דעתו גם אשבתות וי\"ט ולא מצי למימר שטעה כמו במתני' אלא שהוא מתחרט עכשיו על שבתות וי\"ט שלא הוציאם מן הכלל הלכך צריך שאלה והתרה גמורה כשאר נדרים:"],[3,"עד שבא ר\"ע ולימד נדר כו'","להכי מייתי הך מתני' מקמי פלוגתא דרבה ורבא דפליגי בפלוגתא דשמאי והלל משום דפלוגתא דרבנן ור\"ע בהא דפותחין הוו כפלוגתא דב\"ש וב\"ה דת\"ק כב\"ש ור\"ע כב\"ה וא\"ת ות\"ק כב\"ש וי\"ל דאית ליה דלא נחלקו ב\"ש וב\"ה בדבר זה:"],[4,"אמר רבה דכ\"ע כל היכא דאמר אילו הייתי יודע וכו'","מאחר שלא החליף דבריו הראשונים אינו נראה עקירת נדר שמתחלה אמר כולכם והשתא נמי כי שרי לה אמר כולכם לכך לא אמרי' כי הותר מקצתו הותר כולו וה\"ה נמי אם מתחלה אמר בפרט כגון לזה ולזה וכלל אביו עמהם וחזר ואמר אילו הייתי יודע שאבי ביניכם הייתי אומר פלוני ופלוני אסורים ואבי מותר מאחר שלא שינה ולא החליף את לשונו אין כאן עקירת נדר ודכ\"ע לא אמרינן נדר שהותר מקצתו הותר כולו אליבא דרבא והא דנקט שיטתו בלשון כולכם לישנא דמתני' נקט דאמר הרי עליכם קרבן:"],[4,"לא נחלקו אלא","כשהחליף ושינה את דבריו הראשונים שמתחלה אמר כולכם אסורים ועתה אמר אילו הייתי יודע שאבא ביניכם הייתי אומר פלוני ופלוני אסורין ואבי מותר והוא הדין אם החליפם בצד אחר שמתחלה אמר לזה ולזה והשתא אמר כולכם דמאחר שהחליפן לכלל ופרט שמתחלה כלל באיסור ופרט בהיתר אי נמי פרט באיסור וכלל בהיתר אמרי ב\"ה ור\"ע מאחר שהחליפן נראה כעוקר נדרו והותר מקצתו הותר כולו וב\"ש לא שני ליה ואסרו בתרווייהו:"]]],[["ורבא אמר דכולי עלמא כל היכא דאמר אילו הייתי יודע שאבא ביניכם הייתי אומר פלוני ופלוני אסורין ואבא מותר כולם מותרין לא נחלקו אלא באומר אילו הייתי יודע שאבא ביניכם הייתי אומר כולכם אסורין חוץ מאבא","בית שמאי סברי לה כרבי מאיר דאמר תפוס לשון ראשון","ובית הלל סברי לה כרבי יוסי דאמר בגמר דבריו אדם נתפס","איתיביה רב פפא לרבא כיצד אמר רבי עקיבא נדר שהותר מקצתו הותר כולו קונם שאיני נהנה לכולכם הותר אחד מהן הותרו כולם שאיני נהנה לא לזה ולזה הותר הראשון הותרו כולם הותר האחרון האחרון מותר וכולן אסורין","בשלמא לרבה מוקים לה לרישא דאמר לזה ולזה","וסיפא דאמר לכולכם","אלא לדידך בשלמא רישא מוקים לה דאמר לכולכם"],[[0,"דכ\"ע","לא נחלקו באומר תחלה בכלל הרי זה עליכם קרבן ושוב אמר אילו הייתי יודע שאבא ביניכם הייתי אומר פלוני ופלוני אסורין ואבא מותר הואיל ולבסוף פרטן אפילו ב\"ש מודו דכה\"ג הואיל והיתר מקצתו בתוך דבורו הותר כולו:"],[0,"לא נחלקו","אלא דהדר כלל דאמר כולכם אסורים חוץ מאבא:"],[1,"דבית שמאי סברי' לה כר\"מ דאמר תפוס לשון ראשון","דאזלינן בתר ההוא רובא דאמר כולכם אסורין ולא אמרי' משהותר מקצתו הותר כולו:"],[2,"וב\"ה סברי לה כרכי יוסי דיאמר בגמר דבריו אדם נתפס","דאמר חוץ דמתוך דבורו הותר מקצתו דאמר חוץ מאבא הותר כולו:"],[3,"כיצד אמר ר\"ע נדר שהותר מקצתו הותר כולו","דזהו כב\"ה ופליגי רבנן עליה דאמרי לא הותר כולו דהיינו כבית שמאי:"],[3,"שאיני נהנה לזה ולזה","שפרטן:"],[3,"הותרו כולן","מפרש בברייתא לקמן:"],[4,"בשלמא לרבה","דאמר דבכולכם לא פליגי אלא בפלוני ופלוני לא קשיא ליה הך ברייתא דמתרץ לה לרישא כסיפא וסיפא כרישא דקתני רישא ר' עקיבא אומר הותרו כולן מיירי בהיכא דפרט שאמר שאיני נהנה לזה ולזה ולא בכולכם ור\"ע הוא דאמר כב\"ה והיינו דקאמר לא נחלקו אלא בהייתי אומר פלוני ופלוני אסורין ואבא מותר ופליגי רבנן עליה דר\"ע דקסברי כב\"ש וסיפא דסיפא דקתני כולן אסורין מוקי לה דאמר כולכם ודברי הכל היא דבכולכם אסורים לא פליגי ר\"ע ורבנן כדאמרי' דכולי עלמא היכא דקאמר כולכם כולן אסורין והשתא סיפא דרישא דתני הותר הראשון הותרו כולן לא דייק אלא לסיפא דסיפא כדקאמר:"],[6,"אלא לדידך","לרבא דאמר בכולכם פליגי היכי מוקמינן לה לברייתא:"],[6,"בשלמא רישא","דקתני דאמר ר' עקיבא הותר אחד מהן הותרו כולן דפליגי רבנן עליה:"],[6,"מוקים לה דקאמר כולכם","ולא אפיק אלא כדקתני ר' עקיבא וכו' ופליגי רבנן עליה דר' עקיבא כב\"ה:"]],[[0,"ורבא אמר דכ\"ע וכו'","פי' רבא אית ליה דכל היכא דאמר בסוף פלוני ופלוני בין אמר מעיקרא כולכם בין מעיקרא לזה ולזה דהשתא לא החליף לשונו אפ\"ה כיון דלבסוף הותר מקצתו לגמרי שלא כלל אביו עם האחרים כשבא להתיר נדרו אמרינן הותר מקצתו הותר כולו דב\"ש אמרי נמי נדר שהותר מקצתו הותר כולו לא נחלקו אלא דאמר כולכם לבסוף דב\"ש סברי לה כר\"מ דאמר תפוס לשון ראשון ובתחלת דבריו בשעת התרה כלל אביו עמהם וא\"כ אין כאן הותר מקצתו וא\"ת אי תפוס לשון ראשון אמאי אביו מותר והלא מתחלה אמר כולכם דמשמע אפילו אביו ויש לומר דודאי אנן סהדי דאין דעתו לאסור אביו אילו יודע שהיה שם ומ\"מ לא חשיב ליה הותר מקצתו לגבי להתיר לאחרים:"],[3,"מתיבי כיצד אמר רבי עקיבא נדר שהותר מקצתו הותר כולו וכו'","בשלמא לרבה דתלי פלוגתייהו בהחלי' לשונו מוקי רישא כדקתני כולכם כגון דאמר בתחלת נדרו לזה ולזה עכשיו כשחוזר בו אמר כולכם כדקתני בברייתא וסיפא דברייתא דקתני לזה ולזה הותר הראשון הותרו כולן מיירי שאמר מתחלה בשעת נדרו כולכם ועכשיו בשעת חזרה אומר לזה ולזה וכולכם דרישא ולזה ולזה דסיפא דהך בריית' תרווייהו קאי אשעת חזרה ואיצטריך רישא וסיפא לאשמועינן דבכל ענין שיחליף לשונו אמר ר\"ע הותר מקצתו הותר כולו וא\"ת מ\"מ קשה מסיפא דסיפא דקתני הותר האחרון וכולן אסורין היכי משכחת לה וי\"ל דהשתא לא דייקינן בלישנא דראשון ואחרון עד בסמוך:"],[6,"אלא לדידך בשלמא רישא","דאמר הותר [א' מהן] הותרו כולן דאמר כולכם בשעת חזרה ולכך לרבי עקיבא הותרו כולם ולא לרבנן אלא סיפא על כרחו דאמר לזה ולזה בשעת חזרה אמאי פליגי רבנן עליה וא\"ת לפי' ר\"ת דפירש לעיל דרבא דפליג בכולכם לבסוף בין אמר בשעת הנדר כולכם בין אמר בשעת הנדר לזה ולזה אם כן לישנא דכולכם ברישא ולזה ולזה תרוייהו אשעת הנדר קיימי דאידי ואידי בשעת חזרה אמר כולכם ולהכי ר\"ע דוקא ולא רבנן וי\"ל דמשמע ליה דלשונות דברייתא אחזרה קיימי מדקתני כיצד אמר ר\"ע נדר שהותר מקצתו הותר כולו משמע דאשעת היתר קאי לפרושי ועי\"ל כיון דעיקר פלוגתא דר\"ע ורבנן תלוי במה שאמר לבסוף כולכם א\"כ זה היה לו לפ' בבריי' ברישא ובסיפא כ\"נ לרש\"י:"]]],[["אלא סיפא דאמר לזה ולזה רבי עקיבא היא אמאי פליגי רבנן עליה והאמרת דברי הכל מותר","אמר ליה רבא ולרבה לרבי עקיבא מי ניחא סיפא במאי מוקים לה דאמר לכולכם הי דין הוא ראשון והי דין הוא אחרון","אלא רישא דאמר לכולכם וסיפא כגון שתלאן זה בזה ואמר פלוני כפלוני ופלוני כפלוני","דיקא נמי דתניא הותר האמצעי הימנו ולמטה מותרין ולמעלה אסורין","איתיביה רב אדא בר אהבה לרבא קונם בצל שאני טועם שהבצל רע ללב אמרו לו והלא הכופרי יפה ללב הותר בכופרי ולא בכופרי בלבד הותר אלא בכל הבצלים מעשה היה והתירו רבי מאיר בכל הבצלים","מאי לאו דאמר אילו הייתי יודע שהכופרי יפה ללב הייתי אומר כל הבצלים אסורין וכופרי מותר","לא באומר אילו הייתי יודע שהכופרי יפה ללב הייתי אומר בצל פלוני ופלוני אסורין וכופרי מותר ורבי מאיר אליבא דרבי עקיבא ואליבא דרבנן","איתיביה רבינא לרבא רבי נתן אומר יש נדר שמקצתו מותר ומקצתו אסור כיצד נדר מן הכלכלה"],[[0,"אלא סיפא","דרישא דאמר לזה ולזה הותר הראשון הותרו כולן כדקתני לה ורבי עקיבא היא ולא רבנן כדקתני כיצד א\"ר עקיבא וכו' ומשמע דפליגי רבנן עליה:"],[0,"והא אמרת","היכא דאמר הייתי אומר פלוני ופלוני אסורין כולן מותרין והשתא לא דייק סיפא אלא סיפא דרישא והשתא לא מצי רבא לאוקמא לדברי הכל דבכולן אסורין ליכא מאן דפליג אפילו ר\"ע אבל הכא דקתני הותרו כולן רבנן פליגי עליה:"],[1,"אמר ליה רבא לרב פפא ולרבה מי ניחא סיפא","דסיפא דקתני וכולן אסורין במאי מוקים לה דאמר לכולכם:"],[1,"הדין הוא ראשון והדין הוא אחרון","הא לכולכם קתני סתם ומאי ראשון ומאי אחרון איכא דקתני האחרון מותר וכולן אסורין:"],[2,"אלא אמר רבא","אנא מתרצינא להדדי דלא קשיא כלל דסיפא דקתני ראשון ואחרון לא משמע כדקתני שאיני נהנה לזה ולזה:"],[2,"אלא כגון שתלאן זה בזה","דמעיקרא אמר קונם שאיני נהנה לזה והדר אמר פלוני יהא אסור כפלוני שהדרתי ופלוני השלישי יהא אשור כשני לפיכך קתני הותר הראשון הותרו כולן שכולן תלויין בו הותר האחרון האחרון מותר וכולן אסורין שהרי הראשון והאמצעי לא נתלו באחרון לפיכך לא הותרו השנים בהתירו של אחרון:"],[3,"דיקא נמי","דהכי הוא דקתני ההיא ברייתא:"],[3,"הותר האמצעי הימנו ולמטה מותר","והיינו הוא והאחרון שתלוי בו מותרים:"],[3,"ממנו ולמעלה","היינו הראשון אסור לפי שהן תלויין בו והוא אין תלוי בהן:"],[4,"והלא הכופרי","בצל של אותו מקום:"],[4,"הותר בכופרי","שלא נדר אלא מאותו שהוא רע ללב ולא בכופרי:"],[4,"והתירו רבי מאיר","דקסבר נדר שהותר מקצתו הותר כולו:"],[5,"מאי לאו דאמר אילו הייתי יודע שהכופרי יפה ללב הייתי אומר כל הבצלין אסורין וכופרי מותר","דהיינו דומיא דכולכם אסורין חוץ מאבאואפ\"ה התירו ר\"מ בכל הבצלים וקשיא בין לרבה בין לרבא דאילו לרבה בכולכם לא פליגי דאסור והכא קא שרי ר\"מ היכא דאמר בכולכם ולרבא קשיא דאמר בכולכם פליגי דב\"ש דאסרי סברי לה כר\"מ:"],[6,"תריץ לה באומר אילו הייתי יודע שהכופרי יפה ללב הייתי אומר בצל פלוני ופלוני אסור וכופרי מותר","דהיינו פלוני ופלוני ולהכי קא שרי ר\"מ והיינו דרבא דאמר פלוני ופלוני דברי הכל מותר דר' מאיר אליבא דרבי עקיבא ואליבא דרבנן קא שרי כלומר אליבא דד\"ה דהא ד\"ה מותר ותרווייה\"ו גרי\"ס המור\"ה:"]],[[1,"ולרבה מי ניחא סיפא במאי מוקים לה הדין הוא ראשון הדין הוא אחרון","כלומר מ\"ש ראשון ומ\"ש אחרון בתרוייהו הוה ליה למימר הותרו כולן:"],[2,"אלא דרישא דאמר כולכם","ובהא פליגי רבנן ור\"ע דסיפא לאו מפלוגתא דרבנן ור\"ע אלא אפי' רבנן נמי מודו וכגון שתלאן זה בזה:"],[4,"איתיביה רב אדא בר אהבה לרבא","בכולהו פירכי גרסינן לרבא מיהו האי פירכא איתא לרבא וכ\"ש לרבה כמו שאפרש בע\"ה:"],[4,"קונם בצל שאני טועם","משנה היא בפרק ר' אליעזר:"],[4,"כופרי יפה ללב","על שם מקומו וכן כלב כופרי ובערוך פי' שהוא לשון כפר שהוא של כפרים:"],[5,"מאי לאו דאמר אילו הייתי וכו' כל הבצלים וכו' והתיר ר\"מ","וקאמר לדידך דקאמרת לעיל דב\"ש אסרי משום תפוס לשון ראשון וב\"ש כרבי מאיר והכא בהך ברייתא מתיר רבי מאיר אע\"ג דסבר תפוס לשון ראשון [ולרבה אמת קשה טפי] דלדידיה אמר לעיל בכולכם אסור לכ\"ע והא דפריך לרבא טפי היינו משום שהיה תלמידו ומשני לא באומר אילו הייתי יודע הייתי אומר פלוני ופלוני ור' מאיר אליבא דרבי עקיבא ואליבא דרבנן כלומר אליבא דכ\"ע הוא והיינו כרבא דאמר לעיל דהכל מודים באומר לזה ולזה ואליבא דרבה נמי לאו פירכא היא די\"ל דאליבא דרבי עקיבא אמר דוקא ולא אליבא דרבנן דהא פליגי רבנן בלזה ולזה:"]]],[["והיו בה בנות שוח ואמר אילו הייתי יודע שבנות שוח בתוכה לא הייתי נודר הכלכלה אסורה בנות שוח מותרות עד שבא רבי עקיבא ולימד נדר שהותר מקצתו הותר כולו מאי לאו דאמר אילו הייתי יודע שבנות שוח בתוכה הייתי אומר תאנים שחורות ולבנות אסורות בנות שוח מותרות ורבי עקיבא היא ופליגי רבנן","לא באומר אילו הייתי יודע שבנות שוח בתוכה הייתי אומר כל הכלכלה אסורה ובנות שוח מותרות","מאן תנא להא דתנו רבנן נדר מחמשה בני אדם כאחד הותר לאחד מהם הותרו כולן חוץ מאחד מהן הוא מותר והן אסורין","אי לרבה רישא רבי עקיבא וסיפא דברי הכל אי לרבא סיפא רבנן ורישא דברי הכל:","\u0001מתני׳\u0002 נדרי אונסין הדירו חבירו שיאכל אצלו וחלה הוא או שחלה בנו או שעכבו נהר הרי אלו נדרי אונסין:","\u0001גמ׳\u0002 ההוא גברא דאתפיס זכוותא בבי דינא ואמר אי לא אתינא עד תלתין יומין ליבטלון הני זכוותאי איתניס ולא אתא אמר רב הונא בטיל זכוותיה","אמר ליה רבא אנוס הוא ואנוס רחמנא פטריה דכתיב (דברים כב) ולנערה לא תעשה דבר","וכי תימא קטלא שאני והתנן נדרי אונסין הדירו חבירו שיאכל אצלו וחלה הוא או שחלה בנו או שעיכבו נהר הרי אלו נדרי אונסין","ולרבא מאי שנא מהא דתנן הרי זה גיטיך מעכשיו אם לא באתי מכאן עד י\"ב חדש ומת בתוך י\"ב חדש הרי זה גט אמאי והא מינס איתניס אמרי דלמא שאני התם"],[[0,"בנות שוח","בנות שבע:"],[0,"הייתי אומר תאנים שחורות ולבנות אסורין","דהיינו פלוני ופלוני ובנות שוח מותרות דהיינו נמי מין תאנים והיינו נדר שהותר מקצתו ומקצתו אסור דתאנים אסורות ובנות שוח מותרות:"],[0,"ורבי עקיבא היא","כדקתני עד שבא ר' עקיבא ולימד וכו':"],[0,"ופליגי רבנן עליה","דאמרי הכלכלה אסורה ובנות שוח מותרות וקשיא לרבא דאמר דכולי עלמא היכא דאמר פלוני ופלוני אסורין ואבא מותר דכולן מותרין דברי הכל:"],[1,"תריץ לה באומר הייתי אומר כל הכלכלה אסורה ובנות שוח מותרות","היינו דומיא דכולכם אסורין חוץ מאבא דפליגי ור' עקיבא היא ולא רבנן:"],[2,"נדר מחמשה בני אדם הותר א' מהן","כגון דאמר פלוני ופלוני אסורין ופלוני מותר הותרו כולן:"],[2,"חוץ מאחד מהם","דהיינו דומיא דכולכם אסורים חוץ מאבא הוא מותר וכולן אסורין והכי איכא למשמע מינה דהך סיפא בכולכם קמיירי מדקתני חוץ משמע דאמר כולכם ומדסיפא קמיירי בכולכם לא פליגי אלא בלזה ולזה:"],[3,"רישא","דקתני הותר לאחד מהן הותרו כולן ר' עקיבא היא ולא רבנן דלרבי עקיבא נדר שהותר מקצתו הותר כולו:"],[3,"וסיפא","דקתני הוא מותר והן אסורין דברי הכל היא והכא נמי קאמר רבה דבכולכם כולן אסורות דברי הכל (היא):"],[3,"ואי לרבא","אמר לזה ולזה דברי הכל מותר ובכולכם פליגי רישא דקמיירי בלזה ולזה דברי הכל דהכי נמי אמר דלזה ולזה ד\"ה מותר וסיפא הוא מותר והן אסורין רבנן היא דרבא לטעמיה דאמר בכולכם פליגי ורבנן אוסרים מ\"מ בין לרבא בין לרבה רישא בלזה ולזה וסיפא בכולכם:"],[4,"מתני' וחלה הוא","המדיר:"],[5,"גמ' דאתפיס זכוותא","שהביא שטרי זכיותיו לב\"ד והיה צריך לחזור לביתו:"],[5,"ואמר","לב\"ד ולבעל דינו אי לא אתינא וכו':"],[6,"ולנערה לא תעשה דבר","משום דאנוסה היא:"],[7,"וכי תימא קטלא שאני","דגבי קטלא חס רחמנא עלה כי אניסה אבל בשאר אונסין דליכא חיוב קטלא לא מפטר משום אונס:"],[7,"והתנן וכו'","ופטור:"],[8,"ולרבא","דאמר אנוס הוא ופטור:"],[8,"מאי שנא מהא דתנן וכו'","דכי מת בתוך שנים עשר חודש דאע\"ג דאנסיה מיתה הוי גט ופטורה מן הייבום:"],[8,"אמרי","משום הכי הוי גט אע\"פ שמת בתוך הזמן:"]],[[1,"לא באומר אילו הייתי יודע שבנות שוח בתוכה הייתי אומר כל הכלכלה אסורה וכו'","וא\"ת מ\"ש גבי בצל דס\"ד דמקשה שאמר הייתי אומר כל הבצלים וגבי כלכלה ס\"ד דמחשבינן דאמר שחורות וכל חד דחייה לזה ולזה וי\"ל דגבי בצל משמע בצל סתמא ולכך משמע כל הבצלים אבל גבי כלכלה לא אמר כל הכלכלה אלא כלכלה בלא כל והרי לא נדר מן הכלכלה עצמה שאינה ראויה לאכילה אלא ממה שבתוכה נדר ולכך ס\"ד דאמר הייתי אומר תאנים שחורות וכו' ואית דגרסי בברייתא לא הייתי נודר אלא משאר כלכלה והשתא ניחא דמשאר משמע קצת שמפרש תאנים שחורות ולבנות וכו':"],[3,"אי לרבה רישא כרבי עקיבא וכו'","דנדר א' מחמשה משמע שהיה מונה והולך עד חמשה והיינו דאמר פלוני ופלוני ואחזרה קאי שקאמר בסוף הייתי אומר פלוני ופלוני וסיפא דקתני חוץ מאחד מהם היינו שהותר בלשון זה שאמר בסוף הייתי אומר כולכם חוץ מאביו ולכך קאמר דלרבה הוי רישא כר\"ע דווקא ושרי בפלוני ופלוני וסיפא דאסר בכולכם חוץ מאביו מיתוקמא ואפילו כדברי הכל דלרבא רישא דברי הכל כדקתני איהו לעיל דהכל מודים בפלוני ופלוני וסיפא רבנן דוקא דאסרי בכולכם ורבי עקיבא שרי והלכך לדידיה רבנן קתני לה:"],[5,"זכוותיה בבי דינא","שטר זכות:"],[6,"והא אונס רחמנא פטריה","וה\"נ לא הוצרך להתנות עליו דדבר פשוט הוא:"],[7,"וכי תימא קטלא שאני","אבל הכא לעולם הוי פושע ממה שלא התנה להוציא אונס מן הכלל הא תנן אלו הן נדרי אונסין ולא אמרינן איבעי לאיתנויי הכא נמי לא שנא וא״ת באיזה אונס מיירי הא באונסא דשכיח איבעי ליה לאיתנויי אי נמי אונס דשכיח ולא שכיח הא נמי איבעי לאיתנויי ולא אתני כדמוכח בכתובות גבי גט ובשמעתין מדמה ליה לגיטין וי״ל דמיירי באונס דלא שכיח כלל וא״ת א״כ דמיירי באונס דלא שכיח כלל מאי טעמיה דרב הונא דאמר דליבטלן זכותיה והא אונס דלא שכיח כלל לא איבעי לאתנויי כדמוכח בגיטין פרק מי שאחזו (גיטין דף עג -) גבי נפל מן הגג וי״ל דשאני הכא דאמר ליבטלן זכוותיה משום שמודה שהשטר פסול לכך אמר ליבטלן זכוותיה אפי' באונס דלא שכיח דהודאת בעל דין כמאה עדים דמי והא מודה שראיותיו שקר הן שהרי אינו מוחל לו שום דבר אלא מטעם הודאה:"]]],[["דאי הוה ידע דמית מן לאלתר הוה גמר ויהיב גיטא","מאי שנא מההוא דאמר להו אי לא אתינא מכאן עד תלתין יומין ליהוי גיטא אתא ופסקיה מעברא אמר להו חזו דאתאי חזו דאתאי ואמר שמואל לא שמיה מתייא אמאי והא מינס אניס","דלמא אונסא דמיגליא שאני ומעברא מיגלי אונסיה","ולרב הונא מכדי אסמכתא היא ואסמכתא לא קניא שאני הכא דמיתפסן זכותן","והיכא דמיתפסין לאו אסמכתא היא והתנן מי שפרע מקצת חובו והשליש את שטרו ואמר אם אין אני נותן לו מכאן עד ל' יום תן לו שטרו","הגיע זמן ולא נתן רבי יוסי אומר יתן ורבי יהודה אומר לא יתן ואמר רב נחמן אמר רבה בר אבוה אמר רב אין הלכה כרבי יוסי דאמר אסמכתא קניא","שאני הכא דאמר לבטלן זכותיה","והלכתא אסמכתא קניא והוא דלא אניס והוא דקנו מיניה בבית דין חשוב:","\u0001מתני׳\u0002 נודרין להרגין ולחרמין ולמוכסין שהיא תרומה אף על פי שאינו תרומה שהן של בית המלך אף על פי שאינן של בית המלך בית שמאי אומרים בכל נודרין"],[[0,"דאי הוי ידע","בשעת התנאי דמיית בתוך הזמן לאלתר גמר ויהיב גיטא מעכשיו הלכך הוי גט ולהכי גמר בלביה למיהוי גט אבל האי אי הוה ידע דאתניס לא הוה מבטל זכוותיה ולא גמר ומקני:"],[1,"ואמר להו שמואל לא שמיה מתייא","אע\"ג דאניס והא מינס אניס ולא ליהוי גיטא:"],[2,"דלמא אונסא דמיגליא שאני","ומעברא אונסא דמיגליא הוא דזימנין דלא משתכחא בהאי גיסא ומבעיא ליה לאסוקי אדעתיה (ודלמא אסיק אדעתיה) ואפי' הכי לא התנה משום הכי אי מיתניס בהאי זמן אמר גמר ומקני דליהוי גט אפילו עיכבו שום אונס אבל בעלמא אי איתניס פטור:"],[3,"ולרב הונא","דאמר בטלן זכוותיה אמאי הא אסמכתא הוא דברים בעלמא וסמך על דעתו כסבור שהוא יכול לבא בזמנו להכי קאמר הכי ואסמכתא לא קניא:"],[3,"שאני הכא","להכי קני:"],[3,"דאתפיס זכותיה לב\"ד","דכגבוי דמי ולא הוה אסמכתא:"],[4,"מי שפרע מקצת חובו והשליש את שטרו","שהניח השטר שהיה לו לבעל חוב עליו ביד נאמן ואמר לו אם איני פורע החוב מכאן עד ל' יום תן לו שטרו למלוה ויחזור ויגבה בו כל מה שכתוב בו בתחילה:"],[5,"ולא נתן","ולא פרע:"],[5,"רבי יוסי אומר יתן","השליש השטר למלוה ואע\"ג דאסמכתא היא דסבור היה לפרוע באותו הזמן קנה המלוה את השטר:"],[5,"אין הלכה וכו'","הא הכא אע\"ג דאתפיס השטר ביד [השליש] הויא אסמכתא ולא קניא לטעמיה דרב:"],[6,"שאני הכא דאמר ליבטלן זכותיה","שלא יהא בהן ממש דזהו חמור מתן לו שטרו:"],[7,"והלכתא אסמכתא קניא","ואע\"ג דלא מתפיס:"],[7,"והוא דלא אניס","באונסא דמוכחא לאינשי כי האי דלעיל דפסקיה מעברא:"],[7,"והוא דקנו מיניה","שלא יחזור בו:"],[7,"ובב\"ד חשוב","שיהא מומחה לרבים וכל הני תלת מילי בעינן בה דאי הוה חד בלא אידך לא קני אלא כולהו ג' בעינן דלא אניס וקנין ובב\"ד חשוב:"],[8,"מתני' להרגין","שהוא הורג על עסקי ממון שאם בא להורגו יכול לדור על זה שהוא של תרומה ויאמר נדר זה עלי אם אינו של תרומה אע\"פ שאינו של תרומה כדי שלא יטלם לפי שיש חיוב מיתה לזו והנדר מותר והיינו נמי נדרי אונסין:"],[8,"ולחרמין","שהוא ליסטים בעלמא שאינו הורג:"],[8,"ולמוכסים","נוטל מכס המלך ורוצה ליטול פירותיו בע\"כ:"],[8,"אף על פי שאינן של תרומה","יכול לידור שהן של תרומה כדי שלא יטלם ומתני' לא זו אף זו קתני:"],[8,"בכל נודרים","להם:"]],[[3,"ולרב הונא אסמכתא היא","הוה מצי למימר דס\"ל לרב הונא דאסמכתא קניא אלא ניחא ליה ליישב רב הונא אליבא דהלכתא דר\"נ פסיק בסמוך כרבי יהודה:"],[6,"שאני הכא דאמר ליבטלו זכוותיה","פי' מטעם הודאה כדפרישית לעיל:"],[7,"והלכתא אסמכתא קניא וכו'","לכאורה דאמר בלא מעכשיו דאילו אמר מעכשיו מועיל שפיר בלא קנין בב\"ד חשוב כדמוכח פר' איזהו נשך (ב\"מ דף סז) ומיהו אור\"י דע\"כ הכא מיירי דאמר מעכשיו מדאמר דקנו מיניה וסתם קנין בסודר וקנין סודר בלא מעכשיו אינו מועיל כלום כדאמר לקמן פרק השותפין (נדרים דף מח:) דהא הדר סודרא למרא פירוש כשחל הקנין אינו מועיל כלום כגון אם אמר לאחר ל' יום א\"כ אין הקנין עד לאחר ל' יום וכבר הדרא סודרא למריה וא\"כ ע\"כ מיירי הכא דאמר מעכשיו ואפ\"ה קאמר דדוקא בב\"ד חשוב קנו מיניה אבל בלא קנין בב\"ד חשוב לא מועיל מעכשיו בלא אסמכתא והא דמשמע באיזהו נשך דמעכשיו מועיל בלא ב\"ד חשוב י\"ל דאסמכתא דהתם שאני לפי שהוא דרך מכר דמיירי שהלוהו על שדהו ואמר ליה אם אין אתה נותן לי מכאן ועד שלש שנים הרי הוא שלי אור\"ת שלכך נהגו לאסוף כל בני העיר בשעת שידוכין היינו כי היכי דליהוו ב\"ד חשוב ולא יהא ערבון אסמכתא ואין נראה לר\"י שהרי כמה פעמים אין שם אלא קרובים וגם אין מתקיים לשום קיום תנאי לכ\"נ דלענין ערבון של שידוכין נראה דהכי הוא דקני שפיר בלא מעכשיו וגם בלא קנין ב\"ד חשוב דלפי שמתבייש ביותר מי שחוזר בו לא חשוב אסמכתא כלל דלאו גוזמא הוא מה שמתנה עמו בערבון אם יחזור בו דדמי בושתו הוא ולא גזרינן כמו אם אוביר ולא איעביד אשלם במיטבא:"],[8,"נודרים להרגין","הורגים נפשות על עסקי ממון ולחרמים קילי טפי וזו אף זו קתני:"],[8,"שהם של תרומה","וא\"ת התינח הרגין וחרמים שגוזלין ממון ועתה כשאמר להם שהם של תרומה לא יגזלו אותם דאינם מתכוונים כ\"א לגזול ולא לאיסורא כיון שאינה ראויה לאכילה לזרים אבל מוכסין מאי אהני לעולם ישאל המכס וי\"ל שלא היו רגילים ליקח מכס זה ממוליכי תרומה לכהנים:"]]],[["חוץ מבשבועה ובית הלל אומרים אף בשבועה","בית שמאי אומרים לא יפתח לו בנדר ובית הלל אומרים אף יפתח לו בית שמאי אומרים במה שהוא מדירו ובית הלל אומרים אף במה שאינו מדירו","כיצד אמר לו אמור קונם אשתי נהנית לי ואמר קונם אשתי ובני נהנין לי בית שמאי אומרים אשתו מותרת ובניו אסורין ובית הלל אומרים אלו ואלו מותרין:","\u0001גמ׳\u0002 והאמר שמואל דינא דמלכותא דינא","אמר רב חיננא אמר רב כהנא אמר שמואל במוכס שאין לו קצבה דבי ר' ינאי אמר במוכס העומד מאליו:","שהן של בית המלך ואף על פי שאינן של בית המלך: היכי נדר אמר רב עמרם אמר רב באומר יאסרו פירות העולם עלי אם אינן של בית המלך","כיון דאמר יאסרו איתסרו עליה כל פירי עלמא באומר היום אי דאמר היום לא מקבל מיניה מוכס","באומר בלבו היום ומוציא בשפתיו סתם ואף על גב דסבירא לן דברים שבלב אינם דברים לגבי אונסין שאני:","בית שמאי אומרים בכל וכו' בית שמאי אומרים במה שהוא מדירו ובית הלל אומרים אף בשאינו מדירו כיצד אמר לו קונם אשתי נהנית לי ואמר קונם אשתי ובני נהנין לי בית שמאי אומרים אשתו מותרת ובניו אסורין ובית הלל אומרים אלו ואלו מותרין:","אמר רב הונא תנא בית שמאי אומרים לא יפתח לו בשבועה ובית הלל אומרים אף יפתח לו בשבועה לבית שמאי בשבועה הוא דלא יפתח לו הא בנדר יפתח לו והא תנן בית שמאי אומרים לא יפתח לו בנדר","ותו מיפתח הוא דלא יפתח לו בשבועה הא מידר נדר בשבועה והתנן בית שמאי אומרים בכל נודרין חוץ מבשבועה","תנא מתניתין בנדר להודיעך כחן דבית שמאי תנא ברייתא בשבועה להודיעך כחן דבית הלל","רב אשי אמר הכי קתני בית שמאי אומרים אין שאלה בשבועה ובית הלל אומרים יש שאלה בשבועה:","\u0001מתני׳\u0002 הרי נטיעות האלו קרבן אם אינן נקצצות טלית זו קרבן אם אינה נשרפת יש להן פדיון הרי נטיעות האלו קרבן עד שיקצצו טלית זו קרבן עד שתשרף"],[[0,"חוץ מבשבועה","שלא יאמר יאסרו פירות שבעולם עלי בשבועה אם אינן של תרומה:"],[1,"לא יפתח לו בנדר","אם הליסטים אינו מזקיקו שידור לא יפתח לו הוא בעצמו:"],[1,"במה שהוא מדירו","בלבד ידור ולא בדבר אחר כדמפרש:"],[2,"כיצד אמר לו וכו' אשתו מותרת לו","דהיינו במה שהוא מדירו:"],[2,"ובניו אסורים","דהיינו במה שלא מדירו:"],[3,"גמ' דינא דמלכותא דינא","ולאו נדרי אונסין נינהו ואמאי נודרין למוכסין להבריח המכס של מלכות:"],[4,"שאין לו קצבה","שנוטל כל מה שרוצה:"],[4,"במוכס העומד מאליו","שאינה של מלכות:"],[6,"כיון דאמר יאסרו","ולא אמר מילתא דהערמה איתסרו ליה:"],[6,"אי דאמר היום לא מקבל מיניה מוכס","ואינו מניחו בשביל אותו נדר שלא יטול הפירות שהרי שומע דבהערמה נדר:"],[7,"","באומר בלבו היום:"],[7,"אינם דברים","בעלמא:"],[9,"לא יפתח לו בשבוע","שלא יאמר לו אם תרצה אשבע לך:"],[9,"הא בנדר יפתח לו","שיאמר לו אם תרצה אדור לך נדר:"],[10,"הא מינדר נדר ליה בשבועה","אם הליסטים מזקיקו לכך וידור לו כן בלשון שבועה כדאמרן לעיל:"],[10,"והא תנן וכו'","ואמאי קתני בברייתא דלא יפתח לו בשבועה:"],[11,"תריץ הכי תנא במתני' בנדר להודיעך כחן דבית שמאי","דאפילו בנדר גרידא לא וכ\"ש בנדר שבועה:"],[11,"וברייתא תנא בשבועה להודיעך כחן דב\"ה","דאפי' בשבועה יפתח לו. וברייתא משום ב\"ה נשנית ולאו דוקא היא ולא מצית למימר התם בשבועה הוא דלא יפתח וכו' ולא מקשינן דב\"ש אדב\"ש:"],[12,"רב אשי אמר הכי קתני","האי לא יפתח דברייתא לא משמע כדאמרינן דבאונסין קאי אלא האי לא יפתח דב\"ש סברי לא יפתח לו החכם פתח לחרטה להשאל על שבועתו דאין שאלה לשבועה לפני החכם וליכא למידק מינה שום קושיא:"],[13,"מתני' אמר הרי נטיעות האלו קרבן","כלומר שיהו הקדש:"],[13,"אם אינן נקצצות","היום מוקי לה בגמרא ועבר היום ולא נקצצו ולא נשרף הטלית הרי הן הקדש ויש להן פדיון והדמים יכנסו להקדש והם יצאו לחולין:"],[13,"אבל אם אמר הרי הנטיעות האלו קרבן עדי שיקצצו אין להם פדיון","לעולם כל זמן שלא נקצצו ואין יוצאין לחולין אלא קדושות הן שהן בקדושת הגוף לעולם ואין להם תקנה עולמית שאפילו פדאן חוזרות וקדושות דכיון דאמר עד שיקצצו אין להם פדיון לעולם כל זמן שלא נקצצו משמע דלעולם יהיו קרבן עד שיקצצו:"]],[[3,"והא אמר שמואל דינא דמלכותא דינא","פי' בב\"ק (דף קיג):"],[4,"במוכס שאין לו קצבה","ואין תאמר מכל מקום דינא דמלכותא הוא וי\"ל כיון שאין דרך המוכסין כך אין זה דינא אלא גזילה של מוכס עצמו ואע\"ג דסבירא לן דברים שבלב אין דברים לגבי אונסין שרו רבנן וא\"ת הא לעיל (נדרים דף כ:) - גבי ד' נדרים התירו בלא שום אונס אף על גב דהוה דברים שבלב הוויין דברים וי\"ל דהתם היינו טעמא משום דאנן סהדי שדעתו לכך וכיון דאנן סהדי הרי כאילו פירש בהדיא ולא הוי דברים שבלב אבל הכא ליכא למימר אנן סהדי אי לאו האונס ובין תלמיד חכם ובין עם הארץ מיתסר בלא אונס כשאמר בלבו היום כיון דלא שייך אנן סהדי וההיא דרבי עקיבא שנשבע ומבטלה בלבו (במסכת כלה) התם נמי הוי אונס שהיה צורך גדול לידע לברר על אותו עז פנים שהיה ממזר:"],[12,"וב\"ה אומרים יש שאלה בשבועה","פי' נזקקין להתיר לו ולמ\"ד לעיל (נדרים דף כב:) אין נזקקין לאלהי ישראל מוקי הך דב\"ה דהכא בנדר בודאי אי נמי בשבועה רק [לא] הזכיר שם שמים:"],[13,"הרי נטיעות האלו קרבן","הכא מיירי שמתפיס להו לדמי קרבן ממש דלא מיירי בקונמות מדלא אמר כקרבן ואפילו לר\"מ דלא שנא בין הקרבן לקרבן דבכל ענין יחול אסור קונם ה\"מ כשאוסר האיסור או עליו או על חבירו כגון שאמר ככר זו קרבן או עלי או עליך אבל כאן שאמר קרבן סתמא ואינו מדכיר קרבן גבי שום אדם הלכך ע\"כ לדמי קרבן אמר:"],[13,"אם אינן נקצצות","כגון דאיכא זיקא נפישא כדאמר בגמ' וסבור הוא שלא יוכלו לימלט מן הרוח וכן טלית זו אם אינה נשרפת כגון דאיכא דליקה וסבור שלא יוכל לימלט מן האש ואפילו הכי יש להן פדיון כלומר הם קדושים ופדיון מועיל בהם ואגב דקתני בסיפא אין להן פדיון תנא נמי ברישא יש להם פדיון אבל עיקר חידוש ממה שהם קדושים כדפירשתי:"]]],[["אין להם פדיון:","\u0001גמ׳\u0002 וליתני קדושות ואין קדושות איידי דבעי למיתנא סיפא אין להם פדיון תנא נמי רישא יש להם פדיון","היכי נדר אמר אמימר באומר אם אינן נקצצות היום ועבר היום ולא נקצצו אם כן למה לי למימר פשיטא לא צריכא כגון דאיכא זיקא נפישא","והא קתני לה גבי טלית וטלית לשריפה קיימא [אין] כגון דאיכא דליקה הכא נמי דאיכא זיקא נפישא וסלקא דעתך דמסיק אדעתיה דלא מיתנצלן ומשום הכי קא נדר קא משמע לן:","הרי נטיעות האלו קרבן כו': ולעולם אמר בר פדא פדאן חוזרות וקודשות פדאן חוזרות וקודשות עד שיקצצו נקצצו פודן פעם אחת ודיו ועולא אמר כיון שנקצצו שוב אין פודן"],[[1,"גמ' וליתני","בהאי לישנא ברישא דהיכא דאמר הרי הפירות האלו קרבן [אם אינם נקצצות] קדושות ואינן קדושות קדושות דחל קדושה עלייהו ואינן קדושות דיש להן פדיון דלפי ההוא עניין דקתני סיפא הויין קדושות ואינן קדושות דאילו בסיפא דהתם דאמר עד שיקצצו הוי קדושה גמורה שהרי הן בקדושת הגוף שאין להם פדיון כל זמן שאין נקצצות אע\"ג דקדושת דמים הוא ואילו כי אמר אם אינן נקצצות ליכא קדושה חמורה שהרי יש להם פדיון ולהכי כי אמר אם אינן נקצצות לענין כי אמר עד שיקצצו קדושות ואינן קדושות הן:"],[1,"","תריץ אין הכי נמי הוה ליה למתני אלא איידי וכו':"],[2,"א\"כ למה ליה למימר","דחל קדושה עלייהו כיון שעבר היום ולא נקצצו:"],[2,"לא צריכא כגון דאיכא זיקא נפישא","שמנשבת רוח קשה בעולם דמסיק אדעתיה דמיתבר להו זיקא דהיינו נקצצות וסד\"א לא גמר בלבו להקדישו אלא אדעתא דמיתבר להו זיקא אמר הכי ולא צריכי פדיון דלא חל עלייהו קדושה וכחולין דמי קמ\"ל דחל קדושה עלייהו דלהקדש גמור מתכוין:"],[3,"[והא וכו']","כלומר היכי מצית אמרת דאיכא זיקא נפישא והקתני לה דומיא דטלית וטלית מי קיימא לשרפה בתמיה:"],[3,"אין כגון דאיכא דליקה","ומסיק אדעתיה דלא מיתצל ולהכי קאמר אם אינה נשרפת:"],[3,"הכי נמי וכו'","וסד\"א דלא מתכוין להקדש כלל כדפרשינן:"],[3,"קמ\"ל","דחל קדושה עלייהו:"],[4,"ולעולם","בתמיה. מדקתני אין להן פדיון משמע שלעולם אין להם פדיון אפי' לאחר קציצה:"],[4,"אמר בר פדא","כל זמן שלא נקצצו עדיין חוזרות וקדושות:"],[4,"נקצצו פודן פעם אחת ודיו","ויצאו לחולין ושוב אינו פודן דהא חולין הן:"]],[[1,"","ה\"ג רבינו שמואל וליתני קדושות ול\"ג ואין קדושות דמשמע דפריך וליתני בסיפא דאינה קדושה ואדרבה בסיפא קדושה טפי דאין להם פדיון היינו דאין מועיל להן פדיון כדקאמר בסמוך אלא גרסינן וליתני קדושות ותו לא וארישא פריך ור\"י [פירש] דשפיר גרסינן ליה ותרווייהו קיימי ארישא ופריך הכי וליתני הרי אלו קדושות אם אינם נקצצות ואינם קדושות אם נקצצו וממילא ידעינן דפשיטא דיש להן פדיון כשאר כל חרמי דמים:"],[1,"איידי דבעי למיתני בסיפא אין להם פדיון","כלומר שאין פדיון מועיל בהם דלעולם חוזרות וקדושו' כדמסיק תנא נמי רישא יש להם פדיון:"],[2,"היכי נדר","פר\"י דאי סתם כדקתני ולא נתן זמן לקציצתן א\"כ אינם קצוצות ואין לך קצוצות דאינם נקצצות לסוף אלף שנים מחמת שהיא מתייבשת:"],[2,"דאיכא זיקא נפישא","וא\"ת מה ענין זה לשאר נדרים דלעיל דקתני ד' נדרים התירו וי\"ל משום דמהו דתימא דחשיב נדרי זרוזין שאין נדר אלא לאמן דבריו שלא יתנצלו ולא משום דדעתו להקדישם אם ינצלו קמ\"ל דאפ\"ה הוו קדושות דגמר בלבו להקדישם [שסבור] הוא שיכול להיות דמינצלן:"],[4,"אין להם פדיון ולעולם","בתמיה וכי לעולם לא יהא להם פדיון דפשיטא ליה דאין להם פדיון ר\"ל שאין מועיל להם פדיון כמקדש וככלים דאין להם פדיון:"],[4,"אמר בר פדא פדאן חוזרות וקדושות וכן לעולם עד שיקצצו","שכך ר\"ל הרי הן קרבן עד שיקצצו דכל שאפדם תחזור ותחול קדושה עליהם כל שעה נקצצו פודן פעם אחת דקדושה שבהן לא פקעה בכדי אע\"ג דעד שיקצצו קאמר:"],[4,"עולא אמר כיון שנקצצו שוב אין פודן","דלא הקדישן אלא עד שיקצצו דפקעה קדושה בכדי כשנקצצו וצ\"ע לעולא אם [פדאן] חוזרות וקדושות או לא וי\"ל שמודה דאם פדאן חוזרות וקדושות כל זמן שלא נקצצו כמו לבר פדא דמדלא פליג עליה שהרי שיטה דהש\"ס משמע כן מדפריך ולעולם משמע פשיטא ליה דאין להם פדיון דקאמר היינו דאינן בתורת פדיון דפשיטא ליה דעד שיקצצו הם קדושות וא\"ת מנלן דלעולא חוזרות וקדושות וכ\"ת מל' עד שיקצצו הא איצטריך לעולא לכוין לשון כשנקצצו דשוב אין פודן כדפרישית וא\"כ מנ\"ל דפדאן חוזרות וקדושות קודם קציצה. וי\"ל דא\"כ הוה ליה למימר (לנודר) הרי הנטיעות האלו קרבן עד שנקצצו ולא יותר או אומר אינם קרבן אלא עד שנקצצו ואז משמע תרתי משמע דפדאן חוזרות וקדושות קודם קציצה ומשמע נמי דאחר קדושה פקעה קדושה מנייהו מדלא אמר הרי הן כקרבן לעולם:"]]],[["אמר ליה רב המנונא קדושה שבהן להיכן הלכה ומה אילו אמר לאשה היום את אשתי ולמחר אי את אשתי מי נפקא בלא גט","אמר ליה רבא מי קא מדמית קדושת דמים לקדושת הגוף קדושת דמים פקעה בכדי קדושת הגוף לא פקעה בכדי","אמר ליה אביי קדושת הגוף לא פקעה בכדי והתניא שור זה עולה כל שלושים יום ולאחר שלושים יום שלמים כל שלושים יום עולה לאחר שלושים יום שלמים אמאי קדושת הגוף נינהו ופקעה בכדי","הכא במאי עסקינן דאמר לדמי","אי הכי אימא סיפא לאחר שלושים יום עולה ומעכשיו שלמים אי אמרת בשלמא חדא בקדושת הגוף וחדא בקדושת דמים"],[[0,"א\"ל רב המנונא","לעולא היאך יוצאין לחולין בלא פדייה:"],[0,"וכי קדושה שלהן להיכן הלכה","כלומר היכי פקעה בכדי אע\"פ שנקצצו:"],[0,"והלא האומר לאשה היום את אשתי","שתהא לי מקודשת היום:"],[0,"ולמחר אי את אשתי","אע\"פ שהתנה כך בשעת קידושין:"],[0,"מי נפקא למחר בלא גט","ה\"נ אע\"ג דנקצצו היינו כמו למחר אין את אשתו ולא נפקי בלא פדיון:"],[1,"מי קא מדמית קדושת הגוף","וכו'. הני נטיעות דקדישי לפדייה קדישי קדושת דמים ולהכי פקעו מאחר שנקצצו אבל אשה קדושת הגוף היא ולהכי לא פקעה בכדי:"],[2,"והתניא מי שאמר שור זה עולה כל ל' יום","שאם יקרב בתוך ל' יום עולה ואם לאחר ל' יום יקרב יהא שלמים:"],[2,"כל ל' יום הוי עולה","כמו שאמר ולאחר ל' יצא מקדושת עולה והוי שלמים:"],[2,"ואמאי","נפקא מקדושת עולה הא קדושת הגוף נינהו ופקעה בכדי וקשיא לעולא דאמר קדושת הגוף לא פקעה בכדי:"],[3,"אמר לך עולא הכא במאי עסקינן","דפקעה קדושת עולה:"],[3,"דאמר לדמי","דאמר הכי תורת דמיו עולה כל ל' יום לאחר שאפדנו ואקח בדליו עולה להכי לאחר ל' יום פקעה בכדי דקדושת דמים היא אבל קדושת הגוף אכתי לא פקעה:"],[4,"א\"ה","דמוקמת לה לדמי:"],[4,"אימא סיפא","דההיא אמר שור זה לאחר שלשים יום עולה ומעכשיו ועד שלשים יום שלמים הכי הוי כדאמר איהו:"],[4,"אי אמרת בשלמא","רישא בקדושת הגוף וסיפא בקדושת דמים:"]],[[0,"היום את אשתי ולמחר אי את אשתי מי נפקא בלא גט","וא\"ת ומנלן דצריך גט וי\"ל דבפרק המגרש בגטין (דף פג:) מיבעיא לן גבי האומר לאשתו היום אי את אשתי ולמחר את אשתי כלומר תהא מגורשת היום ולמחר לא תהא מגורשת מהו ופשיט התם כיון דפסקה פסקה והויא מגורשת לעולם ואם כן גבי קדושין נמי הוי מקודשת לעולם דאיתקש הויה ליציאה וס\"ד השתא דבהא לא פליג עולא:"],[2,"והתנן שור זה עולה כל ל' יום עולה","ומועלין בה כל אותן שלשים יום - אור\"י דגרס דתניא שהיא ברייתא ולא משנה:"],[2,"שור זה עולה כל שלשים יום ולאחר ל' יום שלמים כל ל' יום עולה","ומועלין בה כל אותן ל' יום [וגם] אם בא כל אותן ל' יום מקריבו כדין עולה ואם נתעכב להקריבו עד לאחר ל' יום הוי משם ואילך שלמים אלמא פקעה קדושת הגוף בכדי ולא דמי להא דאמר בזבחים (דף ל -) תחול זו ואח\"כ תחול זו לא חיילא דשאני הכא דלכתחילה לא אמר סתם שיהיה עולה אלא אמר כל ל' יום:"],[3,"דאמר לדמי","שאמר לדמי עולה וא\"ת והא אמרינן הקדיש זכר לדמיו קדוש קדושת הגוף וי\"ל דאיירי הכא דאמר לדמי נסכים דמודה שם רבא כדאמר בשבועות בפ\"ק (דף יא -) אי נמי התם בתם ולכך קדוש קדושת הגוף אבל הכא בבעל מום ולכך קדוש קדושת דמים:"]]],[["היינו דאיצטריך ליה לתנא למיתנא תרתי דסלקא דעתך אמינא קדושת הגוף לא פקעה בכדי קדושת דמים פקעה בכדי אמטו להכי תנא תרתי","אלא אי אמרת אידי ואידי קדושת דמים למה לי למיתנא תרתי השתא יש לומר מקדושה חמורה לקדושה קלה פקעה מקדושה קלה לקדושה חמורה צריכא למימר","לימא תיהוי תיובתא דבר פדא דאמר לא פקעה קדושה בכדי","אמר רב פפא אמר לך בר פדא הכי קאמר אם לא אמר מעכשיו שלמים לאחר ל' יום עולה הוי","מידי דהוה האומר לאשה התקדשי לי לאחר ל' יום דמקודשת ואף על פי שנתעכלו המעות","פשיטא לא צריכא דהדר ביה","הניחא למאן דאמר אינה חוזרת אלא למאן דאמר חוזרת מאי איכא למימר","אפילו למאן דאמר התם חוזרת הכא שאני דאמירתו לגבוה כמסירתו להדיוט","יתיב רבי אבין ורב יצחק ברבי קמיה דרבי ירמיה וקא מנמנם רבי ירמיה יתבי וקאמרי לבר פדא דאמר פדאן חוזרות וקודשות"],[[0,"היינו דאיצטריך וכו'","דאמינא להכי תני תרתי דבין קדושת הגוף בין קדושת דמים פקעה בכדי:"],[1,"למה לי למתני תרתי השתא מקדושה חמורה לקדושה קלה פקעה","עולה שהיא חמורה לקדושת שלמים שהיא קלה:"],[1,"מקדושה קלה","כלומר שלמים דקלה לקדושת עולה שהיא חמורה מיבעיא אלא לאו חד לקדושת הגוף וחד לקדושת דמים דתרוייהו פקעי ותיובתא דעולא וליכא פירוקא:"],[2,"נימא תיהוי תיובתיה דבר פדא","דהכא אמר דאפי' קדושת הגוף פקעה בכדי ובר פדא אמר נקצצו פודן פעם אחת דאפי' קדושת דמים לא פקעה בכדי:"],[3,"חסורי מיחסרא והכי קתני","האומר שור זה עולה כל ל' יום ומעכשיו לאחר ל' יום שלמים כל ל' עולה לאמר ל' יום שלמים דהואיל ואמר מעכשיו חל עליה שם שלמים מעכשיו ומשום הכי הוי שלמים לאחר ל' יום דקדושת הגוף פקעה בהכי בכדי הואיל ואמר מעכשיו אבל אם לא אמר מעכשיו שלמים לאחר ל' יום עולה הוי אפילו לאחר ל' יום דמקודשת לאחר ל' יום דהתם לא פקעה קדושת הגוף בכדי:"],[4,"דמקודשת","לאחר ל' יום דכי לא אמר מעכשיו דמיא להא האומר לאשה הילך פרוטה זו והתקדשי לי לאחר ל' יום דמקודשת לאחר ל' יום ואע\"ג דנתעכלו המעות של קדושין שאינם בעולם הויא מקודשת לאחר ל' יום ה\"נ כי לא אמר מעכשיו אע\"ג דהלכו להך שלשים יום של עולה השתא נמי עולה הוי וסיפא דקתני לאחר שלשים יום עולה ומעכשיו ועד שלשים יום שלמים דלאחר ל' יום הוה עולה ופקע קדושת שלמים אע\"ג דלא אמר מעכשיו התם משום דקדים ואמר ברישא לאחר שלשים יום עולה דכיון שהזכיר עולה תחלה נעשה כאומר מעכשיו הלכך לאחר שלשים יום עולה הוי והכא הוא משום דאמר מעכשיו פקעה קדושה בתרוייהו בין בקדושת דמים בין בקדושת הגוף אבל בעלמא אפילו קדושת דמים לא פקעה בכדי ולא קשה לבר פדא ותיובתא דעולא כדקיימא קיימא:"],[5,"פשיטא","כלומר דכיון דמחסרת למתני' ותרצת דה\"ק שור זה עולה כל שלשים יום ומעכשיו לאחר שלשים יום שלמים דלאחר שלשים יום שלמים הוי ולמה לי למימר שוב דה\"ק אם לא אמר מעכשיו וכו' פשיטא דכיון דאמר צריך למימר מעכשיו ממילא ידענא דאם לא אמר מעכשיו לאחר שלשים יום שלמים הוי עולה:"],[5,"תריץ לא צריכא","דהא קמ\"ל אי הדר ביה דאי הוה קתני כדקאמרת דלאחר שאמר שור זה עולה כל שלשים יום לאחר שלשים יום שלמים אע\"ג דהשתא הדר ביה ואמר מעכשיו הואיל ומעיקרא כשאמר כל שלשים יום עולה לא אמר מעכשיו קודם שאמר לאחר שלשים יום שלמים ולא כלום קאמר ואפי' לאחר ל' יום עולה הוי דהא קמ\"ל דדוקא בעינן שיאמר בתחלה מעכשיו קודם שיאמר לאחר שלשים יום שלמים כדקאמר לעיל:"],[6,"הניחא למ\"ד אינה חוזרת","שאם עמדה ונתקדשה לשני בתוך שלשים יום אינה מקודשת לשני מצי למימר מידי דהוה האומר לאשה וכו':"],[6,"אלא למ\"ד חוזרת","שאם עמדה ונתקדשה לשני בתוך ל' יום מקודשת לשני היכי מצי למימר דכי לא אמר מעכשיו לאחר שלשים יום עולה הוי. תריץ אפי' למ\"ד חוזרת אפי' הכי התם אי לא אמר מעכשיו מעיקרא הוי עולה לאחר שלשים יום:"],[7,"דאמירתו לגבוה כמסירתו להדיוט","וכיון דאמר מעכשיו עולה ולא אמר מעכשיו שלמים לא פקעה בכדי ולעולם הוי עולה:"],[8,"לבר פדא דאמר פדאן חוזרות וקודשות","ואפי' לאחר שנקצצו חוזר ופודן:"]],[[2,"לימא תיהוי תיובתא דבר פדא דאמר לא פקעה קדושה בכדי","וא\"ת אמאי לא פריך לעולא כמו לבר פדא מקדושת הגוף מהא דהא סבירא ליה קדושת הגוף לא פקעה בכדי מההיא דהאומר לאשה היום את אשתי וכו' וי\"ל דאביי שהקשה לרבא וקדושת הגוף לא פקע בכדי וכו' כדי לסתור דברי רבא שהיה אומר דמודה עולא דקדושת הגוף נמי לא פקע בכדי ומכל מקום לא קשה לעולא מההיא דהאומר לאשתו משום דלאו היינו בברייתא אלא מימרא (לעולא) ולכך לא פריך לעולא:"],[3,"אמר לך בר פדא ה\"ק","סיפא אם לא אמר מעכשיו שלמים לאחר ל' יום עולה הוי - פי' שלא אמר [אלא] לאחר שלשים יום עולה הרי זו עולה ואשמעינן חידוש אע\"ג שלא אמר דיבורו בשעה שקדושה חלה דאימת חלה הקדושה לאחר שלשים יום ונדר אחר דיבור אפ\"ה חלה הקדושה שפיר לאחר ל' יום:"],[4,"מידי דהוה האומר לאשה וכו '","וא\"ת בשלמא סיפא מתרצא שפיר אלא רישא דאמר שור זה כל ל' יום עולה לאחר שלשים יום שלמים אלמא דפקעה - קדושה בכדי והיכי מתרץ לה וי\"ל דהכי פירושא כל ל' יום עולה וה\"ה דהוי עולה לאחר ל' יום נמי דקדושה לא פקעה בכדי וזימנין דהוי לאחר ל' יום שלמים כגון דאמר לאחר ל' יום שלמים ותו לא וכ\"ת תרתי למה לי לא זו אף זו קתני לא זו דקדושת הגוף אלא אפילו קדושת דמים נמי לא פקעה וקשה דלשון לא משמע כן דמדקאמר כל ל' יום עולה משמע כל ל' יום עולה דוקא אבל לאחר ל' יום לא הוי עולה לכ\"נ לר' אלחנן דרישא נמי כגון הרי שור זה עולה כל ל' יום מעכשיו ולאחר ל' יום שלמים הוי והוי תוך ל' יום עולה ולאחר שלשים יום שלמים אע\"ג דקדושה לא פקעה בכדי שאני הכא שבתוך כדי דיבור שהתפיסו לעולה אמר מעכשיו ולאחר שלשים יום שלמים א\"כ התחיל קדושת שלמים מיד כמו קדושת עולה אלא שלא נגמרה קדושת שלמים עד לאחר שלשים יום דהכי נמי א\"ר יוחנן פרק האומר דקידושין (דף נח:) דהאומר לאשה הרי את מקודשת לי מעכשיו ולאחר שלשים יום שהקידושין מתחילין מיד ואין נגמרים עד לאחר שלשים יום וא\"ת תינח לאחר שלשים יום הוי לגמרי שלמים וקרב שלמים כיון דקדושת העולה פקעה כדפרישית אלא תוך שלשים יום היכי קרב עולה כדקתני בברייתא ל' יום עולה והלא יש כאן נמי קדושת שלמים בהדי קדושת עולה כדפרישית שמעכשיו מתחיל קדושת שלמים וי\"ל כל שלשים יום עולה דקאמר לאו לענין הקרבה אלא לענין מעילה דכיון דיש בו נמי קדושת עולה מועלין בו אי נמי לענין שלא להקריב שלמים תוך שלשים יום ועי\"ל דאף לענין הקרבה הוי עולה תוך ל' יום שאין קדושת שלמים עליו תוך ל' יום יותר לבטל קדושה ואע\"ג דלגבי קידושי אשה אמרינן שמתחילין הקדושין מיד שאני הכא שיש לקיים ולפרש מה שאמר מעכשיו גבי שלמים לא שיחלו ויתחילו שלמים מיד לבטל קדושת עולה תוך שלשים יום אלא לענין שתפקע קדושת עולה לאחר שלשים יום וה\"ג ברישא כל שלשים יום עולה (שלשים יום) ומעכשיו ולאחר שלשים יום שלמים כל ל' יום עולה ולאחר ל' יום שלמים וסיפא ה\"ק לאחר ל' יום עולה אם לא אמר מעכשיו שלמים לאחר שלשים יום עולה מידי דהוה האומר לאשה הרי את מקודשת לי לאחר שלשים יום ואע\"ג דנתאכלו המעות מקודשת פי' וגבי הקדש אמירתו חשובה כנתינת מעות גבי אשה אע\"ג שנתאכלו לאחר שלשים יום (כ\"א מתחילת ל' יום) אפ\"ה חייל הדבור מתחילת שלשים יום כמו גבי קידושין דחיילי הקידושין לאחר שלשים יום אע\"פ שנתאכלו המעות כדפי' רש\"י לעיל:"],[8,"לבר פדא דאמר חוזרות וקדושות","אלמא מצי איניש למימר הרי זה הקדש לאחר שאפדנו יהא הקדש ולא הוי כמקדיש דבר שלא בא לעולם וטעמא משום דבידו להקדישו עכשיו בידו נמי לפדותו ולחזור ולהקדישו אם כן תפשוט הא דבעי רבי אושעיא הנותן לאשה שתי פרוטות מהו מי הוי כמקדיש דבר שלא בא לעולם הואיל וכל אותן הימים דאין אשתו אין בידו לקדשה או דלמא השתא הא בשעת נתינת קדושין הוי בידו לקדשה אי נמי השתא היה בידו לקדשה וכשהיא אשתו בידו לגרשה ולקדשה מדעתה השתא נמי מצי לקדש לה מדעתה לאחר שמגרשה ותפשוט ליה מהאי דמועיל שפיר וא\"ת כמו דפריך לבר פדא אמאי לא פריך לעולא דהא לעולא אמר לעיל דחוזרות וקדושות אם כן הוה ליה למיפרך לעולא ותפשוט וי\"ל דאין ה\"נ אלא שפיר פריך לבר פדא דאמר בהדיא עוד י\"ל דלעולא לית ליה האי סברא דחוזרות וקדושות ועד שיקצצו דקאמר הנודר היינו דווקא לענין דכיון שנקצצו שוב אינו פודן וא\"ת ועולא מי פליג אסתמא דהש\"ס דסבירא ליה חוזרות וקדושות מדקאמר לעולם אלמא משמע חוזרות וי\"ל דלאו היינו סתמא דהש\"ס אלא בר פדא אמר כן והוא ממלתיה וכן אשכחנא באלו מציאות (ב\"מ כא -) גבי וכמה אמר ר' יצחק וכו':"]]],[["תפשוט דבעי רב הושעיא הנותן שתי פרוטות לאשה ואמר לה באחת התקדשי לי היום ובאחת התקדשי לי לאחר שאגרשיך הכי נמי דהוו קידושי","איתער בהו רבי ירמיה אמר להו מאי קא מדמיתון פדאן הוא לפדאום אחרים הכי אמר רבי יוחנן פדאן הוא חוזרות וקדושות פדאום אחרים אין חוזרות וקדושות ואשה כפדאוה אחרים דמיא","איתמר נמי אמר רבי אמי אמר רבי יוחנן לא שנו אלא שפדאן הוא אבל פדאום אחרים אין חוזרות וקדושות","\u0001מתני׳\u0002 הנודר מיורדי הים מותר ביושבי היבשה מיושבי היבשה אסור מיורדי הים שיורדי הים בכלל יושבי היבשה לא כאלו שהולכין מעכו ליפו אלא במי שדרכו לפרש","\u0001גמ׳\u0002 רב פפא ורב אחא בריה דרב איקא חד מתני ארישא וחד מתני אסיפא מאן דתני ארישא מתני הכי הנודר מיורדי הים מותר ביושבי יבשה הא ביורדי הים אסור ולא כאלו"],[[0,"תפשוט דבעי רב הושעיא וכו' ה\"נ דהוו קידושי","דכי היכי דהתם אמר לה לאחר שאגרשיך שיצתה מרשותו שתתקדש הייני דומיא לאחר שנקצצו שיוצאין מרשות הקדש דמצריך להו פדייה:"],[1,"פדאן הוא","המקדיש קודם שנקצצו חוזרות וקדושות לאחר שנקצצו דהואיל והוא הקדישן אע\"ג דחזר ופדאן חוזרות וקדושות לאחר שנקצצו:"],[1,"פדאום אחרים","קודם שנקצצו אין חוזרות וקדושות לאחר שנקצצו ואשה שקנתה עצמה בגט מדעת עצמה אין חלין עליה קדושין דכפדאוה אחרים דמיא דאין חוזרות וקדושו' לגבי אשה נמי אינה מקודשת:"],[3,"מתני' הנודר","שלא יהנה מיורדי הים מותר ליהנות מיושבי היבשה והנודר מליהנות מיושבי היבשה אסור ליהנות מיורדי הים שהן נמי מיושבי היבשה הן שסופן לצאת ומה שאמר יורדי הים בכלל יושבי היבשה לא כאלו יורדי הים ההולכים מעכו ליפו שאין ביניהם אלא מהלך יום אחד ובאין מהרה ליבשה דהוו בכלל יושבי היבשה:"],[4,"גמ' חד מתני ארישא","לא כאלו וכו' ולא כאלו יורדי הים אסור:"]],[[1,"פדאן אחרים אין חוזרות וקדושו'","שהרי פדאן לעצמו והרי שם דאין אדם מקדיש דבר שאינו שלו אשה נמי כי אחרים שקונה עצמה בגט דאין בידו לקדשה עוד בעל כרחה אלא מדעתה והלכך אימא תיבעי מי אמרינן כיון דאי אפשר לו לקדש בע\"כ לפדיון אחרים דמיא ולא מצי מקדיש לה או דלמא השתא מיהא מצי מקדיש לה אדעתה וכיון דכהאי גוונא מצי לקדש לה לאחר שיגרשנה השתא נמי יקדשנה לפדאן הוא דמיא הלכך תיבעי:"],[3,"הנודר מיורדי הים מותר ביושבי היבשה","שאין עומדין על שפת הים דאין רגילין לעבור בים ומיהו אדם העובר פעם אחת לזמן מרובה ואינו רגיל לעבור שם לא מיקרי יורדי הים והנודר מיורדי הים מותר בו ואפי' למ\"ד בגמ' דאותם שהולכים מעכו ליפו מיקרו יורדי הים התם נהי דאין שוהין בה מ\"מ רגילין לעבור תדיר לעבור בים נינהו אבל זה העובר פעם אחת לעשרה שנים לא מיקרי - יורדי הים כלל דבנדרים הלך אחר לשון בני אדם:"],[3,"לא כאלו ההולכים מעכו ליפו","בגמרא מפרש אמאי קאי:"],[3,"אלא במי שדרכו לפרש","להיות ימים רבים ביחד:"]]],[["ההולכים מעכו ליפו דהלין יושבי יבשה נינהו אלא ממי שדרכן לפרש","ומאן דמתני אסיפא מתני הכי הנודר מיושבי יבשה אסור ביורדי הים ולא באלו ההולכים מעכו ליפו בלבד אלא אפילו במי שדרכו לפרש הואיל וסופו ליבשה סליק","\u0001מתני׳\u0002 הנודר מרואי החמה אסור אף בסומין שלא נתכוון זה אלא למי שהחמה רואה אותן","\u0001גמ׳\u0002 מאי טעמא מדלא קאמר מן הרואין לאפוקי דגים ועוברים","\u0001מתני׳\u0002 הנודר משחורי הראש אסור בקרחין ובעלי שיבות ומותר בנשים ובקטנים שאין נקראין שחורי הראש אלא אנשים","\u0001גמ׳\u0002 מאי טעמא מדלא קאמר מבעלי שיער","ומותר בנשים ובקטנים שאין נקראין שחורי הראש אלא אנשים מאי טעמא אנשים זימנין דמיכסו רישייהו וזימנין דמגלו רישייהו אבל נשים לעולם מיכסו וקטנים לעולם מיגלו","\u0001מתני׳\u0002 הנודר מן הילודים מותר בנולדים מן הנולדים אסור מן הילודים רבי מאיר מתיר אף בילודים וחכמים אומרים לא נתכוון זה אלא במי שדרכו להיוולד","\u0001גמ׳\u0002 לרבי מאיר ולא מיבעיא נולדים אלא ממאן אסור","חסורי מיחסרא והכי קתני הנודר מן הילודים מותר בנולדים מן הנולדים אסור בילודים רבי מאיר אומר אף הנודר מן הנולדים מותר בילודים כי היכי דנודר מן הילודים מותר בנולדים","אמר ליה רב פפא לאביי למימרא דנולדים דמתיילדן משמע אלא מעתה שני בניך הנולדים לך בארץ מצרים הכי נמי דאיתיילדן הוא","ואלא מאי דיילידו משמע אלא מעתה דכתיב הנה בן נולד לבית דוד יאשיהו שמו הכי נמי דהוה והא עדיין מנשה לא בא אלא משמע הכי ומשמע הכי ובנדרים הלך אחר לשון בני אדם","וחכמים אומרים לא נתכוין זה אלא ממי שדרכו להיוולד לאפוקי מאי לאפוקי דגים ועופות"],[[1,"ההולכים מעכו ליפו","אסור בלבד:"],[1,"אלא אפי' ממי שדרכן לפרש","אסור הואיל וסופן לעלות ליבשה הוו בכלל יושבי היבשה:"],[2,"מתני' אסור אף בסומין","דלא נתכוין זה אלא במי שהחמה זורחת עליו:"],[3,"גמ' מדלא אמר מן הרואין","דאילו אמר הכי היה מותר בסומין ומדאמר מרואי חמה משמע ממי שחמה זורחת עליו לאפוקי דגים שבים ועוברין שבמעי אמן שאין חמה רואה אותן שמותר בהן:"],[4,"מתני' הנודר משחורי הראש אסור בקרחים ובעלי שיבות","דשחורי הראש משמע שנודר מאותן שהיו שחורי הראש:"],[4,"ומותר בנשים","מפרש בגמרא:"],[5,"גמ' מאי טעמא","אסור בקרחים:"],[5,"מדלא אמר מבעלי שיער","דאילו אמר מבעלי שיער היה מותר בקרחין:"],[6,"זימנין מיכסו רישייהו וזימנין מיגלו","והוו שחורי ראש:"],[6,"אבל נשים לעולם מיכסו","שאינם שחורי הראש ועטופות כל שעה בלבנים:"],[6,"וקטנים לעולם מיגלו רישייהו","כלומר איהו כי נדר אדעתא דגדולים נדר והני כיון דלאו גדולים נינהו ולא נהיגי מנהג גדולים להכי ליתנהו בכלל גדולים ומותר בהן:"],[7,"מתני' הנודר מן הילודים","משמע שכבר באו לעולם כמה דכתיב הילודים במדבר (יהושע ה):"],[7,"מותר בנולדין","באותן העתידים להוולד:"],[7,"וחכמים אומרים","אסור בשניהן דלא נתכוין זה אלא מכל מי שדרכו להוולד חכמים דסיפא היינו ת\"ק:"],[8,"גמ' לרבי מאיר","דמתיר אף בילודים:"],[8,"ולא מיבעיא בנולדים","נמי דמתיר:"],[8,"אלא ממאן אסור","כלומר א\"כ ממה נדר:"],[9,"חסורי מיחסרא והכי קתני מן הנולדים אסור בילודים","דכיון שנודר באותן שעתידים להוולד כ\"ש שאסר עצמו באותן שכבר נולדו רבי מאיר אומר אף הנודר מן הנולדים וכו' כי היכי וכו':"],[11,"והא עדיין","אפי' מנשה זקינו של יאשיהו לא בא לעולם:"],[11,"ובנדרים הלך אחר לשון בני אדם","דדרכן של בכי אדם לקרות נולדין לאותן שעדיין לא נולדו ואם נדר מן הנולדין אסור בהן:"],[12,"וחכ\"א לא נתכוין זה וכו'","דבין בנולדין ובין בילודין אסור:"],[12,"לאפוקי עופות ודגים","שאין נולדים ממעי אמן אלא מטילין ביצים ומתחממים ויוצאין:"]],[[3,"מדלא קאמר הנודר מן הרואים","כלומר מדלא קאמר האיש הנודר שהוא נודר מן הרואים את החמה שאז ודאי הוי משמע למעוטי סומין וא\"ת הא דלא קאמר מן הרואים משום דאז הוי דגים בכלל (עוברים) והוא רצה שלא יהיה בכלל יש לומר דהשתא נמי כשאמר מרואי החמה הוו דגים בכלל כל כמה שלא נפרש שהחמה רואה אותן קאמר שהרי דגים רואין יפה החמה אבל חמה רואה אותן לא מיקרו הואיל ומכוסין במים:"],[3,"לאפוקי דגים ועוברין","דאין חמה רואה אותן דגים כדפי' ועוברים מכוסין במעי אמן אבל שאר בעלי חיים אסורין ומיהו בתבואה ופירות וכל דבר שאין בו רוח חיים שרי אע\"ג דחמה רואה אותן דכיון שהזכיר רואי החמה משמע דוקא בעלי חיים שעשויים לראות החמה:"],[4,"אסור בקרחין ובעלו שיבות","אע\"פ שקרח אין לו שערות ובעלי שיבות מליאים שיער לבן ואין הראש שחור:"],[5,"מאי טעמא מדלא קתני מבעלי שער","כלומר מדלא קאמר הנודר:"],[6,"אנשים זימנין מיכסו רישייהו וזימנין מגלו","וניכר שחרותם לפעמים כשראשם גלוי ואע\"ג דאיכא קרחין ובעלי שיבות מ\"מ כמה פעמים מגלין ראשן וגם מותרין לגלות באקראי בעלמא אפי' בפני כל העולם מה שאין כן בנשים:"],[6,"קטנים לעולם מיגלו","ואין חידוש כשהוברר שחרות שלעולם הוין כך ואין נקראין שחורי הראש אלא אותם שלפעמים ניכר שחרותם ועוד יש לפרש קטנים לעולם מיגלו בין זכרים בין נקבות ואפילו נקבות קטנות שאינן נשואות רגילות יפה בגלוי הראש ואין רגילין לקרות שחורי הראש אלא אנשים דכוותייהו בנשים אינם שחורי הראש:"]]],[["\u0001מתני׳\u0002 הנודר משובתי שַבָּת אסור בישראל ואסור בכותים מאוכלי שום אסור בישראל ואסור בכותים מעולי ירושלים אסור בישראל ומותר בכותים","\u0001גמ׳\u0002 מאי שובתי שבת אילימא ממקיימי שבת מאי איריא בכותים אפילו נוכרים נמי אלא ממצווים על השבת","אי הכי אימא סיפא מעולי ירושלים אסור בישראל ומותר בכותים אמאי והא מצווים נינהו","אמר אביי מצווה ועושה קתני בתרתי בבי קמייתא ישראל וכותים מצווין ועושין נוכרים ההוא דעבדי עושין ואינם מצווין בעולי ירושלים ישראל מצווין ועושין כותים מצווין ואינם עושין","\u0001מתני׳\u0002 קונם שאיני נהנה לבני נוח מותר בישראל ואסור בנוכרים","\u0001גמ׳\u0002 וישראל מי נפיק מכלל בני נח כיוון דאיקדש אברהם איתקרו על שמיה","\u0001מתני׳\u0002 שאיני נהנה לזרע אברהם אסור בישראל ומותר בנוכרים","\u0001גמ׳\u0002 והאיכא ישמעאל כי ביצחק יקרא לך זרע (בראשית כא, יב) כתיב והאיכא עשו ביצחק ולא כל יצחק","\u0001מתני׳\u0002 שאיני נהנה מישראל לוקח ביותר ומוכר בפחות שישראל נהנין לי לוקח בפחות ומוכר ביותר ואין שומעין לו שאיני נהנה להן והן לי יהנה לנוכרים","\u0001גמ׳\u0002 אמר שמואל הלוקח כלי מן האומן לבקרו ונאנס בידו חייב אלמא קסבר הנאת לוקח היא","תנן שאיני נהנה מישראל מוכר בפחות אבל שווה בשווה לא ואי הנאת לוקח היא אפילו שוה בשוה מתניתין בזבינא דרמי על אפיה","אם כן אימא רישא לוקח ביותר ועוד אימא סיפא שישראל נהנין לי [לוקח בפחות] ומוכר ביותר ואי בזבינא דרמי על אפיה אפילו שוה בשוה","סיפא בזבינא חריפא אי הכי לוקח בפחות אפילו שווה בשווה אלא"],[[0,"מתני' משובתי שבת","מאותן שמשמרין שבת:"],[0,"אסור בכותים","שהן כמו כן משמרין שבת:"],[0,"מאוכלי השום","בלילי שבת:"],[0,"אסור בישראל","דישראל רגילין לאכול שום (ב\"ק פב.) מפני עונה שמקיימין מערב שבת לערב שבת ומרבה להם הזרע כדאמר אשר פריו יתן בעתו אלו תלמידי חכמים המשמשין מטותיהן מערב שבת לערב שבת (כתובות סב:):"],[0,"ואסור בכותים","שהם נמי אוכלים שום בלילי שבת:"],[0,"ומותר בכותים","שהן אינן עולין לירושלים אלא להר גריזים:"],[1,"גמ' אפי' עובדי כוכבים נמי","אי משמרין שבת יהא אסור בהן:"],[1,"אלא","מאי שובתי שבת אותן דמצווין על השבת דהיינו ישראל וכותים הן מצווין על השבת מפני שהן גרים אבל עובדי כוכבים אע\"פ שמשמרין שבת אינן מצווין:"],[2,"ומותר בכותים ואמאי הא מצווין נינהו","נמי לעלות לירושלים:"],[3,"אלא אמר אביי","מאי משובתי שבת מצווה ועושה קתני:"],[3,"בתרתי בבי קמייתא","בשבת ושום:"],[3,"ישראל וכותים מצווין ועושין","ואסור בהן:"],[3,"ועובדי כוכבים עבדי אבל אינן מצווין","לפיכך מותר:"],[3,"בהך דעולי ירושלים ישראל מצווין ועושין כותים מצווין ואינן עושין","להכי מותר בהן:"],[4,"מתני' שאיני נהנה לבני נח","שלא יהנה מכל בני נח שכל העולם יצאו מבני נח:"],[5,"גמ' כיון דאיקדש אברהם","בחלקו של הקב\"ה:"],[5,"איתקרו","ישראל על שמיה דאברהם ולא על שם בני נח:"],[7,"הא איכא ישמעאל","דזרע אברהם הוא והוא מן העובדי כוכבים:"],[7,"יקרא לך זרע","ובאותו זרע קנדר:"],[7,"ולא כל יצחק","ועשו אינו נקרא זרע יצחק להכי מותר בעובדי כוכבים:"],[8,"מתני' שאיני נהנה מישראל לוקח מהן ביתר ומוכר להם בפחות","כלומר בזול ונמצא שאינו נהנה מהן:"],[8,"שישראל","לא יהו נהנין ממנו מוכר להן ביוקר דהשתא אין נהנין ממנו:"],[8,"ואין שומעין לו","שלא ימצא אדם שיהא שומע לו בדבר זה שבשביל נדרו מוכר לו בזול ויקח ממנו ביוקר:"],[9,"גמ' הלוקח כלי מבית האומן לבקרו","אם יפה יתן לו דמיו ואם לאו שיחזיר לו כליו כמו כלי זכוכית:"],[9,"ונאנס מידו","שנשבר חייב לוקח לשלם לו:"],[9,"אלמא הנאת לוקח היא","דהנאה ללוקח במקחו יותר משל מוכר הלכך חייב דגמר ומקני נפשיה בההיא הנאה שמניחו לבקרו. והוי כנושא שכר ונתחייב באונסין:"],[10,"אבל שוה בשוה","אינו יכול [למכור] ואי ס\"ד הנאת לוקח היא הקונה חפץ ולא הנאת המוכר אפי' שוה בשוה נמי יהא יכול למכור דלא הוי הנאת מוכר אלא הנאת לוקח: תריץ דמתניתין דמשמע שוה בשוה לא:"],[10,"בזבינא דרמי על אפיה","עיסקא בישא דלא קפיץ עליה זבינא ודומה לו כמי שמונחת על פניו ועכשיו כשמוכרה שוה בשוה הנאת מוכר היא ולא הנאת לוקח הלכך מוכר בפחות אבל שוה בשוה לא:"],[11,"אימא רישא","דההיא לוקח ביותר ודייקינן מינה הכי נמי אבל שוה בשוה לא אינו לוקח אלמא הנאת לוקח הוי דאי הנאת מוכר אפילו שוה בשוה נמי הנאת מוכר היא ולא הנאת לוקח ובהכי יכול ליקח מהן דאכתי לית ליה הנאה בהנהו זביני:"],[11,"ועוד אימא סיפא קונם שישראל נהנין לי","כלומר שלא יהו ישראל נהנין לי ממני לוקח . בפחות ומוכר ביתר אבל שוה בשוה לא:"],[11,"ואי בזבינא דרמי על אפיה אפילו שוה בשוה","נמי יהא יכול למכור דהא הנאת המוכר ולא הנאת לוקח היא:"],[12,"סיפא בזבינא חריפא","בסחורה דקפיץ עלה זבינא דשוה בשוה הוי הנאת לוקח ולא הנאת מוכר הלכך מוכר ביוקר:"],[12,"אפילו שוה בשוה נמי","יהא לוקח המדיר דהא הנאת לוקח היא ולא הנאת מוכר ולא יהא הך נהנה ממנו:"]],[[0,"הנודר משובתי שבת אסור בישראל ואסור בכותים","שגם הכותים מקיימי מצות שבת:"],[0,"מאוכלי השום אסור בישראל ואסור בכותים","פי' אותן שמצווין לאכול שום מתקנת עזרא בע\"ש וגם הכותים שומרים תקנה דאכילת שום בע\"ש וכה\"ג דמפרשין הכא שר\"ל מאוכלי השום מע\"ש תנן לקמן פרק קונם יין וכו' (נדרים דף סג:) קונם שום שאני טועם עד שתהא שבת אינו אסור אלא עד לילי שבת שלא נתכוין זה אלא עד שעה שדרך שבני אדם אוכלין שום:"],[0,"מעולי ירושלים מותר בכותים","שלא היו עולין לירושלים אלא בהר גריזים היו עובדין:"],[1,"אילימא ממקיימי שבת אפילו עובדי כוכבים נמי","פי' אם יש עובדי כוכבים אסור בהם וא\"ת מאי קאמר הא סתם עובדי כוכבים אין דרכם לשבות בשבת אבל סתם כותים שובתין בשבת וי\"ל דהכי קאמר אילימא ממקיימי שבת ושובתים בשבת לא בעי למימר ממצווין על השבת דא\"כ לא הוה מיתסר בכותים משום דסבירא לן כותים גירי אריות הן ואינם מצווין אלא בעי למימר מקיימין אע\"פ שאינן - מצווין ולכך פריך מאי איריא כותים דכיון שסבר - שכותים גירי אריות הן דא\"כ העובדי כוכבים בכלל הכותים ויש מן העובדי כוכבים ששובתים בשבת ולהכי פריך אפילו עובדי כוכבים נמי:"]]],[["מתניתין בזבינא מיצעא ודשמואל בזבינא חריפא","תניא כוותיה דשמואל הלוקח כלים מן התגר לשגרן לבית חמיו ואמר לו אם מקבלין אותן ממני אני נותן לך דמיהם ואם לאו אני נותן לך לפי טובת הנאה שבהן נאנסו בהליכה חייב","בחזרה פטור מפני שהוא כנושא שכר","ההוא ספסירא דשקל חמרא לזבוני ולא איזבן בהדי דהדר איתניס חמרא חייביה רב נחמן לשלומי איתיביה רבא לרב נחמן נאנסו בהליכה חייב בחזרה פטור","אמר ליה חזרה דספסירא הולכה היא דאילו משכח לזבוני אפילו אבבא דביתיה מי לא מזבין ליה","\u0001מתני׳\u0002 קונם שאני נהנה לערלים מותר בערלי ישראל ואסור במולי נוכרים","שאני נהנה למולים אסור בערלי ישראל ומותר במולי נוכרים שאין הערלה קרויה אלא לשם נוכרים שנאמר כי כל הגוים ערלים וכל בית ישראל ערלי לב (ירמיהו ט, כה) ואומר והיה הפלשתי הערל הזה (שמואל א יז, לו) ואומר פן תשמחנה בנות פלשתים פן תעלוזנה בנות הערלים (שמואל ב א, כ)","רבי אלעזר בן עזריה אומר מאוסה היא הערלה שנתגנו בה רשעים שנאמר כי כל הגוים ערלים (ירמיהו ט, כה) רבי ישמעאל אומר גדולה מילה שנכרתו עליה שלוש עשרה בריתות","רבי יוסי אומר גדולה מילה שדוחה את השבת חמורה","רבי יהושע בן קרחה אומר גדולה מילה שלא נתלה לו למשה הצדיק עליה מלוא שעה","רבי נחמיה אומר גדולה מילה שדוחה את הנגעים רבי אומר גדולה מילה שכל המצוות שעשה אברהם אבינו לא נקרא שלם עד שמל שנאמר התהלך לפני והיה תמים (בראשית יז, א)","דבר אחר גדולה מילה שאלמלא היא לא ברא הקב\"ה את עולמו שנאמר כה אמר ה' אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי (ירמיהו לג, כה)","\u0001גמ׳\u0002 תניא רבי יהושע בן קרחה אומר גדולה מילה שכל זכויות שעשה משה רבינו לא עמדו לו כשנתרשל מן המילה שנאמר ויפגשהו ה' ויבקש המיתו (שמות ד, כד)","אמר רבי חס ושלום שמשה רבינו נתרשל מן המילה אלא כך אמר אמול ואצא סכנה היא שנאמר ויהי ביום השלישי בהיותם כואבים וגו' (בראשית לד, כה) אמול ואשהא שלשה ימים הקב\"ה אמר לי לך שוב מצרים (שמות ד, יט) אלא מפני מה נענש משה"],[[0,"מתני' בזבינא מיצעא","דלא הוי זבינא חריפא ולא זבינא דרמיא על אפיה לפיכך שוה בשוה לא דזימנין הוי הנאת מוכר וזימנין הוי הנאת לוקח:"],[0,"ודשמואל","דאמר חייב:"],[0,"בזבינא חריפא","דודאי הוי הנאת לוקח לפיכך כי נאנס בידו חייב אפי' שוה בשוה דהנאת לוקח היא:"],[1,"נאנסו בהליכה חייב","(מפני שהוא כנושא שכר) בההיא הנאה דאית ליה שמניחו להוליכו לבית חמיו גמר ומקני נפשיה:"],[2,"בחזרה פטור","דלית ליה הנאה שלא נתקבלו:"],[3,"ספסירא","מי שלוקח בהמה ע\"מ למוכרה לאלתר:"],[3,"בחזרה פטור","וה\"נ כי אתניס בחזרה אתניס לפטור:"],[4,"מי לא מזבין ליה","ובחזירה נמי כנושא שכר. הוי:"],[5,"מתני' ואסור במולי עובדי כוכבים","דבכלל ערלים הן:"],[6,"ערלי ישראל","בכלל מולים הן כגון שמתו אחיו מחמת המילה:"],[8,"שחיא דוחה שבת חמורה","דכתיב וביום השמיני ימול (ויקרא ט׳:א׳) ואפילו בשבת:"],[9,"שכל זכיותיו של משה לא עמדו לו","בשעה שנתרשל מן המילה שנאמר ויהי בדרך במלון ויפגשהו ה' ויבקש המיתו (שמות ד׳:כ״ד):"],[10,"שדוחה את הנגעים","דכתיב וביום השמיני ימול ואע\"פ שיש שם בהרת יקוץ:"],[10,"דכתיב התהלך לפני והיה תמים","וכתיב בתריה ואתנה בריתי ביני ובינך:"]],[[7,"שנכרתו","עליה י\"ג בריתות צא וחשוב [מואתנה] (את) בריתי ביני וביניך עד בריתי אקים את יצחק (בראשית י״ז:כ״א) יש י\"ג בריתות:"],[12,"הנה דם הברית אשר כרת וכו'","אע\"ג דפשטיה דקרא בהרצאת דמים בדם שנתן משה באצבעו משתעי מ\"מ מוקי ליה נמי בדם מילה כשנכנסים לברית כדאמרינן (כריתות דף ט.) במה נכנסו אבותינו לברית במילה וטבילה והרצאת דמים מצינו דם מילה קרי דם ברית דכתיב (שמות כ״ד:ח׳) הנה דם הברית אשר וגו':"]]],[["מפני שנתעסק במלון תחילה שנאמר ויהי בדרך במלון (שמות ד, כד)","רבן שמעון בן גמליאל אומר לא למשה רבינו ביקש שטן להרוג אלא לאותו תינוק שנאמר כי חתן דמים אתה לי (שמות ד כה) צא וראה מי קרוי חתן הוי אומר זה התינוק","דרש רבי יהודה בר ביזנא בשעה שנתרשל משה רבינו מן המילה באו אף וחימה ובלעוהו ולא שיירו ממנו אלא רגליו מיד ותקח צפורה צור ותכרת את ערלת בנה (שמות ד, כה) מיד וירף ממנו (שמות ד, כו)","באותה שעה ביקש משה רבינו להורגן שנאמר הרף מאף ועזוב חמה (תהלים לז, ח) ויש אומרים לחימה הֲרָגוֹ שנאמר חמה אין לי (ישעיהו כז, ד) והכתיב כי יגרתי מפני האף והחמה (דברים ט, יט) תרי חימה הוו ואיבעית אימא גונדא דחימה","תניא רבי אומר גדולה מילה שאין לך מי שנתעסק במצוות כאברהם אבינו ולא נקרא תמים אלא על שם מילה שנאמר התהלך לפני והיה תמים (בראשית יז, א) וכתיב ואתנה בריתי ביני ובינך (בראשית יז, ב)","דבר אחר גדולה מילה ששקולה כנגד כל המצוות שבתורה שנאמר כי על פי הדברים האלה וגו' (שמות לד, כז) דבר אחר גדולה מילה שאילמלא מילה לא נתקיימו שמים וארץ שנאמר אם לא בריתי יומם ולילה וגו' (ירמיהו לג, כה)","ופליגא דרבי אליעזר דאמר רבי אליעזר גדולה תורה שאילמלא תורה לא נתקיימו שמים וארץ שנאמר אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי וגו'","אמר רב יהודה אמר רב בשעה שאמר לו הקב\"ה לאברהם אבינו התהלך לפני והיה תמים (בראשית יז, א) אחזתו רעדה אמר שמא יש בי דבר מגונה כיוון שאמר לו ואתנה בריתי ביני ובינך (בראשית יז, ב) נתקררה דעתו","ויוצא אותו החוצה (בראשית טו, ה) אמר לפניו רבונו של עולם הסתכלתי במזל שלי ואין לי אלא בן אחד אמר לו צא מאיצטגנינות שלך אין מזל לישראל","אמר רבי יצחק כל המתמים עצמו הקב\"ה מתמים עמו שנאמר עם חסיד תתחסד עם גבר תמים תתמם (תהלים יח, כו)","אמר רבי הושעיא כל המתמים עצמו שעה עומדת לו שנאמר התהלך לפני והיה תמים (בראשית יז, א) וכתיב והיית לאב המון גוים (בראשית יז, ד)","אמר רבי כל המנחש לו נחש שנאמר כי לא נחש ביעקב (במדבר כג, כג) והא בלמ\"ד אל\"ף כתיב אלא משום מידה כנגד מידה","תני אהבה בריה דרבי זירא כל אדם שאינו מנחש מכניסין אותו במחיצה שאפילו מלאכי השרת אין יכולין ליכנס בתוכה שנאמר כי לא נחש ביעקב ולא קסם בישראל וגו' (במדבר כג, כג)","אמר רבי אבהו אמר רבי אלעזר מפני מה נענש אברהם אבינו ונשתעבדו בניו למצרים מאתיים ועשר שנים מפני שעשה אנגרייא בתלמידי חכמים שנאמר וירק את חניכיו ילידי ביתו (בראשית יד, יד)","ושמואל אמר מפני שהפריז על מדותיו של הקב\"ה שנאמר במה אדע כי אירשנה (בראשית טו, ח) ורבי יוחנן אמר שהפריש בני אדם מלהכנס תחת כנפי השכינה שנאמר תן לי הנפש והרכוש קח לך (בראשית יד, כא)","וירק את חניכיו ילידי ביתו (בראשית יד, יד) רב אמר שהוריקן בתורה ושמואל אמר שהוריקן בזהב","שמנה עשר ושלש מאות (בראשית יד, יד) אמר רבי אמי בר אבא אליעזר כנגד כולם איכא דאמרי אליעזר הוא דחושבניה הכי הוי","ואמר רבי אמי בר אבא בן שלוש שנים הכיר אברהם את בוראו שנאמר עקב אשר שמע אברהם בקולי (בראשית כו, ה) חושבניה מאה ושבעין ותרין","ואמר רמי בר אבא"],[[0,"מפני שנתעסק במלון תחלה","ואח\"כ במילה והיה לו להתעסק במילה תחלה ואותו מלון סמוך למצרים דלא היה סכנה ואותו התינוק לא היה באותה שעה אלא בן שמונה ימים:"],[3,"להורגן","לאותן שני מלאכים:"],[3,"גונדא דחימה","חיל שלו אבל איהו גופיה נהרג:"],[5,"שהיא שקולה כנגד כל המצות שבתורה","דכתיב (שמות כ״ד:ח׳) הנה דם הברית אשר כרת ה' עמכם על כל הדברים האלה וכתיב במילה (בראשית י״ז:ב׳) ואתנה בריתי וגו' כרתי ברית וגו' וכתיב להלן (שם) ואתנה בריתי מה להלן ברית אף כאן ברית:"],[5,"אם לא בריתי יומם ולילה","מה להלן תורה אף כאן תורה והיינו פליגא דהכא מוקי לה להאי קרא במילה והתם מוקי לה בתורה:"],[7,"שמא נמצא בי דבר מנוגה","(עד) עכשיו שלא אמר לו והיה תמים עד עכשיו:"],[9,"כל המתמים","מתמם עמו:"],[11,"כל המנחש","כלומר שרודף אחרי המנחשים:"],[11,"לו נחש","אחריו רודפין ניחושין דכל דקפיד קפדי בהדיה:"],[11,"בלמ\"ד אל\"ף","דמשמע דאין רודפין אחריו:"],[11,"מדה כנגד מדה","דבמדה כאדם מודד בה מודדין לו ולא נפיק מקרא:"],[12,"שנאמר כי לא נחש","כל זמן שאינו מנחש מה כתיב בתריה כעת יאמר ליעקב כלומר עדיין יהא אותו עת דמלאכי השרת יהיו שואלין אותו שאינו מנחש מה פעל אל לפי שהוא נכנס למקום שאין מלאכי השרת יכולין ליכנס:"],[14,"שהפריז על מדותיו","שהגדיל לישאל על מדותיו של הקב\"ה שאמר במה אדע:"],[14,"תן לי הנפש והרכוש קח לך","ולא היה לו לעשות כן שהיה לו לגיירם:"],[15,"שהוריקן בתורה","שלימדם תורה כאדם שמריק מכלי זה לתוך כלי זה כך הוא לימדן תורה:"],[15,"שהוריקן","לשון ציהוב שנא' (תהלים סח) ואברותיה בירקרק חרוץ שנתן להם זהב הרבה:"],[16,"אליעזר","היה שקול כנגד כולן:"],[16,"אליעזר הוא חושבניה","דאליעזר בגימטריא שמונה עשר ושלש מאות שלא היה עמו אלא אליעזר לחוד:"],[17,"מאה ושבעים ותרתין","דהכי משמע עקב כמנין עק\"ב שנים שמע אברהם בקולי וכל שנותיו היו קע\"ה אלמא בן שלש שנים הכיר את בוראו:"]],[]],[["השטן בחושבניה תלת מאה ושיתין וארבעה ואמר רמי בר אבא כתיב אברם, וכתיב אברהם בתחילה המליכו הקב\"ה על מאתיים וארבעים ושלושה איברים ולבסוף המליכו על מאתיים וארבעים ושמונה איברים","אלו הן שתי עינים ושתי אזניים וראש הגוייה","ואמר רמי בר אבא מאי דכתיב עיר קטנה ואנשים וגו' (קהלת ט, יד) עיר קטנה זה הגוף ואנשים בה מעט אלו איברים ובא אליה מלך גדול וסבב אותה זה יצר הרע ובנה עליה מצודים וחרמים אלו עוונות","ומצא בה איש מסכן וחכם זה יצר טוב ומלט הוא את העיר בחכמתו זו תשובה ומעשים טובים ואדם לא זכר את האיש המסכן ההוא דבשעת יצר הרע לית דמדכר ליה ליצר טוב","החכמה תעוז לחכם מעשרה שליטים (קהלת ז, יט) החכמה תעוז לחכם זו תשובה ומעשים טובים מעשרה שליטים שתי עיניים ושתי אזניים ושתי ידיים ושתי רגליים וראש הגוייה ופה","אמר רבי זכריה משום רבי ישמעאל ביקש הקב\"ה להוציא כהונה משֵם שנאמר והוא כהן לאל עליון (בראשית יד, יח) כיוון שהקדים ברכת אברהם לברכת המקום הוציאה מאברהם","שנאמר ויברכהו ויאמר ברוך אברם לאל עליון קונה שמים וארץ וברוך אל עליון (בראשית יד יט-כ) אמר לו אברהם וכי מקדימין ברכת עבד לברכת קונו מיד נתנה לאברהם שנאמר נאם ה' לאדני שב לימיני עד אשית אויביך הדום לרגליך (תהלים קי, א) ובתריה כתיב נשבע ה' ולא ינחם אתה כהן לעולם על דברתי מלכי צדק (תהלים קי, ד) על דיבורו של מלכי צדק","והיינו דכתיב והוא כהן לאל עליון הוא כהן ואין זרעו כהן","\u0001הדרן עלך ארבעה נדרים\u0002","מתני׳ \u0001אין\u0002 בין המודר הנאה מחבירו למודר הימנו מאכל אלא דריסת הרגל וכלים שאין עושין בהם אוכל נפש","המודר מאכל מחבירו לא ישאילנו נפה וכברה וריחיים ותנור אבל משאיל לו חלוק וטבעת וטלית ונזמים","\u0001גמ׳\u0002 מאן תנא אמר רב אדא בר אהבה רבי אליעזר היא דתניא רבי אליעזר אומר אפילו ויתור אסור במודר הנאה","המודר מאכל מחבירו לא ישאילנו כו'"],[[0,"שס\"ד ימים אית ליה וכו'","וימי השנה שס\"ה ימים:"],[0,"המליכו","השליטו:"],[1,"אלו הן שתי עיניים","דלאחר שמל היה שלם בכל אבריו:"],[1,"ראש הגוייה","הוא אבר:"],[4,"מעשרה שליטים","שהן מועילין לגוף יותר מעשרה שליטים ואלו הן כו':"],[5,"הוציאה","לכהונה:"],[6,"על דיבורו של מלכי צדק","ניטלה ממנו הכהונה:"],[9,"אין בין המודר הנאה מחבירו","שחבירו הדירו שלא יהנה ממנו בשום ענין:"],[9,"למודר ממנו מאכל","שלא הדירו אלא הנאת מאכל:"],[9,"אלא דריסת הרגל","לעבור בחצרו ולקצר דרכו:"],[9,"וכלים","ולהשתמש בכלים של מדיר שאין עושין בהם מאכל דמודר הנאה אסור בדריסת הרגל דהיינו הנאה שמקצר דרכו ולהשתמש בכליו אבל מודר ממנו מאכל מותר בשתיהן לפי שזה לא הדיר ממנו אלא מאכל:"],[11,"גמ' מאן תנא","דמודר הנאה אסור בדריסת הרגל ובכלים וכו' אע\"ג דלא מיחזי הנאה:"],[11,"רבי אליעזר היא דאמר אפילו ויתור כו'","ויתור זהו כגון שלקח מדה של תפוחים בפרוטה ולאחר שמדד לו המדה מוסיף לו שתים או שלשה וזהו דרך של חנוונין להוסיף על המדות משלהן הואיל ובלא תנאי נותן לו לא מיחזי כמקח אלא כמתנה ואליבא דרבי אליעזר אסור המודר באותו הויתור של מדידת פירות הכא נמי אף על גב דדריסת הרגל לא הויא הנאה גמורה אסור:"]],[[1,"שתי עינים וב' אזנים וראש הגוייה","ראש האבר שנימול ושמע וראה ושלט בעיניו ואזניו שהמצות מפקחות את העינים והאזנים כדכתיב (דברים כ״ט:ג׳) ולא נתן ה' לכם לב לדעת ועינים לראות ואזנים לשמוע עד היום הזה אבל הכא לא קחשיב לב דהא כתיב (נחמיה ט׳:ח׳) ומצאת את לבבו נאמן לפניך וכרות עמו הברית ונדר על המילה אלמא קודם המילה היה כבר לבו שלם לשמים:"],[5,"להוציא כהונה משם","תימה דאברהם נמי היה מזרעו של שם וי\"ל דמכל בניו של שם קאמר ולבסוף ניטל משאר בניו וניתנה לאברהם לבדו א\"נ י\"ל לפי שלא היה בכור בכל בניו ולא היה לו לירש הכהונה מן הדין אלא דוקא הבכור:"],[9,"אין בין המודר הנאה וכו' אלא דריסת הרגל","במקום דלא קפדי אינשי כגון בקעה בימות החמה:"],[10,"ולא ישאילנו נפה וכברה","אבל לא נקט מחבת ופיטפוט שלא ישאילנו דהא פשיטא שלא ישאיל דהנאה המביאה לידי מאכל הוא אלא אפי' נפה וכברה שאינו יכול לאכול אחר תיקון זה בכלי זה אלא צריך תיקון אחר אפייה ובישול אפ\"ה אסור לשאול לו נפה:"],[10,"מקום שמשכירים אסור","דחשיב הנאת מאכל ממה שנהנה השוכר וראוי לקנות מן המעות מאכל:"],[11,"מני ר\"א היא","ומיירי בבקעה בימות החמה דלא קפדי כדפרישית וא\"ת ולוקמה הכא בחצר דקפדי וכ\"ע וי\"ל דא\"כ הוה ליה מקום שמשכירין והיה אסור במודר מאכל:"],[11,"אפי' ויתור","שמוותר לו כדרך המוכרין ומתני' דלעיל דמוכר בפחות ולוקח ביותר מסתברא דאתי כר\"א:"]]],[["והא מן מאכל נדר אמר רבי שמעון בן לקיש באומר הנאת מאכלך עלי","אימא שלא ילעוס חיטין ויתן על מכתו אמר רבא באומר הנאה המביאה לידי מאכלך עלי","אמר רב פפא שק להביא פירות וחמור להביא עליו פירות ואפילו צנא בעלמא הנאה המביאה לידי מאכל הוא בעי רב פפא סוס לרכוב עליו וטבעת ליראות בה מהו מיפסק ומיזל בארעיה מאי","תא שמע אבל משאיל לו חלוק וטלית נזמים וטבעות היכי דמי אילימא שלא ליראות בהן צריכא למימר אלא לאו אפילו ליראות בהן וקתני משאילו","לא לעולם שלא ליראות ואיידי דקתני רישא לא ישאילנו תנא סיפא משאילו","\u0001מתני׳\u0002 וכל דבר שאין עושין בו אוכל נפש מקום שמשכירין כיוצא בהן אסור","\u0001גמ׳\u0002 מכלל דרישא אף על פי שאין משכירין מאן תנא אמר רב אדא בר אהבה רבי אליעזר היא","\u0001מתני׳\u0002 המודר הנאה מחבירו שוקל לו את שקלו ופורע את חובו ומחזיר לו את אבידתו מקום שנוטלין עליה שכר תיפול הנאה להקדש","\u0001גמ׳\u0002 אלמא אברוחי ארי בעלמא הוא ושרי","מאן תנא אמר רב הושעיא זו"],[[0,"והא מן מאכל עצמו נדר","ואמאי אסור להשאילו נפה והני לאו מאכל נינהו:"],[0,"הנאת מאכלך עלי","יהא אסור:"],[1,"ואימא","מאי הנאת מאכלך שלא ילעוס חיטין שלו ויתן על גבי מכתו והיינו נמי הנאת מאכלך ואכתי אמאי לא ישאילנו נפה וכברה:"],[1,"המביאה לידי מאכלך עלי","ונפה וכברה מביא מאכלו למאכל ולהכי לא ישאילנו לו:"],[2,"אפי' שק וכו' ואפי' צנא בעלמא","של מדיר אסור למודר ליתן בה פירות דהנאה המביאה לידי מאכל הוא ואסור:"],[2,"סוס לרכוב עליו","לילך לבית המשתה:"],[2,"או טבעת ליראות בה","בבית המשתה כדי שינהגו בו כבוד והיינו הנאה:"],[2,"מיפסק ומיזל בארעיה","שהולך דרך קרקעו לבית המשתה ומקצר דרכו:"],[2,"מהו","מי הוי הנאה המביאה לידי מאכל בכל הני או לא:"],[3,"צריכא למימר","דשרי הא ליכא הנאה כלל:"],[3,"וקתני משאילו","וש\"מ דשרי:"],[4,"לא לעולם","אפי' שלא ליראות בה ובדין הוא דלא היה צריך למיתני משאילו:"],[4,"אלא איידי וכו'","ומהא ליכא למשמע מינה:"],[5,"מתני' מקום שמשכירין","שנוהגין להשאיל כל אלו הדברים על ידי שכירות אסור למדיר להשאילו דכיון שנוהגים להשכיר מיחזי כהנאה המביאה לידי מאכל ואסור:"],[6,"גמ' מכלל דרישא","דקתני לא ישאילנו נפה וכברה הוי אע\"פ שאין משכירין כלומר שאין נוהגין להשאיל בשכירות אע\"ג דלא הוי הנאה גמורה דכיון שאין משכירין מאי קא מהני ליה אם זה לא ישאילנו שכנו אחר משאילו בחנם שהרי מקום שאין משכירין הוא:"],[6,"מאן תנא","דאפילו הכי אסור:"],[6,"ר' אליעזר היא","אבל סיפא דקתני מקום שמשכירין אסור דברי הכל היא דהנאה גמורה היא:"],[7,"מתני' שוקל לו את שקלו","המדיר יכול ליתן בשבילו מחצית השקל שנותנין לתרומת הלשכה ויכול לפרוע חובו ואין מהנה לו כלום מדקתני פורע חובו אלמא לא מהני ליה מנכסיו דהא לא יהיב ליה בידים ממש:"],[8,"גמ' אלמא אברוחי ארי בעלמא הוא","שמבריח חובו מעליו ושרי:"],[9,"מאן תנא","דאברוחי שרי:"]],[[1,"אימא שלא ילעוס חיטין","משום הנאת מאכל לעיסתך ואפי' מחטין של מדיר עצמו:"],[2,"וטבעת להראות בו","כאדם עשיר בבית המשתה וע\"י כך יתנו לו מנה יפה:"],[6,"מאן תנא אמר רבא ר\"א היא","וא\"ת תנן חדא זימנא ברישא ר\"א וי\"ל דמכח הך דהכא מדקדק לעיל דאתי כר\"א דאי לאו האי הוה מוקמינן ליה בחצר ודכ\"ע ולכך מדקדק הכא מסיפא:"]]],[["דברי חנן היא","רבא אמר אפילו תימא דברי הכל גבי מודר הנאה דיהיב על מנת שלא לפרוע","מאי חנן דתנן מי שהלך למדינת הים ועמד אחד ופירנס את אשתו חנן אמר איבד את מעותיו","נחלקו עליו בני כהנים גדולים ואמרו ישבע כמה הוציא ויטול אמר רבי דוסא בן הרכינס כדבריהם אמר רבן יוחנן בן זכאי יפה אמר חנן הניח מעותיו על קרן הצבי","רבא לא אמר כרב הושעיא דקא מוקים לה למתניתין כדברי הכל רב הושעיא לא אמר כרבא גזירה שלא ליפרע משום ליפרע","מחזיר לו את אבידתו פליגי בה רבי אמי ורבי אסי חד אמר לא שנו אלא בשנכסי מחזיר אסורין על בעל אבידה דכי מהדר ליה מידעם דנפשיה קא מהדר ליה אבל נכסי בעל אבידה אסורין על מחזיר לא קא מהדר ליה דקא מהני ליה פרוטה דרב יוסף","וחד אמר אפילו נכסי בעל אבידה אסורין על מחזיר מהדר ליה ומשום פרוטה דרב יוסף לא שכיח"],[[0,"דברי חנן היא","דאמר איבד מעותיו שאין למלוה על בעלה של זו כלום הואיל ולא נתן בידו אלא הבריח ארי מעליו שפירנס את אשתו' שהוא חייב לזונה ה\"נ כי פרע חובו אברוחי ארי הוא שאין לו לפרוע על החוב כלום ולהכי שרי דאי כהנים גדולים דפליגי עליה דחנן היא כיון דאמרי ישבע כמה הוציא ויטול מן הבעל הכא נמי סבירא להו כי פרע חובו יכול הפורע לגבות מן הלוה ולהכי הוי הנאה גמורה אם אין הפורע חוזר וגובה ממנו ואסור:"],[1,"דיהיב ליה ע\"מ שלא לפרוע","מזה דהשתא כי פורעו זה לא הוי הנאה הואיל ואי בעי לא מצי למיגבא מיניה כלום ושוקל לו את שקלו נמי מוקמינן ליה לדברי הכל כה\"ג שאינו מהנה לו כלום כגון שהוא עצמו שקל את שקלו ושגרו לירושלים ונגנב או אבד לאחר שנתרמה הלשכה והאי לא נתחייב באחריותו ולא היה לו לפורעו דהכי קיי\"ל (ב\"מ נז:) בני העיר ששיגרו את שקליהן ונגנבו או שאבדו אם נתרמה התרומה נשבעין השלוחין לגזברים שאבדו ובעלים פטורים דתורמין על האבוד ואם קודם שנתרמה הלשכה נשבעין לבני העיר לפיכך כי חזר הנודר ופרע שקלו מותר דלא מהנה ליה כלל:"],[4,"משום לפרוע","דהתם אי הוה פרע תובו הוה מהני ליה:"],[5,"תפול הנאה להקדש","מפ' בגמרא:"],[5,"לא שנו","דמחזיר לו אבידתו אלא כשנכסי מחזיר אסורין על בעל אבידה שהמחזיר הדירו מנכסיו:"],[5,"דכי מהדר ליה מידעם דנפשיה קמהדר ליה","וליכא הנאה שאינו מהנהו מנכסיו כלום:"],[5,"אבל נכסי בעל אבידה אסורין על מחזיר","דמחזיר מודר מבעל אבידה לא מצי מהדר ליה אבידתו משום דאי מהדר ליה הוה מתהני מבעל אבידה:"],[5,"פרוטה דרב יוסף","דאמר רב יוסף העוסק במצוה פטור מן המצוה ולא בעי למיתב ליה פרוטה לעניא בשביל אותה מצוה שמקיים הלכך אין מחזיר לו אבידתו:"],[6,"פרוטה דרב יוסף לא שכיח","דלא שכיח כה\"ג דלהוי שביק ולא יהיב פרוטה לעניא בשביל אותה מצוה ולא מתהני מיניה כלל לפיכך מחזיר לו אבידתו:"]],[[2,"חנן אומר איבד מעותיו","משום דהוי מבריח ארי בעלמא ואע\"ג דחייב במזונות אשתו מ\"מ יכול לומר שהיתה מסתפקת ממעשה ידיה וא\"ת והא פרק השוכר [את] הפועלים (ב\"מ צג:) דרועה שהקדים ברועים ובמקלות חוזרין ונוטלין שכרם מבעל הבית ואמאי מבריח ארי בעלמא וי\"ל דלאו מבריח הוא כיון דברי היזיקא שאם לא הקדים הארי היה אוכל הבהמות והיכא דלא ברי היזיקא שהארי אינו ממש עומד ומזומן ואינו מצילו כי אם מפחד הארי לא הוי ברי היזיקא וא\"ת בפורע חובו מבריח מיניה והלא ידוע לכל שיש לו לפרוע חובו וא\"כ מהנהו וי\"ל דפורע חובו היינו זן אשתו ובניו דאיפשר שיתפרנסו ממעשה - ידיהם ולא ברי היזיקא אבל לא נראה דמדקאמר אחרי כן וזן את בניו ואת בנותיו אלמא משמע דמה שאמר זן בניו לאו פורע חובו וי\"ל דרישא מיירי שזן אשתו ואת בניו שלא בפניו וסיפא מיירי בפניו וזהו חידוש ואף על גב שמפרנסם בפניו ואין מוחהו אפ\"ה חשבינן להו מבריח עי\"ל דפורע חובו היינו פורע ממש וא\"ת א\"כ ודאי [לאו] מבריח ארי י\"ל דיכול לומר בע\"ח לפורע חובו מפייסינן ליה דמחיל לי ואפילו במשכון מפייסנא ליה והדר לי משכוני הלכך לאו ברי היזיקא ולכך הוי מבריח ארי:"],[5,"דמהני ליה פרוטה דרב יוסף","פי' בשעה שעסק במצות אבידה וא\"ת ישיב לו אכילת הנאה להקדש אותה פרוטה במקום שנוטלין עליה שכר וי\"ל דלא מצי לדיין לדעת כמה פעמים פטור הוא על ידה ממיתב ריפתא לעניא וא\"ת והא אברוחי ארי בעלמא הוא שמבריח מעליו העני דאפי' גבי פורע חוב חשבינן ליה מבריח ארי משום דמצי למימר מפייסי' ליה לפיכך לא ברי היזיקא כ\"ש הכא גבי פרוטה שאינה מצויה כ\"כ והא לא חשיב הנאה וי\"ל דפורע חובו היינו אותו שפורע חובו עבורו מבריח ארי מעליו הלכך לאו ברי היזיקא ולכך הוי כמבריח ארי אבל הכא המחזיר עצמו כמבריח הארי מעל עצמו ע\"י שמתעסק באבידת חבירו והרי הוא כאילו נוטל מכיסו של בעל אבידה ונותנה לעני ה\"נ גבי פורע חובו אם הבעל חוב נוטל מעות מזה לפטור חובו כמו כן היה אסור:"]]],[["תנן מקום שנוטלין עליה שכר תפול הנאה להקדש בשלמא למאן דאמר אפילו בשנכסי בעל אבידה אסורים על מחזיר נמי מהדר היינו דקתני מקום שנוטלין עליה שכר תיפול הנאה להקדש","אלא למאן דאמר כשנכסי בעל אבידה אסורים על מחזיר לא מהדר אמאי תיפול הנאה להקדש","אחדא קתני","איכא דמתני לה בהאי לישנא פליגי בה רבי אמי ורבי אסי חד אמר לא שנו אלא בשנכסי בעל אבידה אסורין על מחזיר ומשום פרוטה דרב יוסף לא שכיח אבל נכסי מחזיר אסורים על בעל אבדה לא מהדר ליה משום דקא מהני ליה","וחד אמר אפילו נכסי מחזיר אסורים על בעל אבידה מותר דכי מהדר ליה מידי דנפשיה קמהדר ליה","תנן מקום שנוטלין עליה שכר תפול הנאה להקדש בשלמא למאן דאמר אפילו בשנכסי מחזיר אסורים על בעל אבידה מהדר היינו דמתרץ מקום","אלא למאן דאמר בשנכסי מחזיר אסורין ולא מהדר היכי מתרץ מקום קשיא"],[[0,"מקום שנוטלין עליה שכר","חזרת אבידה שכר:"],[0,"תפול הנאה להקדש","דכיון דמודר ממנו הנאה לא מצי האי למיתב ליה שכר:"],[0,"בשלמא למ\"ד אפי' בשנכסי בעל אבידה אסורין על מחזיר נמי מהדר","ליה אבידתו היינו דקתני מקום שנוטלין עליה שכר תפול הנאה [להקדש] כיון דמחזיר לא מצי למישקל מיניה השכר לפי שזה בעל אבידה הדירו מנכסיו אינו יכול להשתייר השכר בידו דמקום שנוטלים עליה שכר הוא לא מצי בעל אבידה למימר הואיל ואינו יכול ליטול השכר יהא שלי לפיכך תפול הנאה להקדש ואי נכסי מחזיר אסורי' על בעל אבידה והאי מחזיר אדם עשיר הוא ואינו רוצה לקבל שכרו דזילותא הוא לקבל השכר מכל מקום האי בעל אבידה לא מצי תפיס לשכרו משום דמודר הוא מנכסי מחזיר ושכרו איתיה גביה דמקום שנוטלין עליה שכר הוא לפיכך תפול הנאה להקדש:"],[1,"אלא למ\"ד","כשנכסי מחזיר אסורין על בעל אבידה מהדר והתם איכא למימר תפול הנאה להקדש אבל נכסי בעל אבידה אסורים על מחזיר לא מהדר הואיל ולא מהדר ליה לא יהיב ליה אגרא אם כן מאי תפול הנאה להקדש איכא למימר הכא הואיל ולאו בר אגרא הוא:"],[2,"תריץ אחדא קתני","אחד לחוד מיירי תפול הנאה להקדש בשנכסי נחזיר אסורין על בעל אבידה דבעל אבידה לא מצי תפיס אגריה דמחזיר דלא מצי למיתהני מיניה ומחזיר נמי לא בעי ליטול שכר דעשיר הוא להכי תפול הנאה להקדש:"],[3,"לא שכיחא","וליכא הנאה כלל:"],[3,"משום דקא מהני ליה","דאע\"ג דמידעם דנפשיה מהדר ליה אפ\"ה מהני ליה דדמי כמאן דמהני ליה מנכסיו:"],[4,"מהדר ליה","משום דמידעם דנפשיה מהדר ליה ולא מהני ליה כלום:"],[5,"בשלמא למ\"ד אף בשנכסי מחזיר אסורין על בעל אבידה מהדר הינו דמתרץ מקום","כלומר דמשכחת ליה מקום שנוטלים עליה שכר תפול הנאה להקדש דכיון דנכסי מחזיר אסורין על בעל אבידה לא מצי בעל אבידה לשייר השכר לעצמו דהא נכסי מחזיר הן ואסורין עליו וצריך לו ליתן השכר והמחזיר אי אדם עשיר ואינו רוצה לקבל השכר להכי תפול הנאה להקדש:"],[6,"אלא למאן דאמר בשנכסי מחזיר אסורין על בעל אבדיה לא מהדר היכי מתרץ מקום","שנוטלין עליה שכר הא ליכא שכרו כלל דלא מהדר והכא ליכא לתרוצי אחדא קתני דהתם דכיון דקאמר בשנכסי מחזיר אסורין על בעל אבידה קא מוקי ביה תפול הנאה להקדש דכופין לבעל אבידה שיתן השכר להקדש ואין יכול להחזיק בו דנכסי מחזיר אסורין הן עליו אבל הכא ליכא לתרוצי אחדא קתני אנכסי בעל אבידה אסורין עליה דכיון דנכסי מחזיר אין אסורין על בעל אבידה מצי האי בעל אבידה למיתפס השכר לנפשיה ולא נפיל להקדש והיכי מתרץ מקום קשיא:"]],[[0,"בשלמא למאן דאמר בשנכסי כו'","פירוש ששניהם מודרי' זה מזה לכך תפול הנאה להקדש אלא מ\"ד וכו' אמאי תפול הנאה להקדש יתן שכרו למחזיר שהרי אינו מודר מבעל אבדה:"],[2,"ה\"ג אחדא","פי' לגבי חדא מינייהו קתני תפול (עלי) הנאה להקדש לגבי בעל אבידה שאם המחזיר אינו רוצה לקבל השכר א\"כ נהנה מן המחזיר והוא מודר הנאה ממנו אשמעי' במתני' שצריך שיתן הבעל אבידה שכר ויפול הנאה להקדש וא\"ת איכפל תנא לאשמועינן שאם היכא שאין המחזיר רוצה לקבל וי\"ל דאורחא דמילתא הוא שאינו חושש לקבל שכר הואיל דמצוה הוא אע\"פ שאינו מחוייב לעשות כיון שהוא בטל ממלאכתו:"],[6,"היכי מתרץ מקום קשיא","וא\"ת ולישני כדלעיל דחדא קתני ורישא מיירי שאין בעל אבידה רוצה לעכב השכר לעצמו ואז צריך שתפול הנאה להקדש שאין המחזיר רשאי לאוכלו שמודר הנאה ממנו יש לומר דלא דמי בשלמא לעיל רגילות הוא שאין המחזיר רוצה ליטול שכר על השבת אבידה משום - מצוה דגנאי הוא אבל הכא לאו אורחא דמלתא שהרי אין גנאי מלעכבו לעצמו:"]]],[["אמר רבא היתה לפניו ככר של הפקר ואמר ככר זו הקדש נטלה לאוכלה מעל לפי כולה להורישה לבניו מעל לפי טובת הנאה שבה","בעא מיניה רב חייא בר אבין מרבא ככרי עליך ונתנה לו במתנה מהו ככרי אמר לו כי איתיה ברשותיה הוא דאסור או דלמא עליך אמר ליה עילויה שויתיה הקדש","אמר ליה פשיטא דאף על גב דיהבה ליה במתנה אסור אלא ככרי עליך לאפוקי מאי לאו לאפוקי דאי גנבה מיניה מיגנב אמר ליה לא לאפוקי דאי אזמניה עלה"],[[0,"ככר של הפקר","וכ\"ש אי דנפשיה אלא רבותא קמ\"ל דמצי זכי בהפקר לחליה קדושה עילויה:"],[0,"נטלה על מנת לאוכלה","דכיון שהחזיק בו קנאה ואם אכלה מעל לפי כולה ומשלם להקדש לפי כולה וחומש שהרי הוציאה לחולין:"],[0,"אבל נטלה על מנת להורישה לבניו","ואחר כך הקדישה עסקינן דקודם לכן לא יכול להקדישה:"],[0,"לא מעל אלא לפי טובת הנאה שבה","שאינו משלם להקדש אלא כפי חזקת טובה שנותן לאביו אחד מן הבנים בשביל שמורישה לו והיינו טובת הנאה:"],[1,"","ככרי יהא אסור עליך וחזר ונתנו למודר במתנה מהו:"],[1,"כי איתיה ברשותיה","כלומר כל זמן שהוא של מדיר הוא דאסור דהכי משמע ככרי כל זמן שהוא שלי:"],[1,"או דלמא עליך א\"ל","ועלויה שויתיה לאותו ככר הקדש ואע\"פ שנתנו לו במתנה אסור:"],[2,"אלא","הא קמבעיא ליה האי דאמר ככרי עליך אי אמרי' דכל זמן שהוא ברשותיה . דאי אתי לידיה מיניה דיליה קאמר ליה:"],[2,"ולאפוקי דאי גנבה מיגנב","לאותו ככר ונתנה לו הגנב במתנה שאינו אסור בה הואיל והוא עצמו לא נתנה לו או דלמא אע\"ג דאי גנבה ליה מיגנב אסירה ליה:"],[2,"לא לאפוקי דאי אזמניה עליה","למיכל מההוא ככר מעיקרא והדר א\"ל ככרי עליך דהתם כיון דאזמניה עליה קנה חלקו כמה שהוא יכול לאכול הימנה ואינו יכול לאוסרה עליו דלאו כוליה דנותן הוא אלא גם דמזומן:"]],[[0,"היתה לפניו ככר של הקדש וכו'","תימה אי איירי בהקדש מאי שייכא כאן מלתא דרבא גבי מתני' דמיירי בקונמות ונראה דרבא מיירי בקונמות והקדש דנקט לאו דוקא אלא כהקדש קאמר וא\"ת אמאי נקט מלתא בקונמות כיון דבהקדש מצי למינקט וי\"ל דבהקדש לא אמרי' מעל לפי טובת הנאה שבה אם אין בו שוה פרוטה דאין מועל בהקדש בפחות משוה פרוטה אבל בקונמות בכל דהו איכא איסור הנאה:"],[0,"ואמר ככר זו הקדש","בלשון זה אמר אע\"פ שלא אמר לכשאזכה בה אפ\"ה כי זכה בה הוי הקדש והואיל ודעתו לזכות בה וא\"ת והא אין אדם מקדיש דשלב\"ל ולא דמי לאומר הרי פסח קדושה לאחר שלשים דהויא קדושה התם בידו להקדיש מיד אבל הכא לאו בידו להקדיש מיד לכ\"נ שנטלה וזכה בה ולאח\"כ הקדישה ובא אדם אחר ונטלה ואכלה או הוא עצמו מתחילתו שזכה בה נטלה לאוכלה זכה בכולה והלכך הקדש נמי חל על כולה ולכך מעל לפי כולה ואם מתחלת נטילתה לזכות בה בכולה להוריש לבניו לחלוק להם או ליתנה למי שירצה ואין לו בה אלא טובת הנאה אבל גוף הדבר אינו שלו והקדש כמו כן שהרי אין אדם מקריב אלא מה שיש לו בה ולכך מעל לפי טובת הנאה שבה ול\"נ דלישנא דרבא לא משמע הכי דקאמר ככר זה הקדש ואחר מכאן נטלה לאוכלה משמע דהאי אחר שהקדיש שלא זכה בה עני אחר מכיון שהקדישה לכ\"נ דלעולם לא זכה בה עדיין בשעת הקדש וכי תימא אין אדם מקדיש דבר שלא בא לעולם ועדיין לא זכה בה מיירי שהוא בתוך ארבע אמותיו וארבע אמות שלו קנו לו אי נמי כיון שבידו לזכות בה שהוא קרוב ממנה יותר משום אדם הוי חשיב שפיר דבר (שלא) בא לעולם כדאמר פרק האומר בקידושין (דף סב -) כל שבידו לאו כמחוסר מעשה דמי נטלה לאכלה כלומר אחר שזכה בה והקדישה כדפרישית שהיתה תוך ארבע אמותיו והקדישה אחר מכאן:"],[0,"נטלה לאוכלה מעל לפי כולה","לפי שנתכוון לשנות כולה מרשות הקדש ולכך מעל לפי כולה נטלה ע\"מ להורישה לבניו א\"כ לא נתכוון לשנות בכולה ולכך לא מעל אלא לפי טובת הנאה ומידי דהוה אמשאיל קרדום של הקדש ובקע בו לא מעל אלא לפי טובת הנאה שבה:"],[1,"או דלמא עליך אמר ליה ועילויה דידיה שוויה הקדש","לפי גירסא זו דייק מלשון עליך וקשה דא\"כ מאי פריך בסמוך מפרה שאני נהנה לך הא לא אמר ליה עליך הא ליכא למימר דבסמוך פריך מנכסי עליך וכו' דהא מדגרסינן בסיפא או שניתנה לו במתנה ולא קתני שנתנה לו משמע דאפרה קאי ולא אנכסים לכ\"נ דגרס הכא או דלמא עילוייה שויי' הקדש בלא עליך: אמר ליה פשיטא דאע\"ג דמהני במתנה אסור:"],[2,"אלא לאפוקי מאי לאפוקי דאי גנבה מיגנב אמר ליה לאפוקי דאי אזמניה עליה","הכי גריס ר\"ת וה\"פ פשיטא דאסור כי יהבה ליה במתנה אלא לאפוקי מאי כלומר ומה שאסר לענין מה אסרה עליו וכי תעלה על דעתך לומר שאסרה עליו לענין דאי גנבה מיגנב זהו תימה דלא אסרה עליו אלא כשבא לידו בגניבה דאין זו סברא לומר דאסיק אדעתיה דמיגנבא וכן צ\"ל ע\"כ דאי ס\"ד דבמתנה מותרת הא ודאי כל זמן שבידו לא הוצרך לאוסרה דבע\"כ לא יקחנה וצ\"ל דלענין גניבה אסרה עליו וזהו תימה כדפי' ומשני דאי אזמניה - עליה זה בא לאוסרה עליו דמזה אסיק אדעתיה שפיר ולעולם אימא לך דבמתנה מותרת ואע\"ג שדחה סברא פשיטותא מ\"מ רבא במילתיה דאמר רבא דאסור על ידי מתנה ולהכי פריך ליה:"]]],[["איתיביה אמר לו השאילני פרתך אמר לו קונם פרה שאני קנוי לך נכסי עליך אם יש לי פרה אלא זו השאילני קרדומך אמר לו קונם קרדום שיש לי שאני קנוי נכסי עלי אם יש לי קרדום אלא זה ונמצא שיש לו בחייו אסור מת או שנִתְּנה לו במתנה הרי זה מותר","אמר רב אחא בריה דרב איקא שניתנה לו על ידי אחר","אמר רב אשי דיקא נמי דקתני שניתנה לו ולא קתני שנתָנָהּ לו","בעא מיניה רבא מרב נחמן יש מעילה בקונמות או לא","אמר ליה תניתוה מקום שנוטלין עליה שכר תיפול הנאה להקדש למימרא כי הקדש מה הקדש יש בו מעילה אף קונמות יש בהן מעילה","כתנאי קונם ככר זו הקדש ואכלה בין הוא ובין חבירו מעל לפיכך יש לה פדיון ככר זו עלי להקדש ואכלה הוא מעל חבירו לא מעל לפיכך אין לה פדיון דברי רבי מאיר","וחכמים אומרים בין כך ובין כך לא מעל לפי שאין מעילה בקונמות","אמר ליה רב אחא בריה דרב אוויא לרב אשי ככרי עליך ונתנה לו במתנה מי מעל למעול נותן הא לא אסירא עליה למעול מקבל יכול דאמר היתירא בעיתי איסורא לא בעיתי אמר ליה מקבל מעל לכשיוציא שכל המוציא מעות הקדש לחולין כסבור של חולין הוא מועל אף זה מועל"],[[0,"ה\"ג קונם פרה שאני הנאה לך","והכי משמע קונם יהו עליך שאר פרות שיש לי שאני מהנה לך כלומר שאין לי פרה אחרת וזו שיש לי איני משאילך שזו לא רצה להשאילו והאחרות אסורות עליו בנדר או שאמר לו נכסי אסורין עליך אם יש לי פרה אחרת אלא זו ונמצא שיש לו פרה אחרת אסור לישאל ליהנות:"],[0,"קונם קורדום שיש לי שאיני קנוי","כלומר שלא קניתי קורדום אחר וזה איני משאילך שאני צריך לו או שאמר לו קונם נכסי יהו אסורים עלי אם יש לי קורדום אחר אלא זה ונמצא שיש לו קורדום אחר:"],[0,"בחייו אסור","בעל הקורדום אסור ליהנות מנכסיו כל ימי חייו אי נמי בחייו דמדיר אסורין נכסיו על המודר:"],[0,"מת","המשאיל:"],[0,"או שנתנה לו במתנה","למודר אמר לן המורה האי דקתני מת לא קאי אסיפא כלל דהיכי מצי קתני אסיפא [דהא] קתני נכסי עלי מת או שנתנה לו במתנה הרי זה מותר מי מותר הרי אנפשיה קאמר אלא ארישא קתני אהשאילני פרתך שאם מת המדיר מותר בפרה או בנכסים של מדיר דהא אמר נכסי ומאחר שמת לאו נכסיה דידיה אינון והכא נמי אם ניתנו לו במתנה ואמר לן המורה דכס\"ג שאני הנאה שאינו קנוי כינוי לשון בני אדם (שרי) דהכי היו נודרים בירושלים ובנדרים הלך אחר לשון בני אדם קתני שניתנו לו במתנה הרי זה מותר וקשיא לרבא דאמר אע\"ג דיהיב ליה במתנה אסור:"],[1,"אמר לך רבא הכא במאי עסקינן כגון שניתנה לו על ידי אחר","שבעל הפרה נתנו לאחר ואותו אחר נתנו לשואל ולהכי מותר שכבר הוציאה משאיל מרשותו כשנתנה לאחר אבל היכא דאמר ליה ככרי עליך ולא נתנה לו על ידי אחר הואיל ולא יצאת מרשותו קודם לכן אסור ולא דמי להיכא דאיגנבה מיניה משום דהיכא דאיגנבה מיניה הואיל ושלא מדעתו דבעל הככר יצא מרשותו כעודה בידו דמי ואסור אבל היכא שנתנה לו במתנה על ידי אחר יצאת מרשותו מדעתו:"],[2,"ולא קתני שנתנה לו","דמשמע שהוא עצמו נתנו לו:"],[3,"יש מעילה בקונמות","היכא דאמר קונם ככר זה ואכלו מי הוי כהקדש מעליא דיש בו מעילה ומעל או לא:"],[4,"[תניתוה מקום] שנוטלין עליה שכר","ומודר היינו דאמר קונם ומדמי ליה להקדש:"],[5,"קונם ככר זה הקדש","שאמר בלשון הקדש ובלשון קונם והוא הדין נמי לא אמרה אלא בלשון קונם:"],[5,"בין הוא בין חבירו מעל","שהרי הקדישה סתם אכולי עלמא:"],[5,"לפיכך","הואיל ויש בה מעילה יש בה פדיון ויצאה לחולין דהוי כשאר הקדש:"],[5,"אמר זו עלי הקדיש","כיון דאמר עלי עליה דידיה שוויה הקדש והוא מעל אם אכל חייב לשלומי:"],[5,"חבירו לא מעל","דלא אסרה אלא על עצמו וגבי חבירו הוי כחולין:"],[5,"לפיכך אין לה פדיון","שהוא עצמו אין יכול לפדותה לעולם שהרי אמר עלי ולא על אחר ואחר אין יכול למעול בה:"],[6,"בין כך ובין כך","בין אמר סתם בין אמר עלי לא מעל בין הוא ובין חבירו אף על פי שאמר הקדש כיון דאמר נמי קונם שאין מעילה בקונמות:"],[7,"מי מעל","אליבא דמאן דאמר יש מעילה בקונמות קבעי:"],[7,"הא לא אסירא עליה","דנותן:"],[7,"התירא ניחא לי דתיתיב לי איסורא לא בעיתי","כלומר דבתורת היתר קבלתיה ממך ולא בתורת איסור:"],[7,"וכסבור של חולין הן מעל","אעפ\"כ הכי נמי אף זה המקבל אע\"פ שסבור זה המקבל שהיתר הוא כי אכלה מעל:"]],[[0,"קונם פרה שיש לי שאני הנאה לך נכסי עליך אם יש לי פרה אלא זו","שני נדרים הוו ואי קאמר שאומר לו קונם פרה שיש לי שאוכל ליהנות לך ממנה כלו' שאין לי פרה אחרת ואם יש לי תהא קונם עליך או שאמר בלשון הזה נכסי עליך קונם אם יש לי פרה אלא זו שאני עושה בה מלאכתי ונמצא שיש לו פרה אחרת ועתה נאסרה הפרה והנכסים עליו וגבי קונם נמי ה\"פ כדפירשתי:"],[0,"מת או שנתנה לו במתנה מותרת","מת דתו לא מיקרו פרה וקרדום שלו וכן שנתנה לו במתנה מותרת וקס\"ד שנתנה המדיר למודר ומשני שניתנה לו על ידי אחר לפירוש שני דלעיל ניחא דפריך מנתנה לו במתנה דאפרה ואקרדום קאי ואע\"ג דלא אמר עליך אבל לפי' ראשון דלעיל דדייק מעליך קשה מאי פריך מנתנה לו פרה וקרדום הא לא אמר עליך וי\"ל דלפי פירוש ראשון גרס שניתנו לשון רבים וקאי נמי אנכסים ודוחק הוא שבכל הספרים גרסי' שניתן לשון יחיד דמשמע דקאי דוקא אפרה ואקרדום לכ\"נ כפירוש שני וא\"ת אכתי היא גופה תקשה לך אמאי לא תנא שניתנו משום נכסים הלא מיירי משנה גם מנכסים וי\"ל מ\"מ לא נחת לאשמועינן לאשריותא דפרה וקרדום שהיה רוצה לישאל ממנו היה עיקר הנדר וגם בכלל נכסים הם דמיתסר נמי בנדר כנכסים:"],[5,"הוא מעל וחבירו לא מעל לפיכך אין לו פדיון וחכ\"א בין כך ובין כך לא מעל","פירוש וחכמים לא קאי לרישא אלא קאי לסיפא דבעי למימר בין הוא בין חבירו לא מעל וקשה דלישנא דבין כך ובין כך משמע דקאי לכולה מלתא דר\"מ ועוד משמע דאפילו לר\"מ דיש בו מעילה מכל מקום אין לו פדיון וקשה בפרק האשה רבה (יבמות דף פח.) משמע האי יש בו מעילה משום דבידו לפדותו אלמא משמע דיש בו פדיה בקונמות וע\"ק ברישא קאמר ככר זה הקדש מעל מאי קמשמע לן פשיטא דהקדש גמור יש בו פדיון ומעילה לכ\"נ לפרש דרישא לא מיירי בהקדש ממש אלא בקונם בלשון הקדש שאסר הככר לכל כמו הקדש ולכך יש בו מעילה כיון שנאסר לכל כהקדש גמור ככר זה עלי הקדש דמיירי בקונם שאינו אסור לכ\"ע אלא לדידיה לכך אין לו פדיון דהא דאמרינן בשיש בו מעילה משום שבידו לפדותו היינו קונם שאסור לכל כמו הקדש - וחכמים אומרים בין כך ובין כך כו' קאי אפילו לרישא משום דאין מעילה בשום קונמות וכיון שאמר הקדש בלשון קונמות אין מועלין:"]]],[["\u0001מתני׳\u0002 ותורם את תרומתו ומעשרותיו לדעתו ומקריב עליו קיני זבין קיני זבות קיני יולדות חטאות ואשמות ומלמדו מדרש הלכות ואגדות אבל לא ילמדנו מקרא אבל מלמד הוא את בניו ואת בנותיו מקרא","\u0001גמ׳\u0002 איבעיא להו הני כהני שלוחי דידן הוו או שלוחי דשמיא למאי נפקא מינה למודר הנאה אי אמרת דשלוחי דידן הוו הא מהני ליה ואסור ואי אמרת שלוחי דשמיא שרי מאי","תא שמע דתנן מקריב עליו קיני זבין כו' אי אמרת שלוחי דידן קא מהני ליה","וליטעמיך ליתני מקריב עליו קרבנות אלא מחוסרי כפרה שאני דאמר רבי יוחנן הכל צריכין דעת חוץ ממחוסרי כפרה שהרי אדם מביא קרבן על בניו ועל בנותיו הקטנים שנאמר זאת תורת הזב (ויקרא טו, לב) בין גדול בין קטן","אלא מעתה לרבי יוחנן זאת תורת היולדת וגו' (ויקרא יג, יב) בין קטנה ובין גדולה קטנה בת לידה היא והא תני רב ביבי קמיה דרב נחמן שלוש נשים משמשות במוך קטנה ומעוברת ומניקה קטנה שמא תתעבר ותמות","ההיא זאת תורת היולדת בין פיקחת בין שוטה שכן אדם מביא קרבן על אשתו שוטה","כדברי רבי יהודה דתניא רבי יהודה אומר אדם מביא קרבן עשיר על אשתו וכל קרבנות שחייבת","שכך כותב לה ואחריות דאית ליך עלי מן קדמת דנא"],[[0,"מתני' ותורם את תרומתו וכו'","מפרש בגמרא:"],[0,"[ומקריב עליו]","אם היה כהן אותו שנדר שלא יהנה ממנו יכול להקריב עליו קיני זבין וקיני זבות וכו':"],[1,"גמ' הני כהני","שמקריבין קרבנות:"],[1,"שלוחי דידן","דבעלי קרבן:"],[2,"הא קא מהני ליה","שליח לכפר כפרתו ואיהו הדירו שלא יהנה ממנו:"],[3,"אלא","מדקתני מקריב עליו קיני זבין וכו' ש\"מ דשלוחי דשמיא נינהו:"],[3,"","[וליטעמיך] אם כן דשלוחי דשמיא נינהו ליתני סתם מקריב עליו קרבנות אלא מדלא קתני אלא קיני זבין וכו' ש\"מ דשלוחי דידן נינהו ודקשיא לן הא קמהני ליה תריץ לא קמהני ליה דבמחוסרי כפרה שאני כי הני דמתני':"],[3,"דא\"ר יוחנן הכל צריכין דעת","כל הקרבנות צריכין שיהו מקריבים בעלים חוץ ממחוסרי וכו':"],[3,"על בניו ועל בנותיו הקטנים","כשהן מחוסרי כפרה דכתיב זאת תורת הזב וגו' ונשים שמביא קרבן עליהן אע\"פ שאין להם דעת הם הכי נמי גדולים אין צריכין להביא כפרתן לדעתן הלכך הואיל ומקריב עליו שלא לדעתו לא מהני ליה דהא לא ידע ומותר:"],[4,"אלא מעתה לר' יוחנן","דמפיק מזאת תורת הזב בין גדול בין קטן הכא נמי מצי למימר מהאי קרא נמי:"],[4,"שמא תתעבר ותמות","ודאי אלמא לאו בת לידה היא:"],[5,"אמר לך רבי יוחנן","ההוא זאת תורת היולדת לא מרבי לה לקטנה אלא בגדולה מיירי וקא מרבה אפילו יולדת שוטה:"],[5,"שכן אדם מביא קרבן עשיר אפילו על אשתו שוטה","אדם מביא קרבן עשיר על אשתו בין פקחת בין שוטה ולא אמרינן דאע\"פ שנשאת לעשיר עניה היא דמה שקנתה אשה קנה בעלה אלא כל הקרבנות שחייבת מביא עליה:"],[7,"שבך כתב לה ואחריות כו'","דהכי משמע אחריותא עלי וכי היכי דהאי מביא קרבן על אשתו יולדת אפילו שוטה כך כל מחוסרי כפרה אין צריכין דעת ולעולם שלוחי דידן נינהו:"]],[[0,"מקריב עליו קינין וכו'","אם היה המדיר כהן מקריב לזה המודר:"],[0,"לא ילמדנו מקרא","מפרש בגמרא דבלימוד מקרא נוטל שכר אבל מלמדו מדרש כמו ת\"כ והלכות דאין נוטלין עליה שכר ובגמ' מפרש טעמא דנוטלין שכר על המקרא ואין נוטלין שכר על המדר':"],[0,"אבל מלמד בניו מקרא","מצוה קא עביד ולא הוה אלא גורם הנאה בעלמא ואפילו במקום נמי דנוטלין שכר עליה דמ\"מ לא היה המודר נותן שכר למלמד לבניו:"],[1,"איבעי' להו הני כהני שלוחי דרחמנא נינהו וכו'","ואי אמרת שלוחי [דידן] נינהו הא מהני ליה דעבד שליחותא - דודאי גוף הקרבן מצוה קעביד מיהו כיון דהאי כהן שלוחו בזה אסור וה\"נ אמרינן גבי תורם דאי אמרת צריך דעת הא קמהני ליה וה\"נ אי שלוחי דידן נינהו אסור מיהו קשה אמאי לא פשיט ליה מההוא דפ' קמא דקידושין (דף כג -) אמר רב כהנא הני כהני שלוחי דרחמנא נינהו דאי ס\"ד שלוחי דידן נינהו מי איכא מידי דאנן לא מצינן למיעבד ואינהו קא עבדי וי\"ל דרוצה לפשוט ממשנה או מברייתא:"],[2,"ת\"ש ומקריב עליו קיני זבים ואי אמרת שלוחי דידן הא קמהני ליה","ויש להקשות דלמא דאמר כל הרוצה להקריב יבוא ויקריב דכה\"ג לא מהני ליה ושמא נראה לו דמיירי במודר הנאה בכל כהני דהאי ודאי לא מצינו למימר כי בכה\"ג שאני דאז לא יצטרך דעת בעלים ואותן הוו שלוחי דידן:"],[3,"כדרבי' יוחנן","דאמר הכל צריך דעת בעלים אם מחוייב אדם עולה ושלמים אינו יכול לפטור אותו חבירו שלא מדעתו:"],[3,"שהרי מקריב אדם על בניו ועל בנותיו","להתירן לאכול בקדשים דכתיב זאת תורת הזב בין גדול בין קטן וקטן לאו בר דעת הוא אלמא דאין צריך דעת בעלים להתירו לאכול בקדשים במחוסר כפרה:"],[4,"אלא מעתה לרבי יוחנן זאת תורת היולדת וכו'","קצת קשה דבלאו רבי יוחנן ברייתא היא בפ' בנות כותים (נדה דף לד:) דכתיב זאת תורת הזב בין גדול בין קטן:"],[5,"ומשני ההיא זאת תורת היולדת בין פקחת בין שוטה","שכך מצינו שאדם מביא קרבן על אשתו שוטה:"],[6,"מביא אדם קרבן עשיר על אשתו","אם היא חייבת קרבן לידה או מצורעת ואין יכול לומר עניה היא ואין לה שום דבר שכך כתב לה בכתובתה דאחריות דאית לך עלי מן קדמת דנא דמשמע ליה אפילו שוטה צ\"ע מנא ליה הא דמשמע שהוא חייב כל מה שחייבת קודם מזה יש ללמוד דאדם חייב לפרוע חובות אשתו שהיא חייבת קודם שישאנה ולא נראה דבפרק יש נוחלין (ב\"ב דף קלט -) איבעיא ליה אי בעל בנכסי אשתו לוקח הוי או יורש הוי דאי לוקח הוי לא יפרע לבעלי חובות של אשתו שלוותה קודם ואפילו מנכסי מלוג שלה ואם יורש הוי יפרע מנכסי מלוג שלה כמו יורש שפורע חובות אביו מקרקעי ואם כן לא מיבעי אלא מנכסי מלוג שלה אבל מנכסים שלו לא יפרע שום דבר - והך בעיא דלוקח הוי או יורש הוי פסק רבינו שמואל בן בתו של רש\"י קבלה מרבינו חננאל דיורש הוי וצריך הבעל לפרוע מנכסי מלוג שהכניסה לו אשתו והכי הלכתא שאדם פורע חוב אשתו שהיא חייבת קודם לכן אם יש מטלטלין או חובות כעין שהכניסה לו אע\"פ שיורש אינו פורע ממטלטלין מיהו לאחר תקנות גאונים שתיקנו להיות עתה מטלטלין כמקרקעי וגובה כתובתה ממטלטלין אע\"ג דממנה אין לגבות כ\"א ממקרקעי כמו כן גם החובות נמי יתפרעו מן המטלטלין דכל הדין הנוהג בקרקעות נוהג במטלטלין והא דאמר הכא כל קרבנות שהיא חייבת דוקא קרבנות אבל חוב לא יפרע אלא ממה שהכניסה לו דכיון דיורש הוי ומטלטלין כקרקעות עתה שיעבודם על אותן נכסים אין יכולת ביד הבעל להפקיען אבל יותר ממה שהכניסה לו [אינו פורע] וקרבנותיה נמי דוקא קרבנות חובה אבל לא נדרים ונדבות ואם לאחר נישואין [נדרה קרבן] לא ישלם נדריה דאם לא כן יכולה להחריב בעלה - והכי משמע בירושלמי - גרסא אחרת אם פטרה אינו חייב וה\"פ כל קרבנות שהיא חייבת כשהיא תחתיו חייב לפרוע ולפיכך אם פטרה שגירשה אינו חייב שכך כתבה בשובר של כתובה והתקבלתי כתובתי ואחריות דאית לי עלך מן קדמת דנא ולגירסא זו אינו חייב לשלם כלום מקודם נישואין:"]]],[["מתיב רב שימי בר אבא אם היה כהן יזרוק עליו דם חטאתו ודם אשמו","דם חטאתו של מצורע ודם אשמו של מצורע דכתיב (ויקרא יד, ב) זאת תהיה תורת המצורע בין גדול ובין קטן","תנן (משנה גיטין ה, ד) הכהנים שפיגלו במקדש מזידין חייבין הא שוגגין פטורין אלא שפיגולן פיגול","אי אמרת בשלמא שלוחי דשמיא הוו היינו שפיגולן פיגול אלא אי אמרת שלוחי דידן הוו אמאי פיגולן פיגול לימא ליה שליחא שויתיך לתקוני ולא לעוותי","אמרי שאני גבי פיגול דאמר קרא (ויקרא ז, יח) לא יחשב לו מכל מקום","גופא אמר רבי יוחנן הכל צריכין דעת חוץ ממחוסר כפרה שהרי אדם מביא קרבן על בניו ועל בנותיו הקטנים אלא מעתה יביא אדם חטאת חלב על חבירו שכן אדם מביא על אשתו שוטה כרבי יהודה אלמה אמר רבי אלעזר הפריש חטאת חלב על חבירו לא עשה כלום?","אשתו שוטה היכי דמי אי דאכלה כשהיא שוטה לאו בת קרבן היא","ואי דאכלה כשהיא פקחת ונשתטית, הא אמר רבי ירמיה אמר רבי אבהו אמר רבי יוחנן אכל חלב והפריש קרבן ונשתטה וחזר ונשתפה פסול הואיל ונדחה ידחה","אלא מעתה יביא אדם פסח על חבירו שכן אדם מביא על בניו ועל בנותיו הקטנים אלמה אמר רבי אלעזר הפריש פסח על חבירו לא עשה כלום","אמר רבי זירא שה לבית אבות (שמות יב, ג) לאו דאורייתא","וממאי מדתנן (משנה פסחים ח, ג) האומר לבניו הריני שוחט את הפסח על מי שיעלה מכם ראשון לירושלים כיון שהכניס ראשון ראשו ורובו זכה בחלקו ומזכה את אחיו עמו ואי אמרת שה לבית דאורייתא על בישרא קאי ומזכי להו","אלא למה להו דאמר להון אבוהון כדי לזרזן במצות תניא נמי הכי מעשה היה וקדמו בנות לבנים ונמצאו בנות זריזות ובנים שפלים:","ותורם את תרומותיו כו':"],[[0,"אם היה כהן","המדיר:"],[0,"יזרוק עליו דם חטאתו ודם אשמו","קתני סתם דמשמע כל חטאות ואשמות ואע\"ג דלא מחוסרי כפרה נינהו:"],[1,"","לא לעולם שלוחי דידן נינהו ומאי דם חטאתו ודם אשמו דקתני חטאתו של מצורע כו'. דהיינו מחוסרי כפרה וכו' וה\"ה לגדול:"],[2,"מזידין חייבין","לשלם קרבן לבעלים:"],[3,"אלא מעתה","יביא אדם אפי' חטאת חלב על חבירו שכן מביא קרבן על אשתו שוטה דמשמע כל קרבנות שהוא חייבת אפי' אם אכלה חלב: ומתרץ רבי יוחנן אשתו שוטה היכי דמי שתהא מחויבת קרבן אי דאכלה כו':"],[3,"לתקוני שויתיך","שליח ולא לעוותי:"],[4,"אמרי","לעולם שלוחי דידן נינהו ולהכי פיגולו פיגול:"],[4,"לא יחשב לו","פיגול יהיה מכל מקום:"],[5,"אלא מעתה","יביא אדם אפי' חטאת חלב על חבירו שכן מביא קרבן על אשתו שוטה דמשמע כל קרבנות שהיא חייבת אפי' אם אכלה חלב:"],[6,"ומתרץ רבי יוחנן אשתו שוטה היכי דמי","שתהא מחויבת קרבן אי דאכלה כו':"],[7,"פסול","הקרבן דהואיל ונדחה כשנשתטית דלאו בת קרבן היא ידחה התם נמי גבי אשה הואיל ונדחית בשעת אכילה נדחית מהכל ואין אדם מביא קרבן חלב על אשתו שוטה וליכא למירמא מהכא וכי קאמינא דלר' יהודה הא דמביא קרבן על אשתו שוטה כגון זבה או יולדת או מצורעת:"],[8,"וקפריך תו יביא אדם כו'","אלמה אמר ר' אלעזר הפריש פסח על חבירו שלא מדעתו כו':"],[9,"אמר רבי זירא שה לבית אבות","דמשמע אדם מביא פסח ושוחט על בניו ועל בנותיו הקטנים:"],[9,"לאו דאורייתא הוא","להכי הפריש פסח על חבירו לא עשה ולא כלום:"],[10,"וממאי","דלאו דאורייתא הוא מדתנן וכו':"],[10,"ואי אמרת שה לבית אבות","דאדם שוחט על בניו הקטנים דאורייתא:"],[10,"על בישרא קאי ומזכי להו","כלומר היאך יכול זה לזכות את אחיו מאחר שנשחט והא תנן (פסחים פט.) נמנין ומושכין ידיהן עד שישחט אלא אזמוני להו לאחר שחיטה לאו דאורייתא והך משנה משמע דבבניו קטנים מיירי:"],[11,"אלא","הואיל ולאו דאורייתא הוא למה ליה לאבוהון למימר הריני שוחט את הפסח על מי שיעלה מכם לירושלים כדי לזרזן במצות:"],[11,"תניא נמי הכי","כדי לזרזן קאמר מדקאמר בנים שפלים ולא קאמר ובנים לא יצאו ידי חובתן מכלל דלא מחייבי מדאורייתא אלא לזרזן קאמר:"]],[[0,"אם היה כהן","אותו המדיר ממנו זורק חטאתו ואשמו דמשמע ליה דמיירי בחטאת חלב ודם אלמא שלוחי דרחמנא נינהו וה\"ה דמצי לאותובי ממתני' חטאות ואשמות:"],[3,"","אמאי פיגולו פיגול לימא לתיקוני שדרתיך ולא לעוותי:"],[5,"אלמה אמר ר' אלעזר הפריש חטאת חלב וכו'","תימה מדרבי יוחנן גופיה תיקשי דהכל צריכין דעת וצ\"ע וי\"ל דמצינן למימר דר' יוחנן מיירי בכהן המקריב שצריך דעת בעלים:"],[6,"שוטה לאו בת קרבן היא","והא דאמר לעיל זאת תורת היולדת בין פיקחת בין שוטה מיהו איהו לא מצי מייתי:"],[8,"יביא אדם פסח על חבירו שכן אדם מביא קרבן על בניו כשהן קטנים וכו' אמר רבי זירא שה לבית לאו דאורייתא הוא","כלומר דקטנים אינם צריכים למנות דאם אוכלין מן הפסח לא הוי כנאכל שלא למנוייו דלא אסר רחמנא אלא להנהו דאיתנהו במצות תכוסו אבל אותם דלא שייך בהו לא מיירי מידי דהוה אנשים דרשות הן שאע\"פ שאין חייבות בפסח מותרות לאכול ממנו ואינו נקרא שלא למנוייו וכן בקטנים:"],[10,"על בישרא קאי ומזכה להון","בתמיה כלומר לאחר שחיטה יכול להמנותם והא תנן (פסחים דף פט.) מושכין ידיהן עד שישחטו אבל לאחר שחיטה לא אלמא דהמנאת קטנים לאו דאורייתא ובניו דקטנים מיירי:"],[11,"בקטנים למה לי למימר להו","כיון דלא המנום. לזרזן:"]]],[["איבעיא להו התורם משלו על של חבירו צריך דעתו או לא מי אמרינן כיון דזכות הוא לו לא צריך דעת או דלמא מצוה דיליה היא וניחא ליה למיעבדיה","תא שמע תורם את תרומותיו ואת מעשרותיו לדעתו במאי עסקינן אילימא מן בעל הכרי על של בעל הכרי ולדעתו דמאן אילימא לדעתו דיליה מאן שוויה שליח","אלא לדעתו דבעל הכרי הא קמהני ליה דקעביד שליחותיה אלא משלו על של הכרי ולדעתו דמאן אילימא לדעתו דבעל הכרי הא קמהני ליה אלא לאו לדעתיה דנפשיה ומשלו תורם על של חבירו ואי אמרת צריך דעת הא קמהני ליה אלא לאו אין צריך דעת","לעולם משל בעל הכרי על בעל הכרי כדאמר רבא באומר כל הרוצה לתרום יבא ויתרום הכא נמי באומר וכו'","בעא מיניה רבי ירמיה מרבי זירא התורם משלו על של חבירו טובת הנאה של מי מי אמרינן אי לאו פירי דהאיך מי מתקנא כריא דההוא או דלמא אי לאו כריא דההוא לא הויין פירי דהדין תרומה","אמר ליה אמר קרא (דברים יד, כב) את כל תבואת זרעך ונתת","איתיביה תורם את תרומותיו ואת מעשרותיו לדעתו ואי אמרת טובת הנאה דבעל הכרי הא קא מהני ליה אלא שמע מינה טובת הנאה דיליה אמרי לא משל בעל הכרי על של בעל הכרי ולדעתו דבעל הכרי באומר כל הרוצה לתרום יבא ויתרום","תא שמע דאמר רבי אבהו אמר רבי יוחנן המקדיש מוסיף חומש ומתכפר עושה תמורה והתורם משלו על שאינו שלו טובת הנאה שלו:","מלמדו מדרש הלכות ואגדות אבל לא ילמדנו מקרא: מקרא מאי טעמא לא ילמדנו משום דקמהני ליה מדרש נמי קמהני ליה אמר שמואל במקום שנוטלין שכר על המקרא ואין נוטלין שכר על המדרש מאי פסקא"],[[0,"כיון דזכות הוא לו","שמרויח שתורם עליו משלו ולא צריך ליתן לו כלום:"],[0,"לא צריך דעת","שזכין לאדם שלא בפניו:"],[0,"או דלמא","כיון דמצוה דיליה היא דבעל הכרי ניחא ליה למיעבדיה שיקיים הוא את המצוה לפיכן. צריך שיודיעו:"],[1,"אילימא","משל בעל הכרי על בעל הכרי:"],[1,"אילימא לדעתיה דיליה","לדעתו של תורם שלא הודיעו לבעל הכרי שהוא תורם עליו:"],[1,"מאן שוייה שליח","הא קיימא לן מה אתם לדעתכם אף שלוחכם לדעתכם:"],[2,"הא קא מהני ליה דעבד שליחותיה","ואיהו הדירו:"],[2,"הא קא מהני ליה","האי שתורם עליו:"],[2,"אלא לאו לדעתיה דנפשיה","שלא הודיע לבעל הכרי שהוא רוצה לתרום עליו:"],[2,"וא\"א צריך דעת הא קמהני ליה","כיון שתורם עליו בידיעתו הא קמהני ליה:"],[2,"אלא לאו אין צריך דעת","ולהכי תורם עליו דכיון שתורם עליו שלא מדעתו לא מהני ליה כלל:"],[3,"לעולם משל בעל הכרי","מיירי ולדעתו דבעל הכרי ודקאמרת הא קמהני ליה דעביד שליחותיה ותרים:"],[3,"באומר כל הרוצ' לתרום יבא ויתרום","דכיון דלא שויה שליח ממש טפי מאחריני ואחריני נמי יכולין לתרום כמותו לא מהני ליה כלל דאי לא תרים ליה האי תרים ליה איניש אחרינא ומהכא ליכא למשמע מינה כלל:"],[4,"טובת הנאה משל מי","אותה פרוטה שיכול לקבל מישראל אחר כדי ליתנה לבן בתו כהן משל מי היא:"],[4,"אי לאו פירי דהאי","דתורם לא מתקן כריא דההוא ותיהוי אותה פרוטה דתורם:"],[4,"או דלמא לא וכו'","ודבעל הכרי הוי טובת הנאה:"],[5,"את כל תבואת זרעך ונתת ונו'","שמע מינה דבעל הכרי היא טובת הנאה מדכתיב זרעך ונתת:"],[6,"תורם את תרומותיו ומעשרותיו לדעתו","של תורם וקס\"ד דמשלו על של בעל הכרי הא קא מהני ליה דשקיל טובת הנאה:"],[6,"אלא","מדתורם לו שמע מינה דטובת הנאה של תורם היא:"],[6,"אמרי","לעולם מהא ליכא למשמע מיניה טובת הנאה של מי דהכא לא מיירי אלא בשל בעל הכרי ולדעתו דבעל הכרי ולהכי טובת הנאה שלו ואפילו הכי לא קא מהני ליה:"],[6,"באומר כל הרוצה בו'","כדאוקימנא לעיל:"],[7,"המקדיש","שפודה את הקדשו מוסיף חומש ולא אדם אחר כדכתיב ואם המקדיש יגאל את ביתו (ויקרא כז):"],[7,"ומתכפר עושה תמורה","המפריש קרבן לפטור חובתו של חבירו המתכפר עושה תמורה באותו קרבן דהשתא הוי דידיה ולא המפרישו דמאחר שהפריש לצורכו קנאו המתכפר:"],[7,"והתורם וכו' טובת הנאה שלו","של תורם:"],[8,"שנוטלין שכר על לימוד המקרא וכו'","ולהכי לא ילמדנו מקרא בחנם לזה דקמהני ליה השכר שהיה לו ליתן אבל מלמדו הלכות בחנם דלא קא מהני ליה כלל:"],[8,"מאי פסקא","דבמנהגא תליא מילתא ולאו איסורא איכא אפי' למשקל שכר של המקרא תריץ לא ודאי לאו שפיר עבד דשקל כלל:"]],[[0,"ותורם תרומתו לדעתו","בגמ' מפרש לדעת מאן:"],[0,"מי אמרינן כיון דזכות הוא לא צריך דעת","דזכין לאדם שלא בפניו וזכיה מטעם שליחות שפיר הוי שליחותא והא דאמרינן בכל דוכתא דזכייה מטעם שליחות מהכא תניא ליה:"],[1,"אילימא","משל בעל הכרי על בעל הכרי:"],[1,"מאן שוייה שליח","ואמאי תורם:"],[2,"אלא לדעתו דבעל הכרי הא קא מהני ליה דעביד שליחותיה","כיון דהוא ידע הוי כמו שמצוהו ואיכא איסורא ודאי אי לאו בדעתו לא הוה איסורא דמשום המצוה שרי אבל לדעתו דבעל [הכרי] מכי ידע ביה הוי כמו שמצוהו והוי שלוחו:"],[2,"הא קא מהני ליה","האי שתורם עליו:"],[2,"אלא לאו אין צריך דעת","והא דאמרינן (בב\"מ כב -) מה אתם לדעתכם אף שלוחכם לדעתכם י\"ל דהיינו כשתורם משל בעל הכרי אבל בתורם משלו אז אין צריך דעת וא\"ת מיהו קשה לרב דההיא דשוקל שקלו אמאי צריך לאוקמא בהפריש ואבד אפי' בלא הפריש ואבד נמי דמצוה קעביד כי הכא צ\"ע מיהו ק\"ק מאי שנא גבי תורם דמצריך דעת לתרום אסור דשליחותיה קא עביד וגבי מחזיר אבידתו או ללמדו תורה אפילו לדעת יהא אסור כיון שאין מצוה לו ושמא יש לומר דבתורם בתרומה דהדבר תלוי בשליחות דאין יכול לתרום בלא דעתו ושייך ביה שליחותיה קעביד טפי מאבידה דמתני' וגם מצוה איכא פורתא למבין:"],[3,"משל בעל הכרי","תימה דהכא משמע כיון דאמר כל הרוצה לתרום לא מהני ליה ובפרק המדיר בכתובות (דף ע:) גבי המדיר אשתו מליהנות לה עד ל' יום יעמיד פרנס ופריך ופרנס לאו שליחותיה קעביד ומשני באומר כל הזן אינו מפסיד ופריך וכי אמר הכי לאו שליחותיה קעביד והתנן מי שהיה מושלך בבור ואמר כל השומע קולו יכתוב גט לאשתו ומשני מי קאמר יזון כל הזן קאמר אלמא דאי אמר כ\"ל השומע יזון שייך למימר שליחותיה קעביד ויש לומר כל השומע משמע לשון שליחות ציווי אבל כל הרוצה אינו לשון ציווי כ\"א מי שיחפוץ יתרום ור\"י אמר דודאי התם הוא דמיתסר אם אמר יזון דשליחותיה קעביד דקא מהני ליה שזן אשתו ומוותר לה פרנסה דמצוה לפרנס אשתו אבל בשמעתא דתורם משל בעל הכרי ולא משלו ובדין הוא דאיסורא ליכא דאי משום דתורם ליה מצוה קעביד כדמתני ומחזיר לו אבידתו אלא משום דכיון דבתרומה צריך דעת הוי כמו שלוחו דמצווהו לך ותרום וכיון דרבנן הפקיעו תורת השליחות מיניה שפיר עביד וראיה לדבר דאמרינן לעולם משל בעל הכרי וכדרבא ול\"ק לעולם משלו וכדרבא אלא ש\"מ דמשלו אפי' אומר כל הרוצה איסורא איכא כי ההיא דהמדיר שהמפרנס מפרנס אשתו משלו:"],[3,"כל הרוצה","אפילו אחר מצי תרים ליה הלכך דעת איכא שליחותא ליכא:"],[4,"טובת הנאה של מי","שיתן לו ישראל אחר דינר כדי שיתן לבן בתו כהן:"],[4,"או דלמא לא וכו'","ודבעל הכרי הוי טובת הנאה:"],[6,"איתיביה תורם תרומותיו לדעתו","קס\"ד השתא כדפירש לעיל משלו על של בעל הכרי קאמר וא\"צ דעת ואי אמרת טובת הנאה של בעל הכרי מהני ליה בתרומה זו שוה דינר שיתן לו ישראל. הכא במאי עסקינן דאמר כל הרוצה לתרום יבא ויתרום ומיירי דתורם משל בעל הכרי על של בעל הכרי:"],[6,"תורם את תרומותיו ומעשרותיו לדעתו","של תורם וקס\"ד דמשלו על של בעל הכרי הא קא מהני ליה דשקיל טובת הנאה:"],[6,"אלא","מדתורם לו שמע מינה דטובת הנאה של תורם היא:"],[6,"אמרי","לעולם מהא ליכא למשמע מיניה טובת הנאה של מי דהכא לא מיירי אלא בשל בעל הכרי ולדעתו דבעל הכרי ולהכי טובת הנאה שלו ואפילו הכי לא קא מהני ליה: באומר כל הרוצה בו': כדאוקימנא לעיל:"],[7,"","המקדיש בהמה על מנת שיתכפר בו חבירו המקדיש מוסיף חומש דחומש תלאו הכתוב במקדיש דכתיב ואם המקדיש יגאל את ביתו ומתכפר עושה תמורה ובפ\"ק דתמורה (דף י.) מפרש טעמא מקרא:"],[7,"","והתורם משלו על של חבירו טובת הנאה שלו:"]]],[["הא קא משמע לן דאפילו במקום שנוטלין שכר על המקרא שרי למשקל על המדרש לא שרי למשקל","מאי שנא מדרש דלא דכתיב (דברים ד, יד) ואותי צוה ה' בעת ההיא ללמד אתכם וכתיב (דברים ד, ה) ראה למדתי אתכם חוקים ומשפטים כאשר צוני ה' מה אני בחנם אף אתם נמי בחנם מקרא נמי בחנם","רב אמר שכר שימור ורבי יוחנן אמר שכר פיסוק טעמים","תנן לא ילמדנו מקרא בשלמא למאן דאמר שכר פיסוק טעמים היינו דלא ילמדנו אלא למאן דאמר שכר שימור גדול בר שימור הוא בקטן קתני","אי בקטן אימא סיפא אבל מלמד את בניו מקרא קטן בר בנים הוא חסורי מחסרא והכי קתני לא ילמדנו מקרא בקטן אם היה גדול מלמדו לו ולבניו מקרא","מיתיבי תינוקות לא קורין בתחילה בשבת אלא שונין בראשון בשלמא למאן דאמר שכר פיסוק טעמים היינו דאין קורין בתחילה בשבת אלא למאן דאמר שכר שימור אמאי אין קורין בתחילה בשבת ואמאי שונין בראשון הא איכא שכר שימור דשבת","וליטעמיך שכר פיסוק בשבת מי אסור הבלעה היא והבלעה מישרא שרי דתניא השוכר את הפועל לשמור את התינוק לשמור את הפרה לשמור את הזרעים אין נותנין לו שכר שבת לפיכך"],[[0,"והא קא משמע לן","מתני' דאפי' במקום שנוטלין שכר וכו'. ולהכי לא ילמדנו מקרא דהואיל ושרי למשקל שכר אם מלמדו בחנם מהני ליה מן השכר שהיה לו ליתן:"],[2,"רב אמר","מאי טעמא התירו למשקל שכר מן המקרא מפני שאין נוטלין שכר אלא על שכר שימור שמשמרין התינוקות שאין מניחין אותן לצאת ולעסוק בדברים בטלים ולא שכר לימוד המקרא וקטנים דצריכין שימור למדין מקרא ולא גדולים ולהכי לא ילמדנו מקרא לקטנים בחנם דהואיל ושרי למשקל עלייהו שכר קמהני השכר שהיה לו ליתן אבל מלמדו מדרש דקטנים אין לומדים מדרש אלא לגדולים וגדולים לית להו שכר שימור ולא קמהני להו כלל ולהכי שרי:"],[2,"ורבי יוחנן אומר שכר פיסוק טעמים","שקיל מנייהו שמלמדם ניקוד וטעמים וההוא שכר מצי למשקל ופיסוק טעמים אינו אלא במקרא ולהכי לא ילמדנו מקרא:"],[3,"בקטן","(משום דקא מהני ליה שמניח לו את השכר) תריץ מתני' דקתני לא ילמדנו מקרא בקטן משום דקא מהני ליה שמניח לו את השכר שהיה לו ליתן:"],[4,"והכי קתני לא ילמדנו מקרא לקטן","בחנם משום דקא מהני ליה שכר השימור אבל אם היה גדול מלמדו לו ולבניו מקרא גדול משום דאיהו לא צריך שימור ולא קמהני ליה ולבניו נמי הואיל ואביהן עמהם הוא משמרם וליכא שכר שימור:"],[5,"לא קורין בתחילה בשבת","אין מתחילין ללמדם בתחילה בשבת בדבר שלא למדו מעולם אבל שונין בראשון כלומר בדבר שלמדוהו כבר פעם ראשונה לומדים אותן פעם שניה בשבת ולהכי קתני בראשון דרבותא קמ\"ל אע\"פ שלא למדוהו התינוקות אלא פעם אחת שונין:"],[5,"בשלמא למאן דאמר שכר פיסוק טעמים","שרי למשקל:"],[5,"הייינו דאין קורן בתחילה בשבת","דהואיל ומעולם לא למדו דבר זה אלא עכשיו אינו מלמדו אלא בשכר ואתי למשקל שכר בשבת אבל שונין דעביד ליה בלא שכר:"],[5,"אמאי שונין בראשון","אפילו שונין לא דהא איכא שכר שימור דשבת ואתי למשקל שכר בשבת:"],[6,"הבלעה היא","כדקתני ומישרי שרי:"],[6,"דתניא השוכר את הפועל","שנותן לי שכרו של כל יום:"],[6,"לשמור את התינוק","מטומאה:"],[6,"לשמור את הזרעים","לצורך העומר:"]],[[0,"הא קמ\"ל דאפילו במקום שנוטלין שכר על המקרא וכו'","מפרש ואזיל טעמא דמה אני בחנם דכתיב ראה למדתי אתכם ומסתמא משה לא נטל שכר מישראל שעשיר היה:"],[2,"שכר שימור","שמשמר מלמד תינוקות שלא ילכו אנה ואנה אבל מדרש אינו צריך ללמוד כ\"א לגדול שאינו צריך שימור כבן עשר למשנה:"],[2,"שכר פיסוק טעמים","וסבר דפיסוק אינו צריך אלא מדרבנן ולא שייך לומר מה אני בחנם אף אתם בחנם:"],[3,"גדול בר שימור הוא","משמע ליה דמתניתין מיירי אף בגדולים:"],[4,"חסורי מיחסרא והכי קתני","וה\"פ לא ילמדנו מקרא ברגיל ללמוד מקרא דהיינו קטן אבל מלמד הוא בניו מקרא אם ראוי לבנים:"],[5,"אין קורין בתחלה בשבת","מפני עונג שבת:"],[5,"אבל שונין בראשון","פירוש יכולין לחזור חזרה ראשונה בשבת:"],[5,"היינו דאין קורין בתחילה","מפני שמשתכר בשבת ומחזי כמקח וממכר אבל שונין בראשון דכיון דלימדו זו מערב שבת יודעין אותו מערב שבת:"],[5,"ואי משום שכר שימור אמאי שונין בראשון","הא איכא שכר שימור:"],[6,"הבלעה היא","ששכר שבת נבלע ולא מיחזי כמקח וממכר שפוסק לו כך לחצי שנה:"],[6,"לשמור את התינוק","לצורך מי חטאת:"],[6,"לשמור הזרעים","לצורך עומר ושתי הלחם בשביעית אם שוכר ליומי אין נותנין לו שכר דמיחזי כמקח וממכר אם היה נוטל:"]]],[["אם אבדו אינו חייב באחריותן ואם היה שכיר שבת שכיר חדש שכיר שנה שכיר שבוע נותן לו שכר שבת לפיכך אם אבדו חייב באחריותן","אלא גבי שבת היינו טעמא דאין קוראין בתחילה משום דיפנו אבהתהון דינוקי למצותא דשבתא ואיבעית אימא משום דבשבתא אכלין ושתין ויקיר עליהון עלמא כדאמר שמואל שינוי וסת תחילת חולי מעיים","ולמאן דאמר שכר פיסוק טעמים מאי טעמא לא אמר שכר שימור קסבר בנות מי קא בעיין שימור","ולמאן דאמר שכר שימור מאי טעמא לא אמר שכר פיסוק טעמים קסבר (שכר) פיסוק טעמים דאורייתא הוא","דאמר רב איקא בר אבין אמר רב חננאל אמר רב מאי דכתיב (נחמיה ח, ח) ויקראו בספר תורת האלהים מפורש ושום שכל ויבינו במקרא ויקראו בספר תורת האלהים זה מקרא מפורש זה תרגום ושום שכל אלו הפסוקים ויבינו במקרא זה פיסוק טעמים ואמרי לה אלו המסורות","אמר רבי יצחק מקרא סופרים ועיטור סופרים וקריין ולא כתיבן וכתיבן ולא קריין הלכה למשה מסיני","מקרא סופרים אָרֶץ שָׁמַיִם מִצְרַיִם","עיטור סופרים אחר תעבורו (בראשית יח, ה) אחר תלכו (בראשית כד, נה) אחר תאסף (במדבר יב, יד) קדמו שרים אחר נוגנים (תהלים סח, כו) צדקתך כהררי אל (תהלים לו, ז)","קריין ולא כתיבן פרת דבלכתו (שמואל ב ח, ג) איש דכאשר ישאל איש בדבר האלהים (שמואל ב טז, כג) באים דונבנתה (ירמיהו לא, לח) לה דפליטה (ירמיהו נ, כט) את דהגד הוגד (רות ב, יא) אלי דהגורן (רות ג, ה) אלי דהשעורים (רות ג, יז) הלין קריין ולא כתבן","וכתבן ולא קריין נא דיסלח (מלכים ב ה, יח)"],[[0,"אם אבדו","בשבת:"],[0,"אינו חייב באחריותן","הואיל ואינו שכיר ביום שבת:"],[0,"אם היה שכיר שבת","שנותנים לו ז' פשיטים שכרו לשבוע אע\"פ שמגיע ליום שבת פשוט אחד כיון דכל יום שבת נבלע עם שכירות שאר השבוע זו היא הבלעה ששכר שבת מבליע בתוך ימי השבוע נותנין שכר שבת דהבלעה שרי:"],[0,"אם אבדו","בשבת חייב באחריותן דהא נותנין לו שכר השבת:"],[1,"אלא גבי שבת","דקתני לא קורין בתחילה אבל שונין לאו משום שכר פיסוק ולא משום שכר שימור קאמר דהא שרי בהבלעה:"],[1,"דיפנו אבהתהון דינוקא למצוותא דילהון","שאם היו עסוקין להקרותן בתחילה בדבר חדש היו טרודין בהן ולא היו פנויין למצות שבת להתענג בו אבל שונין הואיל וכבר למדוהו לא מיטרדי בהו:"],[1,"דיפנו","כדי שיהו פנויין:"],[1,"ויקיר להו עלמא","שכבד עליהם ללמוד מפני המאכל ולהכי אין קורין בתחילה בשבת דמצער להו:"],[2,"בנות","שמלמדין אותן תורה מי בעיין שימור אינהו לאו אורחייהו למיפק אבראי דכתיב כל כבודה בת מלך פנימה (תהילים מ״ה:י״ד) וליכא לאוקמא בה שכר שימור:"],[3,"שכר פיסוק טעמים דאורייתא הוא","ולא מצי למשקל עלייהו אגרא:"],[4,"אלו הפסוקים","עד היכן מסיים כל פסוק ופסוק ולהכי קרי להו שום שכל שיכול להשכיל בפסוק בין כל פיסוק ופיסוק:"],[5,"הלכה למשה מסיני","דנקראין הכי:"],[6,"מקרא סופרים ארץ ארץ","כלומר מה שקורין ארץ ארץ דלא כתבינן ההברה דלא כתבינן יו\"ד בין אל\"ף לרי\"ש ובין רי\"ש לצד\"י וכן נמי ארץ דלא כתבינן ב' אלפי\"ן או ה\"א סמוך לאל\"ף ויו\"ד בין רי\"ש לצד\"י וכן שמים דלא כתבינן שאמים אל\"ף בין שי\"ן למ\"ם ובין מ\"ם ליו\"ד וכן מצרים:"],[7,"עיטור סופרים אחר תעבורו","ולא כתיב תעבורו אחד והיינו עיטור שמעטרין הדיבור דהכי משמע יפה:"],[7,"קדמו שרים אחר נוגנים","ולא כתיב אחר נוגנים קדמו שרים:"],[7,"צדקתך כהררי אל","ולא כתיב כהררי אל צדקתך דהכי מסתבר טפי ובדווקא משתעי:"],[8,"איש דכאשר ישאל איש בדבר האלהים","באחיתופל כתיב:"],[8,"באים דונבנתה","[קרי ולא] כתיב:"],[8,"לה דפליטה","שניהן כתובין בירמיהו:"],[8,"את דהגד הוגד אלי","דכולהו הני קריין ולא כתיבן:"],[9,"וכתיבן ולא קריין נא דיסלח","דנעמן:"]],[[0,"שכר שבוע נותנין לו שכר שבת ואם אבדו חייב באחריותן","כדין שומר שכר דמחייב בגניבה ואבידה ואין להקשות חפצי שמים הוא דקבלת שכר לאו חפצי שמים:"],[1,"","אלא היינו טעמא דאין קורין בראשון דיפנו אביהם של תינוקות ולאו משום שכר שבת כלל אלא אפי' כשאביהם של תינוקות מלמדין אותן בחנם שיהיה להם פנאי שיהא פנוים לסעודת שבת ואם יקראו בראשון ישהו שהייה מרובה וה\"ה אם יש להם מלמד בשכר שאסור מהאי טעמא:"],[1,"אבל שונין בראשון","דתו ליכא שהייה כל כך כיון שמלמדים כבר:"],[1,"למצותיה","דשבתות:"],[1,"ואיבעית אימא","טעמא דאין קורין משום דבשבת אוכלים טפי מבחול ויקיר עלייהו עלמא כלומר שכבדין הם מפני שינוי ווסת דאין יכולין לעסוק ולטרוח וללמוד בראשון:"],[2,"בנות מי בעיין שימור","ומתני' סתמא קתני בין בנים ובין בנות ובנות ליכא יוצאניות ולא בעיא שימור א\"כ לא שייך בהן שכר שימור:"],[3,"שכר פיסוק טעמים דאורייתא","ואסור ליטול שכר עליהם:"],[4,"אלו הפסוקים","מקום שהפסוק מסיים שם:"],[4,"ואמרי לה אלו המסורות","מאן דאית ליה פיסוק טעמים לאו דאורייתא מפרש אלו המסורות חסירות ויתירות:"],[6,"מקרא סופרים ארץ ארץ","[שמשתנין] באתנחתא וזקף קטן שמים מצרים:"],[7,"עיטור סופרים","דלכאורה משמע דאחר תעבורו וסבריה ואחר תעבורו וכן אחר תאסף ואחר מסתבר אחר נוגנים ואחר משמע:"],[8,"פרת דבלכתו","להשיב ידו בנהר פרת פרת אינו כתוב ונקרא:"],[8,"איש דכאשר ישאל","פי' כאשר ישאל איש בדבר האלהים איש קרי ולא כתיב:"],[8,"באים דונבנתה","הנה ימים באים ונבנתה באים קרי ולא כתיב:"],[8,"את דהגד הוגד","הגד הוגד לי את אשר עשית:"],[8,"אלי דהגורן","אלי אם לא:"],[9,"נא דיסלח","בנעמן:"]]],[["זאת דהמצוה (דברים ו, א) ידרוך דהדורך (ירמיהו נא, ג) חמש דפאת נגב (יחזקאל מח, טז) אם דכי גואל (רות ג, ט) הלין כתבן ולא קריין","אמר רב אחא בר אדא במערבא פסקין להדין פסוקא לתלתא פסוקין ויאמר ה' אל משה הנה אנכי בא אליך בעב הענן (שמות יט, ט)","אמר רבי חמא ברבי חנינא לא העשיר משה אלא מפסולתן של לוחות שנאמר פסל לך שני לוחות אבנים כראשונים (שמות לד, א) פסולתן שלך יהא","אמר רבי יוסי ברבי חנינא לא ניתנה תורה אלא למשה ולזרעו שנאמר כתב לך (שמות לד, כז) פסל לך (שם, א) מה פסולתן שלך אף כתבן שלך משה נהג בה טובת עין ונתנה לישראל ועליו הכתוב אומר טוב עין הוא יבורך וגו' (משלי כב, ט)","מתיב רב חסדא ואותי צוה ה' בעת ההיא ללמד אתכם (דברים ד, יד) ואותי צוה ואני לכם ראה למדתי אתכם חוקים ומשפטים כאשר צוני ה' אלהי (דברים ד, ה) אותי צוה ואני לכם","ועתה כתבו לכם את השירה הזאת (דברים לא, יט) השירה לחודה למען תהיה לי השירה הזאת לעד בבני ישראל (שם) אלא פילפולא בעלמא","אמר רבי יוחנן אין הקב\"ה משרה שכינתו אלא על גבור ועשיר וחכם ועניו וכולן ממשה גבור דכתיב ויפרוש את האהל על המשכן (שמות מ, יט) ואמר מר (בכורות מד א) משה רבינו פרסו וכתיב עשר אמות ארך הקרש וגו' (שמות כו, טז) אימא דאריך וקטין","אלא מן הדין קרא דכתיב ואתפוש בשני הלוחות ואשליכם מעל שתי ידי ואשברם (דברים ט, יז) ותניא (בבא בתרא יד א) הלוחות ארכן ששה ורחבן ששה ועביין שלשה","עשיר פסל לך (שם, א) פסולתן שלך יהא חכם רב ושמואל דאמרי תרוייהו חמשים שערי בינה נבראו בעולם וכולם ניתנו למשה חסר אחת שנאמר ותחסרהו מעט מאלהים (תהלים ח, ו) עניו דכתיב והאיש משה עניו מאד (במדבר יב, ג)","אמר ר' יוחנן כל הנביאים עשירים היו מנלן ממשה ומשמואל מעמוס ומיונה","משה דכתיב לא חמור אחד מהם נשאתי (במדבר טז, טו) אי בלא אגרא לאפוקי מאן דשקל בלא אגרא אלא דאפילו באגרא דילמא משום דעני הוה אלא מן פסל לך פסולתן יהא שלך","שמואל דכתיב הנני ענו בי נגד ה' ונגד משיחו את שור מי לקחתי וחמור מי לקחתי (שמואל א יב, ג) אי בחנם לאפוקי מאן דשקל בחנם אלא דאפילו בשכר דלמא דעני הוה אלא מהכא ותשובתו הרמתה כי שם ביתו (שמואל א ז, יז) ואמר רבא (ברכות י ב) כל מקום שהלך ביתו עמו","אמר רבא גדול מה שנאמר בשמואל יותר משנאמר במשה דאילו במשה רבינו כתיב לא חמור אחד מהם נשאתי דאפילו בשכר ואילו גבי שמואל אפילו ברצון לא שכרו דכתיב (שמואל א יב, ד) ויאמרו לא עשקתנו ולא רצותנו וגו'","עמוס דכתיב ויען עמוס ויאמר אל אמציה לא נביא אנכי ולא בן נביא אנכי כי בוקר אנכי ובולס שקמים (עמוס ז, יד) כדמתרגם רב יוסף ארי מרי גיתי אנא ושקמין לי בשפלתא וגו' (ת\"י)","יונה דכתיב ויתן שכרה וירד בה (יונה א, ג) ואמר ר' יוחנן שנתן שכרה של ספינה כולה אמר ר' רומנוס שכרה של ספינה הויא ד' אלפים דינרי דהבא","ואמר ר' יוחנן בתחילה היה משה למד תורה ומשכחה עד שניתנה לו במתנה שנאמר ויתן אל משה ככלתו לדבר אתו (שמות לא, יח)","\u0001מתני׳\u0002 וזן את אשתו ואת בניו אף על פי שהוא חייב במזונותן ולא יזון את בהמתו בין טמאה בין טהורה רבי אליעזר אומר זן את הטמאה ואינו זן את הטהורה אמרו לו מה בין טמאה לטהורה אמר להו שהטהורה נפשה לשמים וגופה שלו וטמאה"],[[0,"זאת המצוה","כתיב בירמיה:"],[0,"ידרוך דהדורך","כתיב וקראי לא גרס להו ידרוך דכתבן ולא קריין:"],[0,"דכי גואל אתה","ברות:"],[0,"חמש דפאת נגב","וטעמייהו לא מפרש ליה:"],[4,"ללמד אתכם","אלמא הקב\"ה צוה ליתנה לישראל:"],[5,"כתבו לכם","אלמא שניתנה נמי להן לישראל:"],[5,"למען תהיה לי לעד","שילמדו כל התורה וילמדו אותה אלמא לישראל נמי ניתנה:"],[5,"פלפולא בעלמא","להבין דבר מתוך דבר הוא דניתן למשה ונוהג בה טובת עין ונתנה לישראל:"],[6,"פירסו","מכלל דגבור הוא וגוף גדול:"],[6,"ואימא דאריך היה וקטין","שלא היה גופני ולא היה בעל כח:"],[7,"ועוביין שלש","ואפי' הכי שיברן:"],[8,"ותחסרהו מעט","וזו היא אחת שאותה אחת היה הקב\"ה יתירה עליו:"],[10,"אי בלא אגרא","מאי רבותיה:"],[10,"לאפוקי ממאן דשקל בלא אגרא","כל מי שהוא רוצה חמורו של חבירו בלא שכר ומאי מעליותא היא דלא הוה גזלן כ\"ע נמי לא גוזלין נינהו:"],[11,"דלמא","האי דלא שקיל אפי' באגרא לאו משום עושר דלמא משום דעני הוה ולא הוו ליה משואות ולהכי לא הוה צריך:"],[11,"אלא מהכא","שמעינן דעשיר היה מפסל לך:"],[11,"ביתו עמו","כלי תשמישו וזה היה מרוב עושר:"],[12,"לא חמור אחד מהם נשאתי","בעל כרחו אפי' בשכר הא ברצון בעלים היה שוכר ואילו גבי שמואל וכו' לא עשקתנו ולא רצותנו שלא היה שוכר לא באונס ולא ברצון:"],[16,"מתני' וזן את אשתו ואת בניו","של מודר:"],[16,"אע\"פ","שהמודר חייב במזונותן כיון דלאו לפטומי עבידן ודי להן במאי שהוא מפרנסן לאו הנאה מרובה עביד ליה:"],[16,"ולא יזון את בהמתו בו'","הואיל ולפטומי עבידן עביד ליה הנאה מרובה:"],[16,"נפשה לשמים וגופה שלו","לאכילה משום הכי לא יזון אותה לפטומי שמהנהו הנאה מרובה:"]],[[0,"זאת דהמצוה","פרשה ואתחנן ואינו כך בשום חומש:"],[0,"ידרוך הדורך","בירמיה:"],[0,"צדקתך כהררי אל","ולא קרי כהררי אל צדקתך וי\"א הוי\"ו מוצדקתך שאמר אנחנו וצדקתך:"],[4,"[אותי צוה]","הכי אמר משה לישראל אותי צוה ואני לכם:"],[5,"למען תהיה השירה הזאת לעד בבני ישראל","ואי בשירה לחוד מאי עדות איכא:"],[5,"אלא פלפולא בעלמא","שיטת חריפות והבינה נמסר למשה רבינו ונהג טובת עין ואמר משה כו':"],[6,"[וכתיב עשר אמות אורך הקרש]","אלמא ארוך היה וכיון דהיה ארוך גבור היה:"],[7,"עביין ג'","והוצרך לחבטן בקרקע בכח גדול:"],[10,"אי בלא אגרא","מי הוא דשקיל בלא אגרא ומאי רבותא אלא אפילו באגרא לא שקיל דעשיר היה:"],[10,"דלמא משום דעני היה","ולא היה רוצה לשכור מהם:"],[11,"ביתו עמו","כלי תשמישו עמו ואינו נהנה משל אחרים:"],[12,"דאילו במשה כתיב לא חמור אחד מהם נשאתי","בעל כרחייהו מכלל דברצון שכרה ושמא לא היו רוצים ובושים לסרב מלהשכיר ואילו בשמואל כתיב רצותי משמע לא בקשתי לשכור ממנו ואפילו בריצוי:"],[16,"וזן את אשתו ובניו","אי אתיא כחנן ניחא דמבריח ארי בעלמא הוא וכי אתיא נמי כרבנן ניחא שפיר דמיירי הכא ממזונות יתירות ואין נפרע [מבעלה] דכי פליגי רבנן היינו במפרנס סתם אע\"פ שלא פי' לשם הלואה מ\"מ לשם מתנה לא יהיב והוי לרבנן כמו יורד לתוך שדה חבירו שלה ברשות דנוטל מה שהשביח וחנן מחלק בין השביח להיכא דלא הוה אלא מבריח ארי מנכסי חבירו א\"כ אם נותן מתנה לאשה דין הוא שאין יכול לתבוע לבעל כלום והכא מיירי שנותן מתנה לאשה ממכירי הבעל:"],[16,"לא יזון את בהמתו בין טמאה בין טהורה","משום דלפטומא עבידא והוי הנאה גמורה שנהנה זו מגופה וזו מפירה:"],[16,"אמר להם כו'","שהטמאה נפשה וגופה לשמים שאינה יכולה ליהנות אלא בעוד נפשה בה הלכך לאו הנאה היא אבל טהורה נפשה לשמים כלומר אע\"פ שנפשה לשמים גופה שלו לשחיטה:"]]],[["נפשה וגופה לשמים אמרו לו אף הטמאה נפשה לשמים וגופה שלו שאם ירצה הרי הוא מוכרה לנוכרים או מאכילה לכלבים:","\u0001גמ׳\u0002 אמר רב יצחק בר חנניה אמר רב הונא המודר הנאה מחבירו מותר להשיא לו בתו הוי בה רבי זירא במאי עסקינן אילימא בשנכסי אבי כלה אסורין על החתן הרי מוסר לו שפחה לשמשו","אלא ב[ש]נכסי חתן אסורין על אבי כלה גדולה מזו אמרו זן את אשתו ואת בניו ואף על פי שהוא חייב במזונותן ואת אמרת מותר להשיא לו בתו","לעולם בשנכסי אבי כלה אסורים על החתן ובבתו בוגרת ומדעתה","תניא נמי הכי המודר הנאה מחבירו אסור להשיא לו בתו אבל משיאו בתו בוגרת ומדעתה","אמר רבי יעקב המדיר בנו לתלמוד תורה מותר למלאות לו חבית של מים ולהדליק לו את הנר רבי יצחק אמר לצלות לו דג קטן אמר רבי ירמיה אמר רבי יוחנן המודר הנאה מחבירו מותר להשקותו כוס של שלום מאי ניהו הכא תרגימו כוס של בית האבל במערבא אמרי כוס של בית המרחץ:","ולא יזון את בהמתו בין כו': תניא יהושע איש עוזא אומר זן עבדיו ושפחותיו הכנענים ולא יזון את בהמתו בין טמאה בין טהורה מאי טעמא עבדיו ושפחותיו הכנענים למנחרותא עבידן בהמה לפטומא עבידא:","\u0001מתני׳\u0002 המודר הנאה מחבירו ונכנס לבקרו עומד אבל לא יושב ומרפאו רפואת נפש אבל לא רפואת ממון:"],[[0,"נפשה וגופה לשמים","שאינה ראויה לאכילה לפיכך זן אותה דאינו מהנהו הנאה מרובה:"],[0,"מוכרה לעובדי כוכבים","וניחא ליה בפיטומא:"],[1,"גמ' על החתן","שהחתן הוי מודר:"],[1,"הרי מוסר לו שפחה לשמשו","ואמאי מותר:"],[2,"אלא בשנכסי חתן אסורין אצל אבי הכלה","ואע\"פ שהחתן מהנהו שזן את בתו אפי' הכי משיא לו את בתו ומשיב הש\"ס משום הא לא צריך למימר דמותר להשיא את בתו:"],[2,"דגדולה מזו אמרו","בשנכסיו אסורים על הנודר אמרנו וזן את אשתו:"],[2,"אע\"פ וכו' ואת אמרת וכו'","פשיטא דמותר דהא לא מהני כלל:"],[3,"לעולם בשנכסי אבי כלה אסורין על החתן","ודקאמרת הרי מוסר לו שפחה לשמשו תריץ בבתו בוגרת עסקינן שיכול להשיאו ומדעת עצמה דהואיל ואינו משיא אלא מדעת עצמה לאו הנאה דקא מהני ליה איהו אלא הנאה מועטת:"],[4,"תניא נמי הכי","דהנאה מועטת מותרת:"],[5,"המדיר את בנו","מנכסיו אם לא ילמוד תורה:"],[5,"מותר","האב למלאות כו' שהנאה מרובה נדר הימנו ולא הנאה מועטת וזו הנאה מועטת היא:"],[5,"כוס של בית המרחץ","הנאה מועטת היא:"],[6,"למנחרותא עבידן","לצורך עבודה עשויין ולא להתפטם:"],[6,"למנחרותא","לעבודתו והואיל וקי\"ל יכול הרב לומר לעבד עשה עמי ואיני זנך אינה הנאה למודר אם זה מפרנס עבדיו:"],[6,"לפטומא עבידא","דטהורה לשחיטה וטמאה לעובד כוכבים:"],[7,"המודר הנאה מחבירו נכנס לבקרו עומד אבל לא יושב","כדמפרש לקמן:"]],[[1,"הרי מוסר שפחה לשמשו","דס\"ד דאיירי בקטנה שניסת על ידו ואת אמרת דמותר להשיא בתו הא פשיטא דאסור:"],[3,"בבתו בוגרת דמדעתה","וקמ\"ל אף על גב שהוא מדבר עמה ומשיא עצה לה להנשא לו הנאת דבור לא מקרי הנאה:"]]],[["\u0001גמ׳\u0002 במאי עסקינן אי בשנכסי מבקר אסורין על חולה אפילו יושב נמי אי בשנכסי חולה אסורין על המבקר אפילו עומד נמי לא אמר שמואל לעולם בשנכסי מבקר אסורין על החולה ובמקום שנוטלין שכר על הישיבה ואין נוטלין שכר על העמידה","מאי פסקא הא קא משמע לן דאף במקום שנוטלין שכר על הישיבה בעי למשקל על העמידה לא בעי למשקל ואיבעית אימא כדרבי שמעון בן אליקים גזירה שמא ישהא בעמידה הכא נמי גזירה שמא ישהא בישיבה","עולא אמר לעולם בשנכסי חולה אסורין על המבקר וכגון דלא אדריה מן חיותיה אי הכי אפילו יושב נמי הא אפשר בעמידה","מיתיבי חלה הוא נכנס לבקרו חלה בנו שואלו בשוק בשלמא לעולא דאמר בשנכסי חולה אסורין על המבקר וכגון דלא אדריה מן חיותיה שפיר","אלא לשמואל דאמר בשנכסי מבקר אסורין על החולה מאי שנא הוא ומאי שנא בנו אמר לך מתניתין בשנכסי מבקר אסורין על החולה ברייתא בשנכסי חולה אסורין על המבקר","מאי פסקא אמר רבא (אמר) שמואל"],[[0,"במאי עסקינן","נכנס לבקרו:"],[0,"אפילו יושב נמי","יהא מותר שהרי נכסי חולה אין אסורין על המבקר ומותר ליהנות משלו:"],[0,"אי בשנכסי כו'","ולהכי אינו יושב בישיבה שלא יהנה משלו:"],[0,"אפי' עומד לא","דהנאה היא לו שנהנה:"],[0,"ובמקום שנוטלין שכר על הישיבה","שכר שהולך לבקר את החולה ויושב עמו לצוותא ומשכירין אותו:"],[0,"ואין נוטלין על העמידה","ולהכי אינו יושב שאם היה יושב שם המבקר בחנם מוותר היה לו שכרו ומהנהו אם לא יטול שכר אבל עומד הואיל ואין נוטלין שכר על העמידה מותר:"],[1,"מאי פסקא","דעל זה נוטלין שכר ולא על זה:"],[1,"על העמידה לא בעי למשקל","דעראי הוא דכך הוא בכל מקום ולהכי עומד אבל לא יושב דכיון דליכא שכר [על העמידה] לא מהני ליה כלל:"],[1,"ואיבעית אימא","לעולם בשנכסי מבקר אסורין על החולה ואפילו במקום שאין נוטלין שכר על הישיבה ודקאמרת אפי' יושב נמי כדקאמר רבי שמעון בן אליקים לקמן (נדרים דף מב:) לענין שביעי':"],[1,"גזירה שמא ישהא בעמידה הכא נמי שמא ישהא בישיבה","ושהייה דישיבה ודאי הנאה היא לחולה ולהכי לא ישב עמו ואי קשיא אפילו עומד נמי לא גזירה שמא ישהא בעמידה הא לא קשיא דהתם כיון דאכל מפירי דשדה איכא למימר דלמא אגב דאכיל שהייה תמן אע\"ג דקאי והכא דלא אכל משום הכי קאי: (לא מצאתי יותר מזה הלשון וזהו אמר ליה):"],[1,"אפילו יושב נמי","להוי דהא מבקר מותר בנכסי חולה:"],[1,"אפילו עומד","דהא אסור בדריסת הרגל:"],[1,"לעולם בשנכסי מבקר אסורין על החולה","ומשום הכי עומד אבל לא יושב כדמפרש בגמרא:"],[1,"במקום שנוטלין שכר על הישיבה","דהיושב לפני החולה משתכר פורתא משום דקעביד ליה צוותא בעלמא והלכך בישיבה אסור משום דקא מהני ליה ההוא אגרא דניתיב לאיניש אחרינא דיתיב קמיה:"],[1,"אבל בעמידה דמותר","משום דלא קמהני ליה ולא מידי דהא לא עביד למיתב אגרא אעמידה:"],[1,"מאי פסקא","הא קמ\"ל אע\"ג דאיכא דוכתא שנוטלין שכר על הישיבה נוטלין אבל לא על העמידה והיינו טעמא דבעמידה מותר אבל לא בישיבה כדאמר ר\"ש בן אליקים בשילהי פירקין גבי שביעית:"],[1,"","(חס\"ר כא\"ן)"],[1,"שהרי עומד ואוכל","גזירה שמא ישהא בישיבה מרובה והוי הנאת חולה וא\"ת נגזור בעמידה כי היכי דגזרינן התם בעמידה הא לא קשה דאילו התם גזרי' בעמידה אבל הכא דלא מטיא ליה הנאה בעמידה ליכא למיגזר שמא ירבה בעמידה אבל לא בישיבה שנוח לו לזה לישב גזירה שמא ישהא בישיבה:"],[2,"לעולם בשנכסי חולה אסורין על המבקר","וכשאין נוטלין שכר על העמידה ולהכי מותר בעמידה דהא לאו מן חיותיה נדר כדאמר לקמן כל המבקר את החולה גורם לו שיחיה ואהכי מותר:"],[2,"הא אפשר בעמידה","מבקרו בעמידה דמהא לא אדריה אבל בישיבה אדריה:"],[3,"חלה הוא","המדיר מותר לבקרו:"],[3,"חלה בנו","מודר שואלו בשוק על עסקי בנו:"],[3,"היינו דשני בין הוא לבנו","דאילו בשחלה הוא מותר ליכנס לשם דהא לא אדריה מן חיותיה אבל כשחלה בנו אינו נכנס לבקרו דהא ליכא חיותא דמדיר:"],[4,"אלא לשמואל דאמר כו' מאי שנא הוא","דמותר ומ\"ש בנו דאסור הא בעמידה ליכא הנאה כלל אלא ודאי בנכסי חולה אסורין על המבקר מיירי וכדעולא וקשיא לשמואל:"],[4,"אמר לך שמואל כו' וברייתא","מודינא דהכי הוא כדמוקי לה עולא בשנכסי חולה אסורין על המבקר מיהו בהא פליגנא עליה דאיהו מוקי לה בעומד אבל לא ביושב דהא אפשר בעמידה ואנא אמינא דברייתא אפי' יושב שפיר דמי דאמר דלא אדריה מן חיותיה ל\"ש עומד ול\"ש יושב ודיקא נמי מדקתני סתמא חלה הוא נכנס לבקרו אפי' יושב:"],[5,"מאי פסקא","דמתני' בשנכסי מבקר אסורין על החולה:"]],[[0,"אפי' עומד","דקא מתהני מדריסת הרגל:"],[0,"במקום שנוטלין שכר על הישיבה","לכך אסור לבקר בחנם אבל בעמידה דאין נוטלין שכר עליה מותר בחנם דמצוה קעביד:"],[1,"על העמידה לא בעי למשקל","כיון דמצוה הוא ויש לו לעשות בחנם - על הישיבה בעי למשקל ואסור לעשות לו בחנם:"],[2,"דלא אדריה מחיותיה","כלומר היינו טעמא דעומד ואע\"ג דאדריה מן ביתיה לא היה דעתו לאסור עליו ביתו לבא כאן בשביל חיותו לבקרו:"],[2,"אפשר בעמידה","והלכך בישיבה לא הוי חיותא שאפשר למבקר להיות בעמידה:"],[3,"חלה בנו שואלו בשוק","דאסור ליכנס בביתו [כיון שהדירו] וס\"ד דברייתא מתפרשת כפי' דמתני':"],[3,"בשלמא לעולא ניחא","דשרי לבקרו הוא ולבנו אסור אחיותיה דבנו אדרה אלא לשמואל כי היכי דלאביו שרי בעמידה ה\"נ בנו מותר בעמידה:"],[5,"פסקת","הדבר [דמתני' בשנכסי] מבקר אסור וברייתא כשחולה אסור הוה ליה לשנות התנא הברייתא בענין דמתניתין:"]]],[["מתניתין קשיתיה מאי איריא דתני עומד אבל לא יושב שמע מינה דנכסי מבקר אסורין על החולה","אמר ריש לקיש רמז לביקור חולין מן התורה מנין שנאמר (במדבר טז, כט) אם כמות כל האדם ימותון אלה ופקודת כל אדם וגו' מאי משמע אמר רבא אם כמות כל האדם ימותון אלה שהן חולים ומוטלים בעריסתן ובני אדם מבקרים אותן מה הבריות אומרים לא ה' שלחני לזה","דרש רבא (במדבר טז, ל) אם בריאה יברא ה' אם בריאה גיהנם מוטב תהיה אם לאו יברא ה'","איני והא תניא שבעה דברים נבראו קודם שנברא העולם אלו הן תורה ותשובה גן עדן וגיהנם כסא הכבוד ובית המקדש ושמו של משיח","תורה דכתיב (משלי ח, כב) ה' קנני ראשית דרכו וגו'","תשובה דכתיב (תהלים צ, ב) בטרם הרים יולדו ותחולל וגו' (תהלים צ, ג) תשב אנוש עד דכא וגו'","גן עדן דכתיב (בראשית ב, ח) ויטע ה' אלהים גן בעדן מקדם וגו'","גיהנם דכתיב (ישעיהו ל, לג) כי ערוך מאתמול תפתה","כסא כבוד דכתיב (תהלים צג, ב) נכון כסאך מאז","בית המקדש דכתיב (ירמיהו יז, יב) כסא כבוד מרום מראשון","שמו של משיח דכתיב (תהלים עב, יז) יהי שמו לעולם וגו'","אלא הכי קאמר אי איברי ליה פומא מוטב ואם לא יברא ה' והכתיב (קהלת א, ט) אין כל חדש תחת השמש הכי קאמר אי הכא לא מקרב פומא להכא ליקרב","דרש רבא ואמרי לה אמר רבי יצחק מאי דכתיב (חבקוק ג, יא) שמש ירח עמד זבולה שמש וירח בזבול מאי בעיין והא ברקיע קביעי מלמד שעלו שמש וירח מרקיע לזבול ואמרו לפניו רבונו של עולם אם אתה עושה דין לבן עמרם אנו מאירים ואם לאו אין אנו מאירין","באותה שעה ירה בהן חיצים וחניתות אמר להם בכל יום ויום משתחוים לכם ואתם מאירים בכבודי לא מחיתם בכבוד בשר ודם מחיתם ובכל יום ויום יורין בהן חיצין וחניתות ומאירים שנאמר (חבקוק ג, יא) לאור חציך יהלכו וגו'","תניא ביקור חולים אין לה שיעור מאי אין לה שיעור סבר רב יוסף למימר אין שיעור למתן שכרה אמר ליה אביי וכל מצוות מי יש שיעור למתן שכרן והא תנן (משנה אבות ב א) הוי זהיר במצוה קלה כבחמורה שאין אתה יודע מתן שכרן של מצוות אלא אמר אביי אפילו גדול אצל קטן רבא אמר אפילו מאה פעמים ביום","אמר רבי אחא בר חנינא כל המבקר חולה נוטל אחד משישים בצערו אמרי ליה אם כן ליעלון שיתין ולוקמוה אמר ליה כעישורייתא דבי רבי ובבן גילו","דתניא רבי אומר בת הניזונית מנכסי אחין נוטלת עישור נכסים אמרו לו לרבי לדבריך מי שיש לו עשר בנות ובן אין לו לבן במקום בנות כלום אמר להן ראשונה נוטלת עישור נכסים שניה במה ששיירה שלישית במה ששיירה וחוזרות וחולקות בשוה","רב חלבו חלש נפק אכריז רב כהנא"],[[0,"מתניתין קשיתיה","מדוקיא קא משמע ליה:"],[0,"מאי איריא דתני עומד אבל לא יושב","והרי אין מבקר אסור בנכסי חולה:"],[0,"אלא שמע מינה וכו'","וא\"ת מאי טעמא דשמואל דמתרץ לה הכי לוקמא כדעולא הא לא קשיא דשמואל לא מוקי לה כדעולא דקסבר האי שינויא דחיקא היא:"],[1,"ופקודת כל אדם","שבני אדם מבקרין אותן:"],[1,"לא ה' שלחני לזה","לפי שהיו עדת קרח מלעיגין עליו ואומרים שהיה משה אומר להם מדעתו בלא ציווי של מקום:"],[2,"ואם לאו","שאין גיהנם נברא עדיין:"],[3,"איני","מי מספקא ליה למשה:"],[7,"כי ערוך מאתמול תפתה","איזהו יום שיש לו אתמול ולא שלשום כלומר שהיה לו לפניו ולא לפני פניו הוי אומר זה יום שני שבו נברא גיהנם:"],[11,"אלא ה\"ק","אי הכא אין לו פומא ואי לא מקרב הכא יקריבנו המקום:"],[12,"והא ברקיע קביעי","למטה מזבול כדאמרי' במסכת חגיגה (דף יב:):"],[12,"אם אתה עושה דין לבן עמרם","מקרח ועדתו:"],[13,"ובכל יום ויום","מאותו יום ואילך אינן יוצאין מפני שמשתחווין להם עובדי כוכבים עד שמורים בהן חיצים וחניתות:"],[14,"ואפי' גדול אצל קטן","שלא יאמר לא אבקר אלא גדול כמוני: אין לו שיעור דמצוה בקטן כמו בגדול:"],[15,"ליעיילו שיתין ולוקמוה","יכנסו ששים בני אדם כאחת לבקרו ויטול כל אחד ואחד מששים בצערו ומיד מתרפא:"],[15,"כעישורייתא דבי רבי","דאמר מי שיש לו עשר בנות ובן אחד הראשונה נוטלת עישור נכסים והשניה במה ששיירה וכן לכולן ומפרש בהש\"ס ירושלמי נמצאו בנות שנוטלות במנה תרי תילתי פחות ציבחר והאי תלתא ומוסיף ציבחר וגבי חולה נמי מבקר הראשון נוטל אחד מששים בחליו והשני א' מששים במה ששייר:"],[15,"ובבן גילו","בחור כמותו או זקן לזקן:"],[16,"וחוזרות כולן וחולקו' בשוה","מילתא אחריתי דהיכא דיצאו לישא כאחת כל אחת נוטלת עישורה במה ששיירה חבירת' ואז חולקות בשוה אבל כשבאו לינשא זו אחר זו לא:"]],[[0,"מתניתין קשיתיה","והוזקק להעמידה בשנכסי מבקר אסורים על החולה:"],[1,"ופקודת כל אדם","שב\"א מבקרין אותם:"]]],[["רב חלבו באיש לא איכא דקא אתי אמר להו לא כך היה מעשה בתלמיד אחד מתלמידי ר' עקיבא שחלה לא נכנסו חכמים לבקרו ונכנס ר' עקיבא לבקרו ובשביל שכיבדו וריבצו לפניו חיה א\"ל רבי החייתני יצא ר' עקיבא ודרש כל מי שאין מבקר חולים כאילו שופך דמים","כי אתא רב דימי אמר כל המבקר את החולה גורם לו שיחיה וכל שאינו מבקר את החולה גורם לו שימות מאי גרמא אילימא כל המבקר את החולה מבקש עליו רחמים שיחיה וכל שאין מבקר את החולה מבקש עליו רחמים שימות שימות ס\"ד אלא כל שאין מבקר חולה אין מבקש עליו רחמים לא שיחיה ולא שימות","רבא יומא קדמאה דחליש אמר להון לא תיגלו לאיניש דלא לתרע מזליה מכאן ואילך אמר להון פוקו ואכריזו בשוקא דכל דסני לי ליחדי לי וכתיב (משלי כד, יז) בנפול אויבך אל תשמח וגו' ודרחים לי ליבעי עלי רחמי","אמר רב כל המבקר את החולה ניצול מדינה של גיהנם שנאמר (תהלים מא, ב) אשרי משכיל אל דל ביום רעה ימלטהו י\"י אין דל אלא חולה שנאמר (ישעיהו לח, יב) מדלה יבצעני אי נמי מן הדין קרא (שמואל ב יג, ד) מדוע אתה ככה דל בן המלך בבקר בבקר וגו' אין רעה אלא גיהנם שנאמר (משלי טז, ד) כל פעל י\"י למענהו וגם רשע ליום רעה","ואם ביקר מה שכרו מה שכרו כדאמר ניצול מדינה של גיהנם אלא מה שכרו בעוה\"ז","(תהלים מא, ג) י\"י ישמרהו ויחייהו ואושר בארץ ואל תתנהו בנפש אויביו יי' ישמרהו מיצר הרע ויחייהו מן היסורין ואושר בארץ שיהו הכל מתכבדין בו ואל תתנהו בנפש אויביו שיזדמנו לו רועים כנעמן שריפו את צרעתו ואל יזדמנו לו ריעים כרחבעם שחילקו את מלכותו","תניא ר\"ש בן אלעזר אומר אם יאמרו לך ילדים בנה וזקנים סתור שמע לזקנים ואל תשמע לילדים שבנין ילדים סתירה וסתירת זקנים בנין וסימן לדבר (מלכים א יב, כא) רחבעם בן שלמה","אמר רב שישא בריה דרב אידי לא ליסעוד איניש קצירא לא בתלת שעי קדמייתא ולא בתלת שעי בתרייתא דיומא כי היכי דלא ליסח דעתיה מן רחמי תלת שעי קדמייתא רווחא דעתיה בתרייתא תקיף חולשיה","אמר רבין אמר רב מניין שהקב\"ה זן את החולה שנאמר (תהלים מא, ד) יי' יסעדנו על ערש דוי וגו' ואמר רבין אמר רב מניין שהשכינה שרויה למעלה ממטתו של חולה שנאמר יי' יסעדנו על ערש דוי","תניא נמי הכי הנכנס לבקר את החולה לא ישב לא על גבי מטה ולא ע\"ג ספסל ולא על גבי כסא אלא מתעטף ויושב ע\"ג קרקע מפני שהשכינה שרויה למעלה ממטתו של חולה שנאמר יי' יסעדנו על ערש דוי","ואמר רבין אמר רב מטרא במערבא סהדא רבה פרת ופליגא דשמואל דאמר שמואל נהרא מכיפיה מתבריך ופליגא דשמואל אדשמואל דאמר שמואל אין המים מטהרין בזוחלין"],[[0,"באיש","חלה ואית דגרסי באש:"],[0,"כאילו שופך דמים","מפני שבני אדם שנכנסין לבקרו עושים לו לחולה כל צרכיו:"],[1,"לא שיחיה ולא שימות","שהרי אינו יודע בעניינו של חולה:"],[2,"דלא ליתרע מזליה","דדילמא מתצלנא לאלתר אי נמי דלא לישתעי מילי עילויה:"],[2,"מכאן ואילך","חזי דלא מתרפא אמר להו פוקו ואכריזו:"],[5,"ריעים כנעמן","שריפאוהו מצרעתו כגון אלישע דהוה נביא וזקן והשיאו עצה לנעמן:"],[6,"אם יאמרו לך נערים בנה","בית המקדש:"],[6,"וזקנים אומרים סתור","ואל תבנה:"],[6,"וסימן לדבר מרחבעם","דכתיב (מלכים א י״ב:ח׳) ויעזוב את עצת הזקנים וגו' ונחרב בית המקדש על אותה עצה והמורה לא פירש בבית המקדש ואיכא ברייתא. דקתני בהדיא בבית המקדש:"],[7,"לא לסעוד","כמו (במדבר ט״ז:כ״ט) ופקודת כל האדם מתרגמינן וסעודא:"],[7,"תלת שעי קמייתא רווחא דעתיה","כדאמר בעלמא (ב\"ב טז:) אידלי יומא אידלי קצירא ודילמא אמר לא אצטריך למבעי רחמי עליה דאינו כל כך חולה:"],[8,"יסעדנו","כמו ולחם לבב אנוש יסעד (תהילים ק״ד:ט״ו):"],[8,"ומניין שהשכינה כו' שנאמר ה' יסעדנו","קרי ביה יסערנו אי כמי יסעדנו ממש שמסעד שכינה על ראשו כדאמרן בהדיא ששכינה שרויה למעלה ממיטתו:"],[10,"סהדא רבה פרת","כשנהר פרת גדול הוי עדות לגשמים שיורדין לא\"י דא\"י גבוה מכל הארצות ובאין גשמים ונופלין בפרת ומתגדל מהן והאי דאמרי' דנהר מתגדל ממי הגשמים הוי פלוגתא אדשמואל:"],[10,"נהרא מכיפיה מתברך","שנובע מגדותיו ולא ממי גשמים:"]],[[7,"לסעוד","אם יבקר לחולה. פוקד מתרגמינן וסעד:"],[7,"רווח נפשיה","החולה וסבור המבקר החולה עובר לו חליו ונמנע מלבקש רחמים:"],[7,"בתלת בתרייתא תקיף חולשיה","ומסיח מלבקש רחמים עליו:"],[10,"סהדא רבה פרת","שרבו מימיו מן הגשמים:"]]],[["אלא פרת ביומי תשרי בלבד","אבוה דשמואל עבד להון מקוואות לבנתיה ביומי ניסן ומפצי ביומי תשרי:","אמר ר' אמי אמר רב מאי דכתיב (יחזקאל יב, ג) ואתה בן אדם עשה לך כלי גולה זו נר וקערה"],[[0,"אלא פרת ביומי תשרי בלבד","דכל ימות השנה רבין נוטפין על הזוחלין מן הגשמים שיורדין לתוכו ומן השלגים שמתפשרין כל ימות החמה אבל בתשרי כבר פסקו השלגים ונתפשרו כולן והלכו להן מטהרין הזוחלין ואין בנהרות אלא מימיו שנובעין בלבד:"],[1,"אבוה דשמואל","סבירא ליה כאידך דשמואל:"],[1,"ועביד להו לבנתיה מקוואות ביומי ניסן","לפי שביומי ניסן רבין נוטפין עני הזוחלין מחמת הגשמים שהרי כל השלגים והקרח שנתפשרו באין המים דרך צינורות דהוו להו שאובין אבל לא באין דרך צינורות אלא מאליהן שוטפין ובאין טובלין בהן כדאמר זבה ונדה ויולדת טבילתן במי מקוה של מ' סאה ואפי' מי גשמי' מכונסים שלא מצינו מים חיים אלא לזב בלבד שנאמר בו מים חיים והמפרש לא פירש הכי ולאו דוקא דכל נשים בזמן הזה זבות נינהו:"],[1,"מפצי ביומי תשרי","שבתשרי מתמעטין הנהרות מן כל ימות השנה ומעלין טיט . והיה נותן המפץ בקרקעית הנהר שלא יכנס הטיט ברגליהן ויהא חציצה:"]],[]],[["ושטיח בחוסר כל (דברים כח, מח) אמר ר' אמי אמר רב בלא נר ובלא שלחן רב חסדא אמר בלא אשה רב ששת אמר בלא שמש רב נחמן אמר בלא דעה תנא בלא מלח ובלא רבב","אמר אביי נקטינן אין עני אלא בדעה במערבא אמרי דדא ביה כולא ביה דלא דא ביה מה ביה דא קני מה חסר דא לא קני מה קני","אמר ר' אלכסנדרי אמר ר' חייא בר אבא אין החולה עומד מחליו עד שמוחלין לו על כל עונותיו שנאמר (תהלים קג, ג) הסולח לכל עוניכי הרופא לכל תחלואיכי רב המנונא אמר חוזר לימי עלומיו שנאמר (איוב לג, כה) רוטפש בשרו מנוער ישוב לימי עלומיו כל משכבו הפכת בחליו (תהלים מא, ד) אמר רב יוסף לומר דמשכח למודו","רב יוסף חלש איעקר ליה למודיה אהדריה אביי קמיה היינו דבכל דוכתא אמרינן אמר רב יוסף לא שמיע לי הדא שמעתא אמר ליה אביי את אמריתה ניהלן ומהא מתניתא אמריתה ניהלן","כי הוה גמיר רבי תלת עשרי אפי הילכתא אגמריה לרבי חייא שבעה מנהון לסוף חלש רבי אהדר ר' חייא קמיה הנהו שבעה אפי דאגמריה שיתא אזדו הוה ההוא קצרא הוה שמיע ליה לרבי כדהוה גריס להו אזל ר' חייא וגמר יתהון קמי קצרא ואתא ואהדר יתהון קמי רבי כד הוה חזי ליה רבי לההוא קצרא אמר ליה רבי אתה עשית אותי ואת חייא איכא דאמרי הכי קאמר ליה אתה עשית את חייא וחייא עשה אותי","ואמר ר' אלכסנדרי אמר ר' חייא בר אבא גדול נס שנעשה לחולה יותר מן הנס שנעשה לחנניה מישאל ועזריה של חנניה מישאל ועזריה אש של הדיוט והכל יכולים לכבותה וזו של חולה של שמים היא ומי יכול לכבותה","ואמר ר' אלכסנדרי אמר ר' חייא בר אבא ואמרי לה אמר ר' יהושע בן לוי כיון שהגיע קיצו של אדם הכל מושלים בו שנאמר (בראשית ד, יד) והיה כל מוצאי יהרגני רב אמר מן הדין קרא (תהלים קיט, צא) למשפטיך עמדו היום כי הכל עבדיך","רבה בר שילא אמרו ליה שכיב גברא גבוה הוה רכיב גירדונא זוטרא מטא תיתורא איסתויט שדייה וקא שכיב קרי על נפשיה למשפטיך עמדו היום","שמואל חזייה לההוא (קרוקיתא דעקרבא) יתיבא על אקרוקתא ועברה נהרא טרקא גברא ומיית קרי עליה למשפטיך עמדו היום","אמר שמואל אין מבקרין את החולה אלא למי שחלצתו חמה לאפוקי מאי לאפוקי הא דתניא ר' יוסי בן פרטא אומר משום ר' אליעזר אין מבקרין לא חולי מעיים ולא חולי העין ולא מחושי הראש בשלמא חולי מעיים משום כיסופא אלא חולי העין ומחושי הראש מאי טעמא","משום דרב יהודה דאמר רב יהודה דיבורא קשיא לעינא ומעלי לאישתא אמר רבא האי אישתא אי לאו דפרוונקא דמלאכא דמותא מעלי"],[[0,"ושטיח","עור לאכול עליו:"],[0,"בלא מלח ובלא רבב","דמלפת בהו:"],[0,"רבב","שומן:"],[1,"דדא ביה כולא ביה","מי שיש בו דעת כמי שיש בו הכל שאינו נחסר כלום:"],[1,"דא קני מה חסר","מי שקנה דעת אינו חסר כלום:"],[2,"חוזר לימי עלומיו","דנעשה כתינוק שלא טעם טעם חטא:"],[2,"שנא' רוטפש","כלומר כשעת רטוב ופש כמו [פרו ורבו מתרגמינן] פושו וסגו:"],[2,"מנוער","מן החולי ישוב כמו שהיה בימי עלומיו:"],[2,"כל משכבו הפכת בחליו","כל סדר הצעת למודו המסודר לו נהפך לו בחליו ומשכחו:"],[4,"תליסר אפי הלכתא","שהיה שונה למודו בי\"ג פנים:"],[4,"שיתא אזלו ליה","ששכחם:"],[4,"קצרא","כובס:"],[4,"אתה עשית אותי ואת חייא","דגמר להו דכל המלמד את בן חברו תורה מעלה עליו הכתוב כאילו עשאו שנאמר ואת הנפש אשר עשו בחרן:"],[6,"הכל מושלין בו","להמיתו אפי' זבוב אפילו יתוש:"],[6,"למשפטיך עמדו היום כל עבדיך","דכיון שנשפט בישיבה של מעלה הכל נעשו עבדיו של הקב\"ה ליפרע הימנו:"],[7,"גברא גבוה הוי רכיב גירדנא זוטא","פרדה קטנה:"],[7,"תיתורא","גשר:"],[7,"ואסתויט","נתפחדה הפרדה ושדייה מינה ושכיב ואע\"פ שהפרדה נמוכה ואיהו היה ארוך כל כך דלא נפל אלא מעט מת:"],[8,"אקרוקתא","צפרדע ועקרב אינו יכול לשוט בנהר ונשאו צפרדע עליו להעבירו בנהר לנשוך את האיש:"]],[[0,"שטיח","עור מבושל שאוכלין עליו ונושאין אותו עוברי דרכים עמם:"],[1,"דדא ביה","שיש בו דעה:"],[1,"דא לא קני","דעה מה קני:"],[2,"","הסולח לכל עוניכי הרופא לכל תחלואיכי:"],[2,"חוזר לימי עלומיו","דבריא החולה כשנתרפא יותר מלפני שחלה:"],[4,"תליסר אפי הלכתא","י\"ג פנים של הלכות משנה:"],[4,"אתה עשית את חייא","כלומר למדת לו:"],[6,"למשפטיך","כלומר כשעמדו בריותיך למשפטיך הכל עבדים להביא עליהם מה שצוית:"],[7,"גברא רבה","אדם גדול:"],[7,"גירדגא זוטרא","פרד קטן:"],[7,"איטיוטי","נבעת. כמו קמא טיוטא נקטיה בבא קמא (דף לז:):"],[8,"אקרוקתא","צפרדע:"],[9,"שחלצתו חמה","שהחזיק חמימותו ועדיין הוא חולה:"]]],[["כחיזרא לדיקלי חד לתלתין יומין וכי תירייקי לגופא רב נחמן בר יצחק אמר לא היא ולא תירייקה","אמר רבה בר יונתן אמר רב יחיאל ערסן יפה לחולה לרפואתו מאי ערסן אמר ר' יונתן חושלא דשערי עתיקתא דריש נפיא אמר אביי בעיין בישולא כעין בישרא דתורא רב יוסף אמר סמידי דשערי עתיקתא דריש נפיא אמר אביי בעיין בישולא כבשרא דתורא","א\"ר יוחנן בורדם אין מבקרים ואין מזכירין שמו מ\"ט א\"ר אלעזר מפני שהוא כמעיין הנובע וא\"ר אלעזר למה נקרא שמו בורדם שהוא כמעיין הנובע:","ומרפאהו רפואת הנפש כו': היכי קתני אילימא דרפואת נפש בחנם רפואת ממון בשכר ליתני הכי מרפאהו בחנם אבל לא בשכר אלא רפואת נפש גופו רפואת ממון בהמתו א\"ר זוטרא בר טוביה אמר רב אבל אומר לו סם פלוני יפה לה סם פלוני רע לה:","\u0001מתני׳\u0002 ורוחץ עמו באמבטי גדולה אבל לא בקטנה וישן עמו במטה","ר' יהודה אומר בימות החמה אבל לא בימות הגשמים מפני שהוא מהנהו ומיסב עמו על המטה ואוכל עמו על השולחן אבל לא מן התמחוי אבל אוכל הוא עמו מן התמחוי החוזר:","\u0001גמ׳\u0002 תניא לא ירחץ עמו באמבטי ולא ישן עמו במטה בין גדולה בין קטנה דברי רבי מאיר רבי יהודה אומר גדולה בימות הגשמים וקטנה בימות החמה מותר רוחץ עמו באמבטי גדולה ומזיע עמו בקטנה אבל מיסב עמו על המטה ואוכל עמו על השולחן אבל לא מן התמחוי אבל אוכל הוא מן התמחוי החוזר א\"ר יוסי בר חנינא מן התמחוי החוזר לבעה\"ב:","\u0001מתני׳\u0002 לא יאכל עמו מן האבוס שלפני הפועלים ולא יעשה עמו באומן דברי רבי מאיר וחכ\"א עושה והוא ברחוק ממנו:","\u0001גמ׳\u0002 בקרוב לא פליגי דאסיר כי פליגי ברחוק ר\"מ סבר גזרינן רחוק משום קרוב דקא מרפי לה לארעא קמיה ורבנן סברי לא גזרי':"],[[0,"כי חיזרא לדיקלא","כמו האטד שמקיף הדקל ומגין לפירות שאין יכולים למשמש בו כך מגינה על גופו של אדם:"],[0,"תורייקי","תירייק\"א בלע\"ז:"],[1,"חושלא דשערי","שעורים ישנים קלופים:"],[1,"דריש נפה","שמדובקין בנפה ובכברה כשמרקדין בהן:"],[2,"בורדס","בסמ\"ך שילשול גדול שיוצא כל שעה כמעיין הנובע שאין לו שוליים ויצאו ממנו כל המים ואית דאמרי בורדם במ\"ם כמו בור שנובע דם ואית דאמרי מכה שקורין בו\"ן מלנ\"ט שיוצא נמי הימנו דם:"],[2,"מפני שהוא כמעיין הנובע","שקופץ מזה לזה ויש בו סכנה להזכירו:"],[3,"[היכי קתני]","מתני' ומרפאו רפואת נפש:"],[3,"בחנם","כלומר שאין לו הנאה אלא שמחזיק לו טובה בנפשו:"],[3,"רפואת נפש [גופו]","שאם חלה המדיר מותר למודר לרפאותו כדאמרינן לעיל דלא אדריה מן חיותיה:"],[3,"רפואת ממון בהמתו","שאם חלתה בהמתו אסור לרפאותה משום דקמהני ליה:"],[3,"אבל אומר לו כו'","דאמירה ולא כלום היא:"],[4,"מתני' ורוחץ עמו","המודר עם המדיר:"],[4,"אבל לא בקטנה","משום דקא מפשי מיא מיניה ומפיש נמי הבלא:"],[5,"אבל לא מן התמחוי","ביחד מפני שמרבה בעל הבית בשבילו:"],[6,"אבל אוכל הוא מן התמחוי החוזר","לבעל הבית כדמפרש בגמרא שדרכן לאכול מעט ומחזירו לבעל הבית שיש להן מאכילין הרבה וכיון דאין אוכל אלא מעט ומחזיר המותר לא מיתהני מיניה כלום אפי' אם אוכל חבירו פחות הימנו לא מיתהני דהא אינו אוכל אלא מעט והמותר מחזיר. ע\"א לא יאכל עמו מן התמחוי דדרך בני הסעודה לאחר שאכלו כפי שובען מצניעין המותר ונושאים עמם לבתיהן דהתם לא יאכל עמו דשמא אחד מהן אוכל פחות מחבירו ולכשיביאו מותרן לבתיהן חולקין בשוה ונמצא זה משתכר במה שאכל חבירו פחות ממנו אבל אם דרך בני הסעודה לאחר שאכלו מחזירין מותרן לבעל הבית ושוב אין מוסיפין בקערות מותר לאכול עמו:"],[7,"מתני' לא יאכל עמו מן האבוס שלפני הפועלים","כלי גדול שנותן בו בעל הבית ירקות שאוכלין בו הפועלים יחד ומשום טעם דתמחוי:"],[7,"ולא יעשה עמו באומן","שלא יעמוד עמו במענה אחת מפרש בגמ':"],[8,"בקרוב כ\"ע לא פליגי דאסור","לעדור דקא מרפיא כו':"],[8,"גמ' דקא מרפי לה לארעא קמיה","ונוח לו לחרוש אחריו:"]],[[0,"כי חיזרא לדקלא","שחריות שסביב לדקל מגין עליו כדקל בלע\"ז טורק\"א:"],[1,"דריש נפיא","סולת של שעורים:"],[2,"ואין מזכירין שמו","לפי שמתבייש החולה כשמזכיר:"],[2,"בור דם","בור נובע דם מתחתונים:"],[3,"אילימא רפואת נפש בחנם","מיירי בנכסי חולה אסורין על הרופא לכך שכר אסור:"],[3,"אלא רפואת נפש גופו","ומיירי בשנכסי רופא אסורים על החולה ורפואת גופו מותרת בנוטלין עליו שכר ומצוה קעביד:"],[3,"רפואת ממון בהמתו","דלא מצוה קעביד הא קמהני ליה אף כי אין נוטלין עליהן שכר ולא הוה כמו מחזיר אבידתו דמצוה להשיב לו אבידתו אבל אינו מצוה לרפא לו בהמתו:"],[3,"אבל אומר לו סם פלוני יפה לה","דדיבור שרי לאחווי ולהנאותו מדיבורו וי\"א רפואת נפש גופו דמיירי שנכסי חולה אסורין על הרופא ושרי לכנוס בביתו דמן חיותו לא אדריה אבל לא רפואת בהמתו דמתהני מדריסת הרגל ואפי' גבי צורך בהמתו אדריה כדאמרי' לעיל אבל אומר לו לא בבית אלא בשוק ולפי' ראשון ניחא טפי דלפי' זה אמאי נקט אומר אפי' לרפואת בהמתו בידוע שלא בביתו שרי ותו דמצי לפלוגי בין גופו לרפואת בנו:"],[6,"תניא לא ירחץ בין בגדולה בין בקטנה","קאי אאמבטי:"],[6,"גדולה","אם בימות הגשמים וכ\"ש בימות החמה וקטנה בימות החמה אבל לא בימות הגשמים:"],[6,"מזיע בקטנה","שמאחר שאינו אלא מזיע לא מיתהני מיניה:"],[6,"מן התמחוי החוזר לבעל הבית","פי' במתנה:"],[8,"בקרוב כ\"ע לא פליגי דאסור","דמרפה ליה ארעא קמיה וניחא לחפור בה יותר:"]]],[["\u0001מתני׳\u0002 המודר הנאה מחבירו לפני שביעית אינו יורד לתוך שדהו ואינו אוכל מן הנוטות ובשביעית אינו יורד לתוך שדהו אבל אוכל הוא מן הנטיעות הנוטות נדר הימנו מאכל לפני שביעית יורד לתוך שדהו ואינו אוכל מן הפירות ובשביעית יורד ואוכל:","\u0001גמ׳\u0002 רב ושמואל דאמרי תרוייהו נכסים אלו עליך לפני שביעית אין יורד לתוך שדהו ואינו אוכל מן הנוטות אע\"פ שהגיע שביעית ואם בשביעית נדר אין יורד לתוך שדהו אבל אוכל מן הנוטות","ור' יוחנן וריש לקיש דאמרי תרוייהו נכסי עליך לפני שביעית אין יורד לתוך שדהו ואין אוכל מן הנוטות הגיע שביעית אינו יורד לתוך שדהו אבל אוכל הוא את הנוטות","לימא בהא קמיפלגי דרב ושמואל סברי אדם אוסר דבר שברשותו אפילו לכשיצא מרשותו ורבי יוחנן ור\"ל סברי אין אדם אוסר דבר שברשותו לכשיצא מרשותו","ותיסברא מי איכא למ\"ד אין אדם אוסר דבר שברשותו לכשיצא מרשותו א\"כ ניפלגי בנכסים אלו וכ\"ש בנכסי","ותו הא תנן דאדם אוסר דבר שברשותו לכשיצא מרשותו דתנן האומר לבנו קונם שאתה נהנה לי מת יירשנו בחייו ובמותו"],[[0,"מתני' המודר הנאה מחבירו לפני שביעית","שהדירו חבירו קודם שנכנסה שביעית:"],[0,"אין יורד לתוך שדהו","לאכול מפירות שביעית דאסור בדריסת הרגל:"],[0,"ואין אוכל מן הנוטות","מאותן פירות הנוטין חוץ לשדה שיכול ליקח מהן ואינו צריך ליכנס בתוך השדה ואע\"ג דהן שביעית לא יאכל מהן כדאמרינן בגמרא אדם אוסר דבר שברשותו אפילו לכשיצא מרשותו והאי נמי כיון דלפני שביעית הדירו חבירו כי אתי נמי שביעי' אסור בהן:"],[0,"ובשביעית","אבל אם הדירו בשביעית לא יורד לתוך שדהו:"],[0,"אבל אוכל הוא מן הנוטות","הואיל ולא הוי ברשותו השתא כי מדיר ליה ובגמרא מפרש אמאי אינו יורד ואמאי אוכל הא ארעא נמי דהפקר היא:"],[0,"נדר הימנו מאכל לפני שביעית","אבל לא נדר הימנו הנאה לכי מטי שביעית יורד ואינו אוכל דהא לא הדירו אלא מן מאכל אבל אינו אוכל כדפרישית לעיל דאדם אוסר דבר שברשותו אפי' לאחר שיצא מרשותו:"],[0,"ובשביעית","הדירו בשביעית:"],[0,"יורד ואוכל","דעכשיו יצא מרשותו. ואית דנפרש המודר הנאה מחבירו לפני שביעית לא ירד לתוך שדהו לפני שביעית ולא יאכל מן הנוטות כיון דהדירו ובשביעית כלומר אם הגיעה שביעית לא ירד לתוך שדהו כו' ולישנא קמא עיקר:"],[1,"גמ' דאמרי תרוייהו נכסי אלו עליך","כלומר כל נכסי עליך בכל מקום שהן:"],[1,"ואין אוכל מן הנוטות","ואע\"פ שהגיע שביעית ושל הפקר הן:"],[1,"ואם בשביעית נדר","דהשתא לאו ברשותו הוא ולא מצי מדיר לה מנייהו אוכל מן הנוטות:"],[2,"ר' יוחנן ור\"ל דאמרי","הגיע שביעית אין יורד אבל אוכל מן הנוטות:"],[3,"אדם אוסר דבר שברשותו אפילו לכשיצא מרשותו","דכיון דבשעה שאסר הויין ברשותיה אפילו לכי הגיע שביעית נפקן מרשותיה אפילו הכי אסורין עליו:"],[3,"ר' יוחנן ור\"ל סבר אין אדם כו'","ומשום הכי כי הגיע שביעית דנפקא מרשותיה אוכל הוא מן הנוטות:"],[4,"ותסברא","דבהאי טעמא פליגי:"],[4,"ומי איכא למ\"ד אין אדם אוסר כו'","ור' יוחנן ור\"ל הכי סבירא להו:"],[4,"אם כן","דמשום האי טעמא פליגי ואמרי דאוכל הוא בשביעית:"],[4,"ליפלגי בנכסים אלו","אפי' היכא דאמר נכסים אלו עליך ולימרו ר' יוחנן ור\"ל דאוכל בשביעית משום הטעם דאמר אין אדם אוס' דבר שברשותו לכשיצא מרשותו כ\"ש היכא דאמ' נכסי דמשמע כל זמן שהן ברשותו אלא מדלא פליגי בנכסים אלו אלא בנכסי ש\"מ דלית להו האי סברא ועוד היכי מצי אמר לעולם דאין אדם אוסר דבר שברשותו לכשיצא מרשותו והתנן דאוסר:"],[5,"האומר לבנו קונם שאתה נהנה לי","כלומר שאי אתה נהנה לי מכל נכסי:"],[5,"מת יירשנו","שלא אסר עליו אלא כל זמן שהנכסים שלו לפיכך יירשנו אם מת:"],[5,"ואם נדר בחייו ובמותו","כיון דמפרש במותו מת לא יירשנו אלמא דאדם אוסר דבר שברשותו לכשיצא מרשותו לאחר מותו:"]],[[0,"המודר הנאה מחבירו לפני שביעית לא ירד לתוך שדהו","דדריסת הרגל אסורה ואינו אוכל אפילו מן הנוטות חוץ לשדה דאינו צריך לירד ולאוכלם:"],[0,"ובשביעית","פי' אם הדיר בשביעית לא ירד לתוך שדהו ליקח מן הנוטו' (אבל) אם יצטרך לירד ולאכול אסור - ובגמ' פריך אמאי אסור לירד בו לצורך אכילה הא רחמנא אפקריה לשדה לכל דבר אכילה:"],[0,"נדר ממנו מאכל לפני שביעי' יורד לתוך שדהו","דאינו מודר אלא מדבר המביא לידי מאכל ואינו אוכל מן הפירות:"],[0,"ובשביעית יורד ואוכל","דהפקר הוא וקשה דלעיל (נדרים דף לג -) מיבעיא ליה אם מפסק ומיזיל בארעא אי הוי הנאה המביאה לידי מאכל וי\"ל דבשביעית אף השדה הפקר לצורך אכילה דהכי מסיק בגמ' ולאידך נמי דמשני שמא ישהה בעמידה הכא לא שייך במודר מאכל דאי שהה אין בכך כלום:"],[1,"רב ושמואל אמרי נכסי אלו עליך לפני שביעית אינו אוכל מן הנוטות","ואף על פי שהגיע שביעית דכיון דאמר אלו אסורין עליו אפי' לאחר שנתנם או שהפקירם ולכך אסור בשביעית והשתא ס\"ד דבלא אמר נכסיי אלו והגיע שביעית אסור לאכול מן הנוטות דאדם אוסר דבר שברשותו אף כשיצא מרשותו ומתני' דקתני ובשביעי' אוכל בנוטות מיירי בהדירו בשביעית עצמה:"],[2,"רבי יוחנן ור\"ש בן לקיש [אמרי] נכסי עליך אינו יורד לתוך שדהו כו' הגיע שביעית אוכל מן הנוטות","והפקר הן ולא אסרן אלא כי איתנהו לדידיה אבל אי יהבינהו [לא] דאין אדם אוסר בקונמות לכשיצא מרשותיה וה\"ה היכא דאמר נכסי אלו הגיע שביעית מותר בנוטות ופריך אם כן דלא אסר רבי יוחנן כלל לכשיצא מרשותו אמאי לא אשמועינן למילתא באלו אלא אית להו אדם אוסר ועוד תנן דאדם אוסר לכשיצא מרשותו:"],[5,"מת יירשנו","דכשיש כח ברשותו אוסרה ותו לא:"],[5,"בחייו ובמותו לא יירשנו","אלמא אוסר אחריו לאחר מותו שיצאו מרשותו ומשני לה לעולם לא תפשוט מידי דהיכא דאמר נכסי אלו עליך שיאסרו לאחר שיצאו מרשותו דשאני הכא שפי' בהדיא שיאסרו לאחר מותו:"]]],[["אם מת לא יירשנו שאני הכא דקא א\"ל בחייו ובמותו","מכל מקום קשיא אלא בנכסים אלו כ\"ע לא פליגי כי פליגי בנכסי","רב ושמואל סברי ל\"ש נכסים אלו ל\"ש נכסי אדם אוסר ור' יוחנן ור\"ל סברי נכסים אדם אוסר נכסי אין אדם אוסר","ומי איכא למ\"ד ל\"ש נכסים אלו ול\"ש נכסי והא תנן האומר לחבירו קונם לתוך ביתך שאני נכנס שדך שאני לוקח מת או שמכרו לאחר מותר לבית זה שאני נכנס שדה זו שאני לוקח מת או שמכרו לאחר אסור","אלא כי אמרי ר' יוחנן וריש לקיש בנכסי ורב ושמואל בנכסים אלו ולא פליגי:","ובשביעית אין יורד לתוך שדהו כו': מאי שנא דאוכל מן הנוטות דפירי דהפקירא אינון ארעא נמי אפקרה","אמר עולא בעומדין אילנות על הגבולים ר' שמעון בן אליקים אמר גזירה שמא ישהא בעמידה:","\u0001מתני׳\u0002 המודר הנאה מחבירו לא ישאילנו ולא ישאל ממנו לא ילונו ולא ילוה ממנו ולא ימכור לו ולא יקח ממנו:"],[[0,"שאני הכא דאמר בחייו ובמותו","אבל היכא דאמר בסתם אימא לעולם אין אדם אוסר וכו':"],[1,"מ\"מ קשיא","כדאמרינן אי בהאי טעמא פליגי ליפלגו בנכסים אלו:"],[1,"אלא בנכסים אלו כ\"ע לא פליגי","דמשמע נכסים אלו לעולם:"],[1,"כי פליגי דאמר נכסי","ר' יוחנן ור\"ל סברי היכא דאמר נכסי אין אדם אוסר וכו' דנכסי משמע כל זמן שהן ברשותי ורב ושמואל סברי אפילו אמר נכסי (אמר) אדם אוסר דבר וכו':"],[3,"קונם לתוך ביתך שאני נכנס","כל זמן שהוא ביתך דהוי דומיא דנכסי עליך כיון שמת בעה\"ב או שמכרו לאותו בית לאחר מותר ליכנס בו דהשתא אינו שלו אבל אמר לבית זה שאני נכנס דהוי משמע נכסים אלו דקא אסר הבית עליו לעולם אע\"פ שמת או מכרו לאחר אסו' ליכנס בו אלמא דשאני בין נכסי לנכסים והיכי קאמרי רב ושמואל ל\"ש נכסי ול\"ש נכסים דאדם אוסר וכו':"],[4,"","אלא כי אמרי רב ושמואל:"],[6,"בעומדים אילנות על הגבולין","לחוץ שיכול לתלוש מן הפירות מבחוץ מש\"ה אינו יורד דהא דרחמנא אפקריה לארעא גבי שביעית לצורך אכילה ועכשיו לא היה נכנס לצורך אכילה:"],[6,"ר\"ש בן אליקים אמר","הא דקתני אוכל מן הנוטות ודאי כדקאמרת כגון דעומדין על הגבולין משום שיכול להושיט ידו וליקח מבחוץ אבל אין עומדין על הגבולין אינו יורד לתוך שדהו דאסור לו לירד לשם:"],[6,"גזירה שמא ישהא בעמידה","דלאחר שאכל עומד לו לשם וקמיתהני מנכסים דמדיר ואסור דהאי דאפקריה רחמנא כל זמן שהוא אוכל אז יכול לעמוד לשם דהפקר הוא אבל שלא לצורך אכילה לא אפקריה:"],[7,"מתני' המודר הנאה מחבירו לא ישאיל לו","שאלה בכלים הלואה במעות:"]],[[1,"מכל מקום [קשיא]","אי ס\"ל דאין אדם אוסר דבר שלא ברשותו לשמעינן מילתיה באלו:"],[1,"אלא בנכסי אלו לא פליגי דאדם אוסר כי פליגי בנכסי דרב ושמואל סברי ל\"ש נכסי אלו לא שנא נכסי אוסר","וקשה אמאי נקט במילתיה נכסי אלו הוה מצי למיפרך מהך ברייתא דלעיל קונם שאתה נהנה מת יירשנו אלמא בנכסי אינו אוסר או מהאי דלעיל (נדרים דף לה.) גבי קורדום מת או נתנו במתנה מותר מיהו ניחא ליה טפי לאותובי ממתניתין דלקמן דדמי טפי לנכסי אלו דקתני:"],[3,"מי איכא למ\"ד דבנכסי אדם אוסר","והתנן בפ' השותפין - מותר דלא נאסר אלא בעודהו ברשותו:"],[4,"אלא כי אמרי רבי יוחנן וריש לקיש בנכסי רב ושמואל בנכסי אלו","ולא פליגי:"],[5,"","מאי שנא דאוכל מן הנוטות דפירי דהפקירא אינון ארעא נמי הפקירא הוא ואפקרה רחמנא לצורך אכילה ואמאי לא ירד בה לאכול מאותן שאינן נוטות:"],[6,"בעומדים על הגבולין","דיכול לתולשן בלא ירידה בתוך השדה ולכך אמר דלא ירד לתוך השדה כיון דאפשר לאוכלם בלא ירידה אבל היכא דאין עומדין על הגבולין לעולם יורד ואוכל דרחמנא אפקריה:"],[6,"אלא גזירה שמא ירבה בעמידה","לאחר אכילה ולצורך אכילה אפקריה רחמנא שלא לצורך אכילה לא ואינו מותר אלא בנוטות שנוטות מחוץ לשדה ואינו נכנס לתוך השדה כלל:"],[7,"המודר הנאה מחבירו","שחבירו הדירו שלא יהנה משלו: לא ישאילנו חבירו דקא מהני ליה ולא ישאל מחבירו ובגמרא פריך הא לא מהני ליה למודר:"],[7,"ולא ילוונו חבירו","דקמהני ליה:"],[7,"ולא ילוה חבירו ממנו","ובגמרא פריך אמאי:"],[7,"לא ימכור לו חבירו","דאמרינן בשילהי פירקין דלעיל (נדרים דף לא.) דמיתהני מוכר ללוקח ולכך אסור בין למוכר בין ללוקח:"]]],[["\u0001גמ׳\u0002 בשלמא לא ילונו דקא מהני ליה אלא לא ילוה הימנו מאי קא מהני ליה ובשלמא לא ילוה הימנו ולא יקח הימנו דקמיתהני מיניה אלא לא ישאל הימנו מאי קא מיתהני מיניה","א\"ר יוסי בר' חנינא כגון שנדרו הנאה זה מזה אביי אמר גזירה לשאול משום להשאיל וכן בכולהו גזירה:","\u0001מתני׳\u0002 אמר לו השאילני פרתך אמר לו אינה פנויה אמר קונם שדי שאני חורש בה לעולם אם היה דרכו לחרוש הוא אסור וכל אדם מותרים ואם אין דרכו לחרוש הוא וכל אדם אסורין","המודר הנאה מחבירו ואין לו מה יאכל הולך אצל החנוני ואומר איש פלוני נודר ממני הנאה ואיני יודע מה אעשה והוא נותן לו ובא ונוטל מזה","היה ביתו לבנות גדרו לגדור שדהו לקצור הולך אצל הפועלים ואומר איש פלוני מודר ממני הנאה ואיני יודע מה אעשה והן עושין עמו ובאין ונוטלין שכר מזה","היו מהלכין בדרך ואין לו מה יאכל נותן לאחד לשום מתנה והלה מותר בה אם אין עמהם אחר מניח על הסלע או על הגדר ואומר הרי הן מופקרים לכל מי שיחפוץ והלה נוטל ואוכל ור' יוסי אוסר:","\u0001גמ׳\u0002 אמר ר' יוחנן מ\"ט דר' יוסי קסבר הפקר כמתנה מה מתנה עד דאתיא מרשות נותן לרשות מקבל אף הפקר עד דאתי לרשות זוכה","מתיב ר' אבא והלה נוטל ואוכל ורבי יוסי אוסר א\"ר יוסי אימתי בזמן שנדרו קודם להפקירו"],[[0,"גמ' בשלמא לא ילונו","מדיר למודר דודאי קמהני ליה הנאה מפורסמת:"],[0,"אבל לא ילוה ממנו","המדיר מן המודר:"],[0,"מאי הנאה","קא מטי ליה למודר ממאי דאוזיף למדיר:"],[0,"ובשלמא לא ילוה ממנו","מצי נמי למימר דקא מיתהני בכה\"ג כגון דאוזפיה מעות הרעות וקא משלם ליה היאך יפות ולא יקח ממנו משכחת לה דקא מתהני בזבינא דרמי על אפיה:"],[0,"אלא לא ישאל ממנו","מאי הנאה מטי למודר כי משאיל לו כליו הא קא מפחית ודאי לההיא כלי ולא מעלי ליה דסתם שאלה הכי הוא:"],[1,"כגון שנדרו זה מזה","דשניהם אסורים זה בזה:"],[1,"גזירה לשאול כו'","דאי שרית ליה לשאול אתי נמי להשאיל:"],[2,"מתני' אמר לו השאילני פרתך","לאו במודר ומדיר עסקינן:"],[2,"אינה פנויה","דמלאכתו היה עושה ונתעצב השואל כנגד המשאיל ואומר הואיל וסרבת להשאילה לי:"],[2,"קונם שדה שאני חורש","שלא אחרוש שדי בפרתך עולמית ואח\"כ השאילה לו רואין אם הוא פרזי ודרכי לחרוש שדהו הוא אסור לחרוש שדהו באותה פרה:"],[2,"וכל אדם מותר","דודאי כי נדר אדעתיה דנפשיה נדר ולא אדעתא דעלמא וכל אדם מותרים לחרוש לו שדהו באותה פרה:"],[2,"ואם אין דרכו לחרוש","שיש לו אריסין החורשין בשבילו:"],[2,"הוא וכל אדם אסורים","דודאי כי נדר אדעתא דכולי עלמא נדר:"],[3,"המודר הנאה מחבירו ואין לו מה יאכל הולך","המדיר אצל חנוני וכו' ובא חנוני ונוטל מעותיו מן המדיר. אבל בפירוש אסור לומר לו דאם כן הוה ליה החנוני שליח ושלוחו של אדם כמותו:"],[5,"ור' יוסי אוסר","בה במניחו על הסלע או על הגדר:"],[6,"גמ' א\"ר יוחנן מאי טעמא דר' יוסי","דלא חשיב ליה הפקר דקא אסר ליה ליטלו דכי מתהני מיניה ממש דמי ואסור:"],[6,"מה מתנה","לא זכי בה מקבל עד דאתיא לידיה:"],[6,"אף הפקר","נמי לא נפיק מרשות מפקיר עד דאתי לידי זוכה הילכך בהדי דשקיל ליה היאך מעל הסלע כמאן דשקיל ליה מידו ממש דמי ואסור:"],[7,"מתיב ר' אבא","ברייתא היא דקתני נמי מניח על הסלע והלה נוטל ואוכל:"],[7,"א\"ר יוסי אימתי","אני אוסר בזמן שנדרו קודם להפקרו דהשתא מסתברא טעמא דאסור משום דכשהדירו מכל נכסיו הדירו ואפילו כי הפקירן אסור בהן:"]],[[0,"בשלמא לא ילונו חבירו דמהני ליה למודר אלא לא ילוה הימנו מאי קמתהני מיניה המודר","ה\"ג בסיפא בשלמא לא יקח הימנו ולא ילוה הימנו אלא לא ישאל אמאי לא בשלמא לא יקח דמתני' קושיא דאקשית דלא יקח איכא לשנויי בשינויא דחיקא דקמתהני מוכר בזבינא מציעא ולא ילוה דמיתהני מודר דכי הדר פרע מדיר פרע ליה זוזי טבין ותקולי ומהני ליה אלא לא ישאילנו כלי או דבר שחוזר בעין מאי מהני ליה מדיר:"],[1,"אמר אביי גזירה לשאול משום להשאיל למודר וכן כלהו לא ילוה הימנו גזירה שמא ילוה לו אבל","לא יקח אסור מן הדין אטו ליקח בפחות כדמפרש בזבינא מציעא ושמא יש לפרש דלא יקח בפחות קאמר דהשתא נפסד המוכר אלא משום גזירה דגזרינן אטו יקח המודר בפחות דקמתהני ליה וקשה דהא תנן (לקמן נדרים מז:) האומר הריני עליך המודר אסור וכן סוף פ' ארבע נדרים שאיני נהנה לישראל לוקח ביותר דמודר מותר ליהנות ולא מדיר ולא גזרינן דלא יהנה פן יהנה ממנו הוא ומ\"ש דגזרינן לשאול אטו להשאיל ונראה להר\"מ דרגילות הוא כשאדם משאיל לחבירו שחבירו משאיל לו יותר משאר דברים:"],[2,"אמר לו השאילני פרתך אמר ליה אינה פנויה אמר השואל קונם שאני חורש בה לעולם אם היה דרכו לחרוש הוא אסור","דנתכוין לאסור אותו שדרכו לחרוש וכל אדם מותרין לחרוש בה לצרכו שלא נתכוין לאסור אלא על מי שדרכו לחרוש בה:"],[3,"המודר הנאה מחבירו ואין לו מה יאכל ילך וכו'","אורחא דמילתא קתני:"],[3,"הוא נותן לו ובא ונוטל מזה","אם ירצה דהא אין הפועלים יכולין לתבוע כלום:"],[4,"ביתו","לבנות - שאע\"פ שאין צורך מזון כל כך:"],[5,"נותן לאחר במתנה והלה מותר","ולא התירו אלא כשאין לו מה יאכל למדנו שכל הערמות אסורות בין ברבים בין ביחיד בנדרים שלא התירו אלא בשעת הדחק שאין לו מה יאכל - לשון הרב רבי אליעזר ממי\"ץ:"],[5,"הרי הן מופקרין כו' ורבי יוסי אוסר","מפרש בגמ' מאי טעמא דרבי יוסי קסבר הפקר כמתנה מה מתנה יכול לחזור עד דאתי לרשות מקבל ולא הוי כלום עד דאתי לידו אף הפקר עד דאתי לרשות זוכה דקודם לכן לא כלום הוא ודידיה הוא ולכך אסור לזכות בה המודר דבשעה שזוכה בו של מדיר הוא ואהפקר דוקא פליג רבי יוסי אבל אנותן במתנה לא פליג:"]]],[["אבל אם היה הפקירו קודם לנדרו הרי זה מותר ואי אמרת עד דאתי לרשות זוכה מה לי נדרו קודם להפקירו מה לי הפקירו קודם לנדרו","הוא מותיב לה והוא משני לה כל הנודר אין דעתו על מה שהפקיר","מתיב רבא מקצתן לראשון וכולן לשני ראשון קנה","שני לא קנה","אלא אמר רבא היינו טעמא דרבי יוסי גזירה משום מתנת בית חורון","תניא המפקיר את שדהו כל שלשה ימים יכול לחזור בו מכאן ואילך אין יכול לחזור בו"],[[0,"אבל אם היה הפקירו קודם לנדרו מותר","דמסתמא כי מדי אינש על מה דאית ליה ברשותיה הוא דאדריה ולא על מה שכבר הפקיר ואדהכי מותר ואי אמרת טעמא דרבי יוסי משום דלא הוי הפקר עד דאתיא לרשות זוכה מה לי נדרו קודם כו' הא כי נדר האי אכתי לא זכה ביה שום אדם ואמאי מותר:"],[1,"היינו טעמא דשרי דכל המדיר' אין דעתו על מה שהפקיר","אלא על מה שעדיין ברשותו ואדהכי מותר:"],[2,"מתיב רבא כו' מקצתן לראשון וכולן לשני","שכ\"מ שכתב מקצת נכסיו לאחד והשאר כולן כתב לשני:"],[2,"ראשון קנה שני לא קנה","ואם עמד חוזר בשני ואינו חוזר בראשון לפי שכשכתב לראשון שייר לעצמו מה שנתן אחר כך לשני ומן השני חוזר דלא שייר כלום ומש\"ה לא קנה ואי אמרת לא הוי מתנה עד דמטי ליד מקבל אמאי קנה ראשון טפי משני הא כיון דלא אתי לידיה לא הוי שלו וכי היכי דשל שני הוי שיור לראשון איכא למימר נמי דשל ראשון הוי שיור לשני הואיל וברשותו של נותן הן אכתי כל זמן דלא אתי לידיה דהאי אלא מדקנה ראשון ש\"מ ליתא להא דר' יוחנן דאמר לא. זכי מקבל עד דאתיא לידיה:"],[4,"אלא אמר רבא","לעולם קסבר רבי יוסי דמן התורה הויא מתנה לאלתר אע\"ג דלא אתי לרשות זוכה והואיל ומשעה שהפקירו הוי הפקר ומאי טעמא דר' יוסי דאסר הכא במתניתין:"],[4,"היינו טעמא דרבי יוסי","דלא אמר דליהוי הפקר:"],[4,"משום מתנת בית חורון","כדתנן בפרקין לקמן (נדרים דף מח.) דמוכחא מילתא דלא נתנה לחברו אלא בשביל שיבא אביו ויאכל והכא נמי אי אמרינן הוי הפקר כיון דאין שם אחר מיחזי דבשביל מודר ממש הפקיר והיינו דומיא דבית חורון הלכך אוקמינן אדרבנן דלא הוי הפקר עד דאתי לרשות זוכה ואית דמפרשי אלא אמר רבא לעולם לר' יוסי מדאורייתא לא הוי הפקר עד דאתי לרשות זוכה ולא דמי למתנה ומדרבנן הוא דהוי הפקר אע\"ג דלא אתי לרשות זוכה כדאמרי' לקמן כדי שלא תשתכח תורת הפקר והכא במתני' כו':"],[5,"המפקיר את שדהו כל ג' ימים הראשונים יכול לחזור בו","בין אמר אין רצוני שיהא הפקר דחזר בו ובין זכה בו איהו בתוך ג' ימים ושם הפקר לא חייל ביה ולא פקע ליה מידי מעשר דהפקר פטור מן המעשר כדקאמרינן (שבת דף סח.) ונשמר פרט להפקר:"],[5,"מכאן ואילך אינו יכול לחזור בו","ופטור מן המעשר כל מאן דזכי ביה:"]],[[0,"ואי אמרת עד דאתי לרשות זוכה מה לי נדרו קודם להפקירו מה לי הפקירו קודם לנדרו","בכלהו ליתסר דהא ברשותיה קיימי:"],[1,"אין דעתו לאסור מה שהפקיר","הלכך הוי הפקירו קודם לנדרו שרי:"],[2,"מתיב רבא מקצתה לראשון וכולה לשני","פירוש המחלק נכסיו:"],[2,"ראשון קנה","דהוי מתנה במקצת של שכיב מרע דבעינן קנין ואם עמד אינו חוזר והשני לא קנה דהויא מתנה בכולה דחוזר כשעמד ומיירי הכא כשעמד ומשום הכי ראשון קנה דהוה מתנה במקצת וע״כ בנמלך מעיקרא כי יהיב לראשון לא היה בדעתו ליתן כלל לשני דהכי אמר בפרק מי שמת (בבא בתרא דף קמח:) המחלק נכסיו אם כנמלך עמד אינו חוזר אלא באחרון ואם כמחלק שמתחלה כי יהיב לקמא מאז היה בדעתו לחלק אף לשני עמד חוזר אף בראשון אם כן ע״כ כולן לשני דקאמר אף מקצת שנתן לראשון יהא נתון לשני הלכך כי אמר מקצתו לראשון לא היה בדעתו לומר ומקצתו לשני ושוב כי אמר וכולן לשני הוי נמלך דאי כולן לשני דקאמר היה רוצה לתת השאר שלא נתתי לראשון יהא לשני אם כן ראשון אמאי קנה שמא מתחלתו כי אמר מקצתו לראשון היה דעתו ליתן השאר לשני ומנלן שהוא נמלך והיה לו להזכיר אם כנמלך והוי כמחלק ונימא דאם עמד חוזר אלא ע״כ ר״ל אף מה שנתן לראשון ונמלך הוי אלמא דעתו על מה שנתן ה״נ נימא דעתו על מה שהפקיר. כך פר״ת. ויש ספרים דגרסי מקצתו לראשון לא קנה ורבינו נתנאל אמר דברייתא היא בתוספתא גבי עבדים דכתב לראשון מקצת נכסיו ולשני כתב כל נכסיו [ראשון] לא יצא לחירות כיון דשייר מנכסיו ושני קנה עצמו דהא לא שייר לכך משתעבד אף בראשון אלמא דעתו ליתן לשני אף מה שנתן לראשון דאל״כ לא קנה עצמו דהא שייר והוא עצמו נתנו לראשון והשתא אין לו כלום אלא ע״כ דעתו אמה שנתן כבר ה״נ נימא הכי:"],[4,"אלא אמר רבא משום מעשה בית חורון","בשלהי השותפין לקמן (נדרים דף מח -) ואסרו מטעם שלא היתה מתנה גמורה שלא גמר בלבו לתתה הכא נמי אין נראה הפקר שדומה כאילו לא הפקירו אלא לדעת שיזכה בו המודר:"],[5,"תניא המפקיר שדהו כל ג' ימים יכול לחזור בו","וחייב במעשר האוכל ממנו אם אינו מתכוין לדבר דהפקירו אינו הפקר כלל אע\"פ שלא חזר בו נמי לא - הוי הפקר וטעמא משום דאיסור טבל ידוע לכל ויודעין כל העולם דזה איסור טבל עליו וזה הפקר אינו מפורסם ולפיכך כל ג' ימים יכול לחזור בו בין זכה בו הוא בין זכה בו אחר ומש\"ה חייב במעשר כיון דיכול לחזור ולכך גזרו מפני הרמאים דמפקרי והדרי בהו כדמסיק ועד שלשה ימים יש לחוש שמא יאמרו העולם הוא אוכל פירותיו שאינן מתוקנים אבל לאחר שלשה לא גזרו דמכאן ואילך ידוע ההפקר ומועיל ההפקר אפילו לא זכה בו אדם ואין חייב במעשר אבל במתני' המודר מותר מיד כשהפקיר דהתם כמו שאינו ידוע ההפקר כן אינו ידוע שהדירו חבירו דכוותיה דהכא אנו מתירין משום דידוע ההפקר לאחר שלשה ימים כמו איסור הטבל חייב במעשר וליכא למימר דזה מן החיוב על הפטור דמעשר הוא מיניה וביה:"]]],[["אמר תהא שדה זו מופקרת ליום אחד לשבת אחת לחדש אחד לשנה אחת לשבוע אחת עד שלא זכה בה בין הוא בין אחר יכול לחזור בו משזכה בה בין הוא בין אחר אין יכול לחזור בו רישא רבנן סיפא ר' יוסי","אמר עולא סיפא נמי רבנן היא אי הכי אמאי עד שלא זכה בה בין הוא בין אחר יכול לחזו' בו שאני שנה ושבוע דלא שכיחי","ר\"ל אמר מדסיפא ר' יוסי רישא נמי ר' יוסי ורישא היינו טעמא דלא לישתכח תורת הפקר","אי הכי אפילו מיום הראשון נמי ליהוי הפקר אמר רבה מפני הרמאין דמפקירין והדרין בהון","אבל דאורייתא לא הוי הפקר"],[[0,"אמר תהא שדה","מופקרת לשבוע א' לשמיטה אחת:"],[0,"עד שלא זכה בה בין הוא בין אחר יכול לחזור בו","אפילו בסוף שבת או בסוף חדש:"],[0,"משזכה בה בין הוא בין אחר","אפילו תוך שעה משהפקירו זכה בה שום אדם או הוא בעצמו לשום הפקר הוי הפקר דקסבר דלא הוי הפקר עד דאתי לרשות זוכה זכיה דידיה או דאחר לא חשיבא מידי עד דרפק בה פורתא כדאמר במסכת עירובין בפרק עושין פסין (עירובין דף כה.) בההיא איתתא דעבדא מחיצה בנכסי הגר אתא ההוא גברא רפק בה פורתא ואוקמוה רבנן בידיה דההוא גברא:"],[0,"רישא רבנן וסיפא רבי יוסי","רישא דאמר משלשה ימים ואילך אפילו לא אתא לרשות זוכה אין יכול לחזור בו דהוי הפקר רבנן היא ובדין הוא דאפילו מיום ראשון הוי הפקר אלא מפני הרמאים כדאמר רבה . לקמן לדברי הכל וסיפא רבי יוסי דאמר עד שלא זכה בה בין הוא בין אחר יכול לחזור בו דאמר דלא הוי הפקר מדאורייתא עד דאתי לרשות זוכה ומשום הכי קתני יכול לחזור בו כר\"י:"],[1,"אמר עולא סיפא נמי רבנן היא","דודאי מדאורייתא אע\"ג דלא אתיא לרשות זוכה הוי הפקר לאלתר ואפילו מיום ראשון והאי דאמר כל שלשה ימים יכול לחזור דלגביה לא חשיבא הפקר מפני הרמאין דלכולי עלמא אית להו דרבה דאמר מפני הרמאין דהדרי ומחזקי בהו ואמרינן דלא הוי הפקר עד שלשם ימים וסיפא דאמר עד שלא זכה בה לא הוי הפקר דמשמע עד דאתי לרשות זוכה היינו טעמא דשאני חדש ושנה ושבוע דלא שכיחן דאין דרכן של בני אדם להפקיר לזמן וכיון דזה שינה לכך אמרו חכמים דלא ליהוי הפקר לאפקועי ממעשר כל זמן דלא אתי לרשות זוכה:"],[2,"ר\"ל אמר מדסיפא ר\"י","דמשמע דלא ליהוי הפקר עד דאתי לרשות זוכה:"],[2,"רישא נמי","בתוך ג' ולאחר ג' רבי יוסי היא ורישא היינו טעם דלאחר ג' ימים אין יכול לחזור בו דהוי הפקר אע\"ג דלא אתי לרשות זוכה:"],[2,"משום דלא לישתכח תורת הפקר","דמדאורייתא ודאי לא הוי הפקר עד דאתי לרשות זוכה ולעולם כל זמן דלא אתא לידי זוכה לא הוי הפקר גמור וחייב חיוב דתרומה ומעשר והאי דאוקמוה רבנן אתורת הפקר לאו משום לאפקועי מתרומה ומעשר דכיון דמדאורייתא חייב דלאו הפקר הוא לא מפקעי ליה רבנן מתרומה ומעשר דלאו כל כמיניה אלא כדי שלא תשתכח תורת הפקר ומ\"מ גבי שנה ושבוע כיון דלא שכיחי אוקמוה רבנן אדאורייתא דלא הוי הפקר עד דאתי לידי זוכה דלא גזרו ביה רבנן משום שלא תשתכח תורת הפקר:"],[3,"אי הכי אפילו מיום ראשון ליהוי הפקר","כדי שלא תשתכח כו':"],[3,"אמר רבה","בדין הוא דלהוי הפקר מדרבנן אלא מפני הרמאין דבעי לאפקועי שדותם מתרומה ומעשר ואפקרי להו ואי אמרינן דלאלתר הוי הפקר ופטור מן המעשר הדרי מחזקי בהו ואדהכי כל שלשה ימים לא הוי הפקר לגבי איהו דסברי מתוך כך אתי ומחזיק ביה והוי דיליה ומימנעי ולא מפקרי ולעולם אפילו לאחר שלשה ימים לא הוי הפקר מדאורייתא עד דאתי לרשות זוכה:"]],[[0,"אמר שדה זו מופקרת ליום א' לשנה א' עד שלא זכה בו בין הוא בין אחר יכול לחזור בו","וחייב במעשר מדרבנן ובטל ההפקר ומעשר מיניה וביה ואתי נמי כר' יוסי דמחמרינן עליה וה\"ה בלא זמן והאי דנקט זמן לרבותא נקטיה דאע\"ג דלא שכיח גזר ביה משום מתנת בית חורון כך פי' הר\"ר אליעזר ועוד נרא' דנקט הפקר לזמן משום סיפא דאי משזכה בין הוא בין אחר אין יכול לחזור ואפילו תוך ג' ימים ודוקא משום דהפקר לזמן הוא אבל בסתם לא כדפרישית אבל האי דלזמן מועט מסתמא דעתו להפקר גמור דלא שייך למיגזר ועוד דדוקא זכה אחר אבל הוא לא ולחנם נקטיה ומשום דרישא נקט הוא הכא נמי נקטיה דכיון דאתי לרשות זוכה לא שייך למיגזר אבל אם הוא יהיה פטור שייך למיגזר:"],[0,"רישא רבנן וסיפא ר' יוסי","בתמיה: אמר עולא סיפא רבנן וכו' כיון דלא שכיח וגריעי מודו רבנן ואף על גב דלא מחמירין במודר הכא מחמירין טפי דאינו הפקר עד שיזכה בו אחר כדפרישית אבל כשזכה פטור מן המעשר אפילו תוך שלשה ואף ע\"ג דברישא אמר חייב עד לאחר שלשה הכא הטעם כדפי':"],[2,"ריש לקיש אמר אפי' רישא אתיא כר' יוסי","דמחמיר במדיר הכא נמי חייב במעשר ובדין הוא דאפילו לאחר שלשה לא הוי הפקר עד דאתי לרשות זוכה משום רמאות אבל אמרו חכמים דליהוי הפקר לאחר שלשה כדי שלא תשתכח תורת הפקר והוי פטור מן המעשר:"],[3,"אי הכי אפי' מיום ראשון נמי","כיון דחיישינן לשלא תשתכח תורת הפקר ושביק שיטתו דלא חל עד דאתי לרשות זוכה היה לו לפטור מיום ראשון. בשלמא לעולא דמוקי לה כרבנן דאמרי כשיטתייהו דמודר שלא תשתכח מפני הרמאין דמדאורייתא לא הוי הפקר אלא נתנו הכתוב לחכמים ויש לנו לפרש הפקר דאורייתא במקום דלא אתי לידי רמאות דעיקר הפקר לא מצינו אלא בשביעית והתם לא אתי לידי רמאות דאינו יכול להחליף שביעית ולומר זאת ששית ודומיא דשביעית דלא אתי לידי רמאות כגון אחר שלשה הוי הפקר אבל תוך שלשה לא ור' יוסי אוסר במתניתין מפני רמאין תוך שלשה אבל לאחר שלשה יהנה המודר לא משום מתנת בית חורון אלא משום דאורייתא לא הוה הפקר כל כמה דיכול ליתי לידי רמאות כך פירש האביעזר - צ\"ע דהא תניא (לעיל נדרים דף מג:) דהפקר אם היה קודם נדרו אז יכול ליהנות אבל לאחר לא יהנה לעולם אפילו לאחר שלשה ואם כן הרי תוך שלשה הואיל דהפקר מדאורייתא הוי הפקר ויש כח ביד חכמים לבטל ההפקר מפני הרמאין ומאי פריך ודילמא אתי לעשורי ודאי אינו חייב מן התורה אפילו תוך שלשה מאחר שזכה וחכמים גזרו מפני הרמאים ומעשר מיניה וביה אבל לאחר שלשה מוכח מילתא דלאו רמאות הוא ואוקמוה רבנן אדאורייתא ובמתניתין דאוסר ר' יוסי במדיר משום דחיישינן לרמאות אבל כשהפקיר קודם נדרו אין שם רמאות דאנן סהדי דלאו לרמאות קמיכוין אבל אין דין מדיר ודין הפקר שוין דמדיר אם הפקירו קודם לנדרו מותר מיד שייך למיגזר וכן נדרו קודם אסור אף לאחר שלשה:"]]],[["ודלמא אתי לעשורי מן החיוב על הפטור ומן הפטור על החיוב","דאמרי' ליה כי מעשרת עשר מיניה וביה","מיתיבי המפקיר את כרמו ולשחר עמד ובצרו חייב בפרט ובעוללות ובשכחה ובפיאה ופטור מן המעשר","בשלמא לעולא דרבנן קתני לה ודאורייתא קתני לה אלא לריש לקיש אמאי פטור מן המעשר","אמר לך כי אמרי אנא לר' יוסי הא רבנן היא"],[[0,"ופריך אבל מדאורייתא לא הוי הפקר ודילמא אתי לעשורי מן הפטור על החיוב ומן החיוב על הפטור","דכיון דאמרת דכל שלשה ימים לא הוי הפקר לא מדאורייתא ולא מדרבנן ואמרינן ליה דליתרום האי דהפקיר סבר המפקיר ודאי מדאורייתא הוי הפקר והפקר פטור מלאפרושי מיניה תרומה ומעשר אלא מדרבנן הוא דמחייבי לאפרושי מפני הרמאין ואתו לעשורי מן החיוב על הפטור דדילמא אית ליה עציץ שאינו נקוב דחייב לעשורי מדרבנן ולא מדאורייתא דלא קרינא ביה היוצא השדה ואמר האי מדרבנן והאי מדרבנן ומפריש מהאי דהפקר אהאי עציץ שאינו נקוב והתורה אמרה והרמותם ממנו מן החיוב על החיוב ולא מן הפטור על החיוב מפני שנראה כפודה תרומה כאדם זה שפודה הקדשו במעות ותרומה ומעשר אין להם פדיון לעולם הלכך אפילו מן החיוב לא אמרו לתרום אלא מן המוקף ומ\"מ אם תרם מזה על זה שלא מן המוקף תרומה הואיל שזה וזה חייב הוא. ל\"א אם אמרת דמכאן ואילך אין יכול לחזור בו דמדרבנן הוי הפקר אבל מדאורייתא לא הוי הפקר השתא נמי אתי מיניה חורבא דהאי מפקיר סבר אפילו מדאורייתא הוי הפקר והאי דמחייב תרומה ומעשר מדרבנן הוא ואתי לאפרושי מן הפטור על החיוב. ע\"א דילמא אתי לאפרושי מן החיוב על הפטור דאם היו מאה כורין נ' של חיוב וחמשים של פטור והפריש מן החיוב על הפטור כור דהשתא מפקע ליה לההוא כור מתורת חלה ואתי מיניה חורבא לעולם:"],[1,"","לא אתי לידי תקלה דאמרי' ליה כי מעשרת מהאי הפקר מיניה וביה:"],[2,"מיתיבי המפקיר את כרמו ולשחר עמד ובצרו","וזכה ביה איהו עצמו:"],[2,"חייב בפרט ועוללות","כמו משאר כרם:"],[2,"ופטור מן המעשר","דחשבינן ליה הפקר ואדהכי מיחייב מהני טפי ממעשר דכתיב בהו תעזוב יתירא כדאמרינן בב\"ק בפרק הגוזל (בבא קמא דף צד.) שאני פרט דכתיב ביה תעזוב יתירה חד בפרשת אמור אל הכהנים וחד בקדושים תהיו דמשמע אפילו דהפקר חייב אבל במעשר דלא כתיב ביה תעזוב יתירא פטור מדאורייתא אבל מדרבנן חייב:"],[3,"בשלמא לעולא","דמוקים לברייתא דלעיל דקתני כל ג' ימים יכול לחזור בו דמדאורייתא הוי הפקר אע\"ג דלא אתי לרשות זוכה אבל רבנן הוא דאמור דלא הוי הפקר עד לאחר שלשה ימים מפני הרמאין הא נמי דתני הכא פטור ממעשר והוי הפקר דאורייתא קאמר אבל מדרבנן חייב מפני הרמאין:"],[3,"אלא לריש לקיש","דאוקים לה לברייתא דלעיל אליבא דרבי יוסי דאמר ג' ימים לא הוי הפקר אפילו מדאורייתא דלאחר ג' ימים לא הוי הפקר אלא מדרבנן דגזרו שלא תשתכח תורת הפקר אמאי אם בצרו למחר פטור מן המעשר האמר ר' יוסי דאפילו מדרבנן לא הוי הפקר עד לאחר שלשה ימים:"],[4,"אמר לך ר\"ל כי אמרי אנא לרבי יוסי","אבל הך דקתני ולשחר השכים ובצרו פטור מן המעשר:"],[4,"רבנן היא","דאמרי במתניתין לאלתר הוי הפקר אע\"ג דלא אתי לרשות זוכה:"]],[[0,"ודלמא אתי לעשורי מן החיוב על הפטור","לפר\"ת דתוך שלשה לא הוי הפקר ולעולא פריך דמוקי לה כרבנן דאמרי לעיל דמדאורייתא הוי הפקר ומדרבנן הוא חייב במעשר וכן בסיפא עד שלא זכה בה בין הוא בין אחר יכול לחזור בו ואם כן אתי לעשורי מן החיוב על הפטור אבל לפיר\"י פריך לתרוייהו כיון דמדאורייתא הוי הפקר ומעשר מיניה וביה:"],[2,"המפקיר כרמו ולמחר השכים ובצרו חייב בפרט ובעוללות כו' ופטור מן המעשר","דכתיב ובא הלוי כי אין לו חלק ונחלה עמך יצא זה שידו וידך שוין ובשביעית נמי דרשינן דפטור מן המעשר דכתיב ואכלו אביוני עמך ויתרם תאכל חית השדה מה חיה אוכלת ופטור אף אדם אוכל ופטור ואיכא למימר תרוייהו צריכי אבל בלקט חייב משום דכתיב תעזוב יתירא כדאיתא בפרק הגוזל קמא (בבא קמא דף צד -) וקסבר דהא דתני הך ברייתא המפקיר שדהו תני ברייתא המפקיר כרמו אי רבנן אי ר' יוסי ולהכי פריך בשלמא לעולא רבנן קתני לה דפטור דקאמר מדאוריי' הוא ומדרבנן הוא חייב אלא ר״ש בן לקיש דמוקי הך דלעיל כרבי יוסי והך נמי כר' יוסי אמאי פטור מן המעשר ולפר״ת ניחא דהשתא מן התורה לעולא אמר דלא הוי הפקר אע״ג דאין רמאותו ניכר הכא דעבד רמאות ניכר דהשכים ובצרו לא כל שכן שיהיה חייב במעשר ואמאי פטור אבל לפר״י קשה מאי פריך דהא אמר לעיל לר' יוסי נמי מדאורייתא הוי הפקר ה״נ נימא הכי ויש ליישב דהכי פריך כיון דאמר לעיל קודם שראינו רמאותו דבטלו חכמים דבר תורה וחייבוהו במעשר וכל דתקון רבנן כעין דאורייתא תקון מאיזה טעם ראו לאסור מפני הרמאין דמפקרי והדרי בהו ויבא הדבר לידי איסור דאורייתא לאכול דבר שאינו מתוקן הכא דרמאותו ניכר יש לו לאסור ולחייב מן התורה ומשני מי סברת דרבי יוסי היא רבנן היא דאמרי דלא הוי הפקר מפני הרמאין וא״ת אם כן לרבנן ליהוי חייב כיון דרמאותו ניכר וי״ל דהם מקילין ליגזור טפי מרבי יוסי דאמר לעיל היכא דזכה אחר הוי הפקר מדרבנן ולרבי יוסי אינו כן ואם איתא לרבי יוסי נמי הוי הפקר:"]]],[["איבעית אימא הא דאפקריה באנפי תרין והא דאפקריה באפי תלתא דאמר ר' יוחנן משום רבי שמעון בן יהוצדק כל המפקיר בפני שלשה הוי הפקר בפני שנים לא הוי הפקר","ור' יהושע בן לוי אמר דבר תורה אפילו באחד הוי הפקר ומה טעם אמרו בשלשה כדי שיהא אחד זוכה ושנים מעידין:","\u0001הדרן עלך אין בין המודר\u0002"],[[0,"ואיבעית אימא","כי פליג ר' יוסי עלייהו דרבנן דאמרי לא הוי הפקר:"],[0,"כגון דילא אפקריה אלא באפי תרי","ואדהכי הכי קתני ר' יוסי במתניתין דאסור דלא הוי הפקר כל זמן דלא אתא ליד זוכה אבל היכא דאפקריה באפי בי תלתא הוי הפקר ואע\"ג דלא אתא ליד זוכה וכי קתני דפטור מן המעשר דאפקריה באפי בי תלתא:"],[1,"ור' יהושע בן לוי אמר דבר תורה אפי' בחד הוי הפקר","דאע\"ג דלא הגיע לרשות זוכה הוי הפקר לאלתר:"],[1,"ומה טעם אמרו כו' ושנים מעידין","דאי ליכא אלא תרי כי זכי חד מאן מעיד עליה דהלה הפקירו ולעולם לאלתר הוי הפקר והיינו כרבנן דרבי יהושע בן לוי סבירא ליה כרבנן:"]],[[0,"הא כגון דאפקריה בפני שלשה ואינו יכול לחזור בו","ודמי כאילו אתי לרשות זוכה והא דאית ליה דאינו הפקר עד דאתי לרשות זוכה באפי תרי דיכול לחזור בו דאמר רבי יוחנן בפני שנים איכא למיחש לרמאי וגם סתם הפקר מועיל אפי' שלא בפני שלשה:"],[1,"רבי יהושע בן לוי אומר דבר תורה אפי' באחד הוי הפקר","פר\"ת דר' יוחנן סבר לה כרבי יוסי ורבי יהושע בן לוי כרבנן ומן התורה הוי הפקר לאלתר וזו היא כפר\"ת דלעיל דמדאוריי' אמר רבי יוסי דלא הוי הפקר אבל לפר\"י דלעיל מצי סבר כר' יוסי דלא פליג אר' יוחנן מידי (אלא) - מהכא שמעינן דדוקא [בקרקעות הוא דשייך] רמאות אבל במטלטלין הוי הפקר לאלתר אפי' בפני שנים ואפי' לפירוש ר\"ת הלכתא כר' יהושע בן לוי דקיימי רבנן כוותיה ועוד ר' יהושע בן לוי ור' יוחנן הלכה כרבי יהושע בן לוי בכל מקום לשון הרב ר\"א מדפסקינן בפ' תפלת השחר (ברכות כח:) דלית (ליה) הלכתא כוותיה אלא בתרי והתם מפרש להו אבל באחריני הלכתא כוותיה דרבי יהושע בן לוי דלא מצריך תלתא מדרבנן אלא גבי מעשר וכדפרישית טעמא שלא יפקיענו ממעשר אבל לא להפקיר כליו בשבת שלא יעבור על שביתת כלים וכן בהמתו לא בעי תלתא אלא כדפריש בינו לבין עצמו שפיר דמי כדאמר פ\"ק דשבת (דף יח:) גבי כלים דמפקר אפקוריה וסתמא קאמר בכל עניינים:"]]],[["מתני׳ \u0001השותפין\u0002 שנדרו הנאה זה מזה אסורין ליכנס לחצר ר\"א בן יעקב אומר זה נכנס לתוך שלו וזה נכנס לתוך שלו"],[[0,"מתני' השותפין שנדרו הנאה זה מזה","מפרש בגמ' אי בנדרו אי בהדירו מיירי:"],[0,"אסורים ליכנס לחצר","בחצר של שניהן דכל חד אסור בדריסת הרגל של חבירו וקא סבר אין ברירה דאימור האי לחלק חבירו עייל והאי לחלק חבירו עייל:"],[0,"ר\"א בן יעקב אומר זה נכנס כו'","דקסבר יש ברירה:"]],[[0,"מתני' השותפין אסורין ליכנס בחצר","דאדריסה קפדי ובפרק חזקת הבתים (בבא בתרא דף נז:) מוקמינן ליה כרבי אליזר דאמר דויתור אסור במודר הנאה:"],[0,"רבי אליעזר ב\"י אמר זה מהלך בתוך שלו","דסבר דיש ברירה והאי בדידיה קמהלך והאי בדידיה קמהלך והכי מפרש בפרק שור שנגח את הפרה ומיהו ודאי אסור ליה לשטוח פירות בכל החצר אבל להלך בכולו מותר דאמר בכל דוכתא דקמהלך היינו חלקו:"]]],[["ושניהם אסורים להעמיד ריחים ותנור ולגדל תרנגולים","היה אחד מהם מודר הנאה מחבירו לא יכנס לחצר רבי אליעזר בן יעקב אומר יכול הוא לומר לו לתוך שלי אני נכנס ואיני נכנס לתוך שלך וכופין את הנודר למכור את חלקו","היה אחד מן השוק מודר באחד מהם הנאה לא יכנס לחצר רבי אליעזר בן יעקב אומר יכול לומר לו לתוך של חבירך אני נכנס ואיני נכנס לתוך שלך","המודר הנאה מחבירו ויש לו מרחץ ובית הבד מושכרין בעיר אם יש לו בהן תפיסת יד אסור אין לו בהן תפיסת יד מותר","האומר לחבירו קונם לביתך שאני נכנס ושדך שאני לוקח מת או שמכרו לאחר מותר קונם בית זה שאני נכנס שדה זו שאני לוקח מת או שמכרו לאחר אסור:","\u0001גמ׳\u0002 איבעיא להו בנדרו פליגי הדירו זה את זה מאי מי אמרינן בנדרו הוא דפליגי אבל בהדירו זה את זה מודו ליה רבנן לראב\"י דכי אנוסין דמו או דילמא אפילו בהדירו זה את זה פליגי רבנן","ת\"ש היה אחד מהן מודר הנאה מחבירו ופליגי רבנן תני נדור מחבירו הנאה","הכי נמי מסתברא דקתני סיפא וכופין את הנודר למכור את חלקו אי אמרת בשלמא דנדר הוא היינו דקתני כופין אלא אי אמרת דאדריה אמאי כופין אותו הא מינס אניס","אמר רבה אמר זעירי"],[[0,"ושניהם אסורין מלהעמיד ריחים ותנור","לקבוע ריחים ולגדל תרנגולים באותה חצר:"],[1,"הכי גרסינן היה אחד מהם מודר הנאה על חבירו כופין את הנודר","שהדיר את חבירו למכור את חלקו אתאן לרבנן דאמרי אסורים ליכנס לחצר:"],[2,"היה אחד מן השוק מודר מן א'","מן השותפים לא יכנס:"],[5,"גמ' בנדרו הוא דפליגי","היכא דנדרו שניהם זה מזה דזה אמר לחבירו קונם שאני נהנה לך וזה אומר קונם שאני נהנה לך דעכשיו נדרו זה מזה ממש והתם הוא דקא אסרי רבנן ליכנס לחצר דאיהו עצמו קאסר עליה אבל הדירו זה את זה דכל אחד הדיר את חבירו ואמר קונם שאתה נהנה לי קונם נכסי עליך דתרוייהי אנוסים דכל אחד אסר ליה חבריה שלא מדעתיה התם מודו ליה רבנן לר' אליעזר דזה נכנס לתוך שלו וזה נכנס לתוך שלו:"],[5,"או דילמא אפילו בהדירו [זה את זה] נמי פליגי","דלא שנא אנוסין ול\"ש רוצין:"],[7,"ה\"נ מסתברא","דבנדרו מיירי ובנדרו הוא דפליגי דקתני כופין את הנודר:"],[7,"אי אמרת בשלמא דנדרו","שנדר שלא יהנה מחבירו להכי כופין דאיהו הוא דאסר אנפשיה:"],[7,"אלא אי אמרת דהדירו חבירו אמאי כופין אותו","הא איהו לא פשע דמינס אניס אלא ודאי בנדרו פליגי:"]],[[0,"ושניהן אסורין להעמיד שם ריחים ותנור ולהעמיד שם תרנגולין","דבכל הכי יכולין למחות זה על זה בלא נדר כדאמר בפרק חזקת הבתים (ב\"ב נז:) הלכך אסור לעשות עתה בחצר כשנדר דאם כן מהני ליה חבירו על שלא עיכב דדוקא דריסת הרגל אינו יכול לעכב כל כמה דלא חלקו וי\"מ דכשהעמיד ריחים באים רוב עם לשם וממלא חלקו וחלק חבירו וכן לגדל תרנגולין דמתפשטין בכל החצר:"],[1,"היה אחד מהם מודר הנאה מחבירו","משום דבעי למתני כופין כו' דלא שייך למתני בשניהם מודרין וכופין הנודר למכור חלקו דחיישינן פן יעבור אבל רישא דשניהם מודרין אין כופין משום דמנכר אבל הכא דאין אסור אלא האחד והשני מותר דחיישינן שמא יכנס המודר כשיראה חבירו נכנס ולכך כופין למודר ותנא שמא יכנס קתני לה ולרבי אליעזר כיון דשניהם מותרין למה כופין:"],[2,"היה אחד מן השוק","הך בבא לר\"א איצטריך [דהוה אמינא] דלא קא שרי ר\"א אלא כשהחצר שלו דקמפסיד בדבר אבל אחד מן השוק לא שרינן ולא סמכינן אברירה כיון שאינו מפסיד כלום קמ\"ל:"],[3,"אם יש לו תפיסת יד למשכיר אסור","דעדיין הוא ברשותו ומדידיה קמיתהני כיון דגם אחר שהשכיר יש לו בה תפיסת יד אבל כשאין לו בה תפיסת יד יצאה כולה מרשותו ואין לו בה כלום ואינו יכול ליאסר - ומכאן פסק ר״ת מי שהשכיר בית ואח״כ אסרו עליו דאין באיסורו כלום ומיהו יש לי לדחות דמיירי דאדריה סתמא דאין עליו תפיסת יד ואין דעתו לאסור מה שהשכיר אבל אם אסר בהדיא מצי אסרה וכ״מ בערכין (דף כא -) (כל) המשכיר בית לחבירו והקדישו הדר בו מעל ומעלה שכר להקדש ועל ההיא נמי קשה מההיא דפרק אף על פי (כתובות דף נט:) שדה שמשכנתי לך לכשאפדנה תיקדש דקדשה משמע דקודם שפדאה לא קדשה ויש לומר דודאי מה שהבית שוה יותר מן השכירות קדוש אבל כנגדו חולין והוי שותפים המשכיר והמקדיש לכך מעל וההיא דאע״פ ה״ק לכשאפדנה תיקדש כל השדה לגמרי אי נמי יש לחלק דודאי בהקדש גמור דאסר לכ״ע דודאי מצי מקדיש המשכיר ובשמעתין דקאמר מותר מיירי שאסר בקונם בעלמא ואלומי אלימי לשיעבודא דשוכר כדאמר גבי שיעבודא דבעל וההיא דאע״פ דאמר דלא קדשה עד שיפדנה מיירי שאסר בקונם בעלמא אבל אם הקדישה הקדש גמור חל ההקדש אם שוה השדה יותר על החוב ועוד יש לחלק דודאי הך דפרק אע״פ מיירי בב״ח כדתנן מוסיף עוד דינר ופודה כל הנכסים הללו אבל הך דערכין מיירי בשוכר ומצי מקדיש משום דסופו לחזור אליו אבל גבי חוב דלא תחזור לו לבסוף אם לא יפרע לו חובו לא מצי מקדיש ובירושלמי מחלק בההיא דערכין בין הקדים לו שכרו ללא הקדים לו שכרו דודאי כשהקדים לו שכרו אינו של משכיר כלל:"],[5,"[בנדרו הוא דפליגי]","בנדר מעצמו דכל אחד ואחד אסר נפשו שאמר קונם שלא אהנה ממך הלכך יש להחמיר וקנסו רבנן אבל הדירו כל אחד חבירו ליהנות משלו מודו ליה רבנן לר' אליעזר דכאנוסין דמו ולא מיתסרו דאית להו ברירה [ובנדרו] קנסו אבל בהדירו לא קנסו - וצ\"ע בהא דתנן האומר הריני עליך חרם ואת עלי שניהם אסורים בדברים של אותה העיר אלמא בהדירו נמי אסרו רבנן ונראה דכיון שאמר הרי אתה עלי חרם קנסינן ליה גם על חבירו דבכל מקום השוו חכמים מדותיהם ואסרו שניהם:"],[5,"או דילמא אפילו כשהדירו חבירו קנסו רבנן","אי נמי לית להו ברירה ומיהא בפ' שור שנגח את הפרה (בבא קמא דף נא:) אמר בהדיא דרבנן לית להו ברירה וצריך למימר דלית להו הך סוגיא (אלא בת״ש היה אחד מהם מודר ופליגי):"],[6,"ת\"ש היה אחד מהם מודר","משמע שחבירו הדירו ואסרי רבנן:"],[6,"תני נודר","שאסר עצמו מחבירו:"],[7,"אי אמרת בשלמא בנודר היינו דקתני כופין","דפושע שאסר עצמו מחבירו ויכול לבא לידי תקלה:"],[7,"אלא אי אמרת שהדירו אמאי אמר כופין","דכופין הנודר היינו המודר אמאי כופין המודר דמאי חטא:"]]],[["מחלוקת שיש בה כדי חלוקה אבל אין בה כדי חלוקה דברי הכל מותר","א\"ל רב יוסף הרי בית הכנסת דכמי שאין בו כדי חלוקה דמי ותנן שניהן אסורין בדבר של אותה העיר","אלא אמר רב יוסף אמר זעירי מחלוקת שאין בה כדי חלוקה אבל יש בה כדי חלוקה דברי הכל אסור","אמר רב הונא הלכה כר\"א בן יעקב וכן א\"ר אלעזר הלכה כר' אליעזר בן יעקב:","המודר הנאה מחבירו ויש לו שם מרחץ וכו': וכמה תפיסת יד אמר רב נחמן למחצה לשליש ולרביע אבל בבציר לא אביי אמר אפילו בבציר אסור היכי דמי דשרי דמקבל בטסקא:"],[[0,"כשיש בה בדי חלוקה","ארבע אמות לזה וארבע אמות לזה וטעמא דמאן דאסר הואיל ואפשר בחלוקה:"],[0,"אבל אין בה כדי חלוקה דבר הכל מותר","דמאי אפשר ליה למיעבד:"],[1,"בדבר של אותה העיר","כדמפרש בית הכנסת והתיבה וכו':"],[2,"שאין בה כדי חלוקה","ומאן דאסר משום דכבית הכנסת דמי דקתני דש ניהם אסורים ומאן דשרי הואיל ואי אפשר בחלוקה:"],[2,"אבל יש בה כדי חלוקה דברי הכל אסור","דסגי ליה בחלוקה:"],[4,"וכמה תפיסת יד","יש לו למדיר באותו מרחץ דליתסר ביה האי:"],[4,"אבל בבציר","מרביע לא חשיב תפיסת יד ומותר בו המודר וספרים דכתיב בהו בבצין משמע נמי בבצים ואית דגרסי בביצין כמו ביצין של יוצר כדאמר בב\"מ (דף עד.) שהיוצר עושה כמין ביצים של חומר ומהם עושה קדרות והכי משמע ליה דאית ליה תשמישתא כלום אבל כדי להניח ביצים של יוצר להתם לייבשם אין זו תפיסת יד:"],[4,"אביי אמר אפי' בבציר","מרביע הוי תפיסת יד ואסור בהם המודר והכי נמי איכא לפרש כל הני לישני:"],[4,"דמקבל בטסקא","שקיבלו השוכר לתת ממנו מס בכל שנה ושנה דהאי לא הוי תפיסת יד כלל:"]],[[0,"מחלוקת בשיש בו כדי חלוקה","דאז מתהני בחלוקה שיכול לכוף את חבירו לחלוק לכך לא קנסוה רבנן אבל אין בה דין חלוקה שאין יכול לכוף את חבירו קנסו רבנן:"],[3,"אמר רב הונא הלכה כרבי אליעזר בן יעקב","וקשה דבפרק בתרא פסקינן כרבי אושעיא דאמר בדאורייתא אין ברירה בדרבנן יש ברירה והכא דאורייתא הוא ומפרש ר\"ת דהא דפסקי' כרבי אליעזר בן יעקב לאו מטעם דיש ברירה אלא משום דויתור מותר במודר הנאה וכשהדירו זה את זה מדריסת הרגל לא נאסרו וא\"כ לפי זה שאם אסרו עצמם בדריסה אסורין ליכנס לחצר ואדם מן השוק שאסר מותר ליכנס דויתור מותר ור\"י פי' דפסקינן שפיר מטעמא דיש ברירה ובביצה (דף לח:) לא פסיק כר' אושעיא אלא ממאי דאמר בדרבנן יש ברירה הילכך שותפין שנדרו דריסת הרגל מותרין בחצר ואדם מן השוק מודר הנאה מחבירו אסור ליכנס דויתור אסור דאשכחן סתמא בפרקין דלעיל דויתור אסור:"],[4,"למחצה לשליש ולרביע","שהמשכיר מקבל שליש הריוח ואין לשוכר כ\"א ב' חלקים דברשותו הוא מקבל ואסור:"],[4,"אבל בבציר","פירוש בפחות מותר:"],[4,"","אביי אמר אפילו בבציר אסור כך הגירסא ראשונה:"],[4,"דמקבל בטסקא","פירוש שמקבל השוכר מן המשכיר בכך וכך לשנה ואיתא ספרים דגרסי אפילו בבצין פירוש קרקע היוצר כמו על הבצין של יוצר (ב\"מ דף עד.) ורגילין לייבשן במרחץ ואם רגילות להשכיר לייבש בצין של משכיר באותו מרחץ הוה תפיסת יד:"]]],[["האומר לחבירו וכו': בעי אבימי קונם לבית זה שאתה נכנס מת או שמכרו לאחר מהו אדם אוסר דבר שברשותו לכשיצא מרשותו או לא","אמר רבא ת\"ש האומר לבנו קונם שאי אתה נהנה לי ומת יירשנו בחייו ובמותו ומת לא יירשנו ש\"מ אדם אוסר דבר שברשותו לכשיצא מרשותו שמע מינה:","תנן התם קונם פירות האלו עלי קונם הן על פי קונם הן לפי אסור בחילופיהן ובגידוליהן","בעי רמי בר חמא אמר קונם פירות האלו על פלוני מהו בחילופיהן מי אמרינן גבי דיליה הואיל ואדם אוסר פירות חבירו על עצמו אדם אוסר דבר שלא בא לעולם על עצמו גבי חבירו הואיל ואין אדם אוסר פירות חבירו על חבירו אין אדם אוסר דבר שלא בא לעולם על חבירו"],[[0,"","ה\"ג בעי אבימי קונם בית זה שאתה נכנס ומת או שמכרו לאחר מהו:"],[0,"אדם אוסר דבר וכו'","ואפילו לאחר שמת או שמכרו לאחר הוי נמי אסור או לא:"],[2,"תנן התם","לקמן בפרק הנודר מן הירק:"],[2,"קונם פירות האלו עלי או קונם הן לפי או קונם הן על פי אסור בחילופיהן","אם נתחלפו בפירות אחרות ודבר שלא בא לעולם הוא:"],[2,"גידוליהן","שנטען והגדילו:"],[3,"על פלוני","שאסרן על חבירו:"],[3,"מהו","אי הוי אסור בחילופיהן כמו שהוא אסור אי לא מי אמרינן גביה דיליה כי אמר קונם הן לפי או על פי אסור בחילופיהן אף על גב דהוי דבר שלב\"ל הואיל ואשכחן גבי דיליה כי האי חומרא דאיהו אוס' פירות חבירו עליו ואהכי מחמירי' לגביה דאוסר נמי עליו דבר שלב\"ל אבל גבי חבירו הואיל ואינו אוסר פירות חבירו על חבירו דאי אמר לחבירו קונם פירות של פלוני עליך לא הוי כלום לא אמרינן נמי דאית בידו למיסר ליה בחליפין דהוי דבר שלא בא לעולם:"]],[[0,"מת או מכרו לאחר מותר","לפי שלא נתכוין לאסור אלא בעודו שלו:"],[0,"שדה זה שאני לוקח בית זו שאני נכנס והבית שלו מת או מכרו מהו","מי אמרי' כיון דדידיה הוא אינו יכול לאסור אלא בעודו שלו דנהי דתנן בית זה שאני נכנס ומכרו אסור ה\"מ כשמדיר עצמו מבית חבירו דעתו לאוסרו עליו (שהרי אסרו עליו) כשאינו שלו ומיבעיא לאבימי כשאמר בהדיא בחייו ובמותו: ת\"ש כו' הכא לא דחי שאני הכא דקאמר בחייו ובמותו כדאמר לעיל דהכא כי נמי אמר בחייו ובמותו מיבעיא ליה משום דאין אדם אוסר דבר שברשותו לכשיצא מרשותו:"],[2,"תנן התם","לקמן בפרק הנודר מן הירק:"],[2,"אסור בחילופיהן","אם מכרם או החליפם אסורין [דמיהן וחלופיהן] דחשבינן להן כהקדש ותופס דמיו וגידולי הקדש הקדש:"],[3,"","אמר קונם פירות אלו על פלוני מהו בחילופיהן וה״ה דמיבעיא ליה (בשאר איסורין) אם מכר מהו שיהנה המודר מן החילופין דשמא אסור כי ההוא דלעיל דאסור בחלופיהן וה״ה דמיבעיא ליה בשאר איסורי הנאה כגון ערלה וכלאי הכרם מדקמייתי למפשט בעיין ממתני' דמקדש בערלה וכלאי הכרם וליכא לפרושי דמיבעיא ליה באיסורי הנאה מהו בחילופיהן אם מותר למוכרם בתחילה דפשיט' דאסור כדמוכח פרק כל שעה (פסחים דף כא:) למ״ד לא תאכלו איסורי הנאה משמע מדאיצטרי' קרא למישרי נבילה למכרה לעובד כוכבים אלמא דאסור למכור איסורי הנאה משום דבשעת מכירה הוא נהנה מגוף האיסור וה״ל כשרשיפא מעצי איסור וגם אם מכרם בדיעבד פשיטא ליה דמותרין מן התורה כדמפרש בשלהי פרק שני דקדושין (דף נח -) דאין לך דבר שתופס דמיו אלא עבודת כוכבים ושביעית וקאמר התם דהוו להו שני כתובים הבאים כאחד ואין מלמדין מהם שאר איסורין וכי קמיבעיא אם החליפן אסורין מדרבנן כדקאמר במתניתין קונם פירות אלו עלי אסור בחילופיהן דחילופיהן כגידוליהן או שמא גבי דידיה הואיל ואדם אוסר כו' אבל גבי חבירו דאין אדם אוסר פירות חבירו על חבירו אין אדם אוסר דבר שלא בא לעולם על חבירו וה״ה בכל איסורי הנאה ושרי ונראה דלהכי לא קמיבעיא ליה בחליפין איסורי הנאה [לאסור לאותן] שלא החליפם דפשיטא דשרי כדאמר (חולין דף ד -) חמצן של עוברי עבירה אחר הפסח מותר מיד מפני שהם מחליפין ולא מיבעיא ליה אלא לאותו עצמו שהחליפן ומבעיא בהחלפתם אי קנסינן ליה ואסור ליהנות מדרבנן:"]]],[["או דילמא משום דחילופין כגידולין דמי לא שנא הוא ולא שנא חברו","אמר רב אחא בר מניומי ת\"ש האומר לאשתו קונם שאני נהנה ליך לווה ובעלי חובין באין ונפרעין מ\"ט בעלי חובין נפרעין לאו משום דחילופין לאו כגידולין דמי","אמר רבא דילמא לכתחילה הוא דלא ואי עבד עבד","אלא ת\"ש המקדש בערלה אינה מקודשת מכרן וקידש בדמיהן הרי זו מקודשת הכא נמי לכתחילה הוא דלא ואי עבד עבד:","\u0001מתני׳\u0002 הריני עליך חרם המודר אסור הרי את עלי חרם הנודר אסור הריני עליך ואת עלי שניהם אסורין ושניהם מותרין בדבר של עולי בבל"],[[0,"או דילמא","הכי קאמר דודאי אסור בחלופייהן דומיא דגידולין נינהו וכי היכי דאסור בגידולין הכי נמי אסור בחליפין:"],[1,"קונם שאני נהנה לך לווה ובעלי חובין באין ונפרעין","מבעלה דרצון הבעל הוא שילוו לה והא הכא דלוותה מאחרים דחילופי ממונו של בעל הוי ולא מיתסר אלמא דאין אדם אוסר דבר שלב\"ל על חבירו דהא נפרעין מבעלה:"],[1,"לאו כגידולין דמי","ובגידולין אסור אבל בחליפין מותר:"],[2,"אמר רבא","לעולם אימא לך דחליפין כגידולין דמו ומיתסרי ואהכי לכתחילה לא תלוה ותאכל אבל בדיעבד שפיר דמי והא דאמרינן בהך פירקא דלעיל (נדרים דף מג.) המודר הנאה מחבירו ואין לו מה יאכל נותן לזה ובא הלה ונוטל מזה לא דמיא להא דהאי לא רמי עליה דהאי למיפרנסיה והאי דקיהיב להאי אימור לא משום מודר קא יהיב ליה אלא מתנה בעלמא הוא דקא יהיב להאיך אבל האי בעל דלמפרנסה קאי אימא דליתסר ליה לפרוע לבעל חוב לכתחילה הוא דלא:"],[3,"תא שמע","דמותר אפי' לכתחילה:"],[3,"המקדש בערלה","שהוא איסור הנאה אינה מקודשת:"],[3,"מכרן וקידש בדמיהן מקודשת","אלמא דחליפין לאו כגידולין דמו דגידולין אסור ובחליפין משתרי:"],[3,"ה\"נ","מיירי דלכתחילה לא ימכור ואם קידש בדמיהם מאי דעבד עבד:"],[4,"מתני' הריני עליך חרם","נכסי יהיו עליך חרם:"],[4,"המודר אסור","אבל המדיר מותר:"]],[[1,"","תא שמע האומר לאשתו קונם שאני נהנה לך ותלה הדבר בתשמיש שאמר הנאת תשמישך עלי אם תיהנה משלי דאל\"כ כיון דמשועבד לה לא מצי מדיר לה אי נמי דאדרה כשהיא ארוסה (או) ונישאת:"],[1,"לוה ובעלי חובין נפרעין","כדאמר לותה ואכלה ועמדה ומיאנה אין לה מזונות הא לא מיאנה יש לה מזונות ואפילו לרבנן דחנן דאמרי הניח מעותיו על קרן הצבי ה\"מ במפרנס אשת חבירו סתם אבל הלוה לה בתורת הלואה נפרע מן הבעל וא\"ת ולרבנן דחנן היאך פורע חובה הרי אסור לפרוע למי שמודר הנאה ממנו וי\"ל דהיינו בפורע חוב חבירו שהוא יכול לתובעו ולומר פרע לי מה שפרעתי בשבילך והוי כאילו הלוהו ממש אבל באשתו אינו חייב לפרוע לו כלל מה שפרע בשבילה:"],[1,"מאי טעמא בעלי חובות חוזרין ונפרעין לאו דחילופין לאו כגדולין דמו","ושרו ליהנות למודר דאי אסורין א\"כ מעות שמוסרין לה המלוים הוו חליפי מעות הבעל ומההוא דתנן (לעיל נדרים דף מג -) המודר הנאה מחבירו הולך אצל חנוני הרגיל אצלו וכו' לא מצי למיפשט בעיין דסתם חנוני לית ליה למיתבע מידי מן המדיר הילכך מתנת חנם הוא דיהיב לחנוני ואם ירצה חנוני עדיין יוכל לתבוע מודר אבל הכא דבעלי חובות יש לו על הבעל שהבעל חייב במזונות אשתו א\"כ מה שהם מלוים לה הוי ממש חליפי מעות הבעל:"],[2,"דילמא לכתחילה הוא דלא הא דיעבד עבד","כלומר לותה דוקא בדיעבד קאמר דאז בעלי חובין נפרעין אבל לכתחילה לא תלוה וכשלותה הרי זה דיעבד שאין זה חליפי איסור ממה שעדיין האיסור לא בא אבל מעיקרא סלקא דעתך דשרו רבנן ללוות בתחילה ולגרום דברים שיבא לידי איסור לכן פשיט מיניה דחליפי (טומאה) מותרין:"],[3,"ת\"ש המקדש [בערלה] (בדמי ערלה פי' בדמים של ערלה) או כלאי הכרם אינה מקודשת משום דאיסורי הנאה אינון ולא הוי ממון","מכרם וקדש בדמיהן בערלה וכלאי הכרם מקודשת דאינן תופסין דמיהן אלמא שרי לאיתהנויי בחליפין דאי אסור ליהנות היה לנו לומר דאסור לשהות עמה באותם קידושין:"],[3,"ה\"נ הא לכתחילה הא דיעבד","כלומר אכתי איבעיא ליה אי מותר לכתחילה הוא או דוקא דיעבד אבל לכתחילה לא ואע\"ג דעל ידי הקידושין הוא נהנה ממנה לכתחילה דוקא בקידושין שלא תקנו חכמים להפקיע הקידושין דכיון שהיא אשתו הוא חייב ליהנות ממנה אבל משאר הנאות אם אסור למוכרם אם לקח מן המעות כלי אסור ליהנות ממנו דאסור בחלופיהן קרינן ביה. מפירו\"ש רבינ\"ו שמעו\"ן מקוצ\"י:"],[4,"הריני עליך חרם המודר אסור","דהכי קאמר הרי ממוני אסור עליך:"],[4,"הרי אתה עלי חרם","הכי קאמר הרי ממונך עלי כחרם וחרם הוי הקדש דסתם חרם לבדק הבית:"],[4,"ומותרים בדברים של עולי בבל כגון בור שבאמצע הדרך שעשאוהו עולי גולה","לפי שהפקירוהו לכל ישראל ולא נתנוהו להם להיות שותפין (כך) [בו] לענין שיוכל האחד לאסור חלק חבירו:"]]],[["ואסורים בדבר של אותה העיר ואיזהו דבר של עולי בבל כגון הר הבית והעזרות והבור שבאמצע הדרך ואיזהו דבר של אותה העיר כגון הרחבה והמרחץ ובית הכנסת והתיבה והספרים והכותב חלקו לנשיא","ר' יהודה אומר אחד כותב לנשיא ואחד כותב להדיוט מה בין כותב לנשיא לכותב להדיוט שהכותב לנשיא אין צריך לזכות להדיוט צריך לזכות וחכמים אומרים אחד זה ואחד זה צריכין לזכות לא דברו בנשיא אלא בהוה רבי יהודה אומר אין אנשי גליל צריכין לכתוב שכבר כתבו אבותיהן על ידיהן:","\u0001גמ׳\u0002 אמאי מיתסר אמר רב ששת הכי קתני ומה תקנתן יכתבו חלקן לנשיא","רבי יהודה אומר אחד כותב לנשיא ואחד כותב להדיוט ומה בין כותב לנשיא לכותב להדיוט הכותב לנשיא אין צריך לזכות והכות' להדיוט צריך לזכות וחכמים אומרים אחד זה ואחד זה צריכים לזכות לא דברו בנשיא אלא בהוה:","ר' יהודה אומר אין אנשי גליל צריכין לזכות שכבר כתבו אבותיהן על ידיהן: תניא ר' יהודה אומר אנשי גליל קנטרנין היו והיו נודרין הנאה זה מזה עמדו אבותיהם וכתבו חלקיהן לנשיא:","\u0001מתני׳\u0002 המודר הנאה מחבירו ואין לו מה יאכל נותנו לאחר לשום מתנה והלה מותר בה מעשה באחד בבית חורון שהיה אביו נודר הימנו הנאה והיה משיא את בנו ואמר לחברו חצר וסעודה נתונים הינן לפניך אלא כדי שיבא אבא ויאכל עמנו בסעודה","אמר אם שלי הם הרי הם מוקדשין לשמים א\"ל נתתי לך את שלי שתקדישם לשמים אמר לו נתת לי את שלך אלא שתהא אתה ואביך אוכלין ושותין ומתרצין זה לזה ויהא עון תלוי בראשו אמרו חכמים כל מתנה שאינה שאם הקדישה תהא מקודשת אינה מתנה:","\u0001גמ׳\u0002 מעשה לסתור חסורי מיחסרא והכי קתני ואם הוכיח סופו על תחילתו אסור ומעשה נמי בבית חורון באחד דהוה סופו מוכיח על תחילתו","אמר רבא לא שנו אלא דאמר ליה והינן לפניך אלא כדי שיבא אבא אבל א\"ל שיהו לפניך שיבא אבא מדעתך הוא דא\"ל","לישנא אחרינא אמרין לה אמר רבא לא תימא טעמא דא\"ל והינן לפניך הוא דאסור אבל א\"ל הן לפניך שיבא אבא ויאכל מותר אלא אפילו אמר ליה הן לפניך יבא אבא ויאכל אסור מאי טעמא סעודתו מוכחת עליו"],[[0,"בדבר של אותה העיר","דשל שניהן הן:"],[0,"והבור שבאמצע","כדמפרש בשלהי פרק בתרא דעירובין (דף קד.):"],[0,"והספרים","ספרי תורה ששניהן נתנו בהן מעות עם אנשי אותה העיר:"],[0,"והכותב חלקו לנשיא","בגמרא מפרש לה:"],[1,"שהכותב לנשיא א\"צ לזכות","ע\"י אחר אבל הכותב להדיוט צריך לזכות ובזה כח נשיא יפה מכח הדיוט:"],[1,"בהווה","שכן דרך לחלוק כבוד לנשיא:"],[4,"גמ' תניא רבי יהודה אומר אנשי גליל קנטרנין הן","כעסנים הן:"],[4,"וכתבו","מדבר של אותה העיר לנשיא כוי שיהו אלו ואלו מותרין בהן:"],[5,"מתני' המודר הנאה מחבירו ואין לו מה יאכל","הך מתניתין אייתי נמי לעיל באידך פירקין (נדרים ד' מג.) אלא דהתם לא נקט לה אלא משום דיוקא משום דבעי למיתנא עלה הפקר דפליג בה רבי יוסי:"],[6,"ויהא העון תלוי בראשו","שיהא אביו המודר הנאה אוכל על ידו:"],[6,"אמרו חכמים כל מתנה שאינה","כל כך ברשות המקבל שאם הקדישה אינה מקודשת אינה מתנה:"],[7,"גמ' מעשה לסתור","דברישא קתני המודר הנאה וכו' וקתני תקנתא דמצי למעבד כה\"ג והדר תני נעשה וכו' לסתור דבריו הראשונים:"],[7,"חסורי מחסרא והכי קתני","במתניתין המודר הנאה וכו':"],[7,"ואם הוכיח סופו על תחלתו","שלא נתן לו אלא על מנת שיתן לזה ייאכל אסור ומעשה נמי וכו':"],[8,"לא שנו","דאינה מתנה אלא דאמר ליה והינן לפניך דמשמע דהכי א\"ל והינן נתונין לך אלא על מנת שיבא אבא:"],[8,"אבל אמר ליה והן לפניך שיבא אבא ויאכל מדיעתיה הוא דקא אמר ליה","דהכי משמע והן נתונים לך והם בדעתך שיבא אבא הוי דוקא לו: ע\"א אמר רבא לא תידוק ותימא דאיכא חילוק בין והינן לפניך בין והן לפניך דודאי תרוייהו אסירי דהא סעודתו מוכחת עליו שלא נתן לו אלא על מנת שיבוא אביו ויאכל דה\"ל כמ\"ד והינן לפניך:"]],[[0,"בדברים של אותה העיר","שהם דרים בה שהן (מפני) שותפין וזה אסור מפני חלקו של זה:"],[0,"רחבה ומרחץ ובית הכנסת","אתיא כרבנן דאסרו בחצר דאין ברירה:"],[0,"אסור ברחבה ובבית הכנסת","יש לדקדק לכאורה משמע דאתי' כרבנן דאמרי אין ברירה ולא אמר האי בדידיה קמהלך כמו בחצר לרבי אליעזר ובפרק בתרא דביצה (דף לט -) גבי בור דמתניתין דעולי בבל קבעי למימר דמתני' דהכא אית ליה ברירה ולכך מותר בבור משום דהאי בדידיה קממלא והאי בדידיה קממלא ואם כן אמאי אסור בבית הכנסת ובדברים של אותה העיר ויש לחלק [בממלא] מים מן הבור בהא סבר תנא דיש ברירה בהא שהוא מסלקו מחלק חבירו אבל להשתמש או להכנס בדבר שחבירו שותף ודאי לית להו ברירה וה\"ה דהוי מצי למיתני דשניהן מותרין למלאות מבור שבעיר בפרק הדר (עירובין מה:) עוד נראה להר\"ר שמואל מאויר\"א ז\"ל דסוגיא דהתם סברה כסברא דריש פירקין דרבנן סברי שפיר דיש ברירה ולא אסרו אלא (בברירה) משום קנסא ודווקא בדברים של אותה העיר אבל בדברים של עולי בבל לא רצו לקנוס לפי שהוא לכל העולם:"],[0,"והתיבה","ארון שנותנין בו ס\"ת:"],[0,"והספרים","היו רגילין לקנות ספרים משל צבור ללמוד בהם בני העיר:"],[0,"והכותב חלקו לנשיא","מפרש בגמרא דה\"ק כיצד תקנתם יכתבו חלקם לנשיא והא דלעיל גבי חצר לא קאמר הך תקנתא דחצר שהיא מיוחדת ממש אין תקנה לתת אותה לנשיא אבל הכא דמעיקרא נמי אין כל הדברים הללו מיוחדים להם לא יפסידו אם יכתבו חלקם לנשיא שגם אחר כך יכולין לילך וליהנות שהנשיא לא יקפיד עליהן כיון שגם לו אינה מיוחדת שהרי היא לכל בני העיר ולנשיא לאו דווקא ה\"ה אם לאחד מבני העיר אלא לרווחא דמילתא נקט כדמוכח לקמן לא דברו חכמים אלא בהווה והטעם לפי שחולקים כבוד לנשיא א\"נ כיון שאנו מתחילים לעשות תקנה בחלק זה יש לנו לעשות התקנה הטובה שנוכל ואם נתקן שיתנוהו לאחד מבני העיר שגם הוא ידיר אחד מחבירו הנאה אבל הנשיא אינו רגיל להדיר ולהקפיד על ישראל:"],[1,"אין צריך לקנות","דאלים כחו ולכך תיקנו שיכתוב לנשיא דאין צריך לקנות שאם יתקנו לכתוב לאחר פעמים ישכחו לזכות ואתי לידי תקלה:"],[1,"שכבר כתבו אביהם","כלומר זכותם כתבו לנשיא מדורות הראשונים:"],[2,"אמאי מיתסר","בשביל שכתב חלקו לנשיא:"],[4,"עמדו אבותיהם","ראשי בית אבות שלהם והכריחום שיכתבו חלקיהם לנשיא:"],[6,"כל מתנה שאם הקדישה אינה מקודשת אינה מתנה","כלומר שאם הקדישה בעודה בידו אינה מקודשת אינה מתנה גם לשאר מינים ואסור אביו ליכנס בחצר וא\"ת והא אמר מתנה על מנת להחזיר שמה מתנה וי\"ל דהתם כל כמה דלא החזיר הוי מתנה גמורה לכל מה שירצה אבל הכא אין בידו להקנותה לשום אדם דלא נתנה אלא כדי שיאכל אביו:"],[7,"מעשה לסתור","דעד השתא לא חזינן מתנה גרועה:"],[7,"ואם הוכיח סופו על תחילתו","פירוש סוף דיבורו כגון שסיים ואינם לפניך אלא כדי שיאכל פלוני אבל אמר ליה והם לפניך שיבא אביו מדעתו קאמר ליה:"],[9,"סעודתו מוכיח עליו","שלא היה בדעתו ליתן כ\"א שיבא אביו:"]]],[["ההוא גברא דהוה ליה ברא דהוה שמיט כיפי דכיתנא אסרינהו לנכסיה עליה אמרו ליה ואי הואי בר ברך צורבא מרבנן מאי אמר להון ליקני הדין ואי הואי בר ברי צורבא מרבנן לקנייה מאי","אמרי פומבדיתאי קני על מנת להקנות הוא וכל קני על מנת להקנות לא קני","ורב נחמן אמר קני דהא סודרא קני על מנת להקנות הוא","אמר רב אשי ומאן לימא לן דסודרא אי תפיס ליה לא מיתפיס ועוד סודרא קני על מנת להקנות וקני מן השתא הלין ניכסין דהדין לאימתי קני לכי הוי בר בריה צורבא מרבנן לכי הוה הדר סודרא למריה","אמר ליה רבא לרב נחמן והא מתנת בית חורון דקני על מנת להקנות הוא ולא קא קני","זימנין אמר ליה משום דסעודתו מוכחת עליו וזימנין אמר ליה ר' אליעזר היא דאמר אפילו ויתור אסור במודר הנאה","תנן אמרו חכמים כל מתנה שאינה שאם הקדישה תהא מקודשת אינה מתנה כל לאיתויי מאי לאו לאתויי הא מילתא דשדיא בכיפי לא לאתויי לישנא בתראה דשמעתיה דרבא:","\u0001הדרן עלך השותפין\u0002"],[[0,"כיפי דכיתנא","שהיה גוזל אניצי פשתן ואית דאמרי שהיה משמט עצמו מללמוד תורה והיה עוסק באניצי פשתן:"],[0,"ואי הוה בר ברך צורבא מרבנן מאי","כלומר מה יהיה ומי יורש נכסיך:"],[0,"ליקני הדין דאי הוי בר בריה צורבא מרבנן וכו'","משום דאכתי לא הוי בר בריה בעולם והוה ליה מזכה לעובר והמזכה לעובר לא קנה:"],[1,"קני על מגת להקנות הוא","דברא בנכסי אביו לא צריך קנין הלכך מקני ליה לבריה אדעתא לאקנויי לבר בריה היא:"],[1,"וכל דקני על מנת להקנות","לא הוי קנין:"],[2,"דהא סודרא קני על מנת להקנות הוא","דהא לא מקני נותן למקנה כליו של קונה והא מקני ליה לדידיה דקא מקני ליה לההוא חפץ לקונה הכא נמי כי אמר על מנת להקנות קני:"],[3,"אי תפים ליה לא מתפיס","בתמיה דאי בעי מקנה למישקל בכנפא דסודרא ולמיקניה למישקליה לדידיה ליכא מאן דמחי ליה:"],[3,"ועוד סודרא","לא דמי לההיא כלל דאילו גבי סודרא כי תפיס ליה משמע דהכי אמר ליה קני השתא בשעת קנין על מנת להקנות וקני השתא הסודר ומקני ליה בשעת קנין החפץ אבל קני נכסי דהדין לאימת קא קני להו לכי הוי בר בריה צורבא מרבנן הלכך השתא נמי לא קני ואסור לקנות להן ובן בנו נמי לא קנה ואי בעי אביו יהיב ליה לנכסיה ולכל ' מאן דבעי:"],[4,"והא מתנת בית חורון דקני על מנת להקנות הוא ולא קני זימנין אמר ליה וכו'","דהתם היינו טעמא דלא קני דסעודתו מוכחת עליו דודאי לא יהיב ליה אלא משום סעודה ואסור הואיל ומחזי דמיתהני מיניה הכא נמי כיון דקא בעי דיאכל אבא לא קנה אידך משום דקא מתהני אביו מיניה ואהכי אסור:"],[6,"לאו לאתויי הא מילתא דשריא בכפילה","כלומר האי מעשה שמוטל בתנאי כפול דכפל לדיבוריה דאמר ליקני הדין ואי הוי בר בריה צורבא מרבנן ליקנייה לבריה דודאי לא קנה ואית דגרסי מאי לאו לאתויי הא מילתא דשמיט בכיפי מילתא דבית חורון דדמיא לאותו מעשה דכיפי דכתנא:"],[6,"לא לאיתויי לישנא בתרא דשמעתיה דרבא","דאמר לעיל אפי' א\"ל והן לפניך שיבא אבא ויאכל דאסור אבל היכא דא\"ל ליקני הדין דאי הוי בר בריה צורבא מרבנן לקנייה קני על מנת להקנות הוא:"]],[[0,"דהוה שמיט כיפי דכיתנא","אניצי פשתן היה שמיט ומקלקל אותם:"],[0,"אסרינהו לנכסיה","הדירו שלא יהנה מנכסיו בחייו ובמותו:"],[0,"אמרו לו","לאביו למה אסרת בנך אחר מותך:"],[0,"אמר ליה ליקני הדין דאי הוה ברי' צורבא מרבנן ליקני","כלומר יקנה נכסי' הללו שאם יהיה בנו צורבא מרבנן יקנה אותם לו:"],[1,"קנה על מנת להקנות הוא","שהבן קונה לעצמו כדי להקנות לבנו ולא הוי כשאר זוכים בשביל חביריהם ומועיל דכל עיקר הזכייה אינה בשביל עצמו כי אם בשביל חבירו המקבל המתנה אבל הכא אמר ליה קנה כדי שתקנה לבנך כשיהיה צורבא מרבנן וגם לעצמו לא נגמרה המתנה ולא הויא - לה כמתנה על מנת להחזיר דמסיק בקידושין (דף ו:) דמקנה בה קרקע לנותן דהתם נגמר המכירה כשאמר ליה הריני נותן לך דבר זה על מנת להחזיר ובכסף זה תקנה לי שדי אבל הכא מפרש בהדיא שאינו מקנה לו אלא ע\"מ להקנות:"],[2,"ורב נחמן אמר קני","(והכא קני) ואע\"ג דהשתא אין הבן בעולם ולא מחלק בין בא לעולם ובין לא בא לעולם ובין שמקנה לבן עצמו כדי להקנות לבנו:"],[2,"דהא סודרא","שקונין בו חליפין:"],[2,"קנה על מנת להקנות הוא","כלומר ורגילות הוא שהוא מחזיר לו הסודר ויודע הוא שלא יתקיים בידו וקני ליה שהרי יודע שמקנה הוא לו ע\"י הקנין החפץ שלו וכמו כן [הכא על מנת] להקנות הוא אע\"פ שלא תתקיים מתנה בידו קנה שפיר ויקנה אותה לבן:"],[3,"ומאן לימא לן דהך סודרא אי תפיס ליה לא מתפיס","כלומר מאן לימא לן דאי בעי לא פסיק ליה דילמא ודאי אי בעי פסיק ליה ומתנה מעליא היא (אבל) [ועוד] קני ע\"מ להקנות ליכא לדמויי לסודרא דבסודרא קני על מנת להקנות מהשתא הוא דבשעה שמקנה לו הסודר אמר לו שיקנה לו בחליפין מיד ה\"נ שמעינן מינה אם אמר להקנות מיד בשעת הקנאה קני:"],[3,"הלין נכסים לאימת קני לכי הוי צורבא מרבנן כבר הדרא סודרא למריה","ולאו דווקא סודרא ונראה דרב אשי סבירא ליה כפומבדיתאי דקני ע\"מ להקנות לשון גרוע הוא ולא גמר להקנות לו כלל ולא נגמרה המתנה כלל ולא דמי לסודר שנותנו בידו להיות קונה בו מיד אבל כשיש תרתי לריעותא שאין המתנה נגמרה לו וגם אחר זמן לאו קנייה הוא ומטעם זה נראה דאפי' אם נתן לו שטר ואמר לו קנה בשטר זה ע\"מ שתקנה בו לבנו והשטר קיים בימי הבן לאו קנייה הוא כסברא דפומבדיתאי והאי דקאמר הדרא סודרא למריה לאו דוקא אלא כלומר קניין שאינו גמור אינו מועיל להקנות בו לאחר זמן ולא דמי לסודר שקנה בו מיד - ובלא שמעתין אור\"י שאין אדם יכול להקנות חפץ לחבירו מעכשיו לאחר שלשים יום דההיא שעתא דחל הקניין הדרא סודרא למריה כי ההיא דנתקרע או שאבד למאן דאמר לכשתתן וכן משוך פרה זו ולא תהא קנוייה לך אלא לאחר שלשים יום דאם אינה עומדת באגם לא קנה דנתבטלה המשיכה ומיהו אם הקנה לו מעכשיו ע\"מ שארצה לאחר ל' ודאי נגמרה המתנה מיד קודם החזרת הסודר:"],[4,"והרי מתנת בית חורון דקני ע\"מ להקנות ולא קני","דמקני לו החצר והסעודה להקנות לאביו דלא קנה דאי קנאה א\"כ קנאה המקבל ובהיתר מקנה לה לאביו וא\"כ אמאי אסרו - ומשני משום דסעודתו מוכיח עליו שלא היה רוצה שיקנה כלל כ\"א בשביל שיסעוד אביו וא\"כ אין דעתו להקנות כלל למקבל כ\"א לאביו וכי נמי קנה ע\"מ להקנות קני בעלמא משום דמקנה שפיר למקבל אך המקבל יקנה אותה לאחר אבל הכא אין דעתו להקנות כלל למקבל כ\"א לאביו:"],[5,"וזימנין א\"ל ר\"א היא","דמחמיר במודר הנאה הלכך כי נמי קני ע\"מ להקנות קני הכא לא קני להחמיר:"],[6,"לאיתויי מאי לאו לאיתויי הא מילתא דשמיט כיפי","כלומר ע\"מ להקנות ואור\"ת גירסא דשדייה בכפילא פירוש לשון המושלך בכפילות שכפל דבריו וחזר ואמר אי הוה בר בריה צורבא מרבנן ליקני ע\"מ להקנות:"],[6,"לאיתויי לישנא בתרא דרבא","אי אמר והם לפניך אסור:"]]],[["מתני׳ \u0001הנודר\u0002 מן המבושל מותר בצלי ובשלוק אמר קונם תבשיל שאיני טועם אסור במעשה קדרה רך ומותר בעבה ומותר בביצה טורמוטא ובדלעת הרמוצה הנודר ממעשה קדרה אין אסור אלא ממעשה רתחתה אמר קונם היורד לקדרה שאיני טועם אסור בכל המתבשלין בקדרה:","\u0001גמ׳\u0002 תניא ר' יאשיה אוסר ואע\"פ שאין ראיה לדבר זכר לדבר שנא' (דברי הימים ב לה, יג) ויבשלו את הפסח באש כמשפט","לימא בהא קמיפלגי דרבי יאשיה סבר הלך אחר לשון תורה ותנא דילן סבר בנדרים הלך אחר לשון בני אדם","לא דכולי עלמא בנדרים הלך אחר לשון בני אדם מר כי אתריה ומר כי אתריה באתרא דתנא דילן לצלי קרו ליה צלי ולמבושל קרו ליה מבושל באתרא דר' יאשיה אפילו צלי קרו מבושל","והא קרא נסיב לה אסמכתא בעלמא:","קונם תבשיל כו': והא מתבשיל נדר","אמר אביי האי תנא כל מידי דמתאכל ביה ריפתא תבשיל קרו ליה והתניא הנודר מן התבשיל אסור בכל מיני תבשיל ואסור בצלי ובשלוק ובמבושל ואסור בהיטריות רכות שהחולין אוכלין בהן פיתן","איני והא רבי ירמיה חלש על לגביה ההוא אסיא לאסיוה חזא קרא דמחת בביתיה שבקיה ונפק אמר מלאך מותא אית ליה לדין בביתיה ואנא איעול לאסאה יתיה","לא קשיא הא ברכיכי הא באשוני רבא בר עולא אמר הא בקרא גופיה והא בגוויה דקרא דאמר רב יהודה לוליבא דקרא בסילקא לוליבא דכיתנא בכותחא ודבר זה אסור לאומרו בפני עם הארץ","רבא אמר מאן חולין רבנן רבא לטעמיה דאמר רבא"],[[0,"מתני' הנודר מן המבושל מותר בצלי ובשלוק","מבושל מבושל כראוי:"],[0,"שלוק","מבושל יותר מדאי:"],[0,"קונם תבשיל שאיני טועם","כל תבשיל במשמע:"],[0,"מעשה קדרה רך","שיש בה רוטב:"],[0,"אבל לא בעבה","כגון דייסא:"],[0,"","טורמוטא הרמוצה מפרש בגמ':"],[0,"רתחתא","דבר הרותח כגון רוטב וכל דדמי ליה:"],[0,"היורד לקדרה","דמשמע בין צונן בין רותח:"],[0,"אסור בכל המתבשלין","בין רך בין עבה:"],[1,"גמ' ר' יאשיה אוסר","בצלי ובשלוק דמתקרי נמי מבושל:"],[2,"הלך אחר לשון בני אדם","דאין דרכם לקרות לצלי מבושל:"],[5,"והא מתבשיל נדר","דמשמע בין רך בין עבה:"],[6,"האי תנא","דמתניתין דלא קרי לעבה תבשיל:"],[6,"בכל מידי דמתאכלא ביה ריפתא","דמלפתין בו את הפת קרי תבשיל:"],[6,"והא תניא","בניחותא:"],[6,"בהיטריות רכות","בדילועין רכות שהחולין אוכלין בהן פיתן:"],[7,"איני","מי אוכלין החולין מהן:"],[7,"חזא קרא דמחיתא","דלעת מונחת שם שהיה אוכל ממנה:"],[8,"לוליבא דקרא בסלקא","תוכו של דלעת יפה לאכול עם התרדין:"],[8,"לוליבא דכיתנא","תוכן של זרעוני פשתן יפים לאכלן בכותח:"],[8,"ודבר זה אסור לאומרו בפני עם הארץ","משום דדבר מעולה הוא לרפואה ואסור לומר להם שום דבר שיהנו ממנו ואית דאמרי דלא ליכלו טובא וליפסדו כיתנא:"],[9,"חולין רבנן","שעוסקין בתורה ואינם נהנים מן העולם ובאים לידי חולי:"]],[[0,"מתני' הנודר מן המבושל מותר בצלי ובשלוק","שלוק שאין מבושל יותר:"],[0,"קונם תבשיל שאני טועם אסור במעשה קדירה רך","מפרש בגמרא כל מידי שנותנין בו פת לשרות קרוי תבשיל ומותר בעבה שאינו נאכל עם פת וצ\"ע אמאי שני למיתני ענין אחר מרישא לפלוג בנודר מן התבשיל בלא שאומר שאני טועם ובשאר בבי כבוש ושלוק ומליח נקט דווקא שאני טועם להוסיף בו איסור וי\"ל רבותא נקטי' דאפ\"ה מותר בעבה וברישא מצי למיתני מבושל שאני טועם מותר בצלי ובשלוק אלא לא היה תופס חידוש [בהאי] דמבושל לא משמע בשום ייתור צלי ושלוק:"],[0,"[טורמוטא והרמוצה]","מפרש בגמ':"],[1,"רבי יאשיה אוסר בצלי ואע\"פ שאין ראיה לדבר זכר לדבר","ולכך לא הוי ראיה דבנדרים הלך אחר לשון בני אדם:"],[5,"והא מן תבשיל נדר","ורך לא הוי תבשיל כיון שהוא רק כמים בעלמא:"],[6,"בהיטריות","פירוש קרייאני:"],[7,"","[איני] וכי קרי טובים לחולים וכו':"],[8,"ברכיכי","מועילים לחולים:"],[8,"באשוני","פירוש קשות הם רעות לחולה שאינן מבושלות כצורך:"],[8,"בקרא גופה","פירוש חיצון שבקרא קשה הוא ורע לחולה:"],[8,"בגויה","רך שבתוכו יפה לחולה:"],[8,"לוליבא דקרא","כל דבר שהוא [רך] קרי לוליבא:"],[8,"בכותח","טוב ליתן בכותח:"],[8,"ודבר זה אסור לאומרו בפניהם","שמלעיגים עלינו ואומרין שאנו קובעים מילי דחוכא ואיטלולא בהש\"ס ובקונט' פירש שאסור ללמוד להם שום תקנה ולא נראה:"],[9,"מאן חולין","דקתני לעיל שהחולין אוכלין כו':"],[9,"רבנן","שמתוך שעמלים בתורה הם חלשים אבל לחולין ממש לא מעלי:"],[9,"רבא לטעמיה","דרבנן איקרו חולים:"]]],[["כמאן מצלינן על קצירי ועל מריעי [כמאן כר' יוסי] מדאמר קצירי ומריעי שמע מינה קצירי קצירי ממש מריעי רבנן:","ומותר בעבה: מתני' דלא כבבלאי דאמר ר' זירא בבלאי טפשאי דאכלי לחמא בלחמא","א\"ר חסדא דמשאיל להון להלין נקדני דהוצל הדין דייסא היכין מעלי למיכלה דחיטי בלחמא דחיטי ודשערי בלחמא דשערי או דלמא דחיטי בדשערי ודשערי בדחיטי","רבא אכליה בחסיסי רבה בר רב הונא אשכחי' לרב הונא דקאכיל דייסא באצבעתיה אמ' ליה אמאי קאכיל מר בידיה א\"ל הכי אמר רב דייסא באצבעתא בסים וכל דכן בתרתין וכל דכן בתלת","אמר ליה רב לחייא בריה וכן אמר ליה רב הונא לרבה בריה מזמנים לך למיכל דייסא עד פרסה למיכל בישרא דתורא עד תלתא פרסין אמר ליה רב לחייא בריה וכן א\"ל רב הונא לרבה בריה כל מידעם לא תפלוט קמיה רבך לבר מן קרא ודייסא שהן דומין לפתילתא של אבר ואפילו קמי שבור מלכא פלוט","רבי יוסי ורבי יהודה חד אכיל דייסא באצבעתיה וחד אכיל בהוצא א\"ל דאכיל בהוצא לדאכיל באצבעתיה עד מתי אתה מאכילני צואתך אמר ליה דאכיל באצבעתיה לדאכיל בהוצא עד מתי אתה מאכילני רוקך","רבי יהודה ורבי שמעון אייתו לקמייהו בלוספיין רבי יהודה אכל ר' שמעון לא אכל א\"ל רבי יהודה מאי טעמא לא אכיל מר אמר ליה ר' שמעון אלו אין יוצאין מבני מעים כל עיקר אמר ליה רבי יהודה כ\"ש שנסמוך עליהן למחר","רבי יהודה הוה יתיב קמיה דר' טרפון אמר ליה רבי טרפון היום פניך צהובין אמר ליה אמש יצאו עבדיך לשדה והביאו לנו תרדין ואכלנום בלא מלח ואם אכלנום במלח כל שכן שהיו פנינו צהובין","אמרה ההיא מטרוניתא לרבי יהודה מורה ורוי אמר לה הימנותא בידא דההיא איתתא אי טעימנא אלא קידושא ואבדלתא וארבעה כסי דפסחא וחוגרני צידעי מן הפסח עד העצרת אלא (קהלת ח, א) חכמת אדם תאיר פניו","אמר לי' ההוא צדוקי לרבי יהודה פניך דומין אי כמלוי רבית אי כמגדלי חזירין א\"ל ביהודאי תרוייהו אסירן אלא עשרים וארבעה בית הכסא אית לי מן ביתא עד בי מדרשא וכל שעה ושעה אני נכנס לכל אחד ואחד","ר' יהודה כד אזיל לבי מדרשא שקיל גולפא על כתפיה אמר גדולה מלאכה שמכבדת את בעליה רבי שמעון שקיל צנא על כתפיה אמר גדולה מלאכה שמכבדת את בעליה","דביתהו דרבי יהודה נפקת נקטת עמרא עבדה גלימא דהוטבי כד נפקת לשוקא מיכסיא ביה וכד נפיק רבי יהודה לצלויי הוה מיכסי ומצלי וכד מיכסי ביה הוה מברך ברוך שעטני מעיל","זימנא חדא גזר רבן שמעון בן גמליאל תעניתא ר' יהודה לא אתא לבי תעניתא אמרין ליה לא אית ליה כסויא שדר ליה גלימא ולא קביל"],[[0,"מצלינן אקצירי","רופא חולי עמו ישראל:"],[0,"מריעי","על פליטת סופריהן:"],[1,"מתניתין","דקתני דעבה לא מיתאכלא בריפתא:"],[1,"דלא כבבלאי","דמלפתי פיתן בדייסא דהויא עבה:"],[2,"נקדני","דייקנים במאכל:"],[2,"[היכין מעלי]","באיזה דבר מעולה אכילת הדייסא:"],[2,"דחיטי","יכול לאכלה בלחם של חטים ודייסא דשערי יכול לאכלה בלחם של שעורים:"],[2,"או דילמא","דייסא של חטים יפה לאכול בשל שעורים ושל שעורים בשל חטים ואית דגרסי נקרני מלשון כי קרן עור פניו (שמות ל״ד:כ״ט) מלאים חכמה ומאירה פניהם שנא' חכמת אדם תאיר פניו:"],[3,"אכלה בחסיסי","היה מלפת פיתו בחסיסי ומפרש לה במסכת פסחים (דף לט:) קימחא דאבישונא קמח של קליות שעורים שלא הביאו שליש ומיבשין אותן בתנור וקלופין הן:"],[4,"מזמני לך לאכל דייסא עד פרסה","דע שאותו מאכל איכו סועד לבך אלא עד הילוך פרסה. ובשר השור עד שלש פרסאות: ע\"א אי מזמני לך לאכול דייסא עד פרסה לך אחר דייסא לאכול וטפי לא ולאכול בשר שור לך עד שלש פרסאות:"],[4,"כל מידעם לא תפלוט קמי רבך","לא תרוק רוק בפני רבך כדאמר במס' עירובין (דף צט.) הרק לפני רבו חייב מיתה שנאמר וכל משנאי אהבו מות אבל אם אכלת דלעת ודייסא ונזדמן לך הרוק בפיך פלוט בפני רבך וזרוק אותו לחוץ שיש בו סכנת נפשות שהן קשין לגופו של אדם כפתילה של אבר:"],[4,"ואפילו לפני שבור מלכא פלוט","ואל תתבייש:"],[5,"צאתך","עפרורית שבצפרניו:"],[5,"עד מתי אתה מאכילני רוקך","שהיה נותן ההוצא בפיו ומדביק בו הרוק שבפיו ומחזירו בקערה:"],[6,"בלוספיין","תאנים שנתבשלו יותר מדאי:"],[6,"","כיון שאין יוצאין מבני מעים:"],[6,"כ\"ש","דמעלו שנסמוך עליהן שאין אנו צריכים לאכול מאכל אחר למחר:"],[8,"מורה ורוי","אתה תלמיד בעל הוראה ואתה שיכור מפני שהיו פניו צהובין כל שעה:"],[8,"הימנותא בידא דההיא איתתא","אמונתי בידך שאיני שותה כל השנה יין אלא קידושא ואבדלתא:"],[8,"וחוגר אני צדעי","וקושר אני צדעי פדחתי משום מיחוש ראשי מפני ד' כוסות ששתיתי שאני חושש מהן מפסח עד עצרת:"],[9,"אי כמלוי ברבית כו'","שהן מרויחין ביותר ופניהן צהובין ויפין:"],[9,"תרוייהו","לגדל חזירין ולהלוות ברבית אסירי ליהודאי ודאי לאו מינייהו פני צהובין:"],[10,"שקיל גולפא","היה נושא הקנקן לבית המדרש לישב עליה:"],[10,"מלאכה שמכבדת כו'","דעכשיו ישב עליה בבית המדרש:"],[11,"נפקת נקטת עמרא","יצאת לשוק וקנתה לצמר ועבדה גלימא:"],[11,"דהוטבי","ועשתה ממנו סרבל טוב:"],[11,"וכד נפקת","איהי לשוקא הות ניכסי ביה:"],[11,"","ורבי יהודה כד הוה מצלי הוה נמי מכסי ביה:"],[11,"שעטני מעיל","שתיה להן חביב כל כך שלא היה להן אחר:"]],[[0,"כמאן מצלינן האידנא על החולים כר' יוסי","דאמר אדם נדון בכל יום דאילו למאן דאמר דנדון בראש השנה הוי תפלת שוא:"],[1,"מתני' דלא כבבלאי דאכלי דייסא בנהמא","וא\"כ גם תבשיל עבה אסור לדידהו:"],[2,"איכא דמשאיל להני נקרני","פירוש מי ימצא שישאל להני נקיי הדעת כמו נקיר שמיה (פסחים קיא:) וכן לנקר חצירו (ביצה ח:) ויש מפרשין נקדני כמו (ברכות נ -) הנקדנין תופסים אותו ע\"כ וכל המדקד' בדברי' נקרא נקדן:"],[3,"בחסיסי","קמח של קליות וכן פר\"י (פרק כל שעה ד' לט) ור\"ח פירש קמח של עדשים ופירושו נראה יותר דלפרש\"י היה לו לקרותו קימחא דאבישונא ועוד אמר פ' כל שעה ממחו ליה קדרה בחסיסי ואי קימחא דאבשונא הא אמר לעיל מיניה בההוא פירקא דאסור:"],[4,"לפלוט","כלומר אם יצטרך לרוק ירוק ואל יניח בשביל כבוד רבו:"],[6,"בלוספיין","מין תאנים רעים:"],[6,"כל שכן דנסמוך עליהם למחר","שלא יתעכלו מהר וכל זמן שהמאכל בתוך הבני מעיים הלב נסעד:"],[8,"וחוגרני צדעי","פירוש חוגר וקושר היה צדעיו לפי שהיה חש בראשו על היין ששתה בפסח:"],[10,"שקיל גולפא","לישב בבית המדרש:"],[10,"שמכבדת בעליה","שלא אצטרך לישב על גבי קרקע:"],[11,"שעטני מעיל","חשוב היה לו כמעיל:"]]],[["דלי ציפתא ואמר ליה לשלוחא חזי מאי איכא מיהו לא ניחא לי דאיתהני בהדין עלמא","ר' עקיבא איתקדשת ליה ברתיה (דבר) דכלבא שבוע שמע (בר) כלבא שבוע אדרה הנאה מכל נכסיה אזלא ואיתנסיבה ליה","בסיתוא הוה גנו בי תיבנא הוה קא מנקיט ליה תיבנא מן מזייה אמר לה אי הואי לי רמינא ליך ירושלים דדהבא אתא אליהו אידמי להון כאנשא וקא קרי אבבא אמר להו הבו לי פורתא דתיבנא דילדת אתתי ולית לי מידעם לאגונה אמר לה ר' עקיבא לאנתתיה חזי גברא דאפילו תיבנא לא אית ליה","אמרה ליה זיל הוי בי רב אזל תרתי סרי שנין קמי דר' אליעזר ור' יהושע למישלם תרתי סרי שנין קא אתא לביתיה שמע מן אחורי ביתיה דקאמר לה חד רשע לדביתהו שפיר עביד ליך אבוך חדא דלא דמי ליך ועוד [שבקך] ארמלות חיות כולהון שנין אמרה ליה אי צאית לדילי ליהוי תרתי סרי שנין אחרנייתא אמר הואיל ויהבת לי רשותא איהדר לאחורי הדר אזל הוה תרתי סרי שני אחרנייתא","אתא בעשרין וארבעה אלפין זוגי תלמידי נפוק כולי עלמא לאפיה ואף היא קמת למיפק לאפיה אמר לה ההוא רשיעא ואת להיכא אמרה ליה (משלי יב, י) יודע צדיק נפש בהמתו אתת לאיתחזויי ליה קא מדחן לה רבנן אמר להון הניחו לה שלי ושלכם שלה הוא שמע (בר) כלבא שבוע אתא ואיתשיל על נידריה ואשתריי ואשתרי","מן שית מילי איעתר רבי עקיבא מן כלבא שבוע מן אילא דספינתא דכל ספינתא עבדין ליה מין עינא זימנא חדא אנשיוה על כיף ימא אתא הוא אשכחיה","ומן גווזא דזימנא חדא יהיב ארבעה זוזי לספונאי אמר להו אייתי לי מדעם ולא אשכחו אלא גווזא על כיף ימא אתיוה ליה אמרו ליה עביד מרנא עליה אישתכח דהוה מלי דינרי דזימנא חדא טבעת ספינתא וכולי עיסקא הוה מחית בההוא גווזא ואישתכח בההוא זימנא","דמן דסרוקיתא ומן מטרוניתא"],[[0,"דלי ציפתא","הגביה המחצלת שהיה יושב עליה:"],[0,"ואמר ליה לשלוחא","דאזל לביתיה:"],[0,"חזי מאי איכא","ראה כמה עושר יש לי שנעשה לו נס ונתמלא כל אותו מקום זהובים:"],[1,"ואיתנסיבת ליה בסיתוא","בימות החורף:"],[2,"הוה גנו בי תיבנא","היו ישנים בין התבן שלא היו להם כרים וכסתות:"],[2,"קא מנקיט ליה תיבנא מן מזייה","היה מלקט התבן משערו:"],[2,"אי הוי לי רמינא לך ירושלים דדהבא","אם יהיה לי סיפוק שאתעשר אעשה לך ירושלים של זהב בתי נפש שמצויירת בכל ענייני ירושלים והיינו דאמרינן במסכת שבת (דף נט.) עיר ירושלים של זהב כדעבד ליה רבי עקיבא לדביתהו:"],[2,"אתא אליהו קרא אבבא וכו'","עבד הכי משום קורת רוח להן דלדידיה לא היה לו אפילו תבן כמו להם:"],[3,"שפיר עביד ליך אבוך","דאדריך מנכסיה:"],[3,"חדא דלא דמי לך","שהוא גרוע ממך ועוד שמניחך באלמנות חיות שהרי הניחך כמה שנים:"],[4,"יודע צדיק נפש בהמתו","אית דאמרי דאיהי הות ידעה דר' עקיבא הוה ואמרה ליה דלא מיתגניא בעיניה ואית דאמרי דלא הות ידעה אלא הכי קא אמרה דצדיק לא מבזה לאינשי:"],[4,"שלי ושלכם שלה היא","על ידה הוא כל מה שלמדתי:"],[5,"מן שית מילי איעתר רבי עקיבא מן כלבא שבוע","דפליג ליה בנכסיה.:"],[5,"ומן אילא דספינתא דכל ספינתא עבדין ליה מן עינא","עושין להן מן אותו ענין של איל ואית דגרסי מין עיינא היו עושין כמין צאן של עץ והיו נותנים בו כספם:"],[5,"אנשיוה על כיף ימא","ששכחו לאותו איל על שפת הים ומצאו רבי עקיבא:"],[6,"ומן גווזא","תיבה:"],[6,"ארבעה זוזי לספונאי","ליורדי הים לריוח:"],[6,"אייתו לי מדעם","הביאו לי שום דבר:"],[6,"מרנא עליה","ימתין אדונינו עליו עד שנביא לך יתר:"],[6,"דזימנא חדא טבעה ספינתא","וכל ממונא דהוה בספינתא הוה מונח בההוא גווזא:"],[7,"ומן מטרוניתא","שפעם אחת הוצרכו חכמים ממון הרבה לבית המדרש ושיגרו את ר' עקיבא אצל מטרוניתא אחת ולוה ממנה ממון גדול וכשנתנה לו אמרה לו מי יהיה לי ערב שתפרע לי לזמן קבוע אמר לה מי שתרצה אמרה לו הקב\"ה והים שהיה ביתה על שפת הים אמר לה ר\"ע כן יהיה כשהגיע הזמן חלה ר\"ע ולא היה יכול להביא הממון יצאת אותה מטרוניתא על שפת הים ואמרה רבש\"ע גלוי וידוע לפניך כי לך ולים הזה האמנתי מעותי הכניס הקב\"ה רוח שטות בלבו של קיסר ונכנס' לבית גנזיו ונטלה קרטלית וזרקה לים והשליכה הים לפתח ביתה של אותה מטרוניתא ונטלתה ולאחר זמן הביא לה ר' עקיבא הממון ואמר לה אל יחר ליך שלא הבאתי לך הממון בזמן שקבענו שחליתי אמרה לו יהא הכל שלך שממוני בא לידי בזמנו וספרה לו כל המעשה ונתנה לו מתנות גדולות ופטרתו לשלום:"]],[[0,"דלי ציפתא","פירוש הגביה המחצלת וסמך שימצא שם מעות הרבה בנס:"],[2,"גני בתיבנא","מחמת עוני:"],[2,"מנקיט ליה תיבנא","ממה שנאחז לו בשערו:"],[2,"רמינא ליך ירושלים דדהבא","וכן עשה כדאיתא בשבת (דף נט.):"],[3,"דלא דמי ליך","אינו ראוי והגון לך:"],[5,"אילא דספינתא","כל הספינות עושין להם איל של זהב:"],[7,"ומן מטרונית'","פעם אחת הוצרכו תלמידי רבי עקיבא למעות הלכו אצל מטרוניתא ללוות ממנה אמרה להם איני מאמנת אמר לה רבי עקיבא מי את חפצה שאתן ליך ערב אמרה לו מי שאמר והיה העולם וים הגדול וכשהגיע הזמן חלה רבי עקיבא ולא בא הלכה על שפת הים אמרה רבש\"ע היום חלה רבי עקיבא עבדך והוא העמידך ערב לי מה עשה הקב\"ה באותו היום נשטית בת קיסר ונטלה קופסא מליאה כסף וזהב והטילה לים וצפה ובאת לאותו מקום ונטלה אותו ומצאה בה ממון גדול וכשנתרפא רבי עקיבא בא אצלה ואמר גלוי וידוע לפני מי שאמר והיה העולם שחליתי באותו הזמן עכשיו הרי כל ממונך בידי וסיפרה לו כל המעשה והכניסתו בבית גנזיה ונתנה לו מתנות גדולות:"]]],[["ומן אשתו של טורנוסרופוס ומן קטיעא בר שלום:","רב גמדא יהיב ד' זוזי לספונאי לאתויי בהון מידעם לא אשכחו אתיוה ליה בהון קופא אישתמיט על לחרתא חפרו בתריה אשכחוה דרביע על מרגלייתא אייתינון ליה כולהון","אמרה ליה בת קיסר לרבי יהושע בן חנניה תורה מפוארה בכלי מכוער א\"ל למדי מבית אבוך במה מניחין יין אמרה ליה במאני דפחרא אמר לה כולי עלמא בפחרא ואתון במאני דפחרא אתון אחיתון במאני דכספא ודהבא","אזלת ורמת חמרא במאני דכספא ודהבא וסרי אמר לה אף אורייתא כן והאיכא שפירין וגמירין אמר לה אי הוו סנו הוו גמירין טפי","ההיא דאתיא לקמיה דרב יהודה מנהרדעא לדינא ואיתחייבת מן דינא אמרה ליה שמואל רבך הכי דנן אמר לה ידעת ליה אמרה ליה אין גוצא ורבה כריסיה אוכם ורבה שיניה אמר לה לבזוייה קאתית תיהוי ההיא אתתא בשמתא פקעה ומתה:","ומותר בביצה טורמיטא: מאי ביצה טורמיטא אמר שמואל עבדא דעביד לה שוי אלפא דינרי ומעייל לה אלפא זימני במיא חמימי ואלפא זימני במיא קרירי עד דמתזוטרא כי היכי דבלעיתה ואם אית כיבא סריך עלה וכד נפקא ואתיא ידע אסיא מאי סמא מתבעי ליה ובמאי מתי","שמואל הוה בדיק נפשיה בקולחא עד דמסתרין אינשי ביתיה עליה שעריהון","תנן התם היה עושה בכלופסין לא יאכל בבנות שבע בבנות שבע לא יאכל בכלופסין מאי כלופסין מינא דתאיני דעבדין מנהון לפדי","ההוא גברא דיהב עבדא לחבריה לאגמוריה אלפא מיני לפדי אגמריה תמני מאה אזמניה לדינא לקמיה דרבי אמר רבי אבותינו אמרו נשינו טובה אנו אפילו בעינינו לא ראינו","רבי עבד ליה הלולא לר\"ש ברבי כתב על בית גננא עשרין וארבעה אלפין ריבואין דינרין נפקו על בית גננא דין ולא אזמניה לבר קפרא אמר ליה אם לעוברי רצונו כך לעושי רצונו על אחת כמה וכמה אזמניה אמר לעושי רצונו בעולם הזה כך לעוה\"ב עאכ\"ו:","יומא דמחייך ביה רבי אתיא פורענותא לעלמא א\"ל לבר קפרא לא תבדיחן ויהיבנא לך ארבעין גריוי חיטי א\"ל ליחזי מר"],[[0,"ומן אשתו של טורנוסרופוס","אדון אחד ששמו רופוס והיה מפטפט בדברי תורה כנגד ר\"ע והיה ר\"ע מנצחו בכל פעם והיה אותו אדון מתבייש ובא וסיפר לאשתו אמרה לו אני אפתהו ואכשילהו לפי שהיתה יפת תואר ביותר באתה אצלו וגילתה שוקה כנגדו ורק ר\"ע ושחק ובכה אמרה לו מדוע עשית כן אמר לה השנים אומר לך מה שרקקתי בשביל שמטיפה סרוחה באת ובכיתי בשביל שיופיך עתיד לבלות בארץ ומה ששחק לא רצה לומר לה אעפ\"כ הפצירה בו עד שאמר לה שעתידה להתגייר ותנשא לו אמרה לו וכי יש תשובה אמר לה הן ונתגיירה לאחר שמת בעלה ונשאת לו והביאה לו ממון גדול:"],[0,"מן קטיעא בר שלום","מפורש במסכת ע\"ז בפ\"ק (דף י:):"],[1,"קופא","קוף:"],[1,"על לחרתא","נכנס הקוף בחור אחד בקרקע:"],[1,"רביע","רובץ:"],[4,"הכי דנן","כמו שדנתני אתה בתמיה:"],[4,"ידעת ליה","מכרת אותו:"],[4,"ורבה כריסיה","בטן גדול יש לו:"],[5,"טורמיטא עבדה דעביד ליה","לההיא ביצה טורמיטא שווי אלפא זוזי:"],[5,"עד דמתזוטרא","שמתמעטת כדי שיכול לבולעה שלימה:"],[5,"ואי אית ביה כיבא","במעיו סריך עליה על ההיא ביצה וניכר בה:"],[5,"וכדנפקא ממעיו","שלימה ידע אסיא כו':"],[6,"הוה בדיק נפשיה בקולחא","היינו דומיא דביצה טורמיטא והיה מפשפש כל מעיו אם יש בהן כאב והיה מתחלש ומתעלף כל כך עד שאשתו בוכה עליו ותולשת שערה מחמת דאגה:"],[7,"היה עושה","הפועל שמלקט לו בכלופסין:"],[7,"לא יאכל בבנות שבע","שלא הרשתו התורה לאכול אלא מאותו המין שהוא מלקט דכתיב כי תבא בכרם רעך ואכלת ענבים וגו' (דברים כג):"],[7,"לפדי","מיני מאכל:"],[8,"לאגמורי אלפא מיני לפדי","שילמדו לעשות אלף מיני מאכל:"],[8,"אזמניה לדינא","על מאתים מין שלא לימדו:"],[8,"אבותינו אמרו נשינו טובה","דכתיב נשיתי טובה (איכה ג׳:י״ז) שראוה כבר אלא שעכשיו שכחוה אבל אנו לא ראינו טובה מעולם שאין אנו יודעים כמה מיני טעם יש בפירות כלומר דבר מופלא הוא שכל כך לימדו:"],[9,"לא אזמני' לבר קפרא","לפי שהיה איש בדחן ומתיירא שמא יעשה שום דבר שישחוק:"],[9,"אמר","בר קפרא לרבי אם לעוברי רצונו משפיע לו טובה כ\"כ לעושי רצונו כו' שהיה מגנהו על שלא זימנו:"],[9,"לעושי רצונו","משפיע לו בעוה\"ז טובה כ\"כ שהתחיל לספר בשבחו בשביל שזימנו:"]],[[0,"אשתו של טורנוסרופוס","שהיה ר\"ע מקפח טורנוסרופוס לפני קיסר בקראי פעם אחת הלך לביתו זועף אמרה לו אשתו מפני מה פניך זועפים היום אמר לה מפני פלוני שמצער אותי אמרה לו אלהיהם של אלו שונא זימה תן לי רשות ואכשיל אותו בדבר עבירה והלכה וקישטה עצמה ובאת לפני רבי עקיבא כשראה אותה רקק ושחק ובכה אמרה ליה פרש לי שלשה דברים הללו אמר לה שתים אפרש והשלישית לא אפרש מה שרקקתי שאת כותית ובאת מטיפה סרוחה ופסולה מה שבכיתי על האי שופרא דבלי בארעא ומה ששחק לה לא פירש לה והוא שחק לפי שראה ברוח הקודש שעתידה להתגייר ולהנשא לו אמרה לו יש לי תשובה אמר לה הן הלכה ונתגיירה והכניס' לו ממון הרבה ונשאה:"],[0,"קטיעא בר שלום","פ\"ק דע\"ז (דף י:) מפ':"],[1,"קופא","קוף:"],[1,"לחרתא","לחור:"],[1,"דרביע","רבוץ:"],[1,"אייתינהו נהליה","מדת חסידות עשו לו ולא מן הדין אלא אמרו אחרי אשר על ידי גלגולו בא נתנו לו:"],[3,"אי הוי סנו","פי' מכוערין:"],[5,"טורמיטא","אין בו משמעות:"],[5,"דזוטרא","ויכול לבולעה:"],[5,"סריך עלה","כלומר הכאב נדבק עליה:"],[6,"בקולחא","היינו ביצת טורמיטא והיתה בודקת כל גופו עד שהיה מפיג לבו:"],[6,"עד דמסתרין אנשי ביתי' עליה","מסירין שערן מרוב צער:"],[7,"עשה בכלופסין לא יאכל בבנות שוח","פי' בפועל קאמר שאמרה תורה שאוכל ואמר התם שאינו אוכל אלא באותו המין וכלופסין אינו ממין בנות שוח ואע\"ג ששניהם תאנים שני מינים הם:"],[7,"לפדי","תבשיל:"]]],[["דכל גריוא דבעינא שקילנא שקל דיקולא רבה חפייה כופרא וסחפיה על רישיה ואזל ואמר ליה ליכיל לי מר ארבעין גריוי חיטי דרשינא בך אחוך רבי א\"ל לאו אזהרתך דלא תבדחן א\"ל חיטי דרשינא קא נסיבנא","א\"ל בר קפרא לברתיה דרבי למחר שתינא חמרא בריקודא דאבוך ובקירקני דאמך בן אלעשה חתניה דרבי הוה ועשיר גדול הוה אזמניה לבי הילולא דרבי שמעון ברבי","א\"ל בר קפרא לרבי מאי (ויקרא כ, יג) תועבה כל דא\"ל רבי דהכין הוא תועבה פרכה בר קפרא א\"ל פרשיה את א\"ל תיתי דביתכי תירמי לי נטלא אתת רמיא ליה א\"ל לר' קום רקוד לי דאימר לך הכי אמר רחמנא תועבה תועה אתה בה","לכסא אחרינא א\"ל מאי (ויקרא יח, כג) תבל א\"ל כי עניינא קדמאה א\"ל עיביד לי דאומר לך עבד אמר ליה תבל הוא תבלין יש בה מי שניא הדא ביאה מן כולהון ביאות","אמר ליה ומאי (ויקרא יח, יז) זימה אמר ליה עיביד כי עניינא קדמאה עבד ואמר ליה זו מה היא לא יכיל בן אלעשה למיסבל קם ונפק הוא ואינתתיה מתמן","מאי בן אלעשה דתניא לא לחנם פיזר בן אלעשה את מעותיו אלא להראות בהן תספורת של כ\"ג","דכתיב (יחזקאל מד, כ) כסום יכסמו את ראשיהם תנא כעין לולינית מאי לולינית א\"ר יהודה תספרתא יחידתא היכי דמי אמר רבא ראשו של זה בצד עיקרו של זה והיינו תספורת של כהן גדול:","ובדלעת הרמוצה: מאי דלעת הרמוצה אמר שמואל קרא קרקוזאי רב אשי אמר דלעת הטמונה ברמץ","איתיביה רבינא לרב אשי רבי נחמיה אומר דלעת ארמית היא דלעת המצרית כלאים עם היונית כלאים עם הרמוצה תיובתא:","מתני' הנודר ממעשה קדרה אין אסור אלא ממעשה רתחתא אמר קונם היורד לקדרה שאני טועם אסור בכל הנעשה בקדרה:","גמ' תניא הנודר מן היורד לקדרה אסור ביורד לאלפס שכבר ירד לקדרה קודם שיורד לאלפס מן היורד לאלפס מותר ביורד לקדרה מן הנעשה בקדרה מותר בנעשה באלפס מן הנעשה באלפס מותר בנעשה בקדרה","הנודר מן היורד לתנור אין אסור אלא בפת ואם אמר כל מעשה תנור עלי אסור בכל הנעשים בתנור:"],[[0,"דבכל גריוא דבעינא","באיזה מדה שארצה אקח:"],[0,"חפייה כופרא","זיפתו מבחוץ כדי שיחזיק החטים:"],[0,"ליכיל לי","ימוד לי:"],[0,"דרשינא בך","כלומר שאתה חייב לי:"],[1,"שתינא חמרא ברקודא דאבוך","שאביך ירקד:"],[1,"ובקירקני דאמך","במזיגתה שאמך תמזוג לי הכוס:"],[2,"מאי תועבה","עשו שניהם:"],[2,"תרמי לי נטלא","תמזוג לי הכוס כמו אנטל:"],[2,"תועה אתה בה","כלומר שמניח את אשתו של היתר ותפס זו של זנות:"],[3,"[מאי תבל","דכתיב] ואשה לא תעמוד לפני בהמה לרבעה תבל הוא (ויקרא יח):"],[3,"כי עניינא קמא","תיתי דביתכי תירמי לי ולדידיה א\"ל קום רקוד לי:"],[3,"וכי תבלין יש בה","כלומר יש בביאה זו טעם מבאחרות שמנחת בעלה ונרבעת לבהמה:"],[4,"זו מאי היא","ומפרש ביבמות (דף לז:) באיש הבא על נשים הרבה וכן אשה שנבעלה לאנשים הרבה ואינה יודעת מאיזה מהם נתעברה והולידה בת נמצא אב נושא את בתו ואח נושא את אחותו על זה נאמר ומלאה הארץ זימה כלומר זו מה היא שאין אדם יודע אותה אשה שהוא נושא אם מותרת לו אם לאו:"],[4,"לא יכיל בן אלעשה למיסבל","אותו זילותא של רבי לפי שהיה עשיר גדול ולא היה יכול לראות דבר של זילותא מחמיו:"],[5,"מאי בן אלעשה","כלומר מנין דהוה עשיר:"],[5,"פיזר מעותיו","שהיה נותן ממון גדול לספר שהיה מספר לו כתגלחת של כ\"ג:"],[6,"תספורת יחידתא","שאין כמותה:"],[7,"הרמוצה קרא קרקוזאי","דלועין של אותו מקום שאינן מתבשלין לעולם יפה:"],[7,"הטמונה ברמץ","עפר של גחלים דלאו תבשיל הוא:"],[8,"כלאים עם דלעת הרמוצה","אלמא דהרמוצה לאו טמונה ברמץ אלא שם מקום הוא ומין זרעים הוא:"],[9,"מתני' ממעשה רתחתא","היינו דבר שנגמר בישולו בקדרה ואינו אלא מחמשת המינין לאפוקי דבר שאין גמר בישולו בקדירה עד שמבשלין אותו באילפס:"],[9,"בכל הנעשה בקדירה","אפילו מבושל באילפס אסור:"],[10,"גמ' ביורד באילפס שכבר כו'","הואיל וקודם שמניחו באילפס מבשלו בקדרה והדר מניחו באילפס כן היה מנהגן והוי יורד לקדרה ולפיכך אסור:"],[10,"מן היורד באיליפס מותר ביורדי לקדרה","קודם שירד לאילפס:"],[10,"מן הנעשה בקדירה","לגמרי כל בישולו שאינו יורד לאילפס כלל:"],[10,"מותר בנעשה באילפס","אע\"פ שהיה קודם לכן בקדרה:"],[10,"מותר בנעשה בקדרה","בנגמר בקדרה:"]],[[0,"טחייה כופרא","טחו בכופרא:"],[0,"דיקולא","סל גדול:"],[0,"דרשינא בך","שהלויתיך ומילי דבדיחותא היה אומר:"],[1,"ברקודא דאבוך ובקורקני דאימך","כמו מרקדים טרפיי\"ד:"],[2,"תועה אתה בה","שמניחין נשותיהן והולכין אצל משכב זכור:"],[3,"תבלין יש","בביאה זו משניא הדא ביאה מכל ביאות:"],[7,"קרי קרקוזאי","דילועין של אותו מקום שאינו בכלל תבשיל:"],[7,"דלעת הטמונה ברמץ","אינו בכלל תבשיל:"],[8,"כלאים","מכלל דהרמוצה לא הוי טמונה ברמץ אלא על שם מקום הוא:"],[9,"הנודר ממעשה קדירה אינו אסור אלא במעשה רתחתא","דבר שנגמרה בקדירה ואין אסור [אלא] בדבר שנגמר בו: באילפס אסור בכל המתבשל בקדירה ואפילו גמרו באילפס:"],[10,"תנא הנודר מן היורד בקדירה אסור ביורד לאילפס","אחר שירד לקדירה דיורד לקדירה משמע שירד תחלה לקדירה:"],[10,"מן היורד [לאילפס] מותר ביורד לקדירה","תחילה אע\"פ שנגמר באילפס דיורד לעולם משמע על שם תחלת ירידתו ולא על שמ סופו:"],[10,"מן הנעשה בקדירה","משמע הנגמר הלכך מותר היורד לקדירה תחלה ונגמר באילפס:"],[11,"מן היורד לתנור אינו אסור אלא בפת","דלא איקרי יורד בתנור אלא פת בלבד:"],[11,"כל מעשה תנור עלי אסור בכל הנעשה בתנור","צ\"ע דמשמע דהחילוק בין יורד למעשה ואמאי תנא כל מעשה א\"כ ברישא ליתני כל יורד:"]]],[["\u0001מתני׳\u0002 מן הכבוש אין אסור אלא מן הכבוש של ירק כבוש שאני טועם אסור בכל הכבושים מן השלוק אינו אסור אלא מן השלוק של בשר שלוק שאני טועם אסור בכל השלוקים:","\u0001גמ׳\u0002 א\"ל רב אחא בריה דרב אויא לרב אשי אמר דכביש מאי דשליק מאי דצלי מאי דמליח מאי היכין משמע תיבעי:","\u0001מתני׳\u0002 מן הצלי אין אסור אלא מן הצלי של בשר דברי ר' יהודה צלי שאני טועם אסור בכל הצלויים מן המליח אין אסור אלא מן המליח של דג מליח שאני טועם אסור בכל המלוחים","דג דגים שאני טועם אסור בהן בין גדולים בין קטנים בין מלוחים בין תפלים בין חיים בין מבושלים ומותר בטרית טרופה ובציר הנודר מן הצחנה אסור בטרית טרופה ומותר בציר ובמורייס הנודר מטרית טרופה אסור בציר ובמורייס:","\u0001גמ׳\u0002 תניא רבי שמעון בן אלעזר אומר דג שאני טועם אסור בגדולים ומותר בקטנים דגה שאני טועם אסור בקטנים ומותר בגדולים דג דגה שאני טועם אסור בין בגדולים בין בקטנים","אמר ליה רב פפא לאביי ממאי דדג שאני טועם גדול הוא דכתיב (יונה ב, א) וימן י\"י דג גדול לבלוע את יונה והכתיב (יונה ב, ב) ויתפלל יונה אל י\"י אלהיו ממעי הדגה","הא לא קשיא דלמא פלטיה דג גדול ובלעיה דג קטן אלא (שמות ז, כא) והדגה אשר ביאור מתה קטנים מתו גדולים לא מתו אלא דגה משמע גדולים ומשמע קטנים ובנדרים הלך אחר לשון בני אדם:","הנודר מן הצחנה כו': אמר ליה רבינא לרב אשי אמר הרי עלי ציחין מאי תיבעי:","\u0001מתני׳\u0002 הנודר מן החלב מותר בקום ור' יוסי אוסר מן הקום מותר בחלב אבא שאול אומר הנודר מן הגבינה אסור בה בין מלוחה וטפלה הנודר מן הבשר"],[[0,"מתני' אינו אסור אלא בכבוש של ירק","דסתם כבוש ירק הוא אבל אמר כבוש שאני טועם הואיל ואמר כי האי לישנא אסור בכל הכבושין וה\"ה בכל הנך אם אמר בשלוק סתם אינו אסור כו' דסתם שלוק שלהן אינו אלא בשר ודעתיה לא הוי אלא בשר דדרכו להתבשל ולהשלק:"],[1,"גמ' אמר קונם דכביש עלי או דשליק עלי מאי","מי אמרינן דכביש דמי כמ\"ד הכבוש או דילמא דמי כמאן דאמר כבוש שאני טועם ואסור בכל הכבושין:"],[1,"תיבעי","כלומר תיקו:"],[3,"מתני' דג דגים שאני טועם","דג משמע גדול דגים משמע קטנים וכיון דאמר שניהם אסור בהן בין גדולים בין קטנים:"],[3,"ומותר בטרית טרופה","דג ששמו טרית ומוכרין אותו בחתיכות שלא נדר אלא מדג הנמכר שלם:"],[3,"ובציר","שעושין מקרבי דגים וכל שכן במורייס שאין עושין אותו אלא משומן של דגים:"],[3,"אסור בציר ובמורייס","דהני בכלל טרופין נינהו:"],[6,"גמ' הלך אחר לשון בני אדם","שקורין דג לגדול ודגה לקטנים להכי כי אמר דג מותר בקטנים וכי אמר דגה אסור בקטנים וכי אמר דג דגה אסור בשניהם:"],[7,"אמר הרי עלי ציחין","מי אמר דמדגים ממש קאמר ולא מדבר אחר או דילמא דמי כמאן דאמר מן הצחנה:"],[8,"מתני' מן הקום","משג\"א היינו נסיובי דחלבא דקום אינו בכלל חלב:"],[8,"אוסר","דקא סבר יש בו צחצוח חלב והוי בכלל חלב:"],[8,"מן הקום מותר בחלב","דברי הכל דחלב אינו בכלל קום:"]],[[0,"קונם מן הכבוש","שאמר קונם כבוש עלי אינו אסור אלא בכבוש של ירק דסתם כבוש משמע כבוש של ירק אבל לא כבוש שאני טועם כיון שאמר שאני טועם אסור בכל הכבושים:"],[0,"מן השלוק","סתמא הוי של ירק:"],[1,"דכבוש מאי","פירוש אם אמר קונם דכבוש עלי מאי כסתם כבוש דמי ואינו אסור אלא בכבוש ירק או דילמא כשאני טועם דמי ואסור בכל הכבושי':"],[2,"מן הצלי","סתמא הוי דבשר:"],[2,"מן המליח","סתם מליח הוי דג מליח:"],[3,"דג דגים שאני טועם","פירוש דג או דגים ורבי שמעון דאמר בגמרא דג גדולים משמע פליג אהא וי\"א דג ודגים דאמר לתרוייהו:"],[3,"בטרית טרופה","מין דג גדול שחותכין וטורפין אותו ולא מיקרי לא דג ולא דגים אלא יש להם שם בפני עצמם:"],[3,"","טרית טונינ\"א בלע\"ז וי\"מ שלכך מותר בטרית שלא נתכוון אלא בדגים שלמים:"],[3,"ומותר בציר","אע\"פ שדגים מעורבין בו וא\"צ לומר מורייס שאין בו אלא שומן דגים:"],[3,"הנודר מן הצחנה","דגים טרופים כדאמר בע\"ז (דף מ -) ובסנהדרין (דף מ: ') מוניני וצחנתא טעים ופריס להו וי\"מ דגים קטנים ולפי שהטרית חתוכה בחתיכות קטנות הוי בכלל צחנה:"],[3,"ומותר בציר ובמורייס","דאין ניכר בהם ממשות הדגים ולא נתכוון אלא לממשות הדגים:"],[3,"הנודר בטרית טרופה אסור בציר ובמורייס","טרופה ואין טרופה גדולה מזה שאין בהם רק ליחלוחית הדג ושומנו:"],[4,"תניא ר' שמעון אומר דג שאני טועם אסור בדג גדול","דדג משמע דג גדול כדכתיב וימן ה' דג גדול:"],[4,"דג דגה","פירוש שאמר שניהן בין גדולין בין קטנים משמע מייתור הלשון:"],[6,"במעי הדגה וכו' בנדרים הלך אחר לשון בני אדם","וקורין לקטנים דגה:"],[7,"הרי עלי צחיחין","כיון דאמר לשון זה משמע צחנתא זו דוקא ומותר בטרית טרופה או דלמא כנודר מן הצחנה ואסור בטרית:"],[8,"ומותר בקום","מי חלב דהואיל ופסולת חלב הוא אינו בכלל חלב ורבי יוסי אוסר דפסולת חלב הוי בכלל חלב:"],[8,"קום","מי חלב שקורין משג\"א ורבי יוסי סבר דקום בכלל חלב וכן חלב בכלל קום וי\"מ הנודר בקום מותר בחלב לדברי הכל:"],[8,"הנודר מן הגבינה אסור בין מלוחה בין תפילה","ואע\"ג דלא אכלי אינשי אלא מלוחה:"],[8,"הנודר מן הבשר מותר ברוטב ובקיפה","אע\"ג שיש בו טעם בשר ואע\"ג דקיפה הוי בשר שנקפה בשולי הקדירה דלא קרי אינשי בשר אלא חתיכות בשר שהן בעין:"],[8,"ר' יהודה אוסר","דסבר היא וטעמה:"],[8,"בבשר מותר ברוטב","לכאורה משמע דמותר בשר להחליף ולמכור וכן בנודר מן הענבים ומן התאנים: שאינו מתכוין לאסור עצמו בהנאת מין כשהוא מזכיר אבל כשאמר קונם בשר זה עלי אסור אפילו בהנאה וכי ההיא דקונם פירות הללו עלי דאסור בחילופיהן:"]]],[["מותר ברוטב ובקיפה ור' יהודה אוסר","אמר רבי יהודה מעשה ואסר עלינו רבי טרפון בביצים שנתבשלו עמו אמרו לו כן הדבר אימתי בזמן שיאמר בשר זה עלי שהנודר מן הדבר ונתערב באחר אם יש בו בנותן טעם אסור","הנודר מן היין מותר בתבשיל שיש בו טעם יין אמר קונם יין זה שאני טועם ונפל לתבשיל אם יש בו בנותן טעם הרי זה אסור:"],[[0,"מותר ברוטב","מרק:"],[0,"ובקיפה","מקפה עבה מתבלין פונדליר\"ש בלע\"'ז:"],[1,"שנתבשלו","בתוכו בשביל רוטב שנכנס בביצה ובשביל טעם בשר שהיה בבצים:"],[1,"כן הדבר","שאסור כשאמר בשר זה עלי שיש בקדרה לכשאמר כן כל מה שיש בקדרה שיש בו טעם בשר אסור:"],[1,"שהנודר מן הדבר","כגון שאמר בשר זה עלי ונתערב כו' אבל כי לא אמר בשר זה עלי אלא קונם בשר עלי דמשמע בשר ממש מותר ברוטב ובקיפה:"]],[[1,"אמר ר\"י מעשה ואסר וכו'","פירוש דכי היכי דבשר שאני טועם אסור ברוטב ה\"נ אם אמר שאני אוכל ובגמרא נמי הכי הוא כי קא מיבעי ליה בשאיני אוכל בשאיני טועם דוקא או לאו דוקא וכן לענין שלוק שאני טועם:"],[1,"אמרו לו כן הדבר","שאסורין אפילו ביצים שנתבשלו עם הבשר ואימתי בזמן שאמר בשר זה עלי דמשמע היא וטעמה שהנודר מן הדבר שאמר דבר זה עלי' וכו':"],[2,"הנודר ביין מותר בתבשיל","כרבנן דלר\"י אסור:"],[2,"קונם יין זה וכו' אסור אם יש בו בנ\"ט","וא\"ת כי נמי אין בו בנ\"ט דקונמות הוי דבר שיש לו מתירין כדאמרינן בשילהי פירקין דלקמן וי\"ל דחומר דבר שיש לו מתירין אינו נוהג אלא במין במינו אבל במין בשאין מינו אפילו יש לו מתירין בטל בששים וכן משמע בשמעתין דבצל (לקמן נדרים דף נח.):"]]],[["\u0001גמ׳\u0002 ורמינהו מן העדשים אסור באשישים ור' יוסי מתיר","לא קשיא מר כי אתריה ומר כי אתריה באתרא דרבנן קרו לחלבא חלבא ולקומא קומא באתריה דרבי יוסי לקומא נמי קרו ליה קומא דחלבא","תניא הנודר מן החלב מותר בקום מן הקום מותר בחלב מן החלב מותר בגבינה מן הגבינה מותר בחלב מן הרוטב מותר בקיפה מן הקיפה מותר ברוטב אם אמר בשר זה עלי אסור בו וברוטבו ובקיפו","הנודר מן היין מותר בתבשיל שיש בו טעם יין אמר קונם יין זה שאיני טועם ונפל לתוך התבשיל אם יש בו טעם יין הרי זה אסור:","\u0001מתני׳\u0002 הנודר מן הענבים מותר ביין מן הזיתים מותר בשמן אמר קונם זיתים וענבים אלו שאיני טועם אסור בהן וביוצא מהן:","\u0001גמ׳\u0002 בעי רמי בר חמא אלו דוקא או שאיני טועם דוקא","אי ס\"ד אלו דוקא שאיני טועם למ\"ל הא קמ\"ל דאע\"ג דאמר שאיני טועם אי דאמר אלו מיתסר ואי לא לא","אמר רבא ת\"ש קונם פירות האלו עלי קונם הן לפי אסור בחילופיהן ובגידוליהן הא ביוצא מהן מותר","ה\"ה דאפי' ביוצא מהן אסור והא עדיפא ליה לאשמועינן דחילופיהן כגידוליהן דמי","ת\"ש שאיני אוכל ושאיני טועם מותר בחילופיהן ובגידוליהן הא היוצא מהן אסור איידי דלא נסיב ברישא יוצא מהן לא נסיב נמי בסיפא יוצא מהן","ת\"ש אמר ר' יהודה מעשה ואסר רבי טרפון עלי ביצים שנתבשלו עמו אמרו לו אימתי בזמן שאמר בשר זה עלי שהנודר מן הדבר ונתערב באחר ויש בו בנותן טעם הרי זה אסור","באלו לא קא מיבעיא לן דדוקא הוא כי מיבעיא לן בשאיני טועם דוקא או לאו דוקא","ת\"ש דג דגים שאיני טועם אסור בהן בין גדולים בין קטנים בין חיים בין מבושלים ומותר בטרית טרופה ובציר","אמר רבא וכבר יצא מהן:"],[[0,"גמ' מן העדשים אסור באשישים","בלחם שמעורב בו קמח של עדשים דקסבר אשישים בכלל עדשים הם:"],[0,"ורבי יוסי מתיר","דלא הוי בכלל עדשים קשיא דרבי יוסי אדר' יוסי קשיא דרבנן אדרבנן דרבנן אסרי הכא ואמרי אשישים בכלל עדשים ובמתניתין שרו דקאמרי קומא לאו בכלל חלב הוא והכי נמי קשיא לרבי יוסי דהכא מתיר משום דסבירא ליה דאשישים לאו בכלל עדשים ובמתני' קאסר דסבירא ליה קומא בכלל חלב היא קיימא:"],[1,"קומא דחלבא","והואיל והוי בכלל חלב להכי אסור והכי נמי מתריצנא לברייתא באתריה דתנא קמא קרו ליה אשישים לפת של עדשים ובאתריה דר' יוסי לא קרו אשישים הלכך שרי ר' יוסי:"],[3,"מותר בתבשיל שיש בו טעם יין","שהרי לא נדר מטעמו של יין:"],[4,"מתני' קונם זיתים וענבים אלו שאיני טועם","הואיל ואמר טועם אסור בהן:"],[4,"וביוצא מהן","בשמן וביין:"],[5,"גמ' אלו דוקא","דמשום אלו אסור בהן וביוצא מהן או דילמא שאיני טועם דוקא דמשום דאמר שאיני טועם אסור בהן וביוצא מהן:"],[6,"אי ס\"ד אלו דוקא","ושאיני טועם לאו להכי תנא שאיני טועם למה לי:"],[6,"הא קא משמע לן דאע\"ג דאמר שאיני טועם אי אמר אלו מיתסר","ביוצא מהן אי לא לא והכי כמי [אי הוי] אמרי' ואי אמרת שאיני טועם דוקא ואלו לאו דוקא למאי תנא אלו [והוה מתרצינן] הא קמשמע לן אע\"ג דאמר אלו אי אמר שאיני טועם מיתסר ביוצא מהן אי לא לא מאי:"],[7,"פירות האלו","כיון דאמר אלו אסור בחילופיהן ובגידוליהן ודייקינן מיניה הא ביוצא מהן כגון סחט משקה מותר ושמע מינה דאלו לאו דוקא: תריץ לא תימא הא ביוצא מהן מותר אלא הוא הדין דאפי' יוצא מהן אסור דהא אלו קאמר ואלו דוקא והא דלא נקט בהדיא אסור ביוצא מהן:"],[8,"הא עדיפא לאשמועינן דחילופיהן","אע\"ג דלא הוו גופייהו כגידולין דמו:"],[9,"שאיני אוכל ושאיני טועם","כגון דלא אמר אלו טועם משמע דמדידהו גופוייהו קאמר לפיכך מותר בגידוליהן ובחילופיהן ודייקינן הא ביוצא מהן אסור דהא טועם מגופייהו קאמר אלמא דשאיני טועם דוקא:"],[9,"הוא הדין דאפי' ביוצא מהן מותר איידי דלא תנא ברישא יוצא מהן מותר","דעדיפא ליה נקט לא קתני בסיפא יוצא מהן:"],[10,"בזמן שאמר בשר זה עלי","דהוי כמ\"ד אלו עלי וש\"מ אלו דוקא:"],[12,"ומותר בציר","דהיינו ציר היוצא מהן אלמא דשאיני טועם לאו דוקא:"],[13,"אמר רבא","תריץ הא דקתני מותר בציר שכבר יצא מהן קודם שנדר ולהכי מותר אבל אם לאחר שנדר יצא מהן לעולם אימא לך דאסור ושאיני טועם דוקא:"]],[[0,"ורמינהו אסור באשישין","דפסולת עדשים (אינם) בכלל עדשים ורבי יוסי מתיר קשיא דרבי יוסי אדרבי יוסי ודרבנן אדרבנן:"],[1,"","לא קשיא דבנדרים הלך אחר לשון בני אדם [ובאתרי' דר\"י לקומא נמי קומא דחלבא:"],[2,"מן הרוטב מותר בקיפה","דקדוקי בשר אף כי איכא נתינת טעם מן הרוטב דלא אסור אלא הקרוי רוטב בלבד וכרבנן דפליגי ארבי יהודה במתני':"],[2,"","בשר מותר ברוטב בשר זה אסור ברוטבו ובמקפה אי איכא נתינת טעם:"],[5,"אלו דוקא או שאני טועם דוקא","אמתני' בעי דקתני קונם זיתים אלו שאני טועם אסור בהם וביוצא מהם ומיבעי ליה מה שאנו אוסרין יוצא מהם איירי דאמר שאני טועם דוקא אבל אם לא אמר אלא קונם אלו עלי לא מיתסר אלא (ביוצא) מהם וא\"ת היכי מצינו למימר דשאני טועם חמור מקונם אלו והא גבי חילופיהן וגדוליהן דמותר בהם [כשאמר שאני טועם] וכשאמר קונם פירות אלו - אסור ויש לומר דשאני גבי חילופיהן שאינו תלוי באלו כלל אלא בהזכרה כשאמר שאני אוכל שאני טועם דלא נתכוון לאסור כ\"א גופם לאכול ולא חילופיהן ובשלא הזכיר שאיני אוכל ואמר קונם עלי פירות כי נמי לא אמר אלו שוינהו עליה איסור בין הם בין חילופיהן אבל לענין יוצא מהם יכול להיות דאלים טפי לישנא דשאני אוכל ושאני טועם מקונם אלו:"],[6,"","דאי סלקא דעתך אלו דוקא שאני טועם ל\"ל הא קמ\"ל דאע\"ג דאמר שאני טועם אי אמר אלו אין אי לא לא [הגה\"ה ז\"ו מצאת\"י מבחו\"ץ]:"],[6,"ת\"ש שאני אוכל ושאני טועם מותר בחילופיהן","נראה דקאי אקונם פירות אלו דאע'\"ג דאמר אלו כשאמר שאני אוכל מגרע ליה איסור הנאה דגלי אדעתיה שאינו אוסר אלא באכילה אע\"ג דלענין יוצא מהם אהני שאני טועם להחמיר וראיה לדבר דהא שאני אוכל קאי נמי אפירות אלו לאידך בבא האומר לאשתו קונם מעשה ידיך אסור בחילופיהן ואיירי כגון דאמר אלו או שמא משמעות הלשון כך כשאוסר מעשה ידיה כגון אם אמר פירות אלו וקתני עלה שאני אוכל שאני טועם מותר בחילופיהן ובגידוליהן ולפירוש זה ק' דדייקא הא ביוצא מהם אסור [דלמא] שאני הכא דקאמר אלו ושאני טועם ושמא מדלא נקט התנא בהדיא בסיפא קונם פירות אלו שאני טועם אלא נקט שאני טועם גרידא משמע דאפילו לא אמר אלו אשמעינן תנא דמותר בחילופיהן ואסור ביוצא מהם:"],[6,"","ע\"ד כא\"ן הגה\"ה מהר\"ם וז\"ה מצאת\"י בפני\"ם:"],[7,"ת\"ש [קונם פירות האלו עלי וכו'] הא ביוצא מהם מותר","דאי אסור ליתני אסור ביוצא מהם וכ\"ש בחילופיהן דמשמע ליה דמסתבר טפי להתיר יוצא מהם מחילופיהן [ומשני] דאה\"נ דיוצא מהם אסור ולרבותא - נקט יוצא מהם ואשמועינן חלופיהן כגידוליהן ואסורין דאי תנא יוצא מהם אסור ה\"א דחילופיהן דשרו הואיל ולא באו מגוף האיסור עצמו:"],[9,"ת\"ש שאני אוכל שאני טועם ולא אמר אלו מותר בחילופיהן הא יוצא מהם אסור","אע\"ג דלא אמר אלו דאי מותר לישמעינן יוצא מהם וכ\"ש חילופיהם שאינם מגוף הפירות דהכי [משני] לעיל דחילופיהן עדיף לאשמועינן ברישא לאיסורא מביוצא מהם וקשה לידחי במאי דסלקא דעתך בת\"ש דלעיל דאדרבה מסתבר טפי לאיסורא חילופיהן מיוצא מהם וזיל הכא קמדחי ליה [וזיל הכא קמדחי ליה] ומשני איידי דלא נסיב רישא יוצא מהם כו' דהא שניא דהא עדיף ליה למיתני חילופיהן כגידוליהן לא נקט נמי בסיפא יוצא מהם ואע\"ג דה\"ה ודאי שרו בחילופיהן:"],[10,"בשר זה עלי כו' אסור בנותן טעם","ומדמי יוצא מהם לנ\"ט דכי היכי דאסר אדנפשיה כדאמר בשר זה עלי בנ\"ט ה\"נ אסור יוצא מהן וזה היינו כמו אלו אלמא דבאלו מיתסר יוצא מהן:"],[12,"ת\"ש ומותר בטרית טרופה ובציר","וציר היינו יוצא מהן אלמא בשאני טועם גרידא מותר יוצא מהם:"],[13,"אמר רבא שכבר יצא","פי' האי ציר דקשרי היינו בציר שיצא מהם קודם נדרו ובההוא אינו נאסר אף כשאני טועם דוקא אבל ביוצא מהם אחר נדרו (אסור) אימא לך דאסור דשאני טועם דוקא ולא איפשיטא לן אי שאני אוכל דוקא הלכך בשל תורה הלך לחומרא ובשאני טועם גרידא אסור יוצא מהם ועוד נשמעינן שאם אדם אוסר שלא יאכל בשר עד זמן פלוני שאסור ברוטב דהא בהא תליא דאי יוצא מהם אסור ה\"נ נתינת טעם אסור דמדמה לה להדדי:"]]],[["\u0001מתני׳\u0002 הנודר מן התמרים מותר בדבש תמרים מסתוניות מותר בחומץ סתוניות רבי יהודה בן בתירא אומר כל ששם תולדתו קרויה עליו ונודר הימנו אסור ביוצא הימנו וחכמים מתירים:","\u0001גמ׳\u0002 [חכמים] היינו ת\"ק","איכא בינייהו הדא דתניא כלל זה אר\"ש בן אלעזר כל שדרכו לאכול ודרך היוצא ממנו לאכול כגון תמרים ודבש תמרים נדר בו אסור ביוצא ממנו נודר מיוצא ממנו אסור בו","כל שאין דרכו לאכול ודרך היוצא ממנו לאכול נודר בו אין אסור אלא ביוצא ממנו שלא נתכוון זה אלא ליוצא ממנו:","\u0001מתני׳\u0002 הנודר מן היין מותר ביין תפוחים מן השמן מותר בשמן שומשמין מן הדבש מותר בדבש תמרים מן","החומץ מותר בחומץ סתוניות מן הכרישין מותר בקפלוטות מן הירק מותר בירקות השדה שהוא שם לוויי:","\u0001גמ׳\u0002 תניא הנודר מן השמן בארץ ישראל מותר בשמן שומשמין ואסור בשמן זית ובבבל אסור בשמן שומשמין ומותר בשמן זית מקום שמסתפקין מזה ומזה אסור בזה ובזה","פשיטא לא צריכא דרובא מן חד מסתפקין מהו דתימא איזיל בתר רובא קא משמע לן ספק איסורא לחומרא","הנודר מן הירק בשאר שני שבוע אסור בירקות הגינה ומותר בירקות השדה ובשביעית אסור בירקות השדה ומותר בירקות הגינה אמר רבי אבהו משום רבי חנינא בן גמליאל"],[[0,"מתני' מן הסתוניות","היינו ענבים קשים שמניחן בכרם כל ימי הסתיו ועושין מהן חומץ:"],[0,"כל ששם תולדתו קרויה עליו","כגון חומץ זה שיצא ממנו קרוי נמי על שם אמו חומץ סתוניות ולא חומץ סתם:"],[0,"נדר ממנו אסור ביוצא וכו'","והכי נמי כי נדר בסתוניות אסור נמי בחומץ היוצא ממנו:"],[0,"וחכמים מתירין","וקא פריך בגמרא היינו תנא קמא דקתני מותר בחומץ סתוניות:"],[2,"גמ' נדר בו","בתמרים:"],[2,"אסור ביוצא ממנו","בדבש תמרים:"],[3,"כל שאין דרכו לאכול","כגון סתוניות דדרך היוצא ממנו לאכול והן עצמן אין דרכן לאכול. תנא קמא דמתניתין דאמר מותר בחומץ סתוניות לית ליה דרבי שמעון בן אלעזר אלא קסבר נדר בו אין אסור אלא בו אע\"ג שאין דרכו לאכול וחכמים תנא בתרא אית להו דרבי שמעון בן אלעזר ודקתני וחכמים מתירים בו בגופו אבל ביוצא ממנו לא דאין אסור אלא ביוצא ממנו והיינו כר' שמעון בן אלעזר דאמר לא נתכוון זה כו' ורבי יהודה בן בתירא היה אוסר בו וביוצא הימנו:"],[4,"מתני' מן השמן","משמע שמן זית להכי מותר בשמן שומשמין:"],[5,"כרישין","קטנית:"],[5,"מותר בירקות השדה","דהיינו שם לוויי ירק השדה ולא ירק סתם:"],[6,"גמ' מותר בשמן שומשמין","לפי שאין מצוי בא\"י שמן שומשמין אלא שמן זית ובאותו שמן נדר:"],[6,"מזה ומזה","משמן זית ומשמן שומשמין:"],[7,"ספק איסורא לחומרא","ומשמן שמסתפקין בו נדר בין רב בין מעט:"],[8,"אסור בירקות","הגינה. גרי\"ס המור\"ה במסכת\"א ז\"ו ומותר בירקות השדה. שעליהן סומכין בשביעית שהפקירו הגנות לעניים ואין מסתפקין אלא בירקות השדה:"]],[[0,"הנודר מן התמרים מותר בדבש","פירוש דאמר קונם תמרים עלי מותר בדבש היוצא מהם דדבש איקרי תמרים [לא איקרי] וקשה אמאי לא תנא הכא כדקתני בשאר בבי תמרים אלו שאני טועם אסור ביוצא מהם:"],[0,"בסתוניות","ענבים קשים ורעים לאכול מותר בחומץ היוצא מהן:"],[0,"כל ששם תולדתו עליו","פירוש שאינו מפסיד שמו הראשון כמו דבש תמרים ששם תמרים עליו נדר בתמרים אסור בדבש:"],[0,"וחכמים מתירין","בגמ' פריך היינו תנא קמא:"],[1,"חכמים היינו ת\"ק","דשרי בדבש תמרים איכא בינייהו דתניא כו' כל שדרכו לאכול כו' ומיירי ששם תולדתו עליו דאל\"כ לית ליה [הנודר] בענבים מותר ביין וכל שאין דרכו לאכול כגון סתוניות שאין דרכן לאכול וחומץ שלהם דרכו לאכול:"],[3,"נדר בו אינו אסור אלא ביוצא ממנו","ת\"ק לית ליה דרבי שמעון וחכמים אית ליה דרבי שמעון [ולאו לגמרי כר\"ש סבירא להו] דודאי בדבש תמרים לא סברי כוותיה אלא בדינא דסתוניות וה\"ק וחכמים מתירים בתמרים לאכול בדבש אבל בסתוניות לא שרינן בחומץ וקשה דהוה להו למיתני וחכמים אוסרין בסתוניות והר\"ם פי' לפי מה שפירש דסתוניות אין דרכן ליאכל אלא היוצא מהם יש לפרש ת\"ק ורבי יהודה בן בתירא לית להו דר\"ש בן אלעזר דאסרו בסתוניות גופייהו ולא אסרי אלא ביוצא מהם וי\"מ איכא בינייהו דת\"ק נקט מן התמרים מותר בדבש משמע דדוקא בתמרים וסתוניות שהם ראויין אסור בהם ומותר ביוצא מהם הא נדר מדברים שאינם ראוים לאכול אסור בין בהם בין ביוצא מהם:"],[4,"מותר ביין תפוחים","דסתם יין דענבים קאמר:"],[4,"מותר בשמן שומשמין","דסתם שמן הוא שמן זית:"],[4,"מותר בדבש תמרים","דסתם דבש זהו דבש דבורים:"],[5,"מותר בחומץ סתוניות","דסתם חומץ מיין טוב שהחמיץ:"],[5,"מן הכרישין מותר בקפלוטות","אע\"פ שממין כרישין הן באו שיש להן שם לווי:"],[5,"מן הירק סתם מותר בירק שדה","דסתם ירק של גינה:"],[6,"בארץ ישראל","דסתם שמן שלהן של זית:"],[7,"מהו דתימא זיל בתר רובא","ולא נתכוין לאסור עצמו אלא באותו מין שמסתפק הרוב קמ\"ל דגם מאותו שמסתפקים המיעוט אסר עצמו:"],[8,"בשאר שני שבוע אסור בירקות גינה ומותר בירקות שדה","דסתמא מירקות גינה נדר דירקות שדה יש להם שם של לווי בכל שאר שני שבוע ומרישא שמעינן לה דקתני מותר בירקות שדה אלמא אסור בירקות גינה אבל סיפא איצטריך ליה:"],[8,"בשביעית","פירוש שנדר בשביעית דירקות שדה מצויין בשביעית שבאות מאליהן אבל ירקות גינה אינם באין אלא על ידי זריעה הלכך סתם ירקות בשביעית ירקות שדה היא:"]]],[["לא שנו אלא במקום שאין מביאין ירק מחוצה לארץ לארץ אבל במקום שמביאין ירק מחוצה לארץ לארץ אסור","כתנאי אין מביאין ירק מן חוצה לארץ לארץ רבי חנניה בן גמליאל אומר מביאין ירק מחוצה לארץ לארץ מ\"ט דמאן דאמר אין מביאין אמר רבי ירמיה משום גוש:","\u0001מתני׳\u0002 מן הכרוב אסור באיספרגוס מן האיספרגוס מותר בכרוב","מן הגריסין אסור במקפה ורבי יוסי מתיר מן המקפה מותר בגריסין מן המקפה אסור בשום ור' יוסי מתיר מן השום מותר במקפה","מן העדשים אסור באשישים ר' יוסי מתיר מן האשישים מותר בעדשים","חטה חטין שאני טועם אסור בהן בין קמח בין הפת גריס גריסין שאני טועם אסור בהן בין חיין בין מבושלין רבי יהודה אומר קונם גריס או חטה שאני טועם מותר לכוס חיים:","\u0001גמ׳\u0002 תניא ר' שמעון בן גמליאל אומר חטה שאני טועם אסור לאפות ומותר לכוס חטים שאני טועם אסור לכוס ומותר לאפות חטה חטין שאני טועם אסור בין לכוס בין לאפות","גריס שאני טועם אסור לבשל ומותר לכוס גריסין שאני טועם אסור לכוס ומותר לבשל גריס גריסין שאני טועם אסור בין לבשל בין לכוס:","\u0001הדרן עלך הנודר מן מבושל\u0002"],[[0,"(גמ') לא שנו","דשביעית מותר בירקות הגינה אלא במקום שאין מביאין ירק מח\"ל דכיון שאין מביאין ודאי לא נדר אלא מאותם שמסתפקים שם היינו מירקות השדה ולהכי מותר בשל גינה:"],[0,"אבל במקום שמביאין כו' אסור","אף בירקות הגינה הואיל ורגילין לאכול שם בין ירקות השדה בין ירקות הגינה דודאי אדעתא דהכי נדר:"],[1,"כתנאי כו'","לדעתא דמ\"ד אין מביאין ירקות כו' לדידיה מותר בירקות גינה ואסור בירקות שדה דכיון דאין מביאין לאו עליה נדר ולמ\"ד מביאין אסור אף בירקות גינה:"],[1,"משום גוש","שמא יש מעפר חוצה לארץ בעיקרייהו וטמא משום ספק מת:"],[2,"מתני' אסור באיספרגוס","דהוי בכלל כרוב דמין כרוב הוא:"],[2,"מותר בכרוב","דאין כרוב בכלל איספרגוס:"],[3,"אסור במקפה","של גריסין:"],[3,"מותר בגריסין","ד\"ה דאין גריסין בכלל מקפה:"],[3,"מן המקפה","של גריסין:"],[3,"אסור בשום","שנותנים ממנו בקדרה דהיינו בכלל מקפה:"],[3,"ר' יוסי מתיר","דקסבר אין מקפה בכלל גריסין:"],[3,"אסור בשום","של מקפה:"],[3,"מותר במקפה","דאין מקפה בכלל שום:"],[4,"אסור באשישים","בפת שמעורב בו קמח עדשים דיש בכלל עדשים אשישים:"],[4,"ומן אשישים כו'","דברי הכל היא:"],[5,"ר' יהודה אומר קונם גריס או חטה שאגי טועם מותר לכוס","חטה וגריס סתם דלא אמר חטה חטין גריס גריסין דקסבר [ר\"י גריס או חטה] מבושלים משמע חיין לא משמע ור' יהודה לא פליג עליה דתנא קמא:"],[6,"גמ' אסור לאפות","דאדעתא דהכי אמר חטה כדי לאפות דחטה גרגיר א' משמע ומגרגיר לא קאמר:"],[6,"חטין","משמע חיין:"],[7,"גריס","משמע מבושל:"],[7,"גריסין","משמע נמי חיין:"]],[[0,"","לא שנו דבשביעית מותר בירקות גינה משום דלא שכיחי שיאכלו ירקות גינה אלא במקום שאין מביאין כו' אבל במקום שמביאין שכיח הוא ירקי גינה ונתכוין לאסור ירקי גינה בשביעית:"],[1,"משום גוש","דדרך הירק להיות גוש תלוי בו וגזרו על גוש ארץ העמים:"],[2,"","איספרגוס מין כרוב הוא ובכלל כרוב הוא:"],[2,"מן האיספרגוס מותר בכרוב","דשאר כרוב אינם קרויין איספרגוס:"],[3,"מן הגריסין אסור במקפה של גריסין","שנקראת גריסין אף כשהן בתבשיל אבל מן המקפה מותר בגריסין יבשין דלא תימא דכי נדר במקפה מן הראוי למקפה קאמר והיינו גריסין ולרבנן איצטריך דאע\"ג דאסרי שום כשנדר במקפה הכא מודו:"],[3,"מן השום מותר במקפה","דלא נתכוון אלא לשום יבש:"],[4,"מן האשישים","פי' פסולת עדשים מותר בעדשים שאין העדשים נקראין אשישין מן העדשים אסור באשישים שהם נקראים על שם העדשים ור\"י מתיר דסבר דאינם בכלל עדשים:"],[5,"חטה חטין שאני טועם אסור בין בחטין בין בפת","דחיטה משמע לאפות ומיהו בברייתא בגמ' גרסינן איפכא ושמא טוב לפרש הכא חטה או חיטים גריס או גריסין אסור בין חיין בין מבושלין ורבי שמעין ורבי יהודה מחלקין בין חטה לחטין גריס גריסין כדמפרש גבי חטה חטין רבי יהודה אמר קונם גריס או חטה שאני טועם מותרין לכוס חיין דחטה וגריס משתמעי מבושלין:"],[5,"רבי יהודה אומר גריס או חטה שאני טועם מותר לכוס חיים","מדקאמר חטה וגריס סתם ולא אמר (חטה) חטין גריסין קסבר [חטה גריס] מבושלין משמע חיין לא משמע:"],[6,"חטה שאני טועם מותר לאפות","דחטה לא משמע אלא חיין חטין משמע לאפות ורבי שמעון ורבי יהודה לא פליגי דלתרוייהו גריס חטה מבושלין משמע ולא חיין גריסין חטין משמע חיין אבל לא מבושלים:"]]],[["מתני׳ \u0001הנודר\u0002 מן הירק מותר בדלועין ורבי עקיבא אוסר אמרו לו לרבי עקיבא והלא אומר אדם לשלוחו קח לי ירק והוא אומר לא מצאתי אלא דלועין","אמר להם כן הדבר או שמא אומר הוא לא מצאתי אלא קיטנית אלא שהדלועין בכלל ירק וקיטנית אינו בכלל ירק ואסור בפול המצרי לח ומותר ביבש:","\u0001גמ׳\u0002 הנודר מן הירק כו': והא מן ירק נדר אמר עולא באומר ירקי קדירה עלי ודילמא ירק הנאכל בקדרה קאמר באומר ירק המתבשל בקדרה עלי","במאי קא מיפלגי רבנן סברי כל מילתא דצריך שליחא לאמלוכי עלה לאו מיניה הוא ורבי עקיבא סבר כל מילתא דמימליך שליחא עלה מיניה הוא אמר אביי מודה רבי עקיבא לענין מלקות שאינו לוקה","תנן התם השליח שעשה שליחותו בעל הבית מעל לא עשה שליחותו שליח מעל","מאן תנא אמר רב חסדא מתניתין דלא כרבי עקיבא דתנן כיצד אמר לו תן בשר לאורחים ונתן להם כבד תן כבד ונתן להם בשר השליח מעל ואי רבי עקיבא הא א\"ר עקיבא כל מילתא דמימליך עלה שליח מיניה הוא למעול בעל הבית ולא למעול שליח","אמר אביי אפילו תימא רבי עקיבא"],[[0,"מתני' הנודר מן הירק וכו' ורבי עקיבא אוסר","דקסבר דילועין בכלל ירק:"],[0,"אלא דילועין","מכלל דלאו מיניה הוא:"],[1,"לא מצאתי אלא קיטנית","בתמיה כלומר להכי לא קאמר ליה אלא די דילועין מכלל דדילועין מיניה הוא ולא מין קיטנית:"],[1,"פול המצרי לח","הוי מין ירק:"],[1,"ומותר ביבש","שהוא מין דגן:"],[2,"גמ' אמאי אוסר ר\"ע הא מן ירק נדר","ודילועין לא איקרי ירק:"],[2,"ירקי קדרה עלי","ודילועין בכלל ירקי קדרה הן שהרי מתבשלין בקדרה:"],[2,"ודילמא","האי דקאמר ירקי קדרה עלי ירק הנאכל בקדרה עלי קאמר כגון שומים ובצלים שהן נאכלים בקדרה שנותנין אותן בקדרה כדי ליתן טעם בתבשיל:"],[2,"באומר ירק המתבשל בקדרה","דדילועין נמי הן מתבשלין בקדרה ונותנין אותן בשביל תבשיל אבל שומין אין נותנין אותן אלא בשביל טעם ולהכי ר\"ע אוסר:"],[3,"דצריך שלוחא לאימלוכי עליה","כגון דילועין כי אמר לשלוחו קח לי ירק אינו מביא לו דילועין אלא אומר לו לא מצאתי אלא דילועין ומימליך עליה וקאמר ליה דרוצה אתה שאביא לך דילועין וכהאי גוונא לאו מיניה לפיכך כי נדר בירק מותר בדילועין:"],[3,"ורבי עקיבא סבר כו'","מדקאמר ליה לא מצאתי אלא דילועין ולא אמר לא מצאתי אלא קיטנית אלמא דילועין מין ירק הוא:"],[3,"מודה רבי עקיבא","אע\"ג דאוסר בדילועין אם אכל דילועין אינו לוקה דקסבר ליכא מלקות דלא יחל דברו הואיל וצריך לאימלוכי ביה עלה:"],[5,"מתניתין","דמעילה דשליח מעל דלא כר\"ע דקתני סיפא לא עשה שליחותו שליח מעל:"],[5,"אמר לשלוחו תן בשר לאורחים ונתן להם כבד שליח מעל","דלא עשה שליחותו דאין כבד בכלל בשר:"],[5,"ואי ר\"ע","הא אמר כבד בכלל בשר הוי דמילתא דמימליך עלה שליח מיניה הוא וה\"נ אע\"ג דלא אימליך השתא אורחיה הוא לאימלוכי דכי אמר לו תן בשר לאורחין ולא היה לו בשר אלא כבד דרכו לומר אין לי אלא כבד וכמאן דמימליך דמי:"],[5,"למעול בעל הבית","דהא עשה שליחותו:"]],[[0,"מתני' הנודר מן הירק אסור בדילועין","והוא אומר לא מצאתי אלא דלועין - ואין לוקחם מיד אלמא לא קרי להו אינשי ירק:"],[1,"אמר להם כך הדבר","כלומר משם אני מביא ראיה:"],[1,"אסור בפול המצרי","דלכולי עלמא הוי בכלל ירק:"],[1,"ומותר ביבש","דלא מיקרי ירק:"],[2,"והא מן ירק נדר","ולמה אסור בדלועין שהם פירי:"],[2,"באומר ירקי קדירה עלי","כשדרכם לבשלם והני דרכם לבשלם:"],[2,"ודלמא ירק הנאכל בקדירה קאמר","כגון שומין ובצלים שהוא נאכל בקדירה כגון ליתן טעם בתבשיל:"],[2,"באומר ירק המתבשל בקדירה","מפני שהוא קשה וקסבר ר\"ע דלועין בכלל ירק המתבשלים בקדירה:"],[3,"וצריך לאימלוכי","דאין לוקח אותן בסתם (כיון) [עד] דאימליך עליה:"],[3,"מודה הוא לענין מלקות","בל יחל שאינו לוקה דמספקא ליה אי דלועין בכלל ירק ומספיקא [לא] אמר למילקיה:"],[4,"תנן התם","פרק בתרא דמעילה (דף כ.):"],[4,"בעה\"ב מעל","דגמרינן חטא חטא מתרומה מה התם ע\"י שליח אף הכא ע\"י שליח אע\"ג דבעלמא אין שליח לדבר עבירה:"],[5,"ונתן להם כבד","דכבד לאו מין בשר וכי אמר לשלוחו קח לי בשר ולא מצא אלא כבד לא מימליך עליה וכששולחו לבקש בשר אינו חוזר ואומר לא מצאתי אלא כבד אלא אומר לא מצאתי בשר כלל:"],[5,"מיניה הוא","ועשה שליחותו ולמעול בעה\"ב וקשה דרבי עקיבא מודה דאין לוקה דמספקא ליה אי מידי דמימליך עליה מיניה הוא ונראה דלא קשה כלל דדוקא בדלועין דלאו ירק הוא אלא פירי מספקא ליה אבל במידי אחרינא פשיטא ליה דמימליך עליה ומיניה הוא וי\"מ דהיינו הא דמשני מי לא מודה ר\"ע דצריך לאימלוכי ביה ומן הדין הוא דאינו מינו ולהחמיר אר\"ע [דמינו הוא] אבל לא למעול דהאמר לעיל שאינו לוקה ול\"נ דא\"כ שליח אמאי מעל כיון דמספקא ליה אם מינו [הוי או] אינו מינו א\"כ עשה שליחותו ולכ\"נ דודאי הפירוש כך הוא מי לא מודה ר\"ע דצריך לימלוכי ביה דבסתם אין השליח לוקח אם אין שואל למשלח אם יחפוץ הילכך במעילה כיון דשליח לא נמלך לא הוי עשה שליחותו ולכך מעל השליח כי נמי הוי מינו לגמרי וקושיא דלמעול בעה\"ב נתרץ בע\"ה כמו שפירשתי והר\"ם היה אומר דלמעול בעל הבית לאו דוקא אלא כלומר לא ימעול שליח וכדפרישית דשמא עשה שליחותו ומשני לא מודה דצריך לאימלוכי כדפרישית:"]]],[["מי לא מודה רבי עקיבא דצריך אימלוכי איתמר שמעתא קמיה דרבא אמר להון שפיר אמר נחמני","מאן תנא דפליג עליה דרבי עקיבא רבן שמעון בן גמליאל היא דתניא הנודר מן הבשר אסור בכל מיני בשר ואסור בראש וברגלים ובקנה ובכבד ובלב ובעופות ומותר בבשר דגים וחגבים","רשב\"ג אומר הנודר מן הבשר אסור בכל מיני בשר ומותר בראש וברגלים ובקנה ובכבד ובלב ובעופות ואין צריך לומר בשר דגים וחגבים וכן היה רשב\"ג אומר קרביים לאו בשר ואוכליהן לאו בר אינש אוכליהן כבשר לענין זביני לאו בר אינש","מ\"ש בשר עוף לתנא קמא דאסיר דעביד שליחא דמימליך עליה בשר דגים נמי עביד שליחא דאי לא משכח בישרא מימליך עליה דאמר אי לא משכחנא בישרא אייתי דגים וליתסרו","אמר אביי כגון שהקיז דם דלא אכיל דגים אי הכי אפילו עופות נמי לא אכיל דאמר שמואל דמסוכר ואכיל בישרא דצפרא פרח לביה כצפרא ותניא אין מקיזין לא על דגים ולא על עופות ולא על בשר מליח ותניא הקיז דם לא יאכל לא חלב ולא גבינה ולא ביצים ולא שחליים ולא עופות ולא בשר מליח שאני עופות דאפשר על ידי שליקה","אביי אמר כגון דכייבין ליה עיניה דדגים קשין לעינים אי הכי אכיל דגים דהא אמר שמואל נו\"ן סמ\"ך עי\"ן נונא סמא לעינים ההוא סוף אוכלא:"],[[0,"תריץ מי לא מודה ר\"ע דצריך אימלוכי","שליח בבעל הבית ואע\"ג דס\"ל דמיניה הוא במילתא דצריך לאימלוכי הכי איבעיא ליה למימר שליח לבעל הבית רוצה אתה שאתן להם כבד וכיון דלא מימליך לא עשה שליחותו ופשע ושליח מעל אע\"ג דסבר דמין בשר הוי:"],[0,"לשמעתא","האי תירוצא דקא מתרץ אביי:"],[1,"בכל מיני בשר","בין בהמה ובין חיה:"],[1,"אסור בראש וכו'","דכל הני מיני בשר נינהו ואפילו כבד:"],[2,"רבן שמעון אומר מותר בראש וכו'","דקסבר לאו מינא דבשר הם אבל בקרביים הכל מודו דמין בשר הוו הואיל ואית בהו שומן טפי מכל הנך מראש והכבד והלב והיינו דפליג עליה דר\"ע דקא סבר כבד לאו מין בשר ור\"ע סבר מיניה הוא:"],[2,"וכן היה רבי שמעון אומר","שמעתא אחריתי קרביים לאו בשר ואוכליהן לאו בר נש הוא ואמרינן למאי הלכתא קרביים לאו בשר הוו הא אמרינן לעיל גבי נדרים אסור בכל מיני בשר ולא הוציא קרביים וקא מתרץ דהאי אוכליהן לאו בר נש לענין זביני שהקונה קרביים בדמי בשר שיכול לקנות הבשר וקונה קרביים לאו בר נש הוא דבטלה דעתו אצל בני אדם:"],[3,"דעביד שליח דמימליך עליה","דכי לא משכח בישרא מימליך עליה דבעל הבית ואמר לא משכחנא בישרא אלא בשר עוף ולהכי אסור דמיניה הוא:"],[3,"דגים גמי כו' וליתסרי","ואמאי מותר בבשר דגים:"],[4,"כגון שהקיז דם","בשעת הנדר דכיון דלא אכיל דגים בההיא שעתא לא נדר אדעתא דדגים ולא ממליך עליה כלל:"],[4,"אפי' דעופות נמי כו'","דלאו אדעתא דעופות נדר ולא מימליך עליה הוא וכיון דלא אכיל עופות השתא לישתרי:"],[4,"שאני עופות","שאפשר להו בתקנתא להקזה דאפשר לאכלן ע\"י שליקה - אע\"פ שהקיז דם ומידי דמצי למיכל בשום ענין נדר וממליך עליה ואסור:"],[5,"כגון דכייבין ליה עיניה","בשעת הנדר:"],[5,"דדגים קשין לעינים","וכל מילי דלא הוה מצי למיכל לא נדר אלא אדעתא דמידי דמצי למיכל ולהכי אדגים שרי ומן העופות אסור:"],[5,"נו\"ן סמ\"ך עי\"ן כו' בסוף אוכלא","בסוף החולי שכבר עבר זמן מרובה שחשש בעיניו דהתם סם טוב לכאב העינים והאי דקא תני דגים קשים לעינים בתחלת אוכלא כשהתחיל לחשוש בעיניו ובשעת הנדר הוה תחלת אוכלא:"]],[[1,"אסור בראש וברגלים","דסבר רבי עקיבא דכל מאי דמימליך הוי מיניה:"],[2,"מותר בראש","דסבר כתנא קמא דרבי עקיבא דמימליך לא תוי מינו:"],[2,"לענין זביני [לאו איניש הוא]","דשביק בשר וזבין קרביים:"],[4,"שהקיז דם","דקשיא לו הילכך מותר בדגים וחגבים:"],[4,"עופות נמי אין דרכם למיכל","ואמאי אסור בעופות:"],[4,"שאני עופות דאפשר ע\"י שליקה","והא דאמר שמואל פרח לבו היינו ע\"י צלי אבל דגים בין שלוק בין צלי קשה להקזה:"],[5,"סוף אוכלא","סוף החולי:"]]],[["\u0001מתני׳\u0002 הנודר מן הדגן אסור בפול המצרי יבש דברי רבי מאיר וחכ\"א אינו אסור אלא בחמשת המינין רבי מאיר אומר הנודר מן התבואה אינו אסור אלא מחמשת המינין אבל הנודר מן הדגן אסור בכל ומותר בפירות האילן ובירק:","\u0001גמ׳\u0002 למימרא דדגן כל דמידגן משמע מתיב רב יוסף (דברי הימים ב לא, ה) וכפרוץ הדבר הרבו בני ישראל [ראשית] דגן תירוש ויצהר וכל תבואת שדה לרוב וגו' ואי אמרת דגן כל דמידגן משמע מאי כפרוץ הדבר הרבו אמר אביי לאתויי פירות האילן וירק:","ר' מאיר אומר הנודר מן התבואה וכו': אמר ר' יוחנן הכל מודים בנודר מן התבואה שאין אסור אלא מחמשת המינין תניא נמי הכי שוין בנודר מן התבואה שאין אסור אלא מה' המינין פשיטא מהו דתימא תבואה כל מילי משמע קמשמע לן דלא משמע כל מילי","מתיב רב יוסף וכפרוץ הדבר הרבו בני ישראל כו' אמר רבא תבואה לחוד תבואת שדה לחוד","בר מר שמואל פקיד דליתנון תליסר אלפי זוזי לרבא מן עללתא דנהר פניא שלחה רבא לקמיה דרב יוסף עללתא היכי מיקריא אמר רב יוסף מתניתין היא ושוין בנודר מן התבואה שאין אסור אלא מחמשת המינין א\"ל אביי מי דמי תבואה לא משמע אלא מחמשת המינין עללתא כל מילי משמע","אהדרוהו לקמיה דרבא אמר הא לא קא מיבעיא לי דעללתא כל מילי משמע הדא הוא דאיבעיא לי שכר בתים ושכר ספינות מאי מי אמרינן כיון דפחתן לאו עללתא היא או דילמא כיון דלא ידיע פחתייהו עללתא היא אמרוה רבנן קמיה דרב יוסף אמר וכי מאחר דלא צריך לן אמאי שלח לן איקפד רב יוסף","שמע רבא ואתא לקמיה במעלי יומא דכפורי אשכחיה לשמעיה דהוה קא מזיג קמיה כסא דחמרא אמר ליה הב לי דאמזיג ליה אנא יהב ליה וקא מזיג איהו כסא דחמרא כי קא שתי אמר הדין מיזגא דמי למיזגא דרבא בריה דרב יוסף בר חמא אמר ליה הוא ניהו","אמר ליה לא תיתיב אכרעך עד דאמרת לי פירושא דהדין מילתא מאי דכתיב (במדבר כא, יח) וממדבר מתנה וממתנה נחליאל ומנחליאל במות","א\"ל כיון שעושה אדם את עצמו כמדבר שהוא מופקר לכל תורה ניתנה לו במתנה שנאמר וממדבר מתנה וכיון שניתנה לו במתנה נחלו אל שנאמר וממתנה נחליאל וכיון שנחלו אל עולה לגדולה שנאמר ומנחליאל במות ואם הגביה עצמו הקב\"ה משפילו שנאמר (במדבר כא, כ) ומבמות הגיא ולא עוד אלא ששוקעין אותו בקרקע שנאמר (במדבר כא, כ) ונשקפה על פני הישימון ואם חוזר בו הקב\"ה מגביהו"],[[0,"מתני' אלא מחמשת מינין","חטה ושעורה וכוסמין ושיפון ושבולת שועל:"],[0,"רבי מאיר אומר בו'","בהא ודאי מודינא לך שהנודר מן התבואה אינו אסור אלא מחמשת מינין אבל הנודר מן הדגן אסור בכל מין דמידגן משמע דבר שעושין ממנו כר ופול המצרי יבש עושין ממנו כרי ולהכי אסור:"],[1,"גמ' למימרא דדגן","דכתיב בקרא כל מין דמידגן משמע וחייב במעשר מן התורה ואפי' משאר מינין מדקתני הנודר מן הדגן אסור בכל:"],[1,"וכפרוץ הדבר","כלומר קיבלו עליהם תקנתא של חזקיהו לעשר הכל כדכתיב הרבו בני ישראל וגו' אי אמרת בשלמא דדגן לא משמע אלא מחמשת מינין היינו דאתא קרא למימר הרבו בני ישראל דאפי' דבר שלא נתחייב במעשר מן התורה כגון שאר מיני דמידגני היו מעשרים כדי להחזיק בתקנה אלא אי אמרת דגן כל מיני דמידגן משמע מאי וכפרוץ הדבר הרבו כלומר מה הוסיפו על מה שכתוב בתורה:"],[1,"אמר אביי","כל דמידגן משמע ומאי וכפרוץ הדבר הרבו לאיתויי פירות האילן וירק דהרבו בו בני ישראל ליתן מהן מעשר דמדאורייתא לא מחייב במעשר אלא מידי דמידגן דלא משמע אלא מחמשת מינין:"],[3,"ותבואת השדה לרוב","אלמא דתבואה משמע כל מילי דהא דכתיב ותבואת השדה לאו מחמשת מינין דאיקרו תבואה: תבואה סתם לא משמע אלא מחמשת מינין תבואת השדה משמע כל מידי הגדל מן השדה:"],[4,"פקיד","צוה בצוואתו:"],[4,"היכי מיקריא","כלומר ממה אגבה אותו ממון:"],[4,"אלא מחמשת מינין","ואינו גובה אלא מחמשת מינין:"],[4,"עללתא","משמע כל מילי שעולה ומשבח ואפי' משאר פירות שמשבחין צוה לגבות מהן:"],[5,"אהדרוה לקמיה דרבא","לאותה תשובה:"],[5,"שכר בתים ושכר ספינות","גובה מהן או לא:"],[5,"מי אמרינן כיון דפחתן","שמתחסרין כל זמן שמתיישנין:"],[5,"לאו עללתא","מיקרו שאין עולה ומשביח ולא גבי מינייהו:"],[5,"או דילמא כיון דלא ידיע פחתייהו","שעל יד על יד מתחסר ואינו ניכר פחיתותו להדיא והואיל ונוטל הימנו שכר עולה ומשביח הוי ויהבו ליה מההוא אגרא:"],[5,"אמרוה קמיה דרב יוסף","הא דאמר רבא דהא לא מיבעיא ליה דעללתא כל מידי משמע:"],[6,"דמי למזיגא דרבא","שכשהיה רבא לומד לפניו היה מוזג לו בענין זה:"],[7,"לא תיתיב אכרעך כו'","לפי שהגיס לבו שאל לו מקרא זה כדי להשפיל דעתו:"],[8,"כמדבר שהוא מופקר לכל","מלמד תורה בחנם לכל:"],[8,"נחליאל","נעשית לו התורה כמו נחלה:"],[8,"ששוקעין אותו בארץ","כמו המשקוף:"]],[[0,"מתניתין אסור בפול המצרי","דכל מידי דאידגן שמעמידין אותו בכרי נקרא דגן:"],[1,"וכפרוץ הדבר","פסוק הוא בדברי הימים שתיקן חזקיהו שיביאו המעשרות לאוצר לבית המקדש וכפרוץ תקנתו הרבו בני ישראל מעשר דגן תירוש ויצהר וכל תבואת שדה לרוב והשתא ס\"ד דכל תבואת שדה כלומר כגון פול המצרי אסיפא דקרא סמיך דכתיב כל תבואת שדה לרוב ואי דגן כל מילי דאידגן משמע ל\"ל למיכתב כל תבואת שדה ונהי דדגן דכתיב באורייתא מעשר דגנך לא משמע אלא ה' מינין מיהו ההוא דדברי הימים משמע כל מילי דאי בלשון ב\"א משמע כל מידי דמדגן ההוא נמי משמע כל מילי:"],[2,"הכל מודים","אפילו רבנן שאין אסור אלא מה' מינין:"],[3,"מתיב רב יוסף","וה\"ה לרבי מאיר דמתני' מותיב ואמר אביי לאיתויי פירות האילן וירק:"],[3,"תבואת שדה לחוד","דודאי משמע כל מילי:"],[4,"עללתא","כל מין דמידגן משמע:"],[5,"הא לא מיבעיא ליה","דכל פירות איקרי עללתא כל דבר אוכלין מקרי עללתא וכן שאר נכסים דעללתא מידי דהוא בעין משמע כי קמיבעיא ליה שכר בתים שכר ספינות מי אמרינן כיון דבתים וספינות פוחתים בכל יום ומשתנים לאו בכלל עללתא דעללתא משמע מידי דמשבח ולא מידי דפוחת:"],[5,"או דלמא כיון דלא ידיע פחתייהו","פי' שפוחתין מעט מעט ולזמן מרובה ה\"ל [מידי] דמשבח ואיקרי שפיר עללתא:"],[8,"שיהא מופקר לכל","שיהיה מלמד תורה לכל:"],[8,"ששוקפין","לשון איסקופה הנדרסת:"]]],[["שנאמר (ישעיהו מ, ד) כל גיא ינשא","תניא הנודר מן הדגן אסור אף בפול המצרי יבש ומותר בלח ומותר באורז בחילקא בטרגיס ובטיסני הנודר מן פירות השנה אסור בכל פירות השנה ומותר בגדיים ובטלאים ובחלב ובביצים ובגוזלות ואם אמר גידולי שנה עלי אסור בכולן","הנודר מן פירות הארץ אסור בכל פירות הארץ ומותר בכמהין ופטריות ואם אמר גידולי קרקע עלי אסור בכולן","ורמינהי על דבר שאין גידולו מן הארץ אומר שהכל נהיה בדברו ותניא על המלח ועל הזמית ועל כמהין ופטריות אומר שהכל נהיה בדברו אמר אביי מירבא רבו מארעא מינק מאוירא ינקי ולא מארעא והא קתני על דבר שאין גידולו מן הארץ תני על דבר שאין יונק מן הארץ:","\u0001מתני׳\u0002 הנודר מן הכסות מותר בשק וביריעה ובחמילה אמר קונם צמר עולה עלי מותר להתכסות בגיזי צמר הפשתן עולה עלי מותר להתכסות באניצי פשתן","ר' יהודה אומר הכל לפי הנודר טען והזיע והיה ריחו קשה אמר קונם צמר ופשתים עולה עלי מותר להתכסות ואסור להפשיל לאחוריו:","\u0001גמ׳\u0002 תניא הנודר מן הכסות מותר בשק וביריעה ובחמילה ואסור בפונדא ובפסקיא ובסקורטיא ובקטבליא ואנפליא ופליניא ומכנסים וכובע מאי איסקורטי אמר רבה בר בר חנה כיתונא דצלא","תניא יוצאין בשק עבה ובסגוס עבה וביריעה ובחמילה מפני הגשמים אבל לא בתיבה ולא בקופה ולא במחצלת מפני הגשמים הרועים יוצאין בשקים ולא רועים בלבד אמרו אלא כל אדם אלא שדברו חכמים בהווה:","ר' יהודה אומר הכל לפי הנודר כו': תניא כיצד א\"ר יהודה הכל לפי הנודר היה לבוש צמר והצר ואמר קונם צמר עולה עלי אסור ללבוש ומותר לטעון היה טעון פשתן והזיע ואמר קונם פשתן עולה עלי מותר ללבוש ואסור לטעון:"],[[1,"חילקא","חטה שנחלקת לשנים:"],[1,"טרגיס","לשלשה:"],[1,"טיסני","לארבעה ולהכי שרי שכבר נשתנה החטה:"],[1,"אסור בכולן","דכולן גידולי שנה נינהו:"],[2,"מותר בכמהין ופטריות","שגדלין נמי על העצים:"],[2,"אסור בכולן","דכמהין ופטריות גידולי קרקע נינהו:"],[3,"זומית","שלמור\"א בלע\"ז:"],[3,"אומר שהכל נ\"ב","מדקא חשיב בכלל שאין גידולו מן הארץ כמהין ופטריות אלמא דלאו גידולי קרקע נינהו:"],[3,"מאוירא ינקי","שאין להם שרשים בארץ לפיכך אין מברכין עליהם כדבר שגדל מן הארץ:"],[3,"והא קתני על דבר שאין גידולו מן הארץ","והיינו כמהין ופטריות אלמא אפי' מירבא נמי לא רבו מארעא:"],[3,"שאין יונק","דהיינו כמהין ופטריות דמאוירא ינקי:"],[4,"מתני' חמילה","כעין יריעה היא:"],[4,"קונם צמר עולה כו'","משמע מלבוש של צמר:"],[4,"באניצי פשתן","דדייק ולא נפיץ:"],[5,"טעון צמר ופשתן והזיע","מחמת המשוי:"],[5,"","והיה ריחו קשה וכו':"],[5,"ואסור להפשילן לאחוריו","לעשות משוי מאותן מינין דבענין שנצטער נדר דהיינו לטעון ולא לכסות ולהכי מותר לכסות:"],[6,"גמ' פונדא","אזור חלול שחוגרין בו:"],[6,"פסקיא","פיישול\"א:"],[6,"אסקורטיא","מפרש לקמן:"],[6,"קטבליא","מלבוש של עור קשה שלובש על האסקורטיא:"],[6,"אנפליא","הוש\"ש בלע\"ז של עור:"],[6,"פליניא","סינר:"],[6,"כיתונא דצלא","מלבוש של עור:"],[7,"סגוס עבה","מין שק הוא עבה טפי מיריעה:"],[7,"","יוצאין בשבת -בכל אלו דברים:"],[7,"אבל לא בתיבה","שלא יכוף תיבה על ראשו ויצא דמשוי הוי:"],[8,"ומותר לטעון","שלא נדר אלא ממלבוש שהרי היה מצטער ממלבוש:"],[8,"והזיע","מכובד משוי:"],[8,"ואסור לטעון","שלא נדר אלא כפי שהצר לו המשוי הילכך מותר ללבוש:"]],[[1,"חילקא","חטין כתושין חלוקין לשנים:"],[1,"טרגיס","חד לתלתא:"],[1,"טיסני","חד לארבעה:"],[1,"אסור בכולן","דכמיהין ופטריות בכלל גדולי קרקע הן:"],[3,"[מירבא רבו מארעא]","כמהין ופטריות ודאי מארעא רבו ושפיר מיקרו גידולי קרקע אבל היניקה שלהם אינה אלא מאויר קרקע ולא מברכין בורא פרי האדמה:"],[4,"שק יריעה וחמילה","אינן בגדים הם:"],[4,"מותר להתכסות בגיזי צמר","שלא נתכוון זה אלא לבגד ארוג:"],[5,"הכל לפי הנודר","פירוש לפי ענין שהיה בשעת הנדר:"],[5,"היה טעון","פירוש מופשל לאחוריו כדרך נושאי משאות:"],[5,"מותר להתכסות","שלא נתכוון לאסור אלא בענין שהיה מצטער:"],[5,"רוחו קצרה","שמלבושן צר לו אינו אסור לו אלא בלבישה:"],[6,"פונדא","אבנט חלול וככסות דמי:"],[6,"פסקיא","פייש\"א:"],[6,"אנפליא","קלצו\"ן:"],[6,"כיתונא דצלא","פירוש מלבוש עור ויוצאין בשבת להגין מן הגשמים:"],[7,"אבל לא בתיבה","קטנה שעל ראשו דמשוי הוא:"],[8,"והזיע","מחמת כובד משאו וה\"ה דברישא מצי למיתני פשתן ובסיפא צמר:"]]],[["\u0001מתני׳\u0002 הנודר מן הבית מותר בעלייה דברי רבי מאיר וחכמים אומרים עלייה בכלל הבית הנודר מן עלייה מותר בבית:","\u0001גמ׳\u0002 מאן תנא (ויקרא יד, לה) בבית לרבות את היציע בבית לרבות את העלייה אמר רב חסדא רבי מאיר היא דאי רבנן האמרי רבנן עלייה בכלל הבית למה לי קרא בבית לריבויא","אביי אמר אפי' תימא רבנן בעיא קרא דסלקא דעתך אמינא (ויקרא יד, לד) בבית ארץ אחזתכם כתיב דמחבר בארעא שמיה בית עלייה הא לא מחבר בארעא","כמאן אזלא הא דאמר רב הונא בר חייא משמיה דעולא בית בביתי אני מוכר לך מראהו עלייה טעמא דא\"ל בית שבביתי אני מוכר לך אבל בית סתם אינו מראהו עלייה לימא רבי מאיר היא אפילו תימא רבנן מאי עלייה מעולה שבבתים:","\u0001מתני׳\u0002 הנודר מן המטה מותר בדרגש דברי רבי מאיר וחכ\"א דרגש בכלל מטה הנודר מן הדרגש מותר במטה:","\u0001גמ׳\u0002 מאי דרגש אמר עולא ערסא דגדא אמרו ליה רבנן לעולא הא דתנן כשהן מברין אותו כל העם מסובין על הארץ והוא מיסב על הדרגש כולה שתא לא יתיב עלה ההוא יומא יתיב עלה מתקיף לה רבינא מידי דהוה אבשר ויין דכולה שתא אי בעי אכיל ואי בעי לא אכיל ההוא יומא אנן יהבינן ליה","אלא הא קשיא דתניא דרגש לא היה כופהו אלא זוקפו ואי אמרת ערסא דגדא הוא והתניא הכופה את מטתו לא מטתו בלבד הוא כופה אלא כל מטות שיש לו בתוך הבית הוא כופה הא לא קשיא"],[[0,"מתני' מותר בעלייה","שאין עלייה בכלל בית:"],[0,"הנודר מן עלייה כו'","דברי הכל אין בית בכלל עלייה:"],[1,"גמ' ר\"מ היא","דאמר עלייה לאו בכלל בית היא:"],[1,"לימא ר\"מ היא","דאמר אין [עלייה] בכלל [בית]:"],[1,"דיאי וכו'","בבית ארץ משמע דמחובר בארעא הוי בית: עלייה דלא מיחבר בארעא לא הוי בכלל בית ארץ ולהכי בעי קרא לרבויי דהואיל דסמיכא אקירות הבית מטמאה:"],[3,"האומר לחבירו בית שבביתי אני מוכר לך מראהו עלייה","משום דאמר בית בביתי משמע עלייה בתוך ביתי: טעמא דאמר בית בביתי הא אם אמר בית סתם אין יכול להראות לו עלייה. דאין עלייה בכלל בית:"],[3,"אפי' תימא רבנן","לא תימא עלייה ממש מאי עלייה דקתני:"],[3,"מעולה שבנכסיו","הבית המשובח שבבתיו צריך ליתן לו היכא דקאמר בית בביתי אבל אי הוה אמר בית סתם היה יכול להראות לו עלייה ממש דעלייה בכלל בית:"],[4,"מתני' מותר בדרגש","דאין דרגש בכלל מיטה:"],[4,"דרגש בכלל מיטה","ואסור אבל הנודר מן הדרגש דברי הכל אין המיטה בכלל דרגש:"],[5,"גמ' ערסא דגדא","מיטה שעורכין אותה למזל ואין שום אדם ישן עליה: כשהן מברין אותו: לכ\"ג כשהוא אבל:"],[5,"כל","העם כו' יתיב עליה. בתמיה מכלל דדרגש לאו ערסא דגדא הוא:"],[5,"אנן יהבינן ליה","משום דכתיב ויין למרי נפש ה\"נ אף על גב דכולה שתא לא יתיב עליה השתא יתיב:"],[6,"לא חיה כופהו","ממש הכרעים מלמעלה:"],[6,"אלא זוקפו","שמעמידו על שני כרעיו ודיו:"],[6,"ואי אמרת ערסא דנדא","דמיטה חשובה היא כ\"כ אמאי אין צריך לכפותה:"],[6,"והתניא וכו'","וזו נמי הואיל ומיטה חשובה היא צריך לכפותה אלא שמע מינה דרגש לאו ערסא דגדא הוא:"]],[[0,"הנודר מן הבית מותר בעלייה","דעלייה אינה בכלל בית:"],[1,"בבית לרבות היציע בבית לרבות העלייה","הק' ה\"ר יצחק הא דרשינן בקירות הבית ולא בקיר היציע ואמר הר\"ם דכהך בריית' איתא בת\"כ וגרסינן לה הכי כנגע נראה לי ולא לאורי מכאן אמרו בית אפל אין פותחין לו חלונות לראות נגעו בבית להביא חצר הצבוע בבית להביא העלייה ולכך איצטריך לרבות צבוע לפי שמצינו בנגעים בבגד צמר או בבגד פשתים מה פשתן כברייתו אף צמר כברייתו והוציא את הצבוע לפי שהוקשו נגעי בתים ונגעי בגדים והייתי סבור למעט כותל צבוע איצטריך לרבויי ושמא ה\"נ גרסינן בבית לרבות הצבוע - הא דאמר רב הונא פרק בתרא דמנחות (דף קח:) בית בביתי אני מוכר לך מראהו עלייה ואמר עלייה זו מכרתי לך טעמא דא\"ל בית בביתי ולא בית סתם דמשמע בית חשוב אבל אם אמר בית סתם בית מכר לו וקשה דלשם קאמר דעלייה דגריעה קאמר ויד בעל השטר על התחתונה א\"כ מאי איריא בית בביתי אפילו בית סתמא נמי כיון דהטעם תלוי ביד בעל השטר על התחתונה וי\"ל דלשם נמי צריך לפרושי כיון דיד בעל השטר על התחתונה כבית סתם דמי ומראהו עלייה דגריע והכי נקט דאף כי אמר בית בביתי מראהו גרוע וא\"כ בשמעתא ניחא כי [נמי] מראהו עלייה דגריעה אתיא כרבנן וה\"ה בבית סתם מראהו עלייה דעלייה בכלל בית ונקיט בית בביתי לרבותא דאפי' הכי מראהו גרוע והכא לא חש הש\"ס לתרץ כמסקנא דהתם ותירץ כס\"ד התם וה\"ה נמי דלמסקנא דהתם נמי מפרשינן שפיר - הר\"ם:"],[4,"מותר בדרגש","מפרש בגמרא ערסא דצלא ואינו בכלל מיטה סתם:"],[5,"ערסא דגדא","מיטה העשויה לכבוד ולמזל ואין יושבין עליה:"],[5,"אנן יהבינן","מי שמברין אותו:"],[6,"ואי אמרת ערסא דגדא אמאי לא היה כופהו","דבשלמא אי ערסא דצלא ניחא דלא בעי כפייה דדרגש העור תלוי בלולאות ודיו שיזקוף ויקשרנו למעלה מארכובותיו ולא יוכלו לישב עליו:"],[6,"כל מטות שיש לו בבית","מפני כבודו:"]]],[["מידי דהוה אמטה המיוחדת לכלים דתניא אם היתה מטה המיוחדת לכלים אין צריך לכפותה","אלא אי קשיא הא קשיא דתניא רשב\"ג אומר דרגש מתיר קרביטיו והוא נופל מאליו ואי דרגש ערסא דגדא הוא קרביטין מי אית ליה כי אתא רבין אמר שאילתיה לההוא מרבנן ורב תחליפא בר מערבא שמיה דהוה שכיח בשוקא דצלעי ואמר לי מאי דרגש ערסא דצלא","איתמר איזהו מטה ואיזהו דרגש אמר רבי ירמיה מטה מסרגין אותה על גבה דרגש מסרגין אותו מגופו מיתיבי כלי עץ מאימתי מקבלין טומאה המטה והעריסה משישופם בעור הדג ואי מטה מסתרגת על גבה למה לי שיפת עור הדג","אלא הא והא מגופן מטה אעולי ואפוקי בבזיני דרגש אעולי ואפוקי באבקתא","א\"ר יעקב בר אחא אמר רבי מטה שנקליטיה יוצאין זוקפה ודיו א\"ר יעקב בר אידי אמר ר' יהושע בן לוי הלכה כרשב\"ג:","\u0001מתני׳\u0002 הנודר מן העיר מותר ליכנס לתחומה של עיר ואסור ליכנס לעיבורה אבל הנודר מן הבית אסור מן האגף ולפנים:","\u0001גמ׳\u0002 מנלן דעיבורא דמתא כמתא דמי א\"ר יוחנן דאמר קרא (יהושע ה, יג) ויהי בהיות יהושע ביריחו וגו' מאי ביריחו אילימא ביריחו ממש והכתיב (יהושע ו, א) ויריחו סוגרת ומסוגרת אלא ש\"מ בעיבורה","אימא אפי' בתחומה הא כתיב בתחומה (במדבר לה, ה) ומדותם מחוץ לעיר:","הנודר מן הבית אינו אסור אלא מן האגף ולפנים: אבל מן האגף ולחוץ לא מתיב רב מרי (ויקרא יד, לח) ויצא הכהן מן הבית יכול ילך לביתו ויסגיר ת\"ל (ויקרא יד, לח) אל פתח הבית אי אל פתח הבית יכול יעמוד תחת המשקוף ויסגיר תלמוד לומר מן הבית עד שיצא מן הבית כולו","הא כיצד עומד בצד המשקוף ויסגיר ומנין שאם הלך לביתו והסגיר או שעמד תחת השקוף והסגיר שהסגירו מוסגר ת\"ל (ויקרא יד, לח) והסגיר את הבית מכל מקום שאני גבי בית דכתיב מן הבית עד שיצא מן הבית כולו:"],[[0,"המיוחדת","ליתן עליה כלים והואיל ואין ישנים עליה אין צריך לכפותה:"],[1,"רבן שמעון אומר אין צריך לזוקפה","אלא הוא האבל נוטל קרביטין והיא נופלת:"],[1,"קרביטין","לולאות שבו:"],[1,"קרביטין מי אית ליה","הכי קים להו דלא הוו להו קרביטין שאינה עשויה להתפרק אלא עומדת מוצעת לעולם:"],[1,"דצלעי","מוכרי עורות:"],[1,"ערסא דצלא","של עור שישן עליה אבל אינה חשובה כל כך ולהכי הואיל ואינה חשובה לא היה כופה אלא זוקפה ודיו והלכך אמרי' במתני' דמותר בדרגש שאינה מטה חשובה וערסא דצלא אית לה קרביטין ופליג רשב\"ג בגמרא ואמר דבעי כפיה כל כך שמתיר קרביטין והעור נופל מאליו לפי שיש רצועות סביב לעור ומותחין אותו בין ארוכות המטה וקושרין הרצועות בארוכות ושוכבין עליו וכשמתירין הרצועות והעור נופל אין לך כפיה גדולה מזו:"],[2,"מטה מסרגין אותה על גבה","שכורכין הבגד או העור שישנים עליו סביב אותם עצים שעומדים מראשותיו ומרגלותיו נקובים ומכניסין המשיחות שבבגד או שבעור לתוך אותן נקבים:"],[2,"משישופם בעור הדג","שמשפשף העצים של מטה הארוכות והקצרות בעור הדג כדי לעשותן צהובין וחלקים:"],[2,"למה לי שיפת עור הדג","והלא העור מכוסה מן החבלים או מן הבגד או מן העור:"],[3,"הא והא","מסתרגין מגופן:"],[3,"לעיולי ולאפוקי אבזיוני","שמכניסין ראשי המשיחות שבבגד דרך הנקבים וקושרים זה בזה:"],[3,"אעולי ואפוקי באבקתא","שקושרין לו לאות בעצי המטה מראשותיו וממרגלותיו ומכניסין ראשי משיחות בנקבים וקושרין בלולאות והיינו קרביטין:"],[4,"שנקליטיה יוצאין","כדאמרי' התם נקליטין שנים ואותה מטה אין אדם יכול לכפותה מפני נקליטיה אלא זוקפה על ב' מרגלותיה ומניחה ודיו:"],[4,"הלכה כרבן שמעון","דאמר מתיר קרביטין:"],[5,"מתני' לתחומה","בתוך אלפים אמה:"],[5,"לעיבורה","היינו פגום נכנס פגום יוצא של אותה העיר:"],[6,"גמ' אלא שמע מינה בעיבורה הוה קאי","וקרי ליה ביריחו:"],[7,"אימא ואפילו בתחומה","הוי בתוך העיר והאי דכתיב ויהי בהיות יהושע ביריחו בתחומה הוה קאי:"],[7,"","תחומה אקרי חוץ לעיר דכתיב ומדותם מחוץ לעיר:"],[8,"מן האגף ולפנים","מן סגירת הפתח ולפנים אגף כמו (יומא יח.) הגפת דלתות אבל מן האגף ולחוץ על עובי המפתן אינו אסור:"],[8,"יכול ילך לביתו ויסגיר","ע\"י שלוחו:"],[8,"ת\"ל אל פתח הבית","של מנוגע צריך לעמוד:"],[8,"הכי גרסינן על השקוף","על עובי המפתן:"],[8,"עד שיצא מן השקוף","דעל השקוף איקרי בית:"],[9,"בצדי השקוף","מבחוץ מדקאמר עד שיצא מן הבית כולו אלמא דשקוף נמי הוי בית ואמאי הנודר מותר מן האגף ולחוץ:"],[9,"שאני גבי בית וכו'","אבל גבי נדרים מותר מן האגף ולחוץ שקוף היינו אסקופה משקוף מה שעל הפתח:"]],[[1,"דרגש מתיר קרביטיו והעור נופל","קרביטיו לולאות שמחוברין במטה וקשורין בעור:"],[1,"ערסא דצלא","מטה של עור ותולין רצועות בשפת העור סביב וכשרוצין לנטותו עונבים הרצועות בארוכות המטה וכשמתירין אותם הוא נופל והם קרביטיו:"],[2,"","מטה מסרגין הסירוגין על גבה על הארוכות הלכך כשכופין אותו הסירוגין גבוהים ואין יכולין לישב עליו:"],[2,"דרגש סירוגין מבפני'","תחת הארוכות הלכך כי נמי כופהו הוא נמוך לישב עליו כאילו אינו כפוי לכך אמר דאינו צריך לכפותו ואית דגרסי איתמר נמי דדרגש אינו בר כפייה:"],[2,"ל\"ל שיפת עור הדג","והלא אין יופיו נראה שהרי הן מכוסות בחבלים המסורגין על גבה:"],[3,"בבזייני","בבקעים ובנקבים שבארוכות מקצת ארוכות מגולות וצריכה שיפה:"],[3,"באבקתא","לולאות שיש לולאות תלוין בנקבי ארכובותיו ובהם מכניסין ראשי הרצועות התלויות בשפת העור:"],[4,"שנקליטיה יוצאין","שנקליטיה קבועים בכרעי המטה כדרכה:"],[4,"זוקפה","פורס בגד באותן לולאות שבראשי הנקליטין והוי כאילו כפוי שאינו ראוי לישיבה:"],[5,"מותר ליכנס לתחומה","דעד התחום אינו נקרא על שם העיר אבל עיבור נקרא על שם העיר:"],[5,"מן האגף","מקום הגפת הדלת:"],[6,"אלא שמע מינה בעיבורה קאי","וקרי ליה יריחו:"],[7,"ומדותם מחוץ לעיר אלפים באמה","אלמא תחום איקרי חוץ לעיר:"],[8,"יכול ילך לביתו ויסגור","ע\"י שליח או על ידי חבל ארוך תלמוד לומר אל פתח הבית אי אל פתח הבית יכול יעמוד תחת המשקוף ויסגיר דליכא לקיומי בענין אחר שהרי צריך הוא לצאת מן הבית:"]]],[["\u0001מתני׳\u0002 קונם פירות האלו עלי קונם הן על פי קונם הן לפי אסור בחילופיהן ובגידוליהן שאני אוכל ושאני טועם מותר בחילופיהן ובגידוליהן בדבר שזרעו כלה אבל בדבר שאין זרעו כלה אפילו גידולי גידולין אסורין","האומר לאשתו קונם מעשה ידיך עלי קונם הן על פי קונם הן לפי אסור בחילופיהן ובגידוליהן שאני אוכל שאני טועם מותר בחילופיהן ובגידוליהן בדבר שזרעו כלה אבל דבר שאין זרעו כלה אפילו גידולי גידולין אסורין","שאת עושה איני אוכל עד הפסח שאת עושה איני מתכסה עד הפסח עשתה לפני הפסח מותר לאכול ולהתכסות אחר הפסח שאת עושה עד הפסח איני אוכל ושאת עושה עד הפסח איני מתכסה עשתה לפני הפסח אסור לאכול ולהתכסות אחר הפסח שאת נהנית לי עד הפסח אם הולכת את לבית אביך עד החג הלכה לפני הפסח אסורה בהנאתו עד הפסח"],[[0,"מתני' בדבר שזרעו כלה","בקרקע וגדל כגון חטה וכיוצא בה דהיינו גידולין גמורין:"],[0,"אבל בדבר שאין זרעו כלה","כגון השומים והבצלים שאינו כלה בקרקע אלא שרבה וגדל בגופו:"],[0,"אפילו גידולי גידולין אסורין","דכגופייהו דמו:"],[1,"מעשה ידיך עלי","ונתנו לה פירות בשכר מעשה ידיה הואיל ואמר עלי אסור בחילופיהן וט' אבל כי אמר שאיני טועם משמע מהן גופן איני טועם הלכך מותר בחילופיהן ובגידוליהן אם זרעו וצמחו:"],[2,"שאת עושה איני אוכל עדי הפסח","דאמר הכי קונם עלי מה שאת עושה שאיני אוכל ממעשה ידיך עד הפסח או שאמר קונם שאת עושה שאיני מתכסה מכל מלאכתך עד הפסח:"],[2,"מותר לאחר הפסח","שהרי לא נדר מכל מה שתעשה אלא עד הפסח:"],[2,"אפי' אחר הפסח אסור","לאכול ולהתכסות מכל שעושה לעולם שהרי לא קבע בו זמן:"],[2,"","היה עומד באדר ואמר קונם שאת נהנית לי עד הפסח אם תלכי לבית אביך מעכשיו עד החג הלכה לפני הפסח אסורה בהנאתו עד הפסח:"]],[[0,"","קונם פירות האלו עלי ולא גרסי' פירות אלו:"],[0,"אסור בחילופיהן ובגידוליהן","דכיון דהזכיר קונם סתם ולא הזכיר אכילה אסר עצמו בין בחילופיהן בין בגידוליהן:"],[0,"שאני אוכל שאני טועם","לא אסר עצמו אלא בגוף הפירות:"],[0,"בדבר שזרעו כלה","הגידולין הוו כגוף אחר:"],[0,"אבל בדבר שאין זרעו כלה אפילו גידולי גידולין אסורין","כגון בצלים שאין הבצל כלה אלא מוסיף אחרים עליו הלכך גידולין כגופן:"],[1,"האומר לאשתו קונם מעשה ידיך","פי' אם תעשה לי מאכל אסור בחלופיהן אם הכינה לו מאכל והחליפן בפירות - בגידולין פי' בגידולי פירות שלקח מן החליפין:"],[1,"שאני טועם מותר בחליפין","שלא אסר עצמו אלא מהם אבל בדבר שאין זרעו כלה אסור בגידולי גידוליהן ומשכחת לה כגון שנטע אילן או זרע דבר שאין זרעו כלה ונמצא שהגידולין אסורין עליהן דהיינו כמו מעשה ידיה והלכך גידולי גידולין אסורין בדבר שאין זרעו כלה אבל בדבר שזרעו כלה הגידולין אסורין וגידולי גידולין מותרין:"],[2,"קונם שאת עושה איני אוכל עד הפסח","ממה שאת עושה ואשמועינן דלא תימא דה\"ק איני אוכל מכל מה שתעשה עד הפסח לעולם וכן כולם אשמועינן הכי:"],[2,"שאת נהנית לי עד הפסח אם תלכי לבית אביך עד החג","עומד בחודש אחד לפני הפסח ואמר קונם שלא תהא נהנית לי עד הפסח אם תלכי לבית אביך מעכשיו ועד החג והלכה לפני הפסח אסורה עד הפסח כלומר אם הלכה לבית אביה:"]]],[["לאחר הפסח בבל יחל שאת נהנית לי עד החג אם הולכת את לבית אביך עד הפסח הלכה לפני הפסח אסורה בהנאתו עד החג ומותרת לילך אחר הפסח:","\u0001גמ׳\u0002 האומר לאשתו קונם מעשה ידיך עלי קונם הן על פי קונם הן לפי וכו': ישמעאל איש כפר ימא ואמרי לה איש כפר דימא העלה בידו בצל שעקרו בשביעית ונטעו בשמינית ורבו גידוליו על עיקרו והכי קא מיבעיא ליה גידוליו היתר ועיקרו אסור כיון דרבו גידוליו מעיקרו אותן גידולי היתר מעלין את האיסור או לא אתא לקמיה דרבי אמי לא הוה בידיה","אתא לקמיה דרבי יצחק נפחא פשט ליה מן הדא דאמר רבי חנינא תריתאה אמר רבי ינאי בצל של תרומה שנטעו ורבו גידוליו על עיקרו מותר א\"ל ר' ירמיה ואיתימא רבי זריקא שביק מר תרין ועביד כחד","מאן נינהו תרין דא\"ר אבהו א\"ר יוחנן ילדה שסיבכה בזקינה ובה פירות אע\"פ שהוסיפה מאתים אסור","וא\"ר שמואל בר רבי נחמני א\"ר יונתן בצל שנטעו בכרם ונעקר הכרם אסור","הדר אתא לקמיה דר' אמי ופשיט ליה מן הדא דאמר ר' יצחק אמר ר' יוחנן ליטרא בצלים שתיקנה וזרעה מתעשרת לפי כולה אלמא אותן גידולין מבטלין עיקר","דלמא לחומרא שאני","אלא מן הדא דתניא רבי שמעון אומר"],[[0,"הלכה אחר הפסח","והרי היא נהנית ממנו קודם הפסח נמצא עובר בלא יחל דברו במה שנהנית ממנו קודם הפסח שהרי הוא הדירה עד הפסח:"],[0,"ומותרת לילך אחר הפסח","שהרי לא הדירה אלא עד הפסח:"],[1,"גמ' העלה בידו בצל","ברייתא היא איבעי' היא דאיבעיא בבי מדרשא:"],[1,"שעקרו בשביעית ונטעו בשמינית","איכא דאמרי שעיקרו גדל בשביעית ונתגדל עד שרבו גידוליו על עיקרו:"],[1,"וקא מיבעיא ליה הכי","גידוליהן איתינהו היתר שגדלו בשמינית ועיקרו אסור בהנאה שהרי גדל בשביעית וחייבין בביעור וכיון דרבו גידוליו על עיקרו שהיו יותר מן העיקר אותן גידולי היתר מעלין את האיסור שמבטלין את האיסור כולו או לא:"],[2,"מותר","דגידולי היתר מבטלין את האיסור והכא נמי לא שנא:"],[3,"ילדיה","של ערלה:"],[3,"שסיבכה","שהרכיבה בתוך אילן זקן של היתר והיו בה פירות הערלה:"],[3,"ואע\"פ שהוסיפה","פירות לאחר שהרכיבה מאתים חלקים יותר ממה שהיתה בשעת הרכבה אע\"ג דשאר ערלה בטלה במאתים:"],[3,"אסור","אלמא דלא אתו גידולין דהיתר ומעלין את האיסור:"],[5,"ופשט ליה מן הדא","דמותר דהווין נמי תרין:"],[5,"ליטרא","ממש של בצלים:"],[5,"שתיקנה","שעישרה כהלכתה וזרעה וגדלה:"],[5,"מתעשרת לפי כולה","אע\"פ שכבר עישר מן העיקר והעיקר קיים ואינו כלה צריך להפריש מן הגידולים ומן העיקר לפי שבטלו גידולים את העיקר הכא נמי ההוא בצל שהעלה ישמעאל גידולין מבטלין את העיקר:"],[6,"דלמא לחומרא שאני","כגון הכא גבי ליטרא בצלים דלחומרא קאמר דצריך לעשר משום דגדולין מבטלין את העיקר אבל לקולא כגון בעיא דישמעאל דהוי להתיר לא אמר:"]],[[0,"לאחר הפסח","אם נהנית לפני הפסח משלו הרי היא בבל יחל שהרי תלה שלא תלך:"],[0,"שאת נהנית לי עד החג אם את הולכת עד הפסח","והיא עומדת בחדש אחד לפני הפסח:"],[0,"הלכה לפני הפסח אסורה להנות משלו עד החג ומותרת לילך לאחר הפסח","דבשלא הלכה לפני הפסח לא חל הנדר כלל:"],[1,"כפר ימא","יושב על שפת הים:"],[1,"כפר דימא","שם הכפר:"],[1,"העלה בידו בצל","שגדל בשביעית ועקרו בשביעית ויש לו דין פירות שביעית לענין ביעור ושאר דינין:"],[1,"ונטעו בשמינית","שכן דרך נוטעי בצלים שנוטע אחד והרבה גדלים ממנו והוא אינו כלה:"],[1,"","והכי קמיבעיא לי' גידולי היתר הם דלא גזרו על גידולי שביעית להיות שביעית כמו שגזרו על גידולי תרומ' שבתרומה החמירו משום גזל השבט ועיקר אסור בפירות שביעית מי [אתו] גידולי היתר ומעלים את האיסור או לא דנהי דמדאורייתא בטל ברוב שמא חכמים החמירו כיון דעיקר חשוב ולא בטל ומדרבנן הוא דמיבעיא ליה והקשה הרב ר' אליעזר ממיץ אמאי לא הוי זה וזה גורם ומותר שהקרקע שהיא היתר והעיקר שהוא איסור גורמין לגידולין ותירץ דסבר זה וזה גורם (מותר) [אסור] וקשיא להר״ם דהכא חד גורם הוא דקרקע לא חשבינן לה לגורם דהיתר כדאמר פרק אלו טריפות (חולין דף נח -) [ומודו] בביצה טריפה שהיא אסורה בדספנא מארעא דחד גורם הוא והטעם משום דגורם דקרקע אינו מינו ואינו דומה לגורם דתרנגולת ולכך לא חשיב זה וזה גורם דדוקא גבי שאור של חולין ושל תרומה וכן גבי זבל של עבודת כוכבים דדמי אהדדי ולכן מפרש הר״ם דלא שייך זה וזה גורם [אלא] היכא דגורם דאיסור דהיינו עיקר מתבטל הוא בגידולים ואינו בעין שאינו ניכר לא שייך זה וזה גורם וכן בשאור של תרומה מיירי שהוא בעין:"],[2,"בצל של תרומה שנטעו","ולקמן מוקי לה בבצל דגידולי תרומה דגידולי גידולין מותרין:"],[2,"ורבו גידולים על עיקרו מותר","אלמא גידולי היתר מעלין עיקר דאיסור ואע\"פ שאין זרעו כלה כמו בצל:"],[3,"ילדה שסיבכה בזקנה ובה פירות","שהם ערלה אפי' הוסיף במאתים דהיתר אסורים הפירות דעיקר חשוב ואינו בטל בתוספת היתר דכל התוספת דמסיבוך ואילך מותרים דבטל בזקנה גם אילו לא היה - בה פירות וסיבכה תהיה מותרת שמתבטלה בזקנה (אחר) [אלמא] גידולי היתר אין מבטלין עיקר של איסור:"],[4,"בצל שנטעו בכרם","ונאסר כדין כלאי הכרם ונעקר הכרם דהשתא מותרין כל הגידולין:"],[4,"אסור","אפילו הוסיפו מאתים על העיקר אלמא דעיקר האסור אינו בטל ה\"נ בצל דשביעית אינו בטל אלמא (אי איכא [תרין] דאמרי דגידולי היתר אין מבטלין לעיקר דאיסור:"],[5,"ליטרא בצל שתיקנה","פירוש שעישרה מתרומות ומעשרות וזרעה:"],[5,"מתעשרת לפי כולה","ולא אמרי' דליטרא א' שעם הגדולין היה מן העיקר שהרי אין זרעו כלה וכבר היא מתוקנת משום דגידולי איסור מבטלין העיקר ה\"נ נימא דגידולי שמינית מבטלין עיקר של שביעית:"],[6,"דלמא התם לחומרא","דגידולי איסור מבטלין היתר אבל של היתר שמא לא יבטלו איסור:"]]],[["כל דבר שיש לו מתירין כגון טבל ומעשר שני והקדש וחדש לא נתנו בהן חכמים שיעור וכל דבר שאין לו מתירין כגון תרומה ותרומת מעשר וחלה וערלה וכלאי הכרם נתנו בהם חכמים שיעור","אמרו לו והלא שביעית אין לה מתירין ולא נתנו בה חכמים שיעור דתנן השביעית אוסרת כל שהוא במינה אמר להן אף אני לא אמרתי אלא לביעור","אבל לאכילה בנותן טעם ודלמא הא נמי לחומרא שאני","אלא מן הדא פשטה דתנן בצלים שירדו עליהם גשמים וצמחו אם היו עלין שלהן שחורין אסורין הוריקו מותרין","ר' חנניא בן אנטיגנוס אומר אם יכולין ליתלש בעלין שלהן אסורין וכנגדן למוצאי שביעית מותרין למימרא דגידולי היתר מעלין את האיסור ודלמא במדוכנין","אלא מן הדא דתניא"],[[0,"כגון טבל","שיש לו מתירין שמתקנו וניתר ומעשר והקדש יש לו מתירין על ידי פדייה וחדש עומר מתירו להכי אפילו באלף לא בטלי דהא אפשר להו בתקנתא:"],[0,"נתנו בהם חכמים שיעור","דתרומה בטלה במאה וערלה במאתים:"],[1,"השביעית אוסרת כל שהוא במינה","שאם נתערבה סאה של חטין של שביעית באלף של היתר אינה בטלה:"],[1,"אמר להם אף אני לא אמרתי","שיהא שביעית אוסרת במינה כל שהוא:"],[1,"אלא לביעור","שאם נטל בצל של ששית ונטעו בשביעית והוסיפה כל שהוא אותו כל שהוא מבטל את העיקר ומחייב כולו בביעור דמוצאי שביעית:"],[2,"אבל לאכילה","שאם נתערבו פירות שביעית בפירות שמינית לאחר שנתחייבו בביעור ולא ביערן דהשתא קיימי באיסור אכילה אינה אוסרת אלא בנותן טעם ואם אין בה בנותן טעם מתבטל ומדקתני לא אמרתי אלא לביעור דגידולין מבטלין את העיקר התם נמי בבעיא של ישמעאל גידוליו מבטלין את העיקר:"],[2,"הא נמי לחומרא","דהא דאמר לענין ביעור דגידולין מבטלין את העיקר היינו נמי לחומרא שכולן חייבין בביעור העיקר והתוספת אבל בעיא דישמעאל להיתר היא:"],[3,"בצלים","של ששית שירדו עליהם גשמים בשביעית וצמחו מאיליהן בלא נטיעה:"],[3,"אם היו עלין שלהן שחורין","שמחמת שצמחו יש להן כח עוד ליגדל אסורין דודאי גדלי ממי שביעית וגידוליו מבטלין את העיקר:"],[3,"הוריקו","שהן כמו כמושין ירוקין והכסיפו פניהם מותרין שלא גדלו כלום בשביעית:"],[4,"אם יכולין ליתלש","מן הקרקע בעלין שלהן שכל כך יש להן כח בעלין שלהן שכשאוחז בעליהן שומט עיקרו עמו מן הקרקע אסורין דחשיבי גידולי שביעית:"],[4,"כנגדן למוצאי שביעית מותרין","שאם של שביעית וצמחו בשמינית ויש להן כח בעלין מותרין דגידולי היתר מבטלין העיקר של איסור והיינו להיתר כגון הך בעיא דישמעאל ומהא פשטה:"],[4,"ודלמא","לעולם אין גידולי היתר מבטלין את האיסור והכא היכי דמי במדוכנין כלומר האי דקתני וכנגדן למוצאי שביעית מותרין כגון שהודכו שכתשן במדוכה דליתנהו לעיקרן בעינייהו אבל בבעיא דישמעאל דאיתיה לעיקר בעין איכא למימר דלא בטלי:"]],[[0,"כל דבר שיש לו מתירין כגון טבל","שנתערב בחולין דמצי מעשר עליו מדמאי או מעציץ שאינו נקוב:"],[0,"ומעשר שני","דאפשר להעלותו ולאוכלו או לפדותו:"],[0,"וחדש","דהאיר המזרח מתיר:"],[0,"והקדש","דאי בעי פריק ליה:"],[0,"לא נתנו חכמים שיעור","ואסורין בכל שהוא ואין להקשות דבפ' בתרא דע\"ז (דף עג:) אמר דבטבל שלא במינו בנ\"ט י\"ל דהא נמי דאמר שלא נתנו בו שיעור משום דיש לו מתירין היינו דווקא במינו אבל שלא במינו בטל וכן משמע לעיל גבי יין שהוא בנ\"ט ואע\"ג דהוי דבר שיש לו מתירין וא\"ת פרק בתרא דמסכת ע\"ז (שם) דקאמר חוץ מטבל ויין נסך דבמינו במשהו ופריך בשלמא עבודת כוכבים משום חומרא דע\"ז אלא טבל מאי טעמא ומסיק כהיתרו כך איסורו פירוש דחיטה אחת פוטרת את הכרי ולימא טעמא משום דיש לו מתירין וי\"ל דהתם בטבל שהלכו בעליו למדינת הים דאין לו מי יתירו אבל קשה למה לי טעם דיש לו מתירין תיפוק ליה משום דכהיתרו כך איסורו:"],[0,"וכל שאין לו מתירין כגון תרומה","ולקמן מפרש אמאי הוי אין מתירין:"],[0,"וערלה וכלאי הכרם נתנו בו חכמים שיעור","תרומה בק' ערלה וכלאים במאתים ומיירי במין במינו דבשאינו מינו אמרי' פ' גיד הנשה (חולין דף צז -) דתרומה בנ\"ט:"],[1,"דתנן השביעית אוסרת בכל שהוא","והא דאיבעי' ליה לעיל אי גידולי דהיתר מבטלין לעיקר דשביעית י\"ל דהכא מיירי בדבר לח אבל ביבש לא א\"נ שמא גידולי חשיבי טפי ומבטלי עיקר:"],[1,"אמר להם שביעית אינה אוסרת בכל שהוא אלא לביעור פירות","פירש הרב רבי אליעזר כגון פירות ששית שנכנסו בשביעית וגדלו משהו וצריכין ביעור כפירות שביעית דגידולי איסור חשיבי ומבטלי לעיקר דהיתר אבל לאכילה כגון לאחר ביעור בפירות שביעית שנתערבו בפירות דהיתר אינו אוסר במשהו אלא בנותן טעם כשאר איסורין אלמא דגידולי שביעית מבטלין לעיקר דהיתר ה\"נ נימא בבעיין דבצל דגידולי היתר מבטלי לעיקר דאיסור ודחי הא נמי לחומרא אזלינן דגידולי שביעית מבטלין העיקר אבל להקל לא מבטלי גידולי דהיתר לעיקר דאיסור ומה שפירש אלא לביעור לענין פירות ששית שנכנסין בשביעית ק' להר\"מ דתניא כל הספיחין מותרין חוץ מספיחי כרוב ומפרשינן דמיירי בספיחי ששית הנכנסים בשביעית אלמא דגידולי שביעית אינן אוסרין במשהו ונראה דשמא התם מיירי שגמרו בששית ולא גדלו כלל בשביעית וספיחי כרוב אסורין כדמפרש שמא יקח מן העלין ויאמר מן האמהות לקחתי ועוד קשה להר\"ם מהך דמעביר עציץ נקוב בכרם אם הוסיף מאתים אסור לא הוסיף מאתים מותר אלמא דגידולי איסור אינם אוסרים במשהו וכן מצינו בהך דבצלים שירדו עליהם גשמים וצמחו הוריקו מותרין אלמא דגידולי שביעית אינם אוסרים במשהו לכך מפרש הר\"ם דהכא מיירי בבצל שנעקר בששית ונטעה בשביעית ומכיון שהוסיף משהו נאסר כולו כמו כלאי הכרם דעיקרם נאסר דה\"נ אמר התם זרעו מעיקרו בהשרשה כלומר כשתחלת זריעתו באיסור זרוע ובא הוסיף אין לא הוסיף לא והכי נמי תחלת זריעתו באיסור היתה מיהו יש ליישב דלביעור קשה דהיה לו לומר לגידולין אין לו זריעה:"],[3,"בצלים","של ערב שביעית:"],[3,"וירדו עליהם גשמים","בשביעית וצמחו:"],[3,"אם עלין שלהם שחורין","דדרכם להשחיר כשיורדין עליהם גשמים:"],[3,"אסורין","דבידוע שגדלו רובם בשביעית:"],[3,"הוריקו","לא גדלו רובם ומותרין:"],[4,"רבי חנינא בן אנטיגנוס אומר","אף בשלא הושחרו אם יכולין וכו' שגדלו כל כך אסורין דבידוע שגדלו רובם בשביעית:"],[4,"וכנגדם למוצאי שביעית מותרין","כלומר בצלים שבאים משביעית - לשמינית אלמא דגידולי היתר מבטלין לאיסור:"],[4,"ודלמא במדוכנים","שדכו אותם במדוכה בשביעית ולא חשיבי ובטלים בגידולין אבל היכא דלא דכו מיבעיא לן אי בטלו אי לא בטלו:"]]],[["המנכש עם הכותי בחסיות אוכל מהן אכילת עראי ומעשרן ודאי","רבי שמעון בן אלעזר אומר אם ישראל חשוד על השביעית למוצאי שביעית מותר למימרא דגידולי היתר מעלין את האיסור ודלמא בדבר שזרעו כלה הא תניא אלו הן חסיות כגון הלוף השום והבצלים","ודלמא במדוכנין חשוד על השביעית קתני ודלמא בתערובת המנכש קתני","לימא תיהוי תיובתיה דרבי יוחנן ודרבי יונתן אמר רבי יצחק שניא שביעית הואיל ואיסורה ע\"י קרקע בטילתה נמי ע\"י קרקע","הרי מעשר דאיסורו ע\"י קרקע ואין בטילתו על ידי קרקע דתניא ליטרא מעשר טבל שזרעה בקרקע והשביחה והרי היא כעשר ליטרין חייבת במעשר ובשביעית ואותה ליטרא מעשר עליה ממקום אחר לפי חשבון"],[[0,"בחסיות","מפרש לקמן:"],[0,"אוכל מהן עראי","כמו שאר טבל גמור:"],[0,"ומעשרן ודאי'","ולא דמאי דודאי כותי לא הפריש מעשר מהן כלל:"],[1,"רשב\"א אומר כו'","טעמיה דנפשיה קאמר:"],[1,"אם ישראל חשוד על השביעית","שחשוד שנוטע חסיות שביעית בשמינית ישראל המנכש עמו בשמינית מותר לו לאכול מהן משום דגידולי היתר שגדלו בשמינית מעלין את האיסור:"],[1,"ודילמא","הא דרבי שמעון בן אלעזר דגידולי היתר מעלין את האיסור בדבר שזרעו כלה וקא פריך ומי מצית אמרת דבדבר שזרעו כלה מיירי והתניא ואלו הן חסיות הלוף לופינ\"א מכלל דבדבר שאין זרעו כלה מיירי ואפ\"ה מותר ושמע מינה גידולי היתר מעלין את האיסור ולעולם מהא פשטה: וקא פריך עלה דלמא מהא לא תפשוט דבמדוכנין קא מיירי ושמא כלו כשהן נידוכין דליתא לעיקר בעין שהוא מתכוין לכותשן כדי שיהו בטלין:"],[2,"תריץ הא לא מצית אמרת דחשודי על השביעית קתני","וכיון דחשוד הוא לא משגח ליה להאכילן נידוכים ושלימים מאכילן ולעולם תפשוט מינה דגידולי היתר מעלין את האיסור:"],[2,"ודילמא בתערובת","שמעורבין אותן חסיות בין שאר ירקות של היתר ואוכלן על ידי תערובת משום הכי שרי הואיל דליתיה לעיקר בעין אבל אי איתיה כגון בעיא דישמעאל אמרי' דאין גידולי היתר מעלין את האיסור:"],[2,"לא סלקא דעתך המנכש קתני","באותו מין שמנכש עמו אוכל ולעולם פשטינא מהא דגידולי היתר מעלין את האיסור והואיל דאוקימנא דגדולי היתר מעלין את האיסור לימא תיהוי תיובתא דרבי יוחנן ורבי יונתן דאמרו אין מעלין:"],[3,"הואיל ואיסורו על ידיי קרקע","דכתיב ושבתה הארץ (ויקרא כה):"],[3,"בטילתו נמי על ידי קרקע","כי רבו גידוליו על עיקרו אבל ערלה דמיירי בה רבי יוחנן שאין איסורו אלא בשנים וכלאי הכרם אינה אוסרת מחמת קרקע אלא מיני תערובת זרעונין אוסרין מש\"ה אין בטילתן ע\"י קרקע:"],[4,"הרי מעשר וכו' ליטרא מעשר טבל","ליטרא של טבל שהורם ממנו תרומה ומעשר ראשון אבל גבי לוי הוי טבל דאכתי לא תרם ממנו מעשר מן המעשר דהיינו. תרומת מעשר וזרעה בקרקע כשאינה מעושרת:"],[4,"והרי היא כעשרה ליטרין","עם התוספת והעיקר שרבו גידוליו כ\"כ:"],[4,"חייבת במעשר","כל עשר ליטרין:"],[4,"ובשביעית","נמי ששביעית נוהגת בהן שהרי הוא כדגן מעושר בעלמא שזרעו חייב בכל:"],[4,"ואותה ליטרא","שזרע בן לוי כשאינה מעושרת אע\"פ שעישרה עכשיו צריך לעשרה פעם שניה תרומת מעשר שהניח הלוי אשתקד שלא הפריש ממנה שבדין הוא שלא ישתכר בכך שזרעה כשאינה מעושרת:"],[4,"ומעשר עליה ממקום אחר","מפירות של אשתקד וזהו ממ\"א ולא מפירות של שנה זו שאין מעשרין מן החדש על הישן לישנא.) אחרינא ממ\"א לא ידעינן מ\"ר:"],[4,"לפי חשבון","יעשר הליטרא שהניח אשתקד אלמא דאין בטילת' ע\"י קרקע דאע\"ג שנזרעה חייב בתרומת מעשר וק' לר' אמי דפשיטא ליה דגדולי היתר מעלין את האיסור דהא חזינן הכא דחייב להפריש מעשר שלאותה ליטרא לפי חשבון:"]],[[0,"אלא מן הדין המנכש עם הכותי","דבסתמא אם אינו עושה עמו במלאכה אינו אוכל דישראל מובדלים מהם:"],[0,"בחסיות","מפרש לקמן הלוף והשום והבצל - מנכש תולש אחד בינתים כדי שיגדלו יותר:"],[0,"אוכל מהם עראי","[ולא חיישינן] דלמא אותו שזרע הכותי נתחייבו והוקבעו למעשר והוו טבל וגידוליו טבל דמסתמא יש לנו לומר שאותם שזרע לא ראו פני הבית והיה מותר לאכול מהם עראי:"],[0,"ומעשרן","אם לוקח מהן מן הכותי דכותים אינם מעשרים אפילו תרומה גדולה:"],[1,"אם ישראל חשוד על השביעית","ומנכש עמו במוצאי שביעית:"],[1,"מותר","אם אותם חסיות שעושה גדלו מקצתם בשביעית ונכנסו בשמינית מותר לאכול מהם דאף כי הוא חשוד ושמא נטעם בשביעית אתו גידולי דשמינית ומבטלין לאיסור:"],[1,"בדבר שזרעו כלה","כגון תבואה אבל בדבר שאין זרעו כלה מיבעיא ליה:"],[2,"ודלמא במדוכנין","שדכן בשביעית:"],[2,"הא חשוד קתני","ולא טרח להתירו בולי האי ואין לנו לומר שדכן:"],[2,"ודלמא בתערובת","הא דקתני למוצאי שביעית מותר לאכול עמו היינו בביתו פירות תלושין דאיכא למימר דאיכא רובא דפרי שגדלו כולם בשביעית ולא איירי כלל מפירות שנכנסו משביעית לשמינית:"],[2,"המנכש קתני","ואוכל מאותם המחוברות שגדלו בשביעית ואם כן על כרחך ההיתר משום שדותיו דגידולין:"],[3,"לימא תיהוי תיובתא דרבי יוחנן ורבי יונתן","דאמרי לעיל גבי ילדה שסיבכה בזקנה וגבי בצל שנטעו בכרם דגידולי היתר אינם מעלין האיסור:"],[3,"אמר רבי יצחק שאני שביעית הואיל ואיסור על ידי קרקע בטלה נמי על ידי קרקע","כלומר שביעית היתרו ואיסורו תלוי על ידי קרקע ואין התרת גידולין תלוי במעשה האדם דכי אתיא שמינית הם היתר אבל לעיל בהך דילדה שסיבכה בזקנה ההיתר תלוי במעשה האדם שסבכה ודמי למבטל איסור בתחלה אבל שביעית ממילא משתרין גידולין למוצאי שביעית וכן בהך דרבי יונתן דבצל שנטעו בכרם ונעקר הכרם ההיתר בא על ידי שנעקר הכרם ולכך לא מבטלת היתר לאיסור:"],[3,"","והרי מעשר דאיסורו על ידי קרקע ואין התירו על ידי קרקע דתניא ליטרא מעשר טבל שנטעה והרי היא כעשר ליטרים חייבת במעשר ובשביעית ואותה' ליטרא מעשר עליה לפי חשבון היתה טבולה לתרומת מעשר כלומר שהיא של מעשר ראשון והרי היא טבולה לתרומת מעשר וגידולין טבל גמור:"],[4,"והתניא וכו' השום","ושום אין זרעו כלה:"]]],[["אמרי מעשר דיגון הוא דקא גרים ליה","מתיב רמי בר חמא קונם פירות האלו עלי קונם הן על פי קונם הן לפי אסור בחילופיהן ובגידוליהן שאני אוכל ושאני טועם מותר בחילופיהן ובגידוליהן בדבר שזרעו כלה אבל בדבר שאין זרעו כלה אפילו גידולי גידולין אסורין","אמר רבי אבא שאני קונמות הואיל ואי בעי מתשיל עלייהו הוו להו כדבר שיש לו מתירין ואין בטיל ברוב","והרי תרומה דאי בעי מיתשיל עלה ובטלי ברוב דתנן סאה תרומה טמאה שנפלה לפחות ממאה חולין תרקב הא למאה תעלה אמרי בתרומה ביד כהן עסקינן דלא מצי מיתשיל עלה","אי הכי אימא סיפא אם היתה טהורה תמכר לכהן אלא בישראל שנפלו לו מבית אבי אמו כהן עסקינן","[והא] קתני סיפא תימכר לכהן חוץ מדמי אותה סאה","אלא אימא בשלמא קונמות מצוה לאיתשולי עליהן משום דרבי נתן דאמר רבי נתן כל הנודר כאילו בנה במה והמקיימו כאילו מקטיר עליה תרומה מאי מצוה לאיתשולי עלה","גופא אמר רבי יוחנן ליטרא בצלים שתיקנה וזרעה מתעשרת לפי כולה יתיב רבה וקאמר להא שמעתא אמר ליה רב חסדא מאן צאית לך ולר' יוחנן רבך היתר שבהן להיכן הלך אמר ליה מי לא תנן דכוותה בצלים שירדו עליהם גשמים וצימחו"],[[0,"תריץ מעשר","תרומת מעשר דיגון הוא [דקא גרים]. ליה דלא מחייב בתרומת מעשר עד דמידגן והאי מאשתקד נידגנה הלכך מעשר עליה משל אשתקד ולא הוי איסורו על ידי קרקע הלכך לא הוי בטילתו ע\"י קרקע:"],[1,"אפילו גידולי גידולין אסורין","אלמא דאין גידולי היתר מעלין את האיסור וקשיא לרבי אמי:"],[2,"ואין בטיל ברוב","כלומר ברוב מדתו בגדוליו רבים:"],[3,"הרי תרומה דיאי בעי מיתשיל עלה","שאם היה בדעתו להפריש תרומה ומעשר על פירותיו מפירות קופה זו וטעה ונתן מקופה אחרת יכול לשאל עליה לפני חכם ולומר לו לא היה בדעתי ליתן מקופה זו אלא מזו ולא הויא תרומה ואפילו הכי בטלה ברובא דתנן וכו':"],[3,"תירקב","הכל שאין לה תקנה לא לכהן ולא לישראל:"],[3,"הא אם נפל למאה תעלה","סאה אחת ושאר מותר אלמא דבטלה ברוב דידיה כמו האי דהיינו במאה ואכתי קשיא לרבי אמי מתני' דנדרים:"],[3,"[ומשני] הא תרומה בתרומה ביד כהן עסקינן","דמאחר שזכה בה כהן לא מצי מיתשיל עלה אינש ולא דמי לקונמות:"],[4,"תימכר לכהן","הרי ביד כהן היא ואין צריך לו למוכרה:"],[4,"אלא ביד ישראל עסקינן שנפלו וכו'","דלא מצי איהו מיתשיל עלה שכבר זכה בה כהן:"],[5,"והא קתני סיפא אם היתה טהורה תימכר לכהן","שהרי ביד ישראל היא חוץ מדמי אותה סאה אם נפלה לו מבית אבי אמו כהן אמאי אמר חוץ מדמי אותה סאה אפילו אותה סאה נמי תימכר הואיל ובאתה לו בירושה:"],[6,"אלא","לעולם בתרומה ביד ישראל עסקינן ומצי מתשיל [עליה] ואפילו הכי בטלה ברובא והדרא קושיא לדוכתיה תריץ הכי גרסינן אלא גבי קונמות מצוה לאיתשולי עלייהו וכמאן דאיתשיל עלייהו דמי והוה ליה דבר שיש לו מתירין ואין בטל ברוב:"],[6,"אבל תרומה מאי מצוה איכא לאיתשולי עלה","וכיון דלאו מצוה היא לא אתי לאיתשולי עלה וכדבר שאין לו מתירין דמי להכי בטיל ברובא:"],[7,"וזרעה מתעשרת לפי כולה","אפילו מן הליטרא של עיקר:"],[7,"היתר שבהן","אותה ליטרא של עיקר שהיתה מתוקנת:"],[7,"היכן הלך","הואיל ואיתיה בעין אין צריך לעשרם:"],[7,"בצלים","של ששית וכו' לימא היתר שבהן העיקר שגדלו בששית להיכן הלך ותשתרי העיקר:"]],[[1,"מתיב רמי בר חמא קונם פירות הללו עלי קונם כו'","דכיון דאמר קונם סתמא אסרם עליו בהנאה בין בחליפין בין בגידולין:"],[1,"קונם שאני אוכל","לא אסר עצמו אלא בגופם והלכך בדבר שזרעו כלה הגידולין מותרין אבל בדבר שאין זרעו כלה אפילו גידולי גידולין אסורין אלמא גידולי היתר אינם מעלים את האיסור דאי מעלים גידולין אמאי אסורין הרי לא אסר עצמו אלא בגוף הפירות ולא אסר בגידולין וליתו גידולי היתר וליבטלו לעיקר אלא שמע מינה דגידולין לא מבטלין לעיקר הלכך העיקר מתפשט בגידולין ואסורין מטעם עיקר ועיקר חשוב ואינו בטל ונהי דודאי אינו מתיר ע\"י קרקע כמו שביעית מכל מקום דמי לעל ידי קרקע התירו ולא שייך לשנויי דיגון הוא דקא גרים ליה:"],[2,"א\"ר [אבא] שאני קונמות הואיל ואי בעי מיתשל עלייהו והוי כדבר שיש לו מתירין ולא בטיל","ולכך לא מבטלי גידולי לעיקר והא דתנן לעיל (נדרים דף נב -) קונם יין ונפל לתבשיל אם יש בו טעם יין אסור ואם אין בו טעם יין מותר דבטל היינו משום דהוי מין בשאינו מינו דהאי דדבר שיש לו מתירין לא בטיל היינו מין במינו והא דמסיק רב אשי פרק בתרא דביצה (דף לט -) דמים ומלח לא בטילי בעיסה משום דהוי דבר שיש לו מתירין ואע\"ג דלא הוי מין במינו יש לומר דהתם משום דאיכא נתינת טעם ולא בטלי:"],[3,"והרי תרומה כו' דתנן","ה\"ה דהוי מצי למיפרך למאן דאמר תרומה אין לה מתירין:"],[3,"סאה של תרומה שנפלה לפחות ממאה תרקב","דאינה בטלה בפחות מק' ואסמכוה רבנן [אקרא דכתיב] תרימו ממנו מה שאתה מרים ממנו שנפל לתוכו מקדשו:"],[4,"א\"ה","דמוקי להו ביד כהן אם כן איירי שהדימוע אירע בבית הכהן [אימא סיפא אם היתה טהורה] תמכר לכהן והא דידיה הוא אלא מיירי שהיא ביד ישראל וא\"ה בישראל שנפלו לו תרומה מבית אבי אמו כהן דהשתא הוי דידיה:"],[5,"תמכר לכהן חוץ מדמי סאה","והא דידיה הוא אי מיירי שהן ביד הישראל ושפיר מצי מזבין לה אלא שמע מינה דמיירי בתרומה שהפריש ישראל ליתן לכהן:"],[6,"","הכי גרסינן אלא בשלמא קונמות מצוה לאיתשולי עלייהו והוי דבר שיש לו מתירין:"],[7,"גופא כו' היתר שבהם להיכן הלכה","כלומר היתר שהיה בליטרא שעישר היכן הלך דסבירא להו דלא קאמר גידולי היתר מעלין את האיסור מצי לאוכוחי דגידולי היתר מעלין את האיסור מההיא דמנכש דלעיל:"]]],[["אם היו עלין שלהן שחורין אסורין הוריקו מותרין וכי שחורין אמאי אסורין לימא היתר שבהן להיכן הלך א\"ל מי סברת על עיקר קתני אתוספת קתני אסורין אי הכי מאי אתא רשב\"ג למימר דתניא רשב\"ג אומר הגדל בחיוב חייב הגדל בפטור פטור תנא קמא נמי הכי אמר","כולה מתני' רבן שמעון בן גמליאל קתני לה ועד כאן לא שמעת ליה לרבן שמעון בן גמליאל דלא קא טרח אבל היכא דקא טרח בטיל ברובא","וכל היכא דקא טרח בטיל ברובא והרי ליטרא מעשר טבל דקטרח וקתני ואותה ליטרא מעשר עליו ממקום אחר לפי חשבון שאני גבי מעשר דאמר קרא (דברים יד, כב) עשר תעשר וגו' והיתירא זרעי אינשי איסורא לא זרעי אינשי","גופא א\"ר חנינא תירתאה א\"ר ינאי בצל של תרומה שנטעו ורבו גידוליו על עיקרו מותר למימרא דגידולי"],[[0,"אתוספת קתני","דאסורין לאכלן בשמינית דחייב לבערן אבל העיקר שרי דאמרינן היתר שבהן להיכן הלך:"],[0,"הגדל בחיוב","בשביעית חייב בביעור:"],[0,"והגדיל בפטור","דזהו העיקר הגדל בששית פטור הכי נמי קאמר תנא קמא כו':"],[1,"","תריץ כולה מתניתין ר' שמעון בן גמליאל קתני לה והכי קתני שרשב\"ג אומר הגדל כו'. ולעולם אמרי' היתר שבהם להיכן הלך: וקא מהדר גמרא לעול' ואפי' לר\"ש לא אמרי' היתר שבהן להיכן הלך ועד כאן לא אמר רשב\"ג הגדל בפטור פטור דאמרינן היתר שבהן להיכן הלך דלא קא בטיל היתר היכא דלא קא טרח כגון התם שירדו עליהן גשמים וצמחו מאיליהן אבל היכא דקא טרח כגון הכא דנטען כדקתני שתיקנה וזרעה הואיל ועבד בה מעשה גידולין של איסור מבטלין את ההיתר והוי הכל אסור להכי מתעשר לפי כולה:"],[2,"מעשר עליה לפי חשבון","ואף על גב דקא טרח לגבי שאר גידולין:"],[2,"היתירא זרעי אינשי","דבר שהוא מתוקן רגילים בני אדם לזרוע וסגי ליה בשני מעשרות במעשר ראשון ומעשר שני אבל דבר של איסור אין רגילין בני אדם לזרוע והואיל ואיהו קא זרע באיסורא שזרעה בלא תרומה ומעשר קנסינן ליה השתא שמעשר אותו עישור שהיה לו ליתן אשתקד שלא ישתכר בכך:"]],[[0,"אם היו עלין [שלהן] שחורין אסורין","אף מה שגדלו בששית אלמא היתר דידהו פקע:"],[0,"אמר ליה רב חסדא מי סברת על עיקר קתני אסורין על תוספת קתני","אבל על עיקר מותר אם ניכר מן הגידולין:"],[0,"א\"ה","דלת\"ק אין איסור אלא בגידולין לבד מאי אתא למימר דתני ר\"ג הגדל בחיוב חייב הגדל בפטור פטור רבן גמליאל [קאמר] אפי' עליהן שרי ואינם אסורין אלא הגדל בחיוב כלומר באיסור שביעית אבל הגדל בפטור כלומר בהיתר קודם שביעית ונהי דאין העיקר ניכר וכולו אסור מכל מקום נפקא מינה במה שהעיקר מותר שאינו צריך ששים רק מן הגידולין:"],[0,"ת״ק נמי הכי קאמר","בתמיה דלדידך דאמרת דלת״ק אינו אוסר אלא הגידולין: ה״ג כולה מתניתין ר״ג [קתני לה] (דלת״ק אינו אסור אלא גידולין) ועד כאן לא שמיע ליה לר״ג דלא טרח אבל טרח בטל ברוב כך השיב לו רבה דסבירא ליה דהתר פקע וקאמר דר״ג נמי דאמר גדלו בפטור פטור מודה הכא בליטרא בצל שתיקנה וזרעה שהיתר שבו פקע דהתם במילתי' דר״ג לא טרח בגידולין ומאיליהם הם באים הלכך לא חשיבי לבטל העיקר אבל בבצל דטרח בגידולין והחשיבם מבטלין את העיקר ואמר הר״ם דהאי טעמא דטרח ולא טרח היינו כדאמר במנחות פרק רבי ישמעאל (מנחות דף ע -) גבי הך דבצל שתיקנה דהכא דטרח בנטיעתו אבל התם בגידולין דשביעית לאו היינו נטיעתו כלו' אין הנטיעה באיסור שבערב שביעית נטועי' ובאים משביעית אבל הכא תחלת נטיעתה [באה בשביעית] לכך מבטלין גידולין לעיקר ודבר זה מגומגם דליתא להך מילתא דר״ג גבי הך ברייתא ואם היו שחורים עליהן:"],[2,"והרי ליטרא מעשר טבל","פי' לעיל אלמא אף על גב דלא קא טרח לא קמבטלי:"],[2,"שאני התם","בהך דקאמר דמתעשר לפי כולה דאמר קרא עשר תעשר את תבואת זרעך אלמא תבואה זרועה בעי לעשורי כל המעשרות והך נמי שתיקנה הוי סתם זריעה דהיתירא זרעי אבל איסור לא זרעי שאין דרך לזרוע מעשר עצמו כשאינו מתוקן לתרומת מעשר ומינה לא איירי קרא הלכך לא בטל ולא בעי לעשורי כבתחלה כיון דטרח בטלה אבל בהך ליטרא שתיקנה דהיינו כדרך שבני אדם מוציאין לזריעה יש לנו להעמיד בזה קרא דעשר תעשר שצריך לחזור ולעשר כבתחלה:"],[3,"גופא אמר רבי חנינא טירטאה בצל של תרומה כו' מותר","דהוי חולין ומותר לזרים:"]]],[["היתר מעלין את האיסור והתנן גידולי תרומה תרומה בגידולי גידולין קאמרינן הא נמי תנינא גידולי גידולין חולין הא קמ\"ל אפילו בדבר שאין זרעו כלה","והתנן הטבל גידוליו מותרין בדבר שזרעו כלה אבל דבר שאין זרעו כלה גידולי גידולין אסורין רבויא דרבו גידולין על עיקרו מותר קא משמע לן:","\u0001הדרן עלך נודר מן הירק\u0002","מתני׳ \u0001קונם\u0002 יין שאני טועם היום אינו אסור אלא עד שתחשך שבת זו אסור בכל השבת ושבת שעברה חדש זה אסור בכל החדש ור\"ח להבא","שנה זו אסור בכל השנה וראש השנה לעתיד לבא שבוע זה אסור בכל השבוע ושביעית שעברה","ואם אמר יום אחד שבת אחת חדש אחד שנה אחת שבוע אחד אסור מיום ליום","עד הפסח אסור עד שיגיע עד שיהא אסור עד שיצא עד לפני הפסח רבי מאיר אומר אסור עד שיגיע רבי יוסי אומר אסור עד שיצא:","\u0001גמ׳\u0002 קונם יין שאני טועם כו' אמר רבי ירמיה לכשתחשך צריך שאלה לחכם","מאי טעמא אמר רב יוסף גזירה היום משום יום אחד"],[[0,"תרומה","דאין גידולי היתר מעלין את האיסור:"],[0,"בגידולי גידולין קאמר","דהכי קאמר גידולי בצל של תרומה שנטעה ורבו גידוליו על עיקרו דהוו להו גידולי גידולין:"],[0,"תנינא ובו'","דגידולי גידולין של תרומה חולין:"],[0,"אפי' בדבר שאין זרעו כלה","כגון בצל גידולי גידולין מותר:"],[1,"בדבר שזרעו כלה","כגון חיטים גידולי גידולין דזהו השני:"],[1,"תריץ רבויא של גידולי גידולין דרבו גידוליו על עיקרו מותר קא משמע לן","כלומר הא אתא לאשמועינן גידולי גידולין של בצל של תרומה ורבו אותן גידולין על עיקרו מותר דזהו השלישי:"],[3,"מתני' קונם יין שאני טועם היום","דמשמע כל זמן שהוא יום ותו לא:"],[3,"שבת זו","והיה עומד בשבת אסור בכל השבת בששת ימי השבוע:"],[3,"והשבת שעברה","כלומר בשבת שהוא עומד בה ולהכי קרי ליה שעברה לפי שהשבת זה אינו מתחשב אחר ימים הבאים אלא אחר ששת ימים שעברו:"],[3,"חדש זה","אמר קונם יין שאיני שותה בזה החדש והיה עומד באותו יום של ר\"ח:"],[3,"אסור בכל החדש","בכל שלשים יום הבאים:"],[3,"וראש חדש להבא","כלומר ר\"ח זה שהוא עומד לתוכו הוא נמנה עם ימים הבאים שהוא ראשון שלהם:"],[4,"וכן אם היה עומד בראש השנה ואמר קונם יין שאיני טועם שנה זו","אסור בכל השנה ואותו היום של ראש השנה שהוא עומד בו ולהכי קרי לעתיד לבא לפי שהוא נמנה לימים ולחדשים הנכנסים שהוא אחר זמן ולהכי קאמר לעתיד ולא קאמר להבא:"],[4,"ואם היה עומד בשנת השמיטה ואמר קונם יין שאיני טועם בשבוע זו אסור בכל השבוע הבא","ואותה שנה שביעית שהוא עומד בה נמנית לשבוע שעברה להכי קרי ליה שעברה:"],[5,"ואם אמר","שאיני טועם יום אחד מעת לעת שאם היה עומד בשעת הנדר בחצי היום אסור למחר עד חצי היום וכן אם אמר שבת אחד באיזה יום שעומד בשבוע אסור עד יום שמיני לאותו יום שנדר וכן בשנה אחת וכן בשבוע אחת אסור שנה שלימה ושבוע שלם מיום ליום:"],[6,"מתני' אמר קונם יין שאיני טועם עד הפסח אסור עד שיגיע","לדברי הכל:"],[6,"עד שיהא אסור עד שיצא","דמשמע דאמר עד שיצא כל הפסח:"],[6,"עד פני פסח","משמע עד שיגיע ומשמע עד שיצא:"],[6,"עד שיגיע","דקסבר לא מעייל איניש נפשיה לספיקא דכיון דאיכא לספוקי אי משמע עד שיצא או עד שיגיע ודאי בדליכא ספיקא הרהר בדעתו בשעת הנדר דהיינו עד שיגיע. ורבי יוסי אומר עד שיצא. דסבר מעייל איניש נפשיה לספיקא דאיכא לספוקי שמא עד שיצא קאמר:"],[7,"גמ' לכשתחשך","אע\"פ שעבר היום:"],[7,"צריך שאלה לחכם","להתיר לו נדרו משום היכרא:"],[8,"גזירה היום אטו יום אחד","דאי אמרת לכשתחשך אע\"פ שעבר היום הוי מותר אתו למימר נמי כי נדר יום אחד ועומד בחצי היום מותר לכשתחשך ואיהו לא הוי מותר עד מעת לעת הילכך צריך שאלה לחכם וכיון דבעי שאלה לחכם חכם חוקר כיצד נדר ולא יבא לידי חילול נדר:"]],[[0,"בגידולי גידולין","כהך דבצל גופיה הוי גידולין של תרומה:"],[0,"ה\"ג התם דלא רבו הכא דרבו","פירוש הא דאמר גידולי גידולין אסורין גבי טבל היינו כל כמה דלא רבו גידולי גידולין על העיקר אבל הכא ברבו הלכך מבטלי גידולין לעיקר ובספרים כתוב ריבויא דרבו גידולין על עיקרו מותר קמ\"ל ויש לפרש כדפרישית דמלתא דרבי חנינא מיירי דרבו גידולין על עיקרו:"],[0,"","קמשמע לן רבי חנינא דאפילו דבר שאין זרעו כלה גידולי גידולין חולין:"],[1,"והתנן הטבל גידוליו מותרין לאכול אכילת ארעי בלא מעשר בדבר שזרעו כלה","כגון חיטין אבל דבר שאין זרעו כלה גידולי גידולין תרומה כמו טבל:"],[1,"ה\"ג התם דלא רבו הכא דרבו","פירוש הא דאמר גידולי גידולין אסורין גבי טבל היינו כל כמה דלא רבו גידולי גידולין על העיקר אבל הכא ברבו הלכך מבטלי גידולין לעיקר ובספרים כתוב ריבויא דרבו גידולין על עיקרו מותר קמ\"ל ויש לפרש כדפרישית דמלתא דרבי חנינא מיירי דרבו גידולין על עיקרו:"],[3,"קונם יין כו' שאני טועם היום אינו אסור אלא עד שתחשך","ולא אמר דאסור עד מעת לעת כמו בסיפא דאמר יום אחד:"],[3,"שבת זו","ועומד באמצע ביום ג' או ביום ד' אסור בכל השבת. כלומר כל ימי אותה השבוע עד סופה ושבת שעברה כלומר ושבת הבא עליו סוף השבוע אסור כמו כן דאף השבת משבוע שעבר ובגמ' פריך פשיטא:"],[3,"חדש זה","ועומד בט\"ו ימים בטבת אסור בכל החדש עד סופו:"],[3,"ור\"ח להבא","פי' ר\"ח שבט של אחריו היינו כלהבא ומותר בו שהוא [מחדש] הבא:"],[4,"שבוע זה אסור בכל השבוע","ועומד הוא באמצע השמיטה בשנה רביעית או חמישית לשמיטה אסור עד סוף השבוע:"],[4,"והשביעית שעברה","כלומר שנה השביעית הבאה היא כלשעבר שנמנית עם שמיטה שעברה ואסור בה פי' זה רהוט. וי\"מ שבת זו ועומד ביום שבת ונודר בשבת זו אסור בכל השבת כלומר בכל השבוע הבאה ושבת שעברה כלומר ויום השבת שהוא נודר בו גם הוא אסור ואע\"פ שאמת הוא שהוא משבוע שעבר הואיל ונדר בו אסור ובגמרא פריך פשיטא חדש זה ועומד בראש חדש אסור בכל החדש ור\"ח שהוא בו כלהבא כלומר אותו ר\"ח שנודר בו אסור ולכך קרי ליה להבא שהוא עם ראש חדש הבא וכן גבי ראש השנה נמנה משנה הבאה לכך קרי ליה להבא לפי שהוא נמנה משנה הבאה. שנה זו ועומד בראש השנה. שבוע זו ועומד בשנה שביעית אסור בכל השבוע ובשביעית שעברה כלומר אע\"פ שהיא מלשעבר אסור בה כיון שנודר בה:"],[5,"מיום ליום","כלומר עד שנה אחרת באותו יום וכן בשבוע אחרת לאותו יום שנדר:"],[6,"הנודר עד הפסח אסור עד שיגיע","דבלשון בני אדם עד ולא עד בכלל לכך אינו אסור אלא עד שיגיע:"],[6,"עד פני הפסח ר' מאיר אומר עד שיגיע","דה\"ק עד לפני יום של פסח:"],[6,"ר' יוסי אומר עד שיצא","דשמא ה\"ק עד פני שעה אחרונה של יום אחרון של פסח דסבר דמחית אינש נפשיה לספקא ושמא נתכוון לומר פני שעה אחרונה:"],[7,"אמר ר' ירמיה לכשתחשך צריך שאלה לחכם","ואינו מותר בלא שאלה ואע\"ג דמן הדין היה מותר שהרי הגיע זמנו גזירה אטו היכא דאמר יום אחד כלומר אי שרי ליה כשאמר היום לכשתחשך אתי למישרי כשאמר יום אחד ואז הוא אסור עד מעת לעת: א\"ה דחייש לאיחלופי ליגזר ביום אחד דליתסר אף כשהגיע מעת לעת עד הלילה שאמר עד מעת לעת משום היום דהיום הוא אסור עד הערב ומשני היום ביום אחד מיחלף ואתי למשרי כשנודר בבוקר ואומר קונם יום אחד עלי לכשתחשך שסבור שקיים נדרו לפי שעבר יום אחד אבל יום אחד בהיום לא מיחלף אם נתיר לו כשאמר יום אחד באמצע היום כשיבא מעל\"ע לא יבא להתיר כשאמר היום באמצע היום שעדיין לא שמר לא מע\"ל ולא יום שלם:"]]],[["א\"ל אי הכי ליגזור ביום א' משום היום","א\"ל היום ביום אחד מיחלף יום אחד בהיום לא מיחלף","אמר רבינא אמר לי מרימר הכי אמר אבוך משמיה דרב [יוסף] כמאן אזלא שמעתיה דרב ירמיה בר אבא כרבי נתן דתניא רבי נתן אומר כל הנודר כאילו בנה במה והמקיימו כאילו מקטיר עליה:","שבת זו אסור בכל השבת כולה: פשיטא מהו דתימא יומי דשבתא קאמר קמ\"ל:","חדש זה אסור בכל החדש ור\"ח להבא: פשיטא כי איצטריכא לחדש חסר","מהו דתימא ראש חדש לשעבר הוי ולא ליתסר קמ\"ל קרו אינשי ריש ירחא:","שנה זו אסור בכל השנה כולה:","איבעיא להו אמר קונם יין שאני טועם יום מאי דיניה כהיום או כיום אחד","ת\"ש ממתניתין קונם יין שאני טועם היום אין אסור אלא עד שתחשך הא יום כיום אחד דמי","אימא סיפא אמר יום אחד אסור מיום ליום הא יום כהיום דמי אלא מהא ליכא למשמע מינה","אמר רב אשי ת\"ש קונם יין שאני טועם השנה נתעברה השנה אסור בה ובעיבורה היכי דמי"],[[0,"אי הכי ליגזור יום אחד","דליהוי אסור עד שתחשך למחר משום היום דאי אמרת עד מעת לעת אסור ותו לא אתו למישרי נמי כי עמד בשחרית ואמר היום אתי למישתי בחצי היום והוא אסור עד שתחשך:"],[1,"אמר ליה רב יוסף היום ביום אחד מיחלף","דאי שרית היום לכשתחשך בלא שאלה מיחלף ואתי למישרי יום אחד משתחשך דסבר יצא אותו היום שנדר בו כמו כן והוא אינו מותר אלא מעת לעת:"],[1,"יום אחד בהיום לא מיחלף","דלא אשור לשתות למחר עד הלילה דלא אתי למישרי בהיום מחצי יום ואילך דליכא למיחש להכי דהכא לא גמר היום עדיין ומידע ידיע דאסור כל היום משום האי טעמא נמי לא מצרכינן שאלה לסוף מעת לעת דלא אתו למישרי מהיום מחצי יום ואילך דליכא למיחש בהכי כדאמרינן הכא לא גמר עדיין היום ומידע ידיע דאסור בכל היום:"],[2,"כמאן אזלא","הא שמעתתא דאמר רב ירמיה דצריך שאלה לחכם שאין ניתר ע\"פ עצמו כלל דמחמרינן עליה כמאן דלא עבד שפיר:"],[2,"כרבי נתן וכו'","הילכך צריך שאלה לחכם הואיל ועבד איסורא דמחמרינן עליה ואין מראין לו שקיים נדרו מעצמו אלא כשיתירו לו את נדרו ולא משום גזירה דרבינא לא סבירא ליה דרב יוסף וכל היכא דאיכא לאוקומי ביה שאלה מצריכינן ליה שאלה כגון הכא דאמר היום דאיכא למימר מעת לעת קאמר הילכך לכשתחשך צריך שאלה לחכם אבל כי אמר כבת וכולה מתניתין דליכא לאוקומי בהו שאלה דודאי לא משמע טפי אין צריך שאלה:"],[3,"יומי דשבתא קאמר","ימים דשבוע ולא דשבת עצמו:"],[4,"פשיטא","דיום ראש חדש נמי אסור שהרי יום ראש חדש נמנה לחדש זה הנכנס:"],[4,"כי איצטריך","למיתני במתניתין לחדש חסר בחדש שהוא שני ימים ראש חדש ויום ראשון של ראש חדש משלים לחדש מלא זה שעבר וזה הנכנס חסר הוא והוא נדר ביום ראשון של ר\"ח:"],[5,"לחדש שעבר הוי","ולא ליתסר ביה:"],[5,"קמ\"ל","אפילו הכי כיון דקרו ליה ריש ירחא אסור ביה נמי:"],[7,"דיניה כהיום","כאילו אמר היום לחוד ומותר לכשתחשך:"],[7,"או כיום אחד","ואסור מעת לעת:"]],[[2,"אמר רבינא כו' כר' נתן","וקנסא קנסינן ליה אף כי קיים נדרו עד שישאל לחכם ונראה דרבינא מוסיף על טעם דרב יוסף משום גזירה דבשאר נדרים לא קנסינן לשאול לחכם לאחר שנתקיימו אלא אית ליה טעמא דנדרים דגזרינן לעיל וקאמר דבהך טעמא דגזרי' לא סגי אם לא מטעם דקנסינן ליה כר' נתן שעבר על מה שקיימו:"],[3,"פשיטא","דאסור לשבת הבאה דבשבוע שעבר היא מהו דתימא יומא דשבת לא אסר עצמו אלא בימי המעשה שבשבוע ולא נתכוין לאסור בשבת קמ\"ל ולפירוש שני דמתני' פריך פשיטא כיון דקאי בשבת דאסור בו ומשני מהו דתימא דיומי שבוע העתידין לבא קאמר ולא יום השבת עצמו קמ\"ל דכיון דקאי בשבת אמרינן דאף בשבת - נדר ונ\"ל דהטעם לפי שלשון בני אדם לקרות השבוע שבת וא\"כ לשבוע הבא הוא מתכוין ולא לשבת לבד ומכל מקום כיון שעומד בשבת אמר שדעתו גם לשבת כדי שלא יהיה ספק בנדרו ושיחול משעה שנדר:"],[4,"חדש זה פשיטא","דראש חדש נידון בחדש הבא ומותר בו כי איצטריך לחדש חסר כלומר נדר באמצע חדש מלא וחדש חסר אחריו שר\"ח שני ימים ויום ראשון הוא להשלים יום של חדש שעבר דקס\"ד דאסור בו קמ\"ל דהא קרו אינשי ריש ירחא ליום ראשון של ר\"ח ובחודש הבא דיינינן ליה שאינו מנוי בלשון בני אדם בחדש שעבר ולפירוש אחר פשיטא כיון דעומד בר\"ח דאסור בו לא צריכא אלא לחדש חסר שראש חדש שלו שני ימים ונדר ביום ראשון ר\"ח שעבר ולא נתכוון אלא בימי של חדש שעבר קמ\"ל דקרו אינשי ריש ירחא ואינו נמנה בחדש שעבר והילכך כי אמר חדש זה מיתסר ביה וניחא טפי לישנא דחדש חסר לפירוש אחרון וכיון דקאמר דקרו ליה אינשי ריש ירחא א\"כ כשכותבין כתובה או שטרות ביום ראשון של ר\"ח כותבין יום פלוני שהוא ראש חדש ואין צריך לכתוב יום שלשים דהכי משמע לקמן (נדרים סג -) דתנן עד ר\"ח אדר [עד ר\"ח אדר] הראשון ומדמה בגמ' הך ברייתא דשטרות [לנדרים] אלמא דין שטרות כדין נדרים דלשון בני אדם:"],[4,"פסק","ומיהו בגיטין טוב לכתוב שהוא יום שלשים לחדש טבת וכן כתב רבינו תם בכתובת בתו:"],[7,"דיניה כהיום","ומותר משתחשך או כיום אחד ואסור במעת לעת:"],[9,"אלא מהא ליכא למשמע מינה","דלא ידעינן הי דוקא או רישא או סיפא:"],[10,"ת\"ש קונם יין שאני טועם השנה אסור בה עד סופה","ולא מיום ליום הילכך עד ראש השנה ואף כי נתעברה כל השנה עד סופה נקראת משנה זו:"],[10,"למה ליה [למימר]","פשיטא דאסור בה:"]]],[["אילימא כדקתני למה לי למימרא אלא לאו דאמר שנה אלמא שנה כהשנה דמי ויום נמי כהיום דיניה","לא לעולם דאמר השנה ומהו דתימא הלך אחר רוב השנים ולא אית בהו עיבור קא משמע לן","איבעיא להו אמר יין שאני טועם יובל מאי שנת חמשים כלפני חמשים או כלאחר חמשים","ת\"ש דתניא פלוגתא דרבי יהודה ורבנן (ויקרא כה, י) וקדשתם את שנת החמשים שנה שנת החמשים אתה מונה ואי אתה מונה שנת חמשים ואחת מכאן אמרו יובל אינו עולה למנין שבוע רבי יהודה אומר יובל עולה למנין שבוע","אמרו לו לרבי יהודה הרי הוא אומר (ויקרא כה, ג) שש שנים תזרע שדך ואין כאן אלא חמש","אמר להם לדבריכם הרי הוא אומר (ויקרא כה, כא) ועשת את התבואה לשלש השנים הרי כאן ארבע","אלא איכא לאוקמה בשאר שני שבוע דילי נמי איכא לאוקמה בשאר שני שבוע:","עד הפסח אסור כו': למימרא דרבי מאיר סבר לא מעייל איניש נפשיה"],[[0,"אילימא כדקתני","דאמר השנה למה לי למימר פשיטא כיון דאמר השנה משמע השנה זו קאמר ועיבורה נמי בכלל הוי:"],[1,"ולא אית בהו עיבור","ולא ליתסר בעיבורה קא משמע לן: היה עומד בשנה של יובל והיה אומר קונם יין שאיני טועם יובל מהו:"],[2,"שנת חמשים כלפני חמשים","ומותר נמי בשנת חמשים דאיהו לא קאסר עילויה אלא לאחר חמשים או בשנת חמשים נמי אסור דבשנת חמשים מתחיל יובל הבא:"],[3,"ואי אתה מונה שנת חמשים ואחת","שלא תתחיל למנות ז' שנים של שמיטה הבאה בשנת היובל עצמה שלא תהא מונה אחת לשנת נ' ולשנה הבאה אחריה שנת נ\"א שניה אלא לשנת חמשים ואחת תהא מונה אחת ושנת נ' עצמה נמנית ליובל שעבר שאין עולה למנין שבוע הבא כדאמרינן:"],[3,"יובל עולה למנין שבוע","דשנת חמשים עולה לכאן ולכאן:"],[4,"אמרו לו וכו'","אם כן ששנת יובל עולה למנין שבוע אינו אלא חמשה בשבוע ראשון של יובל שהשנה שהיא ראשונה שהיא יובל אסור לזרוע בה והשביעית נמי אסורה שהיא שמיטה ואינה אלא חמשה לזריעה:"],[5,"אמר להם לדבריכם הרי הוא אומר ועשת את התבואה לשלש השנים","שנה ששית ושנה שביעית ושמינית עד קצירתה ואי [נמי] אמרת אין יובל עולה למנין שבוע הרי כאן ארבעה שנים שצריכה לעשות לארבע שנים כיצד שנת מ\"ח היא ששית ותבואה שלה צריכה לששית עצמה ולשנת ארבעים ותשע שהיא שמיטה ולשנת חמשים שהוא יובל ולשנת חמשים ואחת עד הקציר הרי ארבע שנים והאי פירכא לדברי הכל היא דלרבי יהודה נמי איכא למיפרך דאע\"ג דאמר יובל עולה למנין מכל מקום אסור הוא בזריעה והוו נמי ארבע שנים:"],[6,"אלא","לדברי הכל ליכא לאוקמי להאי קרא אלא בשאר שני שבוע בשש השמיטות ולא בשמיטה שביעית של יובל ולא קשיא כלל לא לדידי ולא לרבנן לדידי נמי דפרכת לי שש שנים מוקמינן ליה לקרא בשאר שני שבוע בשאר שמיטין ולא בשמיטה ראשונה הסמוכה ליובל:"]],[[1,"הלך אחר רוב שנים","ולא אית בהו עיבור וכשנדר בשבט ונאסר בחדש העיבור יהיה מותר בחדש אחד לפני ראש השנה קמ\"ל דכולה עד סופה נקראת שנה:"],[2,"יין שאני טועם יובל","ה\"ה דמצי למיבעי כי אמר היובל ומיירי [שעומד] באמצע היובל בשנה ומיתסר עד סוף היובל ומיבעיא כשהגיע שנת היובל כלפני חמשים ומיתסר או כלאחר ושרי אי נמי לפי' שני דפרישית במתני' עומד בשנת יובל עצמו מיבעי ליה אם נאסר בה דאי כלפני חמשים ולא נתכוון לאסור אלא במנוייו הבא עליו:"],[3,"ת\"ש","מפלוגתא דר' יהודה ורבנן דתניא שנת חמשים ואי אתה מונה שנת חמשים ואחת מכאן שאין שנת חמשים נמנית במנין שמיטה שאם היה נמנה א\"כ היא אחת למנין שמיטה א\"כ לת\"ק שנת חמשים כלפני שהרי אינו נמנה לאחריו בשמיטה ולר' יהודה כלאחר חמשים:"],[4,"[ואין כאן] אלא חמש","כגון בשבוע ראשון שסמוך ליובל אחריו כשיגיע ה' שנים עם שנת היובל יהיה שמיטה ויובל אסור בזריעה ומשמע להו דקרא מיירי בכל השמיטות אף בשמיטה הסמוכה ליובל:"],[5,"לדבריכם","שאתם סבורים להעמיד המקרא אף בשמיטה הסמוכה ליובל הרי אמר ועשת את התבואה לשלש השנים ומיירי בכל שמיטה ושמיטה ששנה ששית מספקת לעצמה לשביעית ולשמינית עד אחר קציר והרי כאן ארבעה בשמיטה הסמוכה ליובל לפניה בשביעית ויובל אסורין בזריעה ועוד שנה שאחר היובל ושנה ששית הרי כאן ארבע:"],[6,"אלא כו'","ולא בכל שמיטות איירי כלומר מה שמקשין לי מקרא דשש שנים איכא לאוקומי בשאר שני שבוע שבאמצע היובל:"],[7,"","למימרא [דרבי מאיר כו'] כדפרישית במתניתין:"]]],[["לספיקא ורבי יוסי סבר מעייל איניש נפשיה לספיקא","ורמינהי מי שיש לו שתי כיתי בנות משתי נשים ואמר קדשתי את בתי הגדולה ואיני יודע אם גדולה שבגדולות אם גדולה שבקטנות ואם קטנה שבגדולות שהיא גדולה מן הגדולה שבקטנות כולן אסורות דברי ר\"מ חוץ מן הקטנה שבקטנות","רבי יוסי אומר כולן מותרות חוץ מן הגדולה שבגדולות","אמר רבי חנינא בר אבדימי אמר רב מוחלפת השיטה והתניא זה הכלל כל שזמנו קבוע ואמר עד לפני ר\"מ אומר עד שיצא ורבי יוסי אומר עד שיגיע:","\u0001מתני׳\u0002 עד הקציר עד הבציר עד המסיק אינו אסור אלא עד שיגיע זה הכלל כל שזמנו קבוע ואמר עד שיגיע אסור עד שיגיע אמר עד שיהא אסור עד שיצא וכל שאין זמנו קבוע בין אמר עד שיהא בין אמר עד שיגיע אינו אסור אלא עד שיגיע","עד הקיץ עד שיהא הקיץ עד שיתחילו העם להכניס בכלכלות עד שיעבור הקיץ עד שיקפילו המקצועות:","\u0001גמ׳\u0002 תנא כלכלה שאמרו כלכלה של תאנים ולא כלכלה של ענבים תניא הנודר מפירות הקיץ אין אסור אלא בתאנים רשב\"ג אומר ענבים בכלל תאנים","מאי טעמא דתנא קמא קסבר תאנים מיקצצן בידא ענבים לא מיקצצן בידא רשב\"ג סבר ענבים נמי כי מירדדן מיקצצן בידא:","עד שיעבור הקיץ עד שיכפלו המקצועות: תנא עד שיכפילו רוב המקצועות"],[[0,"גמ' למימרא דרבי מאיר וכו'","כדפרישית:"],[1,"שתי כיתי בנות","משתי נשים שנשא זו אחר זו וכל אחת ילדה שתי בנות:"],[1,"כולן אסורות חוץ וכו' דברי רבי מאיר","דקסבר רבי מאיר מעייל איניש לספיקא דלא איזדהר הארוס בשעת קידושין דלא ליתי לידי קלקול והואיל דלא ידעינן הי מינייהו קידש כולן אסורות:"],[1,"חוץ מן הקטנה שבקטנות","דלדברי הכל לית לה שם גדולה:"],[2,"רבי יוסי אומר כולן מותרות וכו'","דקסבר לא מעייל איניש נפשיה לספיקא:"],[3,"מוחלפת השיטה","כלומר אפיך מתניתין דנדרים ואימא לרבי מאיר מעייל איניש כו':"],[3,"והתניא","בניחותא דמוחלפת:"],[3,"זה הכלל כל שזמנו קבוע","כגון רגלים:"],[3,"עדי שיצא","דקסבר מעייל איניש נפשיה לספיקא:"],[4,"מתני' אמר קונם שאיני טועם יין עד הבציר","של ענבים:"],[4,"עד המסיק","לקיטה של זיתים:"],[4,"וכל שאין זמנו קבוע","כגון קציר ובציר דזמנין הוו בחריפי וזמנין הוו באפלי:"],[5,"עד הקיץ","עד שעת לקיטת תאנים או שאמר עד שיהא הקיץ שניהם משמע דאינו אסור אלא עד שיתחיל העם להכניס תאנים בכלכלות וזהו בתחילת הקיץ:"],[5,"אמר עד שיעבור הקיץ אסור עד שיוכפלו המקצועות","עד שמכפילין הסכינים שקצצו בהן התאנים ומצניעין אותן כמו מקפלין את הכלים (שבת דף קיג.) ענין אחר שיקפלו עד שחורץ אותן בקופיץ ועושין אותן שירטי\"ט כמו ליטרא קציעות ולשון יכפילו על שם שמניחין זו על זו ותרוייהו שיעבור ויקפילו משמע בסוף הקיץ:"],[6,"גמ' ולא כלכלה של ענבים","משמע אף על פי שהבציר הוי סמוך לאלתר לקיץ לא אמרינן שזה נתכוון לכלכלה של ענבים אלא ודאי אינו אסור אלא עד תאנים:"],[6,"עגבים בכלל תאנים","ואסור עד כלכלה של ענבים: ענבים לא מקצצו ביד אלא בסכין ולא דמו כלל לתאנים הלכך לא הוו בכלל תאנים:"],[7,"ענבים נמי כי מירדדן","כשמתבשלין יפה יפה שנושרין ענבים מן האשכול מקצצו נמי בידא כתאנים הלכך הוו בכלל תאנים:"],[8,"תנא הוקפלו רוב המקצועות","אותן תאנים שנשתיירו בשדות ובאילנות:"]],[[1,"ורמינהו מי שיש לו שתי כיתי בנות משתי נשים","מכל אשה שתי בנות קטנה וגדולה משנה היא בקידושין פרק האומר (דף סד:) דסבר רבי מאיר דמחית אינש נפשיה לספיקא ושמא קרי לה לגדולה קטנה שבגדולות ורבי יוסי אמר וכו' דלא מעייל אינש נפשיה לספיקא וגדולה דקאמר גדולה ממש:"],[3,"מוחלפת השיטה","ואיפוך מתני' דר\"מ לדרבי יוסי ודרבי יוסי לדר\"מ:"],[3,"והתניא","בניחותא ולמאי דמסיק התם אביי בלישנא פליגי ואין צריך לומר מוחלפת השיטה:"],[4,"עד הבציר אינו אסור אלא עד שיגיע","וה\"ה נמי אם אמר עד שיהא כיון דאין זמנו קבוע כדמפרש ואזיל:"],[4,"","זה הכלל כל שזמנו קבוע כו' כמו בציר אמר עד שיהא אינו אסור אלא עד שיגיע לבד בפ\"ג בקידושין (דף סד:) י\"מ דקציר ובציר הוי זמנו קבוע ואין זמנו [קבוע] כגון דאמר עד שילך פלוני למקום פלוני שאינו יודע כמה יאחר ול\"נ דהא אמר עד שיהא הקיץ עד שיתחילו לתת בכלכלות אלמא אינו אסור עד שיצא ואין זמנו קבוע תפסינן ליה:"],[5,"קיץ","על שם שקוצצים התאנים. של תאנים נקרא קיץ על שם שנקצצת ביד. וענבים שנקצצין בסכין נקרא בצירה:"],[7,"ענבים נמי כי מירדדן","פירוש כשנתייבשו נקצצות ביד [ל\"א] מיזרדן כמו חבילי זרדין:"],[8,"עד שיקפלו רוב המקצועות","סכינים שקוצצין בהם עיגולי תאנים והעיגולים עצמן נקראין קציעות:"]]],[["תנא הוקפלו רוב המקצועות מותרות משום גזל ופטורות מן המעשרות","רבי ורבי יוסי בר רבי יהודה איקלעו לההוא אתרא בזמן שהוקפלו רוב המקצועות רבי הוה קא אכיל רבי יוסי בר ר' יהודה לא אכיל אתא מרהון אמר להו אמאי לא אכלי רבנן הוקפלו רוב המקצועות הוא ואף על פי כן לא אכיל ר' יוסי בר ר' יהודה קסבר משום סניות מילתא הוא דקאמר הדין גברא","רבי חמא בר רבי חנינא איקלע לההוא אתרא בזמן שהוקפלו רוב המקצועות הוה קאכיל יהיב לשמעיה לא אכיל אמר ליה אכול כך אמר לי רבי ישמעאל בר רבי יוסי משום אביו הוקפלו רוב המקצועות מותרות משום גזל ופטורות מן המעשר","ר' טרפון אשכחיה ההוא גברא בזמן שהוקפלו המקצועות דקאכיל אחתיה בשקא ושקליה ואמטייה למשדיה בנהרא אמר לו אוי לו לטרפון שזה הורגו שמע ההוא גברא שבקיה וערק אמר רבי אבהו משום ר' חנניה בן גמליאל כל ימיו של אותו צדיק היה מצטער על דבר זה אמר אוי לי שנשתמשתי בכתרה של תורה","ואמר רבה בר בר חנה אמר ר' יוחנן כל המשתמש בכתרה של תורה נעקר מן העולם קל וחומר ומה בלשצר שנשתמש בכלי קודש שנעשו כלי חול שנאמר (יחזקאל ז, כב) ובאו בה פריצים וחיללוה כיון שפרצום נעשו חול נעקר מן העולם דכתיב (דניאל ה, ל) בה בליליא קטיל בלשצר המשתמש בכתרה של תורה שהוא חי וקיים לעולם על אחת כמה וכמה","ורבי טרפון כיון דכי אכיל דהוקפלו רוב המקצועות הוה אמאי צעריה ההוא גברא משום דההוא הוו גנבי ליה ענבי כולה שתא וכיון דאשכחיה לר' טרפון סבר היינו דגנבן אי הכי אמאי ציער נפשיה משום דרבי טרפון עשיר גדול הוה והוה ליה לפייסו בדמים","תניא (דברים ל, כ) לאהבה את ה' אלהיך לשמוע בקולו ולדבקה בו שלא יאמר אדם אקרא שיקראוני חכם אשנה שיקראוני רבי אשנן שאהיה זקן ואשב בישיבה","אלא למד מאהבה וסוף הכבוד לבא שנאמר (משלי ז, ג) קשרם על אצבעותיך כתבם על לוח לבך ואומר (משלי ג, יז) דרכיה דרכי נועם ואומר (משלי ג, יח) עץ חיים היא למחזיקים בה ותומכיה מאושר","רבי אליעזר בר ר' צדוק אומר עשה דברים לשם פעלם ודבר בהם לשמם אל תעשם עטרה להתגדל בהם ואל תעשם קורדום להיות עודר בו וקל וחומר ומה בלשצר שלא נשתמש אלא בכלי קדש שנעשו כלי חול נעקר מן העולם המשתמש בכתרה של תורה על אחת כמה וכמה","אמר רבא שרי ליה לאיניש לאודועי נפשיה באתרא דלא ידעי ליה דכתיב (מלכים א יח, יב) ועבדך ירא את ה' מנעוריו אלא קשיא דר' טרפון דעשיר גדול היה והוה ליה לפייסיה בדמים","רבא רמי כתיב ועבדך ירא את ה' מנעוריו וכתיב (משלי כז, ב) יהללך זר ולא פיך הא באתרא דידעי ליה הא באתרא דלא ידעי ליה","אמר רבא שרי ליה לצורבא מרבנן למימר צורבא מרבנן אנא שרו לי תיגראי ברישא דכתיב (שמואל ב ח, יח) ובני דוד כהנים היו מה כהן נוטל בראש אף תלמיד חכם נוטל בראש וכהן מנא לן דכתיב (ויקרא כא, ח) וקדשתו כי את לחם (ה') אלהיך הוא מקריב ותנא דבי רבי ישמעאל וקדשתו לכל דבר שבקדושה"],[[0,"מותרות משום גזל","שנתיאשו מהן הבעלים:"],[0,"ופטורות מן המעשר","משום דהפקירא נינהו:"],[1,"מרייהו","בעלים של תאנים:"],[1,"והוכפלו כו'","דשרו למיכל כל אדם:"],[1,"משום סניות מילתא","כלומר מרוע לב היה אומר כן ולא משום עין יפה דעדיין לא הפקירן:"],[3,"אשכחיה","לרבי טרפון גופיה דקאכיל מן התאנים דקסבר דהפקירא נינהו:"],[3,"אחתיה","לר' טרפון בשקא ההוא גברא שהיה משמרן:"],[3,"על דיבר זה","שהציל עצמו בכבוד תורתו דקאמר אוי לו לטרפון:"],[4,"פריצים","שהוציאו מבית המקדש:"],[4,"ונעשו חול","ואף על פי כן נהרג עליהם בלשצר:"],[5,"אמאי ציערו","ההוא גברא לר' טרפון הא מהפקירא קא אכיל:"],[5,"וקא סבר היינו דגנבן","להכי צעריה:"],[5,"אי הכי אמאי ציער ר' טרפון נפשיה","כיון שתפסו כגנב מאי הוה ליה למעבד:"],[5,"חיה לו לפייסו","בממון:"],[8,"לפעלם","לשם שמים:"],[8,"ודיבר בהן לשם שמים","שתהא כל כוונתך לשמים:"],[8,"להיות עודר כו","להשתכר ממנו כדי לאכול:"],[9,"אלא קשיא דיר' טרפון","אם שרי ליה לאיניש לאודועי נפשיה שהוא חכם במקום שאין מכירין אותו אמאי ציער נפשיה בשביל שהודיע לזה שהוא חכם:"],[11,"שרו לי תגראי","הקדימו דיני לשל אחרים בשביל כבוד תורתי:"],[11,"","ובני דוד כהנים היו אלא מה וכו':"]],[[0,"הוקפלו כו' מותרות משום גזל","שהבעלים מפקירין אותם:"],[0,"ופטורות מן המעשר","כהפקר:"],[3,"שנשתמשתי בכתרה של תורה","שהניחו אותו האיש בשביל כבוד תורתו:"],[5,"[א\"ה אמאי ציער]","מאי הוה ליה למיעבד כיון שלא היה רוצה להניחו בענין אחר בשלמא אי הוה שביק ליה כי אמר הוקפלו רוב המקצועות ניחא שהיה מצטער על מה שלא אמר לו:"],[6,"לאהבה את ה' אלהיך","משמע מאהבת הבורא ולא לכבוד עצמך:"],[11,"שרו לי תגראי","כלומר פסוק דין שלי תחילה:"]]],[["לפתוח ראשון ולברך ראשון וליטול מנה יפה ראשון","אמר רבא שרי ליה לצורבא מרבנן למימר לא יהיבנא אכרגא דכתיב (עזרא ז, כד) מנדה בלו והלך לא שליט למירמא עליהון וא\"ר יהודה מנדה זו מנת המלך בלו זו כסף גולגלתא והלך זו ארנונא","ואמר רבא שרי ליה לצורבא מרבנן למימר עבדא דנורא אנא לא יהיבנא אכרגא מ\"ט לאברוחי אריא מיניה קאמר","רב אשי הוה ליה ההוא אבא זבניה לבי נורא א\"ל רבינא לרב אשי האיכא (ויקרא יט, יד) לפני עור לא תתן מכשול א\"ל רוב עצים להסקה ניתנו:","\u0001מתני׳\u0002 עד הקציר עד שיתחיל העם לקצור קציר חטין אבל לא קציר שעורין הכל לפי מקום נדרו אם היה בהר בהר ואם היה בבקעה בבקעה","עד הגשמים עד שיהו הגשמים עד שתרד רביעה שניה רשב\"ג אומר עד שיגיע זמנה של רביעה עד שיפסקו גשמים עד שיצא ניסן כולו דברי ר' מאיר ר' יהודה אומר עד שיעבור הפסח:","\u0001גמ׳\u0002 תניא הנודר עד הקיץ בגליל וירד לעמקים אע\"פ שהגיע הקיץ בעמקים אסור עד שיגיע הקיץ בגליל:","עד הגשמים עד שיהו גשמים עד שתרד רביעה שניה רשב\"ג אומר וכו': אמר ר' זירא מחלוקת דאמר עד הגשמים אבל אמר עד הגשם עד זמן גשמים קאמר"],[[0,"לפתוח ראשון","לקרוא בספר תורה:"],[0,"ולברך ראשו","בברכת המוציא ובברכת המזון:"],[0,"וליטול מנה יפה ראשון","כשחולק עם אחיו הכהנים בלחם הפנים:"],[1,"מנדה בלו והלך וגו'","מקרא הוא בספר עזרא:"],[1,"לא יהיבנא אכרגא","איני רוצה ליתן מס בשביל שאני חכם:"],[2,"עבדא דנורא","עבד של עבודת כוכבים פלונית אני ואיני רוצה ליתן מס. נורא שם עבודת כוכבים:"],[3,"אבא","יער:"],[3,"לפני עור","דאינהו קא עבדי מינה צורך עבודת כוכבים:"],[3,"להסקה ניתנו","וכמוכר להסקה דמי ולא לעבודת כוכבים:"],[4,"מתני' אמר קונם שאיני טועם עדי הקציר","עד שיתחילו לקצור חטין קאמר ולא קציר שעורים וקציר שעורים הוי מוקדם:"],[4,"אם היה בהר","בשעת הנדר אע\"פ שירד בבקעה אסור עד שיתחילו לקצור בהר:"],[5,"אמר קונם שאיני טועם עד הגשמים","או שאמר שאיני טועם עד שיהו גשמים אסור עד שתרד רביעה שניה דגשמים משמע שנים:"],[5,"רביעה שניה","מפרש בגמרא:"],[5,"עד שיגיע זמנה של רביעה","אע\"פ שלא ירדה כיון שהגיע זמנה מותר:"],[5,"אמר קונם שאיני טועם עד שיפסקו גשמים אסור עדי שיצא ניסן כולו דבר ר' מאיר","רבי מאיר לטעמיה דאמר במסכת תענית בפ\"ק עד מתי שואלין את הגשמים ר\"מ אומר עד שיצא ניסן רבי יהודה אומר עד שיעבור הפסח ותו לא:"],[7,"גמ' מחלוקת דיאמר עד הגשמים","דמר סבר עד זמנה ומר סבר עד שתרד:"],[7,"אבל אם אמר עד הגשם","דברי הכל עד זמן גשמים של רביעה ראשונה קאמר למר כדאית ליה ולמר כדאית ליה עד שיגיע זמנה כו' דגשם חדא רביעה משמע:"]],[[2,"עבדא דנורא אנא","כלומר שהוא משועבד לכהנים של אותה עבודת כוכבים שעבדיהם פטורין מן המכס ואינו נראה כמודה להם שהדבר ידוע [דליפטור] ממס [אמר הכי]:"],[3,"האיכא לפני עור","שיעשו צלמים או בנין לפני עבודת כוכבים:"],[3,"רוב עצים להסקה","וכל היכא דאיכא למיתלי בהיתירא תלינן מכאן יש ללמוד שאסור להלות מעות לצורך בנין עבודת כוכבים או לצורך תכשיטיה כ\"ש למכור להם משמשין ודברי תיפלות כגון גביעים מחתות וספרים והמונע יצליח:"],[4,"הנודר עד הקציר","ובמקומו יש קציר חטים וקציר שעורים עד שיתחיל קציר חטין דקציר המיוחד קאמר:"],[4,"הכל לפי מקום נדרו","כלומר מה שאמרנו קציר חטין היינו במקום שיש קציר חטין אבל אם אין במקומו אלא קציר שעורין [שעורין] קאמר ולא תלינן בקציר חטין דעלמא וגם לענין זה אזלינן אחר מקום נדרו שאם היה בהר קציר הר קאמר וכי נמי מטא קציר דבקעה אינו אסור עד קציר דהר:"],[5,"עד הגשמים שיהיו גשמים כיצד עד שירד רביעה שניה","דבא\"י לא היו יורדין גשמים כ\"א ג' פעמים וקורין להם רביעות:"],[5,"רשב\"ג אומר עד שיגיע זמנה של רביעה שנייה","כי נמי לא ירדה ובגמ' מפרש אימתי זמנה:"],[5,"עד שיצא ניסן כו'","דעד - ניסן זמן ירידת גשמים:"],[6,"אינו אסור עד שיגיע בגליל","במקום שנדר:"],[7,"מחלוקת דאמר עד הגשמים","[בהא אמרינן עד] רביעה שנייה נדר למר כדאית ליה ולמר כדאית ליה או עד שתרד או עד הזמן אבל אמר עד הגשם עד זמן קאמר פירוש רביעה ראשונה:"]]],[["מיתיבי איזוהי זמנה של רביעה הבכירה בג' בינונית בשבעה אפילה בעשרים ושלשה דברי רבי מאיר רבי יהודה אומר בשבעה ובשבעה עשר ובעשרים ושלשה","רבי יוסי אומר בשבעה עשר ובעשרים ושלשה ובחודש כסליו וכן היה ר' יוסי אומר אין היחידים מתענין עד שיגיע ר\"ח כסליו","ואמרינן עלה בשלמא רביעה ראשונה לישאל שלישית להתענות אלא שניה למאי ואמר רבי זירא לנודר","ואמרינן עלה כמאן אזלא הא דתניא רשב\"ג אומר גשמים שירדו שבעה ימים זה אחר זה אתה מונה בהן רביעה ראשונה ושניה כמאן כרבי יוסי","ההוא דאמר עד הגשמים:","\u0001מתני׳\u0002 קונם יין שאיני טועם לשנה נתעברה השנה אסור בה ובעיבורה עד ראש אדר עד ראש אדר הראשון עד סוף אדר עד סוף אדר הראשון:","\u0001גמ׳\u0002 אלמא סתמא דאדר דקאמר ראשון הוא","לימא מתני' רבי יהודה היא דתניא אדר הראשון כותב אדר הראשון אדר שני כותב אדר סתם דברי ר\"מ ר' יהודה אומר אדר הראשון כותב סתם אדר שני כותב תיניין","אמר אביי אפילו תימא ר\"מ הא דידע דמעברא שתא הא דלא ידע"],[[0,"הבכירה בג'","במרחשון:"],[1,"בראש חדש כסליו","הוי רביעה אחרונה:"],[2,"לשאול","להתפלל על הגשמים:"],[2,"להתענות","לגזור תענית אם לא ירדו:"],[2,"ואמר ר' זירא לנודר","דהנודר בין עד הגשם בין עד הגשמים אסור עד זמן רביעה שניה ומשמע בין שאמר עד הגשם בין דאמר עד הגשמים:"],[2,"אמר לך ר' זירא האי דיאמר שניה לנודר היינו דאמר עדי הגשמים","וגשמים תרתי משמע אבל אמר עד הגשם לעולם אימא לך עד זמן גשמים שהיא רביעה ראשונה קאמר ולא שניה:"],[3,"ואמרינן עלה כמאן אזלא וכו' במאן כרבי יוסי","דמיום י\"ז עד יום כ\"ג הוו שבעה ימים דאי ר' מאיר לא הוו אלא ה' ימים אלמא דאפי' רבן גמליאל דמקיל הכא גבי נדרים דאמר עד שיגיע זמנה של רביעה אע\"פ שעדיין לא ירדה סבירא ליה אתה מונה ראשונה ושניה ולא ראשונה בלבד לא שנא דאמר עד הגשם לא שנא דאמר עד הגשמים וקשיא לר' זירא:"],[5,"מתני' אמר שאיני טועם עדי ראש חדיש אדר","סתם אין אסור אלא עד ראש חדש אדר הראשון: גמ' מדקתני מתני' אינו אסור אלא עד אדר הראשון אלמא דכל היכא דקאמר עד אדר סתמא אדר הראשון משמע ולא שני:"],[7,"דתניא","הרוצה לכתוב בשטר אדר הראשון כותב בהדיא אדר הראשון אבל אם רוצה לכתוב אדר השני כותב סתם דברי ר\"מ דסתם אדר השני משמע ולא הראשון:"],[7,"אדר השני כותב","בהדיא אדר השני דבסתם אדר הראשון תוא:"],[8,"אפילו תימא","מתניתין ר\"מ ומתני' כגון דלא ידע דמיעברא שתא הילכך כי אמר סתם אדר הראשון משמע ולא השני שלא נתכוין אלא לאדר הסמוך לשבט וברייתא דקתני אדר השני כותב סתם כגון דידע דמיעברא שתא וכי אמר אדר סתם משמע אדר השני:"]],[[0,"מיתיבי איזהו זמנה של רביעה","כלומר ראשונה בשלשה במרחשון בינונית כו' אפילה פירוש אחרונה [בכ\"ג] רבי יהודה אומר כו':"],[1,"אין היחידים מתענין","בפ\"ק דתענית (דף י -) מפרש מאן יחידים רבנן מתענין ומתפללין שירדו גשמי':"],[2,"רביעה ראשונה לשאול","לומר ותן טל ומטר שלא בגולה ובגולה כמו אנן אין שואלין עד ששים בתקופה:"],[2,"להתענות","אם לא ירדו:"],[2,"אלא שנייה","למה הוזכרה ואמר רבי זירא לומר שאם נדר עד הגשמים שניה קאמר ואמרינן עלה כמאן אזלא הא דתניא כו' וקשה לרבי זירא דאמר דברי הכל בין ת\"ק בין רשב\"ג דעד הגשם רביעה ראשונה קאמר והכא אומר עלה אתה מונה בהם באותן שבעה ימים וכרבי יוסי דאמר לעיל בי\"ח בכ\"ג דליכא אלא שבעה ימים ביניהם [ורבי זירא] נמי אמר דשניה לנודר דמשמע השתא דהכל שנינו לנודר אף היכא דאמר עד הגשם - ומשני דאמר עד הגשמים וא\"ת ורשב\"ג אמאי נקט גשמים שירדו והא אף במתני' תנן עד שיגיע זמן של רביעה שניה וי\"ל דנקט ירדו בשביעי רביעה ראשונה כדמפרש בפ\"ק דתענית (דף ו:) לענין להלך בשבילי הרשות שהותרו כשירדו דוקא דבלא ירידה ודאי לא הותרו:"],[5,"אסור בה ובעיבורה","עד סופה דעיבורה הוי בכלל שנה ושנה:"],[7,"ר' יהודה אומר אדר ראשון כותב סתם אדר שני כותב תניין","וכר' יהודה:"],[8,"הא דידע דמיעברא שתא","דאז קרי לאדר שני סתם ומתני' בשאינו יודע בעיבורה עד אדר ואדר ראשון מיקרי אדר:"]]],[["והתניא עד ר\"ח אדר עד ר\"ח אדר הראשון אם היתה שנה מעוברת עד ר\"ח אדר השני","מכלל דרישא לאו במעוברת עסקינן שמע מינה הא דפשיטא ליה דמעברא שתא הא דלא ידע:","\u0001מתני׳\u0002 ר' יהודה אומר קונם יין שאיני טועם עד שיהא הפסח לא נתכוון זה אלא עד ליל פסח עד שעה שדרך בני אדם לשתות יין","אמר קונם בשר שאיני טועם עד שיהא הצום אינו אסור אלא עד לילי צום שלא נתכוון זה אלא עד שעה שדרך בני אדם לאכול בשר ר' יוסי בנו אומר קונם שום שאני טועם עד שתהא שבת אינו אסור אלא עד לילי שבת שלא נתכוון זה אלא עד שעה שדרך בני אדם לאכול בשום","האומר לחבירו קונם שאני נהנה לך אם אין את בא ונוטל לבניך כור אחד של חטין ושתי חביות של יין הרי זה יכול להפר את נדרו שלא ע\"פ חכם ויאמר לו כלום אמרת אלא מפני כבודי זהו כבודי","וכן האומר לחבירו קונם שאת נהנית לי אם אין את בא ונותן לבני כור של חטין ושתי חביות של יין ר\"מ אומר אסור עד שיתן וחכ\"א אף זה יכול להפר את נדרו שלא ע\"פ חכם ויאמר לו הרי אני כאילו נתקבלתי","היה מסרב בו לשאת בת אחותו ואמר קונם שהיא נהנית לי לעולם וכן המגרש את אשתו אומר קונם אשתי נהנית לי לעולם הרי אלו מותרות להנות לו שלא נתכוון זה אלא לשום אישות","היה מסרב בחבירו שיאכל אצלו אמר קונם לביתך שאני נכנס טיפת צונן שאני טועם לך מותר ליכנס לביתו ולשתות ממנו צונן שלא נתכוון זה אלא לשום אכילה ושתיה:","\u0001הדרן עלך קונם יין\u0002"],[[0,"והתניא","סיוע:"],[0,"הכותב עד ר\"ח אדר","סתם עד ר\"ח אכר הראשון קאמר מדקתני אם היתה שנה מעוברת וכו' מכלל דרישא דקתני עד ר\"ח כו' לאו במעוברת עסקינן בתמיה הא מדקתני עד אדר הראשון מכלל דבמעוברת עסקינן ומאי שנא רישא ומאי שנא סיפא:"],[1,"אלא שמע מינה רישא דלא ידיע דמיעברא שתא","וכי נדר לשם אדר הסמוך לשבט קאמר הילכך עד אדר הראשון וסיפא מיירי בדידע דשתא מעוברת היא דהכי משמע אם היה יודע שהשנה מעוברת אסור עד ר\"ח אדר השני:"],[2,"מתני' שלא נתכוון זה שלא לשתות אלא עד שעה שדרך בני אדם לשתות יין","דודאי רוצה הוא לשתות ד' כוסות של יין בלילי פסח שכל אדם שותין:"],[3,"אלא עד לילי צום","עד אותה לילה שיצום למחר ואותה הלילה מותר לאכול בשר:"],[3,"עדי שעה שדרך בני אדם לאכול בשר","ורוצה לאכול עמהן:"],[3,"עד לילי שבת","ובלילי שבת מותר:"],[3,"שדרך בני אדם לאכול שום","והיינו לילי שבת:"],[4,"זהו כבודי","שלא אטול ממך:"],[5,"ויאמר לו","המדיר הריני כאילו נתקבלתי מה שבקשתי ממך:"],[6,"הרי אלו מותרות ליהנות ממנו","שאר הנאה:"],[6,"אלא לשם אישות","שנדר שלא תהנה ממנו דרך אישות:"],[7,"שלא נתכוון זה","המסרב בו אלא לאכילה ושתיה המרובה וכי אמר זה קונם לביתך כו' לא נתכוון לידור הנאה ממנו אלא לאכילה ושתיה מרובה נתכוון:"]],[[0,"והתניא","בניחותא. מכלל דרישא לא במעוברת בתמיה הא ודאי במעוברת איירי דהא קתני עד אדר ראשון אלא ודאי במעוברת וקשיא רישא אסיפא אלא רישא דלא ידע דמעוברת סיפא דידע דמעוברת ונדר עד אדר שני וקאמר דאדר סתם של מעוברת היינו אדר שני דחדש העיבור אדר ראשון הוא ולא אדר שני תדע שהרי אדר הראשון משלשים יום שני מכ\"ט ועוד דמגילה ופורים בשני אלמא ראשון חודש העיבור:"],[0,"עד ר\"ח אדר הראשון","דסתם אדר הוא אדר הראשון:"],[2,"שלא נתכוון זה אלא עד שדרך בני אדם לשתות יין","דהיינו עד לילי הפסח דבליל פסח יש לנו לומר שלא אסר עצמו:"],[3,"עד שיהא הצום","צום העשור:"],[3,"עד לילי הצום","דהיינו סעודה של יום הכפורים דרגילין לאכול בשר כדאיתא בחולין (דף פג.) רבי יוסי הגלילי אומר אף ערב יום הכפורים בגליל:"],[3,"שדרך בני אדם לאכול שום","דהיינו ליל שבת שהוא מתקנת עזרא שיאכלו שום בע\"ש:"],[4,"האומר לחבירו כו'","דברים שבלב כי הני דמוכחי הויין דברים ואע\"פ שלא פירש כמו שפירש חשבינן ליה:"],[4,"כור אחד של חטין וכו'","הני תרי בבי נתפרשו למעלה בפרק ארבעה נדרים (נדרים דף כד.):"],[5,"ר\"מ אמר עד שיתן","אבל ברישא מודה דקאמר [אם] אין אתה בא ונוטל וזה רגילות שיאמר זה הוא כבודי והיתירא מעליא הוא אבל הכא אין רגילות לומר התקבלתי מאחר שמפצירו שיתן לבנו:"],[6,"לשאת בת אחותו","אורחא דמילתא נקט כדאמר (יבמות סב:) הנושא בת אחותו עליו הכתוב אומר אז תקרא וה' יענה:"],[6,"","שלא נתכוון זה להכנס לביתו אלא לאכילה ושתיה סעודה גדולה שמפצירו בדבר:"]]],[["מתני׳ \u0001רבי\u0002 אליעזר אומר פותחין לאדם בכבוד אביו ואמו וחכמים אוסרין","אמר רבי צדוק עד שפותחין לו בכבוד אביו ואמו יפתחו לו בכבוד המקום אם כן אין נדרים מודים חכמים לר' אליעזר בדבר שבינו לבין אביו ואמו שפותחין לו בכבוד אביו ואמו","ועוד אמר רבי אליעזר פותחין בנולד וחכמים אוסרין כיצד אמר קונם שאני נהנה לאיש פלוני ונעשה סופר או שהיה משיא את בנו ואמר אילו הייתי יודע שהוא נעשה סופר או שהיה משיא את בנו בקרוב לא הייתי נודר","קונם לבית זה שאני נכנס ונעשה בית הכנסת אמר אילו הייתי יודע שהוא נעשה בית הכנסת לא הייתי נודר רבי אליעזר מתיר וחכמים אוסרין:","\u0001גמ׳\u0002 מאי אין נדרים אמר אביי אם כן אין נדרים ניתרין יפה"],[[0,"מתני' רבי אליעזר אומר פותחין לאדם בכבוד אביו ואמו","שאומר לו אילו היית יודע שאומרים על אביך אוי לו לאב שגדל בן רשע כזה שהוא פרוץ בנדרים שכן רשעים דרכן לנדור כדאמרינן לעיל בפירקין קמא (נדרים דף ט.) ואם אמר לאו דאילו הייתי יודע לא הייתי נודר מתירין לו:"],[0,"וחכמים אוסרין","שאפילו אין דעתו להתחרט נותנים לו דעת להתחרט:"],[1,"רבי צדוק אומר ער שפותחין לו בכבוד אביו ואמו כו'","כלומר אם כן יכולים לפתוח לו בכבוד אביו ואמו פותחין לו נמי בכבוד המקום שיכולים לומר לו נמי שכנגד הקב\"ה עושה שנודר ורשע הוא לשמים:"],[1,"אלא אם אתה אומר כן","שפותחין לו בכך:"],[1,"אין נדרים","בגמרא מפרש לה:"],[1,"בדבר שבינו לבין אביו ואמו","במה שהדיר והם צר. כים לו להנאתו שפותחין לו בכבודם:"],[2,"פותחין בנולד","בדבר שלא היה בעולם בשעת נדרו ועדיין עתידין לבוא לעולם לאחר שנדר ומפרש כיצד:"],[2,"ונעשה סופר","אית דאמרי תלמיד שהוא צריך לו ואית דאמרי לבלר שצריך לו נמי:"],[2,"או שהיה משיא","המודר את בנו ואמר אילו הייתי יודע כו' בקרוב זמן לא הייתי נודר:"],[3,"ונעשה","אותו בית:"],[3,"בית הכנסת","האי נולד ממש הוא:"],[3,"ר\"א מתיר וחכמים אוסרין","דקסברי אין פותחין בנולד ובמס' נזיר בפ' ב\"ש (נזיר דף לב:) מפרש דזכינהו חכמים לר' אליעזר והודה להם:"],[4,"גמ' מאי אין נדרים","דקאמר לן רבי צדוק לר' אליעזר אין נדרים:"],[4,"ניתרין יפה","כדפרשינן לעיל אפילו שאין דעתו להתחרט מתוך שמאיימין עליו כל כך משום כבוד אביו ואמו אומר שמתחרט אבל אין מתחרט לגמרי:"]],[[0,"מתני' רבי אליעזר אומר פותחין לאדם בכבוד אביו","כלומר אילו היית יודע שאומרים עליך לאביך ולאמך ראיתם בנכם קל בנדרים ויתביישו וי\"מ שיאמרו העולם אוי לאב ולאם שהגדילו בן שקל בנדרים כזה:"],[0,"וחכמים אוסרין","דחיישינן שמא יתבייש ויאמר מדעת כן לא נדרתי וישקר:"],[1,"אמר ר\"א בר צדוק","ראייה לדברי חכמים:"],[1,"עד שפותחין בכבוד אביו יפתחו בכבוד המקום","פירוש אילו היית יודע שקוראין אותך רע לפני המקום כלום היית נודר:"],[1,"אמרו לו אין נדרים","ובגמרא מפרש ליה:"],[2,"קונם שאיני נהנה לפלוני ונעשה סופר","וצריך לו לפי שהוא כותב שטרות העיר או שמשיא בנו וצריך ליכנס לביתו לחופת בנו:"],[3,"ואין חכמים מודים","בגמרא מפרש במאי פליגי:"],[3,"ועוד אמר ר' [אליעזר]","קולא אחרת:"],[4,"מאי אין נדרים","אמר אביי אין נדרים נתרים יפה - כלומר שבלב מקיים הנדר ומחמת בושת אומר שלדעת כן לא נדר:"],[4,"אמרו לו מת","ובגמרא פריך מת נולד הוא:"]]],[["ורבא אמר א\"כ אין נדרים נשאלין לחכם","תנן ומודין חכמים לרבי אליעזר בדבר שבינו לבין אביו ואמו שפותחים לו בכבוד אביו ואמו בשלמא לאביי דאמר אם כן אין נדרים ניתרין הכא כיון דאיחצף ליה הא איחצף ליה","אלא לרבא דאמר אם כן אין נדרים נשאלין לחכם הכא אמאי פותחין אמרי כיון דכל נדרי לא סגיא להון דלאו חכם הכא נמי פותחין:","ועוד אמר רבי אליעזר פותחין בנולד כו': מ\"ט דרבי אליעזר אמר רב חסדא דאמר קרא (שמות ד, יט) כי מתו כל האנשים והא מיתה דנולד הוא מכאן שפותחין בנולד","ורבנן מאי טעמייהו קסברי הנהו מי מייתי והא אמר ר' יוחנן משום ר' שמעון בן יוחי כל מקום שנאמר נצים ונצבים אינן אלא דתן ואבירם אלא אמר ר\"ל שירדו מנכסיהן","אריב\"ל כל אדם שאין לו בנים חשוב כמת שנאמר (בראשית ל, א) הבה לי בנים ואם אין מתה אנכי ותניא ארבעה חשובין כמת עני ומצורע וסומא ומי שאין לו בנים עני דכתיב כי מתו כל האנשים מצורע דכתיב (במדבר יב, יב) אל נא תהי כמת וסומא דכתיב (איכה ג, ו) במחשכים הושיבני כמתי עולם ומי שאין לו בנים דכתיב הבה לי בנים ואם אין מתה אנכי"],[[0,"אין נדרים נשאלין לחכם","שאומר בלבו מה לי לילך אצל חכם לא צריכנא דודאי מותר הוא דכל כך הנאהו ומתירו הוא בעצמו והתורה אמרה לא יחל דברו הוא אינו מוחל אבל אחרים מוחלים לו:"],[1,"בשלמא לאביי דאמר","היינו טעמא דרבנן משום דאין ניתרים יפה הכא מודו ליה לרבי אליעזר:"],[1,"דכיון דאיחצף","כולי האי מעיקרא דאדריה לאביו ולאמו מנכסיו הא איחצף ליה ועומד בחוצפו כדמעיקרא ואי מתחרט ודאי חרטה ופיו ולבו שוין ואהכי מתירין לו בכך:"],[2,"אלא לרבא דיאמר היינו טעמא משום דאין נדרים נשאלין לחכם","הכא נמי בנדרים שבינו לבין אביו ואמו אמאי מודו רבנן הא נמי לא אתו לשיולי לחכם ומתיר הוא בעצמו בכבוד אביו ואמו:"],[2,"אמרי כיון דשאר נדרים לא סגי","בלא שאלה לחכם משוש דאין פותחין בכבוד אביו ואמו שלא יתיר עצמו הכא בנדר שבינו לבין . אביו ואמו מודו רבנן דפותחין . דבשביל האי נדר גרידא דפתחו בכבוד אביו ואמו לא אתי למימר אין נדרים נשאלין לחכם כיון דכולהו נדרים בעלמא נשאלין לחכם:"],[3,"כי מתו כל האנשים","לפי שנדר משה ליתרו שלא לשוב מצרימה בשביל אותן האנשים המבקשים את נפשו כדמפרש לקמן ויואל משה ופתח לו המקום בכך לך שוב מצרים ומותר לך כדין שבשביל אותן שנדרת כבר מתים הן:"],[4,"ורבנן","דלא סברי ליה דפותחין בנולד אמרי לך ההוא לאו נולד הוא דהאי קמ\"ל רחמנא כי מתו מי מתו אלא ירדו מנכסיהם והיינו כי מתו דהכי קאמר רחמנא הנהו כבר מתו באותה שעה קודם שנדרת ולא הוי נולד אהכי אשתרי בההיא חרטה אבל בנולד לאו היינו חרטה להתיר בה את הנדר:"],[4,"והאמר ר' יוחנן משום ר' שמעון בן יוחי כל מקום כו'","כולא תירוצא דרבנן היא:"],[4,"ואינו אלא דתן ואבירם","ולא מתו עד מעשה קרח אלא האי כי מתו שירדו מנכסיהן כבר בשעת הנדר דלאו נולד הוא והיו כמתים:"],[5,"במחשכים הושיבני כמתי עולם","כשאדם נתון במחשך ואינו רואה חשוב כמת:"]],[[0,"אין נדרים נשאלין לחכם","אם פותחין בכבוד המקום בלא חרטה אחרת כל אחד ואחד יתיר נדרו בפ\"ע ואתי לזלזולי:"],[1,"כיון דאיחציף חציף","וליכא למיחש פן יהיה בלבו לקיים הנדר בכל ענין דכיון דחציף כולי האי לא יתבייש לומר שנדר בכל ענין כו':"],[2,"אלא לרבא דאמר אין נדרים נשאלין לחכם","לפי שאין החכם מוצא חרטה אלא מגוף הנדר הכא אמאי פותחין שהרי חרטה זאת אינה מגוף הנדר ויש לחוש דבכל נדרים לא ישאל לחכם:"],[2,"כיון דבכל נדרים לא סגי בלא חכם","דלא אסרו רבנן לפתוח בכבוד אביו ואמו כ\"א בזה לא יטעה וילך אצל חכם:"],[3,"ועוד אמר רבי אליעזר","קולא אחרת בנדרים והכא לא פרכינן כיון דאפסקו רבנן אמאי תנא ועוד כדפריך פרק שני דעירובין (דף כג -) דכיון דקולא היא אית ליה שפיר למתני' ועוד דלא פריך הכי אלא גבי חומרא (אלא) לפי שאין חידוש להחמיר:"],[3,"פותחין בנולד וחכמים אוסרין","פי' דבשביל הנולד אין נעשה הנדר נדר טעות וטעמא דכל חרטה דע\"י חרטה נעשה הנדר טעות ובטל מעיקרו:"],[3,"מאי טעם דרבי אליעזר","דמסברא יש לנו לומר דאין פותחין בנולד:"],[3,"כי מתו כל האנשים","משה נדר שישב אצל חמיו במדין לפי שהיה ירא לשוב למצרים מפני דתן ואבירם ופתח לו הקב\"ה פתח ממה שמתו ומיתה הוי נולד:"],[4,"ורבנן","פי' היכי סברי מתו בתמיה כל מקום שנאמר נצים כדכתיב שני אנשים נצים נצבים דכתיב ויפגעו את משה ואת אהרן נצבים וה\"פ אותם שהיו נצבים פגעו במשה ואהרן וכל מקום לאו דוקא דאינו כתוב במקום אחר דאי משום דכתיב ודתן ואבירם יצאו נצבים הרי הוא מפרש בהדיא ולא איצטריך ליה:"],[4,"אלא שירדו מנכסיהם","ובנולד כי האי דעוני מודו רבנן:"],[5,"ארבעה חשובים כמתים","ונפקא מיניה למבעי עלייהו רחמי:"]]],[["תניא המודר הנאה מחבירו אין מתירין לו אלא בפניו מנה\"מ אמר רב נחמן דכתיב (שמות ד, יט) ויאמר ה' אל משה במדין לך שוב מצרים כי מתו כל האנשים אמר לו במדין נדרת לך והתר נדרך במדין דכתיב (שמות ב, כא) ויואל משה אין אלה אלא שבועה דכתיב (יחזקאל יז, יג) ויבא אתו באלה","(דברי הימים ב לו, יג) וגם במלך נבוכד נצר מרד אשר השביעו באלהים (חיים) מאי מרדותיה אשכחיה צדקיה לנבוכד נצר דהוה קאכיל ארנבא חיה א\"ל אישתבע לי דלא מגלית עילוי ולא תיפוק מילתא אישתבע","לסוף הוה קא מצטער צדקיהו בגופיה איתשיל אשבועתיה ואמר שמע נבוכד נצר דקא מבזין ליה שלח ואייתי סנהדרין וצדקיהו אמר להון חזיתון מאי קא עביד צדקיהו לאו הכי אישתבע בשמא דשמיא דלא מגלינא א\"ל איתשלי אשבועתא","[א\"ל מתשלין אשבועתא] אמרי ליה אין אמר להו בפניו או אפילו שלא בפניו אמרי ליה בפניו אמר להון ואתון מאי עבדיתון מאי טעמא לא אמריתון לצדקיהו מיד (איכה ב, י) ישבו לארץ ידמו זקני בת ציון אמר רבי יצחק ששמטו כרים מתחתיהם:","\u0001מתני׳\u0002 רבי מאיר אומר יש דברים שהן כנולד ואינן כנולד ואין חכמים מודים לו כיצד אמר קונם שאני נושא את פלונית שאביה רע אמרו לו מת או שעשה תשובה קונם לבית זה שאני נכנס שהכלב רע בתוכו או שהנחש בתוכו אמרו לו מת הכלב או שנהרג הנחש הרי הן כנולד ואינו כנולד ואין חכמים מודים לו:","\u0001גמ׳\u0002 קונם שאני נכנס לבית זה שהכלב וכו' מת נולד הוא א\"ר הונא נעשה כתולה נדרו בדבר ור' יוחנן אמר כבר מת וכבר עשה תשובה קאמרי ליה"],[[0,"אין מתירין לו","לנודר אלא בפניו של מדיר:"],[0,"במדין לך","מהו במדין לך אלא הכי קא\"ל במדין נדרת לפני יתרו לך והתר בפני יתרו שאין מתירין לו לאדם אלא בפניו ויתרו הדירו למשה שלא לשוב מצרים מפני אותן אנשים המבקשים להורגו ואמר רבי תלמיד חכם מיפר לעצמו:"],[1,"ארנבא חיה","שאינה מבושלת ואית דאמרי חיה ממש שאכל אותה כשהיא חיה:"],[2,"הוה מצטער צדקיהו בגופיה","שהיה רוצה לגלות הדבר שיהו מבזין אותו בני העולם:"],[2,"איתשיל אשבועתיה","נשאל על שבועתו:"],[3,"מאי עבדיתו","דשריתון ליה מ\"ט לא אמריתון ליה לצדקיהו דלא מציתו למשריה אלא בפניו:"],[4,"מתני' שהן כנולד","דדמו לנולד אבל הן ממש אינן נולד ופותחין בהן:"],[4,"שאביה רע","תולה נדרו ברעות אביה מכלל דאי לא הוה רשע היה נושא אותה:"],[4,"או שעשה תשובה","דהיינו נולד פותחין בה ואומר לו בשעת חרטה אילו היית יודע שאביה עושה תשובה כלום היית נודר והוא אומר לאו וה\"נ מכלב ונחש:"],[5,"גמ' מת נולד הוא","דהוי נולד גמור ומאי קאמר אינו כנולד:"],[5,"אמר רב הונא נעשה כתולה נדרו בדבר","ברשעת אביה דמשמע כל זמן שאביה בחיים דודאי אם אמר שאיני נושא את פלונית סתם ודאי כדקאמרת השתא דאמר שאביה רע לפי שהוא רשע אינו נושא את בתו ואהכי פותחין לו לומר אילו היית יודע שמת:"],[5,"ורבי יוחנן אמר","לא הוי נולד כלל דבשעה שנדר כבר מת אהכי פותחין לו דכבר מת בשעה שנדר והוה ליה בטעות והא דאמר במתני' שהן כנולד דדמו לנולד פורתא:"]],[[0,"דתנן המודר הנאה מחבירו","שנדר בפניו שלא יהנה ממנו אין מתירין אלא בפניו לכאורה משמע דלפניו היינו דבעי מדעתו וקשה דהכא לא שייך שהרי נדר מעצמו שלא יהנה מחבירו ואין שום סברא שיצטרך דעתו להתיר נדרו לכ\"נ דבפניו אינו אלא מפני החשד ואפילו בע\"כ כיון שיהיה בפניו וכן משמע במדין לך והתיר נדרך אפילו בע\"כ דיתרו ואתי סוגיא דהכא כטעמא דמפני החשד ובירושל' מפרש שני טעמים אחד מפני החשד שלא יחשדנו שעובר על נדרו ולא נשאל לחכם ולאותו טעם א\"צ דעתו כדפרישית ועוד מפרש טעם אחר מפני בושה שאנו רוצים שיתבייש בפניו ושמעתי כטעמא דמפני החשד ודלא כפר\"ת דגטין שמפרש בדבר שעשה לו טובה על ידי הנדר - דהכא במודר הנאה איירי ולא קאמר המדיר חבירו:"],[3,"אמרו לו בפניו","וא\"ת מה בדעתו של צדקיהו מה היתה מועלת לו ההתרה שלא בפניו וסנהדרין למה התירו לו וי\"ל דצדקיהו היה מצטער ביותר על שלא היה מגלה השבועה והיה מתבטל ממלאכת שמים והוי כמו לדבר מצוה ועי\"ל דמצוה על החכמים לעשות רצון המלך ולדבר מצוה מתירין כדפרישית:"],[5,"כתולה נדרו בדבר","פירוש במה שהוא רע והוי כמפרש דלקמן שאביה קיים:"],[5,"רבי יוחנן אומר וכבר מת","והוי נדר בטעות ומותר בלא הפרה והכי קאמר ר\"מ יש דברים שדומה לנולד דדומה כאילו מת - אחר הנדר דאיכא למיטעי ואפ\"ה לא חיישינן וחכמים אוסרין דחיישינן דלמא מיחלף במת אחר הנדר וכן גזרינן כשעשה תשובה אטו היכא דלא עשה:"]]],[["מתיב רבי אבא קונם שאיני נושא לפלונית כעורה והרי היא נאה שחורה והרי היא לבנה קצרה והרי היא ארוכה מותר בה לא מפני שכעורה ונעשת נאה שחורה ונעשת לבנה קצרה ונעשת ארוכה אלא שהנדר טעות בשלמא לרב הונא דאמר נעשה כתולה נדרו בדבר תנא תולה נדרו בדבר ותנא נדר טעות אלא לר' יוחנן דאמר כבר מת וכבר עשה תשובה למה לי למתני תרי זימני נדר טעות קשיא:","\u0001מתני׳\u0002 ועוד אמר ר\"מ פותחין לו מן הכתוב שבתורה ואומרין לו אילו היית יודע שאתה עובר על (ויקרא יט, יח) לא תקום ועל לא תטור ועל (ויקרא יט, יז) לא תשנא את אחיך בלבבך (ויקרא יט, יח) ואהבת לרעך כמוך (ויקרא כה, לו) וחי אחיך עמך שהוא עני ואין אתה יכול לפרנסו אמר אילו הייתי יודע שהוא כן לא הייתי נודר הרי זה מותר:","\u0001גמ׳\u0002 א\"ל רב הונא בר רב קטינא לרבנן נימא כל דמעני לאו עלי נפיל מאי דמטי לי לפרנסו בהדי כ\"ע מפרנסנא ליה א\"ל אני אומר כל הנופל אינו נופל לידי גבאי תחלה:","\u0001מתני׳\u0002 פותחין לאדם בכתובת אשתו","ומעשה באחד שנדר מאשתו הנאה והיתה כתובתה ת' דינרים ובא לפני ר\"ע וחייבו ליתן לה כתובתה אמר לו רבי ח' מאות דינרין הניח אבא נטל אחי ד' מאות ואני ד' מאות לא דיה שתטול היא מאתים ואני מאתים א\"ל ר\"ע אפי' אתה מוכר שער ראשך אתה נותן לה כתובתה אמר לו אילו הייתי יודע שהוא כן לא הייתי נודר והתירה רבי עקיבא:","\u0001גמ׳\u0002 מטלטלי מי משתעבדי לכתובה אמר אביי קרקע שוה ח' מאות דינר והקתני שער ראשו ושער ראשו מטלטלי הוא ה\"ק אפי' אתה מוכר שער ראשך ואוכל","שמעת מינה אין מסדרין לבעל חוב אמר רב נחמן ברבי יצחק"],[[0,"","מתיב רבי אבא וכו' והרי היא נאה:"],[0,"אלא שהנדר בטעות","מעיקרא ולא הוי נדר:"],[0,"בשלמא לרב הונא","תנא רישא תולה נדר בדבר וסיפא תנא תולה נדר בטעות דאינו נדר:"],[0,"","אלא לרבי יוחנן כו':"],[1,"מתני' על לא תקום ולא תטור","שאם בקשת ממנו כלי ולא השאילך והדרתו הנאתך או שעשה לך דבר . שלא כהוגן ומתוך שנאה. הדרתו והתורה אמרה לא תשנא את אחיך בלבבך התורה הזקיקתו לפרנסו ולאוהבו ולהחיותו:"],[1,"שמא יעני ואי אתה יכול לפרנסו","מחמת נדרך:"],[1,"ואם אמר אילו הייתי יודע","בשעת הנדר בכל אזהרות הללו לא הייתי נודר:"],[2,"גמ' ונימא כל דמיעני","אמאי פותח לו שמא יעני לימא ליה מדיר לאו כל דמיעני נפול עלי לפרנסו ימנו לו גבאי לפרנסו ומאי דמטי לדידי למיהב לפרנסתו:"],[2,"בהדי כ\"ע מפרנסנא ליה","ואמאי מוזקק אני לפרנסו טפי משאר עלמא:"],[2,"הא לא מצי טעון דכל הנופל","בעניות אינו נופל לידי גבאי תחילה אלא קרובים מתגלגלין עמו:"],[4,"מתני' אתה מוכר שער ראשך","מפרש בגמרא:"],[4,"ואמר","הבעל אילו הייתי יודע כו':"],[5,"גמ' ש\"מ","מדקאמר ח' מאות זוז הניח לנו אבא רצונה ליטול מאתים ש\"מ דמטלטלי משתעבדי לכתובה והא קי\"ל (כתובות פא:) דלא משתעבדי:"],[5,"אמר אביי","ה\"ק קרקע שוה ח' מאות זוז כו':"],[5,"והא קתני אפי' אתה מוכר שער ראשך","ומשמע דקאמר אפי' אין לך להשלים כתובה אלא משער ראשך זקוק אתה למוכרו ולהשלים לה:"],[5,"ושער ראשו מטלטלי הוא","דכל העומד ליגזוז כגזוז דמי:"],[5,"ה\"ק","ר\"ע אפי' אין לך מה לאכול אא\"כ תמכור שער ראשך זקוק אתה ליתן לה כל הקרקע שיש לך:"],[6,"ש\"מ אין מסדרין לבעל חוב","כלומר דהכל גובין ממנו ונותנין לבעל חובו מדקאמר ליה ר\"ע אתה מוכר שער ראשך ותאכל והא קי\"ל במס' ערכין (דף כג:) ובב\"מ (דף קיד.) דמניחין לו כלי תשמישו ומטה ומפץ ושולחן ומזון ל' יום: הכי קאמר ליה אפי' אתה נותן לה כל אשר לך שאין לך לאכול אלא שער ראשך אין קורעין לה כתובתה עד שתפרע לה הכל משלם. ואית דאמרי אין מסדרין לבעל חוב אין עושין לו סדר של חיות שאין מניחין לו מה שסדרו חכמים כדאמרינן התם שמניחין לו כלי תשמישו ומטה וכו':"]],[[0,"בשלמא לרב הונא כו'","תרי מילי דלא דמו אהדדי לכך תנא לתרווייהו:"],[0,"אלא לר' יוחנן דאמר כבר מת והוי נדר טעות למה לי למתני","כלומר היינו הך דלקמן וטובא קשה דהא הכא פליגי רבנן ובהך דלקמן לא פליגי ואם כן צריכי טובא ואומר הר\"ם דה\"פ למה לי למתני תרתי ליתני הך בבא גבי הך דלקמן דמיירי בנדר טעות והכי נמי בפרק עשרה יוחסין (קדושין דף עד -) דקאמר אלא למ\"ד לדברי המכשיר בה מכשיר בבתה אבא שאול מאי אתא לאשמועינן ופירוש אמאי לא תנא האי מילתא דאבא שאול גבי ר\"ג ורבי יהושע וכן התם דקאמר מאי קמ\"ל יש ממזר מחייבי כריתות תנינא חדא זמנא כלומר וניתני התם מילתא דר\"ע וטעמא דלא פליגי רבנן בהך דכעורה ונמצאת שהיא נאה דלא שייך למיגזר אטו היכא שאינה נאה בשעת הנדר ושוב נעשית נאה אבל הכא איכא למיגזר אטו מת או עשה תשובה דהוי נולד:"],[2,"שמא יעני","ונימא כל מאן דמתעני עלי נפיל. בתמיה ומאי פתיחה היא בשביל כך לא יתחרט ואף כי יעני אין מוטל עליו לפרנסו לימנו ליה גבאי ויתפרנס עם שאר עניי העיר:"],[2,"אינו נופל ליד גבאי תחלה","כלומר מיד שהעני אין הגבאי מפרנסו מיד ומוטל על היחידים לפרנסו:"],[3,"בכתובת אשתו","ולא אמרי' [דאין פותחין] בפרעון הכתובה דהוי נולד:"],[4,"מוכר שער ראשך","מפרש בגמרא:"],[5,"ש\"מ מטלטלי משתעבדי לכתובה","ופליגי ביה ר\"מ ורבנן בפרק האשה שנפלו (כתובות דף פא:) דרבנן סברי דכתובה גריעה מבמ\"ח ולא משתעבדי לה מטלטלי דאפי' מיניה [אינה גובה] ':"],[5,"אפי' אתה מוכר שער ראשך ואוכל","כלומר צריך אתה ליתן לה כל אשר לך ואפי' תצטרך למכור שער ראשך למזונותיך אבל ודאי לפרוע הכתובה לא היה מוכר:"],[6,"ש\"מ אין מסדרין לב\"ח","ופלוגתא היא בפרק המקבל (ב\"מ דף קיד -) דאיכא מ\"ד מסדרין מניחין לו כלי תשמישו וכ\"ש שער ראשו:"],[6,"לומר שאין מקרעין כתובה","ומיפטר דלעולם יתחייב בה אף אם אין לו בלתי שער ראשו ונפקא מיניה דאם יעשיר יפרענה כולה דלעולם מסדרין דנהי דטעמא דמסדרין דגמר מיכה [מיכה] מערכין ובערכין תנן נתן סלע והעשיר אינו נותן לו כלום י\"ל דלענין השג יד לא גמרינן מערכין אלא לענין סידור דכתיב בקרא ואם מך הוא מערכך החייהו מערכך והלכך מדינא דב\"ח י\"ל דמסדרין אבל מדינא דהשג לא [נשוה] לערכין:"]]],[["לומר שאין מקרעין שטר כתובה","\u0001מתני׳\u0002 פותחין בימים טובים ובשבתות בראשונה היו אומרים אותן הימים מותרין ושאר כל הימים אסורין עד שבא ר\"ע ולימד שהנדר שהותר מכללו הותר כולו","כיצד אמר קונם שאיני נהנה לכולכם הותר אחד מהן הותרו כולן","שאיני נהנה לזה ולזה הותר הראשון הותרו כולן הותר האחרון האחרון מותר וכולן אסורין (הותר האמצעי הימנו ולמטה מותר הימנו ולמעלה אסור)","שאני נהנה לזה קרבן ולזה קרבן צריכין פתח לכל אחד ואחד","קונם יין שאני טועם שהיין רע למעיים אמרו לו והלא המיושן יפה למעיים הותר במיושן ולא במיושן בלבד הותר אלא בכל היין קונם בצל שאני טועם שהבצל רע ללב אמרו לו הלא הכופרי יפה ללב הותר בכופרי ולא בכופרי בלבד הותר אלא בכל הבצלים מעשה היה והתירו ר\"מ בכל הבצלים","\u0001גמ׳\u0002 הותר האחרון האחרון מותר וכולן אסורין מאן תנא","אמר רבא ר\"ש היא דאמר עד שיאמר שבועה לכל אחד ואחד","קונם יין שאני טועם וכו' ותיפוק ליה דאין רע אמר ר' אבא ועוד יפה קתני","קונם בצל שאני טועם שהבצל וכו' ותיפוק ליה דאין רע אמר ר' אבא ועוד יפה קתני","\u0001מתני׳\u0002 פותחין לאדם בכבוד עצמו ובכבוד בניו אומרים לו אילו היית יודע שלמחר אומרין עליך כך היא ווסתו של פלוני מגרש את נשיו ועל בנותיך יהו אומרין בנות גרושות הן מה ראתה אמן של אלו להתגרש ואמר אילו הייתי יודע שכן לא הייתי נודר ה\"ז מותר","קונם שאני נושא את פלונית כעורה והרי היא נאה שחורה והרי היא לבנה קצרה והרי היא ארוכה מותר בה לא מפני שהיא כעורה ונעשת נאה שחורה ונעשת לבנה קצרה ונעשת ארוכה אלא שהנדר טעות","ומעשה באחד שנדר מבת אחותו הנייה והכניסוה לבית ר' ישמעאל וייפוה אמר לו ר' ישמעאל בני מזו נדרת אמר לו לאו והתירה ר' ישמעאל","באותה שעה בכה ר' ישמעאל ואמר בנות ישראל נאות הן אלא שהעניות מנוולתן וכשמת ר' ישמעאל היו בנות ישראל נושאות קינה ואומרות בנות ישראל על ר' ישמעאל בכינה וכן הוא אומר בשאול (שמואל ב א, כד) בנות ישראל על שאול בכינה","\u0001גמ׳\u0002 מעשה לסתור חסורי מחסרא והכי קתני ר' ישמעאל אומר אפילו כעורה ונעשת נאה שחורה ונעשת לבנה קצרה ונעשת ארוכה מעשה באחד שנדר מבת אחותו והכניסוה לבית ר' ישמעאל וייפוה וכו'"],[[1,"מתני' אותן הימים","ימים טובים ושבתות שבהן מותר ושאר ימות השנה אסור:"],[3,"הותר הראשון הותר לכולן","כדאוקימנא בפ' ד' נדרים שתלאן כולן בראשון:"],[4,"אמר שאיני נהנה לזה קרבן ולזה קרבן צריכין פתח לכל אחד ואחד","אע\"פ שאמר כל טענותיו בתוך כדי דיבור:"],[7,"גמ' אמר רבא","מתני' דמשוי חילוק בין היכא דאמר כולכם להיכא דאמר לזה קרבן ולזה קרבן:"],[7,"ר\"ש היא דאמר עד שיאמר [שבועה] לכל אחר ואחד","דתנן במסכת שבועות היו חמשה תובעין אותו וכו' ר\"ש אומר לעולם אינו חייב עד שיאמר לכל אחד ואחד שבועה לא לך ונמצא בכולן לשקר אבל אמר שבועה לא לך ולא לך אינו חייב אלא אחת להכי נמי מתני' היכא דאמר קונם שאיני נהנה לכולכם והותר באחד הותר בכולן:"],[9,"ותיפוק לי דאין רע","אמאי קא מהדר תנא דהיכא דאמרו לו והלא המיושן יפה למעיים דלא הוי נדר דמשמע דוקא יפה דאי לא הוי לא רע ולא יפה לא הותר ותיפוק ליה דלא הוי נדר דאינו רע וה\"ל נדר בטעות:"],[9,"ועודי יפה קתני","והכי נמי גבי אשה זו לא מפני שהיא כעורה ונעשת יפה אח\"כ או שחורה ונעשת לבנה אלא נאה ולבנה מעיקרא:"],[12,"וייפוה","שקישטוה והלבישוה ונראית יפה:"],[14,"מעשה לסתור","דרישא קתני אם היא נאה מעיקרא הוי נדר בטעות אבל אם נעשת נאה ע\"י קישוט כגון הך דר' ישמעאל ה\"ל נולד ואין פותחין בנולד והדר קא מפיק מעשה (הוא) אפי' היכא דנעשת נאה ע\"י קישוט פותחין לו:"],[14,"חסורי מיחסרא והכי קתני","רבי ישמעאל אומר אפי' כעורה ונעשת נאה ע\"י קישוט אינו נדר ופותחין לו ומעשה נמי וכו':"]],[[1,"פותחין לאדם בימים טובים","במי שנדר שלא לשתות יין עד שלשים יום אומרים לו אילו היית יודע שיש ביניהם שבתות וימים טובים מי היית נודר:"],[1,"","נדר שהותר מקצתו הותר כולו:"],[3,"שאיני נהנה לזה ולזה","לעיל פרק ארבעה נדרים (נדרים דף כו:) אוקימנא דתלאן זה בזה דאמר קונם שאני נהנה לפלוני לכך הותר הראשון הותרו כולן דתלויין בו הותר האחרון שאין האחרים תלויין בו:"],[4,"שאני נהנה לזה קרבן ולזה קרבן","דכיון דאמר קרבן לכל אחד וא' כל אחד נדר בפני עצמו ולא נתבטל נדר של חבירו ובגמרא מוקי לה כר\"ש דאמר צריך שבועה לכל אחד ואחד דלרבנן דפליגי עליה כי נמי אמר קרבן שאני נהנה לזה ולזה הוי כל אחד קרבן:"],[7,"","ר\"ש הוא דאמר אינו חייב קרבן שבועה לכל חד וחד עד דאמר שבועה לכל אחד ואחד ורבנן פליגי דכי אמר שבועה לא לך ולא לך חייב על כל אחד ואחד והכי נמי בקרבן לקמן הוי כל חד נדר באפיה נפשיה:"],[8,"ותיפוק ליה דאין רע","איין ישן ואבצל פריך למה לי למימר שהוא טוב:"],[8,"ועוד יפה","כלומר חדא ועוד קאמר - דחקו בספקא צ\"ע ואית ספרים דלא גרסינן ליה:"],[10,"האי לזילותא מכוון","והרי אין [כאן] זילזול ומשני דשפיר הוי זילזול:"],[10,"בכבוד עצמו ובכבוד אשתו","ולא אמרי' שיתבייש ואמר לאו אדעתא דהכי נדרי:"],[11,"כעורה והיא נאה מותרין","בלא שאלה דהוי נדר טעות:"],[11,"לא מפני שנעשית לבנה","כלומר אז לא הייתי מתיר דהוי נולד:"],[12,"ומעשה","בגמרא פריך מעשה לסתור:"],[12,"וייפוה","מפרש בגמרא שעשה לה שן זהב והוי נולד:"],[13,"בכה ר' ישמעאל","מתוך רחמנות:"]]],[["תנא שן תותבת היתה לה ועשה לה רבי ישמעאל שן של זהב משלו כי שכיב רבי ישמעאל פתח עליה ההוא ספדנא הכי בנות ישראל על ר' ישמעאל בכינה המלבישכן וכו'","ההוא דאמר לה לדביתהו קונם שאי את נהנית לי עד שתטעימי תבשילך לרבי יהודה ולר\"ש ר' יהודה טעים אמר ק\"ו ומה לעשות שלום בין איש לאשתו אמרה תורה שמי שנכתב בקדושה ימחה על המים המאררים בספק ואני על אחת כמה וכמה","ר\"ש לא טעים אמר ימותו כל בני אלמנה ואל יזוז שמעון ממקומו ועוד כי היכי דלא לתרגלי למינדר","ההוא דאמר לדביתהו קונם שאי את נהנית לי עד שתרוקי בו ברשב\"ג אתת ורקק אלבושיה א\"ל רב אחא מדפתי לרבינא והא האי לזילותא קא מיכוין א\"ל מירק על מני דרשב\"ג זילותא רבתא היא","ההוא דאמר לה לדביתהו קונם שאי את נהנית לי עד שתראי מום יפה שביך לר' ישמעאל בר' יוסי","אמר להם שמא ראשה נאה אמרו לו סגלגל שמא שערה נאה דומה לאניצי פשתן שמא עיניה נאות טרוטות הן שמא אזניה נאות כפולות הן שמא חוטמה נאה בלום הוא שמא שפתותיה נאות עבות הן שמא צוארה נאה שקוט הוא שמא כריסה נאה צבה הוא שמא רגליה נאות רחבות כשל אווזא שמא שמה נאה לכלוכית שמה אמר להן יפה קורין אותה לכלוכית שהיא מלוכלכת במומין ושרייה","ההוא בר בבל דסליק לארעא דישראל נסיב איתתא אמר לה בשילי לי תרי טלפי בשילה ליה תרי טלפי רתח עלה למחר אמר לה בשילי לי גריוא בשילה ליה גריוא אמר לה זילי אייתי לי תרי בוציני אזלת ואייתי ליה תרי שרגי","אמר לה זילי תברי יתהון על רישא דבבא הוה יתיב בבא בן בוטא אבבא וקא דאין דינא אזלת ותברת יתהון על רישיה אמר לה מה הדין דעבדת אמרה ליה כך ציוני בעלי אמר את עשית רצון בעליך המקום יוציא ממך שני בנים כבבא בן בוטא","\u0001הדרן עלך רבי אליעזר\u0002","מתני׳ \u0001נערה\u0002 המאורסה אביה ובעלה מפירין נדריה"],[[0,"שן תותבת","שנפלה שינה והושיבה שן אחר באותו מקום ועומד בכיעור:"],[0,"ועשה לה ר' ישמעאל שן","באותו מקום של זה משלו והיינו שייפוה:"],[0,"בכינה","עליו:"],[2,"ימותו כל בני אלמנה","כלומר ימות הבעל ותהא היא אלמנה ואח\"כ ימותו בניה:"],[2,"לא יזוז שמעון ממקומו","שיטעום תבשילה ולהכי לא רצה לטעום כי היכי דלא לירגלי למידר שלא יהיו קלים בנדרים:"],[3,"האי לזילותא","דרשב\"ג קמיכוון וכל כמה דלא ירקא באנפיה ממש ליכא זילותא ואי לא לא הוה מותרת דאיהו על דעת כן אמרה כדי לזלזלו:"],[3,"א\"ל מידק לר\"ג זילותא רבה היא","דאדם חשוב הוא:"],[4,"מום יפה שביך","דמשום שהיה בה כ\"כ מומין קאמר לה אם יש בה שום דבר יפה:"],[5,"שמא ראשה נאה","ולכך הדירה שתראהו לו:"],[5,"סגלגל","דומה לאניצי פשתן שראשיהן סגלגלים עגולין:"],[5,"טרוטות","רכות:"],[5,"בלום","סתום:"],[5,"צוארה שקוט","שראשה מונח בין כתיפותיה:"],[5,"אמר להן יפה אתם קורים אותה לכלוכית שהיא מלוכלכת במומין","זה השם יפה לה והיינו ודאי מום יפה שבה ועל דעת כן הדירה שתודיעני אותו דבר יפה דשמה יפה לה ששמה לכלוכית ואיהי נמי מלוכלכת. ע\"א יפה אתם קורין אותה לכלוכית שהיא מלוכלכת במומין דכיון דאין בה דבר יפה להראות ודאי על דעת כן הדירה בעלה שהיה יודע שאין בה דבר יפה ואין יכולה להראות והואיל ואין בה שום דבר יפה נמצא שאין הנדר חל עליה:"],[6,"בשילי לי תרי טלפי","שני רגלי בהמה ובישלה ב' עדשים שלא היתה מכרת בלשונות שלהם בא\"י לא היו טוענין כך ואית דגרסי בשילי טלופחי כלומר מעט עדשים שכן אדם נוהג לומר ואיהי סברה דשתי עדשים קאמר לה ובשלה לו שתי עדשים בלבד ולא רצתה לשנות על דבריו:"],[6,"ורתח עלה","למחר אמר אי אמינא לה נמי תרי תעביד לי כאיתמל ואמר לה בשילי לי גריוא מידה גדולה דסבר כי היכי דתטרח עלה דמילתא ולא תבשיל אלא כדי סעודה:"],[6,"תרי בוציני","לשון שני שרגי שני מנורות דתרוייהו נקראו בוציני בלשון ארמי:"],[7,"תברינהו על רישא דבבא","על ראש הפתח ומחמת כעס אמר לה ואיהי סברה דקאמר לה למיתבר יתהון על רישא דבבא בן בוטא דהוה יתיב תמן:"],[9,"מתני' נערה המאורסה אביה ובעלה מפירין נדריה","ולהכי נקט נערה דדוקא נערה שהיא ברשות אביה כדאמרי' נמי במס' כתובות האב זכאי בקדושי בתו ובמעשה ידיה ובמציאתה ובהפרת נדריה בזמן שהיא נערה ומפיק לה מהאי קרא:"]],[[4,"עד שתראי מום יפה","כלומר יפה מאום שום דבר יפה כמו ובכפי דבק מאום (איוב ל״א:ז׳):"],[5,"סגלגל","עגול:"],[5,"טרוטות","פירושו עגולות:"],[5,"כפולות","פירושו גדולות:"],[5,"בלום","סתום:"],[5,"שקוט","קצר כדתנן בבכורות (דף מג:) צוארו שקוט:"],[5,"עבה","ונראה שהוא נפוח:"],[5,"ושרייה","שהיה בה דבר יפה ששמה הגון ויפה לה:"],[6,"בוציני","אבטיחים:"],[6,"שרגי","נרות דמתרגמינן בוציני:"],[7,"תברינהו אבבא","בכעס אמר לה לשבור אותם על הדלת והיא היתה סבורה שאמר לה לשבור אותם על ראש בבא בן בוטא:"],[7,"שני בנים","כנגד שני שרגי:"],[9,"נערה המאורסה אביה ובעלה מפירין נדריה","בשותפות ונערה הוי מבת י\"ב שנים וששה חדשים ומשם ואילך היא בוגרת ולכך נקט נערה למעוטי בוגרת דבוגרת אינה עוד ברשות האב:"],[9,"אביה ובעלה מפירין נדריה","ובגמרא מפרש טעמא:"]]],[["הפר האב ולא הפר הבעל הפר הבעל ולא הפר האב אינו מופר ואין צריך לומר שקיים אחד מהן:","\u0001גמ׳\u0002 היינו רישא אביה ובעלה מפירין נדריה מהו דתימא או אביה או בעלה קתני קמ\"ל","ואין צריך לומר שקיים אחד מהן למה לי למיתנא השתא יש לומר הפר זה בלא זה ולא כלום קיים אחד מהן למה לי צריכא למיתני","כי איצטריך ליה כגון דהפר אחד מהן וקיים אחד וחזר המקיים ונשאל על הקמתו מהו דתימא מאי דאוקי הא עקריה קמ\"ל דמפירין שניהם בבת אחת","ונערה המאורסה אביה ובעלה מפירין נדריה מנלן אמר רבה אמר קרא (במדבר ל, ז) ואם היו תהיה לאיש ונדריה עליה מכאן לנערה המאורסה שאביה ובעלה מפירין נדריה אימא האי קרא בנשואה כתיב","אי משום נשואה קרא אחרינא כתיב (במדבר ל, יא) ואם בית אישה נדרה אימא תרוייהו בנשואה וכי תימא תרי קראי בנשואה למה לי למימר שאין הבעל מיפר בקודמין"],[[0,"הפר האב","ביום שמעו:"],[0,"ולא הפר הבעל","אלא שתק מעת לעת:"],[0,"או הפר הבעל ולא הפר האב","דשתיקתו של זה מבטלת הפרתו של זה ואין צריך לומר היכא דקיים אחד מהן הנדר דהפרתו של זה אינה מועלת כלום:"],[1,"גמ' היינו רישא","דכיון דקתני אביה ובעלה מפירין נדריה ל\"ל למיתנא תו הפר הבעל ולא הפר האב היינו רישא דזה מעכב על זה:"],[1,"מהו דתימא","דאי לאו דקתני הפר האב כו' הוה אמינא הא דקתני אביה ובעלה. מפירין נדריה משמע או אביה או בעלה זה בלא זה להכי קתני סיפא דתרוייהו מפירין ביחד:"],[2,"ואין צוריך לומר שקיים אחד מהם ל\"ל למיתני כלל","ממילא ידענא דלאו כלום הוא דהשתא הפר זה בלא זה כו':"],[3,"כי איצטריכא ליה","למיתנא ואין צריך לומר שקיים אחד מהן:"],[3,"כגון שהפר האחד מהן","הנדר ובא האחר וקיימו וחזר המקיים ונתחרט ממה שקיימו ונשאל לחכם על הקמתו בו ביום ששמע וקיים דאי הויא הקמה דלא מצי מתיר ליה חכם אינו יכול להפר תו ואי לא הויא הקמה דמתיר ליה חכם מצי להפר ולהכי איצטריך למיתני שקיים אחד מהן:"],[3,"דמהו דתימא מאי דאוקים לאו קיום הוא","דהא עקריה בחרטתו והואיל דלאו קיום הוא הא דאיתשיל עליה כי הפר לה דמי ואינו צריך להפר יותר קמ\"ל דלא הויא הפרה עד שיפרו שניהם בבת אחת שזה נמי יפר. ע\"א מאי דאוקי הא עקריה ולאו קיום הוא דהא עקריה בחרטתו ומצי מיפר קמ\"ל דלא הויא הפרה עד דמפירין שניהם בבת אחת ולא שיצטרכו להפר זה עם זה ממש בבת אחת אלא הכי בעי למימר כל שאילו רוצין יכולין להפר בבת אחת אף בזה אחר זה מפירין לאפוקי היכא דהפר א' וקיים אחד שאין המקיים יכול להפר בשעה שהפר זה עד שישאל על הקמתו דהא ליכא למימר דבבת אחת ממש בעינן דהא כתיב ביום שמעו דכל היום מותר להפר כדמפקינן לקמן:"],[4,"אמר קרא אם היו תהיה לאיש","לעיל מהאי קרא כתיב כי הניא אביה אותה וכתיב ואם היו תהיה לאיש וי\"ו מוסיף על ענין ראשון וכי היכי דאב מבטל נדרי בתו בזמן שהיא ברשותו ה\"נ מבטל עם הבעל כל זמן שהיא ארוסה דעדיין היא ברשותו:"],[4,"מכאן לנערה כו': ואימא","הדין קרא אם היו תהיה בנשואה כתיב שהבעל מיפר לה ולא האב ולא מיירי בארוסה:"],[5,"בנשואה לא מצית למימר דיהא קרא אחרינא כתיב","לנשואה ואם בית אישה נדרה:"],[5,"ואימא תרווייהו","הני קראי מיירי בנשואה דבעל מיפר ואי אמרת תרי קראי בנשואה למה לי חד לומר לך שאין הבעל מיפר בקודמין. ואם היו תהיה לאיש אתי למילף שהבעל מיפר נדריה של נשואה ואם בית אישה נדרה משמע דאותן נדרים שנדרה בבית אישה מיפר בעלה אבל אם היו עליה נדרים קודם שנשאה כשהיתה ארוסה וכנסה לא מצי מיפר:"]],[[0,"הפר האב ולא הפר הבעל","ובגמרא פריך היינו רישא אביה ובעלה:"],[2,"גמ' למה לי למיתני השתא י\"ל וכו'","וא\"ת מ\"ש דבכל דוכתא דתנא האי לישנא ואצ\"ל בפרק הזהב (ב\"מ ס.) תנן ואין צ\"ל חדשות בארבע וצ\"ע אם יהא בברייתא ולא במשנה וי\"ל דמשום הכי פריך הכא השתא משום דכיון דקיים אחד מהן הוי כמו לא הפר וכבר אמר לעיל כך אבל בדוכתא אחריתי כמו בהזהב לא אמר לעיל כל כך האי לישנא משום הכי לא פריך:"],[3,"וחזר המקיים ונשאל וכו'","דאמר לקמן נשאלין על ההקם:"],[3,"","דמה דהקים הא עקריה (הא) וסגי לה כשיפר לה עתה והפרת חבירו שבשעת הקם הפרה מלתא היא קמ\"ל דעד שמפירין שניהם בבת אחת והפרה קמייתא שהיתה כשהקים חבירו אינו כלום דבעינן כשיפר האחד שחבירו לא יקים אבל ודאי לא בעינן שיפרו שניהם ביחד דה\"ה אם הפרו זה אחר זה אם לא הקים:"],[4,"מנלן","דאב גרידא לא מצי מיפר:"],[4,"אמר קרא אם היו תהיה לאיש ונדריה עליה","והפרת נדריה כתובה למעלה דכתיב ואסרה אסר בבית אביה בנעוריה וכתיב ואם הניא אותה וכתיב בסמוך ואם היו תהיה לאיש אתא לך האי קרא וערבינהו לאב ולבעל ולקמן פריך אימא או אב או ארוס:"],[4,"ואם היו תהיה למה לי ש\"מ לארוסה","ואי קשיא אימא דואם היו תהיה איצטריך לערבו עם האב וללמד דאפילו בנשואה בעינן הפרת האב הא לא קשיא דא\"כ לא לכתוב ואם בית אישה בתר הפרת האב ונ\"מ כולהו ואם היו תהיה למה לי שמע מינה לארוסה (כך פירש הר\"ר אליעזר) וקשה דמכל מקום אימא דקרא דאם היו תהיה מיירי בין בנשואה בין בארוסה וקרא דבית אישה איצטריך לומר שאין מיפר בקודמין ויש לומר דאם היו תהיה לאו בנשואה מיירי דכיון דאין הבעל מיפר בקודמין דהא בההוא דאם היו תהיה כתיבי קודמין דכתיב ונדריה עליה (א\"נ) [א\"כ] על כרחך לאו בנשואה מיירי דהא אין הבעל מיפר בקודמין אבל האב מיפר בקודמין כדאמר בסמוך:"]]],[["ולאו ממילא שמעת מינה","איבעית אימא דהויה קדושין משמע","אימא אב לחודיה מיפר א\"כ (במדבר ל, ד) ואסרה איסר בית אביה יניא אותה למה לי השתא י\"ל במקום ארוס מיפר אב לחודיה שלא במקום ארוס מיבעיא","אימא אב ליבעי ארוס וארוס לחודיה מיפר וכי תימא אב דכתב רחמנא למה לי מיבעי ליה דאי הקים הקים","א\"כ בית אישה נדרה למאי כתב ק\"ו ומה במקום אב ארוס מיפר לחודיה שלא במקום אב מיבעיא","אימא (במדבר ל, יא) אם בית אישה נדרה לומר שאין הבעל מיפר בקודמין","ומיניה ארוס מיפר בקודמין","אלא לאו משום שותפותיה דאב"],[[0,"ולאו ממילא","דלעולם אם היו תהיה אתי לנערה המאורסה דאי כדקאמרת דתרוייהו בנשואה למה לי לא לכתוב אלא בית אישה לחודיה וממילא שמעת מינה דאינו מיפר בקודמין דמשמע אם בית אישה נדרה ולא מה שנדרה קודם לכן ואם היו תהיה למה לי שדייה לארוסה שהבעל והאב מפירין נדריה:"],[1,"ואיבעית אימא","להכי לא מצית לאוקומא להאי קרא ואם היו תהיה אלא בארוסה דכתיב לשון הויה דמשמע קידושין כדאמרינן במסכת קידושין (דף ה.) ויצאה והיתה מקיש הויה ליציאה:"],[2,"ואימא","להכי סמוך הכתוב כי הניא אביה אותה ואם היו תהיה לאיש לומר דאב מיפר לחודיה לבתו ארוסה בלא הארוס:"],[2,"א\"כ ואסרה איסר","דאתא לאשמועינן דאב מיפר בזמן שהיא ברשותיה שהיא נערה למה לי למכתב ממילא שמעינן דודאי מיפר דהשתא במקום ארוס שיש לו לארוס רשות בה האב מיפר לחודיה שלא במקום ארוס מיבעיא דאב מיפר לחודיה אלא ודאי להכי אתא קרא לומר דהאב מיפר עם הארוס:"],[3,"ואימא אב ליבעי ארוס","שאינו יכול להפר בלא ארוס כדקאמרת אבל ארוס מיפר לחודיה בלא אב:"],[3,"וכי תימא","אב דסמיך רחמנא לאם היו תהיה לו למה לי דדרשת לנערה דאביה ובעלה מפירין נדריה:"],[3,"מיבעי ליה דאם הקים","שיש לו לאב בכך רשות בה דאם הקים נדריה אין הארוס יכול שוב להפר אבל בלא הקמת אב מיפר בעל לחודיה:"],[4,"אט כן","דארוס לחודיה מיפר לא איצטריך לן קרא למימר דבעל מיפר נדרי אשתו דמק\"ו הוא דנפקא מה אם בעודה ארוסה שרשות שניהן בה מצי למיפר ארוס לחודיה כשנשאת שאין לאב רשות בה מיבעיא דמיפר בעל לחודיה אלא מדאיצטריך קרא למכתב ואם בית אישה נדרה שמע מינה דארוס במקום אב אינו מיפר לחודיה:"],[5,"ואימא","לעולם דארוס מיפר לחודיה ודקאמרת א\"כ בית אישה נדרה למה לי לומר לך שאין הבעל מיפר בקודמין:"],[6,"ומיניה","כלומר מיהא דאמרת דאיצטריך קרא להכי מיניה איכא למישמע נמי דלאו ארוס לחודיה מיפר דהשתא ומה בעל לאחר שנישאת לו אינו מיפר בקודמין במה שנדרה כשהיא ארוסה לו אינו יכול להפר עכשיו כשנכנסה כולה ברשותו:"],[6,"ארוס מיפר בקודמין","בתמיה בזמן שהיא ארוסה ולא נכנסה ברשותו היכי מצי מיפר לחודיה בהני נדרים שנדרה כשהיתה ארוסה:"],[7,"אלא לאו","האי דארוס מיפר:"],[7,"משום שותפותיה דאב","דמיפר בהדיה אבל ארוס לחודיה ודאי לא מצי מיפר:"]],[[1,"איבעית אימא","לא מצית אמרת דהיו תהיה בנשואה מיירי דהויה קדושין משמע מדלא כתיב ואם תלקח לאיש:"],[1,"אימא","דלכך עירוב פרשיות לומר דאב לחודיה מיפר בארוסה:"],[2,"אם כן ואסרה איסר דכתיב גבי פנויה למה לי השתא י\"ל במקום ארוס מיפר כו'","ואם תאמר אי הוה שתיק מיניה דהיו תהיה לא ידענא דבמקום ארוס אב מיפר וי\"ל לא ליכתוב אב אלא גבי ארוס אם היו תהיה ואמאי כתב גבי פנויה:"],[3,"ואימא אב ליבעי ארוס וארוס לחודיה מיפר","וכי תימא אב דכתב רחמנא למה לי - כלומר לענין מה סמכיה לקרא דהפרת האב גבי היו תהיה דמשמע דאב מיפר ומאי נפקא לן מינה בהפרתו כיון דבלא ארוס אינו מיפר וארוס בלא אב מיפר:"],[3,"מיבעי ליה דאם הקם הקים","האב והארוס מיפר דמוקם הנדר: אם כן בית אישה נדרה דמיירי בנשואה למה לי במקום אב ארוס מיפר לבדו שלא במקום אב מיבעי שיפר לבדו וקשה לימא דאימא דבית אישה איצטריך לומר דבנשואה אין האב מקים כמו בארוס ויש לומר דלהא לא איצטריך דפשיטא דבנשואה אין אב מקים אי נמי משמעותיה דקרא דגבי נשואה לא בהקים מיירי:"],[5,"אימא אם בית אישה נדרה לומר שאין הבעל מיפר בקודמין","ולעולם ארוס לחודיה מיפר:"],[6,"ומינה","כלומר מתשובתך אתה למד שאין ארוס לחודיה מיפר דלגבי נשואה אין בעל מיפר בקודמין וגבי ארוסה כתיב קודמין שמע מינה דמשום שותפות דאב הוא דבהכי יפה כחו דאב דמיפר בקודמין ובעל בלא אב אינו מיפר בקודמין:"]]],[["דבי רבי ישמעאל תנא (במדבר ל, יז) בין איש לאשתו בין אב לבתו מכאן לנערה המאורסה שאביה ובעלה מפירין נדריה ולתנא דבי ר' ישמעאל אם היו תהיה לאיש מאי עביד ליה","מוקים לאידך דרבא ורבא האי דתני דבי רבי ישמעאל מאי עביד ליה מיבעי ליה לומר שהבעל מיפר נדרים שבינו לבינה","איבעיא להו בעל מיגז גייז או מקליש קליש היכא קא מיבעיא לן כגון דנדרה מתרין זיתין ושמע ארוס והיפר לה ואכלתנון","אי אמרי' מיגז גייז לקייא אי אמרינן מקליש קליש איסורא בעלמא הוא מאי","תא שמע אימתי אמרו מת הבעל נתרוקנה רשות לאב בזמן שלא שמע הבעל קודם שימות או ששמע ושתק או ששמע והפר ומת בו ביום זו היא ששנינו מת הבעל נתרוקנה רשות לאב"],[[0,"בין איש לאשתו בין אב לבתו","ואיש דכתיבי בהאי קרא לא צריכי דאי משום איש לאשתו הרי כבר נאמר למעלה אלא מכאן לנערה המאורסה כו' דבין אב ובין איש מפירין נדריה דאיש מיפר חלקו באשתו ואב מיפר חלקו בבתו:"],[1,"כדאידך דרבה","דאמר לקמן (נדרים דף ע.) מקיש קודם הויה שניה כו':"],[1,"דברים שבינו לבינה","כגון שלא אשמש מטתו ושלא אכחול ושלא אתקשט:"],[2,"מיגז גייז","מה שהוא מיפר קוצץ החצי של נדר ועוקרו לגמרי וחלק אחר כדקאי קאי עד דאתי אב ומיפר לאותו חלק:"],[2,"או מקליש קליש","דהפרתו פשטה בכולי נדר וקלש ליה במעט והנדר קל ממה שהיה עד עכשיו:"],[2,"כגון שנדרה בשני זיתים","שלא תאכלם ושמע ארוס והיפר לה חלקו ואכלתן לזיתים:"],[3,"אי אמרת מיגז גייז","דכי שמע ארוס ומיפר חלקו הוי נדר מופר דהויא כאילו חלקו באמצע לשנים:"],[3,"לקיא","הא איתתא דאכלתן לזיתים משום לאו דלא יחל דכי אכלה להנך תרי זיתים חד הוה מותר בהפרת הארוס דמיגז גייז לנדרה ואידך אסור משום חלק האב דנמצא דאכלה זית שלם באיסור:"],[3,"ואי אמרת מיקלש קליש","דאינו חותך לשנים אלא למעט מיקל לה דלא הוי הנדר חמור כדהוה עד השתא הא כי אכלה הנהו תרי זיתי כיון שהנדר נקלש ומיקל ליה איסורא בעלמא הוא דעבדא ולא לקיא דהנדר אינו גמור:"],[4,"אימתי אמרו כו'","בנערה קא נקט לה מתניתין:"],[4,"מת הבעל","כשהוא ארוס:"],[4,"נתרוקנה רשות לאב","כאדם שמריק יין מכלי אל כלי כלומר שיצא כל הרשות מן הבעל ובא לרשות האב:"],[4,"בזמן שלא שמע בעל","את נדרה קודם שימות דביום שמעו בעינן וליכא:"],[4,"או ששמע והפר חלקו בו ביום","ששמע ואפילו שמע ושתק שלא הפר ולא קיים ולא הספיק להראות דעתו עד שמת בו ביום דהואיל ואכתי איכא שהות ביום דאי הוה בעל מצי מיפר איכא למימר דמיתה גרמה לו דדלמא אי הוה קיים אכתי הוה מיפר לה מיקמי דליעבר יומא ומת בו ביום קאי אשמע ושתק:"],[4,"זו היא ששנינו","על כל הני קאי: מת הבעל נתרוקנה רשות לאב והאב עצמו מיפר כולו בזמן שלא היפר הבעל וכן בזמן שהיפר הבעל חוזר האב ומיפר את חלקו כדתנ' עלה במתניתין בזה יפה כח האב מכח הבעל שהאב מיפר בלא שותפות אבל הבעל אינו מיפר אלא בחיי האב:"]],[[0,"בין איש לאשתו בין אב לבתו מכאן וכו'","דמשמע ליה דבאשה אחת מיירי דקאמר דשתי רשויות עליה אב ואישה ואכתי איכא למיפרך ואימא בנשואה נמי מפירין אביה ובעלה ולתרץ כדשנינן לעיל מדהכא כתיב בית אישה נדרה דקאמר שאינו מיפר בקודמין והכא לא כתיב ומיפר בקודמין שמע מינה דמשום שותפות דאב הוא דמיפר בקודמין:"],[0,"ותנא דבי ר' ישמעאל היו תהיה למה לי","נרא' לפרש דלא מגופא דקרא קא בעי דהא איצטריך למימר דמיפר בקודמין אלא פריך מסמיכות דקרא למה לי כי נמי לא סמכם הכתוב ידענו שפיר דאב ובעל צריכין להפר שניהם מקרא דבין איש לאשתו:"],[1,"מיבעיא ליה לכאידך דרבא","דדריש לקמן מת הבעל נתרוקנה לרשות האב ומן הסמוכין דריש ליה ואם תאמר והא איצטריך הא דהיו תהיה להא דרשא דלעיל שהבעל מיפר מן האירוסין ויש לומר כיון דהוה מצי למכתב היו וכתב תהיה שמע מינה דאתי לומר נתרוקנה רשות לאב:"],[1,"ורבא","דדריש ביה מילתיה דלעיל הא דר' ישמעאל למה לי לומר שהבעל מיפר בדברים שבינו לבינה וכן בין אב לבתו לומר שיפר האב דברים שבינו לבין בתו דס\"ד דאפילו מכל דבר כיון שאינו מפרש שום דבר שהוא מיפר קמ\"ל דברים שבינו לבין בתו דוקא דדברים מעינוי נפש:"],[2,"איבעיא להו","ארוס דמיפר בלא אב מיגז גייז מה שמיפר מבטל וחצי הנדר נשאר על עומדו כאשר בתחלה או מיקלש קליש בהפרתו מקליש כל הנדר נתגרע כולו וה\"ה דמצי למיבעי מאב אי מיגז גייז או מיקלש קליש בהפרתו כשמיפר בלא בעל:"],[2,"היכא מיבעיא ליה","כלומר ונפקא מיניה כגון דנדרה מזיתים שאמרה שלא תאכל מכל זיתים אי אמרת מיגז גייז לקייא דחצי הנדר במקומו עומד ונשאר האיסור על העתיד ועובר בבל יחל ואי מיקלש קליש איסור בעלמא דנתגרע כל הנדר ואין כאן אלא איסור בעלמא:"],[4,"אימתי אמרו מת הבעל נתרוקנה לרשות האב כגון שלא שמע בעל או שמע והפר","דכיון דבעל לא קיים לה יפר האב אחר מות הבעל אבל אם שמע וקיים בעל או שמע ושתק ומת ביום של אחריו דהוה הקמה אין יכול להפר כיון דקיים בעל:"]]],[["אבל אם שמע וקיים או ששמע ושתק ומת ביום שלאחריו אין יכול להפר","שמע אביה והפר לה ולא הספיק בעל לשמוע עד שמת האב זו היא ששנינו מת האב לא נתרוקנה רשות לבעל שמע בעלה והפר לה ולא הספיק האב לשמוע עד שמת הבעל זו היא ששנינו מת הבעל נתרוקנה רשות לאב","שמע בעלה והפר לה ולא הספיק האב לשמוע עד שמת אין הבעל יכול להפר שאין הבעל מיפר אלא בשותפות"],[[0,"אבל אם שמע","הבעל וקיים אע\"פ שמת בו ביום או שמע ושתק כל אותו היום ומת הבעל ביום שלאחריו אין האב יכול להפר הואיל ועבר יום שמעו:"]],[[1,"ה\"ג שמע אביה והפר לה ולא הספיק הבעל לשמוע עד שמת האב אינו יכול להפר","ע\"י הבעל דלא נתרוקנה לרשות הבעל ולא סגי בהפרת אב והבעל אינו מיפר דבעינן אב קיים בשעת הפרת הבעל הלכך הפרה דאחר מיתת האב לא כלום היא ובהפרה שהפר האב לפני מותו לא סגי כיון דהבעל לא הפר:"],[1,"ה\"ג שמע בעלה והפר לה ולא הספיק [האב] לשמוע עד שמת הבעל זהו ששנינו מת הבעל נתרוקנה רשות לאב","והיינו כמו רישא אלא ענין אחר הוא דהכא מת הבעל קודם ששמע [האב] שנדרה וניחא ליה למיתני בכל הענינים:"],[2,"שמע בעלה והפר לה ולא הספיק האב לשמוע עד שמת האב אין הבעל יכול להפר שאין הבעל מיפר אלא בשותפות","ודאי מרישא שמעינן לה אלא משום דבעי למיתני איפכא גבי האב תניא נמי הכי גבי בעל שמע אביה והפר לה ולא הספיק בעלה לשמוע עד שמת חוזר אב ומיפר חלקו של בעל וזה לא שמעינן מרישא דהבא הפר אב בחיי בעל ולא הועילה כלום אותה הפרה שוב לא תועיל הפרתו דלא מצינו ב' הפרות באדם אחד לכך אשמעינן דחוזר אב ומיפר:"]]],[["שמע אביה והפר לה ולא הספיק הבעל לשמוע עד שמת חוזר האב ומפר חלקו של בעל א\"ר נתן הן הן דברי ב\"ש ב\"ה אומרים אין יכול להפר","ש\"מ לב\"ש מיגז גייז לב\"ה מקלש קליש ש\"מ","בעי רבא יש שאלה בהקם או אין שאלה בהקם את\"ל יש שאלה בהקם יש שאלה בהפר או אין שאלה בהפר","ת\"ש דא\"ר יוחנן נשאלין על ההקם ואין נשאלין על ההפר","בעי רבה קיים ליכי קיים ליכי ונשאל על הקמה ראשונה מהו","ת\"ש דאמר רבא אם נשאל על הראשונה שניה חלה עליו בעי רבה קיים ליכי ומופר ליכי ולא תיחול הקמה אא\"כ חלה הפרה מהו"],[[0,"שמע אביה והפר לה","בו ביום ולא הספיק הבעל לשמוע שיפר לה עד שמת חוזר ומיפר חלקו של בעל ואין צריך להפר חלקו הואיל וכבר הפר:"],[0,"ב\"ה אומרים אין יכול להפר","חלקו של בעל בלבד אא\"כ חוזר ומיפר חלקו עמו משום דסבירא להו מקליש היכא דהפר חר בלא חבריה ואכתי הוי הנדר שלם אלא שאין איסורא חמור כבתחלה וכיון דאכתי הנדר שלם הוא מיבעי ליה לבטל חלקו וחלק הבעל דנתרוקנה רשותו לו:"],[1,"ובית שמאי סברי מיגז קא גייז","כי קדם האב והפר חלקו חתכו לשנים ונתבטל חציו ועדיין חציו קיים וכשמיפר עכשיו חלקו של בעל הוי שלו מופר:"],[1,"ש\"מ","דתנאי היא ומקלש קליש כבית הלל:"],[2,"יש שאלה בהקם","שאם קיימו לה נדרה האב והארוס ונשאלו על הקמתן מהו מי יש שאלה ויכולין להפר לה או לא:"],[2,"יש שאלה בהפר","היכא דקיים האחד והיפר האחד יכול האחר לשאול על הקמתו במקום שהפר כבר השני והוי מופר:"],[2,"ענין אחר יש שאלה בהפר","כלו' את\"ל יש שאלה בהקם מי הוי מופר הנדר באותה שאלה דהקמה דאין צריך לומר לה בהפרתו או אין שאלה בהפר דלא הוי מופר אא\"כ מפר לה בעל או האב לאחר שנשאל דבאותה שאלה דהקמה לא הוי מופר לה:"],[2,"ע\"א יש שאלה בהקם","שקיים לה הבעל או האב הנדר ואח\"כ הלך ונשאל עליו לחכם והתירו החכם מי אמרינן דכיון שקיים את הנדר שוב אין נשאלין עליו ולא הוי שאלה מעליא או דלמא כיון שהתירו חכם בטלה הקמתו וביטל הנדר:"],[2,"את\"ל יש שאלה בהקם יש (לה) שאלה בהפר","כלומר במקום הפר שאם שמע את נדרה ולא רצה להפר אלא הלך ונשאל בו ביום על אותו נדר לחכם מאי מי אמרינן הואיל אם היא הולכת לחכם ונשאלת לו שיהא מתירה דהא לדברי הכל אם נשאלת לחכם יכול להתיר לה הכא נמי אם נשאל האב לחכם על נדר בתו יהא מותר הואיל ואי בעי מצי מיפר:"],[3,"ת\"ש דאמר רבי יוחנן נשאלין על ההקם","באותו ענין שפירשתי ואין נשאלין על ההפר כמו כן:"],[3,"ת\"ש נשאלין על ההקם","ללישנא קמא נשאלין על ההקם ומותרין להפר לה:"],[3,"ואין נשאלין על ההפר","דהיכא דקיים אחד והפר אחד אין נשאל אלא או כולו בשאלה או כולו בהפרה בעינן וללישנא בתרא נשאלין על ההקם ומותרין להפר לה אח\"כ ואין נשאלין על ההפר דאין הנדר מופר במה שמתיר החכם לבטל ההקמה אא\"כ מיפר לה בעל או אב לאח\"כ:"],[4,"קיים ליכי קיים ליכי","תרי זימני ונשאל על הקמה ראשונה וביטלה:"],[4,"מהו","כלומר הקמה שניה דלא נשאל עליה בטלה באותו שאלה אי לא:"],[5,"ת\"ש דאמר רבא","בפ' ואלו מותרין (לעיל נדרים יח.) שבועה שלא אוכל שבועה כו' דאמר רבא אם נשאל על הראשונה שניה חלה עליו ה\"נ אם נשאל על הקמה ראשונה שניה חלה עליו:"],[5,"אמר קיים ליכי והדר אמר מופר ליכי","בתוך כדי דבור ובלשון הזה אמר בתוך כדי דבור ראשון ולא תיחול הקמה אא\"כ חלה הפרה מהו. מי ביטל ההקמה וקיים ההפרה אי לא:"]],[[0,"אמר רבי נתן הן דברי ב\"ש","אהך סיפא קאי ובה\"א אינו יכול להפר האב ש\"מ - לב\"ש מיגז גייז אב שמיפר חלקו וחלק הבעל כדקאי הלכך הוריש לאב וב\"ה סברי מיקלש קליש בהפרה דאב ונדר גרוע הוא הלכך אין יכול הבעל להורישו לאב דהכי נמי מיגז גייז לא יצאו לבעל וי\"מ דב\"ה פליגי נמי ארישא דהפר הבעל ומת דאמר דמפר וב\"ה אומרים אינו יכול להפר כיון דהפר בעל מיקלש קליש [ונתגרע] הנדר ולא יועיל להתבטל ע\"י הפרה דאב גרידא ולב\"ש מיגז גייז ונשאר נדר חשוב ומועיל לבטלו הפרה דאב ויכול להיות דלא פליגי ברישא משום דהפרת הבעל נתבטל לפי שאינו קיים בשעת הפרת האב אי נמי שבתחלה לא הפר האב מתוך שחלקו קיים יפר לו חלק הבעל:"],[2,"יש שאלה בהקם","אם הקים הבעל ושאל לחכם מהו שיוכל הבעל להפר ובו ביום מיירי דאי ביום של אחריו לא מועיל השאלה דמוקם [הנדר] לעולם [וכ\"ש] כיון דקיים:"],[2,"יש שאלה בהפר","אם נשאל על הפרתו מי אמרינן שהנדר חזר לאיתנו או לא:"],[3,"","ת\"ש [דאמר ר\"י] נשאלים על ההקם ואין נשאלין על ההפר:"],[4,"בעי רבה קיים ליכי קיים ליכי ונשאל על הקמה ראשונה מהו","מי אמר דיכול להפר לפי דהקמה שניה אינה כלום שהרי לא חלתה על הראשון או דלמא כי משכחת רווחא חיילא:"],[5,"","ת\"ש [דאמר רבא אם] נשאל על הראשונה כשנשבע ב' שבועות שלא יאכל ככר זה דשבועה שניה לא חלתה מיד ומושבע ועומד מהראשונה שניה חלה עליו דכי משכח רווחא חיילא וה\"נ כי משכח רווחא חיילא:"],[5,"קיים ליכי מופר ליכי ולא תיחול הקמה עד דחיילא הפרה מהו","מי חיילא בתרא או קמא אבל לא מבעיא ליה [אם אמר] קיים ליכי ומופר ליכי ולא אמר לא תיחול הקמה עד למחר וכו' דהא ודאי הקמה שאמר תחלה חלה ולא הפרה ולא מיבעי למ\"ד תפוס לשון ראשון אלא אפילו לרבי יוסי דאמר אף בגמר דבריו אדם נתפס וחיילי תרוייהו גבי תמורת עולה ותמורת שלמים (תמורה דף כה:) היינו דוקא התם דיכולין לקיים שניהם אף זה אחר זה להביא בדמי חציה עולה וחציה שלמים אבל הכא דאי אפשר לחול זה אחר זה כיון דחל הראשון לא תחול אחריו שני:"]]],[["תא שמע מפלוגתא דרבי מאיר ורבי יוסי דתנן הרי זו תמורת עולה תמורת שלמים הרי זו תמורת עולה דברי רבי מאיר ורבי יוסי אומר אם לכך נתכוין מתחלה הואיל ואי אפשר לקרות שני שמות כאחד דבריו קיימין","ואפילו רבי מאיר לא קאמר דלא אמר לא תיחול זו אלא אם כן חלה זו אבל הכא דאמר לא תיחול הקמה אלא אם כן חלה הפרה ר\"מ נמי מודה דהפרה חלה","בעי רבה קיים ומופר ליכי בבת אחת מהו ת\"ש דאמר רבה כל דבר שאינו בזה אחר זה אפי' בבת אחת אינו","בעי רבה קיים ליכי היום מהו מי אמרינן כמאן דאמר לה מופר ליכי למחר או דלמא הא לא אמר לה"],[[0,"ת\"ש","דכי האי גוונא פלוגתא דר\"מ ורבנן במסכת תמורה בפ' כיצד מערימין על הבכור:"],[0,"הרי זה תמורת עולה תמורת שלמים כו' דבריו קיימין","ויביא בדמי חציה עולה ובדמי חציה שלמים:"],[1,"ואפילו רבי מאיר","לא אמר תפוס לשון ראשון אלא דלא אמר לא תיחול זו אלא אם כן חלה שניה ועל מה נחלקו באומר תמורת עולה ותמורת שלמים רבי מאיר סבר דלמא מיהדר הוא דהדר ביה מתמורת עולה ואמר תמורת שלמים והואיל וכן תפוס תחלת דבריו והרי היא עולה: ור' יוסי סבר אי אמר תמורת עולה ושלמים הוה אמינא קדושה ואינה קריבה קמ\"ל:"],[1,"אבל הכא דקאמר לא תחול בו'","ודאי הויא הפרה כי ההוא טעמא דתמורה:"],[2,"קיים ומופר ליכי","ולא אמר ליכי בין קיים למופר מי אמרינן כיון דלא אמר קיים ליכי ומופר לכי הויא כמ\"ד לא תיחול הקמה אלא אם כן חלה הפרה דכיון דלא אמר קיים ליכי גלי אדעתיה דבהפרה ניחא ליה או דלמא לא שנא וכמ\"ד קיים ליכי ומופר ליכי דמי ולא תהוי הפרה:"],[2,"ת\"ש דאמר רבה","[בקדושין] ואמעשר בהמה קאי:"],[2,"כל שאינו בזה אחר זה","כגון שאם קרא לעשירי עשירי וחזר וקרא לי\"א עשירי אינו קדוש וקאמר אף בבת אחת שאם קרא לשניהן עשירי סתם אין האחד עשר קדוש ה\"נ כיון דאינו בזה אחר זה שאם אמר לה עכשיו קיים ליכי ולאחר שעה אמר מופר ליכי אין בהפרתו כלום בבת אחת נמי כי אמר קיים ומופר ליכי אין באותה הפרה כלום אע\"ג דבבת אחת קאמר קיים ומופר ליכי:"],[3,"היום מהו","מי אמרינן כיון דאמר היום כמאן דאמר היום יהא מקויים אבל למחר יהא מופר לה והוי מופר:"],[3,"או דלמא הא לא אמר לה","בפירוש מופר ליכי למחר:"]],[[0,"ת\"ש מפלוגתא דר\"מ ור' יוסי","פי' מפלוגתא דר' יוסי פשטינן בעיין לכ\"ע:"],[0,"תמורת עולה ותמורת שלמים וכו' ואמר רבי יוסי אם לכך נתכוון מתחלה","כיון שבשעת תמורת עולה היה בדעתו לומר תמורת שלמים לאפוקי אם נמלך כדתניא בסיפא דמילתא הואיל וא\"א לקרות שני שמות בב\"א דבריו קיימין עון דאמר בדמי חציה עולה ובדמי חציה שלמים ואפילו ר\"מ לא אמר אלא דלא אמר לא תחול זו אא\"כ חלה זו דבזה מודה דלא חלה הראשונה וחלה שניה אבל הכא כו' אפי' ר\"מ מודה דחל הפרה והקמה לאו כלום הוא:"],[2,"קיים ומופר ליכי מהו","מי אמרינן דודאי כיון דבדיבור אחד קאמר שלא אמר קיים ליכי מופר ליכי חיילי תרוייהו או לא:"],[2,"כל שאינו בזה אחר זה","אם אמר קיים ליכי מופר ליכי דאין הפרה חלה אחר הקמה בב״א אינו לא לזה ולא לזה והוי כאילו שתק ובפרק שני דקידושין (דף נ:) גבי ב' אחיות אמרה רבה ללמילתיה וא״ת אמאי לא אמר הכי גבי תמורת עולה ותמורת שלמים אמר רבי מאיר תמכר ויבא בדמי חציה עולה ובדמי חציה שלמים (ה״ג וצ״ע דבברייתא תניא בפ' כיצד מערימין (תמורה דף כו) דלרבי מאיר - כולה קרבה עולה) וי״ל דמ״מ ניחא לאביי דאמר כל לחצות מודה ר״מ דכיון דאי אמר לחצות תלו שניהם בבת אחת:"],[3,"בעי רבה קיים ליכי היום מי אמר נו'","דהכי משמע מקיים ליבי היום אבל למחר יהא מופר או דלמא לא אמרינן דדעתו לבטל כיון שאינו מפר בפירוש - אבל ודאי אי אמר קיים ליכי היום ומופר ליכי למחר מועלת הפרתו אלא [אמר] מופר ליכי למחר ולא אמר קיים ליכי היום מי אמרינן כיון דאמר לה מופר ליכי למחר מהיום קאמר לה וקיימה לנדרה או דלמא הא לא אמר לה קיים ליכי היום הלכך כי אמר מופר ליכי למחר מהיום קאמר לה דדעתו להפר מהיום אבל ודאי אמר קיים ליכי היום ומופר ליכי למחר לא אמרינן מהיום קאמר ואע\"ג דמתחלה לא מבעיא ליה אלא משום דלא אמר מופר ליכי אבל אמר קיים ליכי היום ומופר ליכי למחר מועלת ההפרה והשתא פשיטא ליה דלא מועיל הפרה ודוחק דבעיא שניה את\"ל הא לא קאמר לה משמע שגם בעיא דרבה לפי סברא וי\"ל דודאי מעיקרא קים ליה שפיר דאי אמר קיים ליכי היום מופר ליכי למחר לא מהני וה\"פ בעי רבה קיים ליכי היום מהו כיון דאמר היום משמע אבל למחר יהא מופר וכמאן דאמר [מופר] ליכי למחר דדעתיה שתמול מהיום:"]]],[["את\"ל הא לא אמר לה אמר לה מופר ליכי למחר מהו מי אמרינן למחר לא מצי מיפר דהא קיימיה לנדריה היום או דלמא כיון דלא אמר לה קיים ליכי היום כי קאמר לה מופר ליכי למחר מהיום קאמר","ואם תמצא לומר אפילו הכי כיון דקיימו היום למחר כמאן דאיתיה דמי (א\"ל) קיים ליכי שעה מהו מי אמרינן כמאן דאמר לה מופר ליכי לאחר שעה דמי או דלמא הא לא אמר לה","אם תמצא לומר הא לא אמר לה מיהו אמר לה מאי מי אמרינן כיון דקיימו קיימו או דלמא כיון דכוליה יומא בר הקמה ובר הפרה הוא כי אמר מופר ליכי לאחר שעה מהני","ת\"ש הריני נזירה ושמע בעלה ואמר ואני אין יכול להפר ואמאי נימא ואני דאמר הוא על נפשיה דהוי נזיר אבל הריני נזירה דילה דשעה אחת קיימא לאחר שעה אי בעי ליפר אמאי אין יכול להפר לאו משום דכיון דקיימו קיימו לא קסבר כל ואני כמאן דאמר קיים ליכי לעולם דמי","\u0001מתני׳\u0002 מת האב לא נתרוקנה רשות לבעל מת הבעל נתרוקנה רשות לאב בזה יפה כח האב מכח הבעל","בדבר אחר יפה כח הבעל מכח האב שהבעל מפר בבגר והאב אינו מפר בבגר","\u0001גמ׳\u0002 מאי טעמא דאמר קרא (במדבר ל, יז) בנעוריה בית אביה","מת הבעל נתרוקנה רשות לאב מנלן אמר רבה דאמר קרא (במדבר ל, ז) ואם היו תהיה לאיש ונדריה עליה"],[[0,"אמר לה מופר ליכי למחר מהו","דהא קיימיה לנדריה היום דכיון דאמר מופר ליכי למחר אלמא דבהאי יומא דשמע ביה הוי נדר וקיומי קיימיה ותו לא מצי מיפר לה:"],[0,"או דלמא כיון [דלא] אמר","ומופר ליכי בהדי קיים ליכי מהיום דשמע לה קאמר דתיהוי מופר:"],[1,"אם תמצא לומר כיון דקיימו היום","ולא חיילא הפרה עד למחר אלמא דבהאי יומא דשמע ניחא ליה דלקיים וכמאן דאיתיה לקיום דמי דקיימו בידים ולא הוי הפרה כלל:"],[1,"אמר לה קיים ליכי שעה","אחת מהו:"],[1,"או דלמא הא לא אמר לה","מופר ליכי לאחר שעה אחת:"],[2,"אם תמצא לומר","דתיהוי קיום הואיל ולא אמר לה:"],[2,"מיהו אמר לה","מופר ליכי לאחר שעה מהו:"],[2,"מי אמרינן כיון","דאמר לה קיים ליכי שעה אחת דקיימו לעולם ושוב אינו מיפר או דלמא כיון דכוליה יומא דשמע ביה נדרה בר הקמה והפרה הוא שאם לא קיימו בשחרית וקיימו בערבית הוי מקויים וכן אם לא הפירו בשחרית והפירו בערבית הוי מופר דכל היום כשר להפרת נדרים וכי הדר ואמר מופר ליכי ליהוי מופר:"],[3,"ושמע בעלה ואמר ואני","כלומר ואני אהיה נמי כמותיך כיון דאמר הכי אינו יכול להפר נזירות אשתו:"],[3,"ואמאי נימא דהאי דאמר ואני אנפשיה הוא דאמר","דליהוי נזיר:"],[3,"אבל הריני נזירה דילה","דקאמרה איהי שעה אחת:"],[3,"קיימיה","בעל משום לאתפוסי בה דידיה:"],[3,"אבל לאחר שעה","דכבר חל נזירות עילויה:"],[3,"אי בעי למיפריה","אמאי אינו יכול להפר אלא כיון דקיימו משום לאתפוסי בה נזירות דידיה קיימו והכא נמי בנדרים כיון דקיים שעה אחת קיים לעולם ושוב לא מצי מיפר:"],[3,"לא","מהכא ליכא למשמע מינה טעמא דאינו יכול להפר דקסבר כל ואני כמאן דאמר קיים ליכי לעולם [דמי] ותו לא מצי מיפר אבל היכא דלא קיימו אלא שעה אחת וחזר והיפר לה בשעה אחרת תיבעיא לך:"],[4,"מתני' מת האב לא נתרוקנה רשות לבעל","דאין הבעל מיפר אלא בשותפות כדמפרש לעיל (נדרים דף סח:):"],[4,"מת הבעל נתרוקנה רשות לאב","כדמפרש בגמ':"],[4,"בזה יפה כח האב מכח הבעל","דנתרוקנה רשות לאב:"],[5,"שהבעל מיפר בבגר","כדאמרינן במסכת כתובות (דף נז.) הגיע זמן ולא נשאו אוכלות משלו ואוכלות בתרומה וכל הנודרת על דעת בעלה נודרת שמאכילה הואיל והוי חייב במזונותיה כי נודרת יכול להפר לה:"],[5,"אב אינו מפר בבגר","כדכתיב בנעוריה ולא בבגרותה:"],[6,"גמ' בנעוריה בית אביה","כל זמן שהיא נערה שלא בגרה לא תצא מרשות אביה ואפילו היא ארוסה במשמע הלכך כי מת האב לא נתרוקנה רשות לבעל:"],[7,"אם היו תהיה לאיש","בשני הויות הכתוב מדבר:"]],[]],[["מקיש קודמי הויה שניה לקודמי הויה ראשונה מה קודמי הויה ראשונה אב מיפר לחודיה אף קודמי הויה שניה אב מיפר לחודיה","אימא ה\"מ בנדרי' שלא נראו לארוס אבל בנדרים שנראו לארוס לא מצי מיפר אב","אי בנדרים שלא נראו לארוס מבנעוריה בית אביה נפקא","בזה יפה כח האב מכח הבעל כו' ה\"ד","אילימא שקידשה כשהיא נערה ובגרה מכדי מיתה מוציאה ובגרות מוציאה מרשות אב מה מיתה לא נתרוקנה רשות לבעל אף בגרות לא נתרוקנה רשות לבעל","אלא שקידשה כשהיא בוגרת הא תנינא חדא זימנא הבוגר' ששהתה י\"ב חדש","הא גופא קשיא אמרת הבוגרת ששהתה שנים עשר חדש בבוגרת למה לי שנים עשר חדש בוגרת בל' יום סגי לה תני בוגרת וששהתה י\"ב חדש","מ\"מ קשיא איבעית אימא הכא דוקא ובוגרת קתני התם משום דבעי איפלוגי ר\"א ורבנן","איבעית אימא בוגרת דוקא ואיידי דנסיב רישא בזה נסיב סיפא נמי בזה"],[[0,"מקיש קודמי הויה שניה","כלומר שמת ארוס ראשון וראויה להתקדש לאחר:"],[0,"לקודמי הויה ראשונה","שלא נתארסה לעולם והיא יושבת נערה בבית אביה מה קודמי כו':"],[1,"הני מילי","דאב מיפר בקודמי הויה שניה בנדרים שלא נראו לארוס ראשון אי לא שמע להו הבעל קודם שימות דהיינו דומיא דקודם הויה ראשונה:"],[1,"אבל בנדרים שנראו לארוס","ששמע בהן קודם שימות ולא. הספיק להפר אין האב מיפר עד שתחזור ותתארס שיפירו הוא ואחרון:"],[1,"וא\"א דבנדרים שנראו לארוס","לא מצי מיפר לחודיה למה לי למיכתב ואם היו תהיה לאקושי הוויות להדדי:"],[2,"מבנעוריה נפקא","דמשמע כל כמה דיתבא בבית אביה מצי מיפר לה אלא מדקא מקיש הוויות להדדי ש\"מ דומיא דקודם הויה ראשונה קאמר דמצי מיפר לחודיה בנדרים שלא נראו לארוס דומיא דהויה ראשונה. פי' אחר אבל בנדרים שנראו לארוס לא מצי מיפר אי ליכא ארוס אחרון הא לא מצית אמרת דלהכי אתי היקשא לרבות נדרים שלא נראו לארוס דהא מקרא אחרינא שמעינן ליה מבנעוריה נפקא דאמרי' כל שבח נעוריה לאביה שהאב זכאי בהפרת נדריה והלכך כי אתא ואם היו תהיה לאיש לנדרים שנראו לארוס הוא דאתא:"],[3,"היכי דמי","דבעל מיפר בבגר:"],[4,"אי נימא שקדשה כשהיא גערה ובגרה","לאחר שנתארסה:"],[4,"מכדי מיתה מוציאה מרשות האב","שיכולה לקדש את עצמה אע\"פ שהיא נערה:"],[4,"ובגרות מוציאה מרשות האב","דכיון שבגרה אין לאביה רשות בה לא לקדשה ולא למוכרה:"],[4,"","מה במיתת האב לא נתרוקנה כו':"],[5,"אלא כשקדשה כשהיא בוגרת","וקתני כאין האב מיפר אלא הבעל:"],[5,"הא תנינא חדא זימנא","בהך פירקין גופיה:"],[5,"בוגרת ששהתה י\"ב חדש","משנתארסה ר' אליעזר אומר הואיל ובעלה חייב במזונותיה יפר דכמאן שנכנסה ברשותו דמי ואמרינן עלה הא גופא קשיא אמרת הבוגרת ששהתה י\"ב חדש והלא דין שלה ל' יום דהכי תנן במסכת כתובות (דף נז.) נותנין לבתולה שניש עשר חדש לפרנס עצמה לקנות מלבושים ותכשיטין לצורך נישואין משתבעה הבעל להינשא ולאלמנה ולבוגרת ל' יום דבוגרת אית לה מלבושין ותכשיטין והכי נמי לאלמנה ואית להו רווחא טובא בשלשים יום וכולן אם הגיע זמנן כו' אלמא דבוגרת לא בעינן י\"ב חדש:"],[6,"תני בוגרת וכו'","האי כי דיניה והאי כי דיניה יפר ומתני' דקתני שהבעל מיפר בבגר לאחר שלשים יום שתבעה לפרנס את עצמה הוא דקאמר:"],[7,"מ\"מ קשיא","דתרי זימני למה לי למיתני דהבעל מיפר בבגר:"],[7,"איבעית אימא בזו דוקא","דהך רישא דמתני' קתני דהבעל מיפר דוקא קתני לה ובוגרת וששהתה גררא נסבא משום איפלוגי ר\"א ורבנן:"],[8,"ואיבעית אימא בוגרת","דקתני בסיפא בפלוגתא דר\"א ורבנן הוי דוקא והא דקתני שהבעל מיפר לאו דוקא:"],[8,"אלא איידי דנסיב רישא בזה יפה כח האב","איצטריך לה למיתני נסיב סיפא בזה יפה כח הבעל:"]],[]],[["\u0001מתני׳\u0002 נדרה והיא ארוסה נתגרשה בו ביום נתארסה בו ביום אפי' למאה אביה ובעלה האחרון מפירין נדריה זה הכלל כל שלא יצאה לרשות עצמה שעה אחת אביה ובעלה האחרון מפירין נדריה","\u0001גמ׳\u0002 מנלן דארוס אחרון מיפר נדרים שנראו לארוס ראשון אמר שמואל אמר קרא (במדבר ל, ז) ואם היו תהיה לאיש ונדריה עליה נדרים שהיו עליה כבר דלמא הני מילי שלא נראו לארוס ראשון אבל נדרים שנראו לארוס ראשון לא מצי מיפר ארוס אחרון","עליה קרא יתירא הוא","תניא כוותיה דשמואל נערה המאורסה אביה ובעלה מפירין נדריה כיצד שמע אביה והפר לה ולא הספיק הבעל לשמוע עד שמת ונתארסה בו ביום ואפי' מאה פעמים אביה ובעלה האחרון מפירין נדריה שמע בעלה והפר לה ולא הספיק האב לשמוע עד שמת הבעל חוזר האב ומפר חלקו של בעל","א\"ר נתן הן הן דברי בית שמאי אבל בית הלל אומרים אין יכול להפר במאי פליגי"],[[0,"מתני' אביה ובעלה האחרון מפירין נדריה","אפי' מה שנדרה באירוסי ראשון:"],[0,"לרשות עצמה","שלא ניסת לאחד מהן או שלא בגרה בתוך הזמן אביה ובעלה כו':"],[1,"גמ' [ונדריה עליה]","קרא יתירא הוא דלא איצטריך למיכתב דליכתוב רחמנא ואם היו תהיה לאיש ונדריה או מבטא שפתיה אלא עליה מופנה משום נדרים שנראו לארוס הראשון דיכול להפר ארוס אחרון:"],[3,"תניא כוותיה דשמואל","דאפילו בנדרים שנראו לארוס ראשון מיפר בעל אחרון:"],[3,"ולא הספיק הבעל לשמוע כו'","דהיינו לא נראו לארוס ראשון:"],[3,"שמע בעלה והיפר לר","דהשתא נראו לארוס ראשון:"],[3,"חוזר האב ומיפר חלקו של בעל","לפי שאין הבעל מיפר אלא בשותפות שבשעה שהפר עדיין לא שמע האב ובשביל הכי חוזר ומיפר חלקו של בעל עם חלקו:"],[4,"הן הן דברי ב\"ש","דאפילו נדרים שנראו לארוס מיפר האב לחודיה:"],[4,"אבל ב\"ה אומרים","אין אב יכול להפר לא חלקו ולא חלק חבירו עד שיהא ארוס אחד עמו הואיל ונראו לארוס:"],[4,"במאי פליגי","ב\"ש וב\"ה התם אמרי ב\"ש גבי שמע אביה והיפר לה ולא הספיק הבעל לשמוע עד שמת חוזר האב ומיפר חלקו של בעל ומפרשינן התם אליבא דב\"ש אינו צריך להפר חלקו אלא חלק הבעל בלבד וב\"ה אומרים אין יכול להפר חלק הבעל בלבד אלא א\"כ מיפר חלקו עמו והכא מוחלפת השיטה דב\"ש סברי דשמע בעלה והיפר לה ולא הספיק האב לשמוע עד שמת הבעל וחזר האב ומיפר חלקו סל בעל אינו הפרה עד שיכלול חלק הפרתו והפרת בעל בבת אחת והכא קאמרי ב\"ה אינו יכול להפר כלל בלא ארוס אחרון אלא הכא בהא קמיפלגי דהוו נדרים שנראו לארוס כדקתני שמע בעלה והפר לה הכא קאמרי:"]],[]],[["בית שמאי סברי נדרים נמי שראוי לארוס נתרוקנה רשות לאב ומיגז גייז בית הלל סברי אביה ובעלה אחרון מפירין נדריה ולא מיגז גייז","איבעיא להו גירושין כשתיקה דמיא או כהקמה דמיא","למאי נפקא מינה כגון שנדרה ושמע בעלה וגרשה ואהדרה ביומיה אי אמר מר כשתיקה דמי מצי מיפר לה ואי אמר מר כהקמה דמי לא מצי מיפר לה"],[[0,"","ב\"ש נתרוקנה רשות לאב וצריך להפר שניהן בבת אחת של אותו ושל בעל והתם הוויין נדרים שלא נראו לבעל כדקתני שמע אביה והפר לה ולא הספיק הבעל לשמוע והתם קאמרי ב\"ש מיגז גייז דהואיל והפר האב כבר לא אצטריך ליה להפר אלא חלקו של בעל וב\"ה סברי נדרים שנראו לארוס ראשון הכא אביה ובעלה מפירין נדריה דהאב אינו מיפר אלא עם ארוס אחרון אבל התם דהוויין נדרים שלא נראו לארוס לא מיגז גייז אלא מיקלש קליש ומיפר חלקו וחלק הבעל:"]],[]],[["ת\"ש אימתי אמרו מת הבעל נתרוקנה רשות לאב בזמן שלא שמע הבעל או שמע והפר או שמע ושתק ומת בו ביום ואי אמרת גירושין כשתיקה דמו ליתני נמי או שמע וגירש מדלא תני הכי ש\"מ גירושין כהקמה דמו","אימא סיפא אבל אם שמע וקיים או שמע ושתק ומת ביום של אחריו אין יכול להפר ואי אמרת גירושין כהקמה דמו ליתני ואם שמע וגירש אלא מדלא קתני הכי ש\"מ גירושין כשתיקה דמו","אלא מהא ליכא למשמע מיניה אי רישא דוקא נסיב סיפא משום רישא אי סיפא דוקא נסיב רישא משום סיפא","ת\"ש נדרה והיא ארוסה ונתגרשה ונתארסה בו ביום אפילו למאה אביה ובעלה האחרון מפירין נדריה ש\"מ גירושין כשתיקה דמו דאי כהקמה דמו מי מצי מיפר ארוס אחרון נידרי דאוקים ארוס ראשון","הב\"ע בשלא שמע ארוס ראשון אי הכי מאי איריא בו ביום אפילו לאחר מאה ימים נמי","כשלא שמע ארוס ושמע האב דבו ביום הוא דמצי מיפר אבל מכאן ואילך לא מצי מיפר","תא שמע נדרה בו ביום גירשה והחזירה בו ביום אין יכול להפר שמע מינה גירושין כהקמה דמו","אמרי הכא בנשואה עסקינן והיינו טעמא דאין יכול להפר משום דאין הבעל מיפר בקודמין:"],[[2,"אי רישא דוקא נסיב סיפא משום רישא","כלומר לא תקשה סיפא לרישא אע\"ג דמרישא שמעינן דגירושין כהקמה דמו ובסיפא שמעינן דכשתיקה דמו לא קשיין אהדדי דאימא רישא דוקא דגירושין כי הקמה דמו והאי דלא תני סיפא שמע וגירשה משום דלא נסיב לה אלא משום רישא ותנא לא בעי לאוסופי מידי בסיפא טפי מרישא:"],[2,"א\"נ סיפא נמי דוקא","דגירושין כשתיקה דמו:"],[4,"הכא במאי עסקינן בשלא שמע ארום ראשון","קודם שגירשה ואהכי מצי מיפר ארוס אחרון הא לאו הכי לא דגירושין כי הקמה דמו:"],[4,"מאי איריא","אי נתארסה לאחר בו ביום דמצי למיפר לה:"],[4,"אפילו לאחר מאה ימים נמי","אם נתארסה לאחר ליהוי ארוס אחרון מיפר הואיל ולא נראו לארוס ראשון:"],[5,"אין הבי נמי אלא הב\"ע בשלא שמע ארוס ראשון אבל שמע האב","והואיל דבו ביום שמע צריך להפר בו ביום כדכתיב ביום שמעו:"],[7,"הכא בנשואה עסקינן","הא דקתני גירשה והחזירה כגון שנשאת ונדרה וגירשה ביום ששמע והחזירה בו ביום דעכשיו יצאה שעה אחת לרשות עצמה ואע\"פ שהחזירה נעשית כנשואה לאחר דלא מצי מיפר דעכשיו הן קודמין כדתנן (לעיל נדרים דף ע ז.) זה הכלל כל שלא יצאת לרשות עצמה שעה אחת אביה ובעלה מפירין נדריה הא יצאה לרשות עצמה אין מפירין משום דאין הבעל מיפר בקודמין:"]],[[0,"ליתני שמע וגירש","ומת בו ביום מדלא תני הכי וכו':"],[1,"ליתני שמע וגירש","ומת ביום שלאחריו דאין אב מיפר מדלא תני הכי וכו':"],[2,"אלא מהא ליכ' למשמע","דשמא רישא דווקא ושמא סופא דווקא ולא קשי' רישא שסיפא דאי רישא דווקא דגירושי' כהקמ' ובדין הוא דליתני בסיפא שמע וגירשה נסיב סיפא משו' רישא דברישא לא מצי למיתני ליה וסיפא דדווקא לגירושי' עשתיקה ובדין הוא דברישא מצי למיתני שמע וגירש משום סיפא לא נסיב לה לא תני לה ברישא:"],[3,"ת\"ש נדרה והיא ארוסה ונתקדשה בו ביום","וס\"ד מדנקט בו ביום מיירי ששמכ בעל וכשגירה הרי קיים אי גירושי' כהקמה."]]],[["\u0001מתני׳\u0002 דרך תלמידי חכמים עד שלא היתה בתו יוצאה מאצלו אומר לה כל נדרים שנדרת בתוך ביתי הרי הן מופרין וכן הבעל עד שלא תכנס לרשותו אומר לה כל נדרים שנדרת עד שלא תכנסי לרשותי הרי הן מופרין שמשתכנס לרשותו אינו יכול להפר","\u0001גמ׳\u0002 בעי רמי בר חמא בעל מהו שיפר בלא שמיעה (במדבר ל, ח) ושמע אישה דוקא הוא או לאו דוקא הוא","אמר רבא ת\"ש דרך תלמידי חכמים עד שלא יצאת בתו מאצלו אומר לה כל נדרים שנדרת בתוך ביתי הרי הן מופרין והא לא שמע","לכי שמע הוא דמיפר א\"כ כי לא שמע למה ליה למימר הא קמשמע לן אורחיה דצורבא מרבנן להדורי","ת\"ש מסיפא וכן הבעל עד שלא תכנס לרשותו אומר לה הכא נמי דאמר לה לכי שמענא","ת\"ש האומר לאשתו כל נדרים שתדורי עד שאבא ממקום פלוני הרי הן קיימין לא אמר כלום הרי הן מופרין רבי אליעזר אומר מופר והא לא שמע","הכא נמי דאמר לכי שמענא ולמה לי מן השתא לכי שמע ליפר לה קסבר דלמא מטרידנא ההיא שעתא","תא שמע האומר לאפוטרופוס כל נדרים שנודרת אשתי מכאן ועד שאבא ממקום פלוני הפר והפר לה יכול יהו מופרין תלמוד לומר (במדבר ל, יד) אישה יקימנו ואישה יפרנו דברי רבי יאשיה","אמר לו רבי יונתן מצינו בכל התורה כולה שלוחו של אדם כמותו","ואפילו רבי יאשיה לא קאמר אלא משום דגזירת הכתוב הוא אישה יקימנו ואישה יפרנו אבל דכולי עלמא שלוחו של אדם כמותו והא לא שמיע ליה"],[[0,"מתני' דרך תלמידי חכמים וכו'","מפרש בגמרא:"],[0,"אם משתכנס לרשותו אינו יכול להפר","דאין הבעל מיפר בקודמין:"],[1,"גמ' מהו שיפר בלא שמיעה","שיאמר כל נדרים שנדרה אשתי יהו מופרים אע\"ג שלא שמע בהן וה\"ה נמי באב אי מצי למיפר בלא שמיעה:"],[1,"ושמע אישה דוקא הוא","דאינו מיפר אלא אם כן שמע:"],[2,"והא לא שמע","והיכי מצי מיפר להו:"],[3,"לכי שמע הוא דמיפר","דהא דמיפר להו לא משום דהשתא מיפר בלא שמיעה אלא לכי שמע ליה לנדר לאח\"כ ליהוי מופר בהא הפרה שהיפר כל זמן שהיא ברשותו:"],[3,"א\"כ","דאכתי לא שמע ולא הוו מופרים בהפרה זו למה ליה למימר השתא הא לא מהני ולא מידי:"],[3,"להדורי","לחזור ולבדוק אחר בתו אם יש עליה שום נדר דליפר לה שלא תבא לידי מכשול:"],[5,"ת\"ש האומר לאשתו וכו' הרי הן קיימין לא אמר כלום","דעדיין לא בא הנדר לעולם והיאך יכול לקיימו:"],[6,"כגון דאמר לה לכי שמענא","יהו מופרים. ומאחר דהפרה תליא בשמיעה למה ליה למימר השתא לכי שמע מפר לה:"],[6,"קסבר דלמא מטרידנא ההיא שעתא","בשעה שישמע הנדר שמא יהא טרוד ולא יפרנו:"],[7,"אישה יפרנו","וגו' ולא שליח:"],[9,"ואפי' ר' יאשיה","אית ליה דשלוחו של אדם כמותו אי לאו משום דכתיב אישה יפרנו והיכי מצי משוי שליח כל זמן שלא נדרה הא לא שמע לנדרה אלא לאו ושמע לאו דוקא ואהכי מצי משוי שליח:"]],[]],[["הכא נמי דאמר ליה לכי שמענא מיפר לה לכי שמע ליפר לה הוא סבר דלמא מטרידנא","בעי רמי בר חמא חרש מהו שיפר לאשתו אם תמצא לומר בעל מיפר בלא שמיעה משום דבר מישמע הוא אבל חרש דלאו בר מישמע הוא היינו דר' זירא","דאמר רבי זירא כל הראוי לבילה אין בילה מעכבת בו וכל שאין ראוי לבילה בילה מעכבת בו","או דלמא ושמע אישה לא מעכב אמר רבא ת\"ש ושמע אישה פרט לאשת חרש שמע מינה","איבעיא להו בעל מהו שיפר לשתי נשיו בבת אחת אותה דוקא או לאו דוקא","אמר רבינא ת\"ש אין משקין שתי סוטות כאחת מפני שלבה גס בחבירתה","ר' יהודה אומר לא מן השם הוא זה אלא משום שנאמ' (במדבר ה, כד) והשקה אותה לבדה:"],[[0,"דאמר ליה","לשליח לכי שמענא לנדרה הפר לה:"],[0,"","וקפריך לכי שמע ליפר לה:"],[0,"הוא","הבעל סבר דלמא מיטרידנא:"],[1,"משום דבר מישמע הוא","וקרינן ביה ושמע אישה ואדהכי מלי מיפר:"],[1,"היינו דר' זירא","דאמר במסכת מנחות בפ' המנחות והנסכים והכי הוא שאלו שאלה לעילא מדר' יהודה בר אילעאי מנין לאומר הרי עלי ששים ואחד עשרון שמביא ששים בכלי אחד ואחד בכלי אחד והכי תנינן במתני' מתנדב אדם מנחה של ששים עשרון ומביא בכלי אחד ואם אמר הרי עלי ששים ואחד מביא ס' בכלי אחד וא' בכלי א' פתח ר' יהודה בר אילעאי והתם מפרש כו' א\"ל הרי הוא אומר כל מנחה בלולה בשמן וחריבה אמרה תורה הבא מנחה שיכולה להבלל וקים להו לרבנן דס' נבללין בכלי אחד ויותר אין נבללין כו' ופריך התם מאי טעמא משום דאין נבללין אלמא דבלילה מעכבת והתנן אם לא בלל כשר ומתרץ רבי זירא כי אמרינן דבלילה [אין] מעכבת בראוי לבילה כגון ששים עשרונים הראוי לבילה אם לא בלל כשר וכל שאין ראוי לבילה כגון ששים ואחד בילה מעכבת ומאחר דאין נבללין אין מביאין ה\"נ גבי חרש כל הראוי לשמוע כגון שאינו חרש בדידיה אין שמיעה מעכבת ובעל מיפר בלא שמיעה ושאינו ראוי לשמיעה כגון חרש שמיעה מעכבת בו ולא מצי מיפר:"],[3,"או דילמא ושמע אישה לא מעכב","כלל:"],[4,"בבת אחת","בדיבור אחד:"],[4,"דוקא","יניא אותה ולא שתים בבת אחת:"],[5,"שתי סוטות כאחת","בשתי כוסות:"],[5,"שלבה גס בחבירתה","הואיל ויש לי חברתה אחרת מה בכך אם אשתה אני:"],[6,"והשקה לבדה","דוהשקה דוקא משמע אחת ולא ב':"]],[]],[["\u0001מתני׳\u0002 בוגרת ששהתה י\"ב חדש ואלמנה ל' יום ר' אליעזר אומר הואיל ובעלה חייב במזונותיה יפר וחכ\"א אין הבעל מיפר עד שתכנס לרשותו","\u0001גמ׳\u0002 אמר רבה ר\"א ומשנה ראשונה אמרו דבר אחד דתנן נותנין לבתולה י\"ב חדש לפרנס עצמה הגיע י\"ב חדש אוכלת משלו ואוכלת בתרומה אבל היבם אינו מאכיל בתרומה","עשתה ששה חדשים בפני הבעל וששה חדשים בפני היבם ואפילו כולן בפני הבעל חסר יום א' או כולן בפני היבם חסר יום א' אינה אוכלת בתרומה זו משנה ראשונה ב\"ד של אחריהם אמרו אין האשה אוכלת בתרומה עד שתכנס לחופה","א\"ל אביי דלמא לא היא עד כאן לא קא אשמעינן משנה ראשונה אלא למיכל בתרומה דרבנן אבל נדרים דאורייתא אימא לא","ועד כאן לא שמעת ליה לר' אליעזר אלא גבי נדרים כדרב פנחס משמיה דרבא דאמר כל הנודרת על דעת בעלה היא נודרת אבל תרומה אפילו מדרבנן נמי לא אכלה"],[[0,"מתני' הבוגרת","והנערה ששהתה י\"ב חדש ואלמנה ששהתה ל' יום:"],[0,"הואיל ובעלה חייב במזונותיה","כדאמרינן במס' כתובות בפ' . אע\"פ נותנין לבתולה י\"ב חדש משתבעה הבעל לפרנס את עצמה וכשם שנותנים לאשה כך נותנים לאיש לפרנס את עצמו הגיע זמן ולא נישאו אוכלת משלו וכו' ובוגרת נותנין ל' יום כאלמנה:"],[0,"ר\"א אומר יפר","כדאמר לקמן כל הנודרת על דעת בעלה נודרת:"],[0,"אין הבעל מיפר","יחידי עד שתכנס לרשותו:"],[1,"גמ' משנה ראשונה","בפרק אע\"פ:"],[1,"היבם אינו מאכיל","לשומרת יבם מן הארוסין:"],[2,"עשתה ששה חדשים","שהיתה ארוסה לראשון ו' חדשים ולפני היבם ששה דהיינו י\"ב חדש שנותנין לבתולה לפרנס את עצמה:"],[2,"ואפילו","עשתה כולן י\"ב חודש לפני הבעל וחסר יום אחד אחרון לפני היבם אינו מאכילה בתרומה הא עשתה כולן י\"ב חודש לפני הראשון ונפלה לפני היבם הואיל וכבר חייב הבעל במזונותיה מאכילה יבם בתרומה אף ע\"פ שלא הכניסה ככנוסה דמיא וה\"נ אמר ר\"א הואיל ובעלה חייב במזונותיה יפר:"],[2,"ב\"ד של אחריהן אמרו אין האשה אוכלת בתרומה כו'","והתם מפ' טעמא שמא ימזגו לה כוס בבית אביה ותשקה את אחותה:"],[3,"אלא בתרומה דרבנן","בזמן הזה דלא הוי אלא מדרבנן אי נמי בתרומה דרבנן כגון עציץ שאינו נקוב ופירות שנכנסו מח\"ל:"],[3,"אבל נדרים דאורייתא","התם קא אמרי רבנן דאינו מיפר:"],[4,"וע\"כ לא שמעת ליה לר\"א אלא גבי נדרים","והיינו טעמא דמשנתחייב יפר משום דרב פנחס וכו' והיינו לאחר שנתחייב במזונותיה אבל לגבי תרומה דיבם לא מבעיא בתרומה דאורייתא דלא אכלה אפי' עשתה י\"ב בפני הבעל אלא אפילו בעציץ שאינו נקוב דתרומה דרבנן לא אכלה:"]],[]],[["\u0001מתני׳\u0002 שומרת יבם בין ליבם אחד בין לשני יבמין ר\"א אומר יפר ר' יהושע אומר לאחד אבל לא לשנים ר\"ע אומר לא לאחד ולא לשנים","אמר ר\"א מה אם אשה שקנה הוא לעצמו הרי הוא מיפר נדריה אשה שהקנו לו מן השמים אינו דין שיפר נדריה","אמר לו ר\"ע לא אם אמרת באשה שקנה הוא לעצמו שאין לאחרים בה רשות תאמר באשה שהקנו לו מן השמים שיש לאחרים בה רשות","א\"ל ר' יהושע עקיבא דבריך בשני יבמין מה אתה משיב על יבם אחד אמר לו אין היבמה גמורה ליבם כשם שהארוסה גמורה לאישה","\u0001גמ׳\u0002 בשלמא ר\"ע סבר אין זיקה ור\"י סבר יש זיקה אלא ר\"א מאי טעמיה אי יש זיקה אין ברירה","אמר ר' אמי כגון שעשה בה מאמר ורבי אליעזר סבר לה כב\"ש דאמרי מאמר קונה קנין גמור","ורבי יהושע אומר לך ה\"מ בחד יבם אבל בשני יבמין לא מי איכא מידי דכי אתי אחוהי אסר עליה בביאה או בגיטא ומפר ור\"ע סבר אין זיקה","ולר' אליעזר דאמר מאמר לב\"ש אין קונה אלא לדחות בצרה מאי איכא למימר","הכא במאי עסקינן כגון שעמד בדין ואיתחייב לה מזונות וכדרב פנחס משמיה דרבא דאמר כל הנודרת על דעת בעלה היא נודרת"],[[0,"מתני' בין ליבם אחד","בין שזקוקה ליבם אחד בין לשני יבמין אמר ר' אליעזר יפר ומוקמינן ליה בגמרא בשעשה בה מאמר אחד מהן:"],[1,"ומה אשה שקנה הוא לעצמו","כגון הנושא אשה בעלמא:"],[1,"שהקנו לו מן השמים","יבמה שחייבו לו מן התורה:"],[2,"שאין לאחר רשות בה","המקדש אשה מן השוק לאחר שקידשה לא תפסי בה קידושי מאדם אחר ואהכי מצי מיפר:"],[2,"שיש לאחר רשות בה","שאם עשה בה מאמר יבם זה ובא אחיו אח\"כ ועשה בה מאמר תפיס בה כדאמר (יבמות נ.) יש מאמר אחר מאמר:"],[3,"דבריך בשני יבמין","דבשני יבמין מצית למימר כי האי גוונא:"],[3,"מה אתה משיב על יבם אחד","בהא לא מצית למימר שיש לאחרים רשות בה הואיל וליכא יבם אחר ואת לא משוית חילוק בין יבם אחד לשני יבמין:"],[3,"א\"ל אין היבמה גמורה לאישה","שאם בא עליה זר אין נסקל שאין בה לא דין ארוסה ולא דין אשת איש ואין חייבין עליה אלא לאו דלא תהיה אשת המת וגו' (דברים כ״ה:ה׳):"],[3,"כשם שארוסה","בעלמא גמורה לאישה שנסקלין על ידה:"],[4,"גמ' קסבר אין זיקה","ואפילו ליבם אחד אינה זקוקה דתיהוי כאשתו עד שתכנס לחופה:"],[4,"ור' יהושע סבר יש זיקה","ולהכי לאחד יפר אבל לשנים אינו מיפר דאין ברירה לאיזה מהן זקוקה ולאיזה מהן תתיבם אע\"ג דאמרי' (יבמות כד.) מצוה בגדול לייבם מ\"מ אם בא עליה קטן קנאה:"],[4,"לעולם קסבר ר\"א יש זיקה","והיינו טעמא דאפילו לשנים יפר בשעשה בה האחד מאמר דהשתא יש ברירה ואליבא דב\"ש דאמרי דמאמר קונה קנין גמיר והיא כאשתו לכל דבר הלכך מיפר לה:"],[5,"לעולם קסבר ר\"א יש זיקה","והיינו טעמא דאפילו לשנים יפר בשעשה בה האחד מאמר דהשתא יש ברירה ואליבא דב\"ש דאמרי דמאמר קונה קנין גמיר והיא כאשתו לכל דבר הלכך מיפר לה:"],[6,"ה\"מ ביבם אחד","דיש זיקה:"],[6,"אבל בשני יבמין לא","קני מאמר דלאחר דעשה בה מאמר אילו אתי אחוה מצי לאוסרה עליו בביאה או בגיטא דיש ביאה וגט אחר מאמר:"],[6,"מי איכא מילתא וכו'","משום האי טעמא דאילו אית ליה אחא להאי יבם מצי מפיק לה מיניה בתר הכי שמקדשה או על ידי גט וביאה וקרו להנהו קדושי מאמר ולית בהו מששא כולי האי:"],[7,"ולר' אלעזר בן פדת דאמר מאמר כו' אלא לדחות בצרה בלבד","שאם היו ב' נשים לזה שמת ושתיהן זקוקות ליבם ואי אפשר לייבם לנשתיהן דבית אחד הוא בונה ואינו בונה שתי בתים ובהא מילתא קסברי בית שמאי דמאמר קונה דכשעושה בזו מאמר דוחה לצרה ומתירה לשוק אבל עדיין זו זקוקה לאחיו דמצי אשר לה עליה:"],[7,"מאי איכא למימר","אכתי תיבעי לך מאי טעמא דאמר ר\"א אפילו לשנים יפר:"],[8,"כגון שעמד בדיין","משעשה בה מאמר שזו תבעתו בדין מפני שלא היה מייבמה וחייבוהו בית דין לינשא לה וברח [דאיחייב] לה במזונותיה ובהפרת נדריה וכדרב פנחס כו':"]],[]],[["תנן אמר רבי אליעזר ומה אם אשה שקנה לעצמו הרי הוא מיפר נדריה אשה שהקנו לו מן השמים אינו דין שמיפר נדריה ואי בשעשה בה מאמר קנה לעצמו הוא שקנה לעצמו ע\"י שמים","תפשוט דבעי רבה מאמר לבית שמאי אירוסין עושה או נשואין עושה תפשוט דנשואין עושה דאי אירוסין עושה הא תנן נערה המאורסה אביה ובעלה מפירין נדריה","אמר רב נחמן בר יצחק מאי יפר יפר בשותפות","תניא נמי הכי כרבי אמי שומרת יבם בין יבם אחד בין שני יבמין ר\"א אומר יפר ורבי יהושע אומר לאחד ולא לשנים ר\"ע אומר לא לאחד ולא לשנים","א\"ר אליעזר ומה אם אשה שאין לו חלק בה עד שלא תבא לרשותו משבאת לרשותו נגמרה לו אשה שיש לו חלק עד שלא תבא לרשותו משבאת לרשותו אינו דין שתגמור לו","אמר לו ר\"ע לא אם אמרת באשה שקנה הוא לעצמו שכשם שאין לו חלק בה כך אין לאחרים חלק בה תאמר באשה שהקנו לו מן השמים שכשם שיש לו עמה חלק כך יש לאחרים חלק בה","אמר לו ר\"י עקיבא דבריך בשני יבמין מה אתה משיב על יבם אחד א\"ל כלום חלקנו על יבם אחד ועל שני יבמין בין שעשה בה מאמר בין שלא עשה בה מאמר וכשאר דברים כן נדרים","בלשון הזה אמר בן עזאי חבל עליך בן עזאי שלא שימשת את ר\"ע","מאי"],[[0,"ואי","אמרת טעמא דרבי אליעזר דאמר לשנים מיפר כגון שעשה בה מאמר הא דאמר שהקנו לו מן השמים קנה לעצמו הוא במה שעשה בה מאמר:"],[1,"או נשואין עושה","יורשה ומיטמא לה והבא עליה נידון בחנק דאי אירוסין דלא פקעה זיקת אחיו לגמרי מינה היכי מצי יבם מיפר לחודיה:"],[1,"והא תנן נערה המאורסה וכו'","דכל זמן שהיא ארוסה אכתי שייך בה אביה:"],[2,"מאי יפר דקאמר ר\"א בשותפות","עם אביה דלעולם אירוסין עושה:"],[3,"תניא כוותיה דר' אמי","דבעשה בה מאמר פליגי:"],[4,"משבאת לרשותו נגמרה לו","מיפר נדריה הוא ואביה:"],[4,"אשה שיש לו חלק בה עד שלא תבא לרשותו","שהיא זקוקה לו עד שלא עשה בה מאמר:"],[4,"משבאת לרשותו","דעשה בה מאמר:"],[4,"אינו דין שתיגמר לו","דמפר נדריה:"],[5,"כך אין לאחרים חלק בה","קודם שתתארס לו:"],[5,"כך יש לאחרים חלק בה","לשאר יבמין:"],[6,"מה אתה משיב על יבם אחד","שאין אתה מודה לי עליו הואיל ואין לאחרים חלק בה כארוסה דמיא ומיפר לה:"],[6,"כלום חלקנו כו'","דודאי בין עשה בה מאמר בין לא עשה בה מאמר אינו חייב סקילה הבא עליה כנערה המאורסה הלכך אינו מיפר לא שנא יבם אחד ולא שנא שני יבמין דהכל דינו שוה דאין חיוב יותר הבא על שומרת יבם אחד מהבא על שומרת שני יבמין:"],[6,"וכשאר דברים כן נדרים","דכשם דלענין סקילה אין לה דין כנערה מאורסה כך בנדרים אינה גמורה לאישה להפר כנערה מאורסה והכי מפ' לקמן:"],[7,"שלא שימשת את ר\"ע","שיודע לנצח כל כך ולהשיב תשובות מעולות:"]],[]],[["תניא כוותיה דר' אמי דקתני בין שעשה בה מאמר ובין שלא עשה בה מאמר","א\"נ מרישא דקתני משנכנסה לרשותו נגמרה לו ואי דלא קדיש מאי נגמרה לו תפשוט מיניה כשעשה בה מאמר","מאי וכשאר דברים כן נדרים דקתני אמר רבא הכי קתני אי אתה מודה שאין חייבין סקילה כנערה המאורסה","אמר רב אשי מתני' נמי דיקא אין יבמה גמורה לאישה כשם שארוסה גמורה לאישה","\u0001מתני׳\u0002 האומר לאשתו כל הנדרים שתדורי מכאן עד שאבא ממקום פלוני הרי הן קיימין לא אמר כלום הרי הן מופרין ר' אליעזר אמר מופר וחכ\"א אינו מופר אמר ר\"א אם הפר נדרים שבאו לכלל איסור לא יפר נדרים שלא באו לכלל איסור","אמרו לו הרי הוא אומר (במדבר ל, יד) אישה יקימנו ואישה יפרנו את שבא לכלל הקם בא לכלל הפר לא בא לכלל הקם לא בא לכלל הפר","\u0001גמ׳\u0002 איבעיא להו לר\"א מיחל חלין ובטלין או דלמא לא חלין כלל למאי נפקא מינה"],[[0,"ומאי תניא כוותיה","ממאי משכחינן הכא דתניא כוותיה דר' אמי דכשעשה בה מאמר פליגי:"],[0,"מדקתני ר\"ע אומר כלום חלקנו בין יבם כו' בין שעשה בה מאמר כו'","מכלל דשמעיה ליה לר\"א דאמר דכשעשה בה מאמר יפר ואהכי מהדר ליה ר\"ע הכי:"],[1,"א\"נ","מדקאמר ר' אליעזר ברישא משנכנסה לרשותו נגמרה לו אשה שיש לו חלק בה וכו' אינו דין שתגמר לוואי דלא קדיש דלא עשה בה מאמר מאי עמרה לו איכא:"],[2,"אי אתה מודה","שאפילו עשה בה מאמר שאין חייבין עליה סקילה כנערה המאורסה הלכך לגבי נדרים נמי לא הוי כארוסה ואהכי אינו יכול להפר לה:"],[3,"מתניתין נמי דיקא","כרבי אמי טעמא דר\"ע דאמר בברייתא וכשאר דברים כן נדרים משום סקילה הוא דקאמר:"],[3,"דקתני אין היבמה גמורה לאישה","מדקא קרי לה ליבמה אשה אלמא כשעשה בה מאמר עסקינן ומדאמר הכי דאיכא נמי להקיש לארוסה שמע מינה דמשום סקילה הוא דקאמר ר\"ע דאינו מפר כשם שמפר לארוסה:"],[4,"מתני' הרי הן קיימין לא אמר כלום","דנדרים שלא באו לעולם אינו יכול לקיים:"],[4,"שבאו לכלל איסור","שכבר נדרה וקא חייל עלה אפילו הכי מפר כ\"ש דמפר אותן שלא באו לכלל איסור כשיבאו דעדיין לית בהו מששא אבל לענין קיום אי אפשר שידון כך דנדרים שכבר באו לכלל איסור דין הוא שיקיים הלכך לא אמר כלום לדברי הכל:"],[5,"את שלא בא לכלל הקם","שעדיין לאו באו לעולם ואי אפשר לקיימו כדקתני דכי אמר הרי הן קיימין לא אמר כלום:"],[5,"אינו בא לכלל הפר","דאינו יכול להפר:"],[6,"גמ' מיחל חיילי","עלה ובטלי לאלתר משום דהפרה קודם לכן:"],[6,"או דילמא לא חיילי כלל","דהפרה דעבד קא מהניא דלא חיילא עלה שום נדר:"]],[]],[["כגון דאתפיס אחרינא בהדין נדרא אי אמרת חלין הויא תפיסותא אי אמרת לא חלין לא איכא מששא","מאי ת\"ש אמר רבי אליעזר אם הפר נדרים שבאו לכלל איסור לא יפר נדרים שלא באו לכלל איסור שמע מינה לא חלין","מי קתני שאינן באין שלא באו קתני עדיין לא באו","ת\"ש אמר להן ר\"א ומה במקום שאין מיפר נדרי עצמו משנדר מיפר נדרי עצמו עד שלא ידור מקום שמפר נדרי אשתו משתדור אינו דין שיפר נדרי אשתו עד שלא תדור","מאי לאו דאשתו דומיא דיליה מה [הוא] דלא חיילין אף אשתו נמי דלא חיילין לא הא כדאיתא והא כדאיתא","ת\"ש אמרו לו לר\"א ומה מקוה שמעלה את הטמאין מטומאתן אין מציל על הטהורים מליטמא אדם שאין מעלה את הטמאין מטומאתן אינו דין הוא שלא יציל על הטהורין מליטמא","שמע מינה לא חיילין"],[[0,"דאי אתפיס אחרינא בהדין נדרא","כגון שנדרה בנזיר ואמרה הריני נזירה ושמע איש אחר ואמר ואני כמו כך:"],[0,"ואי אמרת חיילי הוי תפיסותא","וחייל נמי אאידך דאתפיס נמי בהדי האי נדר:"],[0,"ואי אמרת לא חיילי","כמי שלא נדרה דמי ולא חייל נמי אאידך דאתפיס ביה:"],[1,"[ש\"מ]","מדקאמר שלא באו לכלל איסור שמע מינה לא חיילי כלל:"],[2,"מי קתני שאין באין","דמשמע אפילו לכשהיא נודרת:"],[2,"שלא באו קתני","משמע דעדיין לא נדרה אבל לכשיבאו כשתדור אכתי תיבעי לך אי חיילי אי לא:"],[3,"שאין מפר נדרי עצמו משידור","שאין אדם מפר נדרים לעצמו אלא א\"כ נשאל לחכם דכתיב לא יחל דברו (במדבר ל׳:ג׳) הוא אינו מיחל וכו':"],[3,"מפר נדרי עצמו עד שלא ידור","כדתנן בפרק ארבעה נדרים (לעיל נדרים כג:) הרוצה שלא יתקיימו נדריו יעמוד בראש השנה ויאמר כל נדר וכו':"],[4,"הא כדאיתא והא בדאיתא","נדרי עצמו לא חיילי כלל כי מבטל להו מראש השנה אבל נדרי אשתו כשהוא מקדים ומפר אותן חיילי ובטלי לאלתר הואיל ועל דעת בעלה היא נודרת ובברייתא מפרש אמרו לו לר\"א אם אמרו בנדרי עצמו לכך הן בטלין כשהן באין לאחר מכאן שכן בידו להקים תאמר בנדרי אשתו שאינו יכול לקיים עד שלא תדור וכו':"],[5,"ת\"ש אמרו לו לר\"א מקוה יוכיח ומה מקוה שמעלה את הטמאים מטומאתן","שהטובל בו עולה מטומאתו:"],[5,"אין מציל על הטהורים מליטמא","שאינו יכול לטבול בו על מנת שאם יגע בטומאה לאחר כך שתועיל לו האי טבילה שלא יטמא אף בעל נמי אע\"פ שמעלה נדר אשתו שנדרה מאיסור להיתר אינו יכול להציל על הנדרים שעתידה לידור שיהא מקדים להן הפרה. מדקאמרו ליה הכי על הטהורים שלא יטמא שמע מינה דלא חיילי דהכי שמיע להו מיניה דר\"א דלא חיילי משום הכי קאמרי ליה בהאי לישנא על הטהורים מליטמא:"],[5,"אדם שאין מעלה את הטמא מטומאתו אינו דין שלא יציל על הטהורים מליטמא","הכי פירושו אדם שאין מעלה את הטמאים מטומאה שאם בלע טבעת טמאה והקיאה דרך בית הריעי לא אמר דתיהוי ככלי גללין ותעלה מטומאתה:"],[5,"אינו דין שלא יציל על הטהורים מליטמא","שאם בלע טבעת טהורה כדי להקיאה דרך בית הריעי שלא תקבל טומאה לאחר כן מפני שהיא כגללים שאין מיטמא וכשם שאין מציל על הטהורים מליטמא כל עיקר כך לא יהא מועיל לו לארוס כשמפר לנדרי אשתו שעתידה לידור:"],[5,"ע\"א מ\"ר ומה אדם שאין מעלין את הטמאין מטומאתן","שאם בלע טבעת טמאה וטבל לאחר כן אינו מועיל לטבעת טבילתו דלטומאה בלועה לא מהני טבילה ואם הקיאה אחרי כן טמאה:"],[5,"מציל על הטהורים","שאם בלע טבעת טהורה ואח\"כ נטמא מציל על הטבעת כיון דבלועה היא לא נטמאה:"],[5,"מקוה שמעלה את הטמאים מטומאתן","שאם טבלו בו טהורין אינו דין שיציל על הטהורין מליטמא דאפילו נגעו הטומאה לא יטמאו:"],[5,"ע\"א ומה מקוה שמעלה וכו'","הכי פירושו שעל שם ומה חכם שמעלה הקמה שקיים הבעל שמתיר לה אין מציל על אדם שאם ידור לא יהא נדר אדם שאינו מעלה הטמאין כו' כדפדישית בטבעת אף בעל נמי שאינו יכול להפר הקמתו אלא א\"כ ישאל לחכם אינו דין שאינו מפר בנדרי אשתו קודם שנדרה שאינו מועיל כלום מה שהפר קודם שתידור שלא יהא נדרים:"]],[]],[["אימא סיפא אמרו לו לר\"א אם מטבילין כלי טמא ליטהר יטבילו כלי לכשיטמא ליטהר שמע מינה חיילין","אמרי רבנן לא קיימי להון בטעמיה דר\"א והכי קאמרי ליה מאי סבירא לך אי סבירא לך דחיילין ובטלין תהוי כלי תיובתך אי לא סבירא לך דחיילין תהוי מקוה תיובתך","ת\"ש אמר להם ר\"א ומה זרעים טמאים כיון שזרען בקרקע טהורין זרועין ועומדים לא כל שכן ש\"מ לא חיילין","ורבנן לא דרשי ק\"ו והא תניא יכול ימכור אדם את בתו כשהיא נערה אמרת ק\"ו מכורה כבר יוצאה אינה מכורה אינו דין שלא תימכר"],[[0,"אימא סיפא אם מטבילין כלי טמא ליטהר יטבילו כלי טהור לכשיטמא","שיטהר ע\"י טבילה זו דכוותיה גבי נדרים אם מפר אדם בנדרי אשתו לאמר שחלו עליה תאמר שיפר קודם שחלו לכשיחולו שיהיו מופרין אלמא מיחל חיילי והשתא קשיא רישא לסיפא:"],[1,"אמרי רבנן לא קים להו בטעמא דר\"א וכו' והכי קאמרי ליה תיהוי כלי תיובתיך","מסיפא דברייתא דמכלי טמא יש תשובה להשיב דדייקינן מיניה דחיילי ולא בטלי ואי לא סבירא לך דחיילי אלא מעיקרא נמי לית בהו מששא הוי רישא דמקום תיובתיך דדייקינן מיניה דחיילי:"],[2,"כיון שזרען בקרקע טהורים","שעלו מטומאתן והזרעים טהורים:"],[2,"זרועים ועומדים","במחובר:"],[2,"לא כ\"ש","שלא יקבלו טומאה שכל המחובר לקרקע הרי הוא כקרקע אף בנדרים מופרים ועומדים לא כ\"ש דלא חיילי:"],[3,"ורבנן לא דרשי ק\"ו","בתמיה כי האי גוונא דדריש ר\"א בנדרים:"],[3,"יכול ימכור אדם את בתו כשהיא נערה","אין בין נערות לבגרות אלא ששה חדשים:"],[3,"מכורה כבר יוצאה","עכשיו כיון שהגיע ימי נערות כדאמרי' (קדושין ד.) ויצאה חנם אלו ימי נערות:"],[3,"אינו דין שלא תימכר","לאחר כשהיא נערה משום האי טעמא שאם מכורה כבר יוצאה עכשיו אף כאן נמי יהא יכול להפר לה קודם שנדרה הואיל ויפה כחו שאפי' לאחר שנדרה והגיע לכלל איסור יכול להפר לה ביום שמעו:"]],[]],[["אין בעלמא דרשי ק\"ו ושאני הכא דאמר קרא (במדבר ל, יד) אישה יקימנו ואישה יפרנו את שבא לכלל הקם בא לכלל הפר את שלא בא לכלל הקם לא בא לכלל הפר","\u0001מתני׳\u0002 הפרת נדרים כל היום יש בדבר להקל ולהחמיר","כיצד נדרה בלילי שבת יפר בלילי שבת וביום השבת עד שתחשך נדרה עם חשכה מפר עד שלא תחשך שאם חשכה ולא הפר אינו יכול להפר","\u0001גמ׳\u0002 תניא הפרת נדרים כל היום רבי יוסי בר' יהודה ור\"א בר' שמעון אמרו מעת לעת מאי טעמא דתנא קמא אמר קרא (במדבר ל, ו) ביום שמעו","ורבנן מאי טעמייהו דכתיב (במדבר ל, טו) מיום אל יום","ולת\"ק הא כתיב מיום אל יום איצטריך דאי ביום שמעו הוה אמינא ביממא אין בליליא לא כתיב מיום אל יום","ולמ\"ד מיום אל יום הא כתיב ביום שמעו איצטריך דאי כתיב מיום אל יום הוה אמינא מחד בשבא לחד בשבא ליפר לה כתיב ביום שמעו","א\"ר שמעון בן פזי אריב\"ל אין הלכה כאותו הזוג לוי סבר למיעבד כהני תנאי א\"ל רב הכי אמר חביבי אין הלכה כאותו הזוג","חייא בר רב שדי גירא ובדיק רבה ב\"ר הונא יתיב וקאים"],[[0,"אין בעלמא דרשי קל וחומר","כי האי גוונא כדאשכחן לגבי נערה וזרעים טמאים:"],[0,"ושאני הכא","להכי לא דרשי בנדרים קל וחומר דאמר קרא וכו' הלכך לא מצי מפר אלא לאחר שנדרה שבא לכלל הקם:"],[2,"מתני' נדרה בלילי שבת","יכול להפר לה כל אותו ליל שבת ויום שבת והוא הדין נמי כי נדרה במ\"ש שיפר כל אותו היום בא' בשבת אלא הא דנקיט לילי שבת משום דאשמועי' במה שאמרו הפרת נדרים כל היום כלילי שבת ויומו שהלילה הולך אחר היום כדכתיב ויהי ערב ויהי בקר יום אחד אבל לא ליום ולילה שאם נדרה ביום ולא הפר לה שוב אינו יכול להפר לה משתחשך שאין הפרת נדרים אלא אותו יום שנדרה ומשחשכה כבר נכנס יום אחר:"],[4,"גמ' מיום אל יום","משמע מאותה שעה ביום זה עד יום המחרת באותה שעה:"],[5,"ביממא אין","דיום שמעו משמע יממא ולא לילה להכי כתיב מיום אל יום דמשמע יום שלם:"],[6,"הא כתיב ביום שמעו","דמשמע אותו היום בלבד ולא למחר:"],[6,"דיאי מיום אל יום הוה משמע מחד בשבא לחדי בשבא","דהכי משמע מיום אל יום שכמוהו דהיינו שבוע שלם להכי כתיב ביום שמעו ביום אחד שלם מעל\"ע:"],[7,"אין הלכה כאותו הזוג","רבי יוסי ור\"א דאמרי מעת לעת:"],[8,"חייא בר רב הוה שדי גירא ובדיק","שלא היה מעיין כל כך בנדר אלא כמו שהיה עוסק במלאכתו שהיה יורה החץ מתוך כך בדיק ליה לנדר:"],[8,"יתיב וקאים","שלא היה יושב במקום אחד אלא עומד ויושב ובדיק ליה:"]],[]],[["תנן התם מפירין נדרים בשבת ונשאלין לנדרים שהן לצורך השבת איבעיא להו מפירין נדרים בשבת לצורך השבת או דלמא אפי' שלא לצורך","ת\"ש דתני רב זוטי דבי רב פפי אין מפירין נדרים אלא לצורך השבת אמר רב אשי הא לא תנן הכי נדרה עם חשיכה מפר לה עד שלא תחשך ואי אמרת לצורך השבת אין שלא לצורך השבת לא מאי איריא חשכה אפי' בתוך היום אינו יכול להפר דשלא לצורך","תנאי היא הפרת נדרים כל היום רבי יוסי ברבי יהודה ור\"א בר' שמעון אמרו מעת לעת","למ\"ד כל היום אין טפי לא אפילו שלא לצורך השבת מפר למאן דאמר מעת לעת לצורך השבת אין שלא לצורך השבת לא","ונשאלין לנדרים שהן לצורך השבת איבעיא להו כשלא היה להם פנאי או דלמא כשהיה להם פנאי ת\"ש דאיזדקיקו ליה רבנן לבריה דרב זוטרא בריה דרב זעירא אפילו בנדרים שהיה להם פנאי מבעוד יום","סבר רב יוסף למימר נשאלין נדרי' בשבת ביחיד מומחה אין בשלשה הדיוטות לא משום דמתחזי כדינא","א\"ל אביי כיון דסבירא לן אפי' מעומד אפי' בקרובים ואפי' בלילה לא מיתחזי כדינא","אמר ר' אבא אמר רב הונא אמר רב הלכה מפירין נדרים בלילה והא מתניתין היא נדרה בלילי שבת אלא אימא הלכה נשאלין בלילה","א\"ל ר' אבא לרב הונא אמר רב הכי א\"ל אישתיק אמר ליה אישתיק קא אמרת או שתי קאמרת","אמר רב איקא בר אבין איזדקיק ליה רב לרבה"],[[0,"תנן התם","במסכת שבת בפרק בתרא:"],[0,"מפירין נדרים בשבת","בעל לאשתו ואב לבתו:"],[0,"ונשאלין","לחכם:"],[0,"שהן לצורך השבת","כגון שנדרה מאכילה או מתכשיטין:"],[1,"נדרה עם חשיכה","משמע אפי' נדרים שלא לצורך השבת דמסתברא מילתא הואיל ונדרה בשבת עם חשיכה דלאו לצורך השבת נדרה דאי משום עונג אכילה ושתייה כבר אכלה מבעוד יום ואי משום תכשיטי שבת נדרה ההיא שעתא לאו זמן תכשיט הוא דהא משחשיכה רגילים להפשיט תכשיטי שבת אלא ודאי בנדרה שלא לצורך שבת קמיירי וקתני מפר לה עד שתחשך ואי אמרת שלא לצורך השבת אין מפירין בשבת מאי איריא דקתני דמשהחשיך אין יכול להפר אפי' כי נדרה בתוך השבת נמי אין יכול להפר שזה אינו לצורך השבת אלא דמדקתני דמפר לה עד שתחשך שמע מינה דמפירין אפי' שלא לצורך השבת וקשיא לרב דימי דאמר אין מפירין אלא לצורך השבת:"],[3,"למ\"ד כל היום אין טפי לא","הלכך אפי' שלא לצורך השבת מפר שאם אינו מפר עכשיו בשבת שוב אין יכול להפר:"],[3,"למ\"ד מעת לעת קסבר שלא לצורך השבת אין מפירין","כשנדרה בשבת מפני שיכול להפר אחר השבת:"],[4,"כשלא היה להן פנאי","לישאל עליהן מבעוד יום הוא דקאמר דנשאלין עליהן בשבת:"],[4,"או דלמא אפשר לישאל עליהן מבעוד יום","נמי נשאלין עליהן בשבת:"],[4,"דאיזדקיקו ליה רבנן","שנטפלו חכמים כולן להתיר לו בשבת ואפילו בנדרים שהיה לו אפשר לישאל עליהן מבעוד יום:"],[5,"ביחיד מומחה","לרבים הוא דנשאלין לו:"],[5,"אבל בג' לא","בין הדיוטות בין מומחין דכל בי תלתא מיתחזי כי דינא וקיימא לן דאין דנין בשבת:"],[6,"אפי' מעומד","כדאמר לעיל דרבה בר רב הונא הוה יתיב וקאים:"],[6,"","ואפילו בקרובין ואפילו בלילה לא מתחזי כי דינא:"],[7,"והא מתני' היא","דקתני בהדיא מפירין בלילי שבת ומאי קמ\"ל רבי אבא:"],[7,"אלא אימא נשאלין","נדרים לחכם בלילה:"],[8,"אמר רב הכי","דנשאלים נדרים בלילה:"],[8,"אמר ליה אישתיק","רב בשעה ששמע הדבר שתק:"],[8,"אמר ליה אישתיק קאמרת","כלומר מי קאמרת הוה אינש דאמרה קמיה דרב דנשאלין נדרים בשבת ושמע רב ושתק ומדאישתיק רב קאמרת דהכי סבירא ליה או דלמא הכי קאמרת דרב הוה שתי בההיא שעתא דאיתמר קמי' שמעתא ואת נפקת לברא מקמי דליפסוק למישתי ולא ידעת מאי מהדר:"]],[]],[["בקיטונא דבי רב עומד יחידי ובלילה","אמר רבה אמר רב נחמן הלכה נשאלין נדרים עומד יחידי ובלילה ובשבת ובקרובים ואפי' היה להן פנאי מבעוד יום","עומד והתניא ירד ר\"ג מן החמור ונתעטף וישב והתיר לו נדרו רבן גמליאל סבר פותחין בחרטה מיעקר נדר' בעינן ובעי עיוני אהכי ישב ורב נחמן סבר אין פותחין בחרטה ואפילו מעומד","א\"ל רבא לרב נחמן חזי מר האי מרבנן דאתא ממערבא ואמר איזדקיקו ליה רבנן לבריה דרב הונא בר אבין ושרו ליה נדריה ואמרו ליה זיל ובעי רחמי על נפשך דחטאת דתני רב דימי אחוה דרב ספרא כל הנודר אע\"פ שהוא מקיימו נקרא חוטא אמר רב זביד מאי קרא (דברים כג, כג) וכי תחדל לנדור לא יהיה בך חטא הא לא חדלת איכא חטא","תניא האומר לאשתו כל נדרים שתדורי אי אפשי שתדורי אין זה נדר לא אמר כלום יפה עשית ואין כמותך ואם לא נדרת מדירך אני דבריו קיימין","לא יאמר אדם לאשתו בשבת מופר ליכי בטיל ליכי כדרך שאומר לה בחול אלא אומר לה טלי ואכלי טלי ושתי והנדר בטל מאליו א\"ר יוחנן וצריך שיבטל בלבו","תניא בש\"א בשבת מבטל בלבו בחול מוציא בשפתיו ובה\"א אחד זה ואחד זה מבטל בלבו ואין צריך להוציא בשפתיו","א\"ר יוחנן חכם שאמר בלשון בעל ובעל שאמר בלשון חכם לא אמר כלום","דתני' (במדבר ל, ב) זה הדבר החכם מתיר ואין בעל מתיר שיכול ומה חכם שאין מפר מתיר בעל שמפר אינו דין שמתיר ת\"ל"],[[2,"והתניא","במסכת עירובין (דף סד:):"],[2,"ירד ר\"ג וישב כו'","אלמא דבעי ישיבה:"],[2,"ר\"נ סבר פותחין בחרטה","דצריך החכם לפתוח לו בתחלת הנדר ולהעמיד תחילת הנדר בטעות שיהא מתחרט על כך כדאמרינן אילו היו עשרה בני אדם שיפייסוך באותה שעה דהשתא עקר ליה לנדריה לגמרי דכמאן דלא הוי נדר דמי הלכך הואיל ולא אפשר בהיתר אי לאו דמיעקר נדרא בעי עיוני טפי למיעקרי' ואהכי ישב:"],[2,"ורב נחמן סבר אין פותחין בחרטה","ואי לא אמר בפירו' מיחריטנא שרינן ליה ולא בעי לעיוני ויכול להפר אפילו מעומד:"],[3,"ואמרו ליה זיל בעי רחמי אנפשיך","כך פתחו לו בחרטה:"],[3,"הלא לא חדלת","אלא נדרת אית בר חטא:"],[4,"אי אפשי שתידור לא אמר כלום","דאין הפרה בלשון הזה: ואם בא לקיימו ואמר לה יפה עשית שנדרת ואין כמותך אשה חשובה לפי שנדרת ואם לא נדרת אני הייתי מדירך שכל כך ישר בעיני:"],[4,"דבריו קיימין","דאין לך קיום גדול מזה:"],[5,"טלי ואכלי טלי ושתי","להכי נקט הכי משום דהוו דברים שיש בהם עינוי נפש וצרכי שבת נינהו:"],[5,"וצריך שיבטל בלבו","שיאמר בלבו מופר ליכי:"],[7,"חכם שאמר בלשון בעל","מופר ליך:"],[7,"ובעל שאמר בלשון חכם","מותר ליך:"]],[]],[["זה הדבר חכם מתיר ואין בעל מתיר תניא אידך זה הדבר בעל מפר ואין חכם מפר שיכול ומה בעל שאין מתיר מפר חכם שמתיר אינו דין שמפר ת\"ל זה הדבר בעל מפר ואין חכם מפר","נאמר כאן זה הדבר ונאמר להלן (ויקרא יז, ב) זה הדבר בשחוטי חוץ מה בשחוטי חוץ אהרן ובניו וכל ישראל אף פרשת נדרים אהרן ובניו וכל ישראל ומה כאן ראשי המטות אף להלן ראשי המטות","בפרשת נדרים למאי הלכתא אמר רב אחא בר יעקב להכשיר שלשה הדיוטות והא (במדבר ל, ב) ראשי המטות כתיב אמר רב חסדא ואיתימא ר' יוחנן ביחיד מומחה","ראשי המטות בשחוטי חוץ למאי הלכתא אמר רב ששת לומר שיש שאלה בהקדש","לב\"ש דאמר אין שאלה בהקדש ראשי המטות דכתיב בשחוטי חוץ למאי הלכתא ב\"ש לית להו גזירה שוה","זה הדבר בפרשת נדרים למאי כתיב לומר חכם מתיר ואין בעל מתיר בעל מפר ואין חכם מפר","זה הדבר בשחוטי חוץ למאי כתיב לומר על השחיטה חייב ואין חייב על המליקה","אלא לב\"ש להכשיר ג' הדיוטות מנלן נפקא להו מדרב אסי בר נתן","דכתיב (ויקרא כג, מד) וידבר משה את מועדי ה' אל בני ישראל והתניא רבי יוסי הגלילי אומר מועדי נאמרו ולא נאמרה שבת בראשית עמהן בן עזאי אומר מועדי נאמרו ולא נאמר פרשת נדרים עמהן","רב אסי בר נתן קשיא ליה הא מתניתא אתא לנהרדעא לקמיה דרב ששת ולא אשכחיה אתא אבתריה למחוזא א\"ל מועדי ה' נאמרו ולא נאמרה שבת בראשית עמהן","והא כתיב שבת עמהן ותו מועדי ה' נאמרו ולא נאמרה פרשת נדרים עמהן והא מסיטרא כתיבא א\"ל הכי קתני"],[[0,"זה הדבר אשר צוה ה'","דברים ככתבן דאין בעל מתיר דכתיב אם הפר יפר אותם אישה:"],[0,"ת\"ל זה הדבר","ואי אפשר לשנות בדבר וחכם מתיר כדכתיב אלה ראשי המטות וכתיב לא יחל דברו אבל ראשי המטות מוחלין לו ומסיים הברייתא נאמר כאן כו' ונאמר בשחוטי חוץ מה להלן דבר אל אהרן ואל בניו ואל כל בני ישראל דכולהו מיחייבי משום שחוטי חוץ:"],[1,"אף בפרשת נדירים כו'","ולקמן מפרש למאי הלכתא:"],[2,"להכשיר ג' הדיוטות","בהפרת נדרים דאהרן חד ובניו חד וכל ישראל הרי תלתא ומדכתיב בהו כל ישראל שמע מינה להכשיר שלשה הדיוטות:"],[2,"והא ראשי המטות כתיב","בהפרת נדרים דמשמע מומחין:"],[2,"[ביחיד מומחה]","להכשיר בהן יחיד מומחה לרבים:"],[3,"ראשי המטות בשחוטי חוץ למאי הלכתא","דהא אקשינן להו להפרת נדרים:"],[3,"לומר שיש שאלה בהקדש","דפרשת שחוטי חוץ שייכא לגבי הקדש וקמ\"ל ראשי המטות דנשאלין עליו דהקדש טעות אינו הקדש:"],[4,"אין שאלה בהקדש","דהקדש טעות הוי הקדש:"],[4,"ב\"ש לית להו ג\"ש","ולא הוה כתיב ראשי המטות בשחוטי חוץ דלא גמרינן ג\"ש: וקא מקשינן לב\"ש למאי הלכתא כתיב זה הדבר בשחוטי חוץ:"],[6,"ואינו חייב על המליקה","שאם מלק עוף בחוץ אינו חייב:"],[10,"והכתיב שבת עמהן","בסמוך לאותו פסוק וידבר משה את מועדי ה' בפרשת אמור אל הכהנים וכתיב לעיל מינה מלבד שבתות ה' וגו':"],[10,"והא","פרשת נדרים:"],[10,"מסיטרא כתיבא","בצד אותה הפרשה דפנחס כתיב פרשת נדרים:"]],[[1,"מה בשחוטי חוץ כו'","לקמי׳ מפ' לה:"],[2,"להכשיר ג׳ הדיוטי'","דחד ליכא למימר מדאצטריך קרא ראשי מטות ליחיד מומחה מכלל דהדיוטו׳ לא סגי בחד ומדאפיק לחד אוקמי׳ אתלתא כמו דין דבעי׳ שלשה:"],[3,"לומ׳ שיש שאלה בהקדש","שאם שחט קדשי׳ בחוץ ונשאל אהקדש מפטר מקרבן וכרת:"],[4,"ולב״ש דאמרי אין שאלה בהקדש","דאמרי בנזיר (ל:) דהקדש טעות הקדש. [וממילא] דאין שאלה דשאלה דנדר משוס דמשווי לנדר נדר טעות:"],[5,"זה הדנר דנדרי","כיון דלא גמרי ג״ש למאי הלכתא:"],[5,"חכם מתיר וכו'","ולר״י דלעיל (נדרים עז:) דכי נמי דרשי׳ ביה הך דרי׳ מיניה ג״ש דהוי מופנה מצד אחד גבי שחוטי חוץ:"],[10,"הא כתי׳ שבת","תחלת מועדות פ׳ פנחס (במדבר כח):"],[10,"והא מסיטרא כתי׳","בתר פרש׳ [המועדות בראשי] המטות:"]]],[["מועדי ה' צריכין קידוש ב\"ד שבת בראשית אין צריכה קידוש ב\"ד","מועדי ה' צריכין מומחה ואין פרשת נדרים צריכין מומחה אפי' בית דין הדיוטות","והא בפרשת נדרים ראשי המטות כתיב אמר רב חסדא ואיתימא רבי יוחנן ביחיד מומחה","א\"ר חנינא השותק על מנת למיקט מפר אפילו מכאן ועד י' ימים מתיב רבא אימתי אמרו מת הבעל נתרוקנה רשות לאב בזמן שלא שמע הבעל או ששמע ושתק או ששמע והפר ומת בו ביום אבל שמע וקיים או ששמע ושתק ומת ביום של אחריו אין יכול להפר","מאי לאו בשותק על מנת למיקט לא בשותק על מנת לקיים אי הכי היינו או שמע וקיים אלא בשותק סתם","מתיב רב חסדא חומר בהקם מבהפר ובהפר מבהקם חומר בהקם"],[[0,"צריכין קידוש","דכתיב (ויקרא כ״ג:ד׳) אשר תקראו אותם במועדם:"],[0,"שבת בראשית אין צריכה קידוש","דחיילא וקדשה מאליה:"],[3,"השותק על מנת למיקט","שאינו שותק כדי לקיים הנדר אלא שעושה כדי להקניטה ולהוכיחה כדי שלא תרגיל עוד בנדרים שהיא סבורה שהוא שותק על מנת לקיימו:"],[3,"אפי' מכאן עד י' ימים","יכול להפר הואיל ולא היה דעתו לקיים:"],[4,"מאי לאו בשותק על מגת למיקט","וכגון דאמר לחד דלמיקט עביד דכי מת ביום שלאחריו אין יכול להפר ותיובתא דרבי חנינא:"],[4,"לא בשותק על מגת לקיים","ולכך אינו יכול להפר:"],[4,"היינו או שמע וקיים","ותרי זימני למה לי:"],[4,"בשותק סתם","ולחומרא אזלינן:"]],[[0,"מועדי יי' צריכי' קידוש ב״ד","שצריכי׳ לקדש ניסן לעשות בו פסח בט״ו בו:"],[0,"ואין שבת בראשית צריכה קידוש","שאין צריך לקדש יום ראשו׳ לקדש בשביעי בו לשבת:"],[1,"מועדי יי׳ צריכים מומחי׳","כדכתי׳ (ויקרא כ״ג:ד׳) אלה מקראי קדש אשר תקראו אותם קרי ביה אתם משה ואהרן דמומחי׳ נינהו:"],[1,"","ואין נדרים צריכי׳ מומחין. ולהכי סמך פ׳ נדר׳ למועדי׳ לדרוש כן וע״כ תלתא הדיוטו׳ בעי׳ כדפי׳ (ע״א ד״ה להכשיר) מדאצטרי׳ ראשי המטו׳ ליחיד מומחה:"],[3,"השותק ע״מ למקט","שתצטער אשתו ובדעתו לבטל לה אחרי כן:"],[3,"אימתי [אמרו] מת הבעל כו'","היינו ברייתא דאייתינן ריש פרקין (לעיל נדרים סח.):"],[4,"מאי לאו","הא דתנן שמע ושתק ע׳׳מ למיקט וקתני דהוי שתיקה מעליא ומהשתא הוא לסמיך אדבסמוך דאי בעי\"מ לקיים היינו שמע וקיים:"],[4,"שותק לקיים","כמו לקיים בהדיא ואין יכול להפר:"]]],[["שהשתיקה מקיימת ואין שתיקה מבטלת קיים בלבו קיים הפר בלבו אינו מופר קיים אין יכול להפר הפר אין יכול לקיים קתני שהשתיקה מקיימת מאי לאו בשותק על מנת למיקט","לא בשותק על מנת לקיים היינו קיים בלבו קיים אלא בשותק סתם","אשכחן חומר בהקם מבהפר בהפר מבהקם מנא לן אר\"י נשאלין על ההקם ואין נשאלין על ההפר","מתיב רב כהנא (במדבר ל, טו) ואם החרש יחריש לה אישה וגו' בשותק על מנת למיקט הכתוב מדבר אתה אומר בשותק על מנת למיקט או אינו אלא בשותק על מנת לקיים","כשהוא אומר (במדבר ל, טו) כי החריש לה הרי בשותק על מנת לקיים הכתוב מדבר הא מה אני מקיים אם החרש יחריש לה אישה בשותק על מנת למיקט הכתוב מדבר תיובתא","ולוקים הא בשותק על מנת לקיים הא בשותק סתם קראי יתירי כתיבי","מתיב רבא נדרה עם חשכה מפר לה עד שלא חשכה שאם לא הפר וחשכה אינו יכול להפר אמאי להוי כשותק על מנת למיקט תיובתא","מתיב רב אשי יודע אני שיש נדרים אבל איני יודע שיש מפירין יפר יודע אני שיש מפירין אבל איני יודע שזה נדר ר\"מ אומר לא יפר וחכמים אומרים יפר","ואמאי ליהוי כשותק על מנת למיקט תיובתא","\u0001הדרן עלך נערה המאורסה\u0002","מתני׳ \u0001ואלו\u0002 נדרים שהוא מפר דברים שיש בהן ענוי נפש אם ארחץ ואם לא ארחץ אם אתקשט ואם לא אתקשט"],[[0,"קיים בלבו קיים הפר בלבו אינו מופר","והיינו חומר בהקם מבהפר:"],[0,"קיים אינו יכול להפר","אא\"כ נשאל לחכם על הקמתו:"],[0,"הפר אינו יכול לקיים","קתני מיהת שהשתיקה מקיימת וכו':"],[2,"נשאלין על ההקם","שאם קיים לה לנערה המאורסה אביה או בעלה והלך השני ונשאל לו על נדרה של זו ואח\"כ הלך זה שקיים ונשאל על הקמתו:"],[2,"ואין נשאלין על ההפר","אם הפר לה אחד מהן והלך חבירו ונשאל לחכם על חלקו אין זה שאלה לפי שאין נשאלין על נדר שאינו נדר כגון זה שמופר במקצת הוי נדר ואין נדר:"],[4,"כשהוא אומר","למעלה הימנו כי החריש לה הוי בשותק וכו':"],[4,"בשותק ע\"מ למיקט","וכתיב בההוא קרא והקים את כל נדריה דשוב אינו יכול להפר:"],[5,"קראי יתירי כתיבי","מדכתיב החרש יחריש כמה פעמים ש\"מ בשותק ע\"מ למיקט אינו מפר: ע\"א קראי כתיבי החרש יחריש וכי החריש הרי ג' חד בשותק ע\"מ לקיים וחד ע\"מ למיקט וחד בסתם:"],[7,"יודיע אני שיש נדר","הרי ששמע באשתו שנדרה ולא הפר לה ואמר לאחר מכן יודע אני שיש נדר שאשה נודרת אסורה במה שנדרה:"],[7,"אבל איני יודע שיש מפירין","דאפשר בתקנה לכך לא הפרתי לה:"],[7,"יפר","דכיון דלא הוה ידע שיש מפירין מאי ה\"ל למיעבד נעשה כמי שלא שמע:"],[7,"אבל איני יודע שזה נדיר","חשוב וצריך לבטלו:"],[7,"","ר\"מ אומר לא יפר -דכיון דידע דנדרה ויש מפירין כשימעה בעלמא דמי ואיבעי ליה למפר מעיקרא:"],[7,"וחכ\"א יפר","עכשיו דכיון דלא ידע מתחלה דהאי נדר צריך הפרה כמי ששמע עכשיו דמי ולא לכתחלה:"],[10,"ואלו נדרים שהוא מפר דברים שיש בהן ענוי נפש","כדכתיב לענות נפש אישה יקימנו ואישה יפרנו (במדבר ל׳:י״ד):"]],[[10,"מתני' ואלו נדרים שהוא מיפר","בין אב בין בעל:"],[10,"שיש בהן ענוי נפש","(כדקתני) כדכתיב וכל שבועת איסר לענות נפש:"],[10,"אם ארחץ אם לא ארחץ","מפרש בגמ' מאי קאמר:"]]],[["אמר רבי יוסי אין אלו נדרי ענוי נפש ואלו הן נדרי ענוי נפש אמרה קונם פירות העולם עלי הרי זה יכול להפר פירות מדינה זו עלי יביא לה ממדינה אחרת פירות חנווני זה עלי אינו יכול להפר ואם לא היתה פרנסתו אלא ממנו הרי זה יפר דברי רבי יוסי","\u0001גמ׳\u0002 נדרי ענוי נפש הוא דמפר שאין בהן ענוי נפש אינו מפר והא תניא (במדבר ל, יז) בין איש לאשתו בין אב לבתו מלמד שהבעל מפר נדרים שבינו לבינה","אמרי הלין והלין מפר מיהו ענוי נפש מפר לעולם אבל אין בהן ענוי נפש כדאיתה תחותיה הויא הפרה מכי מגרש לה חייל עלה נדרה בדברים שבינו לבינה שאין בהן ענוי נפש אבל יש בהן ענוי נפש לא חייל עליה נדרה","ודברים שאין בהן ענוי נפש כי מגרש לה חיילא עלה והא תנן ר' יוחנן בן נורי אומר יפר שמא יגרשנה ותהא אסורה לו אלמא כי מגרש לה ומפר לה מעיקרא הויא הפרה","אמרי הלין והלין הויא הפרה אלא נדרי ענוי נפש מפר בין לעצמו ובין לאחרים אין בהן ענוי נפש לעצמו מפר לאחרים אינו מפר והכי קתני אלו נדרים שהוא מפר בין לעצמו ובין לאחרים נדרים שיש בהן ענוי נפש","אם ארחץ היכי קאמר אילימא דאמרה קונם פירות עולם עלי אם ארחץ למה לה הפרה לא תרחץ ולא ליתסרן פירות עולם אלו עלה","ועוד בהא לימא ר' יוסי אין אלו נדרי ענוי נפש דלמא רחצה ואיתסרו פירות עולם עלה"],[[0,"אמר רבי יוסי וכו'","ובגמרא מפרש דאין ענוי נפש אלא כגון קונם שלא אוכל בשר ושלא אשתה יין וכדגרסינן במסכת כתובות בפרק המדיר לרבי יוסי ולרבנן דברים שאין בהן ענוי נפש כגון שנדרה שלא לאכול עמו בקערה דהיינו דברים שבינו לבינה בגמרא מפרש היאך מפירן בעל:"],[0,"פירות מדינה זו עלי","בקונם מפורש בברייתא דרבי חייא אם יש לו חלק בהן זהו ענוי נפש אין לו חלק בהן אין אלו ענוי נפש ויביא לה ממדינה אחרת:"],[0,"ואם לא היתה פרנסתו","של בעל אלא הימנו שהחנווני הזה מעלה לו מזונות הרי זה יפר דברי ר' יוסי דהיינו ענוי נפש:"],[1,"","גמ' מדקתני ואלו נדרים שמפר וקמפרש בהו ענוי נפש מכלל דשאין ענוי נפש כגון דברים שבינו לבינה אינו מיפר:"],[1,"והתניא","בספרי בין איש לאשתו בין אב לבתו בנעוריה מה ת\"ל אם לנדרים שיש בהן ענוי נפש הרי כבר נאמר לענות נפש אלא מלמד שהבעל מפר בנדרים שבינו לבינה:"],[2,"אמרי","הני והני בין נדרי ענוי נפש בין שבינו לבינה מפר:"],[2,"מיהו נדרי ענוי נפש מפר לעולם","אפילו לאחר שתצא מתחתיו שתתגרש או תתאלמן וה\"ק מתני' אלו נדרים שהוא מפר לעולם:"],[2,"כי מגרש לה או תתאלמן","דנפקא מרשותיה:"],[2,"חייל עלה","בנדרים שבינו לבינה אבל יש בהן כו' הש\"ס הוא דקא פשיט למילתא:"],[3,"ומי מצית אמרת דברים שאין בהן ענוי נפש כי מגרש לה דחיילי עלה והתנן","במתני' קונם שאני עושה לפיך כל מה שאני עושה להנאת פיך יהא עלי כקרבן:"],[3,"ר' יוחנן בן נורי אומר יפר דשמא יגרשנה ותהא אסורה לו","דבמה שנדרה השתא אין בדבריה כלום דאינה יכול' לאסור עליו מה שתקנו לו חכמים ממנה אבל אם יגרשנה מיד חל הנדר ותהא אסורה לחזור לו שהיא מודרת הנאה ממנו והיינו דברים שבינו לבינה וקא\"ר יוחנן בן נורי יפר אלמא דכי מפר והדר מגרש לה תו לא חייל עלה נדר:"],[4,"אמרי הלין והלין","בין יש בהן ענוי נפש ובין אין בהן ענוי נפש הויא להו הפרה לעולם אפי' לאחר שתתגרש אלא דנדרי ענוי נפש מופרין לעולם בין לעצמו בין לאחרים בין יגרשנה ויחזירנה בין תנשא לאחרים:"],[4,"לעצמו מפר","כשיגרשנה ויחזירנה אבל ניסת לאחרים חיילי עלה: וקא מהדר אליבא דרבנן היכי קתני דאמרה אם ארחץ:"],[5,"ר\"מ אומר לא יפר","דכיון דידע דנדרה ויש מפירין כשמיעה בעלמא דמ. ואיבעי ליה למפר מעיקרא:"],[5,"אילימא דאמרה קונם פירות וכו' למה לי הפרה","דכיון דלא אמרה קונם פירות עלי סתם אלא תליא נדרה בהנאה אמאי מצי מפר והא אפשר דלא הוי ענוי נפש דלא תרחץ ולא תתסר בפירות והשתא לא ס\"ל דרחיצה עצמה הוי ענוי נפש:"],[6,"ועוד","אי דקאמרה כה\"ג בהא לימא ר' יוסי אין אלו נדרי ענוי נפש כלל והא ודאי נדרי ענוי נפש הן:"]],[[0,"[אמר] ר' יוסי אין אלו נדרי ענוי נפש","בגמרא מפרש:"],[1,"מלמד שהבעל מפר דברים שבינו לבינה","אם נדרה שלא לשמשו:"],[2,"מפר לעולם","גם כי תתגרש [וה\"ק] אלו נדרים שהוא מפר [לה] הפרת עולם נדרים שיש בהן ענוי נפש:"],[3,"ר' יוחנן בן נורי אמר","מתני' היא בהאי פירקא (דף פה -) שנודרת קונם שאני עושה לפיך יפר שאם לא יפר שמא יגרשנה ותהא אסורה להחזיר שיחול הנדר דכל כמה שהיא תחתיו לא חל הנדר דאלומי אלמוה לשעבוד דבעל אלמא כי מפר לה מעיקרא הויא הפרה אחר הגירושין:"],[4,"אלא נדרי ענוי נפש מפר בין לעצמו","שהיא תחתיו בין לאחרים אחר שתתגרש ותנשא לאחרים אבל דברים שבינו לבינה לעצמו מפר לאחרים אינו מפר כלומר כל מה דשייך לעצמו הוי הפרתו הפרה בין כשהיא תחתיו ובין כשגירשה דאכתי הוי שפיר בינו לבינה כל כמה דלא נישאת לאחר הלכך הוי הפרתו הפרה כשמחזירה:"],[4,"","לאחרים אינו מפר כשניסת לאחר חל הנדר דהכי משמע קרא בין איש לאשתו בעוד האיש עם אשתו וגם כשגירשה הוי שפיר בין איש לאשתו שאם יחזירנה יהיה בינו לבינה שמותר הוא להחזירה הלכך אינו חל כלל אחר שגירשה ואע\"ג שמן הדין היה לנו לומר שיחול אחר הגירושין ויתבטל כשיחזירנה זה לא מצינו שאחר שחל שיחזור ויתבטל אבל אחר שניסת לאחר תו לא הוי בינו לבינה שאסור הוא להחזירה:"],[5,"היכי קאמרה","דה\"ל למימר קונם רחיצה עלי:"],[5,"אילימא דאמרה קונם פירות עלי אם ארחץ למה לי הפרה לא תרחץ","דמדקתני תנא שנדרה כך מפירות אם תרחץ ולא קתני שנדרה מרחיצה ש״מ דאי לאו דתלינהו בפירות נדר דרחיצה גופה לאו עינוי נפש הוא וא״כ לא תרחץ ועוד בהא לימא רבי יוסי אין אלו נדרי ענוי נפש דלמא רחצה [ואיתסרו] פירות עלה וקשה דמעיקרא פריך לת״ק לא תרחוץ [ולא ליתסרו פירות עלה] והשתא פריך איפכא וי״ל דמשמע ליה מדלא קתני רבי יוסי אומר לא יפר וקאמר אין אלו נדרי ענוי נפש לאורויי לך דבהאי נדר דאיירינן אפי' אם תעבור התנאי אין בנדר ענוי נפש והר״מ פי' דהש״ס סמיך אאם אתקשט דמתרצינן לה בהא דאמרה קונם פירות [אם אתקשט דאם לא תתקשט] קרו לה מנוולתא דה״נ אמר פרק המדיר (כתובות דף עא:) דהיכא דתלתה לקישוט בתשמיש המטה דהיכי תעביד לא תתקשט ולא תיאסר קרו לה מנוולתא הלכך נדר דקישוט הוי נדר דעינוי נפש:"]]],[["ואלא דאמרה קונם הנאת רחיצה עלי לעולם אם ארחץ משום הכי מיפר לה דהיכי תעביד תרחץ מתסרא הנאת רחיצה עלה לא תרחץ אית לה ניוולא ורבי יוסי סבר אפשר דלא רחצה ולניוול לא חיישינן","אי הכי ליתני הכי רבי יוסי אומר תנאי זה אין בו ענוי נפש","אלא דאמרה הנאת רחיצה עלי לעולם אם ארחץ היום ורבי יוסי סבר ניוול דחד יומא לא שמיה ניוול"],[[0,"אלא דאמרה קונם הנאת רחיצה עלי אם ארחץ","פעם אחת שיאסרו לה לעולם כל הנאת רחיצה כגון כיחול ופירכוס וסיכה שהן צרכי רחיצה ואף רחיצה עצמה:"],[0,"ואהכי מיפר דהיכי תעביד כו'","דקסברי רבנן דרחיצה היינו ענוי נפש:"],[0,"ור\"י סבר","אפשר בלא רחיצה ולניוול דרחיצה לא חיישינן ואהכי קאמר דאין אלו נדרי ענוי נפש:"],[1,"אי הכי","הואיל דאוקמת נדרה ברחיצה לרבי יוסי דלא חייש לניוול דרחיצה דליכא ענוי נפש:"],[1,"ליתני הכי ר' יוסי אומר תנאי זה אין בו ענוי נפש","דהא כל הנדר הזה אינו אלא על תנאי בתנאי שעוברת עוברת על הנדר דאי אפשר בשום ענין להיות בו ענוי נפש (הואיל) דניוול הוא לה ולא הוי ענוי נפש לר' יוסי ואמאי קנסיב לה בלשון ענוי נפש דקאמר אין אלו נדרי ענוי נפש מכלל דר' יוסי סבר איכא ענוי נפש בהאי נדרא במקצת:"],[2,"אלא","לעולם לרבי יוסי רחיצה נמי הויא ענוי נפש ומתניתין דהכא בהאי עסקינן. כגון דאמרה אם ארחץ היום דהיינו טעמא דרבי יוסי דאמר אין אלו נדרי ענוי נפש דאפשר דלא אתיא לידי ענוי נפש דלא רחצה היום ולא מיתסרא הנאת רחיצה עלה וליכא אלא ניוול דיומיה דמכאן ואילך רחצה כל אימת דבעיא והשתא ליכא למיפרך לר' יוסי ליתני תנאי זה דקאמר לר' יוסי ניוול רחיצה לזמן מרובה הוי נדרי ענוי נפש ולהכי קתני בלשון הנדר והיינו טעמא דלא פריך הכא כדפרכינן לעיל לר' יוסי דלמא רחצה היום ומיתסרא הנאת רחיצה עלה דר' יוסי חייש לניוול מרובה משום דהתם לא אמרה אלא אם ארחץ סתם ואיכא למיחש דדלמא רחצה אבל הכא דאמרה היום ותו לא ליכא למיחש לדלמא רחצה באותו היום והוא הדין דאפשר לאוקמה נמי דאמרה הכי בתירוץ זה קונם פירות עולם עלי אם ארחץ היום אלא משום דשבקה לההיא ואיירי בהנאת רחיצה מוקים זה נמי בהנאת רחיצה:"]],[[0,"אלא דאמרה הנאת רחיצה עלי לעולם אם ארחץ","פעם אחת דפעם ראשונה יכולה לרחוץ בהיתר:"],[0,"מיתסרא רחיצה עלה","וענוי נפש הוא דמהשתא סבר דרחיצה הוי ענוי נפש דמתחילה נמי דקאמר לא תרחץ מפרשי' למתניתין דתלה רחיצה בפירות דאי לאו הכי לא הוי ענוי:"],[0,"לא תרחוץ אית לה ניוול","כלומר ענוי נפש הוא ור' יוסי סבר אפשר דלא רחצה כלל גם אם רחצה פעם אחת ומיתסרא (בכלל) [בכל] רחיצה לניוול כהאי לא חייש דרחיצה לא הוי ענוי:"],[1,"ולתני הכי רבי יוסי אומר תנאי זה אין בו ענוי נפש","כיון שיש ענוי נפש בקיום התנאי שגם קודם שעברה התנאי היא נמנעת מרחיצה כדי שלא יחול עליה איסור רחיצה הלכך היה לו להזכיר התנאי [ולא הנדר] או לא היה לו לומר רק ר' יוסי אומר לא יפר:"],[2,"אלא דאמרה הנאת רחיצה עלי לעולם אם ארחץ היום","דלרבנן גם מניעה מלרחוץ היום ענוי הוא ומיפר:"],[2,"ור' יוסי ניוול דחד יומא לא שמיה ניוול","משמע דמניעות יום א' הוא דלא הוי עינוי אבל במניעת [עולם] הוי עינוי ולא יתכן דבפרק המדיר מוכח מיניה דלר' יוסי אמרי' רחיצה אין בה עינוי ותו דלקמן פריך ממילתא דהכא דר' יוסי אמילתא דלקמן [גוף כולו] לכ\"ש דאיכא צער ומאי פריך האמרת רבי יוסי לא אמר אלא ברחיצת יום אחד ואית דגרסי ורבי יוסי לניוול לא חייש [כלל אפילו היכא] דמיתסרא לעולם ברחיצה לא הוי ניוול דקים ליה להש\"ס דברחיצה ליכא ענוי לרבי יוסי כלל מדקאמר אין אלו נדרי עינוי נפש משמע שאפי' תעבור בתנאי אין ענוי נפש בנדר זה כלל והרב ר\"א ממיץ גרס ורבי יוסי ניוול דיומיה לא שמיה ניוול - כלומר לא חש התנא להזכיר ניוול דיומיה לכך לא אמר אין בתנאי ענוי נפש שאין זה חידוש דדבר פשוט הוא אלא גדולה מזאת השמיענו אין נדר יכול להיות של ענוי נפש:"]]],[["שנית אם ארחץ אם לא ארחץ היכי דמי אלימא דאמרה תיתסר הנאת רחיצה לעולם עלי אם לא ארחץ היום למה לה הפרה תתסחי אמר רב יהודה דאמרה הנאת רחיצה עלי לעולם אם לא ארחץ במי משרה","דכוותיה דקתני אם לא אתקשט אם לא אתקשט בנפט לכלוך הוא","אמר [רב יהודה] דאמרה הנאת רחיצה לעולם עלי אם ארחץ היום ושבועה שלא ארחץ הנאת קישוט עלי לעולם אם אתקשט היום ושבועה שלא אתקשט","א\"ל רבינא לרב אשי האי אלו נדרים ושבועות מיבעי ליה למיתני א\"ל תני אלו נדרים ושבועות ואיבעית אימא שבועות נמי היינו נדרים דתנן כנדרי רשעים נדר בנזיר ובקרבן ובשבועה","ואמרו רבנן רחיצה אית בה ענוי נפש כי לא רחצה ורמינהי אע\"פ שאסור בכולן אין ענוש כרת אלא באוכל ושותה ועושה מלאכה בלבד ואי אמרת כי לא רחצה איכא ענוי ביום הכיפורים כי רחץ ליחייב כרת","אמר רבא מענינא דקרא גבי יום הכיפורים דכתיב (ויקרא טז, כט) תענו את נפשותיכם מילתא דידע עינויא השתא רחיצה לא ידע עינויא השתא גבי נדרים דכתיב (במדבר ל, יד) כל נדר וכל שבועת אסר לענות נפש מילתא דאתיא ליה לידי ענוי וכי לא רחצה אתיא לידי ענוי","ורמי דרבי יוסי אדר' יוסי מעיין של בני העיר חייהן וחיי אחרים חייהן קודמין לחיי אחרים בהמתם [ובהמת אחרים בהמתם] קודמת לבהמת אחרים כביסתן וכביסת אחרים כביסתן קודמת לכביסת אחרים חיי אחרים וכביסתן חיי אחרים קודמין לכביסתן","רבי יוסי אומר כביסתן קודמת לחיי אחרים השתא כביסה אמר רבי יוסי יש בה צער"],[[0,"שנית אם ארחץ","זה דהוי ענוי נפש לרבי יוסי כדאית ליה ולרבנן כדאית להו:"],[0,"אם לא ארחץ דקתני היכי דמי (אילימא) דאמרה תיתסר הנאת רחיצה עלי לעולם אם לא ארחץ במי משרה","תרחץ איכא ניוול ואע\"ג דרחצה מיהו משום דאין המים יפים ויש להן ריח רע הויא ניוול ור' יוסי סבר תרחץ ואין בכך כלום דבההיא יומא לא שמיה ניוול:"],[1,"דכוותיה גבי קישוט","דקתני סיפא אם לא אתקשט דאמרה תיתסר עלי הנאת קישוט כגון כיחול ופירכוס אם לא אתקשט בנפט לכלוך הוא שהנפט מסריח:"],[2,"לעולם","כדאמר מעיקר' דאסרה הנאת רחיצה עלה לעולם ומתני' חדא קתני דהכי אמרה אם ארחץ [ושבועה שלא] ארחץ דאיתסר עלה רחיצה לגמרי אפי' בזימנא חדא ואי נמי דאמרה הנאת קישוט עלי לעולם כגון קישוט דבגדי צבעונין וקישוט בשמים אם אתקשט אפילו פעם אחת ושבועה שלא אתקשט כלל ורבי יוסי לטעמיה דלניוול לא חייש כלל וליכא ענוי נפש וליכא למיפרך נמי כדפרכינן לעיל דליתני תנאי זה אין בו ענוי נפש דהכא ליכא תנאי כלל מדאתיא שבועה אבתריה ועקרה לה:"],[4,"אע\"פ שאסור בכולן","בכל הני דאית בהו צד ענוי ברחיצה ובסיכה ובנעילת הסנדל ובתשמיש המטה:"],[4,"אינו חייב עליהן כרת אלא על האוכל ועל השותה והעושה בו מלאכה","דלא חייבה תורה אלא בהני דכתיבי בהדיא גבי יום הכיפורים דכתיב תענו את נפשותיכם משמע שהנפש יודעת הענוי וזהו ענוי אכילה ושתיה דרגיל בהו וכיון דלא אכיל ההוא יומא ידיעה עינויא:"],[5,"רחיצה לא ידיעה עינויא","דלאו כל יומא רגיל למירחץ והשתא נמי כי לא רחיץ לא הוי ניכר הענוי:"],[5,"אבל גבי נדר דכתיב לענות נפש","משמע שעתיד לענות והיינו נמי רחיצה דאתיא ליד ענוי נפש ואהכי מיפר לה:"],[6,"מעיין של בני העיר","שמושך והולך לעיר אחרת ואין בו אלא כדי סיפוק שתייתן של בני אותה העיר הרשות בידן לסותמו שלא ילך לאותה עיר אחרת שלמטה הימנה לפי שהמים שלהן הם והמים ברשותן חייהן קודמין לחיי אחרים: ואם יש בה כדי חייהן של אלו ושל אלו ואין בה להסתפק ממה שנשאר מאותו מעיין אלא כדי בהמתן של בני אותה העיר:"],[6,"כביסתן וכביסת אחרים","אם יש בו כדי חיותן וכדי בהמתן של בני אותה העיר ואין במה שנשאר במעיין אלא כדי כביסת בגדיהן של בני העיר:"],[6,"חיי אחרים וכביסתן","שיש לבני העיר ולבהמתן להשקות ממעין אחד ואין כביסה להם אלא זה ואף חיי אחרים תלויין בו ואין בו אלא כדי שיעור של אחד מהן:"],[6,"חיי אחרים קודמין לכביסתן","ויניחום לבני אותה עיר אחרת לחייהן ואל יכבסו בו בגדיהן:"],[7,"השתא כביסה","דבגדים קאמר ר' יוסי דאית ביה צערא ולהכי כביסת קודמת:"],[7,"גוף כולו מיבעיא","דאית ביה ענוי כשאינו רוחץ:"]],[[0,"שנית אם ארחץ אם לא ארחץ היכי דמי","שיחול עליה איסור [רחיצה] בנדר:"],[0,"אם לא ארחץ במי משרה","ולכך [יפר] שאם תרחץ איכא ניוול:"],[1,"דכוותי' שלא אתקשט בנפט לכלוך הוא","ואינו קרוי קישוט אלא אמר רבא תרתי קתני ולעולם כדשנין ושבועה שלא ארחץ ולא רצה לתרץ דאמר קונם שלא ארחץ דא\"כ היינו כמו רישא כי לא רחצה אפילו ביום אחד דהא בארחץ היום מוקמינן לה:"],[4,"ורמינהו אע\"פ שאסר בכולן","בתשמיש המטה בנעילת הסנדל ברחיצה וסיכה באכילה ושתיה אין ענוש כרת אלא על האכילה דהוי ענוי והוי בכלל כל הנפש אשר לא תעונה [ונכרתה] ואי אמרת דמניעת רחיצה הוי עינוי ארחיצה נמי לחייב ביה\"כ ותימה דבפרק בתרא דיומא (דף עד:) פריך וכ\"ת בענוי תשמיש הרי אומר תענו את נפשותיכם איזהו ענוי שיש בו [אבידת נפש] הוי אומר זה אכילה ושתיה וא\"כ רחיצה נמי נהי דמיקריא ענוי אין חייבין עליה ועוד קשה לה\"ר שמואל מאיוורא מאי דעתיה דהאי מקשה אלא לא מקרי רחיצה ענוי א\"כ אמאי מיתסרא דהתם נפקא לן איסורא מהאי קרא דענוי וי\"ל דודאי לא הוי ענוי מן התורה וקרא דענוי הוה אסמכתא בעלמא דאיקרי ענוי וכך - הוא למסקנא ' דהכא:"],[5,"מילתא דידע עינויא השתא רחיצה לא ידיע השתא","כלו' בו ביום דמניעת רחיצה אינה נכרת אלא לימים רבים:"],[5,"[דכתיב לענות נפש]","דמשמע להבא יהיה נדרי עינוי:"],[6,"ורמי דר' יוסי אדר' יוסי","דאמר רחיצה אין בה ענוי:"],[6,"מעיין של בני העיר חייהן וחיי אחרים","כגון בעיירות ששותין מאותה מעיין חייהן קודמין דדרשינן וחי אחיך עמך חייך קודמין:"],[6,"כביסתן","מקום כיבוסי בגדים כביסתן קודמת ומותרין לעכב המים עד שיכבסו רבי יוסי אומר כביסתן קודמת [לחיי אחרים] משום דאית בה צערא:"],[7,"השתא כביסה","של בגדים אמר ר' יוסי [יש בו צער גוף כולו לא כ\"ש - כיבוס] דבגדים אלימא ליה יותר מרחיצת גוף:"]]],[["גוף כולו לא כל שכן אמרי אין כביסה אלימא לר' יוסי דאמר שמואל האי ערבוביתא דרישא מתיא לידי עוירא ערבוביתא דמאני מתיא לידי שעמומיתא ערבוביתא דגופא מתיא לידי שיחני וכיבי","שלחו מתם הזהרו בערבוביתא הזהרו בחבורה הזהרו בבני עניים שמהן תצא תורה שנאמר (במדבר כד, ז) יזל מים מדליו שמהן תצא תורה","ומפני מה אין מצויין ת\"ח לצאת ת\"ח מבניהן אמר רב יוסף שלא יאמרו תורה ירושה היא להם רב ששת בריה דרב אידי אומר כדי שלא יתגדרו על הצבור מר זוטרא אומר מפני שהן מתגברין על הצבור רב אשי אומר משום דקרו לאינשי חמרי","רבינא אומר שאין מברכין בתורה תחלה דאמר רב יהודה אמר רב מאי דכתיב (ירמיהו ט, יא) מי האיש החכם ויבן את זאת דבר זה נשאל לחכמים ולנביאים ולא פירשוהו","עד שפירשו הקב\"ה בעצמו דכתיב (ירמיהו ט, יב) ויאמר ה' על עזבם את תורתי וגו' היינו לא שמעו בקולי היינו לא הלכו בה אמר רב יהודה אמר רב שאין מברכין בתורה תחלה","איסי בר יהודה לא אתא למתיבתא דר' יוסי תלתא יומי אשכחיה ורדימוס בר' יוסי א\"ל מאי טעמא לא אתי מר לבי מדרשא דאבא הא תלתא יומין א\"ל כי טעמיה דאבוך לא ידענא היכא איתאי א\"ל לימא מר מאי קא\"ל דלמא ידענא טעמיה א\"ל הא דתניא ר' יוסי אומר כביסתן קודמין לחיי אחרים קרא מנלן","א\"ל דכתיב (במדבר לה, ג) ומגרשיהם יהיו לבהמתם וגו' מאי חייתם אילימא חיה והלא חיה בכלל בהמה היא אלא מאי חייתם חיותא ממש פשיטא אלא לאו כביסה דהא איכא צערא דערבוביתא","א\"ר יוסי אין אלו נדרי עינוי נפש איבעיא להו לר' יוסי מהו שיפר משום דברים שבינו לבינה ת\"ש א\"ר יוסי אין אלו נדרי עינוי נפש אבל דברים שבינו לבינה הויין","דלמא לדידהו קאמר להו לדידי אפי' דברים שבינו לבינה לא הויין לדידכו דאמריתו הויין נדרי עינוי נפש אודו לי דאין אלו נדרי עינוי נפש","מאי רב אדא בר אהבה אומר מפר רב הונא אומר אין מפר"],[[0,"כביסת בגדיים אלימא ליה לר' יוסי","דאית ביה יותר מרחיצה:"],[0,"דאמר שמואל האי ערבוביתא דרישא","עפרורית שמתכנס לאדם בראשו שאינו רוחץ:"],[0,"מתיא ליה לידי עוירא","מסמא את עיניו:"],[0,"ערבוביתא דמאני","שנושא בגדים שאינו רוחצן עד ששחורין הרבה:"],[0,"לידי שעמומיתא","שגעון וזו שעמומיתא קשה מכולן:"],[0,"ערבוביתא דגופא","זוהמא הבאה על בשרו של אדם מחמת זיעה שאינו רוחץ:"],[1,"הזהרו בערבוביתא","בהנהו דפרשי':"],[1,"ושלא תלמדו תורה אלא בחבורה","שאין אדם מתפלפל אלא מתוך לימוד חבירו:"],[1,"והזהרו בבני עניים","שלא יהו קלים בעיניכם ללמדם תורה:"],[2,"ומפני מה תלמידי חכמים אין מצויין בו'","שאין הדבר מצוי:"],[2,"שלא יהו אומרים","בני אדם תורה ירישה היא להם ואין אנו נזקקין ללמוד תורה:"],[2,"שלא יתגדרו","שלא יתגדלו שלא ינהגו שררה כשיראו שהן ואבותם ובניהם תלמידי חכמים יתגדרו כמו הניחו לו אבותיו להתגדר בו (חולין דף ז.):"],[2,"מפני שהן מתגברין","דודאי כל מי שהוא ת\"ח ובנו ת\"ח ודאי מתגבר:"],[2,"דקרו לאינשי חמרי","שאין נוהגין להן כבוד ומבזין אותן מפני תורה שבהם:"],[3,"נצתה כמדבר מבלי יושב","ישיבה של ת\"ח:"],[3,"נשאל לחכמים","דכתיב מי האיש החכם לנביאים ומלאכי השרת דכתיב ואשר דבר פי ה' אליו ויגידה:"],[4,"שאין מברכין","כשמשכימין לתלמוד תורה ותלמידי חכמים בני תלמידי חכמים מתוך שהן זהירין לעסוק בתורה ורגילין בה אינן זהירין לברך כשפותחין לא מקיימא ברכתא [כדאמרינן בברכת התורה] נהיה אנחנו וצאצאינו מלומדי תורה:"],[5,"ורדימוס בר' יוסי","היינו ר' מנחם בר' יוסי דמיתקרי בנן של קדושים (פסחים קד.):"],[5,"טעמא לא ידענא","דאמר למילתיה שאיני יכול לעמוד על סוף דעתו:"],[6,"אמר ליה דכתיב","גבי לוים ולכל חייתם:"],[6,"אילימא חיה ממש","שמתפרנסת משם:"],[6,"והלא חיה בכלל בהמה","כדכתיב זאת החיה אשר תאכלו מכל הבהמה (ויקרא י״א:ב׳) והואיל דכתיב לבהמתם למה לי חייתם:"],[6,"[אלא לאו כביסה","הוי] חיותם ממש דכביסת בגדיהן היינו חיותם דאי לא מכבסי בגדיהן איכא צערא דחיותם היינו נמי ערבוביתא דאמר לעיל:"],[7,"איבעיא להו לרבי יוסי","דאמר שלא ארחץ שלא אתקשט אינם נדרי עינוי נפש ומשום נדרי עינוי נפש אינו מיפר:"],[7,"מהו שיפר משום דברים שבינו לבינה","שיהו מופרין לעצמו כדאמרן לעיל אבל אין בהן עינוי נפש מפר לעצמו משום דדברים שבינו לבינה היינו קישוט כל הגוף בין קישוט תכשיטין בין קישוט דהעברת שער באותו מקום דקישוט כל הגוף משמע:"],[8,"לדידכו דיאמריתו","דרחיצה הוי עינוי נפש כו' אלא דברים שבינו לבינה דהא לא נדרה אלא מאותו מקום:"],[9,"דיאמר שמואל האי ערבוביתא דרישא","עפרורית שמתכנס לאדם בראשו שאינו רוחץ:"],[9,"מאי","כלומר אכתי מיבעי לן אי מפר אי לא:"]],[[0,"ערבוביתא דרישא","שאינו מסרק ראשו תמיד מייתי לידי עוירא פירוש לידי סימוי עינים:"],[0,"דמאני","שאינו מכבס בגדיו תמיד מביאו לידי שעמום:"],[0,"דגופא","שאינו רוחץ תדיר:"],[0,"מתיא לידי שיחנא וכיבי","כלומר כיבי ושעמום קשה מכאב שחין דשחין יש לו רפואה ושעמום אין לו רפואה ומשום הכי אמר רבי יוסי דכביסה קודמת לחייהם אבל רחיצה אין בה צער כולי האי:"],[1,"הזהרו בערבוביתא","פירוש הזהרו בכביסה:"],[1,"הזהרו בחבורה","שתלמדו תורה בחבורה:"],[2,"ירושה היא להם","לתלמידי חכמים ואין אנו זקוקין ללומדה: כדי שלא יתגדרו על הצבור:"],[4,"שאין מברכין בתורה תחלה","כשהם משכימים ללמוד תורה שאין מברכין לעסוק בדברי תורה והערב נא ואשר בחר:"],[5,"טעמא דאבוך לא ידעינן","כלומר מה טעם הוא דכביסה היא קודמת לחיי אחרים:"],[6,"אלא מאי לכל חייתם חיותם ממש","והאיכא צער דחפיפותא שמי שאינו רוחץ חופף ומצטער:"],[7,"קונם פירות העולם עלי יפר","דהוי עינוי:"],[7,"פירות מדינה זה","לא הוי עינוי שיכול להביא ממדינה אחרת: פירות חנוני זה אינו יכול להפריש יכולה להסתפק מחנוני אחר:"],[7,"ואם לא היתה פרנסתו אלא ממנו","כלומר שאותו חנוני מקיף לה ורגיל אצלו מיפר דהוי עינוי נפש:"],[7,"לרבי יוסי מהו שיפר","ברחיצה וקישוט משום דברים שבינו לבינה ונפקא מיניה בהא דלא הוי עינוי נפש כדאמר לעיל דדברים שבינו לבינה לעצמו מיפר לאחרים אינו מיפר:"],[7,"אין אלו נדרי עינוי נפש","ומדלא קאמר סתם רבי יוסי אומר לא יפר שמע מינה משום עינוי נפש הוא דלא יפר אבל מיפר משום בינו לבינה:"]]],[["שלא מצינו שועל שמת בעפר פיר","תניא כוותיה דרב אדא בר אהבה דברים שיש בהן עינוי נפש מפר בין בינו לבינה בין בינה לבין אחרים שאין בהן עינוי נפש בינו לבינה מפר בינה לבין אחרים אינו מפר כיצד אמרה קונם פירות עלי ה\"ז יפר קונם שאיני עושה לפי אבא לפי אחיך לפי אביך לפי אחי ושלא אתן תבן לפני בהמתך ומים לפני בקרך אין יכול להפר","שלא אכחול שלא אפקוס ושלא אשמש מטתי יפר משום דברים שבינו לבינה","שלא אציע לך מטתך ושלא אמזוג לך את הכוס ושלא ארחץ לך פניך ידיך ורגליך אין צריך להפר","ר\"ג אומר יפר שנא' (במדבר ל, ג) לא יחל דברו דבר אחר לא יחל דברו מכאן לחכם שאין מתיר נדרי עצמו","מאן שמעינן דאמר שלא אכחול ושלא אפקוס דברים שבינו לבינה הויין ר' יוסי וקתני דמפר משום דברים שבינו לבינה","אמר מר ושלא אשמש מטתי יפר משום דברים שבינו לבינה היכי דמי אילימא דאמרה הנאת תשמישי עליך למה לי הפרה הא משועבדת ליה אלא באומרת הנאת תשמישך עלי וכרב כהנא","דאמר רב כהנא הנאת תשמישי עליך כופה ומשמשתו הנאת תשמישך עלי יפר שאין מאכילין את האדם דבר האסור לו","מאן תנא הא דתניא דברים המותרים ואחרים נהגו בהן איסור אי אתה רשאי לנהוג בהם היתר כדי לבטלן משום שנאמר לא יחל דברו דבר אחר לא יחל דברו מכאן לתלמיד חכם שאין מפר נדרי עצמו מני ר\"ג היא","בעא מיניה רבא מרב נחמן תשמיש המטה לרבנן עינוי נפש הוא או דברים שבינו לבינה אמר ליה תניתוה ונטולה אני מן היהודים"],[[0,"שלא מצינו שועל שמת בעפר פיר","בעפר חפירתו דהואיל שהוא רגיל בה ומתגדל באותה עפר כך לא מצינו אדם שניזוק במקום שרגיל לדוש . בתוכו שאין השער מזיקו:"],[1,"דברים שיש בהן עינוי נפש מפר בין בינו לבינה כו'","כלומר כשהוא מפר לה הוו מופרים לעולם בין כל זמן שהיא תחתיו ובין בינה לבין אחרים אפי' לאחר שתתגרש ותנשא לאחר:"],[1,"שאין בהן עינוי נפש בינה לבין אחרים אינו מפר","כדמפרש בריש פירקין דלאחר שגרשה תלין עליה:"],[1,"כיצד","איזהו נדרי עינוי נפש שיהיו מופרין לעולם אמרה קונם וכו':"],[1,"שאיני עושה לפי אבא","אינו לא נדרי עינוי נפש ולא דברים שבינו לבינה לכך אינו מפר לה:"],[2,"שלא אכחול ושלא אפקוס","דברים שבינו לבינה:"],[2,"שלא אשמש מטתך","כדמפרש לקמן:"],[3,"שלא אציע מטתך כו' אין צריד להפר","משום דרחמנא זכייה ליה בהני מלאכות:"],[4,"רשב\"ג אומר יפר משום שנאמר לא יחל דברו","דאורייתא דלאו כל כמינה לאפקועי שעבודו דבעל מינה והיינו כרב אדא בר אהבה דאמר דברים שבינו לבינה יפר:"],[4,"","דבר אחר לא יחל דברו מכאן אזהרה לחכם שלא יתיר נדריו לעצמו:"],[8,"דברים המותרים ואחרים שנהגו בו איסור אי אתה רשאי לנהוג כו' מני רשב\"ג היא","דאמר לעיל יפר לה הואיל ונהגה בו איסור והיא סבורה שתהא אסורה להציע לו מטתו ולמזוג כוס אינו רשאי לנהוג בהן היתר אא\"כ מפר לה:"],[8,"משום שנאמר לא יחל דברו","דאינו רשאי לבטל דבריה ולנהוג בהן היתר אא\"כ מפר לה:"],[9,"האומרת נטולה אני מן היהודים","מודרת אני מהם מתשמיש שלא יהנה שום יהודי ממנה:"]],[[0,"בעפר פיר","נוטריקון עפר פיר כגון פירא דכוורי (כתובות דף עט.) והכי קאמר לא יפר שבכך לא תתגנה עליו:"],[1,"שלא אתן תבן לפני בהמתך ולפני בקרך אינו יכול להפר","דלא הוי דברים שבינו לבינה דלא משעבדא ליה ותימה דבפרק אע\"פ אבל כופה ליתן תבן לפני בקרו ותירץ ריצב\"א דהתם מיירי שלא הכניסה לו שפחות והכא מיירי דהכניסה לו חמש שפחות דקאמר התם דיושבת בקתדר' דיקא נמי דקתני שלא אמזוג כוסך דלהכי כופה אותה אפילו אם הכניסה לו מאה שפחות ולא תנא שלא אניק דהא לא משתעבדא ליה כיון דהכניסה לו מאה שפחות:"],[4,"רבן גמליאל אומר יפר שנאמר לא יחל דברו","כלומר אף על גב דמשעבדא ליה צריך הפרה מדרבנן שלא תקל בנדרים ותעבור על לא יחל:"],[6,"למה לי הפרה","הא משעבדת לבעל:"],[8,"מאן תנא דברים המותרים ואחרים נהגו בהם איסור אי אתה רשאי לנהוג בהם היתר לבטלם רבן גמליאל","דאמר לעיל צריך להפר מדרבנן ואף על גב דמשעבדא ליה ולא חייל נדרה אפ\"ה צריך הפרה שלא תבא לעבור באיסור דלא יחל."],[9,"תשמיש לרבנן עינוי נפש הוי","כמו כיחול ופירכוס או דברים שבינו לבינה הוי ונפקא מיניה לדינא דלעיל דדברים שבינו לבינה אינו מיפר אלא לעצמו:"],[9,"נטולה אני מן היהודים","שאוסרת על עצמה אפילו תשמיש בעלה יפר ותהא נטולה מתשמיש היהודים אחרים אחר שיגרשנה:"]]],[["יפר חלקו ומשמשתו ותהא נטולה מן היהודים ואי אמרת נדר ענוי נפש הוי אמאי תהא נטולה מן היהודים ש\"מ דברים שבינו לבינה הויין","לרבנן תבעי לך משום דנטולה אני מן היהודים ר' יוסי קתני לה דאמר רב הונא כוליה פירקין רבי יוסי היא ממאי כיון דקתני ר' יוסי אומר אין אלו נדרי עינוי נפש למה ליה תו למיתנא הרי זה יפר דברי רבי יוסי שמע מינה מכאן ואילך רבי יוסי היא","אמר שמואל משמיה דלוי כל נדרים בעל מפר לאשתו חוץ מן הנאתי על פלוני שאינו מפר אבל הנאת פלוני עלי מפר","תנן פירות מדינה זו עלי יביא לה ממדינה אחרת אמר רב יוסף דקאמרה שתביא","ת\"ש פירות חנוני זה עלי אין יכול להפר הכא נמי דקא אמרה שתביא אתה","לא היתה פרנסתו אלא ממנו הרי זה יפר ואי אמרת דקא אמרה שתביא אתה אמאי יפר אלא מדסיפא דלא מייתי בעל הוי רישא דקא מייתא היא","אלא רישא אין יכול להפר ודקא מייתא היא"],[[0,"יפר חלקו","שתהא מותרת לו:"],[0,"ותהא נטולה מן היהודים","לכשתתגרש שתהא אסורה לעלמא:"],[0,"ואמאי תהא נטולה מן היהודים","כשמגרשה והאמר לעיל דברים שיש בהן עינוי נפש מפר בין לעצמו בין לאחרים אלא מדקתני ותהא נטולה מן היהודים דאינו יכול להפר ש\"מ משום דדברים שבינו לבינה הויין:"],[1,"לרבנן תבעי לך","אי עינוי נפש הוא אי דברים שבינו לבינה דמהכא ליכא למשמע מינה מידי אליבייהו:"],[1,"משום דנטולה אני מן היהודים רבי יוסי קתני לה דיאמר רב הונא כוליה פירקין","כולהו סתמי דמתניתין ר' יוסי תני להו:"],[1,"ממאי מדקתני ר' יוסי אומר אין אלו וכו' למה לי תו למיתני הרי זה יפר דברי ר' יוסי","דלא צריך דהא אכתי ליכא מאן דפליג ש\"מ דמכאן ואילך הוויין כולהו סתמי כרבי יוסי:"],[2,"כל נדרים","של עינוי נפש:"],[2,"חוץ מן הנאתי על פלוני שאינו מפר","דלא הוי לא נדרי עינוי נפש ולא דברים שבינו לבינה:"],[2,"אבל אמרה הנאת פלוגי עלי","שלא אהנה ממנו יפר דהוי ליה נדרי עינוי נפש:"],[3,"פירות מדינה זו עלי","היינו דומיא דהנאת פלוני עלי וקתני יביא לה ממדינה אחרת דאין יכול להפר:"],[3,"אמר רב יוסף","כי קתני יביא לה ממדינה אחרת דאמרה פירות מדינה זו שתביא מן השוק עלי אבל מה שמביאין לה אחרים או היא עצמה יכולה ליהנות מהן הלכך לא יפר דלא הוי עינוי כלל דלא אסרה לגמרי פירות המדינה עליה אלא אותן שיביא לה הוא אבל הנאת פירות עלי דקאסרה על נפשה לגמרי בין ע\"י עצמו בין ע\"י אחרים התם הוי עינוי הלכך יפר:"],[4,"פירות חנווני","היינו דומיא דהנאת פלוני עלי וקתני לא יפר:"],[4,"הכא נמי כו' והא מדקתני סיפא אם לא היתה פרנסתו אלא ממנו","שהבעל אינו רגיל ליקח אלא מאותו חנווני ולא מאחר לפי שאינו מאמינו וזה אינו מאמין אלא לבעל ולא לשלוחו:"],[5,"הרי זה יפר","ויביא לה ומדהך רישא דקא אתיא איהי תו לא אפשר לאוקומה שתביא אתה דאם איתא דקא מייתי הוא מיתוקמא כשתביא והדר קושיין לדוכתה:"],[5,"אלא","לעולם ודאי כדקאמרת רישא דקא מייתא היא ואפי' הכי לא קשיא ליה לשמואל דמתני' ר' יוסי היא:"],[6,"מאי אינו יכול להפר דקתני","ואע\"ג דקאמר פירות מדינה זו ופירות חנווני זה סתם לאו למשמע דאינו יפול להפר לגמרי אלא אעינוי נפש קאמר אבל מפר משום דברים שבינו לבינה שאפשר לעצמו ולא לאחרים והא דאמר שמואל משמיה דלוי דהנאת פלוני עלי מפר בין לעצמו בין לאחרים רבנן היא דעינוי נפש הוי: נ\"א אלא הא דקתני סיפא אם לא היתה פרנסתו אלא ממנו שהחנווני מהנהו לבעל בחנם הוי רישא דקתני פירות חנווני זה עלי כגון דקא מייתא היא כלומר דאורחיה דחנווני למיתב ליה בחנם ומאי איכא בין בבא דרישא לבבא דסיפא אלא בבא דסיפא הוי מן חנווני כדקתני אם לא היתה פרנסתו אלא ממנו ובבא דרישא לא רמיא פרנסתו עילויה אלא זימנא הוי דקא יהיב ליה מפירותיו וקאמר דאינו יכול להפר ואע\"ג דהוי כמאן דאמר הנאת פלוני עלי והוי תיובתא דשמואל דאמר הנאת פלוני עלי מפר והא דקא מייתא איהי לאו דוקא דהוא הדין דקמייתי בעל אלא איידי דסיפא נקט בשל בעל נקיט ברישא בדידה וקאמר כגון דאתיא איהי:"],[6,"אלא רישא","דקתני פירות חנווני זה עלי רבי יוסי היא כדקאמר לעיל:"]],[[0,"שמע מינה דברים שבינו לבינה הוי","דאי עינוי נפש הוה מיפר אף לאחרים:"],[1,"(ואכתי) לרבנן תבעי לך","ומתניתין דנטולה אני מן היהודים רבי יוסי קתני לה דלדידיה פשיטא דדברים שבינו לבינה הוו כדאמר לעיל:"],[1,"כוליה פרקין רבי יוסי","כל סתמות השנויות בפירקין ממילתא דרבי יוסי קתני להו:"],[1,"","למה לי תו למתני הרי זה יפר דברי רבי יוסי ש\"מ מכאן ואילך רבי יוסי היא:"],[2,"","כל נדרים של עינוי נפש חוץ מהנאתי על פלוני דלא הוי עינוי נפש אבל הנאת פלוני עלי מיפר דהוי עינוי נפש:"],[3,"תנן פירות מדינה עלי יביא כו'","ואינו יכול להפר ואמאי והא לא גרע מהנאת פלוני עלי:"],[3,"דאמרה ליה שתביא אתה","כלומר מתניתין מיירי דלא נדרה אלא מאותם שיביא הבעל דכיון דאיכא תקנה בהבאת אחרים ליכא עינוי דאפשר שאחרים יקנו ויתנו לה אבל שמואל מיירי שנדרה מפלוני לגמרי דהוא הדין דבמתניתין מצי למיתני תקנה דאחרים שיכולין לקנות לה אף מאותה העיר אלא אשמעינן רבותא דאף על ידי בעלה יכולה ליהנות על ידי פירות מדינה אחרת ולא הוי כנודרת הנאה מבעלה ורישא דאמרה קונם פירות העולם אע\"ג דאמרה שתביא אתה בפירות מדינה כיון דאינה יכולה ליהנות מבעלה משום מקום הוי עינוי נפש:"],[4,"ת\"ש מסיפא פירות חנוני זה אינו יכול להפר","ואמאי ליהוי כהנאת פלוני עלי:"],[4,"","ה\"נ שתביא אתה דהוי כהנאת אחרים:"],[5,"אם היתה פרנסתו כו'","ומדסיפא דמייתי בעל [דקתני] אם לא היה פרנסתו אלא ממנו פי' ולפי מאי דמוקמא פירות חנווני דאינו מיפר משום דאפשר בהנאת אחרים הך סיפא דקתני יפר ע\"כ [בדאי] אפשר [אלא] על ידי הנאת הבעל' שאין החנווני מקיף כ\"א לבעל גופיה ולא ימסרם לאחר ומדסיפא דמייתי בעל רישא דמייתי איהי פי' מדסיפא דאי אפשר להביא הפירות אלא באיסור על ידי בעל רישא נמי פירות מדינה עלי מיירי בהך גוונא בין יביאם הבעל בין יביאם אחר וליכא בהו אלא הבאה דאיסור וקתני אינו מיפר וקשיא לשמואל דמוקי לה כשתביא אתה ועל כרחך לא מיירי הכי דאם כן אמאי מפליג בזה הענין דאם אין פרנסתו אלא ממנו דמיירי דליכא הנאה דהיתר [נפלוג] וניתני בפירות דאי אפשר בהן הנאה דהיתר כגון שאמרה כל פירות שיובאו מאותה מדינה יפר והכי משמעות הלשון מדסיפא דמייתי בעל באיסור רישא דמייתי איהי באיסור ולחנם החליף הלשון וה\"ה דאסיפא גרידא בלא רישא מצי לאותובי כיון דבסיפא אי אפשר על ידי הבאת אחרים מאי איריא אין פרנסתו אלא ממנו כי נמי מתפרנס מאחרים יפר לשמואל אלא רישא דמייתי איהי באיסור כלומר שנדרה פירות מדינה לגמרי בין יביאם בעל בין יביאם אחר:"]]],[["ומתני' רבי יוסי היא דאמר רב הונא כוליה פרקין ר' יוסי היא ומאי אין יכול להפר משום עינוי נפש אבל מפר נדרים שבינו לבינה","אמר רב יהודה אמר שמואל נדרה משתי ככרות באחת מתענה ובאחת אין מתענה מתוך שהוא מפר למתענה מפר לשאינו מתענה ורב אסי אמר ר' יוחנן מפר למתענה ואין מפר לשאין מתענה","ואיכא דאמרי בעא מיניה רב אסי מרבי יוחנן נדרה משתי ככרות באחת מתענה ובאחת אין מתענה מהו א\"ל מפר למתענה ואין מפר לשאין מתענה","איתיביה האשה שנדרה בנזיר והיתה שותה יין ומטמאה למתים"],[[0,"כולה פירקא ר' יוסי קתני לה","ואנא נמי הכי קא אמינא דכי אמרה הנאת פלוני עלי מפר לעצמו אבל לא לאחרים כשאר דברים שבינו לבינה אבל לרבנן (אינו) יכול:"],[1,"באחת מתענה ובאחת אין מתענה","שאם לא תאכל האחת תהא רעיבה ואיכא עינוי ואם תאכל האחת תהא שביעה ושוב אין צריכה לשניה ולית בה בשניה משום עינוי:"],[1,"מתוך שמפר לאותה שמתענה","לפי שהוא עינוי נפש:"],[1,"מפר נמי לשאין מתענה","דבאותה הפרה שהפר למתענה עלתה הפרה נמי לאותה שאינה מתענה ומותרת בשניהן הואיל ונדרה ביחד ואית דמפרשי באחת מתענה שהאחת פת נקיה וטובה ואם אינה אוכלת ממנה איכא עינוי ובאחת אינה מתענה שהיא פת סובין ואינה חוששת ממנה וליכא עינוי אם לא תאכלנה אפי' הכי מותרת כשמפר למתענה:"],[1,"ואין מפר לשאינה מתענה","דאינו מופר בהפרת האחרת ויחזור ויפר לה אי אפשר לפי שאינן לא נדרי עינוי נפש ולא דברים שבינו לבינה אי נמי למ\"ד כל כי האי גוונא הוי דברים שבינו לבינה ואי קשיא הא קי\"ל נדר שהותר מקצתו הותר כולו הני מילי בהפרת חכם דעדיפא אבל בהפרת בעל לא אמרינן הכי:"]],[[0,"מתני' רבי יוסי היא","דמחמיר בהפרה אבל לרבנן מפר ושמואל כרבנן:"],[0,"דאמר רב הונא כולי פירקין רבי יוסי [היא","והא] דאייתי הכא דרב הונא [אינו מן הצורך] דהא סיומא דמלתא דרבי יוסי בהך בבא דפירות מדינה זו וחנווני זה אלא משום דעל בבא דלקמן דשאיני נהנה לבריות דצריך לשנויי לשמואל כי הכא כמו שאפרש לקמן:"],[0,"ומאי אינו יכול להפר משום עינוי נפש","נראה לפרש דהיינו שינויא אחרינא והוי כמו אי נמי וה\"פ אי נמי כרבנן מצית (למימר) לאוקומא מאי אינו יכול להפר דקאמר משום עינוי אבל מיפר הוא משום דברים שבינו לבינה קאמר וסיגנון תירוץ זה פירשתי פרק השואל (דף קא - ד\"ה סברוה) גבי ומקבל כחוכר דמי דהוה כמו אי נמי:"],[0,"","ע\"א מהרב רבי יונה נ\"ע מתני' רבי יוסי ושמואל כרבנן זהו עיקר ומאי אינו יכול להפר כו' האמת מסיק ואזיל להוציא מסברא דהוה ס\"ד דפירות חנווני אינו יכול להפר כלל והשתא מסיק דאפילו לר' יוסי אמת הוא דפירות חנווני עלי מפר מטעם דברים שבינו לבינה - ומיהו אין לתרץ בכך מילתא דשמואל דאמר הנאת פלוני עלי יפר דמה חושש בעל אם נדרה מאותו פלוני בשביל כך לא ימנע הבעל מלקחת ממנו כל מה שירצה ואשה תהנה מן הבעל בהיתר אבל כשנדרה פירות חנווני עלי לא יוכל הבעל ליקח ממנו ומיקרי בינו לבינה הר\"ר יונה נ\"ע:"],[1,"אמר רב יהודה אמר שמואל נדרה משתי ככרות באחת מתענה","פת נקיה ובאחת אין מתענה פת של שעורים מתוך שמפר למתענה מפר לשאינו מתענה ואין להקשות מהאי דנטולה אני מן היהודים יפר חלקו דלא אמר מפר לגמרי דהיינו משום דברים שבינה לבינה וגזירת הכתוב היא בין איש לאשתו דלדידיה לחודיה מפר אבל הכא כיון דמפר מקצתו הופר כולו והא דתנן לקמן (נדרים דף פז -) נדרה מתאנים וענבים והפר לתאנים לא הפר לענבים ולא אמר הפר מקצתו הפר כולו היינו משום שמפר סתם ומועלת הפרה לכל הנדר וצ\"ע אם נדרה מפלוני [דבר עינוי נפש וגם דבר שאינו עינוי נפש אם אמרי' מתוך שמפר לדבר שמתענה מפר נמי לשאינו מתענה או אינו] מפר לשאינו מתענה דאינו עינוי לה דלא אמר נדר שהופר מקצתו הופר כולו:"]]],[["הרי זו סופגת את הארבעים הפר לה בעלה והיא לא ידעה שהפר לה והיתה שותה יין ומיטמאה למתים אינה סופגת את הארבעים","ואי אמרת מפר למתענה ואין מפר לשאין מתענה דלמא מן יין דאית לה צערא הפר לה מן חרצן ומן זג לא הפר לה דהא לא אית לה צערא ותספוג את הארבעים","אמר רב יוסף אין נזירות לחצאין","א\"ל אביי הא קרבן לחצי נזירות איכא אלא אמר אביי אין נזירות לחצאין ואין קרבן לחצאין","מיתיבי האשה שנדרה בנזיר והפרישה בהמתה ואח\"כ הפר לה בעלה מביאה חטאת העוף ואינה מביאה עולת העוף ואי אמרת אין קרבן לחצי נזירות אמאי מביאה חטאת העוף","ואלא מאי יש קרבן לחצי נזירות שלש בהמות בעי לאתויי חטאת עולה ושלמים אלא לעולם אין קרבן לחצי נזירות וחטאת העוף דמתיא משום דחטאת על הספק","איתיביה האשה שנדרה בנזיר ונטמאת ואחר כך הפר לה בעלה מביאה חטאת העוף ואין מביאה עולת העוף ואי אמרת מפר למתענה ואין מפר לשאין מתענה"],[[0,"הפר לה בעלה והיא לא ידיעה כו'","ואמאי אינה סופגת אע\"ג דהפר לה תספוג דהא אמרינן במס' נזיר בפרק מי שאמר הריני נזיר אישה הפרם וה' יסלח לה באשה שהפר לה בעלה והיא לא ידעה הכתוב מדבר שהיא צריכה סליחה וכפרה דקסבר בעל מיעקר עקר:"],[1,"ואי אמרת מפר למתענה ואין מפר לשאינה מתענה","הא הוי נמי יין זג וחרצן דומיא דשתי ככרות דמתענה ליין ואין מתענה לזג וחרצן ואמאי קתני אינה סופגת את הארבעים דמשמע דמפר לה מכל וכל:"],[1,"דלמא מיין דאית לה צערא","דאית ביה משום עינוי הוא דהפר לה ולא מזג וחרצן אלא מדקתני אינה סופגת ש\"מ דמיפר לה נמי מזג וחרצן באותה הפרה דיין וקשיא לר' יוחנן:"],[2,"אין נזירות לחצאין","כדאמרינן בפ' הריני נזיר מן הגרוגרות (נזיר יא.) והכי הוא אומר הריני נזיר על מנת שאהא שותה יין ומטמא למתים הרי זה נזיר ואסור בכולן ומפרש בברייתא מפני שהתנה על מה שכתוב בתורה הכא נמי כי מפר לה בעלה מפר הכל:"],[3,"אמר ליה אביי הא קרבן לחצי נזירות איכא","בתמיה דאי אמר הריני חצי נזיר מביא חצי קרבן והא קיימא לן דלא אשכחן נזירות לפלגא אלא אי לרבנן הוי נזיר גמור ואסור מכל אי לר\"ש דפליג עלייהו לא הוי נזיר כלל דאמר אינו נזיר עד שיזיר מכולן ואי בעית למימר דיש קרבן לחצי נזירות אמינא נמי דיש נזירות לחצאין אפילו לענין מלקות ואיכא לפרוכיה נמי כדמעיקרא:"],[4,"מביאה חטאת העוף","היום ואינה צריכה להביא עולת העוף והתם מפרש בגמ' למאי הלכתא מביאה חטאת העוף טפי מחטאת בהמה:"],[4,"מביאה חטאת העוף","משום נזירות שעשתה קודם שהפר לה בעלה דכיון דמפר בעלה הוה כחצי נזירות דאילו כי מפר בעל אינו מפר אלא מה שעתיד לבא אבל מעיקרא אינו מפר דקודם הפרה כדקאי קאי והתם במסכת נזיר קא דייק דבעל מיגז גייז והיכא דהפר לה ונמצאו דברים שעשתה קודם הפרה שנטמאת למתים סופגת את הארבעים:"],[5,"וחטאת העוף","אהכי מתיא דמשום הכי אינה צריכה להביא ולא כלום דהא הפר לה אלא משום דר' אלעזר הקפר דאמר הנזיר מביא חטאת על שציער עצמו מן היין ומביאה זו חטאת העוף נמי:"],[5,"על הספק","דאמור ציערה עצמה מן היין מתחלת הנדר עד שעת הפרה דאשכחן דחטאת העוף אתיא נמי על הספק דיולדת שהפילה ואין ידוע מה הפילה אם חתיכה אם ולד מביאה חטאת העוף והואיל דאשכחן בעלמא דחטאת העוף באה על הספק הכא נמי מתיא היא חטאת העוף:"],[6,"האשה שנדרה בנזיר כו'","אהכי קאמר דלמא מיין דאית לה צערא ופו' דלא אפשר למידק כדדייקינן לעיל:"]],[[0,"האשה שנדרה כו' סופגת כו'","בנזיר (דף כא:) מפרש למאי איצטריך ובעי למיפשט מיניה דאפילו הפר לה שוב סופגת משום דבעל מיגז מהפרה ואילך ושעת ההפרה היתה נזירה ולוקה נמי לאחר שהיפר:"],[1,"דילמא מיין וכו'","דלמא לאו דוקא אלא כלומר ודאי לא הפר לה מחרצן וזג דאינו מיפר לשאינו מתענה ותספוג ארבעים:"],[2,"אין נזירות לחצאין","שהרי כשאמרה הריני נזירה קבלה עליה כל דיני נזירות ובאומרו מופר ליך הפר הכל דודאי לעיל כשאמר מופר ליך הואיל ופירשה שתי ככרות כשני נדרים דמו:"],[3,"הא קרבן לחצי נזירות איכא","בתמיה [כגון] שנדרה בנזירות ל' יום והפר לה בט\"ו ימים ה\"נ שתביא אחר ההפרה קרבנות נזיר טהור ואם נטמאת בתוך הנזירות קודם ההפרה שתביא קרבן טומאה דהכי משמע ליה לישנא דרב יוסף אין נזירות ולא אמר אין קרבן:"],[3,"אלא אמר אביי אין נזירות [ואין קרבן] לחצאין","כיון שהפר חצי נזירות נתבטל [כולה ואין] מביאה קרבן לחצי נזירות שמנתה הואיל שנתבטל מכאן ואילך אע\"ג דודאי לוקה בשתיית יין דקודם הפרה דאז היתה נזירה:"],[4,"","האשה שנדרה בנזיר ונטמאת והפרישה בהמה לאשם והפר לה בעלה מביאה חטאת העוף כדין נזיר טמא שמביא אשם ועולת העוף וחטאת העוף ואינה מביאה עולה כדמפרש טעמא וקשה לענין מה נקט והפרישה בהמתה ולמה לא פירש אחר שהפרישה מה יעשה בה:"],[4,"","ואי אמרת אין קרבן לחצי נזירות אמאי מביאה חטאת עוף אלא ש\"מ דיש קרבן לחצי נזירות וקשה להר\"מ דהא על כרחך אין קרבן לחצי נזירות דהא אמר פ\"ד דנזיר (דף כא:) האשה שנדרה בנזיר והפר לה בעלה אם שלו היתה בהמה תצא ותרעה בעדר ואם משלה היתה חטאת תמות עולה תקרב עולה שלמים יקרבו שלמים אלמא חטאת תמות דאין קרבן לחצי נזירות וליכא למימר דהתם בנזיר טהור והכא בנזיר טמא דבסמוך מדמינן לקרבנות טהור:"],[5,"אלא מאי יש קרבנות לחצי נזירות איבעי ליה לאיתויי חטאת עולה ושלמים","אם לא נטמאת והכא שנטמאה איבעי לאיתויי אשם עולת העוף וחטאת העוף:"],[5,"אלא אין קרבן לחצי נזירות וחטאת העוף דמייתי משום דחטאת העוף בא על ספק","אין קפידא אם מביאתו הלכך הזקיקו שתביא חטאת העוף כדאמר בגמרא פ\"ד דנזיר (דף כב.) כדרבי אלעזר הקפר דנזיר חוטא ובעי כפרה:"],[6,"מיתיבי האשה כו' ואין מביאה עולת העוף","דאין קרבנות לחצי נזירות דחטאת העוף דאתי על הספק מייתי כדמתרצינן ומשמע ליה דנזירות מופר מכאן ואילך לגמרי ומותרת לטמא למתים מדנקט ונטמאת ואחר כך הפר לה משום שאם נטמאת אחר שהפר אפילו חטאת העוף לא מייתי:"],[6,"","ואי אמרת כו' מטומאת מת [דלית לה צערא] לא הפר לה ותהא אסורה גם אחר ההפרה לטומאה ואי קשיא אמאי אין משני אין נזירות לחצאין כדמשנינן לעיל ושמא לעיל היינו גבי חרצן דאי אפשר לנזירות בלא איסור חרצן אבל אפשר לנזירות בלא איסור טומאה הלכך טומאה יש לו דין בפ\"ע והוי נזיר מטומאה לחודה אבל מ\"מ קשה מברייתא דלעיל דאיירי בטומאה מצי למיפרך:"]]],[["דלמא מיין דאית לה צערא הפר לה מטומאת מת דלית לה צערא לא הפר לה","אמרי טומאת מת נמי אית לה צערא דכתיב (קהלת ז, ב) והחי יתן אל לבו ותניא היה ר' מאיר אומר מאי דכתיב והחי יתן אל לבו דיספוד יספדון ליה דיבכון יבכון ליה דיקבר יקברוניה","\u0001מתני׳\u0002 קונם שאני נהנה לבריות אינו יכול להפר ויכולה היא ליהנות בלקט שכחה ובפאה","קונם כהנים לוים נהנים לי יטלו על כרחו כהנים אלו ולוים אלו נהנים לי יטלו אחרים","\u0001גמ׳\u0002 אלמא אפשר דמתזנה מדיליה מכלל דבעל לאו בכלל בריות הוא אימא סיפא יכולה ליהנות בלקט שכחה ופאה אבל מדבעל לא אכלה אלמא בעל בכלל בריות הוא","אמר עולא לעולם לאו בכלל בריות הוא ועוד אין יכול להפר מפני שיכולה ליהנות בלקט שכחה ופאה","רבא אמר לעולם בעל בכלל בריות הוא ומה טעם קאמר מה טעם אין יכול להפר מפני שיכולה ליהנות בלקט שכחה ופאה","ר\"נ אמר לעולם בעל לאו בכלל בריות הוא והכי קתני נתגרשה יכולה ליהנות בלקט שכחה ופאה"],[[0,"דלמא מיין דאית לה צערא הפר","מזג וחרצן לא הפר לה דהא אמרת אין נזירות לחצאין אהכי קאמר דמפר כולו ולא שייר אלא טומאת מת משום דלא אפשר ליה להפר לה ותייתי נמי עולת העוף דהא חייל עלה אכתי נזירות לענין טומאה:"],[1,"אמרי טומאת מת","ודאי הוי נמי בכלל הפרה משום דאית לה צערא כדכתיב קרא והחי יתן אל לבו והויא עינוי נפש:"],[1,"דיספוד יספדון ליה כו'","כלומר יספוד לאינשי כי היכי דיספדון ליה נמי והיינו והחי יתן אל לבו שישתדל לעשות עם אחרים כדי שיזכה ויעשה לו כמו כן ולעיל מיניה כתיב טוב ללכת אל בית אבל וגו':"],[2,"מתני' קונם שאני נהנה לבריות","קונם יהא עלי כל מה שאהנה מן הבריות:"],[2,"אינו יכול להפר ויכולה ליהנות מלקט שכחה ופאה","דלא של בריות הן אלא של הפקר:"],[4,"","גמ' מדקאמר דאין יכול להפר משמע דאין בנדר הזה עינוי נפש משום דיכולה להתפרנס משלו:"],[4,"אימא סיפא יכולה ליהנות בלקט שכחה ופיאה אבל מן הבעל לא אכלה","דאי אכלה מבעל היכי מותרת בלקט שכחה ופאה דהא לאו עניה היא:"],[5,"ה\"ג אמר עולא לעולם בעל לאו בכלל בריות הוא חדא ועוד קתני כו'","ואין יכול להפר דמתניתין אכ\"ע קמהדר דאין יכול להפר אליבא דכ\"ע משום דלאו נדרי עינוי נפש הויין ולאו דברים שבינו לבינה:"],[7,"רב נחמן אמר לעולם בעל לאו בכלל בריות","והאי דקאמר אין יכול להפר א\"צ להפר קאמר:"],[7,"ויכולה ליהנות בלקט כו'","משנתגרשה קאמר דהתם לא מציא לאיתהנויי מבעל:"]],[[1,"טומאת מת נמי אית לה צערא","אם תמנע מלטמא דהויא עינוי נפש:"],[2,"קונם שאני נהנה לבריות כו' לא יפר","דלא הוי עינוי נפש [וא\"כ] לשמואל דאמר קונם שאני נהנה לפלוני יפר ותי' לא יפר משום נדרי עינוי נפש אבל מיפר משום דברים שבינו לבינה ורבי יוסי היא כדתרצינן מפירות מדינה:"],[2,"ויכולה ליהנות בלקט שכחה ופאה","שאינו ממון כדאמרי' דאפי' טובת הנאה ליכא לבעלים דעזיבה כתיב בהו [דדוקא היכא דכתיב בהו] ונתת אית בהו טובת הנאה:"],[3,"","כהנים לוים [נהנים] משלו יתן לכהנים תרומתו דטובת הנאה אינה ממון:"],[3,"כהנים ולוים אלו יטלו אחרים","דטובת הנאה ממון ובגמ' פריך מרישא לסיפא:"],[4,"","אלמא מדקתני לא יפר בעל לאו בכלל בריות הוא ומותרת ליהנות ממנו לכך לא חשיב האי נדר לעינוי נפש דאי הוי בכלל בריות אין לך עינוי גדול מזה דמשמע ליה הא דקתני דמותרת בלקט לא הוי טעמא דרישא מדלא קתני מפני שמותרת אלא מילתא באפי נפשה הוא וא\"ת ובעל גופיה מתזן מן הבריות והוי פרנסתו מן החנוני דאמר לעיל (דאסורה) דיפר כדין עינוי נפש וי\"ל דלעיל איירי דאסרה בפירות חנוני שיהא של חנוני אע\"פ שאינו עתה שלו דומיא דפירות מדינה דרישא שאסרה במה שגדל במדינה אבל הכא מיירי שאסרה משל הבריות בעודו שלהם והואיל ובעל לאו בכלל בריות כשיבא לידו מותר אבל מן בעל לא אכלה מדלא קתני הותרה בהם:"],[5,"חדא ועוד קתני חדא דבעל אינו בכלל בריות ועוד כו'","כך מגי\"ה במשנתנו ולעולם בעל מכלל בריות הוא ומה טעם קאמר כו' קשה להר\"ם לעיל [דאמרינן] אם לא היתה פרנסתו אלא ממנו הרי זה יפר ואפילו כדין עינוי נפש ואמאי והרי יכולה ליהנות בלקט שכחה ותי' דלעיל מיירי בנדרה בימות הגשמים דליכא לקט ופאה:"],[7,"נתגרשה יכולה ליהנות בלקט","דאז בשעת גירושין הוי בעל בכלל בריות דנדרה הכי קונם שאני נהנה לכל אדם שיקראו אותם בריות בשעת הנאתי מהם וכי מיגרשה מיקרי בעל [בריות] ואע\"ג דהשתא לא מיתסר בעל לאחר גירושין מיתסר דהוי בכלל בריות לאסור בעלה על נפשה מהשתא ודמי להא דלקמן שדה שאני מוכר לך לכשאקחנה תקדיש הואיל ובידו להקדיש:"]]],[["איתיביה רבא לרב נחמן ובעל לאו בכלל בריות הוא והתנן נטולה אני מן היהודים יפר חלקו ותהא משמשתו ותהא נטולה מן היהודים","ואי אמרת בעל לאו בכלל בריות הוא נדרי עינוי נפש הן ויפר לה לעולם","אימא לך שאני הכא דמוכחא מלתא דעל היתרא קאסרה נפשה","יכולה ליהנות בלקט שכחה ופאה ולא קתני ובמעשר עני והתניא בברייתא ובמעשר עני","אמר רב יוסף ל\"ק הא רבי אליעזר הא רבנן דתנן ר\"א אומר אין אדם צריך לקרות שם על מעשר עני של דמאי"],[[0,"איתיביה רבא לרב נחמן","דאמר בעל לאו בכלל בריות הוא:"],[0,"ותהא נטולה מן היהודים","לכשתתגרש אסורה לינשא דהכי קאמרה ונטולה אני מן היהודים שלא אהנה מתשמישו דהיינו דומיא דהנאת תשמישך עלי וכדרב דאנר כל כי האי גוונא חייל נדרא והשתא מיהדר לאיתויי תיובתא דרב נחמן אי אמרת בשלמא בעל בכלל בריות הוא אהכי יפר חלקו דכי אמרה נטולה אני מן היהודים הוי בעל בכלל ואיתסר ליה מתשמיש והוו להו דברים שבינו לבינה ואהכי יפר כל זמן שהיא ברשותו ולכי נפקא מיניה חיילא נדרא כשאר דברים שבינו לבינה היינו דקתני ותהא נטולה מן היהודים לכשתצא מרשותו של זה שאינה יכולה לינשא לאחרים:"],[1,"אלא אי אמרת דבעל לא הוי בכלל בריות","ותפשוט דכי אמרה ונטולה אני מן היהודים דלא הוי בעל בכלל משום דאמרינן נדרי עינוי נפש הוא הואיל ולכשתתגרש או תתאלמן לא תוכל להנשא לכל אדם אהכי קרי ליה מהשתא עינוי נפש אע\"ג דהשתא כל זמן שהיא תחתיו אינו עינוי נפש דידה והואיל ועינוי נפש אינון אמאי יפר חלקו כשתצא מתחתיו חל הנדר ויפר לה לעולם כשאר נדרי עינוי נפש אלא ש\"מ דבעל בכלל בריות הוא ובנדרים שבינו לבינה הוא מאן דפריך הכי ס\"ל דאי לאו משום דבעל בכלל בריות הוא הוה אמינא דתשמיש עינוי נפש הוא ודלא כרב נחמן דאמר לעיל דתשמיש דברים שבינו לבינה הוא אליבא דר' יוסי:"],[2,"שאני הכא דמוכחא מילתא דעל היתרא קאסרא נפשה","כלומר אבעל קאסרה נפשה משום דלדידיה היא דמשתריא אבל לשאר עלמא לא אצטריכא למידר דלא קא משתריא בהכי דאשת איש היא:"],[3,"והתניא בברייתא","בהך פירקין דבמעשר עני מצי לאיתהנויי:"],[4,"ר' אליעזר אומר","הלוקח פירות מעם הארץ בשנה השלישית ובא לו להפריש מעשר עני אינו צריך לקרות עליו שם מעשר עני דלמעשר ראשון ליכא למיחש דליתי לוי ראיה דלא יהביה עם הארץ וליתיב ליה ולתרומה ליכא למיחש דלא נחשדו עמי הארץ על התרומה דאית בה עון מיתה ומעשר שני ליכא בשנה השלישית אבל בתרומת מעשר מיחייב דלא למדנו בה עון מיתה אלא מהיקשא דתרומה גדולה והואיל ולא כתיב בה בפירוש מיתה מש\"ה לא ציית ע\"ה [להיקשא] ולא מפריש ממנה תרומת מעשר ועל (אותו) מעשר עני אין צריך לקרות עליו אפילו שם מעשר:"]],[[1,"ואי אמרת בעל לאו בכלל בריות הוא","כי נדרה נטולה אני מן היהודים פירוש מתשמיש היהודים משאר יהודים קאמרה ואמאי צריך להפר חלקו והא לא אסרה נפשה אלא משאר יהודים:"],[2,"שאני הכא דמוכחא מילתא","שמתכוונת לאסור עצמה מתשמיש המותר לה דהיינו תשמיש הבעל ולכך צריך להפר חלקו ואית ספרים דגרסי ואי אמרת בעל לאו בכלל בריות הוא נטולה אני מן היהודים לאו תשמיש קאמרה שהרי אסורה בתשמישם בלא נדרה אלא ה\"ק נטולה הנאתי מפירות היהודים שלא אהנה מהם אף כי לא יהא שלהם וא\"כ הוי עינוי נפש דהא אמרינן (לעיל נדרים דף פב:) כשאין פרנסתו אלא ממנו יפר דהא ליכא למימר דאמרה קונם נהנה מן הבריות דוקא בעודו שלהם אבל ממה שיקח הבעל מהם תהנה א\"כ אמאי יפר בעודה תחתיו אפי' בינו לבינה לא הוי כיון שיכול הבעל להביא ממקום שירצה הר\"ר יונה נ\"ע ויפר לה לעולם אף אחר שיגרשנה ואמאי תהא נטולה מן היהודים אלא לאו בעל בכלל בריות הוא וכי אמרה נטולה אני מן היהודים מתשמיש קאמרה והוי בינו לבינה ומשני שאני הכא דמוכחא מילתא דהתורה אסרה וכי נמי בעל לאו בכלל בריות בעלמא הכא הוי בכלל בריות והכי משמע לשון נטולה מבעל ומהשאר יהודים וקשה לפי סברת המקשה תקשה כמו כן מאי תהא משמשתו דקתני כיון דלאו בתשמיש נדרה ושמא ה\"ק יפר ותעמוד תחתיו דלא תצא וקאי אמשנה ראשונה דאמר תצא:"],[4,"אין אדם צריך לקרות","אפי' שם דלהפרשה כלל למעשר עני של דמאי:"]]],[["וחכ\"א קורא שם ואין צריך להפריש מאי לאו למ\"ד ספקו טובל קסבר אית ליה טובת הנאה וכיון דאית ליה טובת הנאה לא מהניא","ולמאן דאמר [אינו] קורא שם קסבר ספקו אינו טובל וכל שספקו אינו טובל לית ליה טובת הנאה ושרי ליה לאיתהנויי","אמר ליה אביי דכ\"ע ספקו טובל ור' אליעזר ורבנן בהא קמיפלגי רבי אליעזר סבר לא נחשדו עמי הארץ על מעשר עני כיון דאילו מפקר נכסיה והוי עני ושקל ליה הוא לית ליה פסידא","ורבנן סברי נכסיה לא מפקר איניש דמירתת דלמא זכי בהו איניש אחרינא הלכך נחשדו","רבא אומר כאן במעשר עני המתחלק בתוך הבית דכתיבא ביה נתינה (דברים כו, יב) ונתת ללוי לגר וגו' מש\"ה אסור ליה לאיתהנויי","כאן במעשר עני המתחלק בתוך הגרנות כיון דכתיב ביה (דברים יד, כח) והנחת בשעריך שרי ליה לאיתהנויי","כהנים ולוים נהנין לי יטלו כו' אלמא טובת הנאה אינה ממון","אימא סיפא כהנים אלו ולוים אלו נהנין לי יטלו אחרים אבל להני לא אלמא טובת הנאה ממון","אמר רב הושעיא לא קשיא הא רבי והא ר' יוסי ב\"ר יהודה דתניא הגונב טבלו של חבירו ואכלו משלם לו דמי טבלו דברי רבי רבי יוסי בר\"י אומר אינו משלם אלא דמי חולין שבו מאי לאו בהא קמיפלגי"],[[0,"וחכ\"א קורא שם ואין צריך להפריש","אלא נותן עיניו בצד זה ואומר מכאן אני נוטל ואוכלו הוא בעצמו דהמוציא מחבירו עליו הראיה דאמר ישראל לעני אייתי ראיה דלא הפרישו עם הארץ ויהיבנא לך והכי אמרי' בפ' בתרא דסוטה (דף מח.) מעשר ראשון ומעשר עני המע\"ה:"],[0,"מאי לאו מ\"ד ספקו אינו טובל","דהיינו ר\"א אומר אינו צריך לקרות שם קסבר אפי' במעשר עני ודאי לית ליה טובת הנאה אלא כל עני שיבא תחילה יטלנו בעל כרחו והואיל דקיל כולי האי דאין ספקו טובל איכא נמי האי קילותא דאין בה טובת הנאה מה שאין כן בתרומה דספקה טבלה ויש בה טובת הנאה כדאמרינן אומר אדם לחבירו טול סלע זה ותן תרומתך לבן בתי כהן ולמאן דאמר קורא שם כולה מתניתין מתוקמא אליבא דחכמים:"],[2,"אמר ליה אביי דכולי עלמא ספקו טובל כו'","והלכך מתני' דלא קתני מעשר עני דברי הכל היא דכיון דספקו טובל בודאי אית ביה טובת הנאה ואהכי אינה יכולה ליהנות ממנו אבל ברייתא דקתני דאכלה נמי במעשר עני לא ר' אליעזר היא ולא רבנן:"],[2,"רבי אליעזר סבר לא נחשדו עמי הארץ על הפרשת מעשר עני","דודאי מפרשי ליה דלא איכפת להו דהדר קא אכלי ליה דכיון דאי בעי מפקר להו לנכסיה כו':"],[3,"רבנן סברי","ודאי נחשדו ולא מפרשי והא דאמר דמפקר להו לנכסיה הא לא עבדי דסבר אי מפקרנא לנכסאי דלמא אתי איניש אחרינא וזכי בהו הלכך נחשדו:"],[4,"במעשר עני המתחלק בתוך הבית","לאחר שהכניס תבואתי לאוצר ולא הפריש ממנה מעשר עני בגורן לפי שנאנס או שלא מנא עניים ליתן להם הלכך כי משכח עניים מיבעי ליה למיתב להו ובההוא מעשר כיון דכתיב ביה נתינה אית ביה טובת הנאה נמי כתרומה דכתיב בה נמי נתינה תתנו תרומה לכהן: והא דקתני בברייתא דיכולה ליהנות ממעשר עני באותו המתחלק בעוד שהוא בגורן דההוא כתיב ביה והנחת בשעריך דהיינו בשעת הגורן וההוא לית ביה טובת הנאה דהא איהו מנח ליה התם ושקיל ליה כל מאן דבעי ואהכי שריא לאיתהנויי ביה:"],[6,"יטלו בעל כרחו","מתנת כהונתם דלאו דידיה קא שקלי אלא דלהון אלמא מדקתני יטלו בעל כרחי דטובת הנאה דאית ליה אפשר למיתן לכהן וללוי אחר שנחזיק לו טובה לא הוי ממון ולא מיתחזי כמאן דמיתהני מיניה:"],[7,"אימא סיפא כו' יטלו אחרים","אבל להני מצי לעכב דלא שקלי אלמא טובת הנאה ממון:"],[8,"דרבי אומר","משלם לו דמי טבלו סבר דטובת הנאה שהיה שלו באותם מתנות בהאי טבל כהיה נותן לכהן שירצה הוי ממון ולהכי משלם לו דמי כולו:"]],[[0,"קורא שם","ומפרישו לעצמו דהמוציא מחבירו עליו הראיה דשמא עם הארץ הפרישו ואין צריך להפרישו - כלומר אין צריך לתתו לעני:"],[0,"ספקו אינו טובל","כלומר ספקו אינו אוסרו משום טבל דכי נמי לא הופרש מותר לאכול הימנו ולאו דוקא ספיקו דה\"ה ודאי דהוי כדאמרינן לקט ופאה [באם] לא הניחם אין טובלין התבואה וכיון דספקו אינו טובל ודאי לית ביה טובת הנאה ושרי לאיתהנוי ותימה מה ענין טובל אצל טובת הנאה דאילו דינא דטובת הנאה נפקא לן בפרק הזרוע (חולין קלא.) דהנך דכתיב בהו ונתת אית בהו טובת הנאה והכא לא כתיב ונתת ואומר הר\"ם דודאי טובל דכתיב ולא יחללו את קדשי בני ישראל אשר ירימו ודרשינן סנהדרין פג.) בעתידים לתרום הכתוב מדבר וכיון דכתיב בהו ירימו כמאן דכתיב ונתת דמי:"],[1,"ומ\"ס צריך לקרות שם וכו'","מתניתין כרבנן וברייתא כר\"א:"],[2,"דלמא דכ\"ע ספיקו טובל","אבל אינו טובל לא מצי למימר דא\"כ אמאי קורא שם:"],[2,"לא נחשדו וכו'","דאין לו הפסד:"],[4,"במעשר עני המתחלק בתוך הבית","דאמר בפרק הזרוע (חולין קלא.) מעשר עני המתחלק בתוך הבית יש בו טובת הנאה דכתיב ביה נתינה דכתיב ונתת ללוי לגר וליתום ולאלמנה ובבית הגרנות כתיב והנחת בשעריך והיינו כמו תעזוב ור\"ת מפרש דבספרי רמי להני קראי אהדדי כתוב אחד אומר ונתת וכתוב אחד אומר והנחת בימות החמה יניחנו בגורן אבל בימות הגשמים יניחנו בבית פן יטנף מן הגשמים הלכך אז מתחלק בבית ואז יש בו טובת הנאה לבעלים:"],[6,"","אלמא טובת הנאה אינה ממון אימא סיפא וכו':"],[7,"[דרבי סבר] טובת הנאה ממון","ולכך משלם דמי תרומה שבו ורישא רבי יוסי ברבי יהודה וסיפא רבי:"]]],[["דרבי סבר טובת הנאה ממון ורבי יוסי בר רבי יהודה סבר טובת הנאה אינה ממון","לא דכולי עלמא טובת הנאה אינה ממון אלא הכא במתנות שלא הורמו קא מיפלגי","ואי טובת הנאה אינה ממון מה לי הורמו מה לי לא הורמו","אלא היינו טעמא דרבי קנסוה רבנן לגנב כי היכי דלא ליגנוב ורבי יוסי בר ר' יהודה סבר קנסוה רבנן לבעל הבית כי היכי דלא לישהי לטיבליה","רבא אמר שאני תרומה דהיינו טעמא דיטלו על כרחו משום דתרומה לא חזיא אלא לכהנים וכיון דקא אתי למיסרא עלייהו שויא עפרא בעלמא","\u0001מתני׳\u0002 קונם שאיני עושה על פי אבא ועל פי אביך ועל פי אחי ועל פי אחיך אינו יכול להפר שאיני עושה על פיך אינו צריך להפר","רבי עקיבא אומר יפר שמא תעדיף עליו יותר מן הראוי לו","ר' יוחנן בן נורי אומר יפר שמא יגרשנה ותהי אסורה עליו","\u0001גמ׳\u0002 אמר שמואל הלכה כרבי יוחנן בן נורי למימרא דקסבר שמואל אדם מקדיש דבר שלא בא לעולם ורמינהי המקדיש מעשה ידי אשתו"],[[0,"ורבי יוסי סבר אינו ממון","ואינו משלם לו אלא דמי חולין שבו:"],[1,"במתנות שלא הורמו קמיפלגי","דרבי סבר כמי שלא הורמו דמיין ולהכי משלם לו דמי כולו ורבי יוסי סבר כמי שהורמו דמיין ואינו משלם אלא דמי חולין:"],[2,"ואי טובת הנאה אינה ממון","אפילו הוויין כמי שלא הורמו אינו משלם לו דמי טבלו דהא לא מפסיד ליה ולא מידי:"],[3,"אלא","לעולם אימא לך דאינו ממון והיינו טעמא דרבי אע\"ג דטובת הנאה אינה ממון אפי' הכי משלם לו דמי כולו משום דקנסו רבנן לגנב כי היכי דלא לגנוב:"],[3,"ור' יוסי סבר","אינו משלם אלא דמי חולין דחדא ועוד קאמר חדא דטובת הנאה אינה ממון ועוד לדבריך דאמרת טעמא משום קנס אדרבה לקנסיה לבעל הבית זה:"],[3,"כי היכי דלא לשהי לטיבליה","ולעולם אכתי רישא וסיפא דמתני' דקשיא אהדדי לא מיתרץ:"],[4,"רבא אמר","לעולם לא קשיא מתניתין וסיפא כדקתני דטובת הנאה ממון ורישא היינו טעמא דיטלו בעל כרחו:"],[4,"שאני תרומה משום דלא חזיא אלא לכהנים","וכיון דאתי למיסרה עלייהו שוייא לההוא תרומה כעפרא בעלמא והואיל וכעפרא הויא לא מיתחלי בטובת הנאה ולהכי שקלי לה בעל כרחו:"],[5,"מתני' קונם שאיני עושה על פי אבא כו' אין יכול להפר","דלא הוי לא נדרי עינוי נפש ולא דברים שבינו לבינה:"],[5,"שאיני עושה לפיך אין צריך להפר","דלא אמרה כלום דלאו כל כמינה לאפקועי לבעל מה דזכי ליה רחמנא:"],[6,"ר' עקיבא אומר יפר שמא תעדיף עליו יותר מן הראוי לו","כדאמרי' במס' כתובות בפ' אע\"פ (כתובות דף סד:) ומה היא עושה לו משקל חמש סלעים שתי ביהודה שהן עשר בגליל כו' והמותר שלה ואותה העדפה שמעדפת הואיל ושלה היא אוסרת עליו אם לא יפר:"],[7,"ר' יוחנן בן נורי אומר","להכי יפר שמא יגרשנה ותהא אסורה לחזור לו דאותה מלאכה שעושה אחר הגירושין כשתבא ברשותו אסור באותה מלאכה ובכל מעשה ידיה מגירושין ואילך וקסבר אדם אוסר דבר שלא בא לעולם כגון מעשה ידיה שעתידה לעשות דלכשתבא לעולם אחר גירושין אע\"פ שלא בא לרשותו בעת שבא לעולם דהא מגורשת היא לכשבאה ברשותו שתנשא לו שיהא אסור ורבי עקיבא סבר בהא מודינא לך דאדם אוסר דשלב\"ל היכא דהוי ברשותו לאלתר כשבא לעולם כגון העדפה אבל אין אדם אוסר דשלב\"ל אע\"פ שבא לעולם אינן ברשותו אלא לאחר זמן לכשיבא לרשותו חל עליהן איסור כדפירשתי:"]],[[1,"לא דכ\"ע אינה ממון והכא במתנות שלא הורמו קמיפלגי","ומפרש בירושלמי בטבלין שנפלו לו מבית אבי אמו כהן מיירי ורבי סבר כמו שהורמו דמיא ורבי יוסי ברבי יהודה סבר לאו כמו שהורמו דמיא:"],[2,"ואי טובת הנאה אינה ממון מה לי הורמו ומה לי לא הורמו","[ובקידושין (דף נח:) משני דמיירי בישראל] שנפלו לו [טבלים] מבית אבי אמו כהן וצ\"ע אמאי לא משני הכא כי התם וצריך לומר שהיה תופס אותו תירוץ לדוחק:"],[3,"אלא היינו טעמא דרבי דקסבר קנסו רבנן לגנב","דמש\"ה מיפטר דטובת הנאה אינה ממון ורבי יוסי ברבי יהודה סבר קנסו רבנן לבעל הבית ואי קשיא לימא דאינו ממון ומיפטר גנב מש\"ה לא קניס לגנב ויש לומר דהוי כמו תירוץ אחר [א\"נ] דלכ\"ע טובת הנאה [הוי] ממון ואפ\"ה מיפטר דקנסו לבעל הבית והא דקאמר רבי סבר דקנסו רבנן לגנב דסבירא ליה דלכ\"ע טובת הנאה אינה ממון וכך היא הסוגיא סוף פרק שני דקידושין איבעית אימא אינה ממון וטעמא דרבי דקנסו לגנב ואיבעית אימא ממון וטעמא דרבי יוסי דקנסו לבעה\"ב:"],[4,"רבא אמר","מתניתין אית ליה טובת הנאה ממון והיינו טעמא דמתניתין דיטלו בעל כרחו כיון דמיתסר עלייהו הוי עפרא בעלמא - כיון שאסר כל כהנים ולוים אם כן אסור הוא ליתן תרומותיו לשום כהן ואין לו בהם שום טובת הנאה שאינו יכול ליתנם לשום אדם ולעכבם לעצמו לא מצי ולכך אינו שלו ומותרין ליטלו בעל כרחו דהוי כמי שאינו שלו אבל בסיפא דמותר ליהנות למקצת כהנים הוי לו טובת הנאה בה ואסורין לבא וליטלה אותם כהנים שאסר:"],[5,"קונם שאני עושה לאבא ולאביך לא יפר","שאין זה נדר שבינו לבינה שאין לו לחוש אם יאסרו (חכמים) במעשה ידיה:"],[5,"על פיך אינו צריך להפר","דאשתעבדא ליה:"],[6,"יפר שמא תעדיף","ממה שפסקו חכמים דהיינו משקל חמש סלעים:"],[7,"","רבי יוחנן בן נורי אומר אף בשביל עיקר מעשה ידיה צריך להפר שמא יגרשנה:"],[8,"למימרא דסבר שמואל אדם מקדיש דבר שלא בא לעולם","שעדיין לא גירשה ועדיין לא באו לעולם מעשה ידיה שהיא מקדשה עתה:"]]],[["הרי זו עושה ואוכלת והמותר רבי מאיר אומר הקדש רבי יוחנן הסנדלר אומר חולין ואמר שמואל הלכה כר' יוחנן הסנדלר אלמא אין אדם מקדיש דבר שלא בא לעולם","וכי תימא כי קאמר הלכה כר' יוחנן בן נורי על העדפה הוא דקאמר","לימא הלכה כרבי יוחנן בן נורי בהעדפה אי נמי הלכה כת\"ק א\"נ (אין) הלכה כרבי עקיבא","אלא אמר רב יוסף שאני קונמות הואיל ואדם אוסר פירות חבירו עליו אוסר נמי דבר שלא בא לעולם עליו","אמר ליה אביי בשלמא אדם אוסר פירות חבירו עליו שהרי אדם אוסר פירותיו על חבירו אלא יאסור דבר שלא בא לעולם על חבירו שהרי אין אדם אוסר פירות חבירו על חבירו","אלא אמר רב הונא בריה דרב יהושע באומרת יקדשו ידי לעושיהן דידים הא איתנהו בעולם","וכי אמרה הכי קדשה והא משעבדן ידיה לבעל דאמרה לכי מגרשה השתא מיהת לא מגרשה וממאי דכי אמרה הכי מהניא"],[[0,"גמ' הרי זו עושה ואוכלת","לדברי הכל ואמרינן התם במסכת כתובות בפרק אע\"פ דבשאין מעלה לה מזונות קא מיירי ואמרי' עושה ואוכלת פשיטא דכיון דאין מעלה לה מזונות ודאי עושה ואוכלת דממאי מתפרנסת ואמרי' סיפא איצטריכא ליה למיתני:"],[0,"והמותר ר\"מ אומר הקדש","דקא סבר אע\"ג דמעשה ידיה אינו יכול להקדיש הואיל ואינה ניזונית משלו מ\"מ מותר על מזונותיה יכול להקדיש שיהא קדוש לאחר מיתתה:"],[0,"ור' יוחנן הסנדלר אומר חולין","דקסבר אין אדם יכול להקדיש דבר שלא בא לעולם לכשיבא לעולם לא יהא שלו אלא לאחר זמן:"],[0,"ואמר שמואל","התם הלכה כר' יוחנן הסנדלר דתקנו לה חכמים מעה כסף תחת מותר מעשה ידיה דאי במעלה לה אפילו בחייה שלו היא וקשיא דשמואל אדשמואל:"],[1,"וכי תימא כי אמר שמואל הלכה כרבי יוחנן בן נורי בהעדפה","כלומר הלכה כר' יוחנן ב\"נ דאמר יפר והיינו טעמא דיפר משום העדפה ולא משום גירושין:"],[2,"לימא הלכה כרבי עקיבא","דמוקי לטעמיה משום העדפה אלא מדקאמר הכי ש\"מ כדאשמעינן מעיקרא ולעולם קשיא דשמואל אדשמואל:"],[3,"אלא אמר רב יוסף","לעולם קסבר שמואל אין אדם מקדיש דבר שלא בא לעולם:"],[3,"ושאני קונמות וכו' ה\"ג אמר לי' בשלמא אדם אוסר פירות חבירו עליו","די\"ל יאסרו פירות חבירו עליו אלא יאסור דבר שלב\"ל על חבירו שבאיזה ענין יש בו כח לכך שהרי אין בו כח לאסור פירות חבירו על חבירו להכי נמי פירות מעשה ידיה הויין של בעל והיאך יכולה לאוסרן עליו הואיל שלא באו לעולם:"],[5,"יקדשו ידי לעושיהן","דידים איתנהו בעולם דהיינו אוסר פירות חבירו עליו:"],[6,"ומי מקדשן והא משעבדין ידיה לבעל","דהשתא הוי דומיא דאוסר פירות חבירו על חבירו:"],[6,"דאמרה לכי מגרשה","יקדשו דכל זמן שהיא ברשותו אינו אוסרתן ואהכי אי לא מיפר מהשתא חיילא קדושה עלייהו ואי מגרשה והדר נסיב לה מיתסרן עליו מעשה ידיה:"],[6,"וממאי דכי אמרה הכי מהני","ואע\"ג דאיתה תחת הבעל:"]],[[0,"עושה ואוכלת","שאין מעשה ידיה קדוש על פיו ובפרק אע״פ (כתובות דף נח:) מפרש שמעלה לה מזונות ולא מעלה לה מעה כסף ומעה כסף תחת מעשה ידיה ומזונות תחת מותר:"],[0,"והמותר ר\"מ אומר הקדש","[איכא] דאמר התם שאינו מעלה לה מעה כסף ולא מזונות ומותר אינו קדוש אלא לאחר מיתה ואיקדוש הכל ומותר ר\"ל מה שישתייר לאחר מיתה שלא אכלה:"],[0,"חולין","שאין אדם מקדיש דבר שלא בא לעולם:"],[1,"וכי תימא כי אמר שמואל הלכה כרבי יוחנן ב\"נ להעדפה","כלומר בדין דפליג רבי יוחנן ב\"נ במתניתין ארבי עקיבא דאמר שמא תעדיף דסבר דהעדפה הויא לעצמה ורבי יוחנן בן נורי סבר דהויא לעצמו ובהך דינא פסק שמואל כר' יוחנן אבל ודאי לא סבר דקדשה מעשה ידיה כלל דאין אדם מקדיש דבר שלא בא לעולם:"],[2,"","הכי גריס רבינו חננאל ולימא הלכה כרבי יוחנן בן נורי להעדפה וא\"נ אין הלכה כר' עקיבא א\"נ הלכה כת\"ק:"],[3,"שאני קונמות","דאמר רבי יוחנן דחיילי על דבר שלא בא לעולם מתוך שהוא תופס בדבר שאין סתם הקדש תופס דאדם אוסר בקונם פירות חבירו עליו ובלשון הקדש אינו אוסר דבר שלא בא לעולם משא\"כ בהקדש והשתא ס\"ד דה\"ה דתאסור האשה על בעלה בקונם כי היכי דאסרה על נפשה ואני מתיר:"],[4,"בשלמא אדם אוסר פירות חבירו","אע\"פ שאינו שלו שכן אדם אוסר פירותיו על חבירו וחבירו אינו ברשותו אע\"פ דדבר האסור אינו ברשותו יאסור דבר שלא בא לעולם על חבירו שכן אין אדם אוסר פירות חבירו על חבירו [וקונמות מעשה ידיה] דמתניתין אינה בעולם והיכי מצי אסרה לבעל:"],[5,"באומרת יקדשו ידי לעושיהם","דידים איתנהו בעולם הרי הוא כמי שהמלאכה נמי היה בעולם:"],[6,"והא משתעבדא ידיה לבעלה","ולא חל הקדש:"],[6,"דאמרה לכי מגרשה","יהיו קדושים - ומנא תימרא דכי אמרה הכי מהני - כיון דאילו השתא לית ליה רשות לאיקדושי היכי קדוש לקמיה ובפרק אע\"פ גרסינן ומי איכא מידי דמעיקרא לא קדוש והשתא קדוש:"]]],[["אמר ר' אילא ומה אילו אומר לחבירו שדה זו שאני מוכר לך לכשאקחנה ממך תקדיש מי לא קדשה","מתקיף לה ר' ירמיה מי דמי שדה זו שאני מוכר לך השתא בידיה היא אשה בידה להקדיש מעשה ידיה הא לא דמי אלא לאומר לחבירו שדה זו שמכרתי לך לכשאקחנה ממך תקדיש מי קדשה","מתקיף לה רב פפא מי דמי גבי זבינא פסיקא מילתייהו גבי אשה מי פסיקא מילתא הא לא דמי אלא לאומר לחבירו שדה זו שמשכנתי לך לכשאפדנה ממך תקדיש מי לא קדשה","מתקיף לה רב שישא בריה דרב אידי מי דמי שדה בידו לפדותו אשה בידה להתגרש הא לא דמיא אלא לאומר לחבירו שדה זו שמשכנתי לך לעשר שנים לכשאפדנה ממך תקדיש מי לא קדשה","מתקיף לה רב אשי מי דמי התם קיץ אשה מי אית לה קיצותא"],[[0,"אמר ר' אילא ומה אילו אומר לחברו שדה זו שאני מוכר לך","כלומר שעדיין היא בידו להקדישה שלא החלטתיה לך מכל וכל:"],[0,"לכשאקחנה ממך","לכשאחזור ואקחנה ממך תקדיש:"],[0,"מי לא קדישה","מי לא חייל שם קדושה עלה לכשיקחנה מזה הכא נמי גבי האי איתתא כי אמרה יקדשו ידי לעושיהן לאחר שתתגרש דודאי חיילא עלייהו שם קדושה:"],[1,"מי דמי","כלומר מי דמיא מילתא דאשה למילתיה דהאי גברא הכא האי גברא דמזבן שדה זו אכתי בידיה היא שעדיין לא מכרה ודיקא נמי דקתני שאני מוכר לך ולא קתני שמכרתי להכי יכול להקדישה לכשתחזור ותבא לרשותו:"],[1,"אבל","הא איתתא כי מקדשא מעשה ידיה כלום יש בידה שום כח והלכך אף על גב דאמר גבי מוכר שדה שיכול להקדישה לכשתבא לרשותו גבי אשה לא אמר:"],[1,"אלא","הא דאשה לא דמיא אלא לאומר כו' וכי היכי דהתם לא קדשה משום דלא קיימא שדה ברשותיה שהרי כבר מכרה הכא נמי לגבי הך איתתא לא קדשי מעשה ידיה:"],[2,"גבי זבינא פסיקא למילתייהו","דגופה לפירות בידא דלוקח:"],[2,"גבי אשה מי פסיקא מילתא","מי הויא גופה לבעל והתם גבי אשה דינא היא דתיקדוש:"],[2,"הא לא דמיא אלא לאומר לחבירו שדה זו שמשכנתי לך לכשאפדנה ממך תקדיש","דהתם אע\"ג דלא קדשה השתא קדשה לקמיה הכי נמי גבי אשה:"],[3,"שדה בידיו לפדותה","כל אימת דבעי אהכי מצי לאקדושה מהשתא:"],[3,"אשה בידיה להתגרש","בתמיה והואיל ואין בידה להתגרש לא חייל הקדש אמעשה ידיה לכשתתגרש:"],[3,"","הכא נמי גבי אשה אף על גב דאין בידה לגרש עצמה כי מיגרשא חיילא קדושה על מעשה ידיה:"],[3,"לאומר לחברו שדה זו שמשכנתי לך לעשר שנים וכו' מי לא קדישה","דהשתא אין בידו לפדותה עד עשר שנים ולכשיפדנה קדשה דחייל עלה קדושה מהשתא:"],[4,"התם קיץ","גבי שדה איכא זמן קצוב לעשר שנים וכיון דאיכא זמן קצוב דמי כאילו יש בידו לפדותה לאלתר:"],[4,"אשה מי יש לה קיצותא","לידע אימתי תתגרש:"]],[[0,"אמר רבי אילא","שינויא הוא ומה אילו האומר לחבירו וכו' מי לא קדשה - אם מכרה וחזר ולקחה ניחול הקדש שהרי עכשיו שלו וכי היכי דאילו אקדיש השתא קדשה כי נמי אמר דקדוש לקמיה קדוש:"],[1,"הא לא דמיא","מסקנא דקושיא היא [לרב הונא בריה דר\"י]:"],[1,"לכשאקחנה תקדיש דלא קדשה","למ\"ד אין אדם מקדיש דבר שלא בא לעולם:"],[2,"ומשני מי דמי גבי זבינא פסקה למילתייהו","שאין לו לא גוף ולא פירות ואין אדם מקדיש דבר שאינו שלו ולא דמי דהתם גופא ופירא בידא דלוקח הכא גופא בידה הוא:"],[2,"הא לא דמי","מסקנא דאתקפתא הוא:"],[2,"לאומר שדה שמשכנתי לך","סתם:"]]],[["אלא אמר רב אשי שאני קונמות דכי קדושת הגוף דמי וכדרבא","דאמר רבא הקדש חמץ ושחרור מפקיעין מידי שעבוד","אי הכי למה לי שמא יגרשנה תני ועוד שמא יגרשנה","\u0001מתני׳\u0002 נדרה אשתו וסבור שנדרה בתו נדרה בתו וסבור שנדרה אשתו נדרה בנזיר וסבור שנדרה בקרבן נדרה בקרבן וסבור שנדרה בנזיר נדרה מתאנים וסבור שנדרה מן הענבים נדרה מן הענבים וסבור שנדרה מן התאנים הרי זה יחזור ויפר:","\u0001גמ׳\u0002 למימרא דיניא אותה דוקא הוא"],[[0,"אלא אמר רב אשי","לעולם באומרת יקדשו ידי לעושיהם לכי מתגרשה כדתריצנא לעיל ודקאמרת כי אמרה הכי מי מהניא אין:"],[0,"שאני קונמות","היינו הקדש דכקדושת הגוף דמיא דלא סגי להו בפדיון כקדשי מזבח דאין להם פדיון:"],[1,"וכדרבא דאמר הקדש כו' מפקיעין מידי שעבוד","ובהקדש דקדושת הגוף קמיירי שאם היה לו בהמה ועשאה אפותיקי לבעל חובו ואחר כך הקדיש אפי' בסתם חיילא עלה קדושת הגוף ואין לו לבעל חובו שום שעבוד עלה והיינו טעמא משום דהוי דבר הראוי למזבח דחייל עלה קדושת הגוף אבל אם היו לו נכסים אחרים ששעבדן לבעל חובו ואח\"כ הקדישן לא פקע שיעבודיה דבעל חובו הואיל ואין בהן אלא קדושת בדק הבית דלאו קדושת הגוף הוא דאתי בעל חובו וגבי ליה מהקדש כדאמרינן במסכת ערכין (דף ע:) מוסיף עוד דינר ופודה כל הנכסים האלו דבאותו דינר יכול לפדות אפילו שוה אלף זוז והתם מפרש האי דינר מאי עבידתיה גזירה שמא יאמרו הקדש יוצא בלא פדיון וכי האי דאמרינן במסכת יבמות (דף סו:) ההיא איתתא דעיילא לגברא איצטלא דמילתא שכיב ובעיא למישקליה בכתובתה אתו יתמי פרסוה אמיתנא אמר רב קנייה מיתנא ואיתסר בהנאה ולית ליה פדיון לעולם:"],[1,"חמץ","ישראל שלוה מן העובד כוכבים ועשה (לו) חמצו אפותיקי לעובד כוכבים והרי הוא ברשותו של ישראל והגיע ו' שעות אותו ישראל חייב עליו בבל יראה ובבל ימצא דאתי איסור חמץ ומפקע לשעבודא דעובד כוכבים מיניה וחייב לבערו:"],[1,"וכן שחרור","עשה עבדו אפותיקי ושחררו מפקיעו מיד שעבודו של זה והא איתתא נמי מציא לאפקועי שעבודו של זה קודם שתתגרש:"],[2,"אי הכי למה לי שמא יגרשנה","דמוקמית למתניתין שמא יגרשנה אפי' לא רצה לגרשה ליקדשו מהשתא ומשני אלמוה רבנן לשעבודא דבעל דלא אתי הקדש ומפקע לשעבודא מיניה:"],[3,"מתני' נדרה אשתו וסבור שהיא בתו","כששמע הנדר היה סבור שבתו היא נדרה והפר לשם בתו:"],[3,"נדרה בקרבן","לשום נדר:"],[3,"בנזיר","כגון דאמרה הריני נזירה:"],[3,"הרי זה יחזור ויפר","אפי' לאחר זמן:"],[4,"גמ' למימרא","דהי אי דכתיב (במדבר ל׳:ו׳) כי הניא אביה אותה דוקא אותה הוא דבעינא שיהא מפר לשם אותה הנודרת דוקא:"]],[[0,"דקדושת הגוף נינהו","כקדושת מזבח לפי שאין להם פדיון:"],[1,"מפקיעין מידי שעבוד","דבעל:"],[1,"הקדש","עשה שורו אפותיקי והקדישו אין ב\"ח גובה הימנו ורבא אזיל לטעמיה דאמר בעל חוב מכאן ולהבא הוא גובה ועד זימניה ברשות הלוה הוא ומצי מקדיש ליה ופרש\"י דהיינו דוקא קדושת הגוף אבל קדושת דמים אמרינן בערכין דמוסיף עליו דינר ופודה כל הנכסים הללו ומפרש בערכין דמה\"ת אינה צריכה פדיון אלא שלא יאמרו הקדש יוצא בלא פדיון:"],[1,"חמץ","עשה חמצו אפותיקי לעובד כוכבים ועבר עליו הפסח אסור דחמצו של ישראל הוא וכן עשה עבדו אפותיקי ושחררו:"],[2,"למה לי שמא יגרשנה","השתא נמי קדישי:"],[2,"אלומיה אלמוה רבנן לשעבודיה דבעל","בעודה תחתיו דשויה כלוקח גמור ולא כמלוה ונראה דלא שייך למיפרך מי איכא מידי דהשתא לא קדיש [ולקמיה] קדוש דקדושיה מיתלא תליא ואי פקע שעבודו דבעל חיילא קדושה דעד השתא (לא) סבירא לן דקדושה אינו יכול להפקיע שום שעבוד הוי חשיב [למיפרך] כיון דלא קדשה השתא לא קדשה לקמיה אבל השתא דאמרי דמן הדין מפקעת אי לא דאלמוה אם כן לאחר שפקע יחול ההקדש:"],[3,"נדרה אשתו וסבור שנדרה בתו","והפר נדרה:"],[3,"בנזיר","שאמרה הרי עלי נזירות וסבור שנדרה בקרבן כלומר שאמרה דבר זה עלי כקרבן והפר הרי זה יחזור ויפר דכתיב יניא אותה ולא הפרה דטעות:"],[4,"למימרא דאותה דוקא","ולכך בעל צריך שידע נדר שנדרה:"]]],[["והא גבי קרעים דכתיב על על דכתיב (שמואל ב א, יב) על שאול ועל יהונתן בנו","ותניא אמרו לו מת אביו וקרע ואחר כך נמצא בנו יצא ידי קריעה","אמרי לא קשיא הא בסתם והא במפרש","והתניא אמרו לו מת אביו וקרע ואחר כך נמצא בנו לא יצא ידי קריעה אמרו לו מת לו מת וכסבור אביו הוא וקרע ואחר כך נמצא בנו יצא ידי קריעה","רב אשי אמר כאן בתוך כדי דבור כאן לאחר כדי דבור","הא דקאמרת יצא ידי קריעה שנמצא בנו בתוך כדי דבור הא דאמרת לא יצא ידי קריעה לאחר כדי דבור","והתניא מי שיש לו חולה בתוך ביתו ונתעלף וכמדומה שמת וקרע ואחר כך מת לא יצא ידי קריעה אמר ר' שמעון בן פזי אמר רבי יהושע בן לוי משום בר קפרא לא שנו אלא שמת לאחר כדי דיבור אבל בתוך כדי דיבור כדבור דמי","והילכתא תוך כדי דבור כדבור דמי חוץ ממגדף ועובד עבודת כוכבים ומקדש ומגרש","\u0001מתני׳\u0002 אמרה קונם תאנים וענבים אלו שאני טועמת קיים לתאנים כולו קיים הפר לתאנים אינו מופר עד שיפר אף לענבים אמרה קונם תאנה שאני טועמת וענבה שאני טועמת הרי אלו שני נדרים","\u0001גמ׳\u0002 מני מתניתין רבי ישמעאל דתניא (במדבר ל, יד) אישה יקימנו ואישה יפרנו אמרה קונם תאנים וענבים אלו שאני טועמת קיים לתאנים כולו קיים"],[[0,"והא גבי קרעים דכתיב על על","דמשמע שאם מתו לו שנים קרובים או שלשה שחייב לקרוע על כל אחד בפני עצמו:"],[0,"על שאול ועל יהונתן בנו ועל עם ה'","דהיינו פרטא:"],[1,"ותניא מת אביו וקרע ואח\"כ נמצא שהוא בנו","שמת ולא אביו יצא ידי קריעה דעל על לאו דוקא הכא נמי אותה לאו דוקא:"],[2,"כאן בסתם כאן במפרש","גבי קריעה שקרע סתם שלא על אביו ולא על בנו אבל במתניתין כגון שהפר בפירוש לשם בתו והלכך כיון דנמצא שאינו כך צריך להפר לשם אשתו שנדרה:"],[3,"והתניא לא יצא ידיי קריעה","וקשיין ברייתא אהדדי:"],[6,"והתניא","דמסייע לרב אשי:"],[7,"והלכתא תוך כדיי דבור","דהחוזר תוך כדי דבור כדבור דמי לכולהו מילי:"],[7,"חוץ ממגדף","מברך את השם:"],[7,"ועובד עבודת כוכבים","האומר לעבודת כוכבים אלי אתה דאדבור לחודיה חייב:"],[7,"והמקדש","אשה והמגרשה אע\"פ שחוזר בתוך כדי דבור אינה חזרה:"],[8,"מתני' אמרה קונם תאנים וענבים שאיני טועמת קיים לתאנים כל הנדר קיים","אף הענבים שאין יכול להפר שוב אפילו אענבים קסבר נדר שהוקם מקצתו הוקם כולו ובגמרא מפרש יקימנו יקים ממנו:"]],[[0,"","והא גבי קריעה דכתיב על שאול ועל יהונתן דמיניה שמעינן קריעה על כל מת ומת ותניא אמרו לו מת אביו וקרע ואחר כך אמרו שהוא בנו יצא ידי קריעה אף על פי שלא קרע על זה הכי נמי נימא דאותה לאו דוקא ואם הפר לאשתו ונמצאת בתו מופר:"],[2,"הא בסתם","הך קריעה דקרע סתם למי שהוא ומתניתין במפרש שאמר אני מיפר לאשתי:"],[4,"","רב אשי אמר כאן שנמצא שהוא בנו תוך כדי דבור של קריעה דהוי כאילו לא קרע אלא לאחר שמיעה והא דתניא לא יצא ידי קריעה שנמצא לאחר כדי דבור:"],[6,"והתניא","בניחותא:"],[6,"אמר רבי שמעון בן פזי","מהא עיקר ראייתו וק\"ק לישנא דוהא תניא דהא לא מייתי מידי אלא ממילתא דרבי שמעון בן פזי:"],[7,"והלכתא תוך כדי דבור כדבור דמי","פירש ה\"ר אליעזר לא ידענא מנין לו ופירש דמדרבנן הוא כדי שישיב אדם וישאל בהפסק ממכרו ולא יפסיד וקשה דהא גבי דינין דאורייתא הוא כגון גבי מנחת חיטין מן השעורין וגבי שבועת העדות אמרינן ליה וצ\"ל דהוי דאורייתא:"],[7,"מגדף ועובד עבודת כוכבים","אפילו חוזר בו תוך כדי דבור קטלינן ליה ומקדש אשה ואחר כך חוזר בו וכן מגרש ואחר כך מבטל הגט לאו כל כמיניה:"],[8,"קיים לחצאין קיים","דדרשינן בגמרא יקימנו יקים ממנו (הפר ממנו) הפר לחצאין אינו מופר כלל דהפרה במקצת לא הוי הפרה ואע\"ג דאמר נדר שהותר מקצתו הותר כולו שאני בין הפרה להתרת חכם:"],[8,"הרי אלו שני נדרים","אם קיים לענבים לא קיים לתאנים:"],[9,"מני מתניתין רבי ישמעאל היא דתניא וכו' קיים [לתאנים] כולו קיים","דהכי משמע יקימנו יקים ממנו מדלא כתיב יקיים וכתיב יקימנו דרשינן מלפניו ולאחריו:"]]],[["הפר לתאנים אינו מופר עד שיפר אף לענבים דברי רבי ישמעאל רבי עקיבא אומר הרי הוא אומר אישה יקימנו ואישה יפרנו מה יקימנו ממנו אף יפרנו ממנו ורבי ישמעאל מי כתיב יפר ממנו ורבי עקיבא מקיש הפרה להקמה מה הקמה ממנו אף הפרה ממנו","אמר ר' חייא בר אבא אמר רבי יוחנן זו דברי רבי ישמעאל ור' עקיבא אבל חכמים אומרים מקיש הקמה להפרה מה הפרה מה שהפר הפר אף הקמה מה שקיים קיים","אמרה קונם תאנה אמר רבא מתני' רבי שמעון היא דאמר עד שיאמר שבועה לכל אחד ואחד","\u0001מתני׳\u0002 יודע אני שיש נדרים אבל איני יודע שיש מפירין יפר יודע אני שיש מפירין אבל איני יודע שזה נדר ר' מאיר אומר לא יפר וחכמים אומרים יפר","\u0001גמ׳\u0002 ורמינהו (במדבר לה, כג) בלא ראות פרט לסומא דברי רבי יהודה רבי מאיר אומר לרבות את הסומא"],[[0,"הפר לתאנים אינו מופר","קסבר הפרה במקצת לאו שמה הפרה עד שיפר אף לענבים:"],[0,"קונם תאנה זו שאיני טועמת וענבה זו שאיני טועמת הרי אלו שני נדרים","הואיל וחילקה טעימה בינתים שאם קיים לענבים לא קיים לתאנים וחייב עליהן שני לאוין:"],[0,"גמ' אף יפרנו ממנו","ואם הפר למקצתו הפר כולו:"],[0,"ולר\"ע רבי ישמעאל קמהדר גבי יפרנו מי כתיב יפר ממנו","גבי הקמה איכא למדרש הכי דהא כתיב יקימנו לשון יקים ממנו (דלא שויוה רבנן למימר דהקמה עיקר): זו דברי ר' ישמעאל ור\"ע: דתרווייהו מודו בהקמה אבל חכמים אומרים מקיש הקמה להפרה מה הפרה במקצת מה שהפר לא הופר דהא לא כתיב יפר ממנו אף הקמה מה שקיים לא קיים אע\"ג דאיכא למידרש יקים ממנו [דלא שויוה רבנן למימר דהקמה עיקר]:"],[2,"אמר רבא","מתני' דקא משוי חילוק בין קונם תאנים וענבים שאני טועמת להיכא דאמרה קונם תאנה שאני טועמת וענבה שאני טועמת לחייבה שני לאוין משום הלשון ר\"ש היא דאמר (שבועות דף לו:) היכא דתבעוהו ה' בני אדם ואמר שבועה כאיני חייב לא לך ולא לך שאם נשבע לשקר אינו חייב בהא שבועה אלא קרבן אחד:"],[2,"עד שיאמר שבועה של כל אחר ואחד","דאמר שבועה לא לך שבועה לא לך דחייב על כל אחד ואחד קרבן:"],[3,"מתני' יודע אני שיש נדרים","שאדם יכול לנדור:"],[3,"אבל איני יודע שיש מפירין","ששום אדם בעולם יכול להפר נדר ואחר כן נודע לו שהפרה מועלת:"],[3,"יפר לה","לאחר זמן כשנודע שיכול להפר דכיון דלא היה יודע שיכול להפר מעיקרא לא קרינן ביה ביום שמעו אלא השתא באותו יום שנודע לו שיכול להפר לה:"],[3,"יודיע אני שיש מפירין","שהפרה מועלת לנדר אבל איני יודע אם נדר זה נדר גמור הוא ונמנע ולא הפר בו ביום:"],[3,"ר\"מ אומר לא יפר","לאחר זמן לכשנודע לו שנדר הוא וצריך הפרה דהואיל והוא ידע בטיב הפרה ולא הפר פושע הוא מ\"מ אי נדר הוא שפיר עביד דמפר אי לאו נדר הוא מאי איכפת ליה מאי דהפר ואיכא מקצת שמיעה ככל שמיעה:"],[3,"וחכמים אומרים יפר","הואיל ולא הוברר הדבר ואע\"ג דאיכא מקצת שמיעה אינה ככל שמיעה חכמים דמתניתין היינו רבי יהודה:"],[4,"גמ' ורמינהו בלא ראות פרט לסומא","שהרג בשוגג שאינו גולה דאמר בלא ראות זה שהרגו לא ראהו דאילו ראהו לא היה הורגו מכלל דיש ספק בידו לראות ואינו רואה דאינו גולה (דאמר) [דסד\"א] מקצת ידיעה לסומא באובנתא דליבא תליא דרוב סומין מבינים לקול הברה מהיכן היא יוצאה ואותה קצת ידיעה בכלל ידיעה היא דקרא לא מיירי אלא היכא דידע לחבריה דהוה התם אלא דלא מיכוין למיקטליה:"]],[[1,"אבל חכ\"א מקיש הקמה [להפרה]","דחכמים לא משמע להו למידרש יקימנו יקים ממנו הלכך הקמה והפרה שוים:"],[2,"רבי שמעון היא","דאמר בפרק שבועת הפקדון (שבועות לו:) דלא הוי שבועה פרט להתחייב חמש חטאות עד שיאמר שבועה לכל אחד ואחד והכא נמי לא הוי שני נדרים אלא משום דאמר קונם לכל אחד ואחד:"],[3,"יודע אני שיש נדרים אבל איני יודע שיש מפירין","כלומר שיוכל בעל להפר ולאחר מיכן [נודע לו שיוכל להפר] יפר ולא אמרינן הרי שמע זה כמה ימים דהא לא הוי שמיעה כיון שלא היה יודע שיכול להפר:"],[3,"יודע אני שיש מפירין אבל איני יודע שזה נדר גמור ר\"מ אמר לא יפר","דלא קרינא ביה ביום שמעו הואיל והיה יודע שיש הפרה וחכמים אומרים יפר הואיל וטעה בנדר לא הוי שמיעה:"],[4,"בלא ראות לרבות סומא","אלמא ר\"מ בתר סברא אזיל ולא בתר ריהטא דקרא דמשמעותיה בבר ראיה ולא בסומא שאי אפשר לראות ואפילו הכי מרבה ליה דסוף סוף : אין רואהו וגולה ואם כן ברישא דמתניתין נמי אמאי מפר נהי דאינו יודע שיש מפירין סוף סוף הרי שמע ולא הפר והרי שמע והחריש קרינא ביה ומשני התם מעניניה דקרא גבי רוצח כו' - השתא מפרש טעמא דרבי יהודה וטעמא דרבי מאיר:"]]],[["אמר רבא הכא מעניניה דקרא והכא מעניניה דקרא ר' יהודה סבר גבי רוצח כתיב (דברים יט, ה) ואשר יבא את רעהו ביער כל דבר מיעל ליער וסומא נמי בר מיעל ליער הוא ואי אמרת בלא ראות לרבות את הסומא מיער נפקא ליה אלא שמע מינה בלא ראות פרט לסומא","רבי מאיר סבר כתיב בבלי דעת כל דבר מידע וסומא לאו בר מידע הוא ואי אמרת בלא ראות פרט לסומא מבלי דעת נפקא ליה אלא שמע מינה בלא ראות לרבות את הסומא","\u0001מתני׳\u0002 המדיר הנאה מחתנו והוא רוצה לתת לבתו מעות אומר לה הרי המעות האלו נתונין לך במתנה ובלבד שלא יהא לבעליך רשות בהן אלא מה שאת נושאת ונותנת בפיך","\u0001גמ׳\u0002 אמר רב לא שנו אלא דאמר לה מה שאת נושאת ונותנת בפיך אבל אמר מה שתרצי עשי קנה יתהון בעל ושמואל אומר אפילו אמר מה שתרצי עשי לא קנה יתהון בעל מתקיף לה רבי זירא"],[[0,"","כדכתיב ואשר יבא את רעהו ביער דהוה ידיע ליה (אבל) סומא אע\"פ שלא ראהו ששם הוא על ידי שמיעה ידע שהוא לשם ונימא דחייב גלות להכי איצטריך קרא בלא ראות פרט לסומא דאינו חייב גלות:"],[0,"רבי מאיר אומר בלא ראות לרבות את הסומא","שגולה דהא אינו רואה והיינו דאיצטריך קרא לרבויי מי שהוא בלא ראות בלא ראיית העין דלא אמר מקצת ידיעה בכלל ידיעה ונימא דהואיל ומקצת ידיעה לאו בכלל ידיעה לא יהא גולה להכי איצטריך לן ריבויא דקרא לחייבו גלות וקשיא דר\"מ אדר\"מ דבמתני' קאמר רבי מאיר מקצת ידיעה בכלל ידיעה ולא יפר והכא קאמר לה לא אמרינן מקצת ידיעה בכלל ידיעה:"],[0,"אמר רבא לא קשיא הכא מעניניה דקרא","גבי רוצח לאו במקצת ידיעה בכלל ידיעה פליגי אלא מדיוקא דקרא דדייק הכי:"],[0,"רבי יהודה סבר כל דבר מיעל ליער הוא","כל מי שיכול ליכנס ליער גולה ואפי' סומא במשמע ואתא בלא ראות דלא איצטריך דכי היכי דמתרבי מבלא ראות מתרבי נמי מיער והוי רבוי אחר רבוי ואין רבוי אחר רבוי אלא למעט ובלא ראות ממעט לסומא:"],[1,"כל דבר מידע הוא","כלומר כל שיש לו ידיעה כשזורק אבן להיכן נופלת וסומא לאו בר מידע הוא:"],[1,"ואי אמרת בלא ראות פרט לסומא","דאינו גולה הוי מיעוט אחר מיעוט מבלי דעת ובלא ראות ואין מיעוט אחר מיעוט אלא לרבות ואתא בלא ראות ומרבה סומא:"],[3,"גמ' לא שנו","דיכול ליתן לה אע\"ג דהוא מודר הנאה ממנו אלא דאמר לה בענין זה אין לך רשות בהן אלא מה שאת נושאת ונותנת לתוך פיך דכיון דאמר לה הכי לא קנה בעל ויכול ליהנות מהן דמשל אשתו הוא אוכל:"],[3,"אבל אמר לה מה שתרצי עשי בהן","אע\"ג דאמר לה שאין לבעליך רשות בהן דמי כמי שקנה הבעל מיד האב דיד אשה כיד בעלה וכמי שנתן לחתנו דמי שהרי הרשה לה בהן לעשות מהם כל דבר ואסור הבעל בהן:"],[3,"ושמואל [אומר אפילו] אמר לה מה שתרצי כו'","קסבר לא אמרינן יד אשה כיד בעלה:"]],[[1,"בבלי דעת","שאינו יודע שהאחר אצלו וסומא לאו בר מידע הוא שאינו יכול לראות אם חבירו עמו אם לאו דאזיל רבי מאיר בתר משמעותיה דקרא כמו במתניתין דאמר לא קרינא כאן ביום שמעו והחריש הואיל וסבור שאינו יכול להפר:"],[1,"ואי אמרת כו'","אלא שמע מינה בלא ראות לרבות את הסומא דיתורא הוא לרבויי דודאי משמעותא לא משתמע [הכי] ולפירוש זה לא גרסינן מה שיש במקצת ספרים והכא מעניניה דקרא ושמע אישה וי\"ס דלא גרסינן:"],[2,"המדיר חתנו כו' נתונים לך במתנה","ואע\"ג דנהנה הוא בדבר אין זה אלא גורם הנאה כדתנן (לעיל נדרים ד' לח.) וזן אשתו ובניו:"],[3,"לא שנו אלא דאמר לה מה שאת נושאת ונותנת לתוך פיך","דלא הויא המתנה שלה לכל דבר הילכך אם אמר לה ע\"מ שאין לבעליך רשות בהם לא קנה הבעל אבל אמר לה מה שתרצי עשי קני יתהון בעל וכי הדר אמר לה על מנת שאין לבעליך רשות בהם לא אמר (לה) כלום דיד אשה כיד בעלה דמיא שנתנם לה לעשות כל מה שתרצה קנאתם בעל אבל כי אמר לה מה שאת נושאת ונותנת לפיך דמתנה לא הויא גמורה לא אמרינן יד אשה כיד בעלה ופר\"ת דהלכה כרב לגבי שמואל דהיינו באיסורי והלכה כרבי מאיר דרב קאי כוותיה הארכתי בפ\"ק דקידושין (דף כג: ד\"ה ור\"א):"]]],[["כמאן אזלא הא שמעתא דרב כרבי מאיר דאמר יד אשה כיד בעלה","ורמינהו כיצד משתתפין במבוי מניח את החבית ואומר הרי זה לכל בני מבוי ומזכה להן על ידי עבדו ושפחתו העברים ועל ידי בנו ובתו הגדולים ועל ידי אשתו","ואי אמרת קנה יתהון בעלה עירוב לא נפיק מרשותיה דבעל","אמר רבא אע\"ג דאמר רבי מאיר יד אשה כיד בעלה מודה רבי מאיר לענין שיתוף דכיון דלזכות לאחרים הוא מיד בעלה זכיא","איתיביה רבינא לרב אשי אלו שזכין להן [על ידי] בנו ובתו הגדולים ועבדו ושפחתו העברים ואלו שאין זכין להן על ידי בנו ובתו הקטנים ועבדו ושפחתו הכנענים ואשתו","אלא אמר רב אשי מתניתין בשיש לה חצר באותו מבוי עסקינן דמגו דזכיא לנפשה זכיא לאחריני","\u0001מתני׳\u0002 (במדבר ל, י) ונדר אלמנה וגרושה יקום עליה כיצד אמרה הריני נזירה לאחר שלשים יום אע\"פ שנשאת בתוך ל' יום אינו יכול להפר"],[[0,"כמאן אזלא הא שמעתא דרב","דמתרץ למתני' דיד אשה כיד בעלה:"],[0,"כרבי מאיר","דאמר בעלמא דיד אשה כיד בעלה:"],[1,"ורמינהו כיצד משתתפין כו'","במסכת עירובין וסתם מתני' ר' מאיר:"],[3,"אמר רבא דאע\"ג דאמר רבי מאיר","בעלמא יד אשה כיד בעלה וכמי שנתן לחתנו דמי:"],[3,"מודה רבי מאיר לענין שיתוף דכיון דלזכות לאחרים הוא מיד בעלה זכיא","כלומר כיון דבעל דעתו הוי לזכות לאחרים על ידי אשתו נמי יצא מיד בעלה ואין לו רשות בהן כלום ואהכי מזכי להו על ידה אבל בעלמא כגון דיהיב מתנה לאשתו אימא לך דיד אשה כיד בעלה:"],[4,"אלו שזכין","גבי שיתוף מבוי קמיירי שמזכה משלו לכל בני מבוי:"],[4,"על ידי בנו ובתו הגדולים","שכבר יצאו מרשותו אבל לא על ידי בנו ובתו הקטנים שידן כידו וכן לא על ידי אשתו אלמא לר\"מ אפ. לו על ידי שיתוף יד אשה כיד בעלה דמיא:"],[5,"אלא אמר רב אשי מתניתין","דלעיל דקאמר דיכול לזכות לכל בני מבוי על ידי אשתו:"],[5,"כשיש לה חצר באותו מבוי","לאותה אשה שאין חצרה זקוקה לבעלה דמגו דזכיא לנפשה לההוא חצר זכיא נמי לאחריני את השיתוף:"],[6,"מתני' ונדר אלמנה וגרושה כיצד","באיזה ענין אמר קרא כנדר אלמנה וגרושה יקום עליה:"],[6,"אמרה הריני נזירה לאחר שלשים יום","ובשעת שנדרה היתה אלמנה או גרושה:"],[6,"אע\"פ שניסת בתוך ל' יום","קודם שיחול הנדר עליה ואיכא למימר הואיל ולא חל הנדר עליה יפר לה בעל אפי' הכי אין יכול להפר דבתר אמירה אזלינן והוי להו קודמין ואין הבעל מפר בקודמין:"]],[[0,"כמאן אזלא הך שמעתא דרב כר\"מ","דאמר פרק קמא דקידושין דיד עבד כיד רבו דמי ומשמע ליה לרבי [זירא] דהכי נמי אמר גבי אשה ומתני' ר\"מ דסתם משנה ר\"מ:"],[1,"ורמינהו כיצד משתתפין במבוי","פירוש שיש הרבה חצירות פתוחות למבוי ואסורות לטלטל בתוכו להוציא ולהכניס בתוכו:"],[1,"מניח חבית של יין","ומזכה להם על ידי אשתו והוי כאילו הכא דיירי ואין אוסרין זה על זה:"],[2,"ואי אמרת יד אשה כיד בעלה כו'","אלא שמע מינה דר' מאיר לא אמר אלא בעבד אבל לא באשה וקשה לרב:"],[3,"כיון דלזכות אחרים מיד בעלה זכיא","כיון דבעל עצמו מזכה בהם ומסתלק עצמו מחלקו [זכיא כדאמרי' במתנת [הבעל] שאין הבעל אוכל פירות:"],[4,"איתיביה רבינא לרב אשי","אמתני' דעירובין קאי ולא קאי אהך סוגיא כלל:"],[4,"ואלו שזכין","כלומר שמזכין על ידן וכו' ואשתו:"],[5,"בשיש לה בית בחצר","ואוסר ביתה על המבוי וצריך הבעל לזכות גם לעצמה והיא קונה כדאמר כיון דבעל יהיב לה מגו דזכיא לנפשה קניא לאחרינא בהכי מיירי מתניתין דעירובין וברייתא דאבל לא על ידי אשתו כשאין לה בית בחצר ואין זוכה לאחרים דלא הוי כאילו הבעל נותן לעצמה:"],[6,"ונדר אלמנה וגו'","קיימא מתניתין אקרא כיצד אמרינן פנויה שאמרה:"],[6,"אינו יכול להפר","דאמרינן דאזלינן בתר שעת נדרה ואז היתה אלמנה ובעל אינו מיפר בקודמין:"]]],[["נדרה והיא ברשות הבעל מפר לה כיצד אמרה הריני נזירה לאחר ל' אע\"פ שנתאלמנה או נתגרשה בתוך ל' הרי זה מופר נדרה בו ביום ונתגרשה בו ביום החזירה בו ביום אינו יכול להפר זה הכלל כל שיצאה לרשות עצמה שעה אחת אינו יכול להפר","\u0001גמ׳\u0002 תניא אלמנה וגרושה שאמרה הריני נזירה לכשאנשא ונשאת ר' ישמעאל אומר יפר ור\"ע אומר לא יפר וסימנא ילל\"י אשת איש שאמרה הריני נזירה לכשאתגרש ונתגרשה ר' ישמעאל אומר לא יפר ורבי עקיבא אומר יפר","אמר רבי ישמעאל הרי הוא אומר (במדבר ל, י) ונדר אלמנה וגרושה וגו' עד שיהא נדר בשעת אלמנות וגרושין ר\"ע סבר הרי הוא אומר (במדבר ל, י) כל אשר אסרה על נפשה עד שיהא איסורי נדר בשעת אלמנות וגרושין","אמר רב חסדא מתני' ר' עקיבא היא אביי אמר אפילו תימא רבי ישמעאל מתניתין תליא נפשה ביומי ברייתא תליא נפשה בנישואין","שלמו יומי ולא נתגרשה שלמו יומי ולא מיתנסבא","זה הכלל דקתני גבי נערה המאורסה לאיתויי הלך האב עם שלוחי הבעל או שהלכו שלוחי האב עם שלוחי הבעל בנערה המאורסה דאביה ובעלה מפירין נדריה","זה הכלל דקתני גבי ואלו נדרים לאיתויי מסר האב לשלוחי הבעל או שמסרו שלוחי האב לשלוחי הבעל שאין הבעל מיפר בקודמין","\u0001מתני׳\u0002 תשע נערות נדריהן קיימין בוגרת והיא יתומה נערה ובגרה והיא יתומה"],[[0,"נדרה והיא ברשות הבעל","שהיתה נשואה והפר לה בעל והשתא מפרש כיצד נדרה אמרה הריני נזירה לאחר שלשים יום והפר לה בעל:"],[0,"אע\"פ שנתאלמנה בו' הרי זה מופר","ואע\"ג דאיכא למימר הואיל ובשעת הנדר דינו שיחול וכבר יצאה לרשות עצמה ולא תועיל בו הפרה להכי אשמעינן דהרי זה מופר דאחר שעת אמירה קאזלינן ואשמעינן היכא דבאה ברשות עצמה בשעת הנדר והיכא דהיא ברשות אחרים נמי:"],[0,"זה הכלל כל שיצאה לרשות עצמה","מפרש בגמ' לאיתויי מאי:"],[1,"גמ' רבי ישמעאל אומר יפר","דהפרה מועלת בו הואיל ולא חל הנדר עד שנכנסה לרשות בעלה:"],[1,"ר' עקיבא אומר לא יפר","דבתר קבלת הנדר אזלינן:"],[1,"וסימניך ילל\"י","כלומר בבא ראשונה תני יפר והדר לא יפר בבא אחרונה תני לא יפר והדר יפר:"],[1,"אשת איש שאמרה","בזמן שהיא אשת איש כו':"],[1,"ר' ישמעאל אומר לא יפר","אין הפרה מועלת בו הואיל ובשעה שהנדר חל הויא ברשות עצמה:"],[1,"ר' עקיבא אומר יפר","דבשעת קבלת הנדר הויא ברשות הבעל:"],[2,"עדי שיהא נדר","כלומר קיום הנדר:"],[2,"ורבי עקיבא סבר הרי הוא אומר כל אשר אסרה על נפשה שיהא איסור הנדר","קבלת הנדר והכי נמי דייקינן במתני' כל אשר אסרה ורבי עקיבא היא:"],[3,"אפי' תימא ר' ישמעאל מתני'","בדין הוא היכא דנדרה כשהיא אלמנה ותלתה נדרה בימים עד לאחר שלשים יום אהכי קאמר אינו יכול להפר דליכא למימר כל הנודרת על דעת בעלה היא נודרת דלא מסקא אדעתא דתינשא בתוך הזמן אהכי אינו יכול להפר דאימור זימנין דשלמו כל ל' יום ולא ניסת וכי נדרה נמי ברשות בעלה ותלתה נדרה בימים דין הוא שיפר איכא למימר כל הנודרת כו' ולא מסקא אדעתא שתתגרש דזימנין דשלמו יומי ולא מיגרשא ואם הפר הרי זה מופר ודידי נמי היכא דתלתה נדרה בנישואין אהכי יפר דעל דעת בעלה נדרה והיכא דתלתה נדרה בגירושין ליכא למימר דתלתה עצמה בבעלה ואהכי לא יפר:"],[5,"זה הכלל דקתני","באידך פירקין (לעיל נדרים דף עא.) גבי נערה המאורסה זה הכלל כל שלא יצאה לרשות עצמה כו' לאיתויי הלך האב עם שלוחי הבעל דהתם לא יצאה לרשות עצמה דאביה ובעלה מפירין נדריה:"],[6,"זה הכלל דקתני הכא","גבי ואלו נדרים דמשמע דיוצאת לרשות עצמה לאיתויי מסר האב לשלוחי הבעל ולא הלך הוא עמהם דאותה שעה יצאה מרשות האב עד שהגיעה לרשות הבעל ויצאה לרשות עצמה ואין הבעל מיפר נדריה שאין הבעל מיפר בקודמין:"],[7,"מתני' ט' נערות נדריהן קיימין","שאין יכול להפר להן:"],[7,"בוגרת והיא יתומה","נערה בוגרת והיא יתומה:"]],[[0,"אמרה הריני נזירה לאחר שלשים יום","פירוש אם אשה שאמרה כן ונתגרשה קודם שיגיעו שלשים יום הרי זה מיפר קודם שיגרשנה:"],[0,"נדרה וגרשה בו ביום והחזירה בו ביום","בפירקין דלעיל (נדרים דף עב -) מוקמינן לה בנשואה ואינו יכול להפר דאין בעל מיפר בקודמין ובגמרא מפרש [זה הכלל] לאיתויי מאי:"],[1,"תניא כו' לכשאנשא רבי ישמעאל אומר יפר","דאזלינן בתר שעתא דחייל הנדר:"],[1,"רבי עקיבא אומר לא יפר","דאזלינן בתר שעתא שנדרה:"],[2,"עד שיהא נדר","שיחול בעודה אלמנה וכיון דלא חל שניסת יפר:"],[2,"כל אשר אסרה על נפשה","בהאי קרא דנדר אלמנה כתיב שיהא איסור הנדר נזירות בשעת אלמנות דאזלינן בתר שעת הנדר:"],[3,"ברייתא תליא נפשה בנישואין","כלומר עד כאן לא קאמר ר\"ש הריני נזירה לכשאנשא דיפר משום שאי אפשר לנדר לחול באלמנותה הילכך קרינא ביה נדר באלמנות:"],[3,"מתניתין תליא נפשה ביומי","ויכול להיות שישלמו הימים בעודה אלמנה וכן בסיפא איכא לשנויי בכה\"ג:"],[5,"זה הכלל דקתני גבי נערה","בפירקין דנערה דלעיל דקתני כל שלא יצאה לרשות עצמה שעה אחת אביה ובעלה אחרון מפירין נדריה ולא אמרינן דמסירתה לשלוחי הבעל הוי קירוב דנישואין ויצאה מרשות אב:"],[6,"זה הכלל דקתני גבי נדרים","כלומר הכא לאיתויי מסר האב לשלוחי הבעל ונדרה וגירשה והחזירה דאין בעל מפר דיצאה כבר מרשות האב כיון שמסרה לשלוחי הבעל הרי הוא כאילו נכנסה לחופה:"],[7,"תשע נערות נדריהן קיימין","בוגרת והיא יתומה בוגרת ומת אביה נערה שלא בגרה ומת אביה נערה ובגרה ומת אביה נערה שמת אביה ומשמת אביה בגרה בוגרת ואביה קיים [נערה ובגרה ואביה קיים] נערה והיא יתומה [נערה בוגרת והיא יתומה] עד כאן הגי'. ה\"פ ט' מיני נערות מיהו אין בהם חידוש בכולם אך השמיענו התנא בכל הצדדין שיוכל למצוא ובוגרת נמי בכלל נערות פי' בוגרת והיא יתומה ונדרה אחר שנתיתמה א'. בוגרת ומת אביה כלומר בוגרת שנדרה ואחר הנדר מת אביה ב'. נערה שלא בגרה ומת אביה פירוש נדרה כשהיא נערה ומת אביה אחר הנדר ובאתה לשאול על נדריה בעודה נערה ג'. נערה ובגרה ומת אביה פירוש נדרה כשהיא נערה ואח\"כ בגרה ובאת לשאול אחר שמת אביה דאביה מת אחר הבגר ד'. נערה שמת אביה פירוש נדרה כשהיא נערה ושוב אחר הנדר מת אביה ובגרה ואחר שבגרה באת לפנינו לשאול על נדרה ה' . בוגרת ונדרה ואביה קיים ו'. נערה בוגרת פירוש נדרה כשהיא נערה ובגרה אחר הנדר ואביה קיים ובאה לשאול בעוד אביה חי ז'. נערה והיא יתומה פירוש נערה שנתיתמה ונדרה אחר שנתיתמה ח'. נערה בוגרת והיא יתומה פירוש נדרה כשהיא נערה ובשעת הנדר היא יתומה ובגרה ובאת לשאול על נדרה אחר שבגרה הרי לך תשע נערות חלוקות ולא ראי זו כראי זו וכולן נדרן קיימין ואין אב יכול להפר:"]]],[["נערה שלא בגרה והיא יתומה בוגרת ומת אביה נערה בוגרת ומת אביה נערה שלא בגרה ומת אביה נערה שמת אביה ומשמת אביה בגרה בוגרת ואביה קיים נערה בוגרת ואביה קיים ר' יהודה אומר אף המשיא בתו הקטנה ונתאלמנה או נתגרשה וחזרה אצלו עדיין היא נערה","\u0001גמ׳\u0002 א\"ר יהודה אמר רב זו דברי ר' יהודה אבל חכ\"א שלש נערות נדריהן קיימין בוגרת ויתומה ויתומה בחיי האב","\u0001מתני׳\u0002 קונם שאיני נהנה לאבא ולאביך אם עושה אני על פיך שאיני נהנית לך אם עושה אני על פי אבא וע\"פ אביך הרי זה יפר","\u0001גמ׳\u0002 תניא שאיני נהנית לאבא ולאביך אם אני עושה לפיך ר' נתן אומר לא יפר וחכ\"א יפר","נטולה אני מן היהודים אם משמשתך ר' נתן אומר לא יפר וחכ\"א יפר","ההוא גברא דאיתסר הנייתא דעלמא עליה אי נסיב איתתא כי לא תנינא הילכתא רהיט בגפא ותובליא ולא אמצי למיתנא אתא רב אחא בר רב הונא ושבשיה ואינסיב איתתא"],[[0,"","נערה שלא בגרה והיא יתומה בוגרת ומת אביה נערה בוגרת ומת אביה ונערה שמת אביה ומשמת אביה בגרה בוגרת ואביה קיים ר' יהודה אומר כו' - בוגרת והיא יתומה בשעת הנדר היתה בוגרת וכבר היתה יתומה מבעלה כלומר יתומה דמתניתין יתומה בחיי האב כדמפרשי רבנן בגמ' דיתומה דשייך למימר בבעל כבאב דיקא נמי היכא דתני מיתת האב תני לה בפירוש בוגרת ומת אביה:"],[1,"גמ' זו דיבר ר' יהודיה","דקתני תשע:"],[1,"אבל חכמים אומרים שלש נערות נדריהן קיימין בוגרת ויתומה ויתומה בחיי האב","וכולהו תשע דמתני' נכללות בהני שלש:"],[2,"מתני' קונם שאיני עושה לאבא ולאביך","כלומר שאני נותן להם יהא עליהם קונם:"],[2,"הרי זה יכול להפר","אע\"ג דלאו נדרי עינוי נפש אינון דלאו כל כמיניה לאפקועי שיעבודא מינה אפי' הכי דברים שבינו לבינה הויין ויכול להפר כלומר הרשות בידו:"],[3,"גמ' ר' נתן אומר לא יפר","דקסבר הואיל ועדיין לא חל הנדר שכל זמן שלא עשתה לפי בעלה ולא שימשתו אינה אסורה לאביה ולאביו ולא יפר:"],[3,"וחכ\"א יפר","אע\"פ שעדיין לא חל הנדר עליה:"],[5,"ההוא גברא דיאמר תיתסר הנייתא דעלמא עליה אי נסיב איתתא כי לא תנינא הלכתא","כלומר תיתסר הנאת עולם עלי אם אקח אשה עד שאשנה הלכות:"],[5,"רהיט בגפא ותובליא","גפא קרי סולם שעולין בו באילן תובליא חבל שתולין בדקל ומושכין להם למטה הענפים שבהן התמרים ומשל של בני אדם הוא רץ למעלה ולמטה לעסוק ולשנות הלכות ולא איסתייעא מילתא ואית דמפרש דהיינו בכפא רץ יחידי למעלה ולמטה כאדם שעולה בחבל באילן:"],[5,"תובליא","חבל כדאמרי' בבבא בתרא (דף לג:) מאן דנקט מגליא ותובליא ואמר אזיל ואגזור דיקלא דפלניא:"]],[[0,"רבי יהודה אומר אף המשיא בתו קטנה","ונכנסה לחופה וגירשה ועדיין היא קטנה או נערה נדריה קיימין וזו היא יתומה בחיי האב שבכל הש\"ס:"],[1,"זו דברי רבי יהודה","דכייל תשעה מיני נערות אבל חכמים אומרים שלשה מיני נערות כלומר לא חשיבי אלא שלש דלא פליגי במידי:"],[2,"קונם שאני נהנית לאבא ולאביך אם אני עושה לפיך","אם אני מהנית לך אינו יכול להפר דאפילו דברים שבינו לבינה לא הוי שתעשה לפיו ולא תהנה לאבא ולאביה לשון הרב רבי אליעזר וברוב הספרים כתיב יפר וכך נראה יותר דהכי נמי אמרי רבנן דפליגי ארבי נתן בגמרא:"],[3,"תניא שאני נהנית לאבא ולאביך אם אני עושה לפיך רבי נתן אומר לא יפר","פירש הרב רבי אליעזר מסתברא טעמיה הוא שאין בעל מפר עד שיחול ולא חל עד שתשמש לבעל ועוד דלא חשיב ליה נדר שבינו לבינה ולא נראה דא\"כ מנלן לר' נתן דאין בעל מיפר עד שיחול דלמא כל טעמו יש דלא הוי נדר שבינו לבינה ונראה דשפיר הוי דברים שבינו לבינה כיון שעל ידי שתעשה לפי בעלה תאסור לההנות אביה משיאה בעלה שם רע בשכינותיה ולא דמי לשאיני עושה לפי אבא ולפי אביך דאמר לעיל דאינו יכול להפר כיון שאסרה עצמה מאיליה דלא תלתה הנדר בעשייתה לפי הבעל וטעמא דרבי נתן משום דסבירא ליה דאין בעל מיפר עד שיחול הנדר ורבנן סברי דבעל מיפר קודם שיחול:"],[4,"נטולה אני מן היהודים","אסרה בתשמיש אם אני משמשך פעם אחת רבי נתן אומר לא יפר עד שתשמשנו וחכ\"א יפר מיד דנדר זה הוי שפיר בינו לבינה שאם תשמש לו פעם אחת תהא אסורה לו לעולם דבעל הוי בכלל היהודים הילכך מיפר קודם תשמיש דאין צריך שיחול:"],[5,"ההוא גברא דאמר תיאסר הנאת עלמא","כלומר כל הנאות שבעולם אי נסיבנא איתתא עד שאלמוד כל הש\"ס ולא חל האיסור עד שנשא האשה:"],[5,"רהיט בגפא ותובליא","[כלי] שמובילין בו פירות ולא היה יכול ליגע וללמוד:"],[5,"שבשיה","כלומר הטעהו [א\"ל] ישא אשה ולא יאסר בהנאת העולם נשא אשה ונאסר:"]]],[["ושרקיה טינא ואתייה לקמיה דרב חסדא אמר רבא מאן חכים למיעבד כי הא מילתא אי לאו דרב אחא בר רב הונא דגברא רבה הוא דקסבר דכי היכי דפליגי רבנן ור' נתן בהפרה הכי נמי פליגי בשאלה","ורב פפי אמר מחלוקת בהפרה דר' נתן סבר אין הבעל מיפר אא\"כ חל נדר דכתיב (ישעיהו כד, כג) וחפרה הלבנה ורבנן סברי בעל מיפר אע\"פ שלא חל נדר דכתיב (איוב ה, יב) מפר מחשבות ערומים","אבל בשאלה דברי הכל אין חכם מתיר כלום אא\"כ חל נדר דכתיב (במדבר ל, ג) לא יחל דברו","לימא מסייע ליה קונם שאיני נהנה לפלוני ולמי שאשאל עליו נשאל על הראשון ואח\"כ נשאל על השני ואי אמרת נשאל אע\"פ שלא חל נדר אי בעי על האי ניתשיל ברישא אי בעי על האי ניתשיל ברישא","ומי ידע אי האי קמא אי האי בתרא","אלא לימא מסייע ליה קונם שאיני נהנה לפלוני הריני נזיר לכשאשאל עליו נשאל על נדרו ואח\"כ נשאל על נזרו","ואי אמרת נשאל אע\"פ שלא חל נדר אי בעי על נדרו איתשיל ברישא אי בעי על נזרו איתשיל ברישא ר' נתן היא","אמר רבינא אמר לי מרימר הכי אמר אבוך משמיה דרב פפי מחלוקת בהפרה אבל בשאלה דברי הכל מפר ואע\"פ שלא חל נדר דכתיב לא יחל דברו"],[[0,"ושבשיה ואנסביה איתתא ושרקיה טינא","טח פניו בטיט כדי שלא יכירהו רב חסדא כאילו היה אדם אחד מהם שנדר שלא ישא אשה כדי שיתיר לו דאפשר אילו היה מכירו לא היה מתיר לו:"],[0,"מאן חכם למיעבד כי האי מילתא","שדקדק בכך שהשיאו אשה קודם שישאל על נדרו כדי שיחול הנדר עליו קודם שאלה דקסבר כרבי נתן דאמר לא יפר הואיל ולא חל הנדר דרבי נתן דיינא הוא ונחית לעומקא דדינא:"],[0,"הכי נמי פליגי בשאלה","שאין נשאלין לחכם עד שיהא הנדר חל עליו:"],[1,"דכתיב וחפרה הלבנה","והא וחפרה דמשמע אימתי הוי הפרה בזמן שחל בנה. בנה היינו נדר רבי נתן לטעמיה דאמר הנודר כאילו בנה במה והמקיימו כו' והיינו חל בנה חל בנין הנדר. ע\"א מסיפיה דקרא וחפרה הלבנה ובושה החמה כדכתיב והיה אור הלבנה כאור החמה ואור החמה יהיה שבעתים וגו' דבההיא שעתא חפרה נהורא דהלבנה דעד השתא כי מלך ה' צבאות על ישראל ולא קודם שימלך וה\"ה גבי נדר מכי חל עליה הוא דמיפר ולא קודם שיחול:"],[1,"דכתיב מפר מחשבות ערומים","דמשמע מפר אפילו מחשבה בעלמא אף ע\"פ שלא חל הנדר עדיין:"],[2,"אבל","בנדרים שצריך שאלה לחכם דברי הכל אינו מתיר אא\"כ חל הנדר כדכתיב לא יחל דברו דמשמע כל זמן שאין שם מעשה בנוי אלא דיבור בעלמא שעדיין לא חל הנדר לא יחל החכם והאי דדרשינן מיניה. הוא אינו מוחל אבל אחרים מוחלין לו בזמן שחל הנדר קאמר:"],[3,"לימא מסייע ליה","לרב פפי דאפילו בשאלה דברי הכל אינו [מתיר] עד שיחול הנדר:"],[3,"קונם שאיני נהנה לפלוני ולכל מי שאשאל עליו","כלומר אם אשאל עליו לשום חכם להתיר לי יהא עלי קונם מה שאני נהנה לאותו חכם:"],[3,"ואי אמרת","דנשאלין לחכם עד שלא חל הנדר אי בעי למישאל על המודר ברישא מיתשיל אי בעי מיתשיל על חכם ברישא: מאי נשאל דקאמר סתמא דמשמע או על החכם או על מודר:"],[5,"לימא מסייע ליה","מהכא קונם שאני נהנה לפלוני דחל עליה נדר לאלתר והריני נזיר לכשאשאל לחכם עליו:"],[5,"נשאל על נדרו","שחל עליו ואח\"כ נשאל נמי על נזרו שלא חל עד שישאל עליו:"],[6,"ואי אמרת נשאל","לחכם נמי אע\"פ שלא חל הנדר וכי היכי דפליגי בהפרה פליגי בשאלה ובדין הוא דלרבנן חל נזירותו:"],[6,"שאיל ברישא","דליזיל לחכם לישאל על נזירותו תחילה ואחר כך על נדרו:"]],[[0,"ושרקיה טינא","פי' טחו בטיט שלא יהנה מן העולם. א\"נ יש לפרש שרקו כדי שלא יכירהו רב חסדא שהיה מתבייש על מה שלא קיים נדרו:"],[0,"מאן חכים כו'","שלא היה רוצה להתיר עד שהשיאו וחל הנדר:"],[0,"ה\"נ בשאלה","דקסבר הלכה כרבי נתן:"],[1,"דכתיב וחפרה הלבנה","פירש ה\"ר אליעזר לא ידעתי לפרש היכי משמע ליה מהכא ונראה דלסימנא בעלמא נקטיה הש\"ס וחפרה בניינה בנין האיסור נראה הוא המקיימו כאילו בנה במה וסימנא בעלמא וטעמא מסברא במקום שאין איסורא לשון הר\"ר אליעזר ואית ספרים דגרסי וטעמיה דרבי נתן משום דכתיב והפר נדרה אשר עליה דמשמע לאחר שיחול עליה הנדר יפירנו וטעמא דרבנן משום דכתיב מפר מחשבות ערומים משעת מחשבה קודם שיחול האיסור יפר וגם זה אמר הר\"ר אליעזר דאינו אלא סימנא בעלמא משעת מחשבה קודם שיחול יפר והכי נמי מצינו פרק הדר [עירובין דף עג:] ודניאל בתרע מלכא דלא מייתי אלא סימנא בעלמא לומר דרבי יהודה בן בבא מתיר בעבדים ואע\"ג דאינו סתמא האי טעמא דר' יהודה בן בבא:"],[3,"קונם שאני נהנה לפלוני ולמי שאשאל לחכם עליו","גם לחכם שאשאל עליו איאסר שלא אהנה משלו:"],[3,"נשאל על הראשון","שאסר הנאתו עליו ואחר כך נשאל [על השני] ס\"ד [דשני] רוצה לומר על החכם שני לאיסור:"],[3,"אי בעי אהא מיתשיל","כלומר ישאל על איזה שירצה תחילה:"],[4,"מי ידעינן הי קמא והי בתרא","דילמא נשאל על הראשון תחילה דקאמר היינו חכם וקרי ליה ראשון משום דהוי ראשון לשאלה ושני קרי לאחר משום דהוי שני לשאלה ראשון דנקט לאו דווקא וה\"ה דמצי למדחי הא מני רבי נתן כדדחי בסמוך:"],[5,"נשאל על נדרו","שכבר חל ואינו נשאל על נזירותו שהרי עדיין לא חל עד שישאל על נזירותו ויהנה מאותו פלוני:"],[6,"הא מני רבי נתן היא","אבל רבא יכול להיות דכי היכי דבהפרה מיפר אע\"ג שלא חל בהתרת חכם נמי מתיר אע\"ג שלא חל:"],[7,"אבל בשאלה ד\"ה מתיר מיד","אע\"פ שלא חל דכתיב לא יחל דברו למימר דלא הוי כמעשה כלומר מתיר מיד אע\"פ שאין שם עדיין אלא דבור אמר הוא דלא יחל אבל אחרים מוחלין לו:"]]],[["למימרא דלא הוה ביה מעשה","מיתיבי קונם שאיני נהנה לפלוני ולמי שנשאל עליו נשאל על הראשון ואח\"כ נשאל על השני אמאי אי בעי על האי ניתשיל ברישא ואי בעי על האי ניתשיל ברישא","מי יודע הי ראשון והי שני","מיתיבי קונם שאיני נהנה והריני נזיר לכשאשאל עליו נשאל על נדרו ואח\"כ נשאל על נזרו ואמאי אי בעי על נדרו ניתשיל ברישא ואי בעי על נזרו ניתשיל ברישא תיובתא","\u0001מתני׳\u0002 בראשונה היו אומרים שלש נשים יוצאות ונוטלות כתובה האומרת טמאה אני לך שמים ביני לבינך ונטולה אני מן היהודים","חזרו לומר שלא תהא אשה נותנת עיניה באחר ומקלקלת על בעלה האומרת טמאה אני לך תביא ראיה לדבריה השמים ביני לבינך יעשו דרך בקשה ונטולה אני מן היהודים יפר לחלקו ותהא משמשתו ותהא נטולה מן היהודים","\u0001גמ׳\u0002 איבעיא להו אמרה לבעלה טמאה אני מהו שתאכל בתרומה רב ששת אמר אוכלת שלא תוציא לעז על בניה רבא אמר אינה אוכלת אפשר דאכלה חולין","אמר רבא ומודה רב ששת שאם נתארמלה שאינה אוכלת מידי הוא טעמא אלא משום תוציא לעז על בניה נתארמלה ונתגרשה אמרי השתא דאיתניסא","אמר רב פפא בדיק לן רבא אשת כהן שנאנסה יש לה כתובה או אין לה כתובה כיון דאונס לגבי כהן כרצון לגבי ישראל דמי אין לה כתובה או דילמא מצי אמרה ליה אנא הא חזינא"],[[0,"למימרא דילא הוה מעשה","כלומר דלא הוה צריך למיעבד האי דעבד רב אחא בר רב הונא מההוא גברא דאתייה לקמיה דרב חסדא:"],[2,"מי קא ידעת הי הראשון","דילמא האי דקאמר דנשאל על הראשון על ההוא דלא חל הנדר אף נשאל עליו קאמר:"],[3,"[נשאל על נדרו וכו']","ואי אמרת דנשאל לחכם לדברי הכל אע\"ג דלא חל הנדר הא מני דלא כרבי נתן ודלא כחכמים:"],[4,"מתני' יוצאות","בעל כרחו של בעל:"],[4,"טמאה אני לך","בא עלי אדם אחד וטימאני לך ובאונס קאמר באשת כהן דבאונס נמי אסורה לו ולהכי נוטלת כתובתה דלא פשעה דאי באשת ישראל אינה יוצאה דאנוסה מותרת לו כדנפקא לן (כתובות דף נא:) מוהיא לא נתפשה דאי ברצון קמיירי אפי' לישראל אסורה ואין לה כתובה דהא פשעה ובגמרא מפרש לה הכי:"],[4,"השמים ביני לבינך","שאינו מזריע דדבר זה אינו גלוי לבריות אלא לשמים:"],[5,"יעשו דרך בקשה","יבקשו הימנו שיפטרנה בגט כראוי ואין מכריחין אותו:"],[6,"גמ' מהו שתאכל בתרומה","כיון דלא מפקינא לה מיניה כל כמה דלא אתו סהדי דאמרי נאנסה:"],[6,"שלא תוציא לעז על בניה","דאי אמרת לא תאכל בתרומה אתו למימר דבניה פסולין מן הכהונה דהרי בני אנוסה נינהו שהרי נפסלה מן התרומה מחמת אונס:"],[6,"דאפשר דאכלה חולין","דהואיל דאפשר בתקנתא לא ספינא לה תרומה:"],[7,"ומודה רב ששת דאי נתארמלה או נתגרשה","דהשתא ליכא לעז דמימר אמרי השתא לאחר גירושין הוא דאיתניסא:"],[8,"אשת כהן שנאנסה","בעדים כו' מתני' לא מיתוקמא אלא באשת כהן שנאנסה ובין למשנה ראשונה ובין למשנה אחרונה יש לה כתובה:"]],[[1,"","מיתיבי קונם כו' כל הני דאייתי לעיל משום סיועא מייתי הכא לתיובתא ודחי להו כדדחי לעיל וסוף דבר איתותב רב פפי כדמסיק ונראה דהלכה כרב פפי דאמר דבנדר ד\"ה אין חכם מתיר עד שיחול הנדר אבל בהפרה נראה דמפר כרבנן דרבי נתן אע\"פ שלא חל וכן משמע אם ארחץ אם לא ארחץ דמפר מיד קודם שיחול:"],[4,"בראשונה היו אומרים שלש נשים יוצאות ונוטלות כתובה האומרת טמאה אני לך","ובגמרא מוקי לה באשת כהן ובביאת אונס דאילו באשת ישראל לא מתוקם דאי באונס שריא ואי ברצון לית לה כתובה:"],[4,"השמים ביני לבינך","כלומר לשמים גלוי דברים שביני לבינך שאין השכבת זרע יורה כחץ דאינו ראוי להוליד בבאה מחמת הטענה כדאמר סוף פרק הבא על יבמתו דקאמרה בעינא חוטרא לידא ומרא לקבורה דאל\"כ אמרינן לה זילי לא מפקדת וסבירא לן למשנה ראשונה דמהימנא:"],[4,"ונטולה אני מן היהודים","שאסרה הנאת תשמיש כל היהודים עליה אפילו מן בעלה וסבירא ליה למשנה ראשונה דבעל אינו יכול להפר ולכך יוצאה ותימה כיון דאסרה עצמה על הבעל א\"כ היא נתנה אצבע בין שיניה ולמה יש לה כתובה רש\"י פירש ביבמות דאנן סהדי דלא היתה נודרת כך אלא א\"כ תשמיש קשה לה והויא כמו אנוסה:"],[5,"חזרו לומר אינה נאמנת דחיישינן שמא נתנה עיניה באחר","וא״ת טמאה אני לך אמאי לא מהימנא הא שויתה נפשה חתיכא דאיסורא כדאמר בקידושין פרק האומר (דף סה.) קידשתני והוא אומר לא קידשתיך הוא מותר בקרובותיה והיא אסורה בקרוביו ותירץ הרב רבי אליעזר דלא מצינו זונה שהיא אסורה לינשא לכהן דודאי הוא מוזהר עליה אבל היא אינה מוזהרת עליו הילכך גם לדבריה אינה אסורה בו וקשה דקאמר פרק יש מותרות (יבמות דף פד:) כל היכא דאיהו מוזהר איהי מוזהרת וע״ק דאמר בגמרא דאוכלת בתרומה שלא להוציא לעז על בניה ואמאי והא לגבי תרומה שויתה נפשה חתיכה דאיסורא ונראה לי דכיון דיש לחוש שמא נתנה עיניה באחר יש כח ביד חכמים לעקור דבריה מכל וכל בסברא גדולה כזאת ומיהו נראה דאף למשנה אחרונה אם אומרת אשה טמאה אני לך ואמר הבעל שמאמינה דאסורה לו דאיהו שויא לנפשיה חתיכה דאסורא ואפי' תחזור בה האשה ותאמר באונס היה ויש אומרים דמשמתינא ליה על שגרם שתיאסר אשתו עליו ועובר על חרם תקנת רבינו גרשם:"],[5,"יעשו דרך בקשה","כלומר יבקשו ממנה שלא תאמר עוד כן משום דלא מהימנא עוד פר״ח ביבמות יבקשו רחמים מאת המקום שיהא להם בנים ולא מהימנא וא״ת והלא סוף פרק הבא על יבמתו (יבמות דף סה.) הוא אמר מינה והיא אומרת מיניה פירוש שאין הזרע יורה כחץ איהי מהימנא משום דאיהי קים לה ביורה כחץ ותירץ הרב רבי אליעזר דהתם קאי אנשאת לשלישי ולא היו לה בנים דאיירי בה לעיל וקאמר תצא בלא כתובה ועלה קאי רבי אמי דהיכא דאמרה מיניה דאומרת שהיא רוצה לעמוד תחתיו דאז ליכא חששא דשמא נתנה עיניה באחר מהימנא ומיהו קשה א״כ היכי משכחת לה נישאת לשלישי תצא בלא כתובה לעולם תערים ותאמר שאינו יורה כחץ וי״ל כגון שיש לו בנים מאשה אחרת ומיירי שמתו דאם היו קיימין לא אמר שתצא והתם כי אמרה מיניה לאו כל כמינה וא״ת והא כל הני עובדי דמייתי פרק הבא על יבמתו מסיבה דיליה מה תיהוי עלה דההיא אתתא וכן ההיא דבעינא חוטרא לידא ומרא לקבורה דקאמר כה״ג ודאי כפינן להוציא ויתן לה כתובה ואמאי ליחוש שמא נתנה עיניה באחר ואור״י דהתם איירי באדם עקור שיש קצת הוכחות בדבר שהיא אומרת אמת שאני וכן פירש' לשם:"],[5,"יפר חלקו","דתשמיש הוי דברים שבינו לבינה הילכך מיפר לעצמו:"],[5,"ותהא נטולה מן היהודים","לכשתתגרש ותינשא לאחרים דלא מהניא הפרתו [אלא] לעצמו ואין לתמוה היאך חל נדרה על תשמיש יהודים אחרים בעודה אשת איש והא אין איסור חל על איסור וי\"ל דהוי איסור כולל מגו דאיתחל בתשמיש בעל שהוא היתר חל נמי על האחרים וצ\"ע למ\"ד לעיל (נדרים דף פב.) כוליה פירקין כר' יוסי דהא ר' יוסי לית ליה איסור כולל באשת איש ונעשית חמותו דאמר נידון בזיקה ראשונה הבא עליו (יבמות דף לב.) ה\"ר שמואל מאיור\"ה ז\"ל:"],[6,"אמרה לבעלה טמאה אני מהו שתאכל בתרומה","למשנה אחרונה מיבעינן ליה דאמרה (אכלה בתרומה) דלא מהימנא לאסור לבעל ומיבעיא לענין תרומה אי מהימנא ליאסר בתרומה כדאמר ביבמות דף לה.) דאפילו באונסי' אשת כהן אסורה לאכול בתרומה:"],[6,"שלא להוציא לעז","כיון שאינה אוכלת בתרומה ודאי מחמת זנות נפסלה:"],[6,"אפשר דאכלה חולין","ולא ירגישו העולם שמחמת זנות נמנעת לאכול בתרומה:"],[7,"שאם נתארמלה או נתגרשה","ויש לה בנים מן הכהן וקיימא לן בפרק יש מותרות (יבמות דף פז:) דאוכלת בשביל בנה דכתיב ויליד ביתו הם יאכלו בלחמו קרי ביה יאכילו אמרינן השתא היא דאיתניסא כלומר השתא נבעלה לפסול לה שנפסלה מן התרומה:"],[8,"אשת כהן שנאנסה יש לה כתובה או אין לה כתובה","קשה להר\"ם דבפרק [נערה שנתפתתה] (דף נא.) אמר חייב לפדותה אם נשבית אלמא אית לה תנאי כתובה ויש לחלק משום [דשבויה] ספק אבל אם נאנסה ודאי [אין] לה כתובה:"]]],[["וגברא הוא דנסתחפה שדהו ואמרינן ליה מתני' היא האומרת טמאה אני לך יש לה כתובה","במאי עסקינן אילימא באשת ישראל אי ברצון כלום יש לה כתובה ואי באונס מי קא מיתסרא על גברא ואלא באשת כהן אי ברצון כלום יש לה כתובה מי גרעה מאשת ישראל ברצון אלא לאו באונס וקתני יש לה כתובה","איבעיא להו אמרה לבעלה גרשתני מהו אמר רב המנונא ת\"ש האומרת טמאה אני לך דאפילו למשנה אחרונה דקתני לא מהימנא התם הוא דמשקרה דידעה דבעלה לא ידע בה אבל גבי גרשתני דידע בה מהימנא דחזקה אין אשה מעיזה פניה בפני בעלה","אמר ליה רבא אדרבה אפי' למשנה ראשונה דקתני מהימנא התם משום דלא עבידא לבזויי נפשה אבל הכא דזמנין דתקיף לה מן גברא מעיזה ומעיזה","מתיב רב משרשיא השמים ביני לבינך דמשנה ראשונה תיובתא דרבא הכא דלית לה כיסופא וקתני דמהימנא קסבר רבא התם כיון דלא סגי לה דלא אמרה אין יורה כחץ אי לא איתא כדקאמרה לא אמרה ליה","השמים ביני לבינך דמשנה אחרונה תהוי תיובתא דרב המנונא והא הכא דידעה היא ובעלה ידע בה וקתני דלא מהימנא","קסבר רב המנונא הכא נמי היא גופה אמרה נהי דבביאה ידע ביורה כחץ מי ידע ומשום הכי משקרא","ההיא איתתא דכל יומא דתשמיש מיקדמה משיא ידיה לגברא יומא חד אתיא ליה מיא לממשא אמר לה הדא מילתא לא הות האידנא אמרה ליה א\"כ חד מן נכרים"],[[2,"גרשתני","מי מהימנא ואם אשת כהן אסור לו להחזירה:"],[2,"התם הוא","דמעיקרא משום דידע לה דבעלה לא ידע בה אי נטמאת חי לא [אהכי] אי אמרה טמאה אני לך לא מהימנא אבל היכא דאמרה גרשתני דידעה דבעלה ידע אי משקרא אי לא לא הות אמרה הכי דחזקה דאין אשה מעיזה פניה בפני בעלה:"],[3,"אדרבה","לא מיבעינן למשנה אחרונה דלא מהימנא אלא אפי' למשנה ראשונה דקתני מהימנא לא הוי טעמא אלא משום דלא עבידא לבזויי נפשה דלימרה דנטמאה אי לאו דהכי הוא כדקאמרה:"],[3,"דזימנין דתקיף לה מן גברא","שציער לה בעלה ומעיזה פניה בפניו. ענין אחר דתקיף לה מן גברא שתוקף יצרה מן אדם אחר שנתנה בו עיניה ובשבילו מעיזה לומר לבעלה גרשתני:"],[4,"והא הכא דלית לה כיסופא","דבהא מילתא לא מבזיא נפשה ואפילו הכי קתני במשנה ראשונה דמהימנא והיכי אמר אפילו למשנה ראשונה כו':"],[4,"התם","נמי אית לה כיסופא דכיון דלא סגי לה דלא קאמרה גבי בי דינא אי יורה כחץ אי לאו דהכי הוא לא קאמרה ואהכי מהימנא:"],[5,"דהא הכא דידעה היא","דבעלה ידע דיורה כחץ וקתני לה לא מהימנא אלמא אשה מעיזה:"],[7,"דכל יומא","לאחר תשמיש מקדמה ומשיא ידא לגברא כדי לטהר ידיו לאחר תשמיש ואתת יומא חד ועבדא הכי אמר לה הדא מילתא דתשמיש לא הוי האידנא:"]],[[2,"גרשתני מהו","מי אמרינן דמהימנא או דלמא עיניה נתנה באחר:"],[2,"","אבל היכא דידע בה מהימנא דאין אשה מעיזה פניה לומר דבר שקר מבעלה בפניו ומהכא שמעינן בכל דוכתא לרב המנונא דסבר באשה שאמרה לבעלה גרשתני נאמנת:"],[3,"דלא עבידא לבזויי נפשה","פירוש לומר שהיא טמאה וזונה:"],[4,"תיובתא [דרבא]","דאמר לא מהימנא דהא הכא לית לה כיסופא שאין כאן הודאת [עבירה] וקתני דמהימנא:"],[4,"קסבר התם כיון דלא סגי דלא אמרה","כלומר אחרי שהיא רוצה לומר דבר זה וגנות גדול כזה:"],[6,"קסבר רב המנונא נהי דבביאה ידע","כלומר נהי דיודע שפולט הזרע ביורה כחץ מי ידע ולכך מעיזה אבל לומר גרשתני דבעלה ידע אי משקרא מהימנא פסק ריצב\"א דהלכה כרב המנונא דבכמה מקומות בהש\"ס מביא דבריו ובסוף גיטין (דף פט:) נמי אמר רב [הונא] אשה שפשטה ידה וקיבלה קידושין מאחר מקודשת מדרב המנונא ואידך כי אתמר דרב המנונא בפניו משמע שפשוט לכל דברי רב המנונא ומהימנא - ויש ללמוד על אשה שטוענת שבעלה אינו יכול להתקשות או שאינו בקי בדרך ארץ דנאמנת דבדבר שיש לו לבעל לידע אינה מעיזה פניה ויוציא ויתן כתובה ולא מיבעיא אי באה מחמת הטענה כגון דאמרה בעינא חוטרא לידא ומרא לקבורה אלא אפילו בלא טענה נמי יכולה היא לומר אינו מקיים מצות עונה וגדולה מזאת אמרו האומר אי אפשי אלא הוא בבגדו והיא בבגדה יוציא ויתן כתובה וכ\"ש בזה ודווקא כשהוא מגרשה ואינה תובעת כתובתה אבל אם צועקת כשרוצה לגרשה שיתן לה כתובה אינה נאמנת דיש לחוש שמא נתנה עיניה (באחר) בכתובה דהכי נמי מפרש בההיא דרב המנונא דאי אמרה גרשתני ותנו לי כתובה אינה נאמנת אף לינשא כדאמר בההיא דהאשה שאמרה מת בעלי ותנו לי כתובה אינה נאמנת לינשא וצריכה להביא ראיה לדבריה ואם טוענת האשה שאין זרעו יורה כחץ אינה נאמנת כמו למשנה אחרונה - כללא דמילתא כל מילי דיכול בעל לידע ומכחישתו נאמנת אבל במילי שאין בעל יכול לידע אינה נאמנת והילכך כשטוענת שאינו יכול להתקשות יוציא ויתן כתובה ואומר ריצב\"א דלא תטול רק מנה מאתים אבל תוספת אין לה כדאמר פרק אע\"פ מן הנשואין גובה את הכל מן האירוסין אינו גובה אלא מנה מאתים שלא כתב אלא ע\"מ לכונסה ובגמרא פסק הלכה למעשה כר\"א ואיבעיא לן נכנסה לחופה ולא נבעלה מהו חיבת חופה קונה או חיבת ביאה קונה ועלתה בתיקו פר\"י דכל תיקו דממונא המוציא מחבירו עליו הראיה ודלא כרב אלפס דפסק כל תיקו דממונא יחלוקו ולכך אף כאן כיון דליכא חיבת ביאה אין לה תוספת דאף דקי\"ל כי העראה חשובה כגמר ביאה לענין חיוב עריות הכא לענין חיבה לקנות תוספת אינה ביאה וכן מי שאינו בריא להתקשות אפילו למ\"ד משמש מת בעריות חייב מ\"מ אין כאן חיבת ביאה וגם מה שהכניסה בנדוניא לא תטול רק בצמצום מה שהביאה אלא מה שרגילין לכתוב נדוניא דהנעלת ליה דכותבין יותר ממה שהכניסה לו דגם זה מן התוספת יש לה ולא תטול כך פסק ריצב\"א בתשובות סתם דבריו:"]]],[["אהלויי דהוו הכא האידנא אי אנת לא דילמא מנהון אמר רב נחמן עיניה נתנה באחר ולית בה מששא במלה","ההיא איתתא דלא הוה בדיחא דעתה בהדי גברא אמר לה האידנא מאי שנא אמרה ליה מעולם לא צערתן בדרך ארץ כי האידנא אמר לה לא הוה הדא מילתא האידנא אמרה ליה א\"כ הלין נכרים נפטויי דהוו הכא האידנא אי אנת לא דילמא חד מנהון אמר להו רב נחמן לא תשגיחון בה נותנת עיניה באחר הואי","ההוא גברא דהוה מהרזיק בביתא הוא ואינתתא על אתא מריה דביתא פרטיה נואף להוצא וערק אמר רבא איתתא שריא אם איתא דעבד איסורא ארכוסי הוה מירכס","ההוא נואף דעל לגבי דההיא אנתתא אתא גברא סליק נואף איתיב [בכלאי] בבא הוה מחתן תחלי תמן וטעמינון חויא בעא מרי דביתא למיכל מן הנהו תחלי בלא דעתא דאינתתא אמר ליה ההוא נואף לא תיכול מנהון דטעמינון חויא","אמר רבא אינתתיה שריא אם איתיה דעבד איסורא ניחא ליה דליכול ולימות דכתיב (יחזקאל כג, לז) כי נאפו ודם בידיהן","פשיטא מהו דתימא איסורא עבד והאי דאמר ליה דניחא ליה דלא לימות בעל דתהוי אינתתיה עלויה (משלי ט, יז) מים גנובים ימתקו ולחם סתרים ינעם קא משמע לן","\u0001הדרן עלך ואלו נדרים וסליקא לה מסכת נדרים\u0002"],[[0,"אהלויי","מוכרי אהלות בשמים:"],[1,"נפטויי","מוכרי נפט:"],[2,"דהוה מהרזק בביתא","שהיה סגור עם אשה בבית:"],[2,"פרטיה נואף להוצא","פרץ הגדר:"],[2,"הוה מירכס","בביתה היה מתחבא בבית שלא ירגיש בו הבעל:"],[3,"בלא דעתא דאיתתא","שאילו היתה יודעת לא היתה מניחתו לאכול:"],[4,"כי נאפו ודם בידיהן","דנואפים הורגין הבעלים:"],[5,"מהו דתימא איסורא עבד","האי בהדה והאי דאמר ליה הכי משום דלא לימות דתיהוי איתתיה עלויה כי מים גנובים ימתקו קמשמע לן דלא אמרינן הכי ושריא:"]],[[0,"אהלויי","מוכרין אהל:"],[0,"שמא עיניה נתנה באחר","ומיירי באשת כהן דאי לאו עיניה נתנה באחר אף בביאת אונס בחיוב שסבורה שהוא בעלה [אסורה]:"],[1,"נפטויי","מוכרי נפט והבעל היה כהן כדפרישית:"],[2,"דהוה מהרזק","נהגו ביחוד וחבירו בהחובל (דף פה:) דהרזקיה לאינדרונא:"],[2,"פרטיה נואף להוצא וערק","כלומר פרץ המחיצה ויצא כך כתוב בספרים - ובערוך פירש דהוי נואף הבעל וערק הבעל:"],[2,"איתתא שריא דאם איתא דעבד איסורא אירכוסי הוי מירכס","פירוש היה נטמן מפני הבעל פירשתי ביבמות:"],[3,"בבא דכפא","בכניסת הפתח:"],[5,"פשיטא","(דהתם) שאף חשוד על שפיכת דמים:"],[5,"מים גנובים ימתקו","כדאמר בסנהדרין ניטל טעם ביאה וניתן לעוברי עבירה קמ\"ל דנואף אינו יודע זה וניחא ליה דלימות בעל כדי שישאנה בפרהסיא:"]]]]};
